\paragraph{Interleaving Distance.}

Let \(F_\bullet\) and \(G_\bullet\) be two persistent objects in \(\caC\). A \emph{natural transformation} \(\varphi: F_\bullet \Rightarrow G_\bullet\) (also called a homomorphism) consists of morphisms \(\{\varphi_t: F_t \to G_t\}_{t \in \mathbb{R}}\) satisfying the following commutative diagrams for all $t \leq s$:
\[
\begin{tikzcd}
F_t \ar[r, "f_{t,s}"] \ar[d, "\varphi_t"'] & F_s \ar[d, "\varphi_s"] \\
G_t \ar[r, "g_{t,s}"] & G_s
\end{tikzcd}
\]
If each \(\varphi_t\) is an isomorphism, we say the two persistent objects are \emph{naturally isomorphic}, denoted \(F_\bullet \cong G_\bullet\).

For any $\delta\geq 0$, a \emph{\(\delta\)-interleaving} between two persistent objects \(F_\bullet\) and \(G_\bullet\) consists of two families of morphisms:
\[
\{\varphi_t: F_t \to G_{t+\delta}\}_{t\in \mathbb{R}}, \quad \{\phi_t: G_t \to F_{t+\delta}\}_{t\in \mathbb{R}},
\]
such that the following diagrams commute for all $t\leq s$:
	\begin{center}
		\begin{tikzcd}[column sep={6em,between origins}]
			F_t \ar[dr, "\varphi_t" below left] 	
			\ar[r,"f_{t,s}"]
			& 
			F_s			
			\ar[dr,"\varphi_s " ]&
			\\
			& G_{t+\delta}
			\ar[r,"g_{t+\delta,s+\delta}" below]
			& 
			 G_{s+\delta}
		\end{tikzcd}
\hspace{0.6cm}
	\begin{tikzcd}[column sep={6em,between origins}]
			&  F_{t+\delta}
			\ar[r,"f_{t+\delta,s+\delta}"]
			& 
			 F_{s+\delta}
			\\
			G_t
			\ar[ur, "\phi_t"] 
			\ar[r,"G_{t,s}" below]
			& 
			 G_{s}
			\ar[ur,"\phi_s" below right]&
		\end{tikzcd}
	\end{center} 
and
\begin{center}
		\begin{tikzcd}
			F_t
			\ar[dr, "\varphi_t" below left ] 
			\ar[rr,"f_{t,t+2\delta}"]%
			&& 
			 F_{t+2\delta}		
			\\
			&  G_{t+\delta}
			\ar[ur,"\phi_{t+\delta}" below right ]
			& 
		\end{tikzcd}
\hspace{0.6cm}
		\begin{tikzcd}
			&  F_{t+\delta}
			\ar[dr,"\varphi_{t+\delta}"]
			& 
			\\
			G_t
			\ar[ur, "\phi_t"] 
			\ar[rr,"G_{t,t+2\delta}" below]
			&& 
			 G_{t+2\delta}.	
		\end{tikzcd}
	\end{center}

\begin{definition} \label{def:interleaving}
    The \textbf{interleaving distance} between \(F_\bullet\) and \(G_\bullet\) is defined as:
    \[
    \di(F_\bullet, G_\bullet) := \inf\{ \delta \geq 0 \mid F_\bullet \text{ and } G_\bullet \text{ are } \delta\text{-interleaved} \},
    \]
    with the convention \(\inf \emptyset = \infty\). 
    When needed, we write \(\di^{\caC}\) to emphasize the underlying category.
\end{definition}

The interleaving distance is non-increasing under post-composition with functors, a property that will be used in the stability results we will discuss later:

\begin{theorem}[{\cite[Section 2.3]{bubenik2015metrics}}]
\label{thm:Bubenik}
For functors $ F_\bullet, G_\bullet:(\bbR,\leq)\to\caC$ and $\rmH:\caC\to \caD$,  
\[ d_{\invariant}^{\caD}(\rmH \circ F_\bullet,\rmH \circ G_\bullet)\leq d_{\invariant}^{\caC}( F_\bullet,G_\bullet).\]
\end{theorem}

\paragraph*{Vietoris–Rips filtration.}

Let \((X, d_X)\) be a metric space and let \(t > 0\). The \emph{Vietoris–Rips complex} \(\VR_t(X)\) is the simplicial complex with vertex set \(X\), in which a finite subset \(\sigma \subset X\) spans a simplex if and only if \(\diam(\sigma) < t\). When there is no risk of ambiguity, we will use the same notation to refer to both a simplicial complex and its geometric realization.

The family \(\{\VR_t(X)\}_{t > 0}\), equipped with the natural simplicial inclusions \(\VR_t(X) \hookrightarrow \VR_s(X)\) for \(t \leq s\), defines a persistent space %—specifically, a filtration of topological spaces—
denoted by \(\VR_\bullet(X)\). We refer to this as the \emph{Vietoris–Rips filtration} of \(X\). Throughout this paper, we adopt the open condition \(\diam(\sigma) < t\); however, all results remain valid under the closed condition \(\diam(\sigma) \leq t\) as well.

Applying the \(k\)-th homology with field coefficients to the filtration \(\VR_\bullet(X)\) yields a persistence module, denoted \(\rmH_k(\VR_\bullet(X))\) and called the \emph{\(k\)-th persistent homology} of \(X\).

\paragraph*{Gromov–Hausdorff distance.}

Let \(X, Y\) be subsets of a metric space \(Z\). The \emph{Hausdorff distance} between \(X\) and \(Y\) in \(Z\) is given by
\[
d_\mathrm{H}^Z(X, Y) := \inf\left\{ r > 0 \mid X \subseteq B(Y, r) \text{ and } Y \subseteq B(X, r) \right\},
\]
where \(B(A, r)\) denotes the open \(r\)-neighborhood of \(A\) in \(Z\).

\begin{definition}
The \textbf{Gromov–Hausdorff distance} between compact metric spaces \((X, d_X)\) and \((Y, d_Y)\) is defined by
\[
\dgh(X, Y) := \inf_{Z, \psi_X, \psi_Y} d_\mathrm{H}^Z(\psi_X(X), \psi_Y(Y)),
\]
where the infimum is taken over all metric spaces \(Z\) and isometric embeddings \(\psi_X: X \to Z\) and \(\psi_Y: Y \to Z\).
\end{definition}

For further background on the Gromov-Hausdorff distance, see \cite{edwards1975structure,gromov2007metric}.

\paragraph*{Homotopy interleaving distance.}

Blumberg and Lesnick observed in \cite{blumberg2017universality} that the interleaving distance between persistent spaces is not homotopy invariant. Motivated by this, they introduced a refined notion based on homotopy classes of persistent spaces.

%\begin{definition}
Let \( X_\bullet ,  Y_\bullet : (\mathbb{R}, \leq) \to \topo\) be persistent spaces. A natural transformation \(\varphi:  X_\bullet  \Rightarrow  Y_\bullet \) is called an \emph{objectwise weak equivalence} if each component \(\varphi_t: X_t \to Y_t\) is a weak homotopy equivalence (i.e., it induces isomorphisms on all homotopy groups).
We say that \( X_\bullet \) and \( Y_\bullet \) are \emph{weakly equivalent}, denoted \( X_\bullet  \simeq  Y_\bullet \), if there exists a third persistent space \(W_\bullet\) and weak equivalences \(W_\bullet \to  X_\bullet \) and \(W_\bullet \to  Y_\bullet \).
%\end{definition}

For \(\delta \geq 0\), two persistent spaces \( X_\bullet \) and \( Y_\bullet \) are said to be \emph{\(\delta\)-homotopy-interleaved} if there exist weakly equivalent persistent spaces \( X_\bullet ' \simeq  X_\bullet \) and \( Y_\bullet ' \simeq  Y_\bullet \) such that \( X_\bullet '\) and \( Y_\bullet '\) are \(\delta\)-interleaved (as persistent objects in \(\topo\)).

\begin{definition}[\cite{blumberg2017universality}]
The \textbf{homotopy interleaving distance} $\dhi$ between persistent spaces \( X_\bullet \) and \( Y_\bullet \) is defined as the infimum $\delta\geq 0$ such that 
$X_\bullet  \text{ and }  Y_\bullet  \text{ are } \delta\text{-homotopy-interleaved}$.
Equivalently,
\[
\dhi( X_\bullet ,  Y_\bullet ) = \inf\left\{ \di^\topo( X_\bullet ',  Y_\bullet ') \mid  X_\bullet ' \simeq  X_\bullet , \,  Y_\bullet ' \simeq  Y_\bullet  \right\}.
\]
\end{definition}

Furthermore, they showed that the homotopy interleaving distance satisfies the following stability result.

\begin{theorem}[\cite{blumberg2017universality}]
\label{thm:stability-HI}
Let \(X\) and \(Y\) be totally bounded metric spaces. Then, for any \(k \in \mathbb{Z}_{\geq 0}\),
\[
\di\left( \rmH_k(\VR_\bullet(X)), \rmH_k(\VR_\bullet(Y)) \right) \leq \dhi\left( \VR_\bullet(X), \VR_\bullet(Y) \right) \leq 2 \cdot \dgh(X, Y).
\]
\end{theorem}


\subsection{Topological Invariants}
\label{subsec:topologicla invariants}

We review several topological invariants from the literature that will be used in this work, including the LS-category, sectional category, and their cohomological lower bounds. Each of these invariants is defined for both topological spaces and continuous maps.

\subsubsection{Lyusternik--Schnirelmann Category}

The notion of LS-category of a space was introduced by Lyusternik and Schnirelmann as a topological invariant to establish lower bounds on the number of critical points of smooth functions on a manifold \cite{lusternik1934methodes}. We begin by reviewing the definition and fundamental properties of LS-category following \cite{cornea2003lusternik}.

Beyond spaces, the LS-category can also be defined for continuous maps. This extension was first introduced by Fox \cite{fox1941lusternik} and further developed by Berstein and Ganea \cite{berstein1962category}. We recall the definitions of LS-category for both spaces and maps below.

\begin{definition}[%LS-category, 
{\cite[Definition 1.1]{cornea2003lusternik}}] \label{def:cat(X)}
    The \textbf{Lyusternik-Schnirelmann category (LS-category)} of $X$, denoted by $\cat(X)$, is the  least number $n$ (or $+\infty$) of open sets $U_1,\dots, U_{n+1}$ in $ X$ that cover $ X$ such that each inclusion $U_i\hookrightarrow  X$ is null-homotopic (i.e. $U_i$ is contractible to a point in $ X$).
\end{definition}

Let \( X \) and \( Y \) be topological spaces with basepoints \( x_0 \in X \) and \( y_0 \in Y \). The \emph{wedge sum} $X\vee_{x_0\sim y_0} Y$ (or simply $X\vee Y$) is the quotient of the disjoint union \( X \amalg Y \) obtained by identifying the basepoints: 
 ${\displaystyle X\vee Y=(X\amalg Y)\;/{x_0 \sim y_0}}$. 

\begin{proposition}\label{prop:properties of cat}
Let $X$ and $Y$ be two based topological spaces. Then:
    \begin{enumerate}[label=(\alph*)]
        \item $\cat(X \times Y) \leq \cat(X) + \cat(Y)$.
        \item \label{prop-item:cat wedge} $\cat(X\vee Y) = \max\{\cat(X), \cat(Y)\}$. 
        %\item $\cat(\bbS^d)=1$;
        \item $\cat\left((\bbS^d)^{\times n}\right) = n$ for any $d\geq 0$ and $n\geq 1$.
    \end{enumerate}
\end{proposition}

\begin{definition}[{\cite[Definition 1.1]{berstein1962category}}]
\label{def:cat(f)}
The \textbf{LS-category of a map $f: X\to  Y$}, denoted by $\cat(f)$, is the least number $n$ (or $+\infty$) such that $ X$ can be covered by open sets $U_1,\dots, U_{n+1}$ such that each $f\vert_{U_i}$ is null-homotopic (i.e. $f\vert_{U_i}$ is homotopic to a constant map from $U_i$ to $X$).
\end{definition}

Shortly after the introduction of the LS-category, Froloff and Elsholz \cite{FroloffElsholz1935} proposed an alternative method for estimating the number of critical values of a function on a manifold. 
Their approach relied on the minimal number of cycles having a non-trivial intersection product, which nowadays is known to be equal to the cup-length.  
Below, we review the cohomology ring, the concept of cup-length, and its connection to the LS-category.

From \cite[Section 3.2]{hatcher2002algebraic}, we recall that cohomology with coefficients in a ring is naturally endowed with a graded ring structure via the cup product operation.
The \emph{cup product} operation is defined at the cochain level using the Alexander–Whitney map, and induces a product on cohomology:
\[\smile: \rmH^*(X) \otimes \rmH^*(X) \to \rmH^*(X),\]
sending $\alpha \in \rmH^p(X)$ and $\beta \in \rmH^q(X)$ to $\alpha \smile \beta \in \rmH^{p+q}(X)$; see  page \pageref{para:cup product} for an interpretation via the diagonal map.
In this work, we consider cohomology over field coefficients, in which case the cohomology becomes a graded algebra over the coefficient field. 
For simplicity, we will often omit the coefficients and write the cohomology of a topological space $X$ as $\rmH^*(X)$.

\begin{definition}
    The \textbf{nilpotency (or index)} of an ideal $I$, denoted by $\nil (I)$, of a ring $R$ is the smallest integer $n$ (or $\infty$) such that $I^{n+1} = 0$. 
\end{definition}

\begin{definition}[{\cite[Definition 1.4]{cornea2003lusternik}}]
    The \textbf{cup-length} of \( X \), denoted by \( \cl(X) \), is defined as the nilpotency of the ideal generated by positive-degree elements in \( \rmH^*(X) \).
\end{definition}

\begin{proposition}[{\cite[Proposition 1.5]{cornea2003lusternik}}]
\label{prop:cl<=cat}
    $\cl(X) \leq \cat(X)$.
\end{proposition}

\subsubsection{Sectional Category}

In \cite{schwarz1961genus}, Schwarz introduced a variant of LS-category, referred to as the genus of a fibration. 
Following the terminology of \cite{james1978category}, this notion is also known as the sectional category of a fibration. 
We provide a review of this concept following \cite[Section 9.3]{cornea2003lusternik}.

\begin{definition}
% A \textbf{fiber bundle} is a short exact sequence
% \[F\to E\xrightarrow{p}B\]
% such that all the subspaces $p^{-1}(b)\subset E$, called \emph{fibers} are homeomorphic. 

A map $p:E\to B$ has the \textbf{homotopy lifting property} with respect to a space $X$ if given a homotopy $g_\bullet:X\times [0,1]\to B$ and a map $\tilde{g}_0:X\to E$ lifting $g_0$, 
% i.e. the following diagram commutes:
% \begin{center}
% \begin{tikzcd}
% & 
% E
% \ar[d, "p" right]
% \\
% X
% \ar[r, "g_0" below, "\simeq" above]
% \ar[ur,"\tilde{g}_0" above]
% & 
% B,
% \end{tikzcd}
% \end{center}
there exists a homotopy $\tilde{g}_\bullet:X\times [0,1]\to E$ lifting $g_t$, i.e. the following diagram commutes:
\begin{center}
\begin{tikzcd}
& 
E
\ar[d, "p" right]
\\
X\times [0,1]
\ar[r, "g_\bullet" below, "\simeq" above]
\ar[ur,"\tilde{g}_\bullet" above, dotted]
& 
B,
\end{tikzcd}
\end{center}

A \textbf{fibration} is a map $p:E\to B$ satisfying the homotpy lifting property for all spaces $X$. 
%For example, the projection $B\times F\to B$ is a fibration where for $\tilde{g_0}(x)=(g_0(x),h(x))$ we can choose lifts of the form $\tilde{g_t}(x)=(g_t(x),h(x))$.
\end{definition}

\begin{definition}[Sectional category]
    Given a fibration $p:E\to B$, the \textbf{sectional category of $p$}, denoted by $\secat(p)$, is the least number $n$ (or $+\inf$) such that $B$ can be covered by $n+1$ open subsets $U_1,\dots, U_{n+1}$ that each admits a section $s_i:U_i\to E$ satisfying \( p \circ s_i = \id_{U_i} \), i.e.
    \begin{center}
    \begin{tikzcd}
    & 
    E
    \ar[d, "p" right]
    \\
    U_i
    \ar[r, hook]
    \ar[ur,"s_i" above, dotted]
    & 
    B,
    \end{tikzcd}
    \end{center}
\end{definition}

\begin{remark}\label{rmk:cat as secat}
    Let $\rmP_0(X)$ be the set of all paths in a based space \(X\) starting from the base point, and let $p_0:\rmP_0(X)\to X$ be the map sending each based path $\gamma$ to $\gamma(1)$. 
    Then 
    \[\cat(X) = \secat(p_0:\rmP_0(X)\to X).\] 
    This is because an open subset $U\subset X$ admits a section $s:U \to \rmP_0(X)$ if and only if the inclusion $U\hookrightarrow X$ is null-homotopic.
\end{remark}

\begin{proposition}[{\cite[Proposition 9.4]{cornea2003lusternik}}] 
\label{prop:coho lower bound secat}
Let $p:E\to B$ be a fibration. Then:
\begin{itemize}
    \item $\secat(p) \leq \cat(B)$. If $E$ is contractible, then $\secat(p) = \cat(B)$.
    \item $\nil (\kernel (p^*)) \leq \secat (p)$, where $p^*$ is the induced morphism on cohomology. 
\end{itemize}
\end{proposition}

