\subsection{Persistent Invariants}
\label{subset:persistent invariants}

Persistent invariants, broadly interpreted, capture the evolution of topological invariants across scale. The classical \emph{rank invariant} of persistent (co)homology vector spaces serves as a prominent example \cite{carlsson2007theory}. There has been ongoing work on developing general frameworks for studying more flexible types of persistent invariants, as seen in works such as \cite{puuska2017erosion, bergomi2019rank, giunti2021amplitudes, memoli2024PersistentCup}.
We review the formalism from \cite{memoli2024PersistentCup} for characterizing persistent invariants that exhibit desirable properties, such as stability.

For any category $\caC$, let $\mor(\caC)$ and $\ob(\caC)$ denote the collection of all morphisms and objects of $\caC$, respectively.

\begin{definition}[{\cite[Definition 2.5]{memoli2024PersistentCup}}]
\label{def:categorical invariant}
A \textbf{categorical invariant} of a category $\caC$ is a map $\invariant :\ob(\caC)\sqcup\mor(\caC)\to\bbN\cup\{\infty\}$ such that 
\begin{itemize}
    \item [(i)] $\invariant (\id _X)=\invariant (X)$,~for all $X\in \ob(\caC)$, and
    \item [(ii)] for any maps $X\xrightarrow{f} Y\xrightarrow{g}Z\xrightarrow{h} W$ in $\caC$, 
	we have \(\invariant(h\circ g\circ f)\leq \invariant(g).\)
\end{itemize}
Alternatively, condition (ii) can be replaced with the equivalent condition
\begin{itemize}
    \item [(ii')] for any maps $X\xrightarrow{f} Y\xrightarrow{g}Z$ in $\caC$, 
	we have $\invariant(g\circ f)\leq \min\{\invariant(f), \invariant(g)\}$.
\end{itemize}
\end{definition}

% \begin{definition}\label{def:p_invariant}
% Let $\invariant $ be a categorical invariant of a category $\caC$. 
% For any persistent object $X_\bullet:(\bbR,\leq)\to\caC$, we associate the functor 
% \begin{align*}
%     \invariant (X_\bullet):(\Int,\subseteq)&\to(\bbN,\leq)^{\mathrm{op}}\\
%     [a,b]&\mapsto \invariant \left(f_a^b\right).
% \end{align*}

% We call $\invariant (X_\bullet)$ the \textbf{persistence $\invariant $-invariant associated to $X_\bullet$}.
% \end{definition}


Given any functor $X_\bullet : (\bbR,\leq)\to\caC$, there is an induced functor $\invariant(X_\bullet)$ from the poset category $\Int$ of intervals to the poset category of natural numbers, given by  
\[
\invariant(X_\bullet)([a,b]) := \invariant(X_a \to X_b).
\] 
%This induced functor is called the \textbf{persistence $\invariant$-invariant associated to $X_\bullet$}. 
We refer to the induced functor as the \textbf{persistence $\invariant$-invariant associated to $X_\bullet$}, or more briefly and generically  as a \textbf{persistent invariant}.


We now recall a notion of distance for comparing persistent invariants.


\begin{definition}[{\cite[Definition 5.3]{patel2018generalized}}]
\label{def:de}
    Let \( \invariant_1, \invariant_2: (\Int, \subseteq) \to (\mathbb{R}_{\geq 0}, \leq) \) be two functors, and let \( \epsilon \geq 0 \). We say that \( \invariant_1 \) and \( \invariant_2 \) are \textbf{\(\epsilon\)-eroded} if, 
    for all \( [a,b] \in \Int \),
    \[
    \invariant_1([a,b]) \geq \invariant_2([a - \epsilon, b + \epsilon]) \quad \text{and} \quad
    \invariant_2([a,b]) \geq \invariant_1([a - \epsilon, b + \epsilon]).
    \]

    The \textbf{erosion distance} between \( \invariant_1 \) and \( \invariant_2 \) is defined as
    \[
    d_{\mathrm{E}}(\invariant_1, \invariant_2) := \inf \left\{ \epsilon \geq 0 \,\middle|\, \invariant_1,\invariant_2 \text{ are }\epsilon\text{-erosed}
    %\invariant_1([a,b]) \geq \invariant_2([a-\epsilon, b+\epsilon]),
    %\invariant_2([a,b]) \geq \invariant_1([a-\epsilon, b+\epsilon]), \forall [a,b] \in \Int
    \right\},
    \]
    with the convention that \( d_{\mathrm{E}}(\invariant_1, \invariant_2) = \infty \) if no such \( \epsilon \) exists.
\end{definition}

\begin{theorem}[{\cite[Theorem 1]{memoli2024PersistentCup}}]
    \label{thm:stab-per-inv}
Let $\invariant :\ob(\caC)\sqcup\mor(\caC)\to\bbN$ be a categorical invariant.
The persistence $\invariant $-invariant is $1$-Lipschitz stable: for any $X_\bullet ,Y_\bullet :(\bbR,\leq)\to\caC$,
$$d_{\mathrm{E}}(\invariant (X_\bullet ),\invariant (Y_\bullet ))\leq d_{\mathrm \invariant}(X_\bullet ,Y_\bullet ).$$
\end{theorem}

\begin{theorem}[{\cite[Theorem 2]{memoli2024PersistentCup}}]
    \label{thm:main-stability} 
    Let $\invariant $ be a categorical invariant of topological spaces such that $\invariant$ is invariant under post- or pre-composition with weak homotopy equivalences.
    %satisfying the condition that for any maps $ X\xrightarrow{f}Y\xrightarrow{g}Z\xrightarrow{h}W$ where $g$ is a weak homotopy equivalence, $\invariant (g\circ f)=\invariant (f)$ and $\invariant (h\circ g)=\invariant (h)$. 
    Then, for two persistent spaces $X_\bullet$ and $Y_\bullet$, we have
    \begin{equation}\label{eq:dE-dHI}
        d_{\mathrm{E}}(\invariant (X_\bullet),\invariant (Y_\bullet))\leq d_{\mathrm{HI}}(X_\bullet,Y_\bullet).
    \end{equation}
    For the Vietoris-Rips filtrations $\VR_\bullet(X)$ and $\VR_\bullet(Y)$ of compact metric spaces $X$ and $Y$, we have
    \begin{equation}\label{eq:dE-dGH}
    d_{\mathrm{E}}\left(\invariant \left(\VR_\bullet (X)\right),\invariant \left(\VR_\bullet (Y)\right)\right)\leq 2\cdot d_{\mathrm{GH}}(X,Y). 
    \end{equation}
\end{theorem}

\section{Topological Complexity (TC)}
\label{sec:TC}

The motion planning problem seeks a function assigning a continuous path between any pair of points in a path-connected space $X$. A \emph{continuous} solution exists if and only if $X$ is contractible \cite[Theorem 1]{farber2003topological}. 
To quantify the discontinuity of such motion planners, Farber introduced the topological complexity of topological spaces. 

In this section, we review the topological complexity of spaces \cite{farber2003topological} %pairs \cite{farber2008invitation,short2018relative}, 
and maps \cite{murillo2021topological,scott2022ls,scott2022topological}, along with cohomological lower bounds for topological complexity.  

\subsection{Topological Complexity of Topological Spaces}

Recall that \( \rmP(X) \) is the space of all continuous paths \(\gamma: [0,1] \to X\), and \( p: \rmP(X) \to X \times X \) is the map assigning to each path its pair of endpoints \( (\gamma(0), \gamma(1)) \). 

%We review the definition and important properties of the topological complexity of a topological space from \cite{farber2003topological}.

\begin{definition}[Topological complexity, 
{\cite{farber2003topological}}%{\cite[Definition 2]{farber2003topological}}
]\label{def:TC} 
Let $X$ be a path-connected topological space.
\begin{itemize}
    \item A \textbf{motion planner} on a subset $U\subset X\times X$ is a continuous map $s:U\to \rmP(X)$ such that $p\circ s = \id_U$. 
    \item The \textbf{topological complexity} %\footnote{This differs from Farber's original definition by $-1$.} 
    $\TC(X)$ of $X$ is the least number $n$ (or $+\infty$) such that $X\times X$ can be covered by open subsets $U_1,\dots, U_{n+1}$, such that there exists a motion planner on each $U_i$\footnote{The motion planners need not be compatible with each other.}. 
    In other words, $s_i:U_i\to \rmP(X)$ is a continuous map satisfying $p\circ s_i=\id_{U_i}$. 
\end{itemize}
\end{definition}

Here are some properties of $\TC(X)$.
\begin{proposition}[\cite{farber2003topological,farber2004instabilities,farber2006topology}]
\label{prop:tc of a space}
Let $X$ and $Y$ be path-connected spaces. Then:
\begin{enumerate}[label=(\alph*)]
    \item If $X$ and $Y$ are homotopic, then $\TC(X)=\TC(Y)$.
    \item If $X$ is paracompact\footnote{A topological space is paracompact if every open cover of it has a locally finite open refinement.}, then $\cat(X)\leq \TC(X)\leq \cat(X\times X)$.
    %\item $\TC(X)\geq \zcup(X)$.
    \item $\TC(X\times Y) \leq \TC(X) + \TC(Y).$ %{this is from \cite{farber2003topological}}
    \item \label{prop-item:wedge}
    $\max\{\TC(X), \TC(Y)\} \leq \TC(X\vee Y)\leq \max\{\TC(X), \TC(Y), \cat(X) + \cat(Y)\}.$ %\cite[Thm 19.1]{farber2003topological}
    \item Let $X=(\bbS^d)^{\times n}$ be the product of $n$ copies of $d$-spheres. Then $\TC(X)$ equals $n$ if $d$ is odd, and $2n$ if $d$ is even.
    \item \label{prop-item:bouquets} Let $X=\bigvee^n\bbS^d$ be the bouquet of $n$ copies of $d$-spheres. Then $\TC(X)$ equals $1$ if $n=1$ and $d$ is odd, and $2$ if either $n>1$ or $d$ is even.
    \item $\TC(X) = \secat(p: \rmP(X) \to X \times X)$.
\end{enumerate}
\end{proposition}
% \begin{proof}
% The statements follow from Theorems 3, 5, 7, 11, and 13 of \cite{farber2003topological} and Lemma 10.2 of \cite{farber2004instabilities}, respectively.
% \end{proof}

\begin{remark}\label{rmk:wedge}
    The lower bound in \cref{prop:tc of a space} Item \ref{prop-item:wedge} was improved to $\max\{\TC(X), \TC(Y),\cat(X\times Y)\}$ in \cite[Theorem 3.6]{dranishnikov2014topological} for ANR spaces. A space \(X\) is called an \emph{absolute neighborhood retract} (ANR) if it admits a neighborhood retract in every space it embeds as a closed subset. This includes all CW complexes. 
\end{remark}

%The ANR condition ensures good homotopy extension property: if \(A \subseteq X\) is closed and \(f: A \to Y\) is continuous, then any such map extends to a neighborhood of \(A\) in \(Y\), provided \(X\) is an ANR. 
%This property ensures that homotopy-theoretic constructions, such as cohomology or cup products, behave well on ANRs. In particular, this condition is required for certain cohomological lower bounds on \(\TC(f)\), such as \(\zcup(f) \leq \TC(f)\), to hold~\cite{scott2022ls}.

We include detailed discussions of the following examples, which will serve as key test cases in  \cref{subsec:stability} for comparing the distinguishing power of persistent topological complexity with that of persistent homology.


\begin{example}[Topological complexity of real projective spaces]
\label{ex:tc of rpn}
    For \( n \geq 1 \), let \( \rp^n \) denote the real projective \( n \)-space. The topological complexity of \( \rp^n \) has been studied extensively; see \cite{farber2003topological}. 
    In particular, it follows from \cite[Theorem 4.5]{farber2003topological} and its proof that, for any positive integer \( r \), if \( n \geq 2^{r-1} \), then
    \[
    \TC(\rp^n) \geq \zcup(\rp^n) \geq 2^r - 1.
    \]
    Thus, for $n = 2^{r-1},\, 2^{r-1}+1,\, \dots,\, 2^r - 2$,
    \[
    \TC(\rp^n) \geq \zcup(\rp^n) > n = \cat(\rp^n).
    \]
    Moreover, it is known that \( \TC(\rp^n) = n \) for \( n = 1, 3, 7 \) and \( \TC(\rp^{2}) = 3 \). 
    Explicit values of \( \TC(\rp^n) \) for all \( n \leq 23 \) are provided in \cite{farber2003topological}.
\end{example}

\begin{example}[Topological complexity of bouquets of spheres]
\label{ex:tc of bouquets}
    \cref{prop:tc of a space} Item \ref{prop-item:bouquets} can be extended to wedges of spheres of varying dimensions. Let \( X := \bbS^{d_1} \vee \dots \vee \bbS^{d_n} \) be the bouquet of spheres of dimensions \( d_1, \dots, d_n \). We claim that
    \begin{equation}\label{eq:tc of bounquets}
        \TC(\bbS^{d_1}\vee \dots \vee \bbS^{d_n}) = 
            \begin{cases}
                1, \quad &\mbox{if $n=1$ and $d_1$ is odd;}\\
                2, \quad &\mbox{otherwise}.
            \end{cases}
    \end{equation}
    While this result is likely known to experts, we include a self-contained proof to demonstrate how one can compute topological complexity using other invariants such as LS-category and cup-length, particularly because we will rely on this example later.

    The case \(n = 1\) follows directly from \cref{prop:tc of a space} Item \ref{prop-item:wedge}. 
    Now assume \(n \geq 2\), and proceed by induction. 
    For the base case \(n = 2\), \cref{prop:tc of a space} Item \ref{prop-item:wedge} yields
    \[
    \TC(\bbS^{d_1} \vee \bbS^{d_2}) 
    \leq \max\left\{ \TC(\bbS^{d_1}),\, \TC(\bbS^{d_2}),\, \cat(\bbS^{d_1}) + \cat(\bbS^{d_2}) \right\}
    = \max\{1, 1, 2\} = 2.
    \]
    Meanwhile, \cref{rmk:wedge} implies
    \[
    \TC(\bbS^{d_1} \vee \bbS^{d_2}) 
    \geq \max\left\{ \TC(\bbS^{d_1}),\, \TC(\bbS^{d_2}),\, \cat(\bbS^{d_1} \times \bbS^{d_2}) \right\}
    = \max\{1, 1, 2\} = 2,
    \]
    and hence \(\TC(\bbS^{d_1} \vee \bbS^{d_2}) = 2\).

    Now assume as the induction hypothesis that the claim holds for any bouquet of \(n\) spheres. 
    Let \(X' := X \vee \bbS^{d_{n+1}}\).
    By \cref{prop:properties of cat} Item \ref{prop-item:cat wedge}, we have
    \(
    \cat(X) = \max_{1\leq i\leq n}\{\cat(\bbS^{d_i})\} = 1,
    \)
    and by \cref{prop:cl<=cat}, 
    \(
    \cat(X \times \bbS^{d_{n+1}}) \geq \cl(X \times \bbS^{d_{n+1}}) = 2.
    \)
    Applying \cref{prop:tc of a space} Item \ref{prop-item:wedge} and \cref{rmk:wedge}, we obtain
    \[
    2 = \max\{1, 1, \cat(X \times \bbS^{d_{n+1}})\} 
    \leq \TC(X') 
    \leq \max\{1, 1, \cat(X) + \cat(\bbS^{d_{n+1}})\} = 2,
    \]
    and therefore \(\TC(X') = 2\), completing the induction.
\end{example}


