\subsection{Zero-divisor-cup-length of Topological Spaces}

As illustrated in \cref{ex:tc of bouquets}, computation of topological complexity often relies on auxiliary invariants such as the LS-category and cup-length. Motivated by this, Farber defines the \emph{zero-divisor-cup-length}, a cohomological invariant derived from the lower bound for sectional category (see \cref{prop:coho lower bound secat}), to provide more accessible lower bounds for topological complexity \cite{farber2003topological}.

The cup product operation is closely related to the map induced at cohomology level by the diagonal map $\Delta_X : X\to X\times X$, defined as $\Delta_X(x) = (x,x)$.
Specifically, let $\pi_1,\pi_2:X\times X\to X$ be the projections onto the first and second component.
Given a map $f:X\to Y$, let $f^*:\rmH^*(Y) \to \rmH^*(X)$ denotes the induced map in cohomology. 
The cohomology classes $\alpha\in \rmH^p(X)$ and $\beta\in \rmH^q(X)$ can be pulled back to $X\times X$ as $\pi_1^*(\alpha)$ and $ \pi_2^*(\beta)$, respectively. 
The \emph{cross product} (or \emph{external cup product}) is defined as 
\[
\rmH^*(X) \otimes \rmH^*(X) \xrightarrow{\times} \rmH^*(X\times X) \text{ with }
\alpha \times \beta := \pi_1^*(\alpha) \smile \pi_2^*(\beta).
\] 

The \emph{(internal) `cup product'} operation $\smile:\rmH^*(X) \otimes \rmH^*(X) \xrightarrow{\times} \rmH^*(X\times X) \xrightarrow{\Delta_X^*} \rmH^*(X)$ can also be defined as the composition of $\Delta_X^*$ and the cross product: \label{para:cup product}
\[
\alpha \smile \beta 
:= \Delta_X^*(\alpha\times \beta) 
= \Delta_X^*(\pi_1^*(\alpha) \smile \pi_2^*(\beta)).
\]
We will use the notation $\smile_X$ when we want to specify its dependence on the space $X$. 

Since we work with field coefficients, the Künneth formula (see \cite[Theorem 3.15]{hatcher2002algebraic} or \cite[Section 5.8]{spanier1989algebraic}) ensures that the cross product induces a ring isomorphism.  
Farber defines the zero-divisor-cup-length in two slightly different but equivalent ways, leveraging the isomorphism \( \rmH^*(X) \otimes \rmH^*(X) \cong \rmH^*(X \times X) \): using \( \ker(\smile_X) \) in \cite{farber2003topological} and \( \ker(\Delta_X^*) \) in \cite{farber2008invitation}.  
We will adopt the latter convention.

\begin{definition}[%zero-divisor-cup-length, 
{\cite[Definition 6]{farber2003topological}}]
    The kernel of $\Delta_X^*: \rmH^*(X \times X) \to \rmH^*(X)$ is called the \textbf{ideal of the zero-divisors} of $\rmH^*(X)$ and its elements are called \textbf{zero-divisors}.

    The \textbf{zero-divisor-cup-length}, denoted by $\zcup(X)$, is the nilpotency of $\kernel (\delta_X^*) $, i.e., the length of the longest non-zero product of positive-degree elements in $\kernel(\Delta_X^*)$.
\end{definition}

% \begin{proposition}[\cite{farber2008invitation}]
% \label{prop:zcl of a space}
% Let $X$ and $Y$ be path-connected spaces. Then:
% \begin{enumerate}[label=(\alph*)]
%     \item $\zcup(X\times Y) \geq \zcup(X) + \zcup(Y).$ %{this is from Lemma 4.52}
% \end{enumerate}
% \end{proposition}

\begin{proposition}[{\cite[Theorem 7]{farber2003topological}}]
\label{prop:zcup<=tc}
    $\zcup(X) = \nil \big(\kernel (p^*: \rmH^*(X\times X) \to \rmH^*(P(X)))\big)$. 
    Thus, $\zcup(X) \leq \TC(X)$. 
\end{proposition}

\begin{proof}
    Let $c:X\to \rmP(X)$ be the map of assigning the constant path at $x$ for any point $x\in X$. 
    Then $c$ is a homotopy equivalence, implying that $c^*$ defines an isomorphism $\rmH^*(P(X))\cong \rmH^*(X)$.
    Note that $\Delta_X = p\circ c$.
    Thus, 
    \[\zcup(X) \leq \nil (\kernel (\Delta_X^*)) = \nil (\kernel (p^*)) \leq \secat(p) = \TC(X).\qedhere\]
\end{proof}

\begin{example}[\cite{farber2003topological}]
\label{ex:zcup of Sn}
    This example illustrates the use of \cref{prop:zcup<=tc} to derive lower bounds on topological complexity.

    Let \(\bbS^n\) be the \(n\)-dimensional sphere. Let \(u \in \rmH^n(\bbS^n)\) denote the fundamental class and \(1 \in \rmH^0(\bbS^n)\) the unit. Consider the elements
    \[
    \alpha := 1 \otimes u - u \otimes 1, \qquad \beta := u \otimes u
    \]
    in \(\rmH^*(\bbS^n \times \bbS^n) \cong \rmH^*(\bbS^n) \otimes \rmH^*(\bbS^n)\). Since \(\Delta^*(x \otimes y) = x \smile y\), we have
    \(
    \Delta^*(\alpha) = u - u = 0\) and \(\Delta^*(\beta) = u \smile u = 0.
    \)
    Thus, both \(\alpha\) and \(\beta\) lie in \(\ker (\Delta^*)\). Furthermore,
    \[
    \alpha \smile \alpha = (1 \otimes u - u \otimes 1)^2 = -2(-1)^n \beta =
    \begin{cases}
    0   & \text{if } n \text{ is odd}\\
    -2\beta & \text{if } n \text{ is even}.
    \end{cases}
    \]
    By \cref{prop:zcup<=tc}, we have
    \[
    \TC(\bbS^n) \geq \zcup(\bbS^n) \geq
    \begin{cases}
    1 & \text{if } n \text{ is odd}, \\
    2 & \text{if } n \text{ is even}.
    \end{cases}
    \]
    For a full computation of \(\TC(\bbS^n)\) and verification that equalities in the above formula hold, see \cite{farber2003topological}.
\end{example}

\subsection{Topological Complexity and Zero-divisor-cup-length of Maps}

\label{subset: tc zcup of maps}

Many efforts have been have been made to generalize the concept of topological complexity from spaces to maps. 
In \cite{pavevsic2017complexity}, Pave{\v{s}}i{\'c}, following a suggestion by Dranishnikov, proposed defining the topological complexity of a map $f:X\to Y$ to be the minimal number $n$ such that $X\times Y$ can be covered by open subsets $U_1,\dots,U_{n+1}$, where for each \( i = 1, \dots, n+1 \), there exists a continuous map \( s_i: U_i \to \rmP(X) \) satisfying \( p \circ s_i = \id_{U_i} \). 
Here, \( p: \rmP(X) \to X \times Y \) is the projection defined by \( p(\gamma) = (\gamma(0), f(\gamma(1))) \), where \( \rmP(X) \) denotes the path space of \( X \).
This definition has the drawback of only applying to maps with the path-lifting property. 
To address this, Pave{\v{s}}i{\'c} later refined the definition in \cite{pavesic2018topologist, pavesic2019topological} to extend its applicability to general maps. 
Despite this improvement, the resulting $\TC(f)$ is still not a homotopy invariant.
This issue was recently resolved in works by Murillo and Wu \cite{murillo2021topological} and Scott \cite{scott2022ls, scott2022topological}. 
We review the concept and properties of topological complexity of maps following the latter.

\begin{definition}[Topological complexity of a map, {\cite[Definition 3.1.1]{scott2022ls}}
]\label{def:TC of f} 
Let $f:X\to Y$ be a continuous map between path-connected spaces.
\begin{itemize}
    \item A \textbf{$f$-motion planner} on a subset $U\subset X\times X$ is a continuous map $s^f:U\to \rmP(X)$ such that $p_X\circ s^f = \id_U$. 
    \item The \textbf{(pullback) topological complexity} $\TC(f)$ of $f$ is the least number $n$ (or $+\infty$) such that $X\times X$ can be covered by open subsets $U_1,\dots, U_{n+1}$, such that there exists a $f$-motion planner on each $U_i$. In other words, $s_i^f:U_i\to \rmP(X)$ is a continuous map satisfying $p_X\circ s_i^f=\id_{U_i}$.
\end{itemize}
\end{definition}

\begin{remark}[Relative topological complexity of a pair]
The notion of \textit{relative topological complexity}, introduced in \cite{farber2008invitation} and further developed in \cite{short2018relative}, can be seen as a special case of the topological complexity of a map, where the inclusion \(A \hookrightarrow X \times X\) serves as the map. 
It generalizes classical topological complexity by allowing paths to traverse a larger space \(X\) while their endpoints lie in \(A \subset X \times X\). 
% In this work, we adopt the map-based perspective to present more general results and refer to \cite{farber2008invitation,short2018relative} for details on relative topological complexity.
\end{remark}

In~\cite[Theorem 3.1.11]{scott2022ls}, the author introduces the following notion as a generalization of the classical zero-divisor-cup-length, which provides a cohomological lower bound for the topological complexity of a space, to the setting of continuous maps.

\begin{definition}[Zero-divisor-cup-length of a map, {\cite[Theorem 3.1.11]{scott2022ls}}
]\label{def:zcl of f} 
Let $f:X\to Y$ be a continuous map between path-connected spaces, and $(f\times f)^*:\rmH^*(Y\times Y)\to \rmH^*(X\times X)$ be the ring homomorphism induced by $f\times f$. 
The \textbf{zero-divisor-cup-length} of $f$ is defined to be 
\[\zcup(f) := \nil \left(\kernel(\Delta_X^*)\cap \im ((f\times f)^*)\right) 
= \nil  \Big(\im \big(\kernel\Delta_{Y}^*\xrightarrow{(f\times f)^*} \kernel\Delta_{X}^*\big)\Big)
.\]
\end{definition}

\begin{remark}
To illustrate the definition of $\zcup(f)$, we include the following diagram, which shows how zero-divisors pull back along the map \( f \):
\[
\begin{tikzcd}
    \ker (\Delta_Y^*) 
    \ar[r,hook]
    \ar[d, "(f\times f)^*" left]
    & \rmH^*(Y\times Y)
    \ar[r, "\Delta_Y^*"]
    \ar[d, "(f\times f)^*" left]
    & \rmH^*(Y) 
    \ar[d, "f^*" right] \\
    \ker (\Delta_X^*) 
    \ar[r,hook]
    & \rmH^*(X\times X) 
    \ar[r, "\Delta_X^*"]
    & \rmH^*(X).
\end{tikzcd}
\]
The right-hand square commutes because \(\Delta_Y \circ f = (f \times f) \circ \Delta_X\), which implies
\[
f^* \circ \Delta_Y^* = \Delta_X^* \circ (f \times f)^*,
\quad \text{so} \quad (f \times f)^*(\ker (\Delta_Y^*)) \subseteq \ker (\Delta_X^*).
\]
Thus, \((f \times f)^*\) sends zero-divisors in \(Y\) to classes in zero-divisors in \(X\). To define \(\zcup(f)\), we consider this image and compute the nilpotency of the resulting ideal:
\[
\zcup(f) = \nil\big((f \times f)^*(\ker (\Delta_Y^*))\big).
\]
\end{remark}

Below, we recall some properties of $\TC(f)$.
\begin{proposition}[\cite{scott2022ls}] \label{prop:TC of a map}
Let $f, f_1, f_2:X \to Y$ and $g:Y \to Z$ be continuous maps between path-connected spaces. 
Then:
\begin{enumerate}[label=(\alph*)]
    %\item \label{prop:TCf and relative TC} $\TC(\iota:A\hookrightarrow X) = \TC_X(A\times A)$ for $\iota$ an inclusion of spaces. 
    \item \label{prop:indentity} $\TC(\id_X)=\TC(X)$.
    \item \label{prop:map v.s. space} $\TC(f)\leq \min\{\TC(X),\TC(Y)\}.$ 
    \item \label{prop:cup cat TC} $\cl(f)\leq \cat(f)\leq \TC(f) \leq \cat(f\times f)$.
    \item \label{prop:cohomology estimate} Let $X$ be an ANR. Then $\zcup(f) \leq \TC(f)$.
    \item $\TC(f_1)=\TC(f_2)$, if $f_1$ and $f_2$ are homotopic.
    \item \label{prop:map composition} $\TC(g\circ f)\leq \min\{\TC(g),\TC(f)\}$, for any  maps $f:X\to Y$ and $g:Y\to Z$.
    \item \label{prop:map composition right h.i.} $\TC(f\circ g) = \TC(f)$, if $g$ has a right homotopy inverse.
    \item \label{prop:map composition left h.i.} $\TC(g\circ f) = \TC(f)$, if $g$ has a left homotopy inverse. 
\end{enumerate}
\end{proposition}
