\section{Persistent Topological Complexity and Its Stability}
\label{sec:persistent_TC}
In this section, we lift both topological complexity and its cohomological lower bound, the zero-divisor-cup-length, to persistent invariants and study their properties, including stability.

\subsection{Persistent Topological Complexity and Cohomological Lower Bound}
\label{subsec:def_persistent_TC}

It follows from \cref{prop:TC of a map} Items \ref{prop:indentity} and \ref{prop:map composition}, that the topological complexity of spaces and maps together satisfy the following conditions:
\begin{itemize}
    \item [(i)] $\TC (\id _X)= \TC (X)$, for any $X$ in $\topo$, and
    \item [(ii)] \(\TC(h\circ g\circ f)\leq \TC(g),\) for any maps $X\xrightarrow{f} Y\xrightarrow{g}Z\xrightarrow{h} W$ in $\topo$. 
\end{itemize}
Thus, $\TC :\ob(\topo)\sqcup\mor(\topo)\to\bbN\cup\{\infty\}$ defines a categorical invariant (see \cref{def:categorical invariant}) on topological spaces. 
When applied to persistent spaces, this invariant gives rise to persistent invariants, according to \cref{subset:persistent invariants}.

More precisely, we introduce the following definition.

\begin{definition}[Persistent topological complexity]
\label{def:p_TC}
    Let $X_\bullet$ be a persistent space over $(\bbR, \leq)$.
    The \textbf{persistent topological complexity} of $X_\bullet$ is the functor %$(\Int, \subseteq) \to (\bbN\cup \{+\infty\}, )$ given by 
    \begin{align*}
        \TC (X_\bullet):(\Int, \subseteq)&\to (\bbN\cup \{+\infty\},\, \geq)\\
        [a,b]&\mapsto \TC \Big(f_a^b: X_a\to X_b\Big).
    \end{align*}
\end{definition}

Analogously, we verify below that the zero-divisor-cup-length defines a categorical invariant on the category of topological spaces, so we can also lift it to a persistent invariant.

\begin{lemma} \label{lem:zcup is categorical}
The zero-divisor-cup-length $\zcup :\ob(\topo)\sqcup\mor(\topo)\to\bbN\cup\{\infty\}$ defines a categorical invariant on topological spaces. 
\end{lemma}

\begin{proof}
For any topological space $X$, we have $\zcup(\id_X) = \nil  \big(\kernel\Delta_{X}^*\big) = \zcup(X)$.
Now consider maps $X \xrightarrow{f} Y \xrightarrow{g} Z$ in $\topo$. Since $((g \circ f) \times (g \circ f))^* = (f \times f)^* \circ (g \times g)^*$, we have
\[
\zcup(g \circ f) = \nil\big(\im((f \times f)^* \circ (g \times g)^*) \cap \ker (\Delta_X^*)\big).
\]
This is bounded above by both
\[
\nil\big(\im(f \times f)^* \cap \ker (\Delta_X^*)\big) = \zcup(f) \quad \text{and} \quad \nil\big(\im(g \times g)^* \cap \ker (\Delta_Y^*)\big) = \zcup(g),
\]
since $(f \times f)^*$ and $(g \times g)^*$ are ring homomorphisms and do not increase nilpotency. Hence,
\[
\zcup(g \circ f) \leq \min\{\zcup(f), \zcup(g)\}.
\]

By \cref{def:categorical invariant}, $\zcup$ defines a categorical invariant on topological spaces.
\end{proof}

\begin{definition}[Persistent zero-divisor-cup-length]
\label{def:p_zcup}
    Let $X_\bullet$ be a persistent space over $(\bbR, \leq)$.
    The \textbf{persistent zero-divisor-cup-length} of $X_\bullet$ is the functor %$(\Int, \subseteq) \to (\bbN\cup \{+\infty\}, )$ given by 
    \begin{align*}
        \zcup (X_\bullet):(\Int, \subseteq)&\to (\bbN\cup \{+\infty\},\, \geq)\\
        [a,b]&\mapsto \zcup \Big(\kernel \Delta_{X_a}^*\xrightarrow{(f_a^b\times f_a^b)^*} \kernel\Delta_{X_b}^*\Big) = \nil  \Big(\im \big(\kernel\Delta_{X_a}^*\xrightarrow{(f_a^b\times f_a^b)^*} \kernel\Delta_{X_b}^*\big)\Big).
    \end{align*}
\end{definition}

