\section{Preliminaries}

In this section, we give necessary preliminaries. Recall the discrete Laplacian operator \(\Delta\) acts on a function \( f \) via matrix multiplication:
\begin{equation*}
    \Delta f_i = -\sum_{j=1}^{N} \frac{\partial K_j}{\partial u_i} f_j = \sum_{v_j \sim v_i} B_{ij}(f_j - f_i) - A_i f_i.
\end{equation*}
It is worth noting that in Lemma A1 of Chow-Luo \cite{BennettChow2003}, the weight satisfies $\Phi \in [0,\pi)$; hence, under the obtuse weight condition (i.e., $\Phi \in [0,\pi)$) considered in this paper, the relationship between $B_{ij}$ and $A_i$ with respect to $L$ remains valid. Glickenstein-Thomas \cite{Glickenstein2017} obtained a more fundamental relationship between $B_{ij}$ and $A_i$ through the analysis of the discrete conformal structure using geometric methods. Here, we provide an analytic proof of their conclusion.

\begin{lemma}[\cite{Glickenstein2017}, Proposition 9]
    \label{Lemma:Glickenstein-lemma}
    In $ \mathbb{H}^{2} $, given a triangulated surface $ (M, \mathcal{T}, \Phi) $ with weight $ \Phi \in[0, \pi) $, for any triangle $ \triangle_{i j k} $, we have
    \begin{equation}
        \label{Equation:Glickenstein-lemma}
        \begin{aligned}
            \frac{\partial \theta_{i}^{j k}}{\partial u_{i}} & =-\cosh l_{i j} \frac{\partial \theta_{i}^{j k}}{\partial u_{j}}-\cosh l_{i k} \frac{\partial \theta_{i}^{j k}}{\partial u_{k}} \\
            & =-\cosh l_{i j} \frac{\partial \theta_{j}^{i k}}{\partial u_{i}}-\cosh l_{i k} \frac{\partial \theta_{k}^{i j}}{\partial u_{i}}
            \end{aligned}
    \end{equation}
\end{lemma}


\begin{remark}
    \label{Remark:Glickenstein-lemma}
    In \cite{Xu2018}, Xu obtained the inherent symmetry of the dual structure of circle packings to the equalities (\ref{Equation:Glickenstein-lemma-proof_4}) and (\ref{Equation:Glickenstein-lemma-proof_5}) (see Appendix) ,
    thereby obtaining the following expression
    \begin{equation}
        \label{Equation:Glickenstein-remark_1}
        \frac{\partial \theta_{i}^{jk}}{\partial u_j} = \frac{1}{A_{ijk} \sinh^2 l_{ij}} \left[ C_k S_i^2 S_j^2 \left(1 - \cos^2 \Phi_{ij}\right) + C_i S_i S_j^2 S_k \gamma_{jik} + C_j S_i^2 S_j S_k \gamma_{ijk} \right].
    \end{equation}
    Here, $\gamma_{ijk} = \cos \Phi_{jk} + \cos \Phi_{ij} \cos \Phi_{ik}.$
    Based on the symmetry present in the above expression, we deduce that
    \begin{equation}
        \label{Equation:Glickenstein-remark_2}
        \frac{\partial \theta_{i}^{jk}}{\partial u_j} = \frac{\partial \theta_{j}^{ik}}{\partial u_i}.
    \end{equation}
    This is precisely the symmetry got in the proof of Lemma \ref{Lemma:Glickenstein-lemma}.
\end{remark}

\begin{corollary}
    \label{Corollary:Glickenstein-corollary}
    Based on the area formula for a hyperbolic triangle
    $\operatorname{Area}\left(\triangle_{ijk}\right)=\pi-\theta_{i}^{jk}-\theta_{j}^{ik}-\theta_{k}^{ij},$
    we have
    \begin{equation}\label{deri-area}
            \frac{\partial}{\partial u_{i}} \operatorname{Area}\left(\triangle_{ijk}\right)
            =\frac{\partial \theta_{j}^{ik}}{\partial u_{i}}\left(\cosh l_{ij}-1\right)+\frac{\partial \theta_{k}^{ij}}{\partial u_{i}}\left(\cosh l_{ik}-1\right),
    \end{equation}
 and     \begin{equation}\label{A-equality}
            A_{i}=\sum_{v_j \sim v_i}B_{ij}\left(\cosh l_{ij}-1\right).
    \end{equation}
    \end{corollary}
   \begin{proof}
     The first equality (\ref{deri-area}) is obvious by Lemma \ref{Lemma:Glickenstein-lemma}. Combining (\ref{deri-area}) with the expressions for $B_{ij}$ and $A_{i}$ (\ref{AB-equality}), we obtain
    \begin{equation*}
        \begin{aligned}
            A_{i} &=\sum_{\triangle_{ijk}\in F}\frac{\partial}{\partial u_{i}}\operatorname{Area}\left(\triangle_{ijk}\right)\\[0.5em]
            &=\sum_{\triangle_{ijk}\in F}\left[\frac{\partial \theta_{j}^{ik}}{\partial u_{i}}\left(\cosh l_{ij}-1\right)+\frac{\partial \theta_{k}^{ij}}{\partial u_{i}}\left(\cosh l_{ik}-1\right)\right]\\[0.5em]
            &=\sum_{v_j \sim v_i}\left(\frac{\partial \theta_{j}^{ik}}{\partial u_{i}}+\frac{\partial \theta_{j}^{il}}{\partial u_{i}}\right)\left(\cosh l_{ij}-1\right)\\[0.5em]
            &=\sum_{v_j \sim v_i}B_{ij}\left(\cosh l_{ij}-1\right).
        \end{aligned}
    \end{equation*}
    Here, $\triangle_{ijk}$ and $\triangle_{ijl}$ denote the two triangles sharing the edge $e_{ij}$. The final equality follows from the fact that
    $\frac{\partial \theta_{j}^{ik}}{\partial u_{i}}=\frac{\partial \theta_{i}^{jk}}{\partial u_{j}}$ by Remark \ref{Remark:Glickenstein-lemma}.  \hfill $\square$
    \end{proof}
With Corollary \ref{Corollary:Glickenstein-corollary} in hand, we now consider the positive definiteness of the Jacobian matrix $L^{T}$ under the condition $\Phi \in [0,\pi)$. We first present the entries of the matrix $L^{T}$ as follows:
\begin{equation*}
    \begin{pmatrix}
    A_{1}+\sum\limits_{j\neq 1}B_{1j} & -B_{12} & \cdots  & -B_{1N} \\
    -B_{21} & A_{2}+\sum\limits_{j\neq 2}B_{2j}  & \cdots  & -B_{2N} \\
    \vdots & \vdots & \ddots  & \vdots \\
    -B_{1,N-1} & -B_{2,N-1}  & \cdots  & -B_{N-1,N} \\
    -B_{1N} & -B_{2N} & \cdots  & A_{N}+\sum\limits_{j\neq N}B_{Nj}
    \end{pmatrix}.
\end{equation*}
It can be observed that this is a diagonally dominant matrix. Moreover, according to Corollary \ref{Corollary:Glickenstein-corollary}, the diagonal entries can be expressed as multiples of $B_{ij}$; therefore, the sign of $B_{ij}$ plays a critical role in determining the positive definiteness of the matrix.

Based on this observation, Zhou \cite{Zhou2019} discussed the structural conditions for obtuse circle packings. In particular, for any triangle $\triangle_{ijk} \in F$, Zhou \cite{Zhou2019} showed that the following inequalities hold:
\begin{equation*}
    \cos \Phi_{ij}+\cos \Phi_{ik}\cos \Phi_{jk}\ge 0,\\cos \Phi_{ik}+\cos \Phi_{ij}\cos \Phi_{jk}\ge 0,\ \cos \Phi_{jk}+\cos \Phi_{ij}\cos \Phi_{ik}\ge 0.
\end{equation*}
Set $\gamma_{ijk}=\cos \Phi_{jk}+\cos \Phi_{ij}\cos \Phi_{ik}$, then the above conditions can be rewritten as
\begin{equation*}
    \label{Equation:Zhou-condition}
    \tag{$\star$}
    \ \gamma_{ijk}\ge 0,\ \gamma_{jki}\ge 0,\ \gamma_{kij}\ge 0, \forall \triangle_{ijk}\in F.
\end{equation*}
Given the $(\star)$ condition,
Xu \cite{Xu2018} proved that the positive definiteness under the inversive distance condition,
and the obtuse case considered herein is a subset of that scenario.
We now state the positive definiteness lemma.
\begin{lemma}
    \label{Lemma:Positive-definiteness-lemma}
    In $\mathbb{H}^{2}$, given $(M, \mathcal{T}, \Phi)$ and assuming that the weight $\Phi$ satisfies the $(\star)$ condition, then the Jacobian matrix $L^{T}=-\Delta=\frac{\partial(K_{1},\ldots,K_{N})}{\partial(u_{1},\ldots,u_{N})}$ is symmetric and positive definite.
\end{lemma}

Furthermore, the finite lower boundness of the Laplace operator plays key role in the proof of the long-time existence of the combinatorial Calabi flows (\ref{Equation:rewritten_calabi_equation}).
Ge-Xu first studied the finite upper boundness of the Laplace operator in $\mathbb{H}^2$ when
$ \Phi \equiv 0$ (see \cite{Ge2016}, Proposition 3.1).
\begin{proposition}
    \label{Proposition:Ge-Xu-upper-bound}
    In $\mathbb{H}^{2}$, given $(M, \mathcal{T}, \Phi \equiv 0)$, we have
    \begin{equation*}
        \begin{gathered}
        0 < B_{ij} < 1, \\
        0 < A_{i} < d_{i}\cosh 1 \leq d\cosh 1,
        \end{gathered}
    \end{equation*}
where $d = \max_{1 \leq i \leq N}\{ d_{i} \}$ and $d_{i}$ denotes the degree at vertex $i$.

\end{proposition}


\section{The first improved estimate on the discrete Laplace operator}

In this section, we establish the first improved explicit estimate on the Laplace operator (\ref{discrete Laplacian operator}) and prove Theorem \ref{main result1}. Based on the quantitative relationship (Corollary \ref{Corollary:Glickenstein-corollary})
between $A_i$ and $B_{ij}$ and their expressions (\ref{AB-equality}),
our proof strategy is to first analyze the properties of the partial derivative $\frac{\partial \theta_i}{\partial u_j}$,
and then consider its properties when these derivatives are summed.
Our crucial observation is that for every face $\triangle_{ijk} \in F$,
there exists an edge $e_{ij} \in E$ such that $B_{ij} > 0$.\par
Firstly, we prove the following inequality.
\begin{proposition}
    	\label{proof_middle_prop}
    	Given three constants \(x, y, z \in [c, 1] , c \in (-1, 0]\). Suppose that the following condition holds
    	\begin{equation}
            \label{Theorem_middle_prop_1_condition}
            x + yz \geq 0, \
            y + xz \geq 0, \
            z + xy \geq 0.
        \end{equation}
    	Then we have
    	\[
    	2 - x^2 - y^2 + x + yz + y + xz + z + xy \geq 1 + c.
    	\]    	
    \end{proposition}
\begin{proof}
    If $\max\{x, y\} \leq |c|$, using the condition (\ref{Theorem_middle_prop_1_condition}), we obtain
    \begin{equation*}
    	\begin{aligned}
            &2 - x^2 - y^2 + (x + yz) + (y + xz) + (z + xy)
            \\
            &\geq 2 - 2c^2 + 0 + 0 + 0 \\
                                                     &\geq 2(1+c)(1-c) \\
                                                     &> 1+c.
        \end{aligned}
    \end{equation*}

    If $\max\{x, y\} > |c|$, there are two cases. In the first case  $\min\{x,y\} \leq |c|$, using condition (\ref{Theorem_middle_prop_1_condition}) and $\max\{x,y\} \leq 1$, we obtain
    \begin{equation*}
    	2 - x^2 - y^2 + (x + yz) + (y + xz) + (z + xy) \geq 2 - 1 - c^2 + 0 + 0 + 0\geq 1+c.
    \end{equation*}
    In the second case $|c| < \min\{x,y\} \leq 1$, by direct calculation we have
    \begin{equation*}
        \begin{aligned}
            &x^2 + y^2 - xy \\
            &\leq x + y - xy \\
            &= 1 - (1-x)(1-y) \\
            &\leq 1.
        \end{aligned}
    \end{equation*}.
    Hence we obtain
    \begin{equation*}
    	\begin{aligned}
    		 &2 - x^2 - y^2 + (x + yz) + (y + xz) + (z + xy) \\
             & \geq 2 - (x^2 + y^2 - xy) + z + 0 + 0\\
    		 & \geq 1 + z \\
             & \geq 1 + c.
    	\end{aligned}
    \end{equation*}
    This completes the proof of the Proposition \ref{proof_middle_prop}. \hfill $\square$
\end{proof}

\begin{theorem}
    \label{Proposition:A_i_and_B_ij_bound_compactness}
    \emph{
    Given a closed triangulated surface $(M, \mathcal{T}, \Phi)$ with $\Phi : E\rightarrow [0, \pi)$ satisfying the condition $\langle\star\rangle$.
    If the circle packing metric $r$ has a uniformly positive lower bound, i.e., $r_i \geq R > 0$ ($R$ is a constant) for any vertex $v_i \in V$,
    then there exists positive constants $a_1(\Phi, R), a_2(\Phi, R), a_3(\Phi, R)$ depending on the weight $\Phi$ and $R>0$ such that $a_1 \leq A_i \leq a_2$ and
    $0 \leq B_{ij} \leq a_3$ for any vertex $v_i, v_j \in V$.}
\end{theorem}

\noindent\begin{proof}

   First by (\ref{Equation:Glickenstein-remark_1}), we have
    \begin{equation*}
        \frac{\partial{\theta_i^{jk}}}{\partial{u_j}} = \frac{\partial{\theta_j^{ik}}}{\partial{u_i}}
        = \frac{1}{A_{ijk}\sinh^2{l_{ij}}}[C_kS_i^2S_j^2(1 - {\cos^2{\Phi_{ij}}})
        + C_iS_iS_j^2S_k\gamma_{jik} + C_jS_i^2S_jS_k\gamma_{ijk}],
    \end{equation*}
    where $C_i = \cosh r_i, S_i = \sinh r_i, A_{ijk} = \sinh{l_{ij}}\sinh{l_{ik}}\sin{\theta_i^{jk}}$ and
    $\gamma_{ijk} = \cos{\Phi_{jk}} + \cos{\Phi_{ij}}\cos{\Phi_{ik}}$.
    Since the weights satisfy the condition $\langle\star\rangle$
    (i.e., $\forall \triangle_{ijk} \in F, \, \gamma_{ijk} \geq 0 , \gamma_{jik} \geq 0 , \gamma_{kij} \geq 0$) and the fact that $l_{ij}, l_{ik}, l_{jk} > 0$ and $\theta_{i}^{jk} \in (0,\pi)$,
    this immediately implies
    \begin{equation*}
        \frac{\partial \theta_{i}^{jk}}{\partial u_j} \geq 0,
    \end{equation*}
    where the equality holds when $\Phi_{ij}=0$ and $\Phi_{ik}+\Phi_{jk}=\pi$.
    If $\triangle_{ijk} \in F$ and $\triangle_{ijl} \in F$ are adjacent faces,
    then $B_{ij} = \partial \theta_{i}^{jk} / \partial u_j + \partial \theta_{i}^{jl} / \partial u_j \geq 0$, where the equality holds when
    $\Phi_{ij}=0$, $\Phi_{ik}+\Phi_{jk}=\pi$, and $\Phi_{il}+\Phi_{jl}=\pi$.

    Set
    \begin{equation*}
        \cos{\Phi_{ij}} = \varphi_{ij},\ \cos{\Phi_{jk}} = \varphi_{jk},\ \cos{\Phi_{ik}} = \varphi_{ik}.
    \end{equation*}
    By calculation we have
    \begin{equation}
        \label{Equation:compact_proof_basic_expression_total}
        \frac{\partial{\theta_i^{jk}}}{\partial{u_j}} = \frac{\partial{\theta_j^{ik}}}
        {\partial{u_i}}
        =\frac{C_kS_i^2S_j^2(1-\varphi_{ij}^2) + C_iS_iS_j^2S_k(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) + C_jS_i^2S_jS_k(\varphi_{jk} + \varphi_{ij}\varphi_{ik})}
        {[(C_iC_j + \varphi_{ij}S_iS_j)^2 - 1]\sqrt{\Delta}},
    \end{equation}
    where
    \begin{equation}
        \label{Equation:compact_proof_basic_expression_delta}
        \begin{aligned}
            \Delta
            &= (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})S_i^2S_j^2S_k^2 + (1-\varphi_{ij}^2)S_i^2S_j^2 + (1-\varphi_{jk}^2)S_j^2S_k^2
            + (1-\varphi_{ik}^2)S_i^2S_k^2 \\[1mm]
            &+ (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})C_iC_jS_iS_jS_k^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})C_jC_kS_jS_kS_i^2
            + (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})C_iC_kS_iS_kS_j^2.
        \end{aligned}
    \end{equation}

    Given that $r_i \geq R > 0$ for every $v_i \in V$,
    and $S_i = \sinh{r_i} = \frac{1-e^{-2r_i}}{2}e^{r_i}$ and $C_i = \cosh{r_i} = \frac{1+e^{-2r_i}}{2}e^{r_i}$,
    it follows that there exists a positive constant
    $a(R) = \frac{1 - e^{-R}}{2}$ such that
    \begin{equation*}
    	2a^2 = \frac{1 + e^{-2R} - 2e^{-R}}{2} < \frac{1 - e^{-2R}}{2}.
    \end{equation*}
    Since $\frac{1 - e^{-2r_i}}{2} \geq \frac{1 - e^{-2R}}{2} > 2a^2$, we have
    \begin{equation}
        \label{Equation:compact_proof_sinh_bound}
    	2a^2e^{r_i}  \leq S_i \leq e^{r_i}  \ \text{for} \ i =1,2,\cdots, N.
    \end{equation}
	By the definition of the hyperbolic sine function, we have
	\begin{equation*}
		C_i = 2 \sinh^2 \frac{r_i}{2} + 1 = 2 (\frac{1 - e^{-r_i}}{2})^2 e^{{r_i}} + 1 \geq 2a^2e^{r_i} + 1,
	\end{equation*}
	hence we obtain
	\begin{equation}
        \label{Equation:compact_proof_cosh_bound}
	 2a^2e^{r_i} + 1 \leq C_i \leq e^{r_i}\ \text{for} \ i =1,2,\cdots, N.
	\end{equation}

    Now, we establish an upper and a lower bounds estimate for $\cosh l_{ij}-1$. We begin by expanding its expression as follows.
    \begin{equation*}
    	\begin{aligned}
    		\cosh{l_{ij}} - 1
    		& = C_iC_j + \varphi_{ij}S_iS_j - 1 \\[1mm]
    		& = \frac{e^{r_i} + e^{-r_i}}{2}\frac{e^{r_j} + e^{-r_j}}{2} + \varphi_{ij} \frac{e^{r_i} - e^{-r_i}}{2}\frac{e^{r_j} - e^{-r_j}}{2} -1 \\[1mm]
    		& = \frac{(1+\varphi_{ij})(e^{r_i+r_j}+e^{-r_i-r_j}) + (1-\varphi_{ij})(e^{-r_i+r_j}+e^{r_i-r_j})}{4} -1 \\[1mm]
    		& = e^{r_i+r_j}\frac{(1+\varphi_{ij})(1+e^{-2r_i-2r_j}) + (1-\varphi_{ij})(e^{-2r_i}+e^{-2r_j} )- 4 e^{-r_i-r_j}}{4}.
    	\end{aligned}
    \end{equation*}
    Let $\bar{\varphi} = \min\{\,0, \min\limits_{e_{ij}\in E} \varphi_{ij}\}\,$.
    By (\ref{Equation:compact_proof_sinh_bound}) and (\ref{Equation:compact_proof_cosh_bound}),
    we obtain the lower bound estimate
    \begin{equation}
        \label{Equation:compact_proof_cosh_lower_bound}
    	\begin{split}
    		\cosh{l_{ij}} - 1
            & \geq(2a^2e^{r_i} + 1) (2a^2e^{r_j} + 1) + 4\varphi_{ij}a^{4}e^{r_i+r_j} - 1 \\[1mm]
            & = 4a^4 (1 + \varphi_{ij}) e^{r_i + r_j} + 2a^2 e^{r_i} + 2a^2 e^{r_j}\\[1mm]
    		& \geq 4a^4 (1 + \bar\varphi) e^{r_i + r_j} \triangleq m_1e^{r_i + r_j},
    	\end{split}
    \end{equation}
     and the upper bound estimate
    \begin{equation}
        \label{Equation:compact_proof_cosh_upper_bound}
        \begin{split}
            \cosh{l_{ij}} - 1
            & = C_i C_j + \varphi_{ij} S_i S_j - 1\\[1mm]
            & \leq e^{r_i+r_j} + e^{r_i+r_j} - 1 \\[1mm]
            & \leq 2e^{r_i+r_j} \triangleq m_2 e^{r_i+r_j}.
    \end{split}
    \end{equation}
    In summary, we obtain two positive constants
    \begin{equation*}
        m_1(R, \Phi) = 4a^4(1+\bar{\varphi}) \ \text{ and } \ m_2 = 2.
    \end{equation*}

    Now we provide an upper and a lower bound estimate for the numerator of (\ref{Equation:compact_proof_basic_expression_total}).
    Combining the estimates (\ref{Equation:compact_proof_sinh_bound}) and (\ref{Equation:compact_proof_cosh_bound}) with the condition $\varphi \in (-1,1]$ for any $e_{ij} \in E$, we obtain the upper bound
    \begin{equation}
        \label{Equation:compact_proof_numerator_upper_bound}
        \begin{split}
            & C_kS_i^2S_j^2(1 - \varphi_{ij}^2) + C_iS_iS_j^2S_k(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) + C_jS_i^2S_jS_k(\varphi_{jk} + \varphi_{ij}\varphi_{ik}) \\[1mm]
            &\leq [(1 - \varphi_{ij}^2) +
            (\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
            (\varphi_{jk} + \varphi_{ij}\varphi_{ik})]e^{2r_i + 2r_j + r_k} \\[1mm]
            & \leq (5-\varphi_{ij}^2)e^{2r_i + 2r_j + r_k}\\[1mm]
            &\leq 5e^{2r_i + 2r_j + r_k} \triangleq m_3e^{2r_i + 2r_j + r_k}.
        \end{split}
    \end{equation}
    By the condition $\langle\star\rangle$ (i.e., for any $\triangle_{ijk}\in F$, we have $\varphi_{ij}+\varphi_{ik}\varphi_{jk}\geq 0$) and the two estimates (\ref{Equation:compact_proof_sinh_bound}) and (\ref{Equation:compact_proof_cosh_bound}),
    we obtain the lower bound
    \begin{equation}
        \label{Equation:compact_proof_numerator_lower_bound}
        \begin{split}
            & C_kS_i^2S_j^2(1 - \varphi_{ij}^2) + C_iS_iS_j^2S_k(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) + C_jS_i^2S_jS_k(\varphi_{jk} + \varphi_{ij}\varphi_{ik}) \\
            &\geq 32a^{10}[(1 - \varphi_{ij}^2) +
            (\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
            (\varphi_{jk} + \varphi_{ij}\varphi_{ik})]e^{2r_i + 2r_j + r_k} \\
            &\triangleq m_4e^{2r_i + 2r_j + r_k}.
        \end{split}
    \end{equation}
    Therefore, we obtain another two positive constants
    \begin{equation*}
        m_3=5  \ \text{ and } \ m_4(R, \Phi) =  32a^{10}[(1 - \varphi_{ij}^2) +
        (\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
        (\varphi_{jk} + \varphi_{ij}\varphi_{ik})].
    \end{equation*}

    Next, we provide an upper and a lower bound estimate for the denominator of (\ref{Equation:compact_proof_basic_expression_total}), which consists of two terms.
    We begin with the upper bound of the first term $(C_iC_j + \varphi_{ij}S_iS_j)^2 - 1$ as follows.
    \begin{equation}
        \label{Equation:compact_proof_denominator_first_part_upper_bound}
		\begin{split}
			&(C_iC_j+\varphi_{ij}S_iS_j)^2-1\\[1mm]
			&=(C_iC_j+\varphi_{ij}S_iS_j+1)(C_iC_j+\varphi_{ij}S_iS_j-1)\\[1mm]
			&\leq (e^{r_i+r_j} + e^{r_i+r_j} + 1) (e^{r_i+r_j} + e^{r_i+r_j} - 1)\\[1mm]
			&\leq (2e^{r_i + r_j} + 1)(2e^{r_i + r_j})\\[1mm]
			&\leq 6e^{2r_i+2r_j}\triangleq m_5e^{2r_i+2r_j}.
		\end{split}
	\end{equation}
    For the first term, we obtain a lower bound estimate
    \begin{equation}
        \label{Equation:compact_proof_denominator_first_part_lower_bound}
        \begin{split}
        	&(C_iC_j+\varphi_{ij}S_iS_j)^2-1\\[1mm]
        	& = (C_i C_j + \varphi_{ij} S_i S_j + 1) (C_i C_j + \varphi_{ij} S_i S_j - 1)\\[1mm]
        	& \geq ((2a^2e^{r_i}+1)(2a^2e^{r_j}+1) + 4a^4 \varphi_{ij} e^{r_i + r_j} + 1)((2a^2e^{r_i}+1)(2a^2e^{r_j}+1) + 4a^4 \varphi_{ij} e^{r_i + r_j} - 1)\\[1mm]
        	&=(4a^4 (1 + \varphi_{ij}) e^{r_i + r_j} + 2a^2 e^{r_i} + 2a^2 e^{r_j} + 2) (4a^4 (1 + \varphi_{ij}) e^{r_i + r_j} + 2a^2 e^{r_i} + 2a^2 e^{r_j} )\\[1mm]
        	&\geq 16a^8(1+\bar\varphi)^2e^{2r_i+2r_j}\triangleq m_6e^{2r_i+2r_j},
        \end{split}
    \end{equation}
    where we used the two estimates (\ref{Equation:compact_proof_sinh_bound}) and (\ref{Equation:compact_proof_cosh_bound}) in the third line.
    Hence, we obtain
    \begin{equation*}
        m_5 = 6 \ \text{ and } \ m_6(R,\Phi) =  16a^8(1+\bar\varphi)^2.
    \end{equation*}

    For the second part $\sqrt{\Delta}$, first we have the following upper bound estimate
        \begin{equation}
        \label{Equation:compact_proof_denominator_second_part_upper_bound}
        \begin{aligned}
            \Delta
            &= (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})S_i^2S_j^2S_k^2 + (1-\varphi_{ij}^2)S_i^2S_j^2 + (1-\varphi_{jk}^2)S_j^2S_k^2
            + (1-\varphi_{ik}^2)S_i^2S_k^2 \\[1mm]
            &\quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})C_iC_jS_iS_jS_k^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})C_jC_kS_jS_kS_i^2
            + (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})C_iC_kS_iS_kS_j^2 \\[1mm]
            &\leq (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})e^{2r_i + 2r_j + 2r_k}+(1-\varphi_{ij}^2)e^{2r_i + 2r_j}
            + (1-\varphi_{jk}^2)e^{2r_j + 2r_k} + (1-\varphi_{ik}^2)e^{2r_i + 2r_k} \\[1mm]
            &\quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})e^{2r_i + 2r_j + 2r_k}
            +(2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})e^{2r_i + 2r_j + 2r_k}
            +(2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})e^{2r_i + 2r_j + 2r_k} \\[1mm]
            &\leq 4e^{2r_i + 2r_j + 2r_k}  + (3 - \varphi_{ij}^2 - \varphi_{jk}^2 - \varphi_{ik}^2)e^{2r_i + 2r_j + 2r_k} + 4 e^{2r_i + 2r_j + 2r_k} + 4e^{2r_i + 2r_j + 2r_k} + 4e^{2r_i + 2r_j + 2r_k}\\[1mm]
            &\leq (19- \varphi_{ij}^2 - \varphi_{jk}^2 - \varphi_{ik}^2)e^{2r_i + 2r_j + 2r_k} \\[1mm]
            &\leq 19e^{2r_i + 2r_j + 2r_k} \triangleq m_7e^{2r_i + 2r_j + 2r_k}.
        \end{aligned}
    \end{equation}
    Then we give the lower bound estimate as follows.
    \begin{equation}
        \label{Equation:compact_proof_denominator_second_part_lower_bound}
        \begin{aligned}
            \Delta
            &= (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})S_i^2S_j^2S_k^2 + (1-\varphi_{ij}^2)S_i^2S_j^2 + (1-\varphi_{jk}^2)S_j^2S_k^2
            + (1-\varphi_{ik}^2)S_i^2S_k^2 \\[1mm]
            &\quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})C_iC_jS_iS_jS_k^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})C_jC_kS_jS_kS_i^2
            + (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})C_iC_kS_iS_kS_j^2 \\[1mm]
            &\geq 128(1+\varphi_{ij}\varphi_{jk}\varphi_{ik})a^{12}e^{2r_i + 2r_j + 2r_k} \\[1mm]
            &\quad +16(1-\varphi_{ij}^2)a^8e^{2r_i + 2r_j}
            + 16(1-\varphi_{jk}^2)a^8e^{2r_j + 2r_k} + 16(1-\varphi_{ik}^2)a^8e^{2r_i + 2r_k} \\[1mm]
            &\quad + 128(\varphi_{ij} + \varphi_{jk}\varphi_{ik} + \varphi_{jk} + \varphi_{ij}\varphi_{ik} + \varphi_{ik} + \varphi_{ij}\varphi_{jk}) a^{12} e^{2r_i + 2r_j + 2r_k} \\[1mm]
            &\geq 128(1+\varphi_{ij}\varphi_{jk}\varphi_{ik})a^{12}e^{2r_i + 2r_j + 2r_k} \\[1mm]
            &\geq 128(1+\bar{\varphi})a^{12}e^{2r_i + 2r_j + 2r_k} \triangleq m_8e^{2r_i + 2r_j + 2r_k}.
       \end{aligned}
    \end{equation}
    The first inequality follows from the estimates (\ref{Equation:compact_proof_sinh_bound}) and (\ref{Equation:compact_proof_cosh_bound}), together with the inequality $2a^2 e^{r_i} + 1 > 2a^2 e^{r_i}$.
    The section inequality follows from the range of $\varphi_{ij}$ and the condition $\langle \star \rangle$.
    The last inequality follows from the fact that for any $x,y,z \in (-1,1]$, $xyz \geq \min\{0,\min\{x,y,z\}\}$.

    Consequently, we obtain the fourth collection of positive constants
    \begin{equation*}
        m_7(R) = 19 \ \text{ and } \  m_8(R,\Phi) = 128(1+\bar{\varphi})a^{12}.
    \end{equation*}
	Thus, multipling the two estimates (\ref{Equation:compact_proof_denominator_first_part_upper_bound}) and (\ref{Equation:compact_proof_denominator_second_part_upper_bound}) gives
	\begin{equation}
        \label{Equation:compact_proof_denominator_upper_bound}
	    \begin{aligned}
            ((C_iC_j + \varphi_{ij}S_iS_j)^2 - 1)\sqrt{\Delta} &\leq m_5e^{2r_i+2r_j}\sqrt{m_7e^{2r_i+2r_j+2r_k}} \\[1mm]
            &= 6e^{2r_i+2r_j} \sqrt{19e^{2r_i+2r_j+2r_k}} \\[1mm]
            &\leq 30e^{3r_i+3r_j+r_k},
	    \end{aligned}
	\end{equation}	
	and multipling the two estimates (\ref{Equation:compact_proof_denominator_first_part_lower_bound}) and (\ref{Equation:compact_proof_denominator_second_part_lower_bound}) gives
	\begin{equation}
        \label{Equation:compact_proof_denominator_lower_bound}
		\begin{aligned}
			((C_iC_j + \varphi_{ij}S_iS_j)^2 - 1)\sqrt{\Delta} &\geq m_6e^{2r_i+2r_j}\sqrt{m_8e^{2r_i+2r_j+2r_k}} \\[1mm]
			&=16a^8(1+\bar{\varphi})^2e^{2r_i+2r_j}\sqrt{128(1+\bar{\varphi})a^{12}e^{2r_i+2r_j+2r_k}} \\[1mm]
			&\geq 128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}}\ e^{3r_i+3r_j+r_k}.
		\end{aligned}
	\end{equation}

    Combining the upper bound estimate (\ref{Equation:compact_proof_numerator_upper_bound})
    of the numerator and the lower bound estimate (\ref{Equation:compact_proof_denominator_lower_bound}) of the denominator, we obtain an upper bound estimate of (\ref{Equation:compact_proof_basic_expression_total})
    \begin{equation}
    	\label{Equation_partial_partial_upper}
    	\begin{aligned}
    		\frac{\partial{\theta_{j}^{ik}}}{\partial{u_i}}
    		&\leq \frac{m_3e^{2r_i+2r_j+r_k}}{ 128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}}e^{3r_i+3r_j+r_k}}  \\[1mm]
    		& =\frac{5}{ 128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }e^{-r_i-r_j}.
    	\end{aligned}
    \end{equation}
    Multiplying (\ref{Equation_partial_partial_upper}) and (\ref{Equation:compact_proof_cosh_upper_bound}) gives
    \begin{equation}
    	 \label{Equation:compact_proof_theta_cosh_upper_bound}
    	\begin{aligned}
    		\frac{\partial{\theta_{j}^{ik}}}{\partial{u_i}}(\cosh{l_{ij}}-1) &\leq \frac{5}{128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }e^{-r_i-r_j} m_2e^{r_i + r_j}
    		\\[1mm]
    		& =\frac{5}{64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }.
    	\end{aligned}    	
    \end{equation}

    Combining the lower bound estimate (\ref{Equation:compact_proof_numerator_lower_bound})
    of the numerator and the upper bound estimate (\ref{Equation:compact_proof_denominator_upper_bound}) of the denominator, we obtain a lower bound estimate of (\ref{Equation:compact_proof_basic_expression_total})
    \begin{equation}
    	\label{Equation_partial_partial_lower}
    	\begin{aligned}
    		\frac{\partial{\theta_{j}^{ik}}}{\partial{u_i}}
    		&\geq \frac{m_4e^{2r_i+2r_j+r_k}}{30e^{3r_i+3r_j+r_k}} \\[1mm]
    		& = \frac{ 16a^{10}[(1 - \varphi_{ij}^2) +
    			(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
    			(\varphi_{jk} + \varphi_{ij}\varphi_{ik})]}{15}e^{-r_i-r_j}.
    	\end{aligned}
    \end{equation}
    Multiplying (\ref{Equation_partial_partial_lower}) and (\ref{Equation:compact_proof_cosh_lower_bound}) gives
   \begin{equation}
    \label{Equation:compact_proof_theta_cosh_lower_bound}
   \begin{aligned}
      \frac{\partial{\theta_{j}^{ik}}}{\partial{u_i}}(\cosh{l_{ij}}-1)
      &\geq \frac{ 16a^{10}[(1 - \varphi_{ij}^2) +
      	(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
      	(\varphi_{jk} + \varphi_{ij}\varphi_{ik})]}{15}e^{-r_i-r_j} m_1 e^{r_i+r_j} \\[1mm]
      &= \frac{64a^{14}[(1 - \varphi_{ij}^2) +
                                (\varphi_{ik} + \varphi_{ij}\varphi_{jk}) +
                                (\varphi_{jk} + \varphi_{ij}\varphi_{ik})](1+\bar{\varphi})}{15}
   \end{aligned}
   \end{equation}
   By Proposition \ref{proof_middle_prop} we obtain the following lower bound
    \begin{equation}
        \label{Equation:compact_proof_theta_cosh_plus_theta_partial_lower_bound}
        \begin{split}
                &\frac{\partial{\theta_{j}^{ik}}}{\partial{u_i}}(\cosh{l_{ij}}-1)+ \frac{\partial{\theta_{k}^{ij}}}{\partial{u_i}}(\cosh{l_{ik}}-1) \\[1mm]
                &\geq
                    \frac{64a^{14}(1+\bar{\varphi})[
                        (2-\varphi_{ij}^2-\varphi_{ik}^2)+	
                        (\varphi_{ik} + \varphi_{ij}\varphi_{jk})
                    +   (\varphi_{jk} + \varphi_{ij}\varphi_{ik})
                    +	(\varphi_{ij} + \varphi_{ik}\varphi_{jk})
                    +   (\varphi_{jk} + \varphi_{ij}\varphi_{ik})
                    ]}{15} \\[1mm]
            & \geq \frac{64a^{14}(1+\bar{\varphi})(1+\bar\varphi)}{15}\\[1mm]
            & = \frac{64a^{14}(1+\bar{\varphi})^2}{15}.
        \end{split}
    \end{equation}
    By the expression (\ref{AB-equality}) of $B_{ij}$, we have $$B_{ij}(\cosh{l_{ij}}-1) + B_{ik}(\cosh{l_{ik}}-1) = (\frac{\partial{\theta_i^{jk}}}{\partial{u_j}}
+ \frac{\partial{\theta_i^{jl}}}{\partial{u_j}})(\cosh{l_{ij}}-1)+(\frac{\partial{\theta_i^{kj}}}{\partial{u_k}}
+ \frac{\partial{\theta_i^{km}}}{\partial{u_k}})(\cosh{l_{ik}}-1).$$
 Therefore, combining (\ref{Equation:compact_proof_theta_cosh_upper_bound}) and (\ref{Equation:compact_proof_theta_cosh_plus_theta_partial_lower_bound}) gives
\begin{equation*}
    \frac{64a^{14}(1+\bar{\varphi})^2}{15} \leq B_{ij}(\cosh{l_{ij}}-1) + B_{ik}(\cosh{l_{ik}}-1) \leq \frac{5}{16 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }.
\end{equation*}
Similarly, we obtain the following estimate of $A_i$
\begin{equation}
        \label{Equation:compact_proof_A_i_bound}
        \frac{64a^{14}(1+\bar{\varphi})^2}{15} \leq A_i = \sum_{j \thicksim i}{B_{ij}(\cosh{l_{ij}} - 1)} \leq \frac{5N}{64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }.
\end{equation}
and the following estimate of $B_{ij}$
    \begin{equation}
        \label{Equation:compact_proof_B_ij_bound}
           0 \leq
            B_{ij} = {(\frac{\partial{\theta_i^{jk}}}{\partial{u_j}}
            	+ \frac{\partial{\theta_i^{jl}}}{\partial{u_j}})} \leq
                \frac{5}{ 64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }e^{-r_i-r_j} \leq
                \frac{5}{ 64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }.
    \end{equation}
    By (\ref{Equation:compact_proof_A_i_bound}) and (\ref{Equation:compact_proof_B_ij_bound}), set the constants as
    \begin{equation*}
    a_1(\Phi, R) = \frac{64a^{14}(1+\bar{\varphi})^2}{15}, a_2(\Phi, R) = \frac{5N}{64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}}}, a_3(\Phi, R) = \frac{5}{ 64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} },
    \end{equation*}
    where $a= a(R) = \frac{1 - e^{-R}}{2}>0$ is a positive constant depending only on the constant $R>0$. We complete the proof.    $\hfill\Box$
\end{proof}

\section{The second improved estimate on the discrete Laplace operator}
In this section, we improve Theorem \ref{main result1} after removing the assumption of circle packing metrics with uniform positive lower bounds, i.e., $r_i \geq R > 0, \forall v_i \in V$ for a constant $R>0$ and prove Theorem \ref{main result2} by using the method of proof by cases. In fact, we show that for any the circle packing metric $r$, the positive upper bound constants $a_2(\Phi, R), a_3(\Phi, R)$ in Theorem \ref{main result1} do not depend on the constant $R>0$ in fact.
\begin{theorem}
    \label{Theorem2_uniform_upper_bound}
    \emph{Given a closed triangulated surface $(X, T, \Phi)$ with  $\Phi : E\rightarrow [0, \pi)$ satisfying the ($\star$) condition.
    Then for any the circle packing metric $r$, there exists positive constants $C_1(\Phi), C_2(\Phi)$ depending only on the weight $\Phi$
     such that $0<A_i \leq C_1$ and
     $0<B_{ij} \leq C_2$ for any vertex $v_i, v_j \in V$.   }
\end{theorem}
\begin{proof}
    We first prove the lower bound part of the estimates.
    Recall the definitions of $A_i$ and $B_{ij}$
    \begin{equation}
    \label{Proof_definition_A_B}
        \begin{aligned}
            B_{i j} &= \frac{\partial \theta_{i}^{j k}}{\partial u_{j}}+\frac{\partial \theta_{i}^{j l}}{\partial u_{j}}, \\
            A_{i} &= \sum_{v_j \sim v_i}B_{ij}\left(\cosh l_{ij}-1\right) = \sum_{v_j \sim v_i} \left( \frac{\partial \theta_{i}^{j k}}{\partial u_{j}}+\frac{\partial \theta_{i}^{j l}}{\partial u_{j}} \right) (\cosh l_{ij}-1),
        \end{aligned}
    \end{equation}
    where $\triangle_{ijk}$ and $\triangle_{ijl}$ denote the two triangles sharing the edge $e_{ij}$.
    The key expression is
    \begin{equation}
    \label{Equation:uniform_upper_bound_proof_theta_total_repeat_en}
    \frac{\partial{\theta_j^{ik}}}{\partial{u_i}}
    =\frac{C_kS_i^2S_j^2(1-\varphi_{ij}^2) + C_iS_iS_j^2S_k(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) + C_jS_i^2S_jS_k(\varphi_{jk} + \varphi_{ij}\varphi_{ik})}
    {\sinh^2 l_{ij} \sqrt{\Delta}},
    \end{equation}
    where  $C_i = \cosh r_i, S_i = \sinh r_i, A_{ijk} = \sinh{l_{ij}}\sinh{l_{ik}}\sin{\theta_i^{jk}}, \gamma_{ijk} = \cos{\Phi_{jk}} + \cos{\Phi_{ij}}\cos{\Phi_{ik}}$ and
    \begin{equation}
    \label{Equation:uniform_upper_bound_proof_theta_delta_repeat_en}
    \begin{aligned}
    \Delta
    &= (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})S_i^2S_j^2S_k^2 + (1-\varphi_{ij}^2)S_i^2S_j^2 + (1-\varphi_{jk}^2)S_j^2S_k^2
    (1-\varphi_{ik}^2)S_i^2S_k^2 \\
    &\quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})C_iC_jS_iS_jS_k^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})C_jC_kS_jS_kS_i^2
    (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})C_iC_kS_iS_kS_j^2.
    \end{aligned}
    \end{equation}
    Therefore, applying the condition $\langle \star \rangle$ and the fact that $l_{ij}, l_{ik}, l_{jk} > 0$ and $\theta_{i}^{jk} \in (0,\pi)$, we have
    \begin{equation}
    \label{Proof_first_geq0}
    	\frac{\partial{\theta_j^{ik}}}{\partial{u_i}} \geq 0,
    \end{equation}
    where the equality holds when $\Phi_{ij}=0$ and $\Phi_{ik}+\Phi_{jk}=\pi$.
    Thus $B_{ij} \geq 0$ and the equality holds when $\Phi_{ij}=0$, $\Phi_{ik}+\Phi_{jk}=\pi, \Phi_{il}+\Phi_{jl}=\pi$.
    By (\ref{Proof_first_geq0}), we get that $\partial{\theta_j^{ik}}/\partial{u_i} + \partial{\theta_k^{ij}/}\partial{u_i} \geq 0$. If the equality holds, then by the conditions for the equality in (\ref{Proof_first_geq0}), we have
    \begin{equation*}
    	\Phi_{ij}=0, \Phi_{ik}+\Phi_{jk}=\pi \ \text{ and } \ \Phi_{ik}=0, \Phi_{ij}+\Phi_{jk}=\pi,
    \end{equation*}
    which implies that $\Phi_{jk} = \pi$. This is a contradiction because the range of weight is $[0,\pi)$. Thus we obtain
    \begin{equation}
    \label{Proof_second_greater_2}
    	\frac{\partial{\theta_j^{ik}}}{\partial{u_i}} + 	\frac{\partial{\theta_k^{ij}}}{\partial{u_i}} > 0.
    \end{equation}
    Using (\ref{Proof_second_greater_2}) and the fact that $A_i \geq \partial{\theta_j^{ik}}/\partial{u_i} (\cosh l_{ij} - 1) + \partial{\theta_k^{ij}/}\partial{u_i} (\cosh l_{ik} - 1)$, we obtain $A_i > 0.$

    Now we prove the upper bound part of the estimates.
    By (\ref{Proof_definition_A_B}),
    it suffices to show that
    $\partial \theta_{j}^{ik}/\partial u_i(\cosh l_{ij}-1)$
    and
    $\partial \theta_{j}^{ik}/\partial u_i$
    have uniform upper bounds.
    Set
    \begin{equation}
    x = \frac{e^{2r_i} - 1}{2},\quad y = \frac{e^{2r_j} - 1}{2},\quad z = \frac{e^{2r_k} - 1}{2}.
    \end{equation}
    Note that $r_i, r_j, r_k \in (0, +\infty)$ corresponds to $x, y, z \in (0, +\infty)$.
    We also use the following notations for some polynomials in the weights
    \begin{equation}
        \label{Equation2_a_b_c_definition}
    \begin{gathered}
    a_1 = 1-\varphi_{ij}^2, \quad a_2 = 1-\varphi_{ik}^2,\quad a_3 = 1-\varphi_{jk}^2, \\
    b_1 = \varphi_{ij}+\varphi_{ik}\varphi_{jk},\quad b_2 = \varphi_{ik}+\varphi_{ij}\varphi_{jk},\quad b_3 = \varphi_{jk}+\varphi_{ij}\varphi_{ik}, \\
    c = 1 + \varphi_{ij}\varphi_{ik}\varphi_{jk}.
    \end{gathered}
    \end{equation}
    By the condition $\langle \star \rangle$, we have $a_n \ge 0$, $b_n \ge 0$ ($n=1,2,3$) and $c > 0$.
    Now we can rewrite the numerator and denominator of (\ref{Equation:uniform_upper_bound_proof_theta_total_repeat_en}) and the term $\cosh l_{ij}-1$ as polynomials in terms of the variables $x$, $y$, and $z$. We first deal with the product of the numerator and $e^{2r_i+2r_j+r_k}$,
    \begin{equation*}
        \begin{aligned}
            & [C_kS_i^2S_j^2(1-\varphi_{ij}^2) + C_iS_iS_j^2S_k(\varphi_{ik} + \varphi_{ij}\varphi_{jk}) + C_jS_i^2S_jS_k(\varphi_{jk} + \varphi_{ij}\varphi_{ik})] e^{2r_i+2r_j+r_k} \\
            &= (1-\varphi_{ij}^2)\frac{e^{2r_k} + 1}{2}(\frac{e^{2r_i} - 1}{2})^2(\frac{e^{2r_j} - 1}{2})^2 + (\varphi_{ik} + \varphi_{ij}\varphi_{jk})\frac{e^{2r_i} + 1}{2}\frac{e^{2r_i} - 1}{2}(\frac{e^{2r_j} - 1}{2})^2\frac{e^{2r_k} - 1}{2} \\
            &\quad + (\varphi_{jk} + \varphi_{ij}\varphi_{ik})\frac{e^{2r_j} + 1}{2}(\frac{e^{2r_i} - 1}{2})^2\frac{e^{2r_j} - 1}{2}\frac{e^{2r_k} - 1}{2} \\
            &= a_1 (z+1) x^2 y^2 + b_2 (x^2+x) y^2 z + b_3 (y^2+y) x^2 z \\
            &= (a_1+b_2+b_3)x^2y^2z + b_2\,xy^2z + b_3\,x^2yz + a_1x^2y^2.
            \end{aligned}
    \end{equation*}
	Define the last line as the following polynomial denote by \(f(x, y, z)\),
    \begin{equation}
    f(x,y,z) := (a_1+b_2+b_3)x^2y^2z + b_2\,xy^2z + b_3\,x^2yz + a_1x^2y^2.
    \end{equation}

    Multiplying the first part of the denominator by $e^{2r_i+2r_j}$, we obtain
    \begin{equation*}
        \begin{aligned}
            &[(C_iC_j + \varphi_{ij}S_iS_j)^2 - 1]e^{2r_i+2r_j} \\
            &= \left( \frac{e^{r_i}+e^{-r_i}}{2}\frac{e^{r_j}+e^{-r_j}}{2} + \varphi_{ij}\frac{e^{r_i}-e^{-r_i}}{2}\frac{e^{r_j}-e^{-r_j}}{2} \right)^2 e^{2r_i+2r_j} - e^{2r_i+2r_j} \\
            &= \left( \frac{e^{2r_i}+1}{2}\frac{e^{2r_j}+1}{2} + \varphi_{ij}\frac{e^{2r_i}-1}{2}\frac{e^{2r_j}-1}{2} \right)^2  - e^{2r_i+2r_j} \\
            &= ((x+1)(y+1) + \varphi_{ij} x y )^2 - (2x+1)(2y+1) \\
            &= (3+4\varphi_{ij}+\varphi_{ij}^2)\,x^2y^2 + 2(1+\varphi_{ij})(x^2y+xy^2) + x^2+y^2+ 2\varphi_{ij}\,xy\,.
            \end{aligned}
    \end{equation*}
    Then we write
    \begin{equation}
    g_1(x,y,z) := (3+4\varphi_{ij}+\varphi_{ij}^2)\,x^2y^2 + 2(1+\varphi_{ij})(x^2y+xy^2) + x^2+y^2+ 2\varphi_{ij}\,xy\,.
    \end{equation}
    Multiplying the term $(\cosh l_{ij}-1)$ by $e^{r_i+r_j}$ gives
\begin{equation*}
        \begin{aligned}
            & (\cosh l_{ij} - 1)e^{r_i+r_j} = \bigl(C_i C_j + \varphi_{ij} S_i S_j - 1\bigr)e^{r_i+r_j} \\
            & = \left( \frac{e^{r_i}+e^{-r_i}}{2}\frac{e^{r_j}+e^{-r_j}}{2} + \varphi_{ij} \frac{e^{r_i}-e^{-r_i}}{2}\frac{e^{r_j}-e^{-r_j}}{2} - 1 \right) e^{r_i+r_j} \\
            & = \left( (x+1)(y+1) + \varphi_{ij}xy \right) - \sqrt{(2x+1)(2y+1)} \\
            & = (1+\varphi_{ij})xy + x + y + 1 - \sqrt{4xy+2x+2y+1}\,.
            \end{aligned}
    \end{equation*}
    We write the polynomial $q(x,y,z)$ defined by
    \begin{equation}
    q(x,y,z) := (1+\varphi_{ij})xy + x + y + 1 - \sqrt{4xy+2x+2y+1}\,.
    \end{equation}
    Finally, we consider the product of $\Delta$ and $e^{2r_i+2r_j+2r_k}$
    \begin{equation*}
        \begin{aligned}
            &\ e^{2r_i+2r_j+2r_k}\Delta
            \\
            &= e^{2r_i+2r_j+2r_k}[(2+2\varphi_{ij}\varphi_{jk}\varphi_{ik})S_i^2S_j^2S_k^2 + (1-\varphi_{ij}^2)S_i^2S_j^2 + (1-\varphi_{jk}^2)S_j^2S_k^2
            + (1-\varphi_{ik}^2)S_i^2S_k^2 \\
            &\quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})C_iC_jS_iS_jS_k^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})C_jC_kS_jS_kS_i^2
            + (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})C_iC_kS_iS_kS_j^2]
            \\
            & = (2+2\varphi_{ij}\varphi_{jk}\varphi_{ik}) (\frac{e^{2r_i}-1}{2})^2(\frac{e^{2r_j}-1}{2})^2(\frac{e^{2r_k}-1}{2})^2+(1-\varphi_{ij}^2)(\frac{e^{2r_i}-1}{2})^2(\frac{e^{2r_j}-1}{2})^2  e^{2r_k}
            \\
            & \quad + (1-\varphi_{jk}^2)(\frac{e^{2r_j}-1}{2})^2(\frac{e^{2r_k}-1}{2})^2 e^{2r_i} +(1-\varphi_{ik}^2)(\frac{e^{2r_i}-1}{2})^2(\frac{e^{2r_k}-1}{2})^2 e^{2r_j}
            \\
            & \quad + (2\varphi_{ij} + 2\varphi_{jk}\varphi_{ik})(\frac{e^{4r_i}-1}{4})(\frac{e^{4r_j}-1}{4})(\frac{e^{2r_k}-1}{2})^2 + (2\varphi_{jk} + 2\varphi_{ij}\varphi_{ik})(\frac{e^{4r_j}-1}{4})(\frac{e^{4r_k}-1}{4})(\frac{e^{2r_i}-1}{2})^2
            \\
            & \quad + (2\varphi_{ik} + 2\varphi_{ij}\varphi_{jk})(\frac{e^{4r_i}-1}{4})(\frac{e^{4r_k}-1}{4})(\frac{e^{2r_j}-1}{2})^2
            \\
            & = 2c x^2y^2z^2
                +a_1x^2y^2(2z+1) + a_3y^2z^2(2x+1) +a_2x^2z^2(2y+1) + 2b_1(x^2+x)(y^2+y)z^2
                \\
            & \quad + 2b_3(y^2+y)(z^2+z)x^2 + 2b_2(x^2+x)(z^2+z)y^2
            \\
            & = 2(c+b_1+b_2+b_3)x^2y^2z^2 + 2(a_1+b_2+b_3)x^2y^2z + 2(a_3+b_1+b_2)xy^2z^2 + 2(a_2+b_1+b_3)x^2yz^2
            \\
            & \quad + a_1x^2y^2 + a_3y^2z^2 + a_2x^2z^2 + 2b_2xy^2z + 2b_3x^2yz + 2b_1xyz^2,
            % = \sum_{i=0}^{2}\sum_{j=0}^{2}\sum_{k=0}^{2} c_{ijk}\, x^i y^j z^k,
        \end{aligned}
    \end{equation*}
    and set
    \begin{equation}
    \begin{aligned}
    	g_2(x,y,z) &=  2(a_1+b_2+b_3)x^2y^2z + 2(a_3+b_1+b_2)xy^2z^2 + 2(a_2+b_1+b_3)x^2yz^2
    	 \\
    	& \quad + a_1x^2y^2 + a_3y^2z^2 + a_2x^2z^2 + 2b_2xy^2z + 2b_3x^2yz + 2b_1xyz^2
    	\\
    	& \quad + 2(c+b_1+b_2+b_3)x^2y^2z^2.
    \end{aligned}    	
    \end{equation}
    By the preceding discussions, we have that $g_1(x,y,z) > 0$ and  $g_2(x,y,z) > 0$.
    Now we have
    \begin{equation}
        \label{Equation2:expression_partial_theta_partial_u}
        \frac{\partial{\theta_j^{ik}}}{\partial{u_i}} = \frac{f(x,y,z)e^{r_i+r_j}}{g_1(x,y,z)\sqrt{g_2(x,y,z)}} = \frac{f(x,y,z)\sqrt{(2x+1)(2y+1)}}{g_1(x,y,z)\sqrt{g_2(x,y,z)}},
    \end{equation}
    and
    \begin{equation}
        \label{Equation2:expression_partial_theta_partial_u_coshl}
        \frac{\partial \theta_j^{ik}}{\partial u_i}(\cosh l_{ij}-1) = \frac{f(x,y,z) q(x,y,z)}{g_1(x,y,z)\sqrt{g_2(x,y,z)}}.
    \end{equation}

    For convenience, set
    \begin{equation}
        T_1(x,y,z) = \frac{\partial \theta_j^{ik}}{\partial u_i}
        \quad \text{and} \quad
        T_2(x,y,z) = \frac{\partial \theta_j^{ik}}{\partial u_i} (\cosh l_{ij} -1).
    \end{equation}
    Since the numerators and denominators are all elementary functions, $T_1(x,y,z)$ and $T_2(x,y,z)$ are well-defined and continuous on the open set $(0, +\infty)^3$. Let $\Omega_1$ and $\Omega_2$ be two disjoint subsets of the domain $(0, +\infty)^3$ such that they form a partition, i.e., $(0, +\infty)^3 = \Omega_1 \cup \Omega_2$. We define these subsets as follows
    \begin{equation}
    \label{theorem_proof_three_regions}
        \begin{gathered}
            \Omega_1 = \left\{ (x, y, z) \in (0, +\infty)^3 \mid \min(x,y,z) \geq \delta \right\},
            \Omega_2 = \left\{ (x, y, z) \in (0, +\infty)^3 \mid \min(x, y, z) < \delta \right\},
        \end{gathered}
    \end{equation}
    where $\delta > 0$ is a sufficiently small constant whose value is determined by the weights $\Phi_{ij}, \Phi_{ik}, \Phi_{jk}$.

    For $\Omega_1$, using the arguments from the proof of Theorem \ref{Proposition:A_i_and_B_ij_bound_compactness}, we obtain the following bounds
    \begin{equation*}
    	T_1(x,y,z) \leq \frac{5}{128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }, \  T_2(x,y,z) \leq \frac{5}{64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} },
    \end{equation*}
    where $a = \frac{1}{2}-\frac{1}{2\sqrt{2\delta+1}}>0$ and  $\bar{\varphi} = \min\{\,0, \min\limits_{e_{ij}\in E} \varphi_{ij}\}$.

    For $\Omega_2$, then at least one of the variables $x$, $y$, or $z$ may approach $0$, which can be divided into three cases based on the asymptotic behavior of the variables: (1) all variables approach $0$; (2) two variables approach $0$; (3) one variable approaches $0$.


    \textbf{Case 1: All three variables approach zero}

    Set $r = \sqrt{x^2 + y^2 + z^2}$ and $(\hat{x}, \hat{y}, \hat{z})=(\frac{x}{r}, \frac{y}{r}, \frac{z}{r})$ which satisfies $\hat{x}^{2}+\hat{y}^{2}+\hat{z}^{2}=1$. Since $(x,y,z) \in \mathbb{R}_{>0}^3$, we have $(\hat{x}, \hat{y}, \hat{z}) \in \mathbb{R}_{>0}^3\cap\mathbb{S}^2$. We now express $f, g_1,$ and $g_2$ as polynomials in $r$
    \begin{equation}
            \begin{aligned}
                f(x, y, z) & =  \sum_{k=4}^{5} f_k(\hat{x}, \hat{y}, \hat{z})\, r^k, \
                g_1(x, y, z) = \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y}, \hat{z})\, r^k, \
                g_2(x, y, z)  = \sum_{k=4}^{6} g_{2,k}(\hat{x}, \hat{y}, \hat{z})\, r^k,
            \end{aligned}
        \end{equation}
        where
        \begin{equation}
            \begin{aligned}
                f_4(\hat{x}, \hat{y}, \hat{z}) &= b_2 \hat{x} \hat{y}^2 \hat{z} + b_3 \hat{x}^2 \hat{y} \hat{z} + a_1 \hat{x}^2 \hat{y}^2, \\
                f_5(\hat{x}, \hat{y}, \hat{z}) &= (a_1+b_2+b_3)\hat{x}^2\hat{y}^2\hat{z}, \\
            \end{aligned}
        \end{equation}
        and
        \begin{equation}
            \begin{aligned}
                g_{1,2}(\hat{x}, \hat{y}, \hat{z}) &= \hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}, \\
                g_{1,3}(\hat{x}, \hat{y}, \hat{z}) &= 2(1 + \varphi_{ij})(\hat{x}^2 \hat{y} + \hat{x} \hat{y}^2), \\
                g_{1,4}(\hat{x}, \hat{y}, \hat{z}) &= (3 + 4\varphi_{ij} + \varphi_{ij}^2)\hat{x}^2 \hat{y}^2, \\
            \end{aligned}
        \end{equation}
        and
        \begin{equation}
            \begin{aligned}
                g_{2,4}(\hat{x}, \hat{y}, \hat{z}) &= a_1 \hat{x}^2 \hat{y}^2 + a_3 \hat{y}^2 \hat{z}^2 + a_2 \hat{x}^2 \hat{z}^2 + 2b_2 \hat{x} \hat{y}^2 \hat{z} + 2b_3 \hat{x}^2 \hat{y} \hat{z} + 2b_1 \hat{x} \hat{y} \hat{z}^2, \\
                g_{2,5}(\hat{x}, \hat{y}, \hat{z}) &= 2(a_1 + b_2 + b_3)\hat{x}^2 \hat{y}^2 \hat{z} + 2(a_3 + b_1 + b_2)\hat{x} \hat{y}^2 \hat{z}^2 + 2(a_2 + b_1 + b_3)\hat{x}^2 \hat{y} \hat{z}^2, \\
                g_{2,6}(\hat{x}, \hat{y}, \hat{z}) &= 2(c+b_1+b_2+b_3)\hat{x}^2 \hat{y}^2 \hat{z}^2, \\
            \end{aligned}
        \end{equation}
	If $a_1 = b_2 = b_3 = 0$, we have $f \equiv 0$. Hence there exists a constant $\delta > 0$ such that $(x,y,z) \in B((0,0,0), \delta)$, $T_1(x,y,z) = 0, T_2(x,y,z) = 0$.

    If $a_1 + b_2 + b_3 \neq 0$, dividing both the numerator and the denominator of $T_1(x,y,z)$ by $r^4$ gives
        \begin{equation*}
            \begin{aligned}
                T_1(x,y,z) &= \frac{f(x, y, z) \sqrt{(1+2x)(1+2y)}}{g_1(x, y, z)\sqrt{g_2(x, y, z)}}
                \\
                & = \frac{(f_4(\hat{x}, \hat{y}, \hat{z})+ f_5(\hat{x}, \hat{y}, \hat{z}) r) \sqrt{(1+2\hat{x}r)(1+2\hat{y}r)}}{(g_{1,2}(\hat{x}, \hat{y}, \hat{z}) + \sum_{k=3}^4 g_{1,k}(\hat{x}, \hat{y}, \hat{z})\, r^{k-2})\sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z}) + g_{2,5}(\hat{x}, \hat{y}, \hat{z}) r}}.
            \end{aligned}
        \end{equation*}
    Hence we have
    \begin{equation*}
        \begin{aligned}
            T_1(x,y,z) &\leq \frac{(f_4(\hat{x}, \hat{y}, \hat{z})+ f_5(\hat{x}, \hat{y}, \hat{z}) r) \sqrt{(1+2\hat{x}r)(1+2\hat{y}r)}}{(g_{1,2}(\hat{x}, \hat{y}, \hat{z}) )\sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z})}}
            \\
            &\leq \frac{f_4(\hat{x}, \hat{y}, \hat{z})(1+r)\sqrt{(1+2\hat{x}r)(1+2\hat{y}r)}}{(g_{1,2}(\hat{x}, \hat{y}, \hat{z}) )\sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z})}}.
        \end{aligned}
    \end{equation*}
    In the first line, we used $g_{1,3}, g_{1,4}, g_{2,5} \geq 0$,
    and in the second line,
    the fact that
    $\hat{x}^2 \hat{y}^2 \hat{z} \leq \hat{x} \hat{y}^2 \hat{z}$,
    $\hat{x}^2 \hat{y}^2 \hat{z} \leq \hat{x}^2  \hat{y} \hat{z} $
    and $\hat{x}^2 \hat{y}^2 \hat{z} \leq \hat{x}^2  \hat{y}^2 $
    which are consequences of  $\hat{x}, \hat{y}, \hat{z} \in (0,1)$.
    Hence for a samll enough $\epsilon$ there exists a small enough constant $\delta_0(\epsilon)$ such that $r\leq \delta_0$, it follows that
    \begin{equation}
    	T_1(x,y,z) \leq \frac{f_4(\hat{x}, \hat{y}, \hat{z})}{g_{1,2}(\hat{x}, \hat{y}, \hat{z}) \sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z})}} + \epsilon.
    \end{equation}
    It remains to prove  $\frac{f_4(\hat{x}, \hat{y}, \hat{z})}{g_{1,2}(\hat{x}, \hat{y}, \hat{z}) \sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z})}}$ is bounded. We now employ the notation
        \begin{equation}
            \begin{aligned}
                s(\hat{x}, \hat{y}, \hat{z}) &= \frac{f_4(\hat{x}, \hat{y}, \hat{z})}{g_{1,2}(\hat{x}, \hat{y}, \hat{z}) \sqrt{g_{2,4}(\hat{x}, \hat{y}, \hat{z})}}
                \\
                &= \frac{b_2 \hat{x} \hat{y}^2 \hat{z} + b_3 \hat{x}^2 \hat{y} \hat{z} + a_1 \hat{x}^2 \hat{y}^2}{(\hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_1 \hat{x}^2 \hat{y}^2 + a_3 \hat{y}^2 \hat{z}^2 + a_2 \hat{x}^2 \hat{z}^2 + 2b_2 \hat{x} \hat{y}^2 \hat{z} + 2b_3 \hat{x}^2 \hat{y} \hat{z} + 2b_1 \hat{x} \hat{y} \hat{z}^2}}.
            \end{aligned}
        \end{equation}
    If $a_3 \neq 0, a_2 \neq 0$, we obtain
    \begin{equation*}
    \begin{aligned}
    s(\hat{x}, \hat{y}, \hat{z}) &\leq \frac{b_2  \hat{x} \hat{y}^2 \hat{z}}{(2+2\varphi_{ij}) xy \sqrt{a_3 y^2 z^2 }} + \frac{b_3 \hat{x}^2 \hat{y} \hat{z}}{(2+2\varphi_{ij}) xy \sqrt{a_2 \hat{x}^2 \hat{z}^2 }} + \frac{a_1 \hat{x}^2 \hat{y}^2}{(2+2\varphi_{ij})xy \sqrt{a_1 \hat{x}^2 \hat{y}^2}}
        	\\
    &\leq \frac{b_2}{(2+2\varphi_{ij})\sqrt{a_3}} + \frac{b_3}{(2+2\varphi_{ij})\sqrt{a_2}} + \frac{a_1}{(2+2\varphi_{ij})\sqrt{a_1}}.
    \end{aligned}  	
   	\end{equation*}
   	If $a_3 = 0, a_2 \neq 0$, we have $b_3 = \varphi_{jk} + \varphi_{ij} \varphi_{ik} = 1 + \varphi_{ij} \varphi_{ik} > 0$ and $b_2 = b_1 = \varphi_{ij} + \varphi_{ik}$. Hence we obtain
   	\begin{equation*}
   	\begin{aligned}
   	   		s(\hat{x}, \hat{y}, \hat{z}) &\leq \frac{b_2 \hat{x} \hat{y}^2 \hat{z} + b_3 \hat{x}^2 \hat{y} \hat{z} + a_1 \hat{x}^2 \hat{y}^2}{(\hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_1 \hat{x}^2 \hat{y}^2 + a_2 \hat{x}^2 \hat{z}^2 + 2b_3 \hat{x}^2 \hat{y} \hat{z} }}
   	   		\\
   	   		& = \frac{b_2  \hat{y}^2 \hat{z} + b_3 \hat{x} \hat{y} \hat{z} + a_1 \hat{x} \hat{y}^2}{(\hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_1 \hat{y}^2 + a_2  \hat{z}^2 + 2b_3  \hat{y} \hat{z} }}.
   	\end{aligned}
   	\end{equation*}
       The denominator of the expression vanishes if either $(\hat{x}, \hat{y}, \hat{z}) \to (0,0,1)$ or $(\hat{x}, \hat{y}, \hat{z}) \to (1,0,0)$. Consider the first case. As $(\hat{x}, \hat{y}, \hat{z}) \to (0,0,1)$ along the specific path defined by $\hat{y} = k\hat{x}$, where $k \in (0,+\infty)$ is an arbitrary constant, we have
   	\begin{equation*}
   	\label{equation:proof_s_hatx_haty_hatz_1}
   	\begin{aligned}
   	   		s(\hat{x}, \hat{y}, \hat{z}) &\leq  \frac{b_2  k^2 \hat{x}^2 \hat{z} + b_3 k\hat{x}^2  \hat{z} + a_1 k^2 \hat{x}^3}{(\hat{x}^2 + k^2\hat{x}^2 + 2\varphi_{ij}k \hat{x}^2) \sqrt{a_1 k^2\hat{x}^2 + a_2  \hat{z}^2 + 2b_3  k\hat{x} \hat{z} }}
   	   		\\
   	   		&\leq \frac{b_2  k^2 \hat{z}  + b_3 k \hat{z} + a_1 k^2 \hat{x}}{(1 + k^2 + 2\varphi_{ij}k ) \sqrt{ a_2  \hat{z}^2 }} .
   	\end{aligned}
   	\end{equation*}
   	Since $\hat{x} \to 0, \hat{z} \to 1$, we obtain that if $k \to 0$, the right term tends to $0$, which implies $s(\hat{x}, \hat{y}, \hat{z}) \leq \epsilon$ for a samll enough constant $\epsilon$.
    If $k \to +\infty$, $s(\hat{x}, \hat{y}, \hat{z}) \leq \frac{b_2}{\sqrt{a_2}}$.
    Hence, we obtain that for any $k$, there exists a constant $c_0>0$ such that $s(\hat{x}, \hat{y}, \hat{z}) \leq c_0$ along the fixed path $\hat{y} = k \hat{x}$ to $(0,0,1)$, which implies that along any path to $(0,0,1)$ we have $s(\hat{x}, \hat{y}, \hat{z}) \leq c_{0}$. Hence there exists $\delta_0> 0$  such that if $(\hat{x}, \hat{y}, \hat{z}) \in B((0,0,1), \delta_0)$, we have $s(\hat{x}, \hat{y}, \hat{z}) \leq c_0$.

   	For $(\hat{x}, \hat{y}, \hat{z}) \to (1,0,0)$, using analogous methods we show that there exists a constant $c_1>0$ and a correspending constant $\delta_1 > 0$ such that if $(\hat{x}, \hat{y}, \hat{z}) \in B((0,0,1), \delta_1)$, we have  $s(\hat{x}, \hat{y}, \hat{z}) \leq c_1$.

   	For the compact set $(\hat{x}, \hat{y}, \hat{z}) \in \{\hat{x}^2 + \hat{y}^2 + \hat{z}^2 = 1\} / ( B((0,0,1), \delta_0) \cup B((1,0,0), \delta_1))$, since the denominator is not zero , using the continuity of the numerator and the denominator, we obtain that there exists a constant $c_2>0$ such that $s(\hat{x}, \hat{y}, \hat{z}) \leq c_2$.

   	Set $C = \max\{c_0, c_1, c_2\}>0$, and we have
   	\begin{equation*}
   		s(\hat{x}, \hat{y}, \hat{z}) \leq C, \text{ if } a_3 = 0, a_2 \neq 0.
   	\end{equation*}

   	The case where $a_2 = 0, a_3 \neq 0$ is analogous. 	
    We now consider $a_2 = a_3 =0$, which  implies that $b_2 > 0, b_3 > 0$.  Since $b_1 = b_3 = b_2$ in this case, we have  $b_1 > 0$. Hence we obtain
    \begin{equation*}
    \begin{aligned}
        	s(\hat{x}, \hat{y}, \hat{z}) &\leq \frac{b_2 \hat{x} \hat{y}^2 \hat{z} + b_3 \hat{x}^2 \hat{y} \hat{z} + a_1 \hat{x}^2 \hat{y}^2}{(\hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_1 \hat{x}^2 \hat{y}^2 + 2b_2 \hat{x} \hat{y}^2 \hat{z} + 2b_3 \hat{x}^2 \hat{y} \hat{z} + 2b_1 \hat{x} \hat{y} \hat{z}^2}} \\
        	&\leq \frac{b_2 \hat{x}^{\frac{1}{2}} \hat{y}^\frac{3}{2} \hat{z} + b_3 \hat{x}^\frac{3}{2} \hat{y}^\frac{1}{2} \hat{z} + a_1 \hat{x}^\frac{3}{2} \hat{y}^\frac{3}{2}}{(\hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_1 \hat{x} \hat{y} + 2b_2  \hat{y} \hat{z} + 2b_3 \hat{x}  \hat{z} + 2b_1 \hat{z}^2}}.
    \end{aligned}
    \end{equation*}
    The denominator tends to zero only if $(\hat{x}, \hat{y}, \hat{z}) \to (0,0,1)$. Along the specific path $\hat{y} = k\hat{x}$, for any constant $k \in (0,+\infty)$, we obtain
    \begin{equation*}
    	s(\hat{x}, \hat{y}, \hat{z}) \leq \frac{b_2 k^{\frac{3}{2}}  \hat{z} + b_3 k^{\frac{1}{2}}  \hat{z} + a_1 k^{\frac{3}{2}} \hat{x} }{(1+ k^2 + 2\varphi_{ij} k)  \sqrt{a_1 \hat{x} \hat{y} + 2b_2  \hat{y} \hat{z} + 2b_3 \hat{x}  \hat{z} + 2b_1 \hat{z}^2}}.
    \end{equation*}
    Since $(\hat{x}, \hat{y}, \hat{z}) \to (0,0,1)$, we obtain that if $k \to 0$, the right term of the above equality tends to $0$, which implies that $s(\hat{x}, \hat{y}, \hat{z}) \leq 1$.
    If $k \to +\infty$, the right term of the above equality tends to $0$ which implies that $s(\hat{x}, \hat{y}, \hat{z}) \leq 1$.
    Hence, using analogous methods we obtain that there exists $\delta_0> 0$  such that if $(\hat{x}, \hat{y}, \hat{z}) \in B((0,0,1), \delta_0)$, we have $s(\hat{x}, \hat{y}, \hat{z}) \leq c_3$.

    For the compact set $(\hat{x}, \hat{y}, \hat{z}) \in \mathbb{R}_{\geq 0}^3 \cap \{\hat{x}^2 + \hat{y}^2 + \hat{z}^2 = 1\} / ( B((0,0,1), \delta_0))$, since the denominator is not zero, using the continuity of the numerator and the denominator, we obtain that there exists a constant $c_4$ such that $s(\hat{x}, \hat{y}, \hat{z}) \leq c_4$.

    Let $C = \max\{c_3, c_4\}$, we have
    \begin{equation*}
        s(\hat{x}, \hat{y}, \hat{z}) \leq C, \text{ if } a_2 = a_3 = 0.
    \end{equation*}

    Summarizing the preceding discussion of the various cases, we obtain the following
    \begin{equation}
        \label{equation:proof_delta_0_estimate}
        \exists C > 0, \exists \delta_0 > 0, \forall (x,y,z) \in B((0,0,0), \delta_0), T_1(x,y,z) \leq C.
    \end{equation}
    Since $T_2(x,y,z) = T_1(x,y,z) (\cosh l_{ij} -1)$, using the relation of $x,y,z$ of $r_i, r_j, r_k$, we get that if $(x,y,z) \in B((0,0,0), \delta_0)$ for some small $\delta_0$, then $\cosh l_{ij} -1 = C_i C_j + \varphi_{ij} S_i S_j - 1 \leq 1$. Hence we also have $T_2(x,y,z) \leq C$.

    \textbf{Case 2: Two variables approach zero}

         When exactly two variables vanish, three distinct sub-cases arise, corresponding to whether \(x = 0\), \(y = 0\), or \(z = 0\).
         First consider the sub-case where \((x,y,z) \in \mathbb{R}^3_{>0}\) approaches
          \((0, 0, \bar{z}) \in D\), with any \(\bar{z}\geq \delta_0\) where $\delta_0$ is choosed in (\ref{equation:proof_delta_0_estimate}).
        \begin{itemize}
            \item $ x \to 0, y \to 0, z \to \bar{z}\geq \delta_0 $
        \end{itemize}
        Let $\rho_{xy} = \sqrt{x^2 + y^2}$ and $x = \rho_{xy} \hat{x} , y= \rho_{xy} \hat{y}$. Since the region is in $\mathbb{R}_{>0}^3$, we have $0 < \hat{x} <1$ and $0 < \hat{y} <1$. We express both the numerator and the denominator as polynomials in the variable $\rho_{xy}$
        \begin{equation}
        \begin{aligned}
            f(x, y, z) &= \sum_{k=3}^{4} f_k(\hat{x}, \hat{y}, z)\, \rho_{xy}^k, \quad
            g_1(x, y, z) = \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^k, \quad
            g_2(x, y, z) = \sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^k,
        \end{aligned}
        \end{equation}
        where
        \begin{equation}
            \begin{aligned}
                f_3(\hat{x}, \hat{y}, z) &= b_2 \hat{x} \hat{y}^2 z + b_3 \hat{x}^2 \hat{y} z, \\
                f_4(\hat{x}, \hat{y}, z) &= a_1 \hat{x}^2 \hat{y}^2 + (a_1 + b_2 + b_3) \hat{x}^2 \hat{y}^2 z,
        	 \end{aligned}
        \end{equation}
        and
        \begin{equation}
            \begin{aligned}
                g_{1,2}(\hat{x}, \hat{y}) &= \hat{x}^2 + \hat{y}^2 + 2\varphi_{ij} \hat{x} \hat{y} = 1 + 2\varphi_{ij} \hat{x} \hat{y}, \\
                g_{1,3}(\hat{x}, \hat{y}) &= 2(1 + \varphi_{ij})(\hat{x}^2 \hat{y} + \hat{x} \hat{y}^2), \\
                g_{1,4}(\hat{x}, \hat{y}) &= (3 + 4\varphi_{ij} + \varphi_{ij}^2)\hat{x}^2 \hat{y}^2,
            \end{aligned}
        \end{equation}
        and
        \begin{equation}
                \begin{aligned}
                g_{2,2}(\hat{x}, \hat{y}, z) &= a_3 \hat{y}^2 z^2 + a_2 \hat{x}^2 z^2 + 2b_1 \hat{x} \hat{y} z^2, \\
                g_{2,3}(\hat{x}, \hat{y}, z) &= 2(a_3 + b_1 + b_2)\hat{x} \hat{y}^2 z^2 + 2(a_2 + b_1 + b_3)\hat{x}^2 \hat{y} z^2 + 2b_2 \hat{x} \hat{y}^2 z + 2b_3 \hat{x}^2 \hat{y} z, \\
                g_{2,4}(\hat{x}, \hat{y}, z) &= a_1 \hat{x}^2 \hat{y}^2 + 2(a_1 + b_2 + b_3)\hat{x}^2 \hat{y}^2 z + 2(c + b_1 + b_2 + b_3)\hat{x}^2 \hat{y}^2 z^2.
            \end{aligned}
        \end{equation}
        The condition $\langle \star \rangle$ implies $a_3 + a_2 + b_1 = 1 - \varphi_{jk}^2 + 1 - \varphi_{ik}^2 + \varphi_{ij} + \varphi_{ik}\varphi_{jk} \geq 0$. The equality holds if and only if $\varphi_{jk} = 1, \varphi_{ik} = 1, \varphi_{ij} + \varphi_{ik} \varphi_{jk} = 0$. However,this is impossible considering the range of $\varphi$. Consequently, $a_3 + a_2 + b_1 > 0$, and as a result, $g_{2,2} > 0$. Noting that $\hat{x}^2 + \hat{y}^2 = 1$ and $-1 < \varphi_{ij} \leq 1$, it is clear that $1+2\varphi_{ij} \hat{x} \hat{y} > 0$, which implies that $g_{1,2} > 0$.

        If $b_2 = b_3 = 0$, then $f_3 \equiv 0$.  By dividing both the numerator and denominator of $T_1(x,y,z)$ by the term $\rho_{xy}^{3}$, the expression becomes
        \begin{equation*}
        \begin{aligned}
            T_1(x,y,z) &= \frac{f_4(\hat{x}, \hat{y}, z) \rho_{xy}^{4} \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^k) \sqrt{ \sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^k}}
            \\
            &= \frac{f_4(\hat{x}, \hat{y}, z) \rho_{xy} \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^{k-2}) \sqrt{ \sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-2}}}.
        \end{aligned}
        \end{equation*}
        However, $f_4(\hat{x}, \hat{y}, z)$ tends to infinity as $z \to +\infty$. Therefore, by dividing both the numerator and the denominator by $z$, we obtain
        \begin{equation*}
            \begin{aligned}
                T_1(x,y,z) &= \frac{\frac{f_4(\hat{x}, \hat{y}, z) }{z}\rho_{xy} \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^{k-2}) \sqrt{ \frac{\sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-2}}{z^2}}}.
            \end{aligned}
        \end{equation*}
        Since $\bar{z} \geq \delta_0$, we have $0 < \frac{1}{\bar{z}} \leq \frac{1}{\delta_0}$. Considering this and the continuity of the numerator and the denominator, it follows that for any $\epsilon > 0$, there exists a constant $\delta_1 > 0$ such that if $(x,y,z) \in B((0,0,\bar{z}), \delta_1)$ for any $\bar{z} \geq \delta_0$, we have
        \begin{equation*}
            T_1(x,y,z) = \frac{\frac{f_4(\hat{x}, \hat{y}, z) }{z}\rho_{xy} \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^{k-2}) \sqrt{ \frac{\sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-2}}{z^2}}} \leq \epsilon.
        \end{equation*}

        When $b_2 \ne 0$ or $b_3 \ne 0$, the expression $T_1(x,y,z)$ can be rewritten as follows by dividing both its numerator and denominator by $\rho_{xy}^{3}$
        \begin{equation*}
            \begin{aligned}
                T_1(x,y,z) &= \frac{(\sum_{k=3}^{4} f_k(\hat{x}, \hat{y}, z)\, \rho_{xy}^k) \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^k) \sqrt{ \sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^k}}
                \\
                &= \frac{(\sum_{k=3}^{4} f_k(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-3}) \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^{k-2}) \sqrt{ \sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-2}}}.
            \end{aligned}
        \end{equation*}
        The numerator and denominator both include zeroth-order terms in $\rho_{xy}$, which implies that $T_1(x,y,z)$ may not converge.
        Analogously, to ensure the boundedness of both the numerator and denominator, we divide them by $z$, which gives
        \begin{equation*}
            T_1(x,y,z) = \frac{\frac{(\sum_{k=3}^{4} f_k(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-3})}{z} \sqrt{(1 + 2\rho_{xy} \hat{x})(1+2\rho_{xy} \hat{y})}}{( \sum_{k=2}^{4} g_{1,k}(\hat{x}, \hat{y})\, \rho_{xy}^{k-2}) \sqrt{ \frac{\sum_{k=2}^{4} g_{2,k}(\hat{x}, \hat{y}, z)\, \rho_{xy}^{k-2}}{z^2}}}.
        \end{equation*}
        Using $0 < \frac{1}{\bar{z}} \leq \frac{1}{\delta_0}$ and the continuity of the numerator and the denominator, it follows that for any $\epsilon > 0$, there exists a constant $\delta_1 > 0$ such that if $(x,y,z) \in B((0,0,\bar{z}), \delta_1)$ for any $\bar{z} \geq \delta_0$, we have
        \begin{equation*}
            T_1(x,y,z) \leq \frac{\frac{f_3(\hat{x}, \hat{y}, \bar{z})}{z}}{g_{1,2}(\hat{x}, \hat{y}) \sqrt{\frac{g_{2,2}(\hat{x}, \hat{y}, \bar{z})}{z^2}}} +  \epsilon = \frac{b_2 \hat{x} \hat{y}^2  + b_3 \hat{x}^2 \hat{y} }{(1 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_3 \hat{y}^2 + a_2 \hat{x}^2 + 2b_1 \hat{x} \hat{y}}} +  \epsilon.
        \end{equation*}
        It remains to demonstrate the boundedness of the right-hand side of the above inequality. We now employ the notation
        \begin{equation*}
            s(\hat{x}, \hat{y}) = \frac{b_2 \hat{x} \hat{y}^2  + b_3 \hat{x}^2 \hat{y} }{(1 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_3 \hat{y}^2 + a_2 \hat{x}^2 + 2b_1 \hat{x} \hat{y}}}.
        \end{equation*}

        If $a_3 \neq 0$ and $a_2 \neq 0$, we are concerned with $(\hat{x}, \hat{y})$ such that $\hat{x}^2 + \hat{y}^2 = 1$ and $0 < \hat{x}, \hat{y} \leq 1$. Consider now the slightly enlarged compact domain where $\hat{x}^2 + \hat{y}^2 = 1$ and $0 \leq \hat{x}, \hat{y} \leq 1$.  In this domain, the numerator $b_2 \hat{x} \hat{y}^2 + b_3 \hat{x}^2 \hat{y}$ is continuous and thus achieves a maximum value. The denominator $(1 + 2\varphi_{ij} \hat{x} \hat{y}) \sqrt{a_3 \hat{y}^2 + a_2 \hat{x}^2 + 2b_1 \hat{x} \hat{y}}$, is also continuous and attains a minimum which is strictly positive. Therefore, we can find a constant $C_1 > 0$ such that $s(\hat{x}, \hat{y}) \leq C_1$ for any unit vector $(\hat{x},\hat{y})$.

        If $a_3 = 0$ and $a_2 \neq 0$, we divide $s(\hat{x}, \hat{y})$ by $x^{\frac{1}{2}}$ as follows
        \begin{equation*}
            s(\hat{x}, \hat{y}) = \frac{b_2 \hat{x}^{\frac{1}{2}} \hat{y}^{2} + b_3 \hat{x}^\frac{3}{2} \hat{y}}{(1+\varphi_{ij}\hat{x}\hat{y}) \sqrt{a_2 \hat{x} + 2b_1 \hat{y}}}.
        \end{equation*}
        Hence we obtain
        \begin{equation*}
            \begin{aligned}
                s(\hat{x}, \hat{y}) &\leq \frac{b_2 \hat{x}^{\frac{1}{2}} \hat{y}^{2} + b_3 \hat{x}^\frac{3}{2} \hat{y}}{(1+\varphi_{ij}\hat{x}\hat{y}) \sqrt{a_2 \hat{x}}}
                \\
                & \leq \frac{b_2 \hat{y}^{2} + b_3 \hat{x} \hat{y}}{(1+\varphi_{ij}\hat{x}\hat{y}) \sqrt{a_2}}
                \\
                & \leq \frac{b_2 + b_3 }{(1+\bar{\varphi})\sqrt{a_2}}.
            \end{aligned}
        \end{equation*}
        The case where $a_3 \neq 0$ and $a_2 = 0$ is analogous. \par
        If $a_3 = 0$ and $a_2 = 0$, in this case, $b_1 = b_2 = b_3 = \varphi_{ij} + 1$. Hence we obtain
        \begin{equation*}
            \begin{aligned}
