                \\
                & \leq \frac{b_2 + b_3 }{(1+\bar{\varphi}) \sqrt{2b_1}}.
            \end{aligned}
        \end{equation*}
        Summarizing the preceding discussion of the various cases, we have
    \begin{equation}
        \label{equation:proof_delta_1_estimate}
        \exists C > 0, \exists \delta_1 > 0, \forall \bar{z} \geq \delta_0, \forall (x,y,z) \in B((0,0,\bar{z}), \delta_1), T_1(x,y,z) \leq C.
    \end{equation}
    Since $T_2(x,y,z) = T_1(x,y,z) (\cosh l_{ij} -1)$, using the relation of $x,y,z$ of $r_i, r_j, r_k$, we obtain that if $(x,y,z) \in B((0,0,\bar{z}), \delta_1)$ for some small $\delta_0$ and any $\bar{z} \geq \delta_0$, then $T_2(x,y,z) \leq C$.
        \begin{itemize}
