        \end{itemize}
        Let $\rho_{xz} = \sqrt{x^2 + z^2}$ and $x = \rho_{xz} \hat{x} , z= \rho_{xz} \hat{z}$. Since the region is in $\mathbb{R}_{>0}^3\cap\mathbb{S}^2$, we have $0 < \hat{x} <1$ and $0 < \hat{z} <1$. We express both the numerator and the denominator as polynomials in the variable $\rho_{xz}$
        \begin{equation}
        \begin{aligned}
            f(x, y, z) &= \sum_{k=2}^{3} f_k(\hat{x}, y, \hat{z})\, \rho_{xz}^k, \quad
            g_1(x, y, z) = \sum_{k=0}^{2} g_{1,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^k, \quad
