            \end{aligned}
        \end{equation}
        and
        \begin{equation}
            \begin{aligned}
                g_{2,2}(\hat{x}, y, \hat{z}) &= a_1\hat{x}^2y^2 + a_3y^2\hat{z}^2 + 2b_2\hat{x}y^2\hat{z}, \\
                g_{2,3}(\hat{x}, y, \hat{z}) &= 2(a_1+b_2+b_3)\hat{x}^2y^2\hat{z} + 2(a_3+b_1+b_2)\hat{x}y^2\hat{z}^2 + 2b_3\hat{x}^2y\hat{z} + 2b_1\hat{x}y\hat{z}^2, \\
                g_{2,4}(\hat{x}, y, \hat{z}) &= 2(a_2+b_1+b_3)\hat{x}^2y\hat{z}^2 + a_2\hat{x}^2\hat{z}^2 + 2(c+b_1+b_2+b_3)\hat{x}^2y^2\hat{z}^2.
            \end{aligned}
        \end{equation}
        Since $a_1 + a_3 + b_2 = 1 - \varphi_{ij}^2 + 1 - \varphi_{jk}^2 + \varphi_{ik} + \varphi_{ij} \varphi_{jk} > 0$, we deduce $g_{2,2} > 0$.  By dividing the numerator and denominator of $T_1(x,y,z)$ by $\rho_{xz}$, we obtain
        \begin{equation*}
            \begin{aligned}
                T_1(x,y,z) = \frac{(\sum_{k=2}^{3} f_k(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-1}) \sqrt{(1 + 2\rho_{xz} \hat{x})(1+2y)}}{( \sum_{k=0}^{2} g_{1,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k}) \sqrt{ \sum_{k=2}^{4} g_{2,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-2}}}.
            \end{aligned}
        \end{equation*}
        By dividing the numerator and the denominator by $y^3$, we obtain
        \begin{equation*}
            \begin{aligned}
                T_1(x,y,z) &= \frac{\frac{(\sum_{k=2}^{3} f_k(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-1})}{y^2} \sqrt{(1 + 2\rho_{xz} \hat{x})(\frac{1}{y^2}+2\frac{1}{y})} }{\frac{( \sum_{k=0}^{2} g_{1,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k})}{y^2} \sqrt{ \frac{\sum_{k=2}^{4} g_{2,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-2}}{y^2}}}
                \\
