                & = \frac{\frac{(\sum_{k=2}^{3} f_k(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-1})}{y^2} ((1+\varphi_{ij})\rho_{xz}\hat{x} + \rho_{xz}\frac{\hat{x}}{y} + 1 + \frac{1}{y} - \sqrt{4\rho_{xz}\hat{x}\frac{1}{y}+2\rho_{xz}\frac{\hat{x}}{y^2}+2\frac{1}{y}+\frac{1}{y^2}}\,) }{(1 + \frac{\sum_{k=1}^{2} g_{1,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k}}{y^2} ) \sqrt{a_1 \hat{x}^2 + a_3 \hat{z}^2 + 2b_2 \hat{x} \hat{z} + \frac{\sum_{k=3}^{4} g_{2,k}(\hat{x}, y, \hat{z})\, \rho_{xz}^{k-2}}{y^2}}}.
