                g_{2,3}(x, \hat{y}, \hat{z}) &= 2(a_1+b_2+b_3)x^2\hat{y}^2\hat{z} + 2(a_2+b_1+b_3)x^2\hat{y}\hat{z}^2 + 2b_2x\hat{y}^2\hat{z} + 2b_1x\hat{y}\hat{z}^2, \\
