            \end{equation*}
            Hence, when $x \leq \delta_4$, $ T_1(x, y, z) \leq \frac{\epsilon}{2b_1}$ for some small enough $\epsilon > 0$ in this case.

            \item[(3)] If $ a_3 = 0 $ and $ b_1 = b_2 = 0 $, we have $f_1 \equiv 0, g_{2,0} \equiv 0$ and $g_{2,1} \equiv 0$. We divide both the numerator and the denominator of $T_1(x,y,z)$ by $x$, and obtain
            \begin{equation}
            	T_{1}(x,y,z) = \frac{((a_1 + b_2 + b_3)+  b_3 \frac{1}{y} + a_1 \frac{1}{z})x \sqrt{(1+2x)(\frac{1}{y^2} + 2\frac{1}{y})}}{(1+ \sum_{k=1}^2\frac{g_{1,k}(y,z)}{y^2}x^{k}) \sqrt{\frac{g_{2,2}(y,z)}{y^2 z^2}}}.
            \end{equation}
            By analogous analysis, we get that when $x \leq \delta_4$, $ T_1(x, y, z) \leq \epsilon$ for some small enough $\epsilon > 0$ in this case.
        \end{itemize}

        For $T_2(x,y,z)$, dividing both numerator and denominator by $y^3z$ gives
        \begin{equation*}
            T_2(x,y,z) = \frac{(b_2 x + \frac{f_2(y,z)}{y^2z}x^2) ((1+\varphi_{ij}) x + \frac{x}{y} + 1 + \frac{1}{y} - \sqrt{4\frac{x}{y} + 2\frac{x}{y^2} + 2\frac{1}{y} + \frac{1}{y^2}})}{(1+ \sum_{k=1}^2\frac{g_{1,k}(y,z)}{y^2}x^{k}) \sqrt{a_3 + \sum_{k=1}^2\frac{g_{2,k}(y,z)}{y^2 z^2}x^k}}.
        \end{equation*}
        We observe that the numerator of $T_2(x,y,z)$ remains arbitrarily small under the three previously discussed cases. In summary, we have
        \begin{equation*}
            \forall \epsilon > 0, \exists \delta_4 > 0, \forall \bar{y} \geq \bar{\delta}, \bar{z} \geq \bar{\delta}, \forall (x,y,z) \in B((0,\bar{y},\bar{z}), \delta_4), T_1(x,y,z) \leq \epsilon, T_2(x,y,z) \leq \epsilon.
        \end{equation*}

        \begin{itemize}
            \item $ y \to 0, x \to \bar{x} \geq \bar{\delta}, z \to \bar{z} \geq \bar{\delta} $
        \end{itemize}

        We express both the numerator and the denominator as polynomials in the variable $y$
        \begin{equation}
        \begin{aligned}
            f(x, y, z) &= \sum_{k=1}^{2} f_k(x, z)\, y^k, \quad
            g_1(x, y, z) = \sum_{k=0}^{2} g_{1,k}(x, z)\, y^k, \quad
            g_2(x, y, z) = \sum_{k=0}^{2} g_{2,k}(x, z)\, y^k,
        \end{aligned}
    \end{equation}
    where
    \begin{equation}
        \begin{aligned}
            &f_1(x, z) = b_3 x^2 z, \\
            &f_2(x, z) = (a_1 + b_2 + b_3)x^2 z + b_2 x z + a_1 x^2,
    	\end{aligned}
    \end{equation}
    and
    \begin{equation}
        \begin{aligned}
            &g_{1,0}(x, z) = x^2, \\
            &g_{1,1}(x, z) = 2(1 + \varphi_{ij})x^2 + 2\varphi_{ij}x, \\
            &g_{1,2}(x, z) = (3 + 4\varphi_{ij} + \varphi_{ij}^2)x^2 + 2(1 + \varphi_{ij})x + 1,
    	\end{aligned}
    \end{equation}
    and
    \begin{equation}
    	\begin{aligned}
    		g_{2,0}(x, z) &= a_2 x^2 z^2, \\
    		g_{2,1}(x, z) &= 2(a_2 + b_1 + b_3)x^2 z^2 + 2b_3 x^2 z + 2b_1 x z^2, \\
    		g_{2,2}(x, z) &= 2(a_1 + b_2 + b_3)x^2 z + 2(a_3 + b_1 + b_2)x z^2 + a_1 x^2 + a_3 z^2 \\
    		&\quad + 2b_2 x z + 2(c + b_1 + b_2 + b_3)x^2 z^2.
    	\end{aligned}
    \end{equation}
    Observing the coefficients, we note a symmetry with the case $ x \to 0, y \to \bar{y} \geq \bar{\delta}, z \to \bar{z} \geq \bar{\delta} $. Hence, applying the analogous method we have
    \begin{equation*}
        \forall \epsilon > 0, \exists \delta_5 > 0, \forall \bar{x} \geq \bar{\delta}, \forall \bar{z} \geq \bar{\delta}, \forall (x,y,z) \in B((\bar{x},0,\bar{z}), \delta_5), T_1(x,y,z) \leq \epsilon, T_2(x,y,z) \leq \epsilon.
    \end{equation*}

    \begin{itemize}
        \item  $ z \to 0, x \to \bar{x} \geq \bar{\delta}, z \to \bar{y} \geq \bar{\delta} $
    \end{itemize}
    We express both the numerator and the denominator as polynomials in the variable $z$
        \begin{equation}
        \begin{aligned}
            f(x, y, z) = \sum_{k=0}^{1} f_k(x, y)\, z^k, \quad
            g_1(x, y, z) = g_{1,0}(x, y), \quad
            g_2(x, y, z) = \sum_{k=0}^{2} g_{2,k}(x, y)\, z^k,
        \end{aligned}
    \end{equation}
    where
        \begin{equation}
            \begin{aligned}
                f_0(x, y) &= a_1 x^2 y^2, \\
                f_1(x, y) &= (a_1 + b_2 + b_3)x^2 y^2 + b_2 x y^2 + b_3 x^2 y, \quad
        	 \end{aligned}
     	\end{equation}	
     	and
     	\begin{equation}
     	        \begin{aligned}
                g_{1,0}(x, y) = (3 + 4\varphi_{ij} + \varphi_{ij}^2)x^2 y^2 + 2(1 + \varphi_{ij})(x^2 y + x y^2) + x^2 + y^2 + 2\varphi_{ij}xy,
       \end{aligned}
           \end{equation}
           and
       \begin{equation}
               \begin{aligned}
                g_{2,0}(x, y) &= a_1 x^2 y^2, \\
                g_{2,1}(x, y) &= 2(a_1 + b_2 + b_3)x^2 y^2 + 2b_2 x y^2 + 2b_3 x^2 y, \\
                g_{2,2}(x, y) &= 2(a_3 + b_1 + b_2)x y^2 + 2(a_2 + b_1 + b_3)x^2 y + a_3 y^2 + a_2 x^2\\
                 &\quad + 2b_1 x y + 2(c + b_1 + b_2 + b_3)x^2 y^2.
            \end{aligned}
        \end{equation}
        By dividing both the numerator and the denominator of $T_1(x,y,z)$ by $x^3 y^3$, we obtain
        \begin{equation*}
            T_1(x,y,z) = \frac{(a_1 + \frac{f_1(x,y)}{x^2 y^2 } z)\sqrt{(\frac{1}{x^2} + 2\frac{1}{x})(\frac{1}{y^2} + 2\frac{1}{y})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2 + 2(1+\varphi_{ij})(\frac{1}{x} + \frac{1}{y})+ \frac{1}{y^2} + \frac{1}{x^2} + 2\varphi_{ij} \frac{1}{x} \frac{1}{y}) \sqrt{a_1 + \frac{g_{2,1}(x,y)}{x^2 y^2}z + \frac{g_{2,2}(x,y)}{x^2 + y^2}z^2}}.
        \end{equation*}
        Dividing both the numerator and the denominator of $T_2(x,y,z)$ by $x^3 y^3$, we obtain
        \begin{equation*}
            T_2(x,y,z) = \frac{(b_2 x + \frac{f_2(x,y)}{x^2 y^2}x^2) (1+\varphi_{ij}+ \frac{1}{y} + \frac{1}{x} + \frac{1}{xy} - \sqrt{4\frac{1}{xy} + 2\frac{1}{xy^2} + 2\frac{1}{yx^2} + \frac{1}{x^2y^2}})}{(1+ \sum_{k=1}^2\frac{g_{1,k}(x,y)}{x^2}x^{k}) \sqrt{a_1 + \sum_{k=1}^2\frac{g_{2,k}(x,y)}{x^2 y^2}x^k}}.
        \end{equation*}
        Analyzing these coefficients, we obtain the following cases.

       \noindent (1) If $ a_1 \ne 0 $, then for any $\epsilon > 0$, there exits a constant $\delta_6 > 0$ such that if $(x,y,z) \in B((\bar{x},\bar{y}, 0), \delta_6)$ for any $\bar{y} \geq \bar{\delta}, \bar{z} \geq \bar{\delta}$, it follows that
       \begin{equation*}
       \begin{aligned}
              		T_1(x,y,z) &\leq  \frac{a_1\sqrt{(\frac{1}{\bar{x}^2} + 2\frac{1}{\bar{x}})(\frac{1}{\bar{y}^2} + 2\frac{1}{\bar{y}})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2 + 2(1+\varphi_{ij})(\frac{1}{\bar{x}} + \frac{1}{\bar{y}})+ \frac{1}{\bar{y}^2} + \frac{1}{\bar{x}^2} + 2\varphi_{ij} \frac{1}{\bar{x}} \frac{1}{\bar{y}}) \sqrt{a_1}} + \epsilon
              		\\
              		&\leq  \frac{a_1\sqrt{(\frac{1}{\bar{x}^2} + 2\frac{1}{\bar{x}})(\frac{1}{\bar{y}^2} + 2\frac{1}{\bar{y}})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{a_1} } + \epsilon
              		\\
              		&\leq  \frac{a_1\sqrt{(\frac{1}{\bar{\delta}^2} + 2\frac{1}{\bar{\delta}})(\frac{1}{\bar{\delta}^2} + 2\frac{1}{\bar{\delta}})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{a_1} } + \epsilon,
       \end{aligned}
       \end{equation*}
       and
       \begin{equation*}
            T_2(x,y,z) \leq \frac{a_1 (1+ \varphi_{ij} + \frac{2}{\bar{\delta}} + \frac{1}{\bar{\delta}^2} + \sqrt{4\frac{1}{\bar{\delta}^2} + 4\frac{1}{\bar{\delta}^3} + \frac{1}{\bar{\delta}^4}})}{(3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{a_1} } + \epsilon.
       \end{equation*}
       Hence, let $$C =  \max\{\frac{a_1\sqrt{(\frac{1}{\bar{\delta}^2} + 2\frac{1}{\bar{\delta}})(\frac{1}{\bar{\delta}^2} + 2\frac{1}{\bar{\delta}})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{a_1} } + 1, \frac{a_1 (1+ \varphi_{ij} + \frac{2}{\bar{\delta}} + \frac{1}{\bar{\delta}^2} + \sqrt{4\frac{1}{\bar{\delta}^2} + 4\frac{1}{\bar{\delta}^3} + \frac{1}{\bar{\delta}^4}})}{(3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{a_1} } + 1\},$$
        the result in this case follows.

    	(2) If $ a_1 = 0 $, we have $f_0 \equiv 0$ and $g_{2,0} \equiv 0$ and by (\ref{Equation2_a_b_c_definition}) we get that $ b_2 = b_3 $. When $ b_2 \ne 0 $, by dividing both the numerator and the denominator of $T_1(x,y,z)$ by $z^{1/2}$, we obtain
    	\begin{equation*}
    	T_1(x,y,z) = \frac{(a_1 + b_2 + b_3 + b_2 \frac{1}{x} + b_3 \frac{1}{y}) z^{\frac{1}{2}})\sqrt{(\frac{1}{x^2} + 2\frac{1}{x})(\frac{1}{y^2} + 2\frac{1}{y})}}{(3 + 4\varphi_{ij} + \varphi_{ij}^2 + 2(1+\varphi_{ij})(\frac{1}{x} + \frac{1}{y})+ \frac{1}{y^2} + \frac{1}{x^2} + 2\varphi_{ij} \frac{1}{x} \frac{1}{y}) \sqrt{ \frac{g_{2,1}(x,y)}{x^2 y^2} + \frac{g_{2,2}(x,y)}{x^2 + y^2}z^2}},
    	\end{equation*}
    	 then for a small enough $\epsilon > 0$ there exists $\delta_{6} > 0$, if $(x,y,z) \in B((\bar{x},\bar{y}, 0), \delta_6)$, the denominator satisfies
         \begin{equation*}
         \begin{aligned}
                      &{(3 + 4\varphi_{ij} + \varphi_{ij}^2 + 2(1+\varphi_{ij})(\frac{1}{x} + \frac{1}{y})+ \frac{1}{y^2} + \frac{1}{x^2} + 2\varphi_{ij} \frac{1}{x} \frac{1}{y}) \sqrt{ \frac{g_{2,1}(x,y)}{x^2 y^2} + \frac{g_{2,2}(x,y)}{x^2 + y^2}z^2}} \\
                      &
                      \geq (3 + 4\varphi_{ij} + \varphi_{ij}^2)\sqrt{4b_2^2},
         \end{aligned}
         \end{equation*}
         while the numerator satisfies
         \begin{equation*}
             {(a_1 + b_2 + b_3 + b_2 \frac{1}{x} + b_3 \frac{1}{y}) z^{\frac{1}{2}}\sqrt{(\frac{1}{x^2} + 2\frac{1}{x})(\frac{1}{y^2} + 2\frac{1}{y})}} \leq \epsilon.
         \end{equation*}
         An analogous argument applies to the numerator of $T_2(x,y,z)$.
         Hence, there exists $\delta_{7} > 0$ such that if $(x,y,z) \in B((\bar{x},\bar{y}, 0), \delta_7)$, we have $ T_1(x, y, z) \leq \epsilon, T_2(x,y,z) \leq \epsilon$ for some small enough $\epsilon > 0$.

    	(3) If $ a_1 = 0 $ and $ b_2 = b_3 = 0 $, we have that $f(x,y,z) \equiv 0$ which implies that $T_1(x,y,z) \equiv 0$ and $T_2(x,y,z) \equiv 0$. Hence the result in this case follows.

    	Let $\delta = \min\{\delta_0, \delta_1, \delta_2, \delta_3, \delta_4, \delta_5, \delta_6\}$.
    	 Summarizing the preceding cases, we conclude that there exists $C_1(\varphi_{ij}, \varphi_{ik}, \varphi_{jk})>0$ and $C_2(\varphi_{ij}, \varphi_{ik}, \varphi_{jk})>0$ such that if $\min\{x,y,z\} \leq \delta$, then $T_1(x,y,z) < C_1(\varphi_{ij}, \varphi_{ik}, \varphi_{jk})$ and $T_2(x,y,z) < C_2(\varphi_{ij}, \varphi_{ik}, \varphi_{jk})$.


    Based on all the discussions of $\Omega_1, \Omega_2$, we conclude that $T_1(x, y, z)$ and $T_2(x, y, z)$ are uniformly bounded above by positive constants depending only on $\Phi$, which are denoted by
    \begin{align*}
        M_1=M_1(\Phi) &= \max_{\triangle_{ijk} \in F} \big\{C_1(\varphi_{ij}, \varphi_{ik}, \varphi_{jk}),  \frac{5}{128 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }\big\}, \\
        M_2=M_2(\Phi) &=  \max_{\triangle_{ijk} \in F} \big\{C_2(\varphi_{ij}, \varphi_{ik}, \varphi_{jk}),  \frac{5}{64 a^{14}(1+\bar{\varphi})^2\sqrt{1+\bar{\varphi}} }\big\}.
    \end{align*}
    By (\ref{AB-equality}) and Corollary \ref{Corollary:Glickenstein-corollary} we have
    $$
    A_i = \sum_{v_j \sim v_i} B_{ij}(\cosh l_{ij} - 1), \quad
    B_{ij} = \frac{\partial \theta_i^{jk}}{\partial u_j} + \frac{\partial \theta_i^{jl}}{\partial u_j},
    $$
    where $\theta_i^{jk}$ and $\theta_i^{jl}$ are inner angles in triangles $\triangle_{ijk}$ and $\triangle_{ijl}$ respectively. Let $d = \max_{v_i \in V} \{\deg(v_i)\}$, we obtain
    \begin{align*}
        |B_{ij}| &\le \left| \frac{\partial \theta_{i}^{jk}}{\partial u_{j}} \right| + \left| \frac{\partial \theta_{i}^{jl}}{\partial u_{j}} \right| \le M_1 + M_1 = 2 M_1, \\
        |A_i| &= \left| \sum_{v_j \sim v_i} (\frac{\partial \theta_{j}^{ik}}{\partial u_{i}} + \frac{\partial \theta_{j}^{il}}{\partial u_{i}})(\cosh l_{ij}-1) \right| \le \sum_{v_j \sim v_i} (M_2 + M_2) = 2 d_i M_2 \le 2 d M_2.
    \end{align*}
    Thus, there exist positive constants $ C_1(\Phi) = 2d M_2 $ and $ C_2(\Phi) = 2 M_1 $, depending only on $\Phi$ and the combinatorial structure of the triangulation $\mathcal{T}=(V,E,F)$, such that the inequalities $0< A_i \leq C_1(\Phi) $ and $0< B_{ij} \leq C_2(\Phi) $ hold for all vertices $ v_i, v_j $ and any circle packing metric $ r \in \mathbb{R}_{>0}^N $. This complete the proof of Theorem \ref{Theorem2_uniform_upper_bound}. \hfill $\square$
\end{proof}


\section{Long time existence of the combinatorial $p$-th Calabi flows}

In this section, we give new proofs of the long time existences of solutions to the combinatorial Calabi flows established by Ge-Xu \cite{Ge2016}, Ge-Hua \cite{Ge2018} and the combinatorial $p$-th Calabi flows established by Lin-Zhang \cite{Lin2019} in $\mathbb{H}^2$, and prove Theorem \ref{long time existence}, based on our main results on two improved estimates for the discrete Laplace operator, namely Theorem \ref{main result1} and Theorem \ref{main result2}.

\begin{theorem}\label{longtime existence}
    For any initial circle packing metric $r(0) \in \mathbb{R}_{>0}^{N}$, the solutions to both the combinatorial Calabi flows (\ref{Equation:rewritten_calabi_equation}) and the combinatorial $p$-th Calabi flow (\ref{Equation:combinatorial_p_th_calabi_flow}) in $\mathbb{H}^{2}$ exist for all time $t \in [0,+\infty)$.
\end{theorem}

Before proving the theorem, we first present an important lemma established by Zhang and Zheng \cite{Zhang24} (see Lemma 4.1 in \cite{Zhang24}).
\begin{lemma}\label{lemma}
    Let $ \Delta v_{i} v_{j} v_{k} $ be a hyperbolic triangle which is patterned by three circles with the fixed weight $ \Phi_{i j}, \Phi_{i k}, \Phi_{j k} \in[0, \pi) $ satisfying $ (\star) $. Let $ \theta_{i}^{j k} $ be the inner angle at $ v_{i} $. Then $ \forall \epsilon>0 $, there exists a number $ l $ so that when $ r_{i}>l $, the inner angle $ \theta_{i}^{j k} $ is smaller than $ \epsilon $.
\end{lemma}

\textbf{Proof of Theorem \ref{longtime existence}}  Note that the combinatorial Calabi flow (\ref{Equation:rewritten_calabi_equation}) is precisely the combinatorial $p$-th Calabi flow (\ref{Equation:combinatorial_p_th_calabi_flow}) in the case of $p=2$, hence we only need to consider the combinatorial $p$-th Calabi flow (\ref{Equation:combinatorial_p_th_calabi_flow}).  We begin by showing that the solution to the $p$-th Calabi flow (\ref{Equation:combinatorial_p_th_calabi_flow}) admits a positive lower bound on any finite time interval $[0,T)$ for $0 \leq T < +\infty$.

    Let $ d_{i} $ denote the degree at vertex $ v_{i} $, which is the number of edges adjacent to $ v_{i} $. Set $ d=\max \left\{d_{1}, \ldots, d_{N}\right\} $, by the definition of the combinatorial Gauss curvature
        \begin{equation*}
    K_i = 2\pi - \sum_{\triangle_{ijk} \in F} \theta_{i}^{jk},
\end{equation*}
 then we have $ (2-d) \pi<K_{i}<2 \pi $, hence
    \begin{equation*}
        \left|K_{j}-K_{i}\right|<d \pi, \forall v_j \sim v_i.
    \end{equation*}
    By (\ref{Equation:combinatorial_p_th_calabi_flow}) and Theorem \ref{main result2}, we obtain
    \begin{equation*}
        \begin{aligned}
            |\frac{d u_i}{dt}| & = |\sum_{v_j \sim v_i} B_{ij}|K_j-K_i|^{p-2}(K_j-K_i) +A_i K_i|\\
                               & \leq \sum_{v_j \sim v_i} B_{ij}|K_j-K_i|^{p-1} + A_i |K_i| \\
                               & \leq d C_2 (d\pi)^{p-1} + C_1(d+2)\pi  \triangleq C,
        \end{aligned}
    \end{equation*}
    where $C$ is a positive constant depending only on the triangulation $\mathcal{T}$. Thus, we have
    \begin{equation*}
        |u_i(t)| \leq |u_i(0)| + C t, \forall i=1, 2, \ldots, N.
    \end{equation*}
    This implies that \(u_i(t)\) is bounded above over any finite time interval, and since \(u_i=\ln \tanh \frac{r_i(t)}{2}\), it follows that \(r_i(t)\) is bounded below in finite time as follows
    \begin{equation*}
        0< \tanh (\frac{r_i(0)}{2}) e^{-Ct}\leq \tanh (\frac{r_i(t)}{2}) \leq \tanh (\frac{r_i(0)}{2}) e^{Ct}.
    \end{equation*}
    Thus we can get an estimate of the lower bound of $r_i(t)$
    \begin{equation*}
        r_{i}(t) \geq \frac{1}{2}\ln \frac{1+\tanh (\frac{r_i(0)}{2}) e^{-Ct}}{1-\tanh (\frac{r_i(0)}{2}) e^{-Ct}} > 0.
    \end{equation*}
    Next, we prove that the solution to the flow equation admits a uniform upper bound. For a vertex \(i\), by Lemma \ref{lemma} one may choose a sufficiently large positive constant \(l\) such that \(r_i>l\) and the interior angle \(\theta_i\) is less than \(\frac{\pi}{2d_i}\), where \(d_i\) denotes the degree of vertex \(i\). Hence, $\pi <K_i< 2\pi$, which leads to \(K_j-K_i<\pi\) for any \(v_j \sim v_i\). Note that if \(a\le b\) then \(|a|^{p-2}a\le|b|^{p-2}b\), which yields

    \begin{equation*}
        \begin{aligned}
        \frac{1}{\sinh r_i}\frac{dr_i}{dt} &= \sum_{v_j \sim v_i}B_{ij}\bigl|K_j-K_i\bigr|^{p-2}(K_j-K_i)-A_iK_i \\
        &\le \sum_{v_j \sim v_i}B_{ij}\pi^{p-1}-A_i\pi \\
        &=\pi^{p-1}\left(\sum_{v_j \sim v_i}B_{ij}-\frac{1}{\pi^{p-2}}A_i\right) \\
        &= \pi^{p-1}\left(\sum_{v_j \sim v_i}B_{ij}(1-\frac{\cosh l_{ij}-1}{\pi^{p-2}})\right),
        \end{aligned}
    \end{equation*}
    where the last equality is due to Corollary \ref{Corollary:Glickenstein-corollary}.
    Noting that $$ \cosh l_{ij} = \cosh r_i \cosh r_j + \cos \Phi_{ij} \sinh r_i \sinh r_j $$ and the condition \(0 \leq \Phi_{ij} < \pi\), it follows that
    \begin{equation*}
        \exists R > 0, \text{ such that } r_i > R, \text{ then } 1-\frac{\cosh l_{ij}-1}{\pi^{p-2}} < 0,
    \end{equation*}
    Since \(B_{ij} \geq 0\), when $r_i > \max\{R,l\}$ we have
    \begin{equation*}
        \frac{1}{\sinh r_i}\frac{dr_i}{dt} \leq \pi^{p-1}\left(\sum_{v_j \sim v_i}B_{ij}(1-\frac{\cosh l_{ij}-1}{\pi^{p-2}})\right) \leq 0,
    \end{equation*}
    hence we obtain \(r_i(t) \leq \max\{R,l,r_{i}(0)\}\). \par
    In summary, we prove both the lower and upper boundeness of solutions to the combinatorial $p$-th Calabi flow (\ref{Equation:combinatorial_p_th_calabi_flow}) in any finite time, which implies that the long time existence of
solutions to the flow (\ref{Equation:combinatorial_p_th_calabi_flow}). This completes the proof. \hfill $\square$


\section{Appendix}
\subsection{A proof of Lemma \ref{Lemma:Glickenstein-lemma}}

\begin{proof}
    We now prove the second equality. To establish the first equality in the equality (\ref{Equation:Glickenstein-lemma}), it suffices to show that
    \begin{equation*}
        \frac{\partial \theta_{i}^{jk}}{\partial u_{j}} = \frac{\partial \theta_{j}^{ik}}{\partial u_{i}}, \quad \frac{\partial \theta_{i}^{jk}}{\partial u_{k}} = \frac{\partial \theta_{k}^{ij}}{\partial u_{i}},
    \end{equation*}
    which follows directly from Lemma A1 in Chow-Luo \cite{BennettChow2003}. However, we also derive these relations in the subsequent proof and discuss them in Remark \ref{Remark:Glickenstein-lemma}.
    For convenience, we adopt the following notations: $\theta_{i} = \theta_{i}^{jk},\ C_{ij} = \cosh l_{ij},\ S_{ij} = \cosh l_{ij},\ C_{i} = \cosh r_{i},\ S_{i} = \sinh r_{i},\ A_{ijk} = \sinh l_{ij}\sinh l_{ik}\sin \theta_{i}^{jk}.$ According to the hyperbolic cosine law, we have
    \begin{equation*}
    S_{ij} S_{ik}\cos \theta_{i} = C_{ij} C_{ik} - C_{jk}.
    \end{equation*}
    Hence, we compute the partial derivatives of both sides of the above equality with respect to $l_{ij}$, $l_{ik}$, and $l_{jk}$ as follows
    \begin{equation*}
        \begin{gathered}
            -\frac{\partial \theta_i}{\partial l_{ij}} S_{ij}S_{ik}\sin \theta_i + C_{ij}S_{ik} \cos \theta_i = S_{ij}C_{ik},
            \\
            -\frac{\partial \theta_i}{\partial l_{ik}} S_{ij}S_{ik}\sin \theta_i + S_{ij}C_{ik} \cos \theta_i = C_{ij}S_{ik},
            \\
            -\frac{\partial \theta_i}{\partial l_{jk}}S_{ij}S_{ik} \sin \theta_i = -S_{jk}.
        \end{gathered}
    \end{equation*}
    A direct computation gives
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_1}
        \begin{gathered}
            \frac{\partial \theta_i}{\partial l_{ij}} = - \frac{S_{ij}C_{ik}-C_{ij}S_{ik}\cos \theta_i}{A_{ijk}} = -\frac{S_{ij}C_{ik} - \frac{C_{ij}^2C_{ik}-C_{ij}C_{jk}}{S_{ij}}}{A_{ijk}}  = -\frac{S_{jk}\cos \theta_j}{A_{ijk}},\\
            \frac{\partial \theta_i}{\partial l_{ik}} = - \frac{C_{ij}S_{ik}-S_{ij}C_{ik}\cos \theta_i}{A_{ijk}} = - \frac{C_{ij}S_{ik} - \frac{C_{ij}C_{ik}^2 - C_{ik}C_{jk}}{S_{ik}}}{A_{ijk}} = -\frac{S_{jk}\cos \theta_k}{A_{ijk}}, \\
            \frac{\partial \theta_i}{\partial l_{jk}} = \frac{S_{jk}}{A_{ijk}}.
        \end{gathered}
    \end{equation}

    Next, recall the formula $C_{ij} = C_i C_j + \cos \Phi_{ij} S_i S_j$, and we obtain
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_2}
        \begin{aligned}
            \frac{\partial l_{ij}}{\partial u_i} = S_{ij} \frac{\partial l_{ij}}{\partial r_i}
            &= \frac{\partial C_i}{\partial r_i} C_j + \cos \Phi_{ij} \frac{\partial S_i}{\partial r_i} S_j \\
            &= S_i C_j + \cos \Phi_{ij} C_i S_j, \\
            \frac{\partial l_{ik}}{\partial u_i} = S_{ik} \frac{\partial l_{ik}}{\partial r_i}
            &= \frac{\partial C_i}{\partial r_i} C_k + \cos \Phi_{ik} \frac{\partial S_i}{\partial r_i} S_k \\
            &= S_i C_k + \cos \Phi_{ik} C_i S_k, \\
            \frac{\partial l_{jk}}{\partial u_i} = S_{jk} \frac{\partial l_{jk}}{\partial r_i}
            &= 0.
        \end{aligned}
    \end{equation}

    Based on the chain rule and the results we have already computed in (\ref{Equation:Glickenstein-lemma-proof_1}) and (\ref{Equation:Glickenstein-lemma-proof_2}), we present the following expression for $A_{ijk} \frac{\partial \theta_i}{\partial u_i}$ as follows:
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_3}
        \begin{aligned}
            A_{ijk}\frac{\partial \theta_i}{\partial u_i} &=
            A_{ijk} S_i \frac{\partial \theta_i}{\partial r_i}
            = A_{ijk} S_i (\frac{\partial \theta_i}{\partial l_{ij}} \frac{\partial l_{ij}}{\partial r_i} + \frac{\partial \theta_i}{\partial l_{ik}} \frac{\partial l_{ik}}{\partial r_i})
            \\
            &=A_{ijk}S_i(-\frac{S_{jk} \cos \theta_j}{A_{ijk}}\frac{S_iC_j + \cos \Phi_{ij} C_i S_j}{S_{ij}} - \frac{-S_{jk}\cos \theta_k}{A_{ijk}} \frac{S_iC_k + \cos \Phi_{ik} C_i S_k}{S_{ik}})
            \\
            &= -\frac{S_{jk} \cos \theta_j}{S_{ij}}(S_i^2 C_j + \cos \Phi_{ij} C_i S_i S_j) - \frac{S_{jk} \cos \theta_k}{S_{ik}} (S_i^2 C_k + \cos \Phi_{ik} C_i S_i S_k)
            \\
            &=  -\frac{S_{jk} \cos \theta_j}{S_{ij}}(C_i C_{ij} - C_j) - \frac{S_{jk} \cos \theta_k}{S_{ik}} (C_i C_{ik} - C_k)
            \\
            &= - \frac{S_{ik}^2(S_{ij}S_{jk}\cos \theta_j)(C_i C_{ij} - C_j) + S_{ij}^2(S_{ik}S_{jk}\cos \theta_k)(C_iC_{ik}-C_k)}{(S_{ij}S_{ik})^2}
            \\
            &= - \frac{S_{ik}^2(C_{ij}C_{jk} - C_{ik})(C_iC_{ij} - C_j) + S_{ij}^2(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k)}{(S_{ij}S_{ik})^2}.
        \end{aligned}
    \end{equation}
    Similarly, we compute the expression for $A_{ijk}\,\frac{\partial \theta_i}{\partial u_j}$ as follows:
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_4}
        \begin{aligned}
            A_{ijk}\frac{\partial \theta_i}{\partial u_j} &= A_{ijk}S_j \frac{\partial \theta_i}{\partial r_j}
            = A_{ijk}S_j(\frac{\partial \theta_i}{\partial l_{ij}} \frac{\partial l_{ij}}{\partial r_j} + \frac{\partial \theta_i}{\partial l_{jk}} \frac{\partial l_{jk}}{\partial r_j})
            \\
            &= A_{ijk} S_j (-\frac{S_{jk}\cos \theta_j}{A_{ijk}}\frac{C_i S_j + \cos \Phi_{ij} S_i C_j}{S_{ij}} + \frac{S_{jk}}{A_{ijk}}\frac{S_jC_k + \cos \Phi_{jk} C_j S_k}{S_{jk}})
            \\
            &= - \frac{S_{ij}S_{jk}\cos \theta_j(C_iS_j^2 + \cos \Phi_{ij}S_iS_jC_j)}{S_{ij}^2} + S_j^2C_k + \cos \Phi_{jk} S_j S_k C_j
            \\
            &= -\frac{(C_{ij}C_{jk} - C_{ik})(C_j C_{ij} - C_i)}{S_{ij}^2} + C_j C_{jk} - C_k.
        \end{aligned}
    \end{equation}
    Then we compute the expression for $A_{ijk}\,\frac{\partial \theta_i}{\partial u_k}$ as follows:
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_5}
        \begin{aligned}
            A_{ijk}\frac{\partial \theta_i}{\partial u_k} &= A_{ijk} S_k \frac{\partial \theta_i}{\partial r_k}
            \\
            &= A_{ijk}S_k(\frac{\partial \theta_i}{\partial l_{ik}} \frac{\partial l_{ik}}{\partial r_k} + \frac{\partial \theta_i}{\partial l_{jk}} \frac{\partial l_{jk}}{\partial r_k})
            \\
            &= A_{ijk}S_k(-\frac{S_{jk}\cos \theta_k}{A_{ijk}}\frac{C_iS_k+\cos \Phi_{ik}S_iC_k}{S_{ik}}+\frac{S_{jk}}{A_{ijk}}\frac{C_jS_k+\cos \Phi_{jk}S_jC_k}{S_{jk}})
            \\
            &= -\frac{S_{ik}S_{jk}\cos \theta_k(C_iS_k^2 + \cos \Phi_{ik}S_iS_kC_k)}{S_{ik}^2}+S_k^2C_j + \cos \Phi_{jk}S_jS_kC_k
            \\
            &= -\frac{(C_{ik}C_{jk}-C_{ij})(C_kC_{ik}-C_i)}{S_{ik}^2} + C_kC_{jk}-C_j.
        \end{aligned}
    \end{equation}
    Next, based on the equalities (\ref{Equation:Glickenstein-lemma-proof_4}) and (\ref{Equation:Glickenstein-lemma-proof_5}), we provide the explicit expression for the right-hand side of the equality (\ref{Equation:Glickenstein-lemma}).
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_6}
        \begin{aligned}
            A_{ijk} \frac{\partial \theta_i}{\partial u_j} C_{ij} &= (-\frac{(C_{ij}C_{jk} - C_{ik})(C_j C_{ij} - C_i)}{S_{ij}^2} + C_j C_{jk} - C_k)C_{ij}
            \\
            &= -\frac{(C_{ij}C_{jk} - C_{ik})(-C_i C_{ij} + C_j + C_j S_{ij}^2)}{S_{ij}^2} + C_j C_{jk} C_{ij} - C_k C_{ij}
            \\
            & = \frac{(C_{ij}C_{jk} - C_{ik})(C_i C_{ij} - C_j )}{S_{ij}^2} - C_{ij} C_{jk} C_j + C_{ik} C_j+ C_j C_{jk} C_{ij} - C_k C_{ij}
            \\
            &= \frac{(C_{ij}C_{jk} - C_{ik})(C_i C_{ij} - C_j )}{S_{ij}^2}+ C_{ik} C_j - C_k C_{ij},
        \end{aligned}
    \end{equation}
    \begin{equation}
        \label{Equation:Glickenstein-lemma-proof_7}
        \begin{aligned}
            A_{ijk} \frac{\partial \theta_i}{\partial u_k} C_{ik} &= (-\frac{(C_{ik}C_{jk} - C_{ij})(C_k C_{ik} - C_i)}{S_{ik}^2} + C_k C_{jk} - C_j)(C_{ik})
            \\
            &= -\frac{(C_{ik}C_{jk} - C_{ij})(- C_iC_{ik} + C_k + C_k S_{ik}^2 )}{S_{ik}^2} + C_k C_{jk} C_{ik} - C_j C_{ik}
            \\
            &=  \frac{(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k )}{S_{ik}^2} - C_{ik} C_{jk} C_k + C_{ij}C_k + C_k C_{jk} C_{ik} - C_{j} C_{ik}
            \\
            &= \frac{(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k )}{S_{ik}^2}+ C_{ij}C_k- C_{j} C_{ik},
        \end{aligned}
    \end{equation}
    Finally, combining the equalities (\ref{Equation:Glickenstein-lemma-proof_3}), (\ref{Equation:Glickenstein-lemma-proof_6}) and (\ref{Equation:Glickenstein-lemma-proof_7}), we have
    \begin{equation*}
        \begin{aligned}
            &\quad A_{ijk}(\frac{\partial \theta_i}{\partial u_k}C_{ik} + \frac{\partial \theta_i}{\partial u_j}C_{ij} + \frac{\partial \theta_i}{\partial u_i})
            \\
            &=\frac{(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k )}{S_{ik}^2}+ C_{ij}C_k- C_{j} C_{ik}+\frac{(C_{ij}C_{jk} - C_{ik})(C_i C_{ij} - C_j )}{S_{ij}^2}+ C_{ik} C_j - C_k C_{ij}
            \\
            &\quad - \frac{S_{ik}^2(C_{ij}C_{jk} - C_{ik})(C_iC_{ij} - C_j) + S_{ij}^2(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k)}{(S_{ij}S_{ik})^2}
            \\
            &= \frac{(1-1)S_{ik}^2(C_{ij}C_{jk} - C_{ik})(C_iC_{ij} - C_j) + (1-1)S_{ij}^2(C_{ik}C_{jk} - C_{ij})(C_iC_{ik} - C_k)}{(S_{ij}S_{ik})^2}
            \\
            &= 0,
        \end{aligned}
    \end{equation*}
    which implies that $\frac{\partial \theta_i}{\partial u_k}C_{ik} + \frac{\partial \theta_i}{\partial u_j}C_{ij} + \frac{\partial \theta_i}{\partial u_i}=0$.
    This completes the proof of Lemma \ref{Lemma:Glickenstein-lemma}. \hfill $\square$
\end{proof}



