\title{A General Simulation-Based Optimisation Framework for Multipoint Constant-Stress Accelerated Life Tests}
\author{Owen McGrath\footnote{Corresponding author. University of Limerick, Ireland; owen.mcgrath@ul.ie}  \hspace{3cm}
