\title{Adaptive Vector-Valued Splines for the Resolution of Inverse Problems}

\author[1]{\fnm{Vincent} \sur{Guillemet}}\email{vincent.guillemet@epfl.ch}

\author*[1]{\fnm{Michael} \sur{Unser}}\email{michael.unser@epfl}


\affil[1]{\orgdiv{Biomedical Imaging Group}, \orgaddress{\street{Station 17}, \orgname{EPFL}, \city{Lausanne}, \postcode{CH-1015}, \country{Switzerland}}}



\abstract{
 We introduce a general framework for the reconstruction of vector-valued functions from finite and possibly noisy data, acquired through a known measurement operator. The reconstruction is done by the minimization of a loss functional formed as the sum of a convex data fidelity functional and a total-variation-based regularizer involving a suitable matrix $\Ls$ of differential operators. Here, the total variation is a norm on the space of vector measures. These are split into two categories: inner, and outer norms. The minimization is performed over an infinite-dimensional Banach search space. When the measurement operator is $\text{weak}^{\star}$-continuous over the search space, our main result is that the solution set of the loss functional is the closed convex hull of adaptive $\Ls$-splines, with fewer knots than the number of measurements. We reveal the effect of the total-variation norms on the structure of the solutions and show that inner norms yield sparser solutions. We also provide an explicit description of the class of admissible measurement operators.}



\vspace{1em}
\keywords{vector splines, total-variation norm,  representer
 theorems, optimization on measure spaces}


\pacs[MSC Classification]{41A15, 47A52, 46G10, 47N10, 93B28, 46N10}

