\subsection{Proofs of Section 3.2}
\label{app:3.2}
Observe that the action of an MDO $\Ls$ is the same as the convolution with $\Ls\{\bb{I}\delta\}$. For example, in one dimension, the action of the differential operator $\D$ is the same as the convolution with $\delta^{'}$. In the sequel, we use this fact and convolve with $\Ls$ instead of $\Ls\{\bb{I}\delta\}$, with a slight abuse of notation. We also make use, without any explicit statement, of the properties showed in Appendix \ref{app:B} of the convolution between matrix-valued distributions. We notate the convolution (composition) of $D$ MDO as $\circledast_{d=1}^D\Ls_d$

In Proposition \ref{prop:Greens}, we use the Laplace formula for inverting a matrix to construct the Green's matrix of an MDO. This construction, different from the one of the Smith normal form given in the core of this paper, will be useful later on. We denote by $\Ls_{r,c}$ the MDO found by removing the $r$th row and the $c$th column of $\Ls$.
\begin{ Proposition }
\label{prop:Greens}

    Let $\mathbf{com}(\Ls)$ be such that $[\mathbf{com}(\Ls)]_{r,c}=(-1)^{r+c}\mathrm{det}(\Ls_{r,c})$. Then, the following equality holds:
    \begin{equation}
    \label{eq:A.3.83}
    \Ls\ast\mathbf{com}(\Ls)^{\intercal}=\bb{I}\mathrm{det}(\Ls).
    \end{equation}
    If, in addition, $\mathrm{det}(\Ls)\neq0$, then it holds that
    \begin{equation}
    \label{eq:A.3.84}
    \Ls\ast\mathbf{com}(\Ls)^{\intercal}\ast\bb{I}g_{\mathrm{det}(\Ls)}=\bb{I}\delta,
    \end{equation}
    with $g_{\mathrm{det}(\Ls)}$ being the unique causal Green's function of $\mathrm{det}(\Ls)$. It follows that $\bb{G}_{\Ls}=\mathbf{com}(\Ls)^{\intercal}\ast \bb{I}g_{\mathrm{det}(\Ls)}$ is the causal Green's matrix of $\Ls$.
\end{ Proposition }
\begin{proof}[\textbf{Proof  of Proposition \ref{prop:Greens}}]
    For matrices (here $D\times D$) with coefficients in a commutative ring (here, the ring of ordinary differential operators), it is known that the equality $\Ls\ast\mathbf{com}(\Ls)^{\intercal}=\bb{I}\mathrm{det}(\Ls)$ always holds. This proves \eqref{eq:A.3.83}. Concerning \eqref{eq:A.3.84}, we calculate that 
    \begin{equation}
        \Ls\ast(\mathbf{com}(\Ls)^{\intercal}\ast\bb{I}g_{\mathrm{det}(\Ls)})=(\Ls\ast\mathbf{com}(\Ls)^{\intercal})\ast\bb{I}g_{\mathrm{det}(\Ls)}=\bb{I}\mathrm{det}(\Ls)\ast\bb{I}g_{\mathrm{det}(\Ls)}=\bb{I}\delta,
    \end{equation}
where we used the associativity of the convolution of matrix-valued distributions (Proposition \ref{prop:10}).
\end{proof}
\begin{proof}[\textbf{Proof of Theorem \ref{prop:greens2}}]
By inserting the factorization $\bb{U}\ast\bb{D}\ast\bb{V}$ of $\Ls$, we get
\begin{align}
\Ls\ast\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta&=\bb{U}\ast\bb{D}\ast\bb{V}\ast\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta\\
&=\bb{U}\ast\bb{D}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta=\bb{U}\ast\bb{U}^{-1}\ast\bb{I}\delta=\bb{I}\delta.
\end{align}
Hence, $\bb{G}_{\Ls}=\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta$ is a Green's matrix of $\Ls$. Since the convolution kernels $g_{\D_d}$ defining $\bb{D}^{-1}$ are all causal by definition, the distribution $\bb{G}_{\Ls}$ is also causal.

To show by contradiction that $\bb{G}_{\Ls}$ is the unique causal Green's matrix, we assume the existence of another causal Green's function $\bb{G}_{\Ls}'$. Consequently, $\Ls\ast(\bb{G}_{\Ls}-\bb{G}_{\Ls}')=\bm{0}$ and $[\bb{G}_{\Ls}-\bb{G}_{\Ls}']_{\cdot,d}\in\mathcal{N}_{\Ls}.$ From Proposition \ref{prop:kernel}, we find that $[\bb{G}_{\Ls}-\bb{G}_{\Ls}']_{\cdot,d}\in\bb{V}^{-1}\mathcal{N}_{\bb{D}}$. Since all functions in$\bb{V}^{-1}\mathcal{N}_{\bb{D}}$ are analytic and, by causality, $[\bb{G}_{\Ls}-\bb{G}_{\Ls}']_{\cdot,d}$ is 0 on $\R^-$, the only possibility is that $(\bb{G}_{\Ls}-\bb{G}_{\Ls}')=\bm{0}$. 

To establish \eqref{eq:3.2.37}, we calculate that, for $\bm{\psi}=(\psi_{d})_{d=1}^D\in\Dd(\R,\R^D)$ and $\bm{\phi}=(\phi_{d})_{d=1}^D\in\Dd(\R,\R^D)$,
\begin{align}
    \langle\bb{G}_{\Ls}\ast\bm{\phi},\bm{\psi}\rangle&=\sum_{d=1}^D\int_{\R}\psi_{d}(t)\int_{\R}\sum_{d'=1}^D[\bb{G}_{\Ls}]_{d,d'}(t-\tau)\phi_{d'}(\tau)\mathrm{d}\tau\mathrm{d}t\\
    &=\sum_{d'=1}^D\int_{\R}\phi_{d'}(\tau)\int_{\R}\sum_{d=1}^D[\bb{G}_{\Ls}]_{d,d'}(t-\tau)\psi_{d}(t)\mathrm{d}t\mathrm{d}\tau\\
    &=\sum_{d'=1}^D\int_{\R}\phi_{d'}(\tau)\int_{\R}\sum_{d=1}^D[\bb{G}_{\Ls}^{\intercal,\vee}]_{d',d}(\tau-t)\psi_{d}(t)\mathrm{d}t\mathrm{d}\tau=\langle\bm{\phi},\bb{G}_{\Ls}^{\intercal,\vee}\ast\bm{\psi}\rangle.
\end{align}
To get \eqref{eq:3.2.38}, we first calculate that 
\begin{align}
    \bb{G}_{\Ls}^{\star}=(\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta)^{\star}&=\bb{I}\delta^{\star}\ast\bb{U}^{-1,\star}\ast\bb{D}^{-1,\star}\ast\bb{V}^{-1,\star}\\
    &=\bb{U}^{-1,\star}\ast\bb{D}^{-1,\star}\ast\bb{V}^{-1,\star}\ast\bb{I}\delta,
\end{align}
where we used the fact that, since $\delta$ is the neutral element for the convolution, it is self-adjoint. Moreover $\bb{I}\delta$ commutes with all matrices because it has a constant diagonal. Then, we can write that 
\begin{align}
\Ls^{\star}\ast\bb{G}_{\Ls}^{\star}&=\bb{V}^{\star}\ast\bb{D}^{\star}\ast\bb{U}^{\star}\ast\bb{U}^{-1,\star}\ast\bb{D}^{-1,\star}\ast\bb{V}^{-1,\star}\ast\bb{I}\delta\\
&=\bb{V}^{\star}\ast\bb{D}^{\star}\ast\bb{U}^{\star}\ast\bb{U}^{\star,-1}\ast\bb{D}^{-1,\star}\ast\bb{V}^{\star,-1}\ast\bb{I}\delta\\
&=\bb{V}^{\star}\ast\bb{D}^{\star}\ast\bb{D}^{-1,\star}\ast\bb{V}^{\star,-1}\ast\bb{I}\delta=\bb{V}^{\star}\ast\bb{I}\delta\ast\bb{V}^{\star,-1}\ast\bb{I}\delta=\bb{I}\delta
\end{align}
because $\bb{U}^{-1,\star}=\bb{U}^{\star,-1}$ and $\bb{D}^{\star}\ast\bb{D}^{-1,\star}=\bb{I}\delta$. The latter comes from the equality $\D_d^{\star}\ast g_{\D_d}^{\star}=\D_d^{\star}\ast g_{\D_d}^{\vee}=\delta$. This concludes the proof.
\end{proof}\hfill\\

\begin{proof}[\textbf{Proof of Proposition \ref{prop:reg}}]
 Denote the order of an ODO $\ls$ by $O(\ls).$ From Proposition \ref{prop:Greens}, we find that 
    \begin{equation}
        [\bb{G}_{\Ls}]_{r,c}=[\mathbf{com}(\Ls)^{\intercal}]_{r,c}\ast g_{\mathrm{det}(\Ls)}=(-1)^{r+c}\mathrm{det}(\Ls_{c,r})\ast g_{\mathrm{det}(\Ls)}.
    \end{equation}
 Furthermore, we find by summing over all permutations $\tilde{\sigma}:[1\cdots D]\setminus\{c\}\to[1\cdots D]\setminus\{r\}$ that,
    \begin{align}
    \mathrm{det}(\Ls_{c,r})=\sum_{\tilde{\sigma}}\mathrm{sgn}(\tilde{\sigma})\circledast_{d=1,d\neq c}^D\ls_{d,\tilde{\sigma}(d)}
    \Rightarrow O(\mathrm{det}(\Ls_{c,r}))\leq\underset{\tilde{\sigma}}{\mathrm{max}}\sum_{d=1,d\neq c}^DO(\ls_{d,\tilde{\sigma}(d)}).\label{eq:A.3.97}
    \end{align}
     Consider a specific permutation $\hat{\sigma}$ for which the maximum in \eqref{eq:A.3.97} is achieved. Then, we calculate that

     \begin{align}
    N_{c,r}+ O(\mathrm{det}(\Ls_{c,r}))&\leq N_{c,r}+\underset{\tilde{\sigma}}{\mathrm{max}}\sum_{d=1,d\neq c}^DO(\ls_{d,\tilde{\sigma}(d)})=O(\ls_{c,r})+\sum_{d=1, d\neq c}^DO(\ls_{d,\hat{\sigma}(d)})\\
    &\leq\underset{\sigma}{\mathrm{max }}\left(O(\ls_{c,\sigma(c)})+\sum_{d=1, d\neq c}^DO(\ls_{d,\sigma(d)})\right)\\
    &\leq\underset{\sigma}{\mathrm{max}}\sum_{d=1}^DO(\ls_{d,\sigma(d)})=O(\mathrm{det}(\Ls)).\label{eq:A.3.99}
     \end{align}
The last equality in \eqref{eq:A.3.99} holds because
\begin{equation}
    O(\mathrm{det}(\Ls))=O\left(\sum_{\sigma}\mathrm{sgn}(\tilde{\sigma})\circledast_{d=1}^D\ls_{d,\sigma(d)}\right)=\sum_{d=1}^DO(\ls_{d,d})=\underset{\sigma}{\mathrm{max}}\sum_{d=1}^DO(\ls_{d,\sigma(d)}).\label{eq:A.3.100}
\end{equation}
In turn, the last two equalities in \eqref{eq:A.3.100} hold because of the assumption of the proposition. Hence, from \eqref{eq:A.3.99}, if $N_{c,r}\geq2$, then $g_{\mathrm{det}(\Ls)}\in\mathcal{C}^{N_{c,r}+O(\mathrm{det}(\Ls_{c,r}))-2}(\R)$ and $[\bb{G}_{\Ls}]_{r,c}\in\mathcal{C}^{N_{c,r}-2}(\R).$ We used the fact that the Green's function of an ordinary differential operator of order $N\geq2$ always belong in $\mathcal{C}^{N-2}(\R).$ If $N_{c,r}=1,$ the same analysis is made but $[\bb{G}_{\Ls}]_{r,c}$ is reduced (in term of regularity) to the derivative of a locally Lipschitz-continuous function, which is known to be in the function space $\mathcal{L}^{\infty}_{loc}(\R).$
\end{proof}

\subsection{Proofs of Section 3.3}
\label{app:3.3}
This section is richer than the concatenation of the proofs of Section 3.3. We start by providing the proof of Proposition \ref{prop:testfunctions}. Then, we introduce in Proposition \ref{prop:compact} a compactly supported right inverse $\bb{G}_{\bm{\phi}}$ of $\Ls$, which allows us to move from $\M(\R,\R^D)$ to $\M_{\Ls}(\R,\R^D)$. In Proposition \ref{prop:defmap} and Theorem \ref{th:M} we further study the action of the kernel $\bb{G}_{\bm{\phi}}$ on the measure space $\M(\R,\R^D)$. Finally, leveraging the previous results, we provide the proof of Theorem \ref{prop:MLprop}.

Observe that even-though Theorem \ref{th:M} is stated before Theorem \ref{prop:MLprop}, the latter does not use Theorem \ref{th:M} in its proof. Consequently, we are not making a "circular" argumentation there. 

\begin{proof}[\textbf{Proof of Proposition \ref{prop:testfunctions}}]
Consider the function $\zeta:\R\to\R$ expressed as
\begin{equation}
    \zeta(x)=\begin{cases}
        c\mathrm{e}^{\frac{1}{x^2-1}},&x\in]-1,1[\\
        0, & \text{else},
    \end{cases}
\end{equation}
 where $c^{-1}=\int_{-1}^{1}\mathrm{e}^{\frac{-1}{1-x^2}}\mathrm{d}x$. The function $\zeta$ is compactly supported in $[-1,1]$, belongs to $\mathcal{L}_1(\R)$ with $\norm{\zeta}_{\mathcal{L}_1}=1$, and is also in $\mathcal{C}^{\infty}(\R).$ In particular, $\zeta\in\mathcal{D}(\R)$. Then, $\forall f\in\C(\R)$, using the continuity of $f$ we get \eqref{eq:A.4.99}, and $\forall t\in\R $ we get \eqref{eq:A.4.100}.
\begin{align}
   &\underset{R\to0}{\text{lim }}\left\langle\frac{1}{R}\zeta\left(\frac{\cdot}{R}\right),f\right\rangle-f(0)=\underset{R\to0}{\text{lim }}\int_{-R}^R\frac{c}{R}\mathrm{e}^{\frac{-1}{1- \frac{x^2}{R^2}}}(f(x)-f(0))\mathrm{d}x\\
    &\hspace{+4.1cm}=\underset{R\to0}{\text{lim }}\int_{-1}^1c\mathrm{e}^{\frac{-1}{1- x^2}}(f(Rx)-f(0))\mathrm{d}x=0\label{eq:A.4.99}.\\
   & \underset{R\to0}{\text{lim }}\left\langle\frac{1}{R}\zeta\left(\frac{\cdot}{R}-t\right),f\right\rangle=f(t)\label{eq:A.4.100}.
\end{align}
We take advantage of Lemma \ref{Lemma:mat2} to build the desired family $(\bm{\phi}_n)_{n=1}^N$.

\begin{Lemma} 
\label{Lemma:mat2}
Let $\{\bb{p}_n\}_{n=1}^{N}:[1,\infty[\to\R^D$ be a free (independent) family of analytic functions. Then, there exist two lists $\{\bb{t}_{n'}\}_{n'=1}^N$ and $\{\bb{c}_{n'}\}_{n'=1}^N$ of coordinates $\bb{t}_{n'}\in[1,\infty[^D$ and coefficients $\bb{c}_{n'}\in\R^D$ such that the matrix $\mathbf{A}\in\R^{N\times N}$ defined as $\mathbf{A}_{n',n}=\langle\bb{p}_{n},\bb{c}_{n'}\odot\bm{\delta}_{\bb{t}_{n'}} \rangle=\sum_{d=1}^D[\bb{c}_{n'}]_d[\bb{p}_{n}]_{d}([\bb{t}_{n'}]_d)$ is invertible.
\end{Lemma}

\begin{proof}[\textbf{Proof of Lemma \ref{Lemma:mat2}}]
We only provide a brief proof by induction on $N>1$. If $N=2,$ take $\bb{c}_1\in\R^D$ and $\bb{t}_1\in[1,\infty[^D$ such that $\langle\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}} ,\bb{p}_{1}\rangle\neq0$. They must exist, otherwise $\bb{p}_1=\bm{0}$ on $[1,\infty[$ and, since $\bb{p}_1$ is analytic, $\bb{p}_1=\bm{0}$ on $\R$. For $\bb{c}\in\R^D$ and $\bb{t}\in[1,\infty[^D$, the determinant of the matrix 
\begin{equation}
\begin{bmatrix}
    \langle\bb{p}_{1},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}} \rangle & \langle\bb{p}_{2},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}} \rangle\\
    \langle\bb{p}_{1},\bb{c}\odot\bm{\delta}_{\bb{t}}\rangle & \langle\bb{p}_{2},\bb{c}\odot\bm{\delta}_{\bb{t}} \rangle
    \end{bmatrix}
\quad\text{is}\quad  \langle\bb{p}_{1},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}}\rangle\langle\bb{p}_{2},\bb{c}\odot\bm{\delta}_{\bb{t}}\rangle-\langle\bb{p}_{2},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}} \rangle \langle\bb{p}_{1},\bb{c}\odot\bm{\delta}_{\bb{t}}\rangle.
\end{equation}
Assume by contradiction that there exists no $\bb{c}\in\R^D$ and $\bb{t}\in[1,\infty[^D$ for which the matrix is invertible. Therefore,  $\forall\bb{c}\in\R^D$ and $\forall\bb{t}\in[1,\infty[^D$, its determinant is 0 and
\begin{equation}
\label{eq:3.3.52}
 \langle\bb{p}_{2},\bb{c}\odot\bm{\delta}_{\bb{t}} \rangle=\frac{\langle\bb{p}_{2},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}}\rangle }{\langle\bb{p}_{1},\bb{c}_{1}\odot\bm{\delta}_{\bb{t}_{1}}\rangle }\langle\bb{p}_{1},\bb{c}\odot\bm{\delta}_{\bb{t}}\rangle.
\end{equation}
It follows from \eqref{eq:3.3.52} that $\bb{p}_1$ and $\bb{p}_2$ are linearly dependent on $[1,\infty[$. Because $\{\bb{p}_{1},\bb{p}_{2}\}$ are analytic, they must be linearly dependent on $\R$, which is a contradiction with the initial assumption of them being a free family. The induction step $N$ reaches the same contradiction over the general formula of a determinant and the assumption that an invertible matrix exists for the $(N-1)$ case. This concludes the proof of Lemma \eqref{Lemma:mat2}.
\end{proof}

 We now resume the proof of Proposition \eqref{prop:testfunctions}. Lemma \ref{Lemma:mat2} yields an invertible matrix $\bb{A}\in\R^{N\times N}$ such that 
\begin{equation}
      \bb{A}_{n',n}=\left\langle \bb{p}_n,\bb{c}_{n'}\odot\bm{\delta}_{\bb{t}_{n'}}\right\rangle\quad\text{with}\quad\bb{t}_{n'}\in[1,\infty[^D. 
\end{equation}
Define $\forall n'\in[1\cdots N]$, $\bm{\zeta}_{n'}(R)=\bb{c}_{n'}\odot\left(\frac{1}{R}\zeta\left(\frac{\cdot}{R}-[\bb{t}_{n'}]_d\right)\right)_{d=1}^D\in\mathcal{D}(\R,\R^D)$ and $\bm{\zeta}(R)=(\bm{\zeta}_{n'}(R))_{n'=1}^N\in\mathcal{D}(\R,\R^D)^N$. Define the matrix $\bb{A}(R)\in\R^{N\times N}$ such that
\begin{equation}
  \bb{A}_{n',n}(R)=\left\langle \bb{p}_n,\bm{\zeta}_{n'}(R)\right\rangle . 
\end{equation}
Since $\mathrm{det}(\cdot)$ is a continuous function in terms of the entries of the matrix it receives, we find that $\underset{R\to 0}{\text{lim}}\mathrm{det}(\bb{A}(R))=\mathrm{det}(\bb{A})\neq0$, and there exists an $R'$ such that $\mathrm{det}(\bb{A}(R'))\neq0.$  Define $\bm{\phi}=(\bm{\phi}_{n'})_{n'=1}^N=\bb{A}(R')^{-1}\bm{\zeta}(R')\in\mathcal{D}(\R,\R^D)^N$. The family $\bm{\phi}$ has the expected properties. First, it verifies Item 2 as a linear combination of $\mathcal{D}(\R,\R^D)$ functions. Second, it verifies Item 3 as a linear combination of functions $\frac{1}{R'}\zeta\left(\frac{\cdot}{R'}-[\bb{t}_{n'}]_d\right)$ whose support is in $[R'(1-[\bb{t}_{n'}]_d),R'(1+[\bb{t}_{n'}]_d)]\subset[0,\infty[$. Finally, concerning Item 1, we calculate that 
\begin{align}
\langle\bb{p}_{n},\bm{\phi}_{n'}\rangle&=\left\langle\bb{p}_{n},\sum_{m=1}^{N}\bb{A}(R')^{-1}_{n',m}\bm{\zeta}_m(R')\right\rangle=\sum_{m=1}^{N}\bb{A}(R')^{-1}_{n',m}\left\langle\bb{p}_{n},\bm{\zeta}_m(R')\right\rangle\\
&=\sum_{m=1}^{N}\bb{A}(R')^{-1}_{n',m}\bb{A}(R')_{m,n}=\delta_{n,n'}.
\end{align}

\end{proof}
\begin{ Proposition }
\label{prop:compact}
Let $\left((\bb{p}_n)_{n=1}^N,(\bm{\phi}_n)_{n=1}^N\right)$ be an $\Ls$-admissible system. Then, the kernel $\bb{G}_{\bm{\phi}}(\cdot,\cdot)$ defined as 
    \begin{equation}
    \bb{G}_{\bm{\phi}}(x,y)=\bb{G}_{\Ls}(x-y)-\sum_{n=1}^{N}\bb{p}_n(x)\left(\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n\right)^{\intercal}(y)
    \end{equation}
    is such that 
    \begin{align}
        &\forall x\in\R,\forall y\notin[\mathrm{min}(0,x),\mathrm{max}(x,\phi^+)]:&&\quad\bb{G}_{\bm{\phi}}(x,y)=\bm{0},\label{eq:A.4.107}\\
        &\begin{cases}
            \forall y\in]-\infty,0[,\forall x\in]y,\infty[\\
            \forall y\in]\phi^+,\infty[,\forall x\in]-\infty,y[, 
        \end{cases}:&&\quad\bb{G}_{\bm{\phi}}(x,y)=\bm{0}\label{eq:A.4.108}.
    \end{align}
\end{ Proposition }
\begin{proof}[\textbf{Proof of Proposition \ref{prop:compact}}]
 We recall that
\begin{equation}
    \Ls=\bb{U}\ast\bb{D}\ast\bb{V}\quad\text{with}\quad\bb{D}=\mathbf{diag}(\D_1,...,\D_D),
\end{equation}
where $\bb{U}$ and $\bb{V}$ are unimodular. As usual, we denote the causal Green's function of $\D_d$ by $g_{\D_d}$ and 
\begin{equation}
\bb{G}_{\Ls}=\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1},\quad\mathrm{with}\quad\bb{D}^{-1}=\mathbf{diag}(g_{\D_1},...,g_{\D_D}).    
\end{equation}
 Observe that, if $\left((\bb{p}_n)_{n=1}^N,(\bm{\phi}_n)_{n=1}^N\right)$ is an $\Ls$-admissible system, then the system

 \begin{equation}
     \left((\tilde{\bb{p}}_n)_{n=1}^N,(\tilde{\bm{\phi}}_n)_{n=1}^N\right)=\left((\bb{V}\ast\bb{p}_n)_{n=1}^N,(\bb{V}^{-1,\star}\ast\bm{\phi}_n)_{n=1}^N\right)
 \end{equation}
is $\bb{D}$-admissible, where $(\tilde{\bb{p}}_n)_{n=1}^{N}$ is a basis of $\mathcal{N}_{\bb{D}}$. Consequently, we calculate that 
\begin{align}
        \bb{G}_{\bm{\phi}}(x,y)&=\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta_{y}\right](x)-\sum_{n=1}^{N}\bb{p}_n(\cdot)
        \left[(\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta)^{\star}\ast\bm{\phi}_n\right]^{\intercal}(y)\label{eq:A.4.115}
        \\
        &=\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta_{y}\right](x)-\sum_{n=1}^{N}\bb{p}_n(x)
        \left\langle\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta_y,\bm{\phi}_n\right\rangle^{\intercal}\label{eq:A.4.116}
        \\
        &=\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1}\right](x)-\sum_{n=1}^{N}[\bb{V}^{-1}\ast\tilde{\bb{p}}_n](x)\left\langle\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1},\tilde{\bm{\phi}}_n\right\rangle^{\intercal}\label{eq:A.4.112},
\end{align}
where to go from \eqref{eq:A.4.115} to \eqref{eq:A.4.116} we used the Bracket property (see Proposition \ref{prop:10}) of convolution. Recall that $\bb{D}^{-1}$ is the diagonal concatenation of the Green's functions of the operators $\D_d$ forming the diagonal of $\bb{D}$. In particular, $\bb{D}^{-1}$ is supported in $[0,\infty[.$ Consequently, $\text{supp}\left(\bb{D}^{-1}\ast\bb{I}\delta_y\right)=[y,\infty[$ and since $\bb{U}^{-1}$ is an MDO, it preserves the support, and  $\text{supp}\left(\bb{D}^{-1}\ast\bb{I}\delta_y\ast\bb{U}^{-1}\right)=[y,\infty[$. Observe further that $\tilde{\bm{\phi}}_n$ is supported in $[0,\phi^+]$. Consequently, if $y>\mathrm{max}(x,\phi^+)\geq\phi^+$, then 
\begin{equation}
    \text{supp}\left(\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta_{y}\right)\cap\text{supp}(\tilde{\bm{\phi}}_n)\subset[y,\infty[\cap[0,\phi^+]=\emptyset\Rightarrow\left\langle\bb{D}^{-1}\ast\bb{U}^{-1}\ast\bb{I}\delta_{y},\tilde{\bm{\phi}}_n\right\rangle=\bm{0}.
\end{equation}
Since $\bb{V}^{-1}$ is an MDO, it preserves the support and $\text{supp}\left(\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{I}\delta_y\ast\bb{U}^{-1}\right)=[y,\infty[$. Therefore, if $y>\mathrm{max}(x,\phi^+)\geq x$, then $\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1}\right](x)=\bm{0}$. Finally, $\bb{G}_{\bm{\phi}}(x,y)=0$ if $y>\mathrm{max}(x,\phi^+).$ Then, we observe that $\bb{D}^{-1}$ is such that $\bb{D}^{-1}=\bb{P}_+$, where each column of $\bb{P}$ is in $\mathcal{N}_{\bb{D}}$, and $\bb{P}_+$ is the causal part of $\bb{P}.$ If $y<\mathrm{min}(0,x)$, then $y<x$ and $y<0$ imply that 
\begin{align}
   &\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1}\right](x)=\left[\bb{V}^{-1}\ast\bb{P}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1}\right](x),\\
   \text{and},\quad &\left\langle\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1},\tilde{\bm{\phi}}_n\right\rangle=\left\langle\bb{P}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1},\tilde{\bm{\phi}}_n\right\rangle.\label{eq:A.4.114}
\end{align}
Furthermore, $\mathcal{N}_{\bb{D}}$ is translation-invariant and stable under differentiation. Therefore, each column of $\tilde{\bb{P}}=\bb{P}\ast\bb{I}\delta_y\ast\bb{U}^{-1}$ is in $\mathcal{N}_{\bb{D}}$ and $\tilde{\bb{P}}(\cdot)=\sum_{n=1}^{N}\tilde{\bb{p}}_n(\cdot)\left\langle\tilde{\bb{P}},\tilde{\bm{\phi}}_n\right\rangle^{\intercal}$. Finally, the combination of \eqref{eq:A.4.112}, \eqref{eq:A.4.114} with the previous comment on $\mathcal{N}_{\bb{D}}$, yields that 
\begin{align}
        \bb{G}_{\bm{\phi}}(x,y)&=\left[\bb{V}^{-1}\ast\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1}\right](x)-\sum_{n=1}^{N}[\bb{V}^{-1}\ast\tilde{\bb{p}}_n](x)\left\langle\bb{D}^{-1}\ast\bb{I}\delta_{y}\ast\bb{U}^{-1},\tilde{\bm{\phi}}_n\right\rangle^{\intercal}\\
        &=\left[\bb{V}^{-1}\ast\tilde{\bb{P}}\right](x)-\sum_{n=1}^{N}[\bb{V}^{-1}\ast\tilde{\bb{p}}_n](x)\left\langle\tilde{\bb{P}},\tilde{\bm{\phi}}_n\right\rangle^{\intercal}\\
        &=\left[\bb{V}^{-1}\ast\tilde{\bb{P}}\right](x)-\left[\bb{V}^{-1}\ast\tilde{\bb{P}}\right](x)=\bm{0}.    
\end{align}
This proves \eqref{eq:A.4.107}. In turn, \eqref{eq:A.4.108} is the converse of \eqref{eq:A.4.107}.
\end{proof}

We define the functional $\bb{G}_{\bm{\phi}}:\Dd(\R,\R^D)\to\C^{\infty}(\R,\R^D)$ as 
\begin{equation}
    \forall\bm{\psi}\in\Dd(\R,\R^D):\quad\bb{G}_{\bm{\phi}}\{\bm{\psi}\}(\cdot)=\int_{\R}\bb{G}_{\bm{\phi}}(\cdot,y)\bm{\psi}(y)\mathrm{d}y=(\bb{G}_{\Ls}\ast\bm{\psi})(\cdot)-\sum_{n=1}^N\bb{p}_n(\cdot)\langle\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n,\bm{\psi}\rangle.
\end{equation}
Likewise, we define the functional $\bb{G}_{\bm{\phi}}^{\star}:\Dd(\R,\R^D)\to\Dd(\R,\R^D)$ as 
\begin{equation}
    \forall\bm{\psi}\in\Dd(\R,\R^D):\quad\bb{G}_{\bm{\phi}}^{\star}\{\bm{\psi}\}(\cdot)=\int_{\R}\bb{G}_{\bm{\phi}}(x,\cdot)^{\intercal}\bm{\psi}(x)\mathrm{d}x=(\bb{G}_{\Ls}^{\star}\ast\bm{\psi})(\cdot)-\sum_{n=1}^N(\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n)(\cdot)\langle\bb{p}_n,\bm{\psi}\rangle.
\end{equation}
We observe that $\forall(\bm{\psi},\bm{\rho})\in\Dd(\R,\R^D)^2$, it holds that 
\begin{equation}
    \langle \bb{G}_{\bm{\phi}}^{\star}\{\bm{\psi}\},\bm{\rho}\rangle= \langle \bm{\psi},\bb{G}_{\bm{\phi}}\{\bm{\rho}\}\rangle,\quad\quad\text{and}\quad\langle \bb{G}_{\bm{\phi}}\{\bm{\psi}\},\bm{\rho}\rangle= \langle \bm{\psi},\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}\rangle.
\end{equation}
In Proposition \ref{prop:defmap} we extend by duality the definition of the mapping $\bb{G}_{\bm{\phi}}$ to the whole vector space $\M(\R,\R^D)$.
\begin{ Proposition }
\label{prop:defmap}
The mapping 
\begin{equation}
        \bb{G}_{\bm{\phi}}:\begin{cases}
        \M(\R,\R^D)\to\bb{G}_{\bm{\phi}}\M(\R,\R^D)\subset\mathcal{D}'(\R,\R^D)\\
        \bb{m}\mapsto\bb{G}_{\bm{\phi}}\{\bb{m}\},
        \end{cases}
    \end{equation}
defined as
\begin{equation}
\label{eq:A.4.123}
    \forall\bm{\psi}\in\mathcal{D}(\R,\R^D):\quad\left\langle\bb{G}_{\bm{\phi}}\{\bb{m}\},\bm{\psi}\right\rangle=\left\langle\bb{m},\bb{G}_{\bm{\phi}}^{\star}\{\bm{\psi}\}\right\rangle,
\end{equation}
is well-defined because $\bb{G}_{\bm{\phi}}^{\star}\{\bm{\psi}\}\in \Dd(\R,\R^D)\subset\C_0(\R,\R^D).$
\end{ Proposition }
\begin{proof}[\textbf{Proof of Proposition \eqref{prop:defmap}}]
    We first calculate that 
    \begin{align}
\int_{\R}\bb{G}_{\bm{\phi}}^{\intercal}(x,\cdot)\bm{\psi}(x)\mathrm{d} x&=\int_{\R}\bb{G}_{\Ls}^{\intercal}(x-\cdot)\bm{\psi}(x)\mathrm{d}x-\sum_{n=1}^{N}(\bb{G}_{\bb{L}}^{\star}\ast\bm{\phi}_n)(\cdot)\int_{\R}\langle\bb{p}_n(x),\bm{\psi}(x)\rangle\mathrm{d}x\\
&=\left[\bb{G}_{\bb{L}}^{\star}\ast\left(\bm{\psi}-\sum_{n=1}^Nc_n\bm{\phi}_n\right)\right](\cdot),\label{eq:3.2.68}
 \end{align}
where $c_n=\int_{\R}\langle\bb{p}_n(x),\bm{\psi}(x)\rangle\mathrm{d}x$. Equation \eqref{eq:3.2.68} is the convolution between a distribution and a test function, which is known to be in $\C^{\infty}(\R,\R^{D})$. Finally, assume that $\bm{\psi}$ is compactly supported in $[\psi^-,\psi^+]$. From \eqref{eq:A.4.108}, we find that, if $y\in]-\infty,\text{min}(0,\psi^{-})[\bigcup]\text{max}(\phi^+,\psi^+),\infty[$, then 
\begin{equation}
    \int_{\R}\bb{G}_{\bm{\phi}}^{\intercal}(x,y)\bm{\psi}(x)\mathrm{d}x=\bm{0}\quad\Rightarrow\quad\int_{\R}\bb{G}_{\bm{\phi}}^{\intercal}(x,\cdot)\bm{\psi}(x)\mathrm{d}x\in\C^{\infty}_c(\R,\R^D)\subset\C_0(\R,\R^D).
\end{equation}
\end{proof}

\begin{theorem}
\label{th:M} 
First, the space $\bb{G}_{\bm{\phi}}\M(\R,\R^D)$ has the following properties.
\begin{itemize}
    \item [1.] For all $\bb{m}\in\M(\R,\R^D):\quad\Ls\{\bb{G}_{\bm{\phi}}\{\bb{m}\}\}=\bb{m}$;
    \item [2.] it is a Banach space for the norm $\norm{\Ls\{\cdot\}}_{\Zz',\M}$ (resp. $\norm{\Ls\{\cdot\}}_{\M,\Zz'}$);
    \item [3.] for all $n$ such that $ 1\leq n\leq N:\quad\left\langle\bb{G}_{\bm{\phi}}\{\bb{m}\},\bm{\phi}_n\right\rangle=0.$
\end{itemize}
Second, the space $\M_{\Ls}(\R,\R^D)$ has the following property:
\begin{itemize}
    \item [4.] direct-sum decomposition $\M_{\Ls}(\R,\R^D)=\bb{G}_{\bm{\phi}}\M(\R,\R^D)\oplus\mathcal{N}_{\Ls}$.
\end{itemize}
\end{theorem}

\begin{proof}[\textbf{Proof of Theorem \ref{th:M}}]
\hfill\\
\textbf{Item 1.}
We first calculate that $\langle\bb{p},\Ls^{\star}\{\bm{\psi}\}\rangle=\langle\Ls\{\bb{p}\},\bm{\psi}\rangle=0,$ $\forall\bm{\psi}\in\Dd(\R,\R^D).$ Observe that $\Ls\{\bb{G}_{\bm{\phi}}\{\bb{m}\}\}\in\Dd'(\R,\R^D).$ Therefore, from \eqref{eq:3.2.68}, we calculate that 
\begin{align}
    \langle\Ls\{\bb{G}_{\bm{\phi}}\{\bb{m}\}\},\bm{\psi}\rangle=\langle\bb{G}_{\bm{\phi}}\{\bb{m}\},\Ls^{\star}\{\bm{\psi}\}\rangle=\langle\bb{m},\bb{G}_{\Ls}^{\star}\ast\Ls^{\star}\{\bm{\psi}\}\rangle=\langle\bb{m},(\Ls\ast\bb{G}_{\Ls})^{\star}\ast\bm{\psi}\rangle=\langle\bb{m},\bm{\psi}\rangle\label{eq:A.4.126}.
\end{align}
Equation \eqref{eq:A.4.126} holds $\forall\bm{\psi}\in\Dd(\R,\R^D),$ which is dense in the predual $\C_0(\R,\R^D)$ of $\M(\R,\R^D)$; thus, it directly implies Item 1.
\hfill\\\hfill\\
\textbf{Item 2.}
It follows directly from Item 1 that $\left(\M(\R,\R^D),\norm{\cdot}_{\Zz',\M}\right)$ and $\left(\bb{G}_{\bm{\phi}}\M(\R,\R^D), \norm{\Ls\{\cdot\}}_{\Zz',\M}\right)$ are isometric.
\hfill\\\hfill\\
\textbf{Item 3.}
For $1\leq n'\leq N$, we get from  \eqref{eq:A.4.123} that
\begin{align}
    \left\langle\bb{G}_{\bm{\phi}}\{\bb{m}\},\bm{\phi}_{n'}\right\rangle&=\left\langle\bb{m},\bb{G}_{\bm{\phi}}^{\star}\{\bm{\phi}_{n'}\}\right\rangle=\left\langle\bb{m},\bb{G}_{\bb{L}}^{\star}\ast\left(\bm{\phi}_{n'}-\sum_{n=1}^N\bm{\phi}_n\langle\bb{p}_n,\bm{\phi}_{n'}\rangle\right)\right\rangle\\
    &=\left\langle\bb{m},\bb{G}_{\bb{L}}^{\star}\ast\left(\bm{\phi}_{n'}-\bm{\phi}_{n'}\right)\right\rangle=0.
\end{align}
\hfill\\\hfill\\
\textbf{Item 4.} We first prove that the sum is direct. Suppose that it is not; then, there exists $\bm{0}\neq\bb{G}_{\bm{\phi}}\{\bb{m}\}\in\bb{G}_{\bm{\phi}}\M(\R,\R^D)$ and $\bm{0}\neq\bb{q}\in\mathcal{N}_{\Ls}$, for which we find the contradiction
\begin{equation}
\bb{G}_{\bm{\phi}}\{\bb{m}\}=\bb{q}\Rightarrow\Ls\{\bb{G}_{\bm{\phi}}\{\bb{m}\}\}=\Ls\{\bb{q}\}\Rightarrow\bb{m}=\bm{0}.
\end{equation}
This shows that $\bb{G}_{\bm{\phi}}\M(\R,\R^D)\oplus\mathcal{N}_{\Ls}\subset\M_{\Ls}(\R,\R^D)$. We conclude by noticing that, $\forall \bb{f}\in\M_{\Ls}(\R,\R^D),$ it holds that
\begin{equation}
    \bb{f}=\bb{G}_{\bm{\phi}}\{\Ls\{\bb{f}\}\}+\left(\bb{f}-\bb{G}_{\bm{\phi}}\{\Ls\{\bb{f}\}\}\right),\quad\text{with}\quad\left(\bb{f}-\bb{G}_{\bm{\phi}}\{\Ls\{\bb{f}\}\}\right)\in\mathcal{N}_{\Ls}.
\end{equation}
\end{proof}

\begin{proof}[\textbf{Proof of Theorem \ref{prop:MLprop}}]
\hfill\\
\textbf{Item 1.}
This follows directly from Theorem \ref{th:M}.
\hfill\\\hfill\\
\textbf{Item 2.}
We know from Theorem \ref{th:M} that $\M_{\Ls}(\R,\R^D)=\bb{G}_{\bm{\phi}}\M(\R,\R^D)\oplus\mathcal{N}_{\Ls}.$ Because $\bb{G}_{\bm{\phi}}\M(\R,\R^D)\oplus\mathcal{N}_{\Ls}$ is isometric to $\M(\R,\R^D)\times\R^N$, the latter space admits a predual, and so does $\M_{\Ls}(\R,\R^D)$. 
\hfill\\\hfill\\
\textbf{Item 3.} This follows directly from Item 2 of Proposition \ref{prop:1} and Items 1 and 2 of Proposition \ref{prop:3}.
\hfill\\\hfill\\
\textbf{Item 4.} We know from Item 4 of Proposition \ref{prop:1} that the extreme points of the unit ball in $(\M(\R,\R^D),\norm{\cdot}_{\M,\Zz'})$ are of the form 
\begin{equation}
\bb{w}\odot\bm{\delta}_{\bb{x}},\quad\text{with}\quad\bb{x}\in\R^D,
\end{equation}
where $\bb{w}$ is an extreme point of the centered unit ball in $\Zz'$. Further, it follows from Theorem \eqref{th:M} that
\begin{equation}
    (\M(\R,\R^D),\norm{\cdot}_{\M,\Zz'}),\quad\text{and}\quad(\bb{G}_{\bm{\phi}}\M(\R,\R^D),\norm{\Ls\{\cdot\}}_{\M,\Zz'})
\end{equation}
are isometric and that, consequently, the extreme points in the unit ball of $(\bb{G}_{\bm{\phi}}\M(\R,\R^D),\norm{\Ls\{\cdot\}}_{\M,\Zz'})$ are exactly of the form
\begin{multline}
\label{eq:148}
    \bb{e}=\bb{G}_{\bm{\phi}}\{\bb{w}\odot\bm{\delta}_{\bb{x}}\}=\bb{G}_{\Ls}\ast(\bb{w}\odot\bm{\delta}_{\bb{x}})-\sum_{n=1}^{N}b_n\bb{p}_n,\quad\text{with}\\
    b_n=\langle\bb{w}\odot\bm{\delta}_{\bb{x}},\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n\rangle.
\end{multline}
Finally, \eqref{eq:148} and the direct sum decomposition in Theorem \ref{th:M} Item 4 show that the extreme points $[\bb{e}]$ of the centered unit ball in  $(\M_{\Ls}(\R,\R^D)/\mathcal{N}_{\Ls}, \norm{\Ls\{\cdot\}}_{\M,\Zz'})$ are exactly
\begin{equation}
[\bb{e}]=\bb{G}_{\Ls}\ast(\bb{w}\odot\bm{\delta}_{\bb{x}})-\sum_{n=1}^{N}b_n\bb{p}_n+\mathcal{N}_{\Ls}=\bb{G}_{\Ls}\ast(\bb{w}\odot\bm{\delta}_{\bb{x}})+\mathcal{N}_{\Ls}.
\end{equation}
This also shows that all $\Ls$-splines $\bb{f}$ are in $\M_{\Ls}(\R,\R^D)$. Moreover if $\bb{f}=\sum_{k=1}^K\bb{G}_{\Ls}\ast(\bb{a}_k\odot\bm{\delta}_{\bb{x}_k})+\bb{q}$ with $\bb{x}_k\neq\bb{x}_{k'}$ for all rows, then we calculate that
\begin{align}
\norm{\Ls\{\bb{f}\}}_{\M,\Zz'}&=
\norm{\Ls\left\{\bb{G}_{\Ls}\ast\left(\sum_{k=1}^K\bb{a}_k\odot\bm{\delta}_{\bb{x}_k}\right)\right\}+\Ls\{\bb{q}\}}_{\M,\Zz'}=
\norm{\sum_{k=1}^K\bb{a}_k\odot\bb{\delta}_{\bb{x}_k}}_{\M,\Zz'}\\
&=\norm{\left(\sum_{k=1}^K\vert [\bb{a}_k]_d\vert\right)_{d=1}^D}_{\Zz'}.
\end{align}
\hfill\\\hfill\\
\textbf{Item 5.}
The argument is the same as the one in the Item 4, upon substitution of $x$ for $\bb{x}$. The norm calculation follows from Item 3 of Proposition \ref{prop:3}.
\end{proof}

\begin{proof}[\textbf{Proof of Proposition \ref{prop:stabilitymat}}]
\hfill\\
\textbf{Item 1.} The calculation of the Green's matrix is straightforward. The equality of native spaces follows from the observation that
\begin{equation}
\tilde{\Ls}\{\bb{f}\}\in\M(\R,\R^D)\Leftrightarrow\\(\bb{S}\Ls)\{\bb{f}\}\in\M(\R,\R^D)\Leftrightarrow\Ls\{\bb{f}\}\in\M(\R,\R^D).
\end{equation}
The equality of null spaces follows likewise.\hfill\\
\textbf{Item 2.} The calculation of the Green's matrix is straightforward. Next, we fix
\begin{equation}
    \bb{A}=\begin{bmatrix}
        0&1\\
        1&0
    \end{bmatrix},\quad
    \bb{L}=\begin{bmatrix}
        \D&0\\
        0&\D^2
    \end{bmatrix}\Rightarrow\quad\bb{G}_{\tilde{\Ls}}(\cdot)=\begin{bmatrix}
        0&(\cdot)_+\\
        (\cdot)_+^0&0
    \end{bmatrix}.
\end{equation}
If $\M_{\Ls}(\R,\R^D)=\M_{\tilde{\Ls}}(\R,\R^D)$, then 
\begin{equation}
    \bb{G}_{\tilde{\Ls}}\ast\begin{bmatrix}
        \delta_0\\
        0
    \end{bmatrix}\in\M_{\Ls}(\R,\R^D)\Rightarrow
    \begin{bmatrix}
        0\\
        (\cdot)_+^0
    \end{bmatrix}\in\M_{\Ls}(\R,\R^D)\Rightarrow
    \begin{bmatrix}
        0\\
        \delta_0'   
    \end{bmatrix}\in\M(\R,\R^D),
\end{equation}
which is a contradiction. The inequality of null spaces is proved likewise.
\end{proof}

\subsection{Proofs of Section 3.4}
\label{app:3.4}
Using the kernel $\bb{G}_{\bm{\phi}}$, we restate Theorem \ref{th:predual} as the precise Theorem \ref{th:Mpred}. The classic extension Theorem \ref{th:extension} taken from \cite{reed1972methods}
[Theorem I.7, p. 9] is necessary for the proof of Theorem \ref{th:Mpred}.

\begin{theorem}
\label{th:extension}
Let $G$ be a bounded linear transformation from a normed space $(\mathcal{X}, \norm{\cdot}_{\mathcal{X}})$ to a complete normed space $(\mathcal{Y}, \norm{\cdot}_{\mathcal{Y}})$. Then, G
has a unique extension to a bounded linear transformation (with the same norm) from the 
completion of $\mathcal{X}$ to $\mathcal{Y}$.
\end{theorem}


\begin{theorem} 
\label{th:Mpred}
Let $(\bb{p}, \bm{\phi})$ be an admissible system in the sense of Definition \ref{def:admissible}. Then, the function space
\begin{equation}
\label{eq:3.2.40}
    \C_{\Ls}(\R,\R^D)=\left\{\bb{g}=\Ls^{\star}\{\bb{v}\}+\sum_{n=1}^Na_n\bm{\phi}_n:\bb{v}\in\C_{0}(\R,\R^D),\bb{a}=(a_n)_{n=1}^N\in\R^N\right\}
\end{equation}
has the following properties
\begin{itemize}
    \item [1.] every $\bb{g}$ has a unique direct-sum representation as in \eqref{eq:3.2.40}, with $\bb{v}=\bb{G}_{\bm{\phi}}^{\star}\{\bb{g}\}$ and, $\forall n\in[1,N],a_n=\langle\bb{p}_n,\bb{g}\rangle$;
    \item [2.] the space $\C_{\Ls}(\R,\R^D)$ is a Banach space for the norm
    \begin{equation}
        \norm{\bb{g}}_{\C_{\Ls}}=\mathrm{max}(\norm{\bb{G}_{\bm{\phi}}^{\star}\{\bb{g}\}}_{\Zz,\infty},\norm{(\langle \bb{p}_n,\bb{g}\rangle)_{n=1}^N)}_{\Yy})=\mathrm{max}(\norm{\bb{v}}_{\Zz,\infty},\norm{\bb{a}}_{\Yy})
    \end{equation}
    or
        \begin{equation}
        \norm{\bb{g}}_{\C_{\Ls}}=\mathrm{max}(\norm{\bb{G}_{\bm{\phi}}^{\star}\{\bb{g}\}}_{\infty,\Zz},\norm{(\langle \bb{p}_n,\bb{g}\rangle)_{n=1}^N)}_{\Yy})=\mathrm{max}(\norm{\bb{v}}_{\infty,\Zz},\norm{\bb{a}}_{\Yy});
    \end{equation}
    \item [3.] the space $\C_{\Ls}(\R,\R^D)$ is the predual of $\M_{\Ls}(\R,\R^D)$; so that $\C_{\Ls}(\R,\R^D)'=\M_{\Ls}(\R,\R^D)$ with 
    \begin{equation}
        \norm{\Ls\{\cdot\}}_{\Zz',\M}+\norm{\left(\langle \cdot,\bm{\phi}_n\rangle\right)_{n=1}^N}_{\Yy'}\text{ being the dual norm of } \mathrm{max}(\norm{\bb{G}_{\bm{\phi}}^{\star}\{\cdot\}}_{\Zz,\infty},\norm{(\langle \bb{p}_n,\cdot\rangle)_{n=1}^N)}_{\Yy})
    \end{equation}
    and 
    \begin{equation}
        \norm{\Ls\{\cdot\}}_{\M,\Zz'}+\norm{\left(\langle \cdot,\bm{\phi}_n\rangle\right)_{n=1}^N}_{\Yy'}\text{ being the dual norm of } \mathrm{max}(\norm{\bb{G}_{\bm{\phi}}^{\star}\{\cdot\}}_{\infty,\Zz},\norm{(\langle \bb{p}_n,\cdot\rangle)_{n=1}^N)}_{\Yy}.
    \end{equation}
\end{itemize} 
\end{theorem}

\begin{proof}[\textbf{Proof of Theorem \ref{th:Mpred}}]
\hfill\\
\textbf{Item 1.}
We first calculate that $\forall\bm{\psi}\in\Dd(\R,\R^D),$ it holds that
\begin{equation}
    \bb{G}_{\bm{\phi}}\{\bm{\psi}\}(\cdot)=\left(\bb{G}_{\Ls}\ast\bm{\psi}\right)(\cdot)-\sum_{n=1}^N\bb{p}_n(\cdot)\left\langle\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n,\bm{\psi}\right\rangle=\left[\bb{G}_{\Ls}\ast\bm{\psi}\right](\cdot)-\sum_{n=1}^N\bb{p}_n(\cdot)\left\langle\bm{\phi}_n,\bb{G}_{\Ls}\ast\bm{\psi}\right\rangle.\label{eq:A.4.136}
\end{equation}
It follows from \eqref{eq:A.4.136} that, $\forall\bb{v}\in\C_0(\R,\R^D)$ and $\forall(a_n)_{n=1}^N\in\R^N$,
\begin{align}   &\left\langle\bb{G}_{\bm{\phi}}^{\star}\left\{\Ls^{\star}\{\bb{v}\}\right\},\bm{\psi}\right\rangle=\left\langle\bb{v},\Ls\{\bb{G}_{\bm{\phi}}\{\bm{\psi}\}\}\right\rangle=\left\langle\bb{v},\bm{\psi}\right\rangle\quad&&\Rightarrow\quad\bb{G}_{\bm{\phi}}^{\star}\left\{\Ls^{\star}\{\bb{v}\}\right\}=\bb{v},\\
&\left\langle\bb{G}_{\bm{\phi}}^{\star}\left\{\sum_{n=1}^Na_n\bm{\phi}_n\right\},\bm{\psi}\right\rangle= \left\langle\sum_{n=1}^Na_n\bm{\phi}_n,\bb{G}_{\bm{\phi}}\{\bm{\psi}\}\right\rangle=0\quad&&\Rightarrow\quad\bb{G}_{\bm{\phi}}^{\star}\left\{\sum_{n=1}^Na_n\bm{\phi}_n\right\}=\bm{0}\\
& &&\Rightarrow\bb{G}_{\bm{\phi}}^{\star}\left\{\bb{g}\right\}=\bb{v}.\label{eq:A.4.139}
\end{align}
We also calculate that, $\forall\bb{v}\in\Dd(\R,\R^D)$ and $\forall(a_n)_{n=1}^N\in\R^N$,
\begin{align}
\label{eq:A.4.141}
    \langle \bb{p}_n,\Ls^{\star}\{\bb{v}\}\rangle=\langle \Ls\{\bb{p}_n\},\bb{v}\rangle=0,\quad\text{and}\quad\left\langle\bb{p}_{n},\sum_{n'=1}^Na_{n'}\bm{\phi}_{n'}\right\rangle=a_{n}\quad\Rightarrow\langle\bb{p}_{n},\bb{g}\rangle=a_{n}.
\end{align}
Then, from Theorem \ref{th:extension} and from the density 
 of $\mathcal{D}(\R,\R^D)$ in $\C_0(\R,\R^D)$, we conclude that \eqref{eq:A.4.141} holds $\forall\bb{v}\in\C_0(\R,\R^D)$. The desired direct-sum decomposition follows directly.
\hfill\\\hfill\\
\textbf{Item 2.} Item 2 follows directly from Item 1 and \eqref{eq:A.4.139}, \eqref{eq:A.4.141}.
\hfill\\\hfill\\
\textbf{Item 3.} Item 3 follows directly from the direct-sum decompositions in Item 4 of Theorem \ref{th:M} and Item 1 of Theorem \ref{th:Mpred}, and from the two duality results 
\begin{align}
    &\left(\bb{G}_{\bm{\phi}}\M(\R,\R^D),\quad\norm{\Ls\{\cdot\}}_{\M,\Zz'}\right)=\left(\Ls^{\star}\C_0(\R,\R^D),\quad\norm{\bb{G}_{\bm{\phi}}^{\star}\{\cdot\}}_{\infty,\Zz}\right)'\\
    \text{and}&\left(\mathcal{N}_{\Ls},\norm{(\langle \cdot,\bm{\phi}_n\rangle)_{n=1}^N}_{\Yy'}\right)=\left(\text{span}(\bm{\phi}_n)_{n=1}^N,\quad\norm{(\langle \bb{p}_n,\cdot\rangle)_{n=1}^N}_{\Yy}\right)'.
\end{align}
The argumentation in the case of inner norms is the same. 
\end{proof}

\begin{proof}[\textbf{Proof of Corollary \ref{coro:diracpredual}}]We first calculate that 
\begin{equation}
    \bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}=\bb{G}^{\star}_{\Ls}\ast\bm{\rho}-\sum_{n=1}^N\langle\bm{\rho},\bm{p}_n\rangle\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n,
\end{equation}
wherefrom it follows that $\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}$, as the convolution between distributions and test functions, is itself a continuous function. In addition, and following the argument made in the proof of Proposition \ref{prop:defmap}, we find that $\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}$ is compactly supported. Consequently, $\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}\in\C_0(\R,\R^D)$. Then, we claim that $\Ls^{\star}\{\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}\}+\sum_{n=1}^N\langle\bm{\rho},\bb{p}_n\rangle\bm{\phi}_n=\bm{\rho}$, which concludes the proof. We calculate that
\begin{align}
    \Ls^{\star}\{\bb{G}_{\bm{\phi}}^{\star}\{\bm{\rho}\}\}+\sum_{n=1}^N\langle\bm{\rho},\bb{p}_n\rangle\bm{\phi}_n&=\Ls^{\star}\left\{\bb{G}_{\Ls}^{\star}\ast\bm{\rho}-\sum_{n=1}^N\langle\bm{\rho},\bb{p}_n\rangle\bb{G}_{\Ls}^{\star}\ast\bm{\phi}_n\right\}+\sum_{n=1}^N\langle\bm{\rho},\bb{p}_n\rangle\bm{\phi}_n=\bm{\rho}.
