\begin{proof}[\textbf{Proof of Proposition \ref{prop:banachrestricted}}]We provide the proof only in the case of inner norms. For $\bb{P}=\bb{A}^{\intercal}\bb{A}$ and $\bb{m}\in\M(\R,\R^D)$, we establish the continuity bound
\begin{equation}
    \norm{(\bb{I}-\bb{P})\{\bb{T}\{\bb{m}\}\}}_{\Zz',\M}=\underset{\pi}{\mathrm{sup}}\sum_{A\in\pi}\norm{(\bb{I}-\bb{P})\{\bb{T}\{\bb{m}(A)\}\}}_{\Zz'}\leq\norm{(\bb{I}-\bb{P})\bb{T}}\norm{\bb{m}}_{\Zz',\M},
\end{equation}
where $\norm{(\bb{I}-\bb{P})\bb{T}}=\underset{\bb{z}:\norm{\bb{z}}_{\Zz'}\leq1}{\mathrm{max}}\norm{(\bb{I}-\bb{P})\{\bb{T}\{\bb{z}\}\}}_{\Zz'}$. Let $(\bb{f}_n)_{n=1}^{\infty}$ be a sequence that is convergent in the strong topology to some $\bb{f}\in\M_{\Ls}(\R,\R^D)$, with $\bb{f}_n\in\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)$. It follows that $\bb{f}\in\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)$ because
\begin{align}
    \norm{(\bb{I}-\bb{P})\{\tilde{\Ls}\{\bb{f}\}\}}_{\Zz',\M}&\leq\norm{(\bb{I}-\bb{P})\{\tilde{\Ls}\{\bb{f}-\bb{f}_n\}\}}_{\Zz',\M}+\norm{(\bb{I}-\bb{P})\{\tilde{\Ls}\{\bb{f}_n\}\}}_{\Zz',\M}\\
    &\leq\norm{(\bb{I}-\bb{P})\bb{T}}
    \norm{\Ls\{\bb{f}-\bb{f}_n\}}_{\Zz',\M}\underset{n\to\infty}{\to}0.
\end{align}
\end{proof}

\begin{proof}[\textbf{Proof of Corollary \ref{coro:restrictedRT1}}]
We prove the extreme-point representation in \eqref{eq:4.3.76} for inner norms $\norm{\cdot}_{\Ww',\M}$. First observe that, $\forall\bb{f}\in\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)$,
\begin{equation}
\label{eq:4.3.79}
    \norm{(\bb{Q}\Ls)\{\bb{f}\}}_{\Ww',\M}=\norm{\tilde{\bb{S}}\{\tilde{\Ls}\{\bb{f}\}\}}_{\Zz',\M},\quad\text{with}\quad
    \tilde{\bb{S}}=\begin{bmatrix}
        \bb{S}&\bm{0}\\
        \bm{0}&\hat{\bb{S}}
    \end{bmatrix},
\end{equation}
where $\hat{\bb{S}}\in\R^{(D-D')\times(D-D')}$ is any invertible matrix and where $\norm{\tilde{\bb{S}}\{\cdot\}}_{\Zz',\M}$ is an inner norm over $\M(\R,\R^D)$.
Since $\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)$ is a Banach subspace of $\M_{\Ls}(\R,\R^D)=\M_{\tilde{\Ls}}(\R,\R^D)$ equipped with the inner semi-norm $\norm{(\tilde{\bb{S}}\tilde{\Ls})\{\cdot\}}_{\Zz',\M}$, it follows from the same argument as in the proof of Theorem \ref{th:optweakstar} that the extreme points  of $\mathcal{V}$ are of the form 
\begin{equation}
\label{eq:4.3.81}
\bb{p}+\sum_{k=1}^Ka_k\bb{f}_k,\quad\quad a_k\in\R,\quad K\leq(M-N),\quad\bb{p}\in\mathcal{N}_{\Ls},
\end{equation}
where $\bb{f}_k$ is a representative of an extreme point of the unit ball in $\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)/\mathcal{N}_{\Ls}$. 
The extreme points of the centered unit ball in 
\begin{equation}
    (\M(\R,\R^{D'}), \norm{\bb{S}\{\cdot\}}_{\Ww',\M})\subset(\M(\R,\R^{D}), \norm{\tilde{\bb{S}}\{\cdot\}}_{\Zz',\M})
\end{equation}
are exactly of the form
\begin{equation}
\label{eq:4.3.82}
    \bb{S}^{-1}\{\bb{a}\delta_x\}=\bb{S}^{-1}\{\bb{a}\}\delta_x,\quad\text{with}\quad x\in\R,\quad\bb{a}\in\R^{D'},
\end{equation}
 where $\bb{a}$ is an extreme point of the centered unit ball in $(\R^{D'},\norm{\cdot}_{\Ww'}).$ In addition, 
\begin{equation}
    \bb{A}\tilde{\Ls}:\M_{\tilde{\Ls}\vert\Ww'}(\R,\R^D)/\mathcal{N}_{\Ls}\to\M(\R,\R^{D'})
\end{equation}
is an isometry. The inverse of an element of the form \eqref{eq:4.3.82} is thus the equivalence class represented by 
\begin{equation}
\label{eq:4.3.84}
(\bb{G}_{\tilde{\Ls}}\bb{A}^{\intercal})\{\bb{S}^{-1}\{\bb{a}\delta_x\}\}=(\bb{G}_{\Ls}\bb{T}^{-1}\bb{A}^{\intercal}\bb{S}^{-1})\{\bb{a}\delta_x\}=(\bb{G}_{\Ls}\bb{Q}^{\dagger})\{\bb{a}\delta_x\}
\end{equation}
which, therefore, exactly represents the extreme points of the unit ball in $\M_{\tilde{\Ls}\vert\bb{A}'}(\R,\R^D)/\mathcal{N}_{\Ls}$. The desired representation follows from \eqref{eq:4.3.81} and \eqref{eq:4.3.84}.
Finally, the proof of the extreme-point representation in \eqref{eq:4.3.76} for outer norms $\norm{\cdot}_{\M,\Ww'}$ has a unique  feature. It is that the norm $\norm{\tilde{\bb{S}}\{\cdot\}}_{\M,\Zz'}$ in \eqref{eq:4.3.79}, now defined as 
\begin{equation}
\label{eq:206}
    \norm{\tilde{\bb{S}}\{\bb{m}\}}_{\M,\Zz'}:=\norm{\underset{\pi}{\text{sup}}\sum_{A\in\pi}\vert\tilde{\bb{S}}\{\bb{m}\}(A)\vert}_{\Zz'},
\end{equation}
 is \emph{not} an outer norm anymore. It is not an inner norm either. Nevertheless, a short calculation would show that the norm in \eqref{eq:206} is $\mathrm{weak}^{\star}$-continuous and equivalent to $\norm{\cdot}_{1,\M}=\norm{\cdot}_{\M,1}.$
These properties are required to ensure that $\mathcal{V}$ is non empty. Finally, the description of extreme points is proved as for inner norms, with an isometry-based argumentation.
\end{proof}

\begin{proof}[\textbf{Proof of Corollary \ref{coro:restrictedRT2}}]
Let $\bb{f}\in\M_{\tilde{\Ls}\vert\bb{A}}(\R,\R^D)$. It follows from
\begin{align}
    \Ls\{\bb{f}\}=(\bb{T}^{-1}\bb{A}^{\intercal}\bb{S}^{-1})\{\bb{m}\}\Leftrightarrow\tilde{\Ls}\{\bb{f}\}=(\bb{A}^{\intercal}\bb{S}^{-1})\{\bb{m}\}&\Leftrightarrow(\bb{A}\tilde{\Ls})\{\bb{f}\}=\bb{S}^{-1}\{\bb{m}\}\\
