\section{Convolution of Distributions}
\label{app:B}
\subsection{Convolution of Scalar Distributions}
The convolution $g\ast\psi\in\Dd(\R)$ of a scalar distribution $g\in\Dd'(\R)$ and a test function $\psi\in\Dd(\R)$ is defined as, 
\begin{equation}
\forall x\in\R:\quad\quad (g\ast\psi)(x)=\langle g^{\vee},\psi(\cdot+x)\rangle:=\langle g^{\vee}\ast\delta_{x},\psi\rangle.
\end{equation}
The convolution $g_1\ast g_2$ of two scalar distribution $(g_1,g_2)\in\mathcal{D}'(\R)^2$ is defined as \cite{beffa2024weakly}[Section 3.2]
\begin{equation}
    \forall\psi\in\mathcal{D}(\R):\quad\langle g_1\ast g_2,\psi\rangle=\langle g_1((\cdot)_1)\otimes g_2((\cdot)_2),\psi((\cdot)_1+(\cdot)_2)\rangle:=\int_{\R^2}g_1(x)g_2(y)\psi(x+y)\mathrm{d}x\mathrm{d}y,
\end{equation}
where the second equality is the informal statement of the central one. Alternatively, one can rely on Fubini's theorem for distributions \cite{treves2016topological} to establish the tensor-product-based definition
\begin{equation}
    \langle g_1\ast g_2,\psi\rangle=\langle g_2,g_1^{\vee}\ast\psi\rangle=\langle g_1,g_2^{\vee}\ast\psi\rangle.
\end{equation}
We summarize in Proposition \ref{prop:9} three properties of the convolution, all extracted from \cite{beffa2024weakly}[Section 3.2].
\begin{ Proposition }
\label{prop:9}
    Let $(g_1,g_2,g_3)\in\Dd'(\R)^3$ be three scalar distributions, either all compactly supported or all one-sided, and let $\ls$ be an ODO. Then the following holds:
    \begin{itemize}
        \item [] \emph{Commutativity} $\forall\psi\in\Dd(\R):\quad\langle g_1\ast g_2,\psi\rangle=\langle g_2\ast g_1,\psi\rangle$.
        \item [] \emph{Associativity} $\forall\psi\in\Dd(\R):\quad\langle (g_1\ast g_2)\ast g_3,\psi\rangle=\langle g_1\ast( g_2\ast g_3),\psi\rangle$.
        \item [] \emph{Differentiation}$\forall\psi\in\Dd(\R):\quad\langle \ls\{g_1\ast g_2\},\psi\rangle=\langle \ls\{g_1\}\ast g_2,\psi\rangle=\langle g_1\ast\ls\{g_2\},\psi\rangle$.
    \end{itemize}
\end{ Proposition }

\subsection{Convolution of Matrix-Valued Distributions}
First, the action of a matrix-valued distribution $\bb{G}\in\Dd'(\R,\R^{D_1\times D_2})$ on a matrix-valued test function $\bm{\Psi}\in\Dd(\R,\R^{D_1\times D})$ is such that 
\begin{multline}
    \langle\bb{G},\bm{\Psi}\rangle\in\R^{D_2\times D },\quad\text{and}\quad\forall1\leq d_2\leq D_2,\forall1\leq d\leq D:\\
    \left[\langle\bb{G},\bm{\Psi}\rangle\right]_{d_2,d_1}=\sum_{d_1}^{D_1}\langle\bb{G}^{\intercal}_{d_2,d_1},\Psi_{d_1,d}\rangle.
\end{multline}
The convolution of a matrix-valued distribution $\bb{G}\in\Dd'(\R,\R^{D_2\times D_1})$ with a matrix-valued test function $\bm{\Psi}\in\Dd(\R,\R^{D_1\times D})$ is defined as 
\begin{multline}
\bb{G}\ast\bb{\Psi}\in\Dd(\R,\R^{D_2\times D})\quad\text{with}\quad
    \forall1\leq d_2\leq D_2,1\leq d\leq D:\\
    [\bb{G}\ast\bm{\Psi}]_{d_2,d}=\sum_{d_1=1}^{D_1}\mathrm{G}_{d_2,d_1}\ast\Psi_{d_1,d}.
\end{multline}
In turn, the convolution of two matrix-valued distributions  $\bb{G}\in\Dd'(\R,\R^{D_1\times D_2})$ and $\bb{H}\in\Dd'(\R,\R^{D_2\times D_3})$ is defined as  
\begin{multline}
\bb{G}\ast\bb{H}\in\Dd'(\R,\R^{D_1\times D_3})\quad\text{with}\quad\forall1\leq d_1\leq D_1,1\leq d_3\leq D_3:\\
[\bb{G}\ast\bb{H}]_{d_1,d_3}=\sum_{d_2=1}^{D_2}\mathrm{G}_{d_1,d_2}\ast\mathrm{H}_{d_2,d_3}.
\end{multline}
We summarize in Proposition \ref{prop:10} four important properties of the convolution of matrix-valued distributions. 
\begin{ Proposition }
\label{prop:10}
Let $\bb{G}\in\Dd'(\R,\R^{D_1\times D_2})$, and $\bb{H}\in\Dd'(\R,\R^{D_2\times D_3})$, and $\bb{J}\in\Dd'(\R,\R^{D_3\times D_4})$ be three matrix-valued distributions either all compactly supported or all one-sided, and let $\Ls$ be an MDO of size $(D_1\times D_1)$. Then, the following holds $\forall\bb{\Psi}\in\Dd(\R,\R^{D_1\times D})$.
\begin{itemize}
    \item[] \emph{Adjoint}$\quad\left\langle\bb{G}\ast\bb{H},\bb{\Psi}\right\rangle=\left\langle\bb{H},\bb{G}^{\intercal,\vee}\ast\bb{\Psi}\right\rangle\quad\Rightarrow\quad\bb{G}^{\star}=\bb{G}^{\intercal,\vee}.$
    \item [] \emph{Associativity} $\quad\left\langle \bb{G}\ast\left(\bb{H}\ast\bb{J}\right),\bb{\Psi}\right\rangle=\left\langle \left(\bb{G}\ast\bb{H}\right)\ast\bb{J},\bb{\Psi}\right\rangle.$
    \item [] \emph{Differentiation} $\quad\left\langle \Ls\{\bb{G}\ast\bb{H}\},\bb{\Psi}\right\rangle=\left\langle \Ls\{\bb{G}\}\ast\bb{H},\bb{\Psi}\right\rangle=\left\langle \bb{G}\ast\bb{H},\Ls^{\star}\{\bb{\Psi}\}\right\rangle.$
    \item [] \emph{Bracket} $\left(\bb{G}^{\intercal}\ast\bm{\Psi}\right)(x)=\left\langle\bb{G}^{\vee}\ast\bb{I}\delta_{x},\bm{\Psi}\right\rangle.$

\end{itemize}
\end{ Proposition }
\begin{proof}[\textbf{Proof of Proposition \ref{prop:10}}]
\hfill\\
    \textbf{Adjoint.}
    We calculate that, $\forall1\leq d_3\leq D_3,\forall1\leq d\leq D,$
    \begin{align}
        \left[\left\langle\bb{G}\ast\bb{H},\bm{\Psi}\right\rangle \right]_{d_3,d}&=\sum_{d_1=1}^D\left\langle\left(\bb{G}\ast\bb{H}\right)^{\intercal}_{d_3,d_1},\Psi_{d_1,d}\right\rangle=\sum_{d_1,d_2=1,1}^{D_1,D_2}\left\langle \mathrm{H}_{d_2,d_3}\ast\mathrm{G}_{d_1,d_2},\Psi_{d_1,d}\right\rangle\\
        &=\sum_{d_1,d_2=1,1}^{D_1,D_2}\left\langle \mathrm{H}_{d_2,d_3},\mathrm{G}_{d_1,d_2}^{\vee}\ast\Psi_{d_1,d}\right\rangle=\sum_{d_2=1}^{D_2}\left\langle \mathrm{H}_{d_2,d_3},[\bb{G}^{\intercal,\vee}\ast\bm{\Psi}]_{d_2,d}\right\rangle\\
        &=\left\langle\bb{H},\bb{G}^{\intercal,\vee}\ast\bb{\Psi}\right\rangle.
    \end{align}
    \hfill\\
    \textbf{Associativity.} We calculate that, $\forall1\leq d_4\leq D_4$ and $\forall1\leq d\leq D,$
    \begin{align}
        \left[\langle \bb{G}\ast\left(\bb{H}\ast\bb{J}\right),\bb{\Psi}\rangle\right]_{d_4,d}&=\sum_{d_1=1}^{D_1}\langle[(\bb{H}\ast\bb{J})^{\intercal}\ast\bb{G}^{\intercal}]_{d_3,d_1},\Psi_{d_1,d}\rangle\\
        &=\sum_{d_1=1}^{D_1}\langle[(\bb{J}^{\intercal}\ast\bb{H}^{\intercal})\ast\bb{G}^{\intercal}]_{d_3,d_1},\Psi_{d_1,d}\rangle\label{eq:B.2.162}\\
        &=\sum_{d_1=1}^{D_1}\langle[\bb{J}^{\intercal}\ast(\bb{H}^{\intercal}\ast\bb{G}^{\intercal})]_{d_3,d_1},\Psi_{d_1,d}\rangle\\
        &=\sum_{d_1=1}^{D_1}\langle[\bb{J}^{\intercal}\ast(\bb{G}\ast\bb{H})^{\intercal}]_{d_3,d_1},\Psi_{d_1,d}\rangle\label{eq:B.2.163}\\
        &=\left[\langle (\bb{G}\ast\bb{H})\ast\bb{J},\bb{\Psi}\rangle\right]_{d_4,d},
    \end{align}
where the associativity of the convolution for scalar-valued distribution allowed us to deduce \eqref{eq:B.2.163} from \eqref{eq:B.2.162}.
\hfill\\\hfill\\
\textbf{Differentiation.} Observe that the action of the MDO $\Ls$ is exactly the same as the convolution with the distribution $\Ls\{\bb{I}\delta\}$. It follows that 
\begin{align}
    \left\langle \Ls\{\bb{G}\ast\bb{H}\},\bb{\Psi}\right\rangle&=\left\langle \Ls\{\bb{I}\delta\}\ast(\bb{G}\ast\bb{H}),\bb{\Psi}\right\rangle=\left\langle (\Ls\{\bb{I}\delta\}\ast\bb{G})\ast\bb{H},\bb{\Psi}\right\rangle=\left\langle \Ls\{\bb{G}\}\ast\bb{H},\bb{\Psi}\right\rangle.
\end{align}
We use the adjoint property to prove the second and third equalities of the Differentiation statement.
\hfill\\ \hfill\\
\textbf{Bracket.}
We  calculate that, $\forall1\leq d_2\leq D_2,\forall1\leq d,\leq D$,
   \begin{align}
       [\left(\bb{G}^{\intercal}\ast\bm{\Psi}\right)]_{d_2,d}(x)&=\sum_{d_1=1}^{D_1}(\mathrm{G}_{d_1,d_2}\ast\Psi_{d_1,d})(x)=\sum_{d_1=1}^{D_1}\left\langle\mathrm{G}_{d_ 1,d_2}^{\vee}\ast\delta_{x},\Psi_{d_1,d}\right\rangle\\
       &=\sum_{d_1=1}^{D_1}\left\langle\left[\bb{G}^{\vee}\ast\bb{I}\delta_{x}\right]_{d_1,d_2},\Psi_{d_1,d}\right\rangle=\left[\left\langle\left(\bb{G}^{\vee}\ast\bb{I}\delta_{x}\right),\bb{\Psi}\right\rangle\right]_{d_2,d}\\
       &=\left[\left\langle\bb{G}^{\vee}\ast\bb{I}\delta_{x},\bb{\Psi}\right\rangle\right]_{d_2,d}.
   \end{align}
\end{proof}
