\section{ABP fit within large deviation sfl RDT}
\label{sec:randlincons}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


One first  observes that the ground state free energy from (\ref{eq:limlogpartfunsqrtaa0}) is clearly a function of blirp $\y^TG\x$. To  connect $f_{sq}$ and blirp results from \cite{Stojnicnflldp25,Stojnicsflldp25}, we follow \cite{Stojnichopflrdt23,Stojnicbinperflrdt23,Stojnicnegsphflrdt23} and start by introducing a few needed technical preliminaries. Let $r$ be a positive integer (i.e., let $r\in\mN$) and for $k\in\{1,2,\dots,r+1\}$ consider real scalars $\beta,p\geq 0$, and $s$, sets $\cX,\bar{\cX}\subseteq \mR^n$, and $\cY\subseteq \mR^m$, function $f_S(\cdot):\mR^n\rightarrow R$, and vectors $\p=[\p_0,\p_1,\dots,\p_{r+1}]$, $\q=[\q_0,\q_1,\dots,\q_{r+1}]$, and $\c=[\c_0,\c_1,\dots,\c_{r+1}]$ such that
 \begin{eqnarray}\label{eq:hmsfl2}
1=\p_0\geq \p_1\geq \p_2\geq \dots \geq \p_r\geq \p_{r+1} & = & 0 \nonumber \\
1=\q_0\geq \q_1\geq \q_2\geq \dots \geq \q_r\geq \q_{r+1} & = &  0,
 \end{eqnarray}
with $\c_0=1$, $\c_{r+1}=0$. Also, let ${\mathcal U}_k\triangleq [u^{(4,k)},\u^{(2,k)},\h^{(k)}]$  where the elements of  $u^{(4,k)}\in\mR$, $\u^{(2,k)}\in\mR^m$, and $\h^{(k)}\in\mR^n$ are independent standard normals. Define function
  \begin{eqnarray}\label{eq:fl4}
\psi_{S,\infty}(f_{S},\p,\q,\c,s)  =
 \mE_{G,{\mathcal U}_{r+1}} \frac{1}{n\c_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_3}\lp\mE_{{\mathcal U}_2} \lp  \sum_{i_3=1}^{l} \lp  \mE_{{\mathcal U}_1} Z_{S,\infty}  \rp^p \rp^{\c_2}\rp^{\frac{\c_3}{\c_2}}\rp^{\frac{\c_4}{\c_3}} \dots \rp^{\frac{\c_{r}}{\c_{r-1}}}\rp, \nonumber \\
 \end{eqnarray}
with
\begin{eqnarray}\label{eq:fl5}
Z_{S,\infty} & \triangleq & e^{D_{0,S,\infty}} \nonumber \\
 D_{0,S,\infty} & \triangleq  & \max_{\x\in\cX,\|\x\|_2=x} s \max_{\y\in\cY,\|\y\|_2=y}
 \lp \sqrt{n} f_{S}
+\sqrt{n}  y    \lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x
+ \sqrt{n} x \y^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}\rp \rp \nonumber  \\
 b_k & \triangleq & b_k(\p,\q)=\sqrt{\p_{k-1}-\p_k} \nonumber \\
c_k & \triangleq & c_k(\p,\q)=\sqrt{\q_{k-1}-\q_k}.
 \end{eqnarray}
With all the above technicalities in place, one can then recall on the following theorem -- certainly one of the key components of sfl LD RDT.
\begin{theorem} \cite{Stojnicsflldp25}
\label{thm:thmsflrdt1}  Consider large $n$ linear regime where  $\alpha=\lim_{n\rightarrow\infty} \frac{m}{n}$ remains constant as  $n$ grows and let $G\in\mR^{m\times n}$ have independent standard normal elements. Let three sets  $\cX,\bar{{\mathcal X}} \subseteq \mR^n$ and $\cY\subseteq \mR^m$ with unit norm elements  and function $f_{\bar{\x}}(\cdot):R^{3n+m}\rightarrow R$ be given. Assume the complete sfl LD RDT frame from \cite{Stojnicsflldp25} and set
\begin{align}\label{eq:thmsflrdt2eq1}
   \psi_{rp} & \triangleq  -\log\lp \sum_{\bar{\x}\in \bar{{\mathcal X}}}
   \lp  \sum_{\x\in {\mathcal X}  }  \lp  \sum_{\y\in {\mathcal Y}  }   e^{ \beta  \lp f_{\bar{\x}}+\y^TG\x \rp } \rp^s \rp^p  \rp
   \qquad  \mbox{(\bl{\textbf{random primal}})} \nonumber \\
   \psi_{rd}(\p,\q,\c,s) & \triangleq    \frac{1}{2}   \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \p_{k-1}\q_{k-1}
   -\p_{k}\q_{k}
  \Bigg.\Bigg)
\c_k \omega(k;p)
  - \psi_{S,\infty}(f_{\bar{\x}},\p,\q,\c,s) \hspace{.23in} \mbox{(\bl{\textbf{fl random dual}})}.
 \end{align}
 For $\hat{\p}_0\rightarrow 1$, $\hat{\q}_0\rightarrow 1$, and $\hat{\c}_0\rightarrow 1$, $\hat{\p}_{r+1}=\hat{\q}_{r+1}=\hat{\c}_{r+1}=0$, let the non-fixed parts of $\hat{\p}$, $\hat{\q}$, and  $\hat{\c}$ satisfy
\begin{eqnarray}\label{eq:thmsflrdt2eq2}
   \frac{d \psi_{rd}(\p,\q,\c,s)}{d\p} =
   \frac{d \psi_{rd}(\p,\q,\c,s)}{d\q} =     \frac{d \psi_{rd}(\p,\q,\c,s)}{d\c} =  0.
 \end{eqnarray}
 Then,
\begin{eqnarray}\label{eq:thmsflrdt2eq3}
    \lim_{n\rightarrow\infty} \frac{\mE_G  \psi_{rp}}{n}
  & = &
 \lim_{n\rightarrow\infty} \psi_{rd}(\hat{\p},\hat{\q},\hat{\c},s) \qquad \mbox{(\bl{\textbf{strong sfl random duality}})},\nonumber \\
 \end{eqnarray}
where $\psi_{S,\infty}(\cdot)$ is as in (\ref{eq:fl4})-(\ref{eq:fl5}).
 \end{theorem}
\begin{proof}
  Follows immediately from Corollary 1 in \cite{Stojnicsflldp25}.
 \end{proof}





