While the  mathematical form from Theorem \ref{thm:thmsflrdt1} is fairly elegant it becomes  practically useful only if all associated quantities can be evaluated. As we will see below, already on the second level of lifting ($r=2$), one obtains results that are not only in an excellent agreement with replica predictions but remarkably accurately agree with the presumed BP's algorithmic hardness.

After taking binary cube sets $\cX=\bar{{\mathcal X}}=\mB^n = \{-\frac{1}{\sqrt{n}},\frac{1}{\sqrt{n}}\}^n$ and the unit sphere $\cY=\mS^m$ together with $f_{\bar{\x}} (\x) =  \beta_z(\1^Th(\z-\kappa) - m ) -\y^T\z
+\nu\bar{\x}^T\x -\nu\bar{\delta}  $, $\beta,\beta_z, p\rightarrow\infty$, and $\c_k\rightarrow\frac{\c_k}{p}, k>1$, in Theorem \ref{thm:thmsflrdt1}, we observe that the \emph{random dual} becomes
\begin{align}\label{eq:prac1}
    \psi_{rd}(\p,\q,\c,s) & \triangleq    \frac{1}{2}    \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \p_{k-1}\q_{k-1}
   -\p_{k}\q_{k}
  \Bigg.\Bigg)
\c_k
  - \psi_{S,\infty}(f_{\bar{\x}},\p,\q,\c,s). \nonumber \\
  & =   \frac{1}{2}    \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \p_{k-1}\q_{k-1}
   -\p_{k}\q_{k}
  \Bigg.\Bigg)
\c_k
  - \frac{1}{n}\varphi(D^{(bin)}(\bar{\x},s)) - \frac{1}{n}\varphi(D^{(sph)}(\bar{\x},s)), \nonumber \\
  \end{align}
where analogously to (\ref{eq:fl4})-(\ref{eq:fl5})
  \begin{eqnarray}\label{eq:prac2}
\varphi(D,\c) & = &
 \mE_{G,{\mathcal U}_{r+1}} \frac{1}{\c_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_3}\lp\mE_{{\mathcal U}_2} \lp
  \max_{\bar{\x}\in\bar{{\mathcal X}}} \mE_{{\mathcal U}_{1}} e^{D}  \rp^{\c_2}\rp^{\frac{\c_3}{\c_2}}\rp^{\frac{\c_4}{\c_3}} \dots \rp^{\frac{\c_{r}}{\c_{r-1}}}\rp, \nonumber \\
  \end{eqnarray}
and
\begin{eqnarray}\label{eq:prac3}
D^{(bin)}(\bar{\x},s) & = & \max_{\x\in\cX} \lp   s\sqrt{n}
   \lp \lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x
+\nu \bar{\x}^T\x -\nu \bar{\delta}
\rp
     \rp
    \nonumber \\
  D^{(sph)}(s) & =  &  \max_{\z} s \max_{\y\in\cY}
\lp \sqrt{n} \lp
\beta_{\z} \sum_{i_1=1}^{l} (1-h(\z_{i_1}-\kappa))  +  \y^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}  -\z  \rp \rp \rp.
 \end{eqnarray}
One then also has
\begin{eqnarray}\label{eq:prac4}
D^{(bin)}(\bar{\x},s) & = & \max_{\x\in\cX}   \lp s\sqrt{n}    \lp  \lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T  +\nu\bar{\x} \rp \x \rp =
       \sum_{i=1}^n \left |s \lp  \lp\sum_{k=1}^{r+1}c_k\h_i^{(k)}\rp  +\nu\bar{\x}_i  \rp   \right |
       \nonumber \\
& = &     \sum_{i=1}^n \left | \lp\sum_{k=1}^{r+1}c_k\h_i^{(k)}\rp   +\nu\bar{\x}_i   \right |
=  \sum_{i=1}^n D^{(bin)}_i(\bar{\x},c_k) - \nu\bar{\delta} , \nonumber \\
 \end{eqnarray}
with
\begin{eqnarray}\label{eq:prac5}
D^{(bin)}_i(\bar{\x},c_k)=\left |  \lp\sum_{k=1}^{r+1}c_k\h_i^{(k)}\rp    +\nu\bar{\x}_i  \right |.
\end{eqnarray}
Moreover,
  \begin{eqnarray}\label{eq:prac6}
\varphi(D^{(bin)}(\bar{\x},s),\c) & = &
n \mE_{G,{\mathcal U}_{r+1}} \frac{1}{\c_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_3}\lp\mE_{{\mathcal U}_2} \lp
  \max_{\bar{\x}_i \in\bar{{\mathcal X}}} \mE_{{\mathcal U}_{1}} e^{D_1^{(bin)}(\bar{\x},c_k)}  \rp^{\c_2}\rp^{\frac{\c_3}{\c_2}}\rp^{\frac{\c_4}{\c_3}} \dots \rp^{\frac{\c_{r}}{\c_{r-1}}}\rp
\nonumber \\
& &
 - \nu\bar{\delta}
\nonumber \\
    & =  &  n\varphi(D_1^{(bin)}(\bar{\x},c_k),\c)  - \nu\bar{\delta}. \nonumber \\
   \end{eqnarray}
We then analogously find
\begin{eqnarray}\label{eq:prac7aa0}
   D^{(sph)}(s) &  =  &    s  \sqrt{n}   \left \| \min \lp - \kappa\1 +\sum_{k=2}^{r+1}b_k\u^{(2,k)},0 \rp  \right \|_2.
 \end{eqnarray}
 Given statistical symmetry, for all practical purposes we can alternatively take
\begin{eqnarray}\label{eq:prac7aa0}
   D^{(sph)}(s) &  =  &    s  \sqrt{n}   \left \| \max \lp \kappa\1 +\sum_{k=2}^{r+1}b_k\u^{(2,k)},0 \rp  \right \|_2.
 \end{eqnarray}
Utilization of the \emph{square root trick} introduced  in \cite{StojnicMoreSophHopBnds10,StojnicLiftStrSec13,StojnicGardSphErr13,StojnicGardSphNeg13} gives as in \cite{Stojnicbinperflrdt23}'s (30) nd (31)
 \begin{eqnarray}\label{eq:prac9}
   D^{(sph)}(s)
   & =  &  s \min_{\gamma_{sq}} \lp \sum_{i=1}^{m} D_i^{(sph)}(b_k)+\gamma_{sq}n \rp, \nonumber \\
 \end{eqnarray}
with
\begin{eqnarray}\label{eq:prac10}
   D_i^{(sph)}(b_k)= \frac{\max \lp \kappa + \sum_{k=2}^{r+1}b_k\u_i^{(2,k)},0  \rp^2}{4\gamma_{sq}}.
 \end{eqnarray}

After  taking $s=-1$ one can finally connect the ground state energy, $f_{sq}$ given in (\ref{eq:limlogpartfunsqrt}), and the random primal, $\psi_{rp}(\cdot)$, given in Theorem \ref{thm:thmsflrdt1}. In particular, for optimal $\hat{\nu}$ and $\hat{\gamma}_{sq}$ (those that maximize and minimize $\psi_{rd}$, respectively) we have
\begin{eqnarray}\label{eq:negprac11}
f_{sq}(\infty)
& = &
\lim_{n,\beta,\beta_z,p\rightarrow\infty} \frac{\mE_G  \log \lp \sum_{\bar{\x}\in\mB^n }  \lp
\sum_{ \x\in\mB^n,\z  }  \min_{\nu} \lp \sum_{\y\in\mS^m  }e^{\beta \lp f_{\bar{\x}} (\x)  +   \y^T G\x    \rp   }    \rp^{-1}
 \rp^p   \rp  }{np}
\nonumber \\
  & = &
 -   \lim_{n,\beta,\beta_z,p\rightarrow\infty} \frac{\mE_G \max_{\nu} \psi_{rp}}{n}
   =
 - \lim_{n,\beta,\beta_z,p\rightarrow\infty} \max_{\nu} \min_{\gamma_{sq}}\psi_{rd}(\hat{\p},\hat{\q},\hat{\c},-1),
\end{eqnarray}
where the non-fixed parts of $\hat{\p}$, $\hat{\q}$, and  $\hat{\c}$ satisfy
\begin{eqnarray}\label{eq:negprac12}
   \frac{d \psi_{rd}(\p,\q,\c,-1)}{d\p} =
   \frac{d \psi_{rd}(\p,\q,\c,-1)}{d\q} =
   \frac{d \psi_{rd}(\p,\q,\c,-1)}{d\c} =  0.
 \end{eqnarray}
Relying on (\ref{eq:prac1})-(\ref{eq:prac10}), one then finds
 \begin{eqnarray}
 \lim_{n\rightarrow\infty} \psi_{rd}(\hat{\p},\hat{\q},\hat{\c},-1) =  \bar{\psi}_{rd}(\hat{\p},\hat{\q},\hat{\c},\hat{\nu},\hat{\gamma}_{sq},-1),
  \label{eq:negprac12a}
\end{eqnarray}
where
\begin{eqnarray}\label{eq:negprac13}
    \bar{\psi}_{rd}(\p,\q,\c,\nu,\gamma_{sq},-1)   & = &  \frac{1}{2}    \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \p_{k-1}\q_{k-1}
   -\p_{k}\q_{k}
  \Bigg.\Bigg)
\c_k
\nonumber \\
& & +\nu\bar{\delta}  - \varphi(D_1^{(bin)}(\bar{\x},c_k(\p,\q))) +\gamma_{sq}- \alpha\varphi(-D_1^{(sph)}(b_k(\p,\q))).\nonumber \\
  \end{eqnarray}
Combining  (\ref{eq:negprac11}), (\ref{eq:negprac12a}), and (\ref{eq:negprac13}) we obtain
 \begin{eqnarray}
f_{sq}(\infty)
& = &
\lim_{n,\beta,\beta_z,p\rightarrow\infty} \frac{\mE_G  \log \lp \sum_{\bar{\x}\in\mB^n }  \lp
\sum_{ \x\in\mB^n,\z  }  \min_{\nu} \lp \sum_{\y\in\mS^m  }e^{\beta \lp f_{\bar{\x}} (\x)  +   \y^T G\x    \rp   }    \rp^{-1}
 \rp^p   \rp  }{np}
\nonumber \\
    &  = &
 -\lim_{n\rightarrow\infty} \psi_{rd}(\hat{\p},\hat{\q},\hat{\c},-1)
 =  - \bar{\psi}_{rd}(\hat{\p},\hat{\q},\hat{\c},\hat{\nu},\hat{\gamma}_{sq},-1) \nonumber \\
 & = & -\Bigg ( \Bigg .  \frac{1}{2}    \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \hat{\p}_{k-1}\hat{\q}_{k-1}
   -\hat{\p}_{k}\hat{\q}_{k}
  \Bigg.\Bigg)
\hat{\c}_k
\nonumber \\
& &
+\hat{\nu}\bar{\delta}
  - \varphi(D_1^{(bin)}(\bar{\x}\,c_k(\hat{\p},\hat{\q}))) + \hat{\gamma}_{sq} - \alpha\varphi(-D_1^{(sph)}(\b_k(\hat{\p},\hat{\q})))\Bigg .\Bigg ).
  \label{eq:negprac18}
\end{eqnarray}

We summarize the above discussion in the following theorem.
\begin{theorem}
  \label{thme:negthmprac1}
Consider large $n$ linear regime with $\alpha=\lim_{n\rightarrow\infty} \frac{m}{n}$ and  assume complete sfl LD RDT setup of \cite{Stojnicsflldp25}. Let
  $\varphi(\cdot)$ and $\bar{\psi}(\cdot)$ be as in (\ref{eq:prac2}) and (\ref{eq:negprac13}), respectively. Also, take the ``fixed'' parts of $\hat{\p}$, $\hat{\q}$, and $\hat{\c}$ as $\hat{\p}_1\rightarrow 1$, $\hat{\q}_1\rightarrow 1$, $\hat{\c}_1\rightarrow 1$, $\hat{\p}_{r+1}=\hat{\q}_{r+1}=\hat{\c}_{r+1}=0$, and let their ``non-fixed'' parts  satisfy
  \begin{eqnarray}\label{eq:negthmprac1eq1}
   \frac{d \bar{\psi}_{rd}(\p,\q,\c,\nu,\gamma_{sq},-1)}{d\p} & = &
   \frac{d \bar{\psi}_{rd}(\p,\q,\c,\nu,\gamma_{sq},-1)}{d\q} =     \frac{d \bar{\psi}_{rd}(\p,\q,\c,nu,\gamma_{sq},-1)}{d\c} =  0 \nonumber \\
   \frac{d \bar{\psi}_{rd}(\p,\q,\c,\nu,\gamma_{sq},-1)}{d\nu} & = &
   \frac{d \bar{\psi}_{rd}(\p,\q,\c,\nu,\gamma_{sq},-1)}{d\gamma_{sq}} =  0.
 \end{eqnarray}
Moreover, set
\begin{eqnarray}\label{eq:prac17}
c_k(\hat{\p},\hat{\q})  & = & \sqrt{\hat{\q}_{k-1}-\hat{\q}_k} \nonumber \\
b_k(\hat{\p},\hat{\q})  & = & \sqrt{\hat{\p}_{k-1}-\hat{\p}_k}.
 \end{eqnarray}
 Then
 \begin{eqnarray}
f_{sq}(\infty)
& = &   -
  \Bigg.\Bigg (
 \frac{1}{2}    \sum_{k=1}^{r+1}\Bigg(\Bigg.
   \hat{\p}_{k-1}\hat{\q}_{k-1}
   -\hat{\p}_{k}\hat{\q}_{k}
  \Bigg.\Bigg)
\hat{\c}_k
\nonumber \\
& &
+\hat{\nu}\bar{\delta}
  - \varphi(D_1^{(bin)}(\bar{\x},c_k(\hat{\p},\hat{\q})),\hat{\c}) + \hat{\gamma}_{sq} - \alpha\varphi(-D_1^{(sph)}(\bar{\x},b_k(\hat{\p},\hat{\q})),\hat{\c})
    \Bigg.\Bigg).
  \label{eq:negthmprac1eq2}
\end{eqnarray}
\end{theorem}
\begin{proof}
Follows immediately from the previous discussion and Theorem \ref{thm:thmsflrdt1}.
\end{proof}


