%a_{T1} & a_{T2}&
%\ldots & 0\\
%\end{pmatrix}\begin{pmatrix} f_1 \\ f_2 \\ \ldots \\ 0\end{pmatrix}
%\right)\\
%=\left(\begin{pmatrix} \overline{a_{11}} & \overline{a_{21}}&
%\ldots & \overline{a_{T1}}\\
%\overline{a_{12}} & \overline{a_{22}}&
%\ldots & \overline{a_{T2}}\\
%\ldots & \ldots &
%\ldots&  \ldots\\
