%\ldots & 0\\
%a_{21} & a_{22}&
%\ldots & 0\\
%\ldots & \ldots &
%\ldots&  0\\
%a_{T1} & a_{T2}&
%\ldots & 0\\
%\end{pmatrix}\begin{pmatrix} f_1 \\ f_2 \\ \ldots \\ 0\end{pmatrix},\begin{pmatrix} f_1 \\ f_2 \\ \ldots \\ 0\end{pmatrix}
%\right)
%\end{eqnarray*}

%Then the fact that $C_{T-1}$ is also an isomorphism follows from
%\begin{equation}
%P_{T-1}C_TP_{T-1}=P_{T-1}U^T(P_{T-1}+P_T)\operatorname{diag}\{d_1,\ldots,
%d_T\}(P_{T-1}+P_T)UP_{T-1}.
%\end{equation}
%where $P_{T-1}$ is a projector on $(x_1,\ldots x_{T-1})$ and $P_T$
%is a projector on $x_T$. Then writing down the quadratic form we
%have
%\begin{equation}
%\left(C_TP_{T-1}f,P_{T-1}g\right)=\left(\operatorname{diag}\{d_1,\ldots,
%d_T\}UP_{T-1}f,UP_{T-1}g\right)
