	\begin{proof}[Proof of Theorem~\ref{th:KP-conv}]
		Proposition~\ref{prop:deformations-KP} implies that we can deform $\{\phi_n\}$ while preserving the KP integrability of the system, transforming it into $\{\overline{\phi}_n \coloneqq \delta_{n,2} B_0\}$. Simultaneously, the differentials $\{\omega_n\}$ undergo a corresponding deformation to a new set $\{\overline{\omega}_n\}$.

		Since, according to Proposition~\ref{prop:def-omegas}, the deformations of $\{\omega_n\}$ that accompany the deformations of $\{\phi_n\}$ also preserve KP integrability, it follows that the KP integrability of $\{\overline{\omega}_n\}$ implies the KP integrability of $\{\omega_n\}$.


On the other hand, in the case $\overline{\phi}_n - \delta_{n,2} B_0=0$, the contribution of all $\phi$-vertices in the graph summation formula of Definition~\ref{def:convolution-system} vanish and we have
%		Finally, Lemma~\ref{lem:Gamma-accent} asserts that using the weights of the $\phi$-vertices given by $\{\overline{\phi}_n \coloneqq \delta_{n,2} B_0\}$ in Equation~\eqref{eq:omega_n-without-tilde} is equivalent to using $\phi$-vertex weights that are identically zero in Equation~\eqref{eq:GraphicalFormulaomega}. Consequently, we obtain 
$\{\overline{\omega}_n\} = \{\psi_n\}$. By assumption, $\{\psi_n\}$ is KP integrable, which implies that $\{\overline{\omega}_n\}$ is also KP integrable, and thus $\{\omega_n\}$ must be as well.
	\end{proof}

\section{Blobbed topological recursion}

\label{sec:Blobbed}

\subsection{Generalized topological recursion}\label{sec:GenTR}
Topological recursion of Chekhov--Eynard--Orantin \cite{CEO,EO-1st} associates a system of meromorphic differentials $\omega^{(g)}_n$, $g\geq 0$, $n\geq 1$, $2g-2+n\geq 0$, to an input data that consists of a Riemann surface $\Sigma$, a finite set of points $\cP\subset \Sigma$, two meromorphic functions $x$ and $y$ on $\Sigma$  such that the zeroes $\restr{}{q}dx = 0$ are simple and $\restr {} {q} {dy}\not= 0$ for each $q\in \cP$, and a bi-differential $B$ with the double pole on the diagonal with bi-residue $1$.
It has its origin in the computation of the cumulants of the matrix models, and by now it has multiple striking applications in algebraic geometry, enumerative combinatorics, and mathematical physics.

The original setup was generalized in~\cite{alexandrov2024degenerateirregulartopologicalrecursion} to the situation when~$dx$ and~$dy$ are meromorphic differentials with arbitrary behavior at the points of~$\cP$. We review here these definitions in the most general setting of local generalized topological recursion.

\begin{definition}\label{def:GendTR}
The initial data of the generalized topological recursion is a quintuple $(\Sigma,dx,dy,\cP,B)$ where
\begin{itemize}
\item $\Sigma$ is a (not necessarily compact) smooth Riemann surface (a complex curve);
\item $B$ is a symmetric meromorphic bidifferential on $\Sigma^2$ with a pole on the diagonal with biresidue~$1$ and holomorphic in the complement to the diagonal;
\item $\cP\subset\Sigma$ is a finite set; its elements are called \emph{key points};
\item $dx$ and $dy$ are meromorphic $1$-forms defined as germs (or even formal Laurent expansions) at the points of $\cP$.
\end{itemize}
\end{definition}

\begin{remark}
Note that we do not assume that $dx$ or $dy$ extend globally to $\Sigma$, but we require that $B$ is globally defined. On the other hand, we can assume that $\Sigma$ is a union of small disks centered at the key points. In this case $B$ is also defined locally near the key points only.	
\end{remark}

 Denote by $p\mapsto \mathfrak{g}^t_{\partial_x}p$ the time~$t$ phase flow of the vector field $\partial_x$ dual to the differential $dx$. Notice that for any meromorphic function~$f$ we have
\begin{equation}
f(\mathfrak{g}^t_{\partial_x}p)=e^{t\partial_x}f(p),\qquad x(\mathfrak{g}^t_{\partial_x}p)=x(p)+t.
\end{equation}


\begin{definition} We say that a system of differentials
\begin{equation}
\omega_n=\sum_{\substack{g\ge0\\(g,n)\ne(0,1)}}\hbar^{2g-2+n}\omega^{(g)}_n, \qquad n\geq 1,	
\end{equation}
  satisfies generalized topological recursion for the input data $(\Sigma,dx,dy,\cP,B)$ if
$\omega^{(0)}_2=B$ and the following two conditions hold:
\begin{itemize}
\item \emph{Generalized loop equations}: the differential
\begin{equation}\label{eq:loop-generalized}
\sum_{r\ge0}\bigl(-d\tfrac1{dy}\bigr)^r[u^r]e^{u(\cS(u\hbar\partial_x)-1)y}
\restr{q^\pm}{\mathfrak{g}^{\pm\frac{u\hbar}{2}}_{\partial_x}p}\cW_n(q^+,q^-;p_{\set n})
\end{equation}
is holomorphic in $p$ at any key point $q\in\cP$ for all $p_1,\dots,p_n$, where $x=x(p)$, and $y=y(p)$, $u$ is a new formal variable, and the extended differentials $\cW_n$ are defined by~\eqref{eq:cW-def1}--\eqref{eq:cW-def2}.
\item \emph{Projection property}: we have
\begin{equation}\label{eq:proj}
\omega^{(g)}_{n}(p,p_{\set {n-1}})=\sum_{q\in\cP}\res_{\tilde p=q} \omega^{(g)}_{n}(\tilde p,p_{\set {n-1}})\int_q^{\tilde p}B(\cdot,p),
\qquad 2g-2+n>0.
\end{equation}
\end{itemize}
\end{definition}

\begin{remark} These two conditions indeed allow to reconstruct the differentials $\omega^{(g)}_n$ recursively. Namely, the loop equations determine uniquely the principal parts of the poles of~$\omega^{(g)}_n$ at the key points with respect to the first argument inductively from the known differentials $\omega^{(g')}_{n'}$ with $2g'-2+n'<2g-2+n$, while the projection property recovers $\omega^{(g)}_n$ from its polar parts.
\end{remark}

\begin{remark}
 The resulting differentials $\omega^{(g)}_n$ are symmetric, meromorphic, and the only poles they may have are the key points in each argument.

In the case when the spectral curve data is nondegenerate, that is, $dx$ has simple zeroes and $dy$ is holomorphic and nonvanishing at the key points, the differentials of the generalized topological recursion coincide with those of usual CEO recursion.	
\end{remark}


\begin{remark}
It is sometimes convenient to define $\omega^{(0)}_1=y\,dx$, for some $y$ defined as a local primitive of $dy$. However, this differential is not always globally defined and univalued. Therefore, we prefer not to include the $(0,1)$-term to $\omega_1$, by convention. Instead, the contribution of the differentials $dx$ and $dy$ to the generalized loop equations (and, as a consequence, to the relations of the recursion) is included explicitly in~\eqref{eq:loop-generalized}.

On the other hand, the unstable term $\omega^{(0)}_2=B$ is included to $\omega_2$. Notice that the projection property is not satisfied for $(g,n)=(0,2)$: the right hand side of~\eqref{eq:proj} gives zero in this case.
\end{remark}

\begin{remark}
Let us write at a key point~$q\in\cP$ in some local coordinate $z$ centered at $q$
\begin{equation}
dx=a\,z^{r-1}dz\,(1+O(z)),\qquad
dy=b\,z^{s-1}dz\,(1+O(z)),\qquad a\,b\ne0.
\end{equation}
The point $q$ is called \emph{special} if $r+s>0$ and $(r,s)\ne(1,1)$, and \emph{non-special} otherwise. Then the non-special key points do not contribute to the topological recursion and they can be excluded from~$\cP$ without changing the differentials of topological recursion. Thus, one can assume without loss of generality that all key points are special.
\end{remark}

\subsection{Changing the set of key points}

Assume that the set $\cP$ of key points in the initial data of topological recursion splits as $\cP=\cP'\sqcup\cP''$.  Denote by $\psi_n$, $\phi_n$ and $\omega_n$ the differentials of (generalized) topological recursion with the spectral curve data $(\Sigma,dx,dy,\cP',B)$, $(\Sigma,dx,dy,\cP'',B)$, and $(\Sigma,dx,dy,\cP,B)$, respectively, that is, we use the same differentials $dx,dy,B$ but different sets of key points, see \cite{alexandrov2024degenerateirregulartopologicalrecursion} for details.

\begin{proposition}\label{prop:cP-cut} Assume that the curve $\Sigma$ is compact and $B$ is the standard Bergman kernel. 
The differentials $\tilde\omega_n=\omega_n-\delta_{n,2}B$ coincide with the convolution differentials of the systems of differentials $\tilde\psi_n=\psi_n-\delta_{n,2}B$ and $\tilde\phi_n=\phi_n-\delta_{n,2}B$.
\end{proposition}

This proposition means that for computing differentials of topological recursion it is sufficient to apply recursion itself in those cases with a single key point only. Then the TR differentials for the case of several key points are expressed in terms of those with one key point by explicit combinatorial expressions.

For the reformulation in terms of potential given in Sec. \ref{S_potentials}, it means that the potential for the generalized TR can be given as a Moyal-type product of the potentials associated with the key points. This is a reformulation of the Givental decomposition, there the diagonal part of the Givental operators is included into the definitions of the elementary potentials, and only the non-diagonal part describes interaction between different key points. Moreover, here we naturally can consider types of decompositions associated with different collections of the key points, which is close to the observations of \cite{AMM1,AMM2} in the context of matrix models and Virasoro constraints.

\begin{proof} Note that the projection property for $\{\omega_n\}$ follows manifestly from the projection properties for $\{\psi_n\}$ and $\{\phi_n\}$, and the structure of the convolution formula.

In order to prove the generalized loop equations at $q\in \cP''$ we use the same trick as in the proof of Proposition~\ref{prop:def-omegas}. Namely, we notice that $\cW^\omega_n(p^+,p^-;p_{\set n})$ can be represented as a linear combination of operators applied to
$\{\cW^\phi_m(p^+,p^-;p'_{\set m})\}$ that act only in the variables associated to $p'_1,p'_2,\dots$. Hence, the expression~\eqref{eq:loop-generalized}  in the generalized loop equations for $\{\omega_n\}$ is represented as a linear combination of operators applied to
\begin{equation}\label{eq:loop-generalized-phi}
	\sum_{r\ge0}\bigl(-d\tfrac1{dy}\bigr)^r[u^r]e^{u(\cS(u\hbar\partial_x)-1)y}
	\restr{q^\pm}{\mathfrak{g}^{\pm\frac{u\hbar}{2}}_{\partial_x}p}\cW^\phi_n(q^+,q^-;p'_{\set m})
\end{equation}
that act only on $p'_1,p'_2,\dots,p'_m$. Note that these expressions are finite for each fixed $n$ and degree of $\hbar$ (cf.~Remark~\ref{rem:topological-expansion}). Thus, the generalized loop equations for $\{\phi_n\}$ imply the generalized loop equations for $\{\omega_n\}$ at the points $q\in\cP''$.

In order to deal with the points $q\in\cP'$ we note that the combinatorics of graphs in the argument of Proposition~\ref{prop:def-omegas} works also with the interchanged roles of the differentials $\{\psi_n\}$ and $\{\phi_n\}$. To this end, we recall Proposition~\ref{prop:duality-convolution-global} --- we have a global setup, and  the residues of $\psi_n$ and $\phi_n$ indeed vanish, since these differential are obtained by topological recursion, so this proposition is applicable. Thus we can change the convolution operation on the edges to use the residues at the points of $\cP''$.  Hence, the argument above with the roles of $\{\psi_n\}$ and $\{\phi_n\}$ interchanged proves the generalized loop equations for $\{\omega_n\}$ at the points $q\in\cP'$.
\end{proof}

\begin{remark} It is important to stress that Proposition~\ref{prop:cP-cut} does not necessarily hold for a non-compact spectral curve. An important requirement is that we can change the convolution operation from the residues at the points of $\cP'$ to the points of $\cP''$, and this requires that the projection formula generates no singularities of the analytic extension of the involved differentials. In short, we can apply Proposition~\ref{prop:cP-cut} with locally defined $dx$ and $dy$ once we know that $B$ extends to the standard Bergman kernel on a global curve.
\end{remark}

\subsection{Definition of the blobbed topological recursion}\label{sec:TR-blobbed}

We are in the setting of Section~\ref{sec:GenTR}, that is, $\Sigma$ is a possibly noncompact Riemann surface and $\cP\subset\Sigma$ is a finite set.

Generalizing the situation of Proposition~\ref{prop:cP-cut}, consider an arbitrary system of symmetric differentials $\{\phi_n\}_{n\geq 1}$ called \emph{blobs}, where $\phi_n$ expands as a formal power series in $\hbar$, $\phi_n = \sum_{d=0}^\infty \hbar^d \phi_n^{\langle d\rangle}$. We assume that all $\phi_n^{\langle d \rangle}$ are holomorphic on $\Sigma^n$ except for $\phi_2^{\langle 0 \rangle}$, whose only singularity is the double pole on the diagonal with bi-residue $1$.

\begin{definition}\label{def:blobbedTR}

We associate to the input data $(\Sigma,dx,dy,\cP,\{\phi_n\}_{n\geq 1})$ a system of meromorphic differentials $\{\omega^{\langle d\rangle}_n\}$, $d\geq 0$, $n\geq 1$, which we call the \emph{blobbed TR differentials}, defined as follows.

\begin{itemize}
	\item
First, we choose an arbitrary Bergman kernel $B$ on $\Sigma^2$. Let $\{\psi^{B,(g)}_n\}$, $g\geq 0$, $n\geq 1$, $2g-2+n\geq 0$, be the system of differentials of generalized topological recursion associated to the input data $(\Sigma,dx,dy,\cP,B)$. Denote
\begin{align}\label{eq:89}
	\psi^{B}_n\coloneqq \sum_{\substack{g\ge0\\(g,n)\ne(0,1)}} \hbar^{2g-2+n}\psi^{B,(g)}_n.
\end{align}
\item Second, set
\begin{equation}\label{eq:90}
\tilde\psi^B_n=\psi^{B}_n-\delta_{n,2}B,\qquad
\tilde\phi_n=\phi_n-\delta_{n,2}B.
\end{equation}
\item
Denote by $\{\tilde\omega_n\}$ the convolution differentials of the systems of differentials $\{\tilde\psi^B_n\}$ and $\{\tilde\phi_n\}$.
The blobbed TR differentials $\omega_n=\sum_{d=0}^\infty\hbar^d \omega_n^{\langle d\rangle}$ are defined as
\begin{align} \label{eq:GraphicalFormulaomega}
	\omega_n  = \tilde\omega_n + \delta_{n,2} B.
\end{align}	
\end{itemize}
\end{definition}

\begin{remark} Note that with this definition the expansions of $\tilde\psi_n^B$ in~$\hbar$ contain no $\hbar^0$ terms, and hence, $\omega_n$ are well defined: there are finitely many graphs of Definition~\ref{def:convolution-system} contributing to each particular~$\omega_n^{\langle d\rangle}$.
\end{remark}

\begin{remark}
Note also that $\omega^{\langle 0 \rangle}_1 = \phi^{\langle 0 \rangle}_1$ and $\omega^{\langle 0 \rangle}_2 = \phi^{\langle 0 \rangle}_2$.
\end{remark}

\begin{remark} Assume that $\phi_n =\delta_{n,2} B$. Then $\omega_n = \psi^{B}_n$ are differentials of the usual (generalized) topological recursion.
\end{remark}

\begin{remark} Assume that the expansions of $\phi_n$ in $\hbar$ are topological, that is, $\phi_n^{\langle d\rangle}\not=0$ only if $d = 2g-2+n$ for some $g\geq 0$. Then the expansion of $\omega_n$ in $\hbar$ is topological as well. Exactly this situation was treated in details in~\cite{BS-blobbed} (in the setting of the original CEO topological recursion).
\end{remark}

\begin{example}
For arbitrary spectral curve data $(\Sigma,dx,dy,\cP,B)$ of topological recursion and a subset $\cP'\subset\cP$, the differentials $\omega_n$ of topological recursion with this spectral curve data can be regarded as differentials of blobbed topological recursion with the initial data~$(\Sigma,dx,dy,\cP',\{\phi_n\})$ with a smaller set $\cP'$ of key points and the differentials $\phi_n$ of topological recursion with the spectral curve data $(\Sigma,dx,dy,\cP\setminus\cP',B)$ regarded as blobs. This assertion is a reformulation of Proposition~\ref{prop:cP-cut}.
\end{example}

\subsection{Independence of a choice of~$B$}

\begin{lemma}\label{lem:Independence-of-B}
The blobbed differentials $\omega^{\langle d\rangle}_n$ are symmetric meromorphic differentials that do not depend on the particular choice of $B$.
\end{lemma}

\begin{example}
A special case of this lemma was observed in \cite[Section 5]{BS-blobbed}. Namely, assume that we have two possible choices for the Bergman kernel, $B_0$ and $B$. Then, the differentials of topological recursion computed with respect to the kernel $B$ (with the trivial blobs) coincide with the differentials of blobbed topological recursion associated with the differential $B_0$ as the Bergman kernel and the differentials $\tilde\phi_n=\delta_{n,2}(B-B_0)$ as the blobs.
\end{example}

The fact that $\{\omega_n\}$ are symmetric and meromorphic follows directly from the definition of the convolution of the systems of differentials. The proof that they do not depend on the choice of $B$ is given in the next Section. %Section~\ref{sec:proof-Independence-B}.

\subsubsection{Proof of Lemma~\ref{lem:Independence-of-B}} \label{sec:proof-Independence-B}

First, we state a deformation formula for the differentials of the topological recursion.

\begin{proposition}
	Let $\{\psi^{(g)}_n\}$ be the differentials of generalized topological recursion corresponding to the initial data $(\Sigma,dx,dy,\cP,B)$. Consider a deformation of the initial data with respect to a small parameter $\epsilon$ such that $\Sigma$, $dx$, $dy$ and $\cP$ are fixed and $B(\epsilon )=B+\epsilon \Delta B +O(\epsilon^2)$,  where~$\Delta B$ is a symmetric bidifferential holomorphic at $\cP\times\cP$. Let $\{\psi^{(g)}_n(\epsilon)\}$ be the differentials of generalized topological recursion corresponding to the initial data $(\Sigma,dx,dy,\cP,B(\epsilon))$. Then $\{\psi^{(g)}_n(\epsilon)=\psi^{(g)}_n+ \epsilon \Delta\psi^{(g)}_n+O(\epsilon^2) \}$, where
	\begin{align} \label{eq:Deformation-B}
		\Delta\psi^{(g)}_n(p_{\set n}) & =
		\sum_{i=1}^n\sum_{q\in\cP}\res\limits_{p=q}\psi^{(g)}_n(p,p_{\set{n}\setminus\{i\}})\int\limits_q^p\Delta B(\cdot,p_i)
		\\ \notag & \quad +
		\frac12\sum_{q,q'\in\cP}\res\limits_{p=q}\res\limits_{p'=q'}
		\biggl(\psi^{(g-1)}_{n+2}(p,p',p_{\set n})\biggr.
		\\ \notag & \qquad \qquad \qquad +\biggl.\sum_{\substack{g_1+g_2=g \\ I_1\sqcup I_2=\set{n}\\2g_i-2+|I_i|+1>0}}
		\psi^{(g_1)}_{|I_1|+1}(p,p_{I_1})\psi^{(g_2)}_{|I_2|+1}(p',p_{I_2})\biggr)
		\int\limits_q^p\int\limits_{q'}^{p'}\Delta B.
	\end{align}  	
\end{proposition}

\begin{proof}
	This formula is proved in the context of the original CEO topological recursion in~\cite{EO-1st}, see also an independent proof in~\cite{Kazarian} and an exposition in~\cite[Appendix]{alexandrov2024topologicalrecursionrationalspectral}. It the context of generalized topological recursion we can reduce this statement to the setting of the original CEO topological recursion by the deformation arguments of~\cite[Proof of Theorem 6.4]{alexandrov2024degenerateirregulartopologicalrecursion}. In a nutshell, the idea is to apply the following system of steps:
	\begin{itemize}
		\item Rewrite Equation~\eqref{eq:Deformation-B} replacing the residues at the points $q,q'\in \cP$ by the integrals over the boundary of some system of disks $D_q$, $q\in \cP$:
		\begin{align} \label{eq:Deformation-B-1}
			\Delta\psi^{(g)}_n(p_{\set n}) & =
			\sum_{i=1}^n\sum_{q\in\cP}\oint_{p\in \partial D_q}\psi^{(g)}_n(p,p_{\set{n}\setminus\{i\}})\int\limits_q^p\Delta B(\cdot,p_i)
			\\ \notag & \quad +
			\frac12\sum_{q,q'\in\cP}\oint_{p\in \partial D_q}\oint_{p\in \partial D_{q'}}
			\biggl(\psi^{(g-1)}_{n+2}(p,p',p_{\set n})\biggr.
			\\ \notag & \qquad \qquad \qquad +\biggl.\sum_{\substack{g_1+g_2=g \\ I_1\sqcup I_2=\set{n}\\2g_i-2+|I_i|+1>0}}
			\psi^{(g_1)}_{|I_1|+1}(p,p_{I_1})\psi^{(g_2)}_{|I_2|+1}(p',p_{I_2})\biggr)
			\int\limits_q^p\int\limits_{q'}^{p'}\Delta B.
		\end{align}
		\item Consider an additional deformation of the initial data with respect to a small parameter $\delta$ as in~\cite[Proof of Theorem 6.4]{alexandrov2024degenerateirregulartopologicalrecursion}. That is, $\Sigma$, $dy$, $B(\epsilon)$ are fixed. The differential $dx(\delta)$ is a local deformation of $dx$ inside $\sqcup_{q\in \cP}D_q$, where $dx(\delta)|_{D_q} =  dx+\delta\sum_{q\in\cP} \frac{dz_q}{(z_q-q)^{A_q}}$. Here $z_q$ is a local coordinate on $D_q$ and $A_q\in Z_{>0}$ is strictly bigger than the order of zeroes of $y$ at $q$. Finally, $\cP(\delta)$ is the set of all simple critical points of $dx(\delta)$ in $\sqcup_{q\in \cP}D_q$, which is the same as the set of all \nonregular{} points in this case.
		\item We get a two-parameter deformation family that analytically depends on $\epsilon$ and $\delta$. Thus we can interchange $\lim_{\delta\to 0}$ and $\restr{\epsilon}{0}\partial_\epsilon$.
		\item With this setup for $\delta\not=0$ the equation
		\begin{align} \label{eq:Deformation-B-2}
			\Delta\psi^{(g)}_n(\delta|p_{\set n}) & =
			\sum_{i=1}^n\sum_{q\in\cP}\oint_{p\in \partial D_q}\psi^{(g)}_n(\delta|p,p_{\set{n}\setminus\{i\}})\int\limits_q^p\Delta B(\cdot,p_i)
			\\ \notag & \quad +
			\frac12\sum_{q,q'\in\cP}\oint_{p\in \partial D_q}\oint_{p\in \partial D_{q'}}
			\biggl(\psi^{(g-1)}_{n+2}(\delta|p,p',p_{\set n})\biggr.
			\\ \notag & \qquad \qquad \qquad +\biggl.\sum_{\substack{g_1+g_2=g \\ I_1\sqcup I_2=\set{n}\\2g_i-2+|I_i|+1>0}}
			\psi^{(g_1)}_{|I_1|+1}(\delta|p,p_{I_1})\psi^{(g_2)}_{|I_2|+1}(\delta|p',p_{I_2})\biggr)
			\int\limits_q^p\int\limits_{q'}^{p'}\Delta B
		\end{align}
		is equivalent to the standard deformation formula in the context of the original CEO topological recursion. In order to see this we note that for $\delta\not=0$ the generalized topological recursion coincides with the original CEO topological recursion (for a local function $x(\delta)$ obtained as some primitive of $dx(\delta)$ on $\sqcup_{q\in \cP}D_q$). Moreover, the differentials $\psi^{(g)}_n(\delta)$ have no residues at the points $q\in \cP(\delta)$, $\delta\not=0$, which fixes the discrepancy with the choice of the lower integration limits for $\Delta B$.
		\item Finally, note that since the generalized topological recursion is compatible with the limits~\cite[Theorem 5.3]{alexandrov2024degenerateirregulartopologicalrecursion}, we see that in the limit $\delta\to 0$ we obtain the statement of the lemma in the context of generalized topological recursion.
	\end{itemize}
\end{proof}

Now we can use this deformation formula to prove Lemma~\ref{lem:Independence-of-B}.

\begin{proof}[Proof of Lemma~\ref{lem:Independence-of-B}]

	Note that any two different choices of $B$ can be connected by a path of admissible choices. Thus it is sufficient to prove that the infinitesimal deformation of $B(\epsilon) = B+\epsilon \Delta B+ O(\epsilon^2)$ --- according to Definition~\ref{def:blobbedTR} this deformation nontrivially affects $\psi_n^{B(\epsilon)} = \psi_n^B + \epsilon \Delta \psi_n^B + O(\epsilon^2)$ in~\eqref{eq:89} and  the shifts by $B(\epsilon) = B+\epsilon \Delta B+ O(\epsilon^2)$ in~\eqref{eq:90} --- leaves the $\omega_n(\epsilon)$ infinitesimally intact, that is,  $\omega_n(\epsilon) = \omega_n + O(\epsilon^2)$.

	Thus, we have to compute the coefficient of $\epsilon^1$ in the following expression:
	\begin{align}
		\{\omega_n(\epsilon)-\delta_{n,2} B(\epsilon)\}
		& \coloneqq \{\psi^{B(\epsilon)}_n-\delta_{n,2}B(\epsilon)\} *  \{\phi_n -\delta_{n,2} B(\epsilon)\},
	\end{align}
	where $[\epsilon^1]\psi^{B(\epsilon)}_n$ is given by Equation~\eqref{eq:Deformation-B}.

	According to Definition~\ref{def:convolution-system}, there are two types of terms that contribute to $[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B$ given as a sum over graphs. We basically have to repeat this definition with the either one of the $\psi$-vertices or one of the $\phi$-vertices being distinguished.
	In the case we have a distinguished $\psi$-vertex, it is decorated by $\Delta\tilde\psi_n = [\epsilon^1]\psi^{B(\epsilon)}_n- \delta_{n,2} \Delta B$. In the case we have a distinguished $\phi$-vertex of index $2$, it is decorated by $-\Delta B$. Pictorially, we represent $[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B$ as the sum over graphs of the following two types:
	\begin{align} \label{eq:TwoTypesOfGraphs}
		\vcenter{
			\xymatrix@C=10pt@R=0pt{
				\txt{\tiny 1} \ar@{-}[dr] &   & \rule{30pt}{0pt} & &  &
				\\
				\txt{\tiny 2} \ar@{-}[r] &  *+[o][F-]{} \ar@{}[u]|(.8){\tilde\psi} \ar@{-}@/^5pt/[rrd]|{*}  & &   &  &
				\\
				\vdots \ar@{-}[ur] & & &  *+[o][F*]{}
				\ar@{}[lu]_(.1){\tilde\phi} & &
				\\
				\vdots \ar@{-}[r] & *++[o][F=]{} \ar@{}[u]|(.6){\Delta\tilde \psi} \ar@{-}@/^5pt/[rru]|{*} \ar@{-}@/_5pt/[rru]|{*}  \ar@{-}@/_5pt/[drr]|{*}& &   & &
				\\
				&  & & *+[o][F*]{}  \ar@{}[lu]_(.1){\tilde\phi}  & \vdots \ar@{-}[l] &
				\\
				\vdots \ar@{-}[r]& *+[o][F-]{} \ar@{}[u]|(.4){\tilde\psi} \ar@{-}@/_5pt/[urr]|{*} & & &\txt{\tiny n} \ar@{-}[lu] &
				\\
				\vdots \ar@{-}[ur]
			}
		}
		\qquad \text{and} \qquad
		\vcenter{
			\xymatrix@C=10pt@R=0pt{
				\txt{\tiny 1} \ar@{-}[dr] &   & \rule{30pt}{0pt} & &  &
				\\
				\txt{\tiny 2} \ar@{-}[r] &  *+[o][F-]{} \ar@{}[u]|(.8){\tilde\psi} \ar@{-}@/^5pt/[rrd]|{*}  & &   &  &
				\\
				\vdots \ar@{-}[ur] & & &   *++[o][F-]{} \save *+[o][F*]{} \restore % Outer border
				\ar@{}[lu]_(.3){-\Delta B} & &
				\\
				& *+[o][F-]{} \ar@{}[u]|(.6){\tilde\psi} \ar@{-}[rru]|{*} \ar@{-}@/_5pt/[drr]|{*}& &   & &
				\\
				&  & & *+[o][F*]{}  \ar@{}[lu]_(.1){\tilde\phi}  & \vdots \ar@{-}[l] &
				\\
				\vdots \ar@{-}[r]& *+[o][F-]{} \ar@{}[u]|(.4){\tilde\psi} \ar@{-}@/_5pt/[urr]|{*} & & &\txt{\tiny n} \ar@{-}[lu] &
				\\
				\vdots \ar@{-}[ur]
			}
		}
	\end{align}
	Note that the distinguished $\phi$-vertex in the graphs of the second type might also be connected to a leaf, or, in one exceptional graph, it might be connected to two leaves:
	\begin{align} \label{eq:ExceptionalGraph}
		\vcenter{
			\xymatrix@C=10pt@R=0pt{
				& \txt{\tiny 1} \ar@{-}[dl]
				\\
				*++[o][F-]{} \save *+[o][F*]{} \restore % Outer border
				\ar@{}[u]^(0.8){-\Delta B} &
				\\
				& \txt{\tiny 2} \ar@{-}[ul]
			}
		}
	\end{align}
	The weight of this exceptional graph of the second type is equal to $-\Delta B(p_1,p_2)$.


	In terms of these graphs (recall the convention that we use $\tilde \psi_m$ and $\tilde \phi_m$ in the decorations, that is, we subtract $B$), Equation~\eqref{eq:Deformation-B} can equivalently be stated as
	\begin{align} \label{eq:deformation-B-graphs}
		\vcenter{
			\xymatrix@C=10pt@R=0pt{
				\txt{\tiny 1} \ar@{-}[dr] &
				\\
				\vdots \ar@{-}[r] &  *++[o][F=]{} \ar@{}[u]|(0.7){\Delta\tilde \psi}
				\\
				\txt{\tiny n} \ar@{-}[ru] &
			}
		}
		& = -\sum_{i=1}^n
		\vcenter{
			\xymatrix@C=10pt@R=5pt{
				\txt{\tiny 1} \ar@{-}[dr] &  & &  \rule{30pt}{0pt}
				\\
				\hat{\vcenter{\hbox{\txt{\tiny\textit{i}}}}} \ \  \vdots \ar@{-}[r] &  *+[o][F-]{}\ar@{}[u]|(.5){\tilde\psi} \ar@{-}[rr]|{*} & & *++[o][F-]{} \save *+[o][F*]{} \restore % Outer border
				\ar@{}[lu]_(.3){-\Delta B} & {\vcenter{\hbox{\txt{\tiny\textit{i}}}}} \ar@{-}[l]
				\\
				\txt{\tiny n} \ar@{-}[ru] & & &
			}
		}
		- \vcenter{
			\xymatrix@C=10pt@R=0pt{
				\txt{\tiny 1} \ar@{-}[dr] &  & \rule{25pt}{0pt} &
				\\
				\vdots \ar@{-}[r] &  *+[o][F-]{} \ar@{}[u]|(0.7){\tilde\psi} \ar@{-}@/_5pt/[rr]|{*} \ar@{-}@/^5pt/[rr]|{*} & & *++[o][F-]{} \save *+[o][F*]{} \restore % Outer border
				\ar@{}[lu]_(.3){-\Delta B}
				\\
				\txt{\tiny n} \ar@{-}[ru] &
			}
		}
		\\ \notag & \quad
		-\sum_{I\sqcup J}
		\vcenter{
			\xymatrix@C=10pt@R=0pt{
				&  & &  \rule{30pt}{0pt}
				\\
				I \big \{ \vdots \ \ &  *+[o][F-]{}\ar@{}[u]|(.6){\tilde\psi} \ar@{-}[rrd]|{*} \ar@{-}[l]+<5pt,7pt> \ar@{-}[l]+<5pt,-7pt> & &
				\\
				& & & *++[o][F-]{} \save *+[o][F*]{} \restore % Outer border
				\ar@{}[lu]_(.3){-\Delta B}
				\\
				J \big \{ \vdots \ \ &  *+[o][F-]{}\ar@{}[u]|(.6){\tilde\psi}  \ar@{-}[rru]|{*} \ar@{-}[l]+<5pt,7pt> \ar@{-}[l]+<5pt,-7pt> & &
			}
		}
	\end{align}
	Note that the order of the automorphism group of the second summand matches the coefficient $\frac 12$ in the second summand of Equation~\eqref{eq:Deformation-B}.

	Now we substitute Equation~\eqref{eq:deformation-B-graphs} instead of the distinguished $\psi$-vertex in each of the graphs of the first type in the expression for $[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B$. Here we face the following problem: for some graphs the new distinguished $\phi$-vertex (decorated by $-\Delta B$) is further connected to a $\phi$-vertex. This type of graphs has never occurred before. Note, however, that since $\Delta B$ and $\tilde \phi_n$ are regular near the points $q_i\in\cP$, the convolution $*$ applied to $-\Delta B$ and $\tilde \phi_n$ vanishes. In other words, the only graphs that contribute after this substitution are the ones where the two edges incident to the new distinguished $\phi$-vertex are either connected to $\psi$-vertices or to the leaves. Thus by this substitution we obtain graphs of the second type.

	Now each graph of the second type except for the exceptional one~\eqref{eq:ExceptionalGraph} enters the formula for $[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B$ exactly twice. First, as the original contribution of the second type in~\eqref{eq:TwoTypesOfGraphs} and second, as a summand in the substitution of~\eqref{eq:deformation-B-graphs} in the graphs of the first type in~\eqref{eq:TwoTypesOfGraphs}, with the opposite signs. Thus the only graph that give a non-trivial contribution to the formula for $[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B$ is the exceptional graph~\eqref{eq:ExceptionalGraph}, and we have
	\begin{align}
		[\epsilon^1]\omega_n(\epsilon)-\delta_{n,2} \Delta B = -\delta_{n,2} \Delta B.
	\end{align}
	We see that the infinitesimal deformation of $\{\omega_n\}$ with respect to an arbitrary infinitesimal deformation of $B$ is trivial, which, as we discussed above, proves that the blobbed differentials do not depend on the choice $B$.
\end{proof}




\subsection{Compatibility with non-perturbative differentials}

\begin{proposition}
Assume that $\Sigma$ is compact, $B$ is the standard Bergman kernel fixed by the requirement of vanishing $\mathfrak{A}$-periods, and $\{\phi_n\}$ are the KP integrable differentials of Krichever construction, see Section~\ref{sec:Kr-constr}. In this case the blobbed differentials associated with the spectral curve data $(\Sigma,dx,dy,\cP,\{\phi_n\}_{n\geq 1})$ coincide with nonperturbative differentials $\omega_n^{\np}$ of~\cite{ABDKSnp}.
\end{proposition}

\begin{proof} The nonperturbative differentials are defined in~\cite{ABDKSnp} by a formula with summation over graphs similar to that one of Lemma~\ref{lem:Gamma-accent} but with a different expression for the contribution of the graphs. An equivalence of the two expressions for the contributions of the graphs follows essentially from the Riemann bilinear relations. In more details, let $\overset \times \Sigma$ be the $4g$-gon obtained as a cut of $\Sigma$ along the $\mathfrak{A}$- and $\mathfrak{B}$-cycles.  Let $\{\psi_n\}$ be the differentials associated by generalized topological recursion to the input data $(\Sigma,dx,dy,\cP,B)$, where $B$ is the Bergman kernel normalized on $\mathfrak{A}$-cycles. By assumption, $\tilde\phi_n(p_{\set n}) =  \prod_{i=1}^n(\eta(p_i)\partial_w)\log\theta(w)$, and since these differentials are holomorphic on $\Sigma$, we can rewrite the sum of the residues in the definition of the convolution $*$ as an integral over $\partial\overset \times \Sigma$. More precisely, we have:
\begin{align}
	&
	\sum_{q\in \cP}\res\limits_{p=q} \tilde\psi_{n+1}(p,p_{\set{n}}) \int_q^p \eta(\cdot) \partial_w \big(\prod_{i=1}^{n'}\eta(p'_i) \partial_w\big) \log\theta(w)
	\\ \notag
	& = \frac{1}{2\pi\ii}\oint_{p\in\partial\overset\times\Sigma} \tilde\psi_{n+1}(p,p_{\set{n}}) \int_o^p \eta(\cdot) \partial_w \big(\prod_{i=1}^{n'}\eta(p'_i) \partial_w\big) \log\theta(w),
\end{align}
where $o\in\Sigma$ is some fixed point not on the boundary of $\overset \times \Sigma$ (recall that the residues of $\tilde\psi_{n+1}$ at the points of $\cP$ vanish).

In order to shorten the notation in what follows, we omit the index $n+1$ of $\tilde \psi$, the arguments $p_{\set{n}}$, and the form $\big(\prod_{i=1}^{n'}\eta(p'_i) \partial_w\big) \log\theta(w)$ (to which we apply $\eta(\cdot) \partial_w$)in the subsequent computation. Recall also that since the Bergman kernel is normalized on $\mathfrak{A}$-cycles, we have $\int_{\mathfrak{A_j}}\tilde \psi = 0$. Thus, we have:
\begin{align}
	\frac{1}{2\pi\ii} \oint_{p\in\partial\overset\times\Sigma} \tilde\psi(p) \int_o^p \eta \partial_w & = \frac{1}{2\pi\ii} \oint_{p\in\partial\overset\times\Sigma} \tilde\psi(p) \int_o^p \sum_{i=1}^g \eta_i(\cdot) \partial_{w_i}
	\\ \notag
	& = - \frac{1}{2\pi\ii} \sum_{j=1}^g \oint_{ \mathcal{A}_j} \tilde\psi \oint_{\mathfrak{B}_j} \eta(\cdot) \partial_w + \frac{1}{2\pi\ii} \sum_{j=1}^g \oint_{ \mathcal{B}_j} \tilde\psi \oint_{\mathfrak{A}_j} \eta(\cdot) \partial_w
	\\ \notag
	& =  \frac{1}{2\pi\ii} \oint_{ \mathcal{B}} \tilde\psi \partial_w.
\end{align}
The latter formula was used instead of the convolution $*$ on the edges of graphs in the definition of $\omega_n^{\np}$ in~\cite{ABDKSnp}. Since further the structure of graphs in~\cite[Section 4.1]{ABDKSnp} coincides with the version of the convolution formula presented in the proof of Proposition~\ref{prop:def-omegas} (in terms of graphs $G'_n$, with $\{\phi_n\}$ and $\{\psi_n\}$ interchanged), we identify the blobbed differentials associated with the spectral curve data $(\Sigma,dx,dy,\cP,\{\phi_n\}_{n\geq 1})$ with the nonperturbative differentials $\omega_n^{\np}$ of~\cite{ABDKSnp}.
\end{proof}

\subsection{KP integrability}

\begin{theorem}\label{th:KP-blobbed}
Assume that the system of blobs $\{\phi_n\}$ in the initial data of blobbed topological recursion is KP integrable. Then the system of differentials of the corresponding blobbed topological recursion is also KP integrable.
\end{theorem}

This theorem generalizes and unifies the KP integrability of the non-perturbative tau function conjectured in~\cite{BorEyn-AllOrderConjecture} and proved in~\cite{ABDKSnp}. It also provides the right context to the result of~\cite{alexandrov2024topologicalrecursionrationalspectral} claiming that the differentials of topological recursion on a global spectral curve is KP integrable if the spectral curve is rational. Indeed, by Theorem~\ref{th:KP-blobbed}, the KP integrability of the system of TR differentials follows from the KP integrability of the system of differentials~$\phi_n=\delta_{n,2}B$ considered as blobs, and by Proposition~\ref{prop:trivialKP}, such system is KP integrable if the spectral curve is rational (and it can be upgraded to an ``only if'' statement, see also~\cite{ABDKS3}). Notice, however, that the proof of Theorem~\ref{th:KP-blobbed} given below rely on the mentioned result of~\cite{alexandrov2024topologicalrecursionrationalspectral}.

\begin{proof} By Lemma~\ref{lem:Independence-of-B}, we have a freedom in a choice of $B$. Let us choose it in a special form
\begin{equation}
B(p_1,p_2)=\frac{dz(p_1)dz(p_2)}{(z(p_1)-z(p_2))^2}
\end{equation}
for some meromorphic function~$z$. We may assume that $z$ takes finite pairwise distinct values at the points of $\cP$, and $dz\ne0$ at these points. Along with the pole on the diagonal, the differential $B$ may have some additional poles, namely, at the pairs of distinct points $(p_1,p_2)$ with equal values of $z$. We can exclude these extra poles by
replacing the curve $\Sigma$ by its open subset $U$ containing~$\cP$. It is even sufficient to assume that $U$ is a union of small disks centered at the points of~$\cP$. The function~$z$ provides an embedding of $U$ to~$\C P^1$, and the differential~$B$ coincides with the standard Bergman kernel on~$\C P^1$ under this embedding. Thus, replacing $\Sigma$ by $U$, we may assume that the spectral curve in the initial data of the topological recursion defining the differentials $\psi^B_n$ is rational. The differentials $dx$ and $dy$ are defined locally in a neighborhood of~$\cP$ but the differentials $\psi^B_n$ still extend as global meromorphic differentials on~$(\C P^1)^n$.

By~\cite[Theorem 1.1]{alexandrov2024topologicalrecursionrationalspectral} and~\cite[Theorem 6.4]{alexandrov2024degenerateirregulartopologicalrecursion}, the differentials~$\psi^B_n$ are KP integrable. By Theorem~\ref{th:KP-conv}, we conclude that the differentials $\omega_n$ of blobbed topological recursion are also KP integrable, at least for the restriction to $U\subset\Sigma$. But since the KP integrability for a system of differentials is a global property, it holds for the whole spectral curve~$\Sigma$.
\end{proof}



\subsection{Recursions}

The differentials of blobbed topological recursion are defined in Section~\ref{sec:TR-blobbed} by a combinatorial formula with summation over graphs. In this section, we present a number of possible recursions for these differentials simplifying their computation in practice.


\begin{proposition}
The differentials of blobbed topological recursion satisfy generalized loop equations, the same as for the differentials of GenTR:
\begin{equation}
\sum_{r\ge0}\bigl(-d\tfrac1{dy}\bigr)^r[u^r]e^{u(\cS(u\hbar\partial_x)-1)y}
\restr{q^\pm}{ \mathfrak{g}^{\pm\frac{u\hbar}{2}}_{\partial_x}p}\cW_n(q^+,q^-;p_{\set n})
\end{equation}
is holomorphic in~$p$ at any $q\in\cP$, where $\cW_n$ is the extended differential associated with the system of differentials $\{\omega_n\}$.
\end{proposition}

Let $G_{\ell,m}\subset G_{\ell+m}$ be the set of graphs of Definition~\ref{def:convolution-system} with $\ell$ $\psi$-leaves marked by $1,\dots,\ell$ and $m$ $\phi$-leaves marked by $\ell+1,\dots,\ell+m$. Set
\begin{equation}
\omega_{\ell,m}=\sum_{\Gamma\in G_{\ell,m}}\frac{\mathsf{w}_\Gamma}{|\Aut(\Gamma)|}
\end{equation}
and denote by $\omega_{\ell,m}^{\langle d\rangle}$ the coefficient of $\hbar^d$ in $\omega_{\ell,m}$. Accordingly, we have
\begin{equation}
\omega_n(p_{\set{n}})=\sum_{I\sqcup J=\set{n}}\omega_{|I|,|J|}(p_I,p_J)+\delta_{n,2}B(p_1,p_2).
\end{equation}

\begin{proposition}
The blobbed TR differentials $\omega_{\ell,m}^{\langle d\rangle}$ with $\ell>0$ satisfy projection property
\begin{equation}
\omega_{\ell,m}^{\langle d\rangle}(p,p_{\set{\ell+m-1}})=\sum_{q\in\cP}\res_{\tilde p=q}\omega_{\ell,m}^{\langle d\rangle}(\tilde p,p_{\set{\ell+m-1}})
\int_q^{\tilde p}B(\cdot,p).
\end{equation}
\end{proposition}

The loop equation define the principal parts of the poles of $\omega^{\langle d\rangle}_{\ell,m}$ at the points of $\cP$ with respect to the first argument, from the known differentials computed in the previous steps of recursion, and the projection property recovers $\omega^{\langle d\rangle}_{\ell,m}$ from the principal parts of its poles. This provides a recursive procedure allowing one to compute all $\omega_{\ell,m}$ with $\ell>0$. However, the computation of $\omega_{0,m}$ is not covered by this recursion.

\medskip
Now, let us split
\begin{equation}
\omega_{\ell,m}=\sum_{k=0}^\infty \omega_{\ell,m,k}
\end{equation}
where $\omega_{\ell,m,k}$ involves the contribution of \emph{graphs with $k$ internal edges} in $G_{\ell,m}$. Then, for $k>0$ we have
\begin{multline}
k\,\omega_{\ell,m,k}(p_{\set{\ell+m}})=*\biggl(\omega_{\ell+1,m+1,k-1}(p,p_{\set{\ell}},\bar p,p_{\set{\ell+m}\setminus\set{\ell}})
\biggr.\\+\biggl.
\sum_{\substack{I_1\sqcup I_2=\set{\ell}\\J_1\sqcup J_2=\set{\ell+m}\setminus\set{\ell}\\k_1+k_2=k-1}}
\omega_{|I_1|+1,|J_1|,k_1}(p,p_{I_1},p_{J_1})\omega_{|I_2|,|J_2|+1,k_2}(p_{I_2},\bar p,p_{J_2})
\biggr)
\end{multline}
where
\begin{equation}
*\omega(p,\bar p)=\sum_{q\in\cP}\res_{p=q}\int_q^p\omega(p,\cdot).
\end{equation}
These relations provide another sort of recursion allowing one to compute $\omega_{\ell,m,k}$ by induction in~$k$. The initial differentials for this recursion are
\begin{equation}
\omega_{\ell,0,0}=\tilde \psi^B_\ell,
\qquad \omega_{0,m,0}=\tilde \phi_{m},
\qquad \omega_{\ell,m,0}=0, \quad \ell>0,m>0.
\end{equation}


