\begin{remark}\label{rem: time-stretched version}
\begin{enumerate}
\item Note that this time-stretching operation removes simply all constant parts of the path (except when $\XX$ is constant on the whole interval $[0,t]$).
    \item \label{rem: time-stretched version i}The definition of the time-stretched version path $\XX^{t,\rhd}$ of a non-constant path on $[0,t]$ depends on the specific bijections $\theta ^k$. Different bijections determine stretched versions that are time reparametrizations of one another, for some reparametrizations that map  $[0,t]$ into   $[0,t]$.
    \item If one component of $\XX$ is strictly increasing, for every $t\in(0,1]$ and $u\in [0,t)$, $\XX^{t,\rhd}_u=\XX_u$.
\end{enumerate}

\end{remark}










\subsection{Marcus transformation of weakly geometric \cadlag rough paths}\label{3sec: Marcus transformation}


In this section, we recall the notion of the Marcus transformation of weakly geometric~\cadlag $p$-rough paths for $p\in [1,3)$, introduced in~\cite{C:17}, (see also Section 2.3 in~\cite{CF:19}). This is an operation that associates every \cadlag path with continuous one obtained by introducing an additional time interval at each jump time and connecting the states before and after the jump via the so-called \textit{log-linear path-function} denoted by $\ell\ell$. Let us start by listing all the objects required for the precise definition.


\begin{enumerate}\phantomsection
    \item Fix $\XX\in D([0,1],G^{[p]}(\Rset^d))$, and let $(t_k)_{k\in\Nset}$ denote the sequence of its jumps times. 
     \item \label{3enumerate: Marcus transformation ii}Fix a sequence $R:=(r_k)_k$ such that for all $k\in \Nset $, $r_k>0$ and $\Sigma_R:=\sum_{k=1}^\infty r_k<\infty$, and define for all $t\in [0,1]$,
\begin{align}\label{3eq:tau X,R}
    \tau_{\XX,R}(t):=t+\sum_{k=1}^\infty r_k1_{\{t_k\leq t\}}.
\end{align}
Notice that $\tau_{\XX,R}$ is an increasing \cadlag function from $[0,1]$ with values in $[0,1+\Sigma_R]$ whose sequence of jumps times coincide with the sequence of jumps times of $\XX$. 
 \item Consider the \textit{log-linear path function} $\ell\ell$ defined as follows:
     \begin{align}\label{eq: ll path funcitonal}
	\ell\ell:G^{[p]}(\Rset^d)\times G^{[p]}(\Rset^d)&\rightarrow C([0,1],G^{[p]}(\Rset^d))\nonumber \\
	(\mathbf{x},\mathbf{y})&\mapsto\Big(s\mapsto\mathbf{x}\otimes \exp^{([p])}(s\log^{({[p]})}(\mathbf{x}^{-1}\otimes\mathbf{y} ))\Big).
	\end{align}
 Notice that for all $(\x,\y)\in G^{[p]}(\Rset^d)\times G^{[p]}(\Rset^d)$, $\ell\ell(\x,\y)(0)=\x$ and $\ell\ell(\x,\y)(1)=\y$. 

\item \label{3enumerate: Marcus transformation iv} Define $\YY\in C([0,1+\Sigma_R],G^{[p]}(\Rset^d))$ as follows: for all $s\in [0,1+\Sigma_R]$,
     \begin{equation*}
 \mathbf{Y}_s:=
\begin{cases}
    \XX_t,& \text{if } s=\tau_{\XX,R}(t) \text{ for some }t\in [0,1];\\
   \XX_{t_k^-}\otimes \exp^{([p])}\left(\frac{(s-\tau_{\XX,R}(t_k^-))}{r_k}\log^{([p])}(\Delta \XX_{t_k})\right) & \text{if }s\in [\tau_{\XX,R}(t_k^-),\tau_{\XX,R}(t_k)], \ k\in \Nset. 
\end{cases}
\end{equation*}
\end{enumerate}

\begin{definition}\label{3def: Marcus transformation}
    Let $\XX\in D([0,1],G^{[p]}(\Rset^d))$. Fix a sequence $R$ as in~\ref{3enumerate: Marcus transformation ii} and let $\tau_{\XX,R}$ be the increasing \cadlag function built through $R$ as in equation~\eqref{3eq:tau X,R}. Let $\YY$ be the continuous path defined via $\tau_{\XX,R}$ and the log-linear path function $\ell\ell$ as in~\ref{3enumerate: Marcus transformation iv}, and let $\psi_{R}$ denote an increasing bijection from $[0,1]$ to $[0,1+\Sigma_R]$. The \textit{Marcus-transformed path of $\XX$} associated with the pair $(R,\psi_R)$ is the continuous path $\widetilde \XX\in C([0,1],G^{[p]}(\Rset^d)) $ given by
    \begin{align*}
    \widetilde \XX_{\cdot}:=\YY_{\psi_R(\cdot)}.
\end{align*}

\end{definition}

