\begin{remark}\phantomsection \label{3rem: Marcus transformed path} Fix $\XX\in D([0,1],G^{[p]}(\Rset^d))$.
    \begin{enumerate}
        \item If $\XX\in C([0,1],G^{[p]}(\Rset^d)),$ for any sequence $R$ as in 
       ~\ref{3enumerate: Marcus transformation ii}, the map $\tau_{\XX,R}$ in~\eqref{3eq:tau X,R} is the identity map, i.e., $\tau_{\XX,R}(t)=t$ for all $t\in [0,1]$, and $\YY=\XX$, for $\YY$ as in~\ref{3enumerate: Marcus transformation iv}. In this case, we establish the convention that $\psi_R$ is an increasing bijection from $[0,1]$ to $[0,1]$ and thus $\widetilde \XX$ is simply a time-reparametrization of $\XX$.
          \item Let $\widetilde \XX$ be the Marcus-transformed path of $\XX$ associated to some pair $(R,\psi_R)$. Observe that we can recover $\XX$ from $\widetilde \XX$ via
        \begin{align*}
            \XX_\cdot :=\widetilde \XX_{\psi_R^{-1}(\tau_{\XX,R}(\cdot))}.
        \end{align*}
        \item \label{3rem: Marcus transformed path iii}  The Marcus-transformed paths of $\XX$ associated with two different pairs $(R,\psi_R)$ and $(\widetilde R,\psi_{\widetilde R})$, are simply  time-reparametrizations of one another. More precisely, let $\ZZ$ and $\widetilde{\ZZ}$ denote the transformed paths associated to $(R,\psi_R)$ and $(\widetilde R,\psi_{\widetilde R})$, respectively. Then  ${\ZZ}_\phi=\widetilde{\ZZ}$ for some time-reparametrization $\phi$ such that for all $t\in [0,1]$, $$\phi(\psi_R^{-1}(\tau_{\XX,R}(t)))=\psi^{-1}_{\widetilde{R}}(\tau_{\XX,\widetilde{R}}(t)).$$

    \end{enumerate}
\end{remark}


\subsection{Signature of weakly geometric \cadlag rough paths}\label{sec: signature}
In this section, we recall the notion of the signature of weakly geometric \cadlag $p$-rough paths and the key idea behind its construction. More detailed discussions can be found in \cite{FS:17} and Chapter 1 in \cite{P:24}. 

The concept of the signature of a \cadlag rough path builds upon the established framework for continuous paths (see e.g.,  \cite{L:98}). More precisely, to compute the signature of a \cadlag rough path $\XX\in D^p([0,1],G^{[p]}(\Rset^d))$ with $\XX_0=\mathbf{1}$, the initial step involves transforming 
$\XX$ into a continuous path via the Marcus transformation (with respect to some pair $(R,\psi_R)$) detailed in Section~\ref{3sec: Marcus transformation}. This transformation results in a path $\widetilde\XX$  which is a continuous weakly geometric $p$-rough path by construction. Lyons's extension theorem guarantees the existence (and uniqueness) of the signature of $\widetilde{\XX}$ (see e.g., Theorem 9.5 in \cite{FV:10}). The signature of the original \cadlag rough path $\XX$ is defined then as the unique $G((\Rset^d))$-valued path $\X$ such that the projection paths over $G^N(\Rset^d)$, denoted by $\X^N$, for $\Nset\ni N>[p]$, are the \cadlag paths given by
 \begin{align}\label{eq: def sig cadlag}
\X^N_\cdot:=\widetilde{\X}^N_{\psi_R^{-1}(\tau_{\XX,R}(\cdot))}.
 \end{align}
Here $\widetilde{\X}^N$ denotes the extension path of $\widetilde{\XX}$ provided by Theorem 9.5 in \cite{FV:10} and $\tau_{\XX,R}$ the \cadlag map defined in equation~\eqref{3eq:tau X,R}. 

These are the key ideas underlying the proof of the analogous theorem in the \cadlag context of Lyons' extension theorem, on which the notion of signature relies.

\begin{theorem}\label{1minimal jump extension}

(\textit{Minimal jump extension theorem}, Theorem 20 in~\cite{FS:17})
   Let $\Nset \ni N>[p]$. Every $\mathbf{X}\in D^p([0,1],G^{[p]}(\Rset^d))$ with $\XX_0=\mathbf{1}\in G^{[p]}(\Rset^d))$ admits a unique extension to a \cadlag path $\mathbb{X}^{N}:[0,1]\rightarrow G^{N}(\Rset^d)$, such that $\mathbb{X}^{N}$ starts from $\mathbf{1}\in G^N(\Rset^d)$, is of finite $p$-variation with respect to 
   $d_{CC}$ on $G^N(\Rset^d)$, and satisfies the following  condition:
\begin{equation}\label{1eqn11}
	\log^{(N)}(\Delta \mathbb{X}_t^N)=\log^{([p])}(\Delta \mathbf{X}_t) \quad  \text{for all }\ t\in[0,1].
	\end{equation}
\end{theorem}












\begin{definition}\label{def: signature cadlag}
    Let  $\mathbf{X}\in D^p([0,1],G^{[p]}(\Rset^d))$ with $\XX_0=\mathbf{1}\in G^{[p]}(\Rset^d))$. The \textit{signature} of $\mathbf{X}$ is defined as the unique path
    \begin{align*}
        \mathbb{X}:[0,1]\rightarrow G((\Rset^d)),
    \end{align*}
    such that for all $\Nset \ni N>[p]$, $\pi_{\leq N}(\mathbb{X})=\mathbb{X}^N$, where $\mathbb{X}^N$ denotes the unique extension path of $\mathbf{X}$ in $G^N(\Rset^d)$ provided by Theorem~\ref{1minimal jump extension}.
\end{definition}
\begin{notation}
    From now on, given $\XX\in D^p([0,1],G^{[p]}(\Rset^d))$, we refer to $\mathbb{X}$ as \textit{signature} of $\mathbf{X}$ and to $\mathbb{X}^N$ as \textit{truncated signature} of order $N$ of $\mathbf{X}$.
\end{notation}




Finally, the truncated signature of a weakly geometric \cadlag rough path can be computed by solving a  (Marcus-type) RDE (see \cite{CF:19}).
\begin{corollary}[Corollary 39 in~\cite{FS:17}]\label{coro: equation signature}
     Let $\mathbf{X}\in D^p([0,1],G^{[p]}(\Rset^d))$ with $\XX_0=\mathbf{1}\in G^{[p]}(\Rset^d))$ and $\Nset \ni N>[p]$. The unique extension path $\mathbb{X}^{N}$ of $\XX$ with values in $G^N(\Rset^d)$ provided by Theorem~\ref{1minimal jump extension} satisfies the  following linear Marcus-type RDE
	\begin{align}\label{eq: MarcusRDE}
&d\mathbb{X}^{N}=\mathbb{X}^{N}\otimes  \diamond d\mathbf{X},\qquad \mathbb{X}^{N}_0=\mathbf{1}\in G^N(\Rset^d),
	\end{align}
 which admits a unique solution, whose explicit form can be written as 
\begin{align}\label{1Rdemarcusexplicit}
	\mathbb{X}^{N}_\cdot=1+\int_0^\cdot\mathbb{X}^{N}_{s^-}\otimes d\mathbf{X}_s+\sum_{0<s\leq \cdot}\mathbb{X}^{N}_{s^-}\otimes \big(\exp^{(N)}(\log^{([p])}(\Delta \mathbf{X}_s))-\Delta \mathbf{X}_s\big).
\end{align}
The integral in~\eqref{1Rdemarcusexplicit} is understood as a  Young (if $p\in [1,2)$) or level 2 rough  (if $p\in [2,3)$) integral  (see Section \ref{sec: rough=young}) and the summation term is well-defined as an absolutely summable series.
\end{corollary}



















 Fix $\u \in T(\Rset^d)$ and recall the shifts introduced in equation~\eqref{3eq: shifts}. Let  $\mathbf{X}\in D^p([0,1],G^{[p]}(\Rset^d))$ with $\mathbf{X}_0=\mathbf{1}$ 
and denote by $\X$ its signature.  Then, a projection of equation~\eqref{1Rdemarcusexplicit} along $\u$ combined with Lemma 2.9 in~\cite{FZ:17} yields that 
\begin{enumerate}
      \item if $p\in [1,2)$,
      \begin{align}\label{eq: u,signature p12}
		\langle \u,\mathbb{X}_{\cdot}\rangle=&\langle \u,\mathbb{X}_{0}\rangle+ \int_0^\cdot \langle \u^{(1)},\mathbb{X}_{s^-}\rangle d\XX_{s}\\
  &+\sum_{0<s\leq \cdot}\langle \u,\mathbb{X}_{s}\rangle -\langle \u,\mathbb{X}_{s^-}\rangle -\langle  
 \u^{(1)},\mathbb{X}_{s^-}\rangle \Delta X_{s},  \nonumber 
		\end{align}
 where the integral 
 is a Young integral of $\langle \u^{(1)},\mathbb{X}_{\cdot}\rangle \in D^p([0,1],\Rset^{d+1})$ with respect to $\XX$, and for all $t\in (0,1]$, we set $(1,\Delta X_t):=\Delta \XX_t$. 
  \item if $p\in [2,3)$,
      \begin{align}\label{eq: u,signature p23}
		\langle \u,\mathbb{X}_{\cdot}\rangle =&  \langle \u,\mathbb{X}_{0}\rangle+\int_0^\cdot \langle \u^{(1)},\mathbb{X}_{s^-}\rangle d\XX_s\\
  &+\sum_{0<s\leq \cdot}\langle \u,\mathbb{X}_{s}\rangle -\langle \u,\mathbb{X}_{s^-}\rangle -\langle \u^{(1)},\mathbb{X}_{s^-}\rangle \Delta X_{s}-\langle \u^{(2)},\mathbb{X}_{s^-}\rangle \Delta  \X^{(2)}_{s},\nonumber 
		\end{align}
   where the integral is a  (level 2) rough integral of the controlled rough path 
   $\big(\langle \u^{(1)},\mathbb{X}_{\cdot}\rangle,\langle \u^{(2)},\mathbb{X}_{\cdot}\rangle\big) \in \mathcal{V}^{p,\frac{p}{2}}_{\XX}$  (Definition \ref{3def: controlled path qr}) with respect to $\XX$, and for all $t\in (0,1]$, we set $(1,\Delta X_t, \Delta  \X^{(2)}_{t}):=\Delta \XX_t$. 
  \end{enumerate}

   \begin{assumpt}\label{assumption}
     Throughout, we assume that all the weakly geometric~\cadlag rough paths start at $\mathbf{1}\in G^{[p]}(\Rset^d)$, i.e., $\mathbf{X}_0=\mathbf{1}$. 
 \end{assumpt}














\section{Functionals of weakly geometric~\cadlag rough paths}\label{sec: funcionals of RP}



\subsection{Non-anticipative Marcus canonical  path functionals}


Inspired by the notion of Marcus-type-RDEs (see~\cite{CF:19}),  we here introduce the class of so-called \textit{non-anticipative Marcus canonical path functionals}. To this end, we start with the notion of non-anticipative path functionals, which in turn relies on the definition of \textit{stopped-paths}. In the following, we set $\Nset_0:=\N\cup\{0\}.$

\begin{definition}
  Given ${{\mathbf{X}}}\in {D}^p([0,1],G^{[p]}(\Rset^{d})))$ and $t\in [0,1]$, we define the \textit{stopped weakly geometric} \textit{\cadlag rough path of ${\mathbf{X}}$} stopped at time $t$ as the \cadlag path ${\mathbf{X}}^t:[0,1]\rightarrow G^{[p]}(\Rset^{d})$  given by
$${\mathbf{X}}^t_u:=
         {\mathbf{X}}_u1_{\{u<t\}}+{\mathbf{X}}_t1_{\{u\geq t\}},$$
         for all $u\in [0,1]$.
 \end{definition}
