\begin{definition}\label{def: non anticipative path functional}
    Let $F:[0,1]\times D([0,1],G^{[p]}(\Rset^d))\rightarrow \Rset$.  We say that $F$ is a \textit{non-anticipative path functional} if for all $(t,\XX)\in [0,1]\times D([0,1],G^{[p]}(\Rset^d)) $, it holds that 
    \begin{align*}
        F(t,\XX)=F(t,\XX^t).
    \end{align*}
\end{definition}

\begin{remark}\label{rem: t variable} The variable $t$ has the role of a parameter and not of a component of the path $\XX$. In fact, it is the parameter needed to specify that the path functional is non-anticipative. 








\end{remark}

Let us now introduce the class of the non-anticipative Marcus canonical  path functionals. We refer to \cite{CF:19} and also ~\cite{FK:85}, \cite{AT:92}, \cite{KP:95} for some related definitions from the literature. 

For $\XX\in D([0,1],G^{[p]}(\Rset^{d}))$, recall the notion of a Marcus-transformed path of $\XX$ associated with some pair $(R,\psi_R)$ given in Definition~\ref{3def: Marcus transformation}  and the one of time-stretched path given in Definition \ref{def: time-stretched version}.
\begin{definition}\label{3def: Marcus canonical path functional}
    Let $F:[0,1]\times D([0,1],G^{[p]}(\Rset^{d}))\rightarrow \Rset$ be a non-anticipative path functional. We say that $F$ is a \textit{non-anticipative Marcus canonical path functional} if
    \begin{enumerate}
        \item \label{item def Mcpf i}for all $\XX\in C([0,1],G^{[p]}(\Rset^d))$, $t\in [0,1]$, $\phi$ time-reparametrization,$$F(t,\XX_\phi)=F(\phi(t),\XX);$$
        \item  \label{item def Mcpf ii}for all $\XX\in C([0,1],G^{[p]}(\Rset^d)) $ and all $t\in [0,1]$,
    $$F(t,\XX)=F(t,\XX^{t,\rhd}),$$
where $\XX^{t,\rhd}$ denotes some time-stretched version of $\XX$ on $[0,t]$;




        \item \label{item def Mcpf iii}for all $(t,\XX)\in[0,1]\times  D([0,1],G^{[p]}(\Rset^d)),$
    \begin{align*}
F(t,\XX)=F(\psi_R^{-1}(\tau_{\XX,R}(t)),\widetilde\XX),\end{align*}
    where $\widetilde \XX$ denotes the Marcus-transformed path of $\XX$ with respect to some pair $(R,\psi_R)$. 
    \end{enumerate}
     We denote the space of such functionals by $\mathcal{M}_{[p]}^0$.
\end{definition}

\begin{notation}
     We  set $((\Mcalp^0)^d)^{\otimes 0}:=\Mcalp^0$ and for $m\in \Nset_0$,  we write $F\in ((\Mcalp^0)^d)^{\otimes m}$ if 
    \begin{align*}
        F:[0,1]\times D([0,1],G^{[p]}(\Rset^{d}))\rightarrow (\Rset^d)^{\otimes m}
    \end{align*}
    is a path functional whose components
    are non-anticipative Marcus canonical path functionals in the sense of Definition~\ref{3def: Marcus canonical path functional}.
\end{notation}





\begin{remark} \label{3rem: Marcus functional independent on the pair}
\begin{enumerate}

\item  The symbol $\Mcalp^0$ does not include the dimension $d$, as it will
always be clear from the context.

 \item \label{item I Marcus canonical does not depend para }Property \ref{item def Mcpf i}  in Definition \ref{3def: Marcus canonical path functional} guarantees that the subsequent conditions \ref{item def Mcpf ii}, \ref{item def Mcpf iii} are independent
 of the specific stretched version of $\XX$ on $[0,t]$ and independent of the specific Marcus-transformed path, respectively. Indeed, let ${\ZZ}$, ${\widetilde\ZZ}$ be two Marcus transformations of $\XX$ associated with  $(R,\psi_R)$ and  $(\widetilde{R},\psi_{\widetilde{R}})$, respectively. By Remark~\ref{3rem: Marcus transformed path}~\ref{3rem: Marcus transformed path iii},  ${\ZZ}_\phi=\widetilde{\ZZ}$, for some  time-reparametrization $\phi$, and for all $t\in [0,1]$, $$\phi(\psi^{-1}_{\widetilde{R}}(\tau_{\XX,\widetilde{R}}(t)))=\psi_R^{-1}(\tau_{\XX,R}(t)).$$ Therefore, by condition \ref{item def Mcpf i},
  \begin{align}\label{3eq: Marcus functional independent on the pair}
      F(\psi^{-1}_{\widetilde{R}}(\tau_{\XX,\widetilde{R}}(t)),\widetilde{\ZZ})=F(\psi^{-1}_{{R}}(\tau_{\XX,{R}}(t)),\ZZ).
  \end{align} 
  Recalling Remark \ref{rem: time-stretched version}\ref{rem: time-stretched version i}, a similar argument holds for condition \ref{item def Mcpf ii}. 

  \item \label{iii2}  A non-anticipative path functional defined only on the set of continuous paths that satisfies conditions~\ref{item def Mcpf i},\ref{item def Mcpf ii} of Definition~\ref{3def: Marcus canonical path functional} can always be extended to a path functional on the entire set of \cadlag path via condition~\ref{item def Mcpf iii}  of Definition~\ref{3def: Marcus canonical path functional}. The resulting functional is a well-defined Marcus canonical path functional. Moreover, this extension is also unique. This is in fact the approach proposed in~\cite{CF:19}.
\end{enumerate}





\end{remark}

\begin{notation}\label{3notation: mut}
      Given the independence on the specific Marcus-transformed path discussed in Remark~\ref{3rem: Marcus functional independent on the pair} and to ease notation, for all $t\in [0,1]$, $\XX\in D([0,1],G^{[p]}(\Rset^d))$ and a pair $(R,\psi_R)$,  we set  $\mu_{t}:=\psi_R^{-1}(\tau_{\XX,R}(t))$ whenever there is no ambiguity.
\end{notation}






 We present some examples of non-anticipative Marcus canonical  path functionals.
\begin{example}\phantomsection\label{example: Marcus canonical}
   \begin{enumerate}
        \item  Let $F(t,\XX):=Y_t$, where $Y$ denotes the solution of a Marcus-type RDE in the sense of Definition 3.1 in \cite{CF:19}, driven by some \cadlag path $\XX\in D^p([0,1],G^{[p]}(\Rset^d))$, at time $t\in (0,1]$. By the solution concept and the property of the rough integral, $F$ is a non-anticipative Marcus canonical  path functional. 

        \item  Let $F$ be the functional such that  for all $(t,\XX)\in [0,T]\times D^p([0,1],G^{[p]}(\Rset^d))$, $$ F(t,\XX):=\sup_{s\in [0,t]}\|\XX_s\|.$$
 Then F is a non-anticipative Marcus canonical  path functional.
 \item \label{item examples Marcus iii}For $\XX\in C^1([0,1],G^1(\Rset^{2}))$, set $\XX^1_\cdot:=\langle  \e_1,\XX_\cdot\rangle=$  and $\XX^2_\cdot:=\langle  \e_2,\XX_\cdot\rangle$, and consider the  path functional (defined only on the set of continuous paths) via $F(t,\XX):=\int_0^t \XX^1_sd\XX^2_s $. Since $F$ verifies~\ref{item def Mcpf i},\ref{item def Mcpf ii} of Definition~\ref{3def: Marcus canonical path functional}, following the discussion in Remark~\ref{3rem: Marcus functional independent on the pair}\ref{iii2}, we can extend it to the set $D^1([0,1],G^1(\Rset^{2}))$ via condition~\ref{item def Mcpf iii}. A direct computation shows that the resulting functional, which is non-anticipative Marcus canonical and we still denote by $F$, explicitly reads as
 \begin{align}\label{eq: F example Marcus}
     F(t,\XX):=\int_0^t \XX^1_{s^-}d\XX^2_s +\frac{1}{2}\sum_{0<s\leq t}\Delta \XX^1_s\Delta \XX^2_s,
 \end{align}
 for all $(t,\XX)\in D^1([0,1],G^1(\Rset^{2}))$.
    \end{enumerate}
\end{example}

\begin{remark}\label{remark: non marucs like}\phantomsection
\begin{enumerate}
    \item  \label{remark: non marucs like i}It is important to note that not every non-anticipative path functional that is well defined on the space of \cadlag paths is a Marcus canonical  path functional. Consider for instance the functional defined via $F(t,\XX):=\int_0^t \XX^1_{s^-}d\XX^2_s $, for all $(t,\XX)\in D^1([0,1],G^1(\Rset^{2}))$. Then, $F$ is not Marcus canonical . Indeed, for  $\XX\in D^1([0,1],G^1(\Rset^{2}))\setminus C^1([0,1],G^1(\Rset^{2}))$, let $\widetilde \XX$ be its Marcus-transformed path with respect to some pair $(R,\psi_R)$. Then, 
    \begin{align*}
        F(\psi_R^{-1}(\tau_{\XX,R}(t)),\widetilde \XX)=\int_0^t \XX^1_{s^-}d\XX^2_s +\frac{1}{2}\sum_{0<s\leq t}\Delta \XX^1_s\Delta \XX^2_s\neq F(t,\XX).
    \end{align*}
    Similarly, the path functional given by $F(t,\XX):=\sum_{0<s\leq t}\Delta \XX^1_s\Delta \XX^2_s$ is not Marcus canonical  as  $0=F(\psi_R^{-1}(\tau_{\XX,R}(t)),\widetilde \XX)\neq F(t,\XX)$ for pure jump paths.   



    \item \label{remark: non marucs like ii}
Note however that 
     some non-anticipative path functionals that  do not appear to be Marcus canonical at first glance can be easily turned into Marcus canonical ones. This is the case for instance for the functional $F$ defined via  $F(t,\XX):=\int_0^t \XX_{s}ds $ for all $(t,\XX)\in[0,1]\times  C^1([0,1],G^1(\Rset))$, which does not satisfy condition \ref{item def Mcpf i} in Definition \ref{3def: Marcus canonical path functional}. However, considering the path functional $\bar{F}(t,\XX):=\int_0^t\XX^2_sd\XX_s^1$ defined on $[0,1]\times  C^1([0,1],G^1(\Rset^2))$, we get that it satisfies property \ref{item def Mcpf i} in Definition \ref{3def: Marcus canonical path functional}, and for all $(t,\wXX)\in [0,1]\times C^1([0,1],G^1(\Rset^2))$ where $\wXX:=(Id,\XX)$, with $Id_u:=u$ for all $u\in [0,1]$ and $\XX\in C^1([0,1],G^1(\Rset))$, it holds that 
    $F(t,\XX)=\bar F(t,\wXX)$. Therefore, a time-extension of the original path can be crucial to satisfy the conditions specified in Definition \ref{3def: Marcus canonical path functional}.




    The above example also illustrates that a functional may have multiple representations. To apply the theory that follows, it is necessary to select the representation that satisfies the conditions for being a non-anticipative Marcus canonical path functional.




\end{enumerate}  
\end{remark}




Next, we introduce the notion of path functionals that are invariant under reparametrization, which is 
the same as condition (i) in Definition~\ref{3def: Marcus canonical path functional}, however on the whole space of \cadlag paths $D([0,1],G^{[p]}(\Rset^d))$ and not only on $C([0,1],G^{[p]}(\Rset^d))$.

\begin{definition}\label{3def: invariant under reparametri}
     Let $F:[0,1]\times D([0,1],G^{[p]}(\Rset^d))\rightarrow \Rset$ be a non-anticipative path functional. We say that $F$ is \textit{invariant under reparametrization} if for all $\XX\in D([0,1],G^{[p]}(\Rset^d))$, $t\in [0,1]$ and $\phi$ time-reparametrization,  
\begin{align*}
F(t,\XX_\phi)=F(\phi(t),\XX).
\end{align*}
\end{definition}

We now show that every $F\in \mathcal{M}^0_{[p]}$ satisfies this property. The proof of the following proposition is given in Appendix \ref{proof 3prop: F Marcus canonical then F invariant}.


\begin{proposition}\label{3prop: F Marcus canonical then F invariant}
    Let $F\in \mathcal{M}^0_{[p]}$. Then $F$ is invariant under reparametrization.
\end{proposition}


To conclude, we introduce the notion of the remainder path functional related to some functionals of $G^{2}(\Rset^{d})$-valued paths. 





\begin{definition}\label{3def: 2 parameter functional}
    Let $F\in ((\Mcalp^0)^d)^{\otimes m}$  and $F'\in ((\Mcalp^0)^d)^{\otimes m+1}$, for $m\in \Nset_0$.
We define the \textit{remainder path functional} (related to $F$ and $F'$) as follows:
$$R^{F,F'}:\Delta_1\times D([0,1],G^{2}(\Rset^{d}))\rightarrow (\Rset^d)^{\otimes m},$$  
given by 
     \begin{align*}
       R^{F,F'}((s,t),\XX):=F(t,\XX)-F(s,\XX)-F'(s,\XX)\pi_1(\XX_{s,t}),
     \end{align*}
     for all $((s,t),\XX)\in \Delta_1\times D([0,1],G^{2}(\Rset^{d}))$.
\end{definition}




















\subsection{Vertically differentiable path functionals}

\begin{definition}\label{def: vertical differentiable path functional}
     Let $F\in \mathcal{M}^0_{[p]}$. We say that $F$ is vertically differentiable at $(t,\XX)\in [0,1]\times D([0,1],G^{[p]}(\Rset^{d}))$ in the direction $i=1,\dots,d$ if the map
\begin{align*}
   \Rset\ni h\mapsto F(\mu_t,\widetilde{\XX}\otimes \exp^{([p])}(h\e_i)1_{\{\cdot \geq \mu_t\}})
\end{align*}
is differentiable at $0$, for some Marcus-transformed path $\widetilde{\XX}$ and $\mu_t\in [0,1]$ given in Notation~\ref{3notation: mut}. In this case we call 
\begin{align}\label{eq: vertical derivativ}
    \frac{d}{dh}F(\mu_t,\widetilde{\XX}\otimes \exp^{([p])}(h\e_i)1_{\{\cdot \geq \mu_t\}})|_{h=0}.
\end{align}
the vertical derivative of $F$ at $(t,\XX)$ in the direction $i$. If $F$ is vertically differentiable in all directions $i=1,\dots,d$ at all $(t,\XX)$, we say that $F$ is vertically differentiable. We denote the space of such functionals by $\mathcal{M}_{[p]}^1$.
\end{definition}



\begin{remark}\phantomsection\label{3rem: vertical derivative indipendent on the pair}
\begin{enumerate}
\item The value of the vertical derivatives of $F\in \Mcalp^1$ at some $(t,\XX)$ is independent of the specific Marcus-transformed path. This follows from Proposition~\ref{3prop: F Marcus canonical then F invariant} and a similar
reasoning as in Remark~\ref{3rem: Marcus functional independent on the pair}.


\item \label{3rem: vertical derivative indipendent on the pair item ii} In~\eqref{eq: vertical derivativ} the Marcus transformation of the path is computed before the vertical perturbation. This is, in fact, a key aspect of this definition. On one hand, it allows the preservation of the Marcus property of the functionals also at the level of the (functional) derivative (see Proposition~\ref{3prop: F Marcus canonical UiF Marcus canonical}). On the other hand, if the original path $\XX$ admits a jump a time $t$, the Marcus property of the functional $F$ allows to interpret the derivative in~\eqref{eq: vertical derivativ} as a derivative computed via a delayed perturbation of the original path:
\begin{align}\label{eq: delayed pert 1}
      \XX^t+h\e_i1_{\{\cdot\geq t+\varepsilon\}},
\end{align}
for some $\varepsilon>0$ independent on the specific pair employed for computing $\tXX$. 

To clarify this aspect, suppose that $\XX$ is a weakly geometric \cadlag $p$-rough path, for $p\in [1,2)$,  that admits a jump only at time $t$. For simplicity, we identify $G^1(\Rset^d)$ with $\Rset^d$. 
Then, applying the Marcus transformation first to the path $\XX$ and then to the perturbed path $\tXX+ h\e_i1_{\{\cdot\geq\mu_t\}}$ yields that~\eqref{eq: vertical derivativ} explicitly reads as
\begin{align*}
    \frac{d}{dh}F(t+\delta_2+\delta_1,\YY^{[i]}(h))|_{h=0},
\end{align*}
for $\YY^{[i]}(h)$ defined  up to time $t+\delta_2+\delta_1$ via 
\begin{equation*}
  \YY^{[i]}(h)_s:=
\begin{cases}
   \XX_{s^-}& \text{if }s\in [0,t],\\
   \XX_{t^-}+\frac{s-t}{\delta_2} \Delta \XX_{t}&  \text{if }s\in [t,t+\delta_2],\\
    \XX_{t^-}+\Delta \XX_t+\frac{s-t-\delta_2}{\delta_1} h\e_{i} &  \text{if }s\in [t+\delta_2, t+\delta_2+\delta_1],
\end{cases}
\end{equation*}
for some $\delta_2,\delta_1>0$ such that $t+\delta_2+\delta_1<1$, $\mu_t=t+\delta_2$.  Since the path $\YY^{[i]}(h)$ stopped at time $t+\delta_2+\delta_1$  is a time-stretched version of some Marcus-transformed path of \eqref{eq: delayed pert 1} on $[0,\mu_{t+\varepsilon}]$, for $\mu_{t+\varepsilon}=t+\delta_2+\delta_1$, by conditions \ref{item def Mcpf ii} and \ref{item def Mcpf iii}, we get
\begin{align*}
   \frac{d}{dh}F(t+\varepsilon,\XX^t+h\e_i1_{\{\cdot \geq t+\varepsilon\}})|_{h=0}= \frac{d}{dh}F(t+\delta_2+\delta_1,\YY^{[i]}(h))|_{h=0}.
\end{align*}


