This confirms that our notion of vertical derivative involving Marcus transformations of the original path allows to view the derivative in~\eqref{eq: vertical derivativ} as a derivative computed via a delayed perturbation of the original path. This aspect affects in particular the higher order vertical derivatives where a jump at the current time always occurs (see Remark~\ref{rem: non commutativity derivate} and Example~\ref{example non commutative}).  Notice furthermore that the independence on the specific $\varepsilon>0$ follows by the invariance of the functional with respect to time-reparametrization.




   \item   If $p\in [1,2)$, the notion of vertical derivatives given in Definition~\ref{def: vertical differentiable path functional} corresponds to the notion of vertical derivatives introduced in~\cite{D:09} (see also Definition 8 in~\cite{CRF:10}) when evaluated at continuous paths.

   Similarly, if for $p\in [2,3)$ a non-anticipative path functional depends only on $\pi_1(\XX)$ for all $(t,\XX)$, then~\eqref{eq: vertical derivativ} matches again the notion of vertical derivative introduced in~\cite{D:09} evaluated at continuous paths. 


\end{enumerate}
\end{remark}




Next, we introduce the notion of higher-order vertical derivatives, which are given via an iterative application of the computation in \eqref{eq: vertical derivativ}. To make the argument precise, we formally introduce the differential that associates to every path functional its derivative functional. The well-posedness of this concept relies on the following proposition, whose proof is given in Appendix \ref{proof 3prop: F Marcus canonical UiF Marcus canonical}.



\begin{proposition}\label{3prop: F Marcus canonical UiF Marcus canonical}
    Let $F\in \mathcal{M}^1_{[p]}$. The path functional given by 
    \begin{align}\label{3eq: pre UiF path functional}
  [0,1]&\times D([0,1],G^{[p]}(\Rset^{d}))\rightarrow\Rset \\
    &(t,\XX)\longmapsto \frac{d}{dh}F(\mu_t,\widetilde{\XX}\otimes \exp^{([p])}(h\e_i)1_{\{\cdot \geq \mu_t\}})|_{h=0},\nonumber
\end{align}
is a non-anticipative Marcus canonical  path functional. 
\end{proposition}




\begin{definition}\label{3def: operator Ui}
    For all $i=1,\dots,d$, we define the differential operators
    \begin{align*}
U^i: \ &\mathcal{M}^1_{[p]}\rightarrow\mathcal{M}^0_{[p]}\\
        & \ F \mapsto U^i(F),
    \end{align*}
   where for all $F\in \mathcal{M}^1_{[p]}$ and all $(t,\XX)\in [0,1]\times D([0,1],G^{[p]}(\Rset^{d}))$,
    \begin{align*}
        U^i(F)(t,\XX):= \frac{d}{dh}F(\mu_t,\widetilde{\XX}\otimes \exp^{([p])}(h\e_i)1_{\{\cdot \geq \mu_t\}})|_{h=0},
    \end{align*}
    for some Marcus-transformed path $\widetilde{\XX}$ and $\mu_t\in [0,1]$ given in Notation~\ref{3notation: mut}.


\end{definition}




Finally, we introduce the notion of higher-order vertical derivatives.
\begin{definition}\label{def: higher order derivatives}
    Let $F\in \mathcal{M}^0_{[p]}$ and $K\in \Nset$. We say that $F$ is $K$ times vertically differentiable if for all $l=1,\dots,K$ the path functionals defined recursively by 
    \begin{align*}
    &U^{i_0}F:=F,\qquad \qquad \qquad \qquad \qquad \qquad \quad \qquad \quad \text{for }l=1,\\
    &U^{i_{l-1}}\dots U^{i_1}U^{i_0}F:=U^{i_{l-1}}(U^{i_{l-2}}\dots U^{i_1}U^{i_0}F), \quad \text{for }l=2,\dots,K, \ (i_1,\dots,i_{l-1})\in \{1,\dots,d\}^{l-1},\nonumber 
\end{align*} 
are vertically differentiable at all $(t,\XX)\in  [0,1]\times D([0,1],G^{[p]}(\Rset^{d}))$.  In this case, we call
\begin{align}\label{3eq: value vertical derivatives higher order}
    U^{i_K}\dots U^{i_1}  F(t,\XX):= U^{i_K}(U^{i_{K-1}}\dots U^{i_1}U^{i_0} F)(t,\XX)
\end{align}
the vertical derivative of order $K$ of $F$ at $(t,\XX)$ in the directions $(i_1,\dots,i_K)\in \{1,\dots,d\}^{K}$.
We denote the space of such functionals by $\mathcal{M}_{[p]}^K$.
\end{definition}

\begin{notation}\label{3notation higher order derivatives}
    In the following, for $K\in \Nset$, $F\in \Mcalp^K$, $l=1,\dots,K$, 
   we let $\nabla^l F$ denote the  $(\Rset^d)^{\otimes l}$-valued 
      path functional such that for all $I=(i_1,\dots,i_l)$,
    \begin{align*}
    \nabla ^lF(t,\XX)_I:=U^{i_l}\dots U^{i_1}F(t,\XX),
\end{align*}
for all $(t,\XX)\in [0,1]\times D([0,1],G^{[p]}(\Rset^{d}))$.
Notice that $\nabla^l F$ is a $(\Rset^d)^{\otimes l}$-valued path functional whose components are in $\Mcalp^{K-l}$.  For notational convenience, we also write $\nabla^0F:=F$ and $\nabla F:=\nabla^1 F$.


\end{notation}









The computation of the higher-order vertical derivatives can be done by considering the iterative procedure described below.  For notational simplicity, we here consider only  \cadlag paths with values in $G^{1}(\Rset^{d})$, identify $G^{1}(\Rset^{d})$ as $\Rset^d$, and explicitly write the procedure for computing the derivatives up to the second order.

