\begin{equation*}
    \begin{array}{l l}
   \text{Step 0:} &\XX^{[0]}:=\XX^t, \\
    &\YY^{[0]}:=\reallywidetilde{\XX^{[0]}}, \\
    &\mu_t^{[0]}:=\psi_{R_0}^{-1}(\tau_{\XX^{[0]},R_0}(t)), \text{ for some pair } (R_0,\psi_{R_0}).
    \end{array}
\end{equation*}

