\begin{example}\label{example non commutative}
Let us consider the path functional introduced in Example~\ref{example: Marcus canonical}\ref{item examples Marcus iii}, that is
\begin{align*}
     F(t,\XX):=\int_0^t \XX^1_{s^-}d\XX^2_s +\frac{1}{2}\sum_{0<s\leq t}\Delta \XX^1_s\Delta \XX^2_s,
 \end{align*}
 for all $(t,\XX)\in D^1([0,1],G^1(\Rset^{2}))$.


A direct computation of the iterative procedure described above shows that for all $(t,\XX)\in [0,1]\times D([0,1],G^{1}(\Rset^{2}))$, one gets $$U^2U^2F(t,\XX)=U^1U^1F(t,\XX)=U^2U^1F(t,\XX)=U^1F(t,\XX)=0,$$ whereas, $$U^2F(t,\XX)=\XX^1_t \quad \text{and}\quad U^1U^2F(t,\XX)=1.$$ 


\end{example}






\begin{remark}\label{rem: non commutativity derivate}
The above considerations, in particular Example \ref{example non commutative}, show that the notion of vertical derivatives of higher order introduced in Definition~\ref{def: higher order derivatives} establishes a differential calculus for path functionals that allows for non-commutative derivation orders. This is in contrast to the setup in \cite{D:09},~\cite{CRF:10},~\cite{CR:12} (see e.g., p. 133 in~\cite{CR:12}). 

\noindent This different behavior can be explained as follows. For a path functional that is non-anticipative, the second-order vertical derivatives at some $(t,\XX)$ as computed in \cite{D:09} (see also Definition 9 in \cite{CRF:13}) explicitly read as   
\begin{align}\label{eq: derivative Dupire}
\partial_{i_2}\partial_{i_1}F(t,\XX)=&\frac{d^2}{dh_{2}dh_1}F(t,\XX^t+(h_2\e_{i_2}+h_1\e_{i_1})1_{\{\cdot \geq t\}})|_{h_{1}=h_2=0},
\end{align}
for $i_1,i_2=1,\dots,d$. In contrast, in the present framework,
\begin{align*}
    U^{i_{2}} U^{i_{1}}F(t,\XX)=\frac{d^2}{dh_{2}dh_1}F(t+\varepsilon_2+\varepsilon_1,\XX^t+h_2\e_{i_2}1_{\{\cdot \geq t+\varepsilon_2\}}+h_1\e_{i_1}1_{\{\cdot \geq t+\varepsilon_2+\varepsilon_1\}})|_{h_{1}=h_2=0}.
\end{align*}
As already argued above this means that, if $i_1\neq i_2$, $ U^{i_{2}} U^{i_{1}}F(t,\XX)$ and $ U^{i_{1}} U^{i_{2}}F(t,\XX)$ are computed by evaluating the functional at different paths. This differs from the computation in \eqref{eq: derivative Dupire} where, since the perturbation occurs at the same time, the functional is evaluated always at the same path. Observe furthermore that $$\partial_{i_2}\partial_{i_1}F(t,\XX)=\partial^2_{\xi_{i_{1}}\xi_{i_2}}G(\xi)|_{\xi=0},$$ for $G(\xi):=F(t,\XX+\xi1_{\{\cdot \geq t\}})$, $\xi \in \Rset^d$. Therefore, by Schwarz's theorem the mixed vertical derivatives as computed in \cite{D:09} are equal as long as the maps $\xi\mapsto \partial^2_{\xi_{i_{1}}\xi_{i_2}}G(\xi)$ are continuous in a neighborhood of $0$. Other considerations for accommodating the non-communicative nature of the higher-order derivatives have been made by \cite{DS19}.






The non-commutative behavior that we obtain here is particularly relevant when dealing with weakly geometric $p$-rough paths, for $p\in[2,3)$,  where the second order vertical derivatives appear in the \Ito-formula (see Sections~\ref{sec: into formula p23}). 
It is, however, also crucial for finite variation paths in view of the Taylor expansions (see Theorem~\ref{th: taylor 12}). 



\end{remark}












\subsection{Var-continuous path functionals}

In this section, we introduce the necessary regularity conditions for the path functionals to derive the results presented in the subsequent sections. Unless otherwise specified,  we let $p\in [1,3)$ and for $q\geq p$, we denote by $d_q$ the $q$-variation pseudometric on the space of \cadlag paths as defined in Section~\ref{sec: rough paths and rough integration}.

\begin{definition}\label{3def: var continuous funcitonals}
    Fix  $m\in \Nset_0$. We say that a path functional $F\in ((\Mcalp^0)^d)^{\otimes m}$ is \textit{$[p,[p]+1)$\text{-}var continuous} if for every $(\XX^n, \XX)_{n\in\Nset}\subset C^p([0,1],G^{[p]}(\Rset^{d}))$ such that for some  $q\in [p,[p]+1)$
    \begin{align*}
        \lim_{n\rightarrow\infty}d_q(\XX^n,\XX)=0,
    \end{align*}
 it holds that 
    \begin{align*}
\lim_{n\rightarrow\infty}d_{q'}(F(\cdot,\XX^n),F(\cdot,\XX))=0,
    \end{align*}
    for all $q'>q$.
    \end{definition}

    \begin{definition}
 Fix $m\in \Nset_0$. For $p\in [2,3)$ and $F\in ((\Mcal_2^0)^d)^{\otimes m}$, $F'\in ((\Mcal_2^0)^d)^{\otimes m+1}$, we say that a remainder path functionals $R^{F,F'}$, defined in Definition~\ref{3def: 2 parameter functional}, is \textit{$[p,3)$\text{-}var continuous} if for every $(\XX^n, \XX)_{n\in\Nset}\subset C^p([0,1],G^{2}(\Rset^{d}))$ such that for some  $q\in [p,3)$
    \begin{align*}
        \lim_{n\rightarrow\infty}d_q(\XX^n,\XX)=0,
    \end{align*}
 it holds that
    \begin{align*}
\lim_{n\rightarrow\infty}d_{q'/2}(R((\cdot,\cdot),\XX^n),R((\cdot,\cdot),\XX))=0,
    \end{align*}
    for all $q'>q$.


\end{definition}
\subsection{Linear functionals of the signature}\label{3sec: linear functions as Marcus}
This section is devoted to the study of linear functionals of the signature.
\begin{definition}
    Fix $\u\in T(\Rset^d)$. We call the path functional  
    \begin{align}\label{3eq: linear functional as Marcus}
    F^\u:&[0,1]\times D^p([0,1],G^{[p]}(\Rset^d))\rightarrow\Rset \\ \nonumber 
    & \quad (t,\XX)\longmapsto F^\u(t,\XX):=\langle \u,\X_t\rangle
\end{align} 
linear functional of the signature.
\end{definition}
\noindent The proof of the following proposition is given in Appendix \ref{proof prop: derivative linear func}.
\begin{proposition}\label{prop: derivative linear func}
    Let $F^\u :[0,1]\times D^p([0,1],G^{[p]}(\Rset^d))\rightarrow \Rset$  be a linear functionals of the signature for some $\u\in T(\Rset^d)$. Then, 
    \begin{enumerate}
        \item  \label{item 1 Fu}$F^\u$ is a non-anticipative Marcus canonical  path functional. 
        \item  \label{item 2 Fu}$F^\u$ is infinitely many times vertically differentiable and for all $k\in \Nset$, 
        \begin{align}\label{3eq: derivatives linear functionals}
    \nabla^k F^\u(t,\XX)=\langle \u^{(k)},\X_t\rangle,
\end{align}
for all $(t,\XX)\in [0,1]\times D([0,1],G^{[p]}(\Rset^d))$.
\item \label{item 3 Fu}$F^\u$ is $[
p,[p]+1)$-var continuous.
    \end{enumerate}
\end{proposition}






Now, a direct combination of Proposition~\ref{prop: derivative linear func} and equations~\eqref{eq: u,signature p12} and~\eqref{eq: u,signature p23} yields the functional \Ito-formula for linear functionals of the signature. 
\begin{lemma}\label{lemma: into linear func}
    Let $F^\u :[0,1]\times D^p([0,1],G^{[p]}(\Rset^d))\rightarrow \Rset$  be a linear functional of the signature for some $\u\in T(\Rset^d)$. Then, the following functional \Ito-formulas hold.
    \begin{enumerate}
      \item If $p\in [1,2)$,
      \begin{align*}
	F^\u(t,\XX)=&F^\u(0,\XX)+ \int_0^t \nabla F^\u(s^-,\XX) d\XX_{s}\\
  &+\sum_{0<s\leq t}F^\u(s,\XX) -F^\u(s^-,\XX)-\Delta F^\u(s^-,\XX) \Delta X_{s}.  \nonumber 
		\end{align*}
The integral term 
 is a Young integral of $\nabla F^\u(\cdot,\XX) \in D^p([0,1],\Rset^{d+1})$ with respect to $\XX$.
  \item If $p\in [2,3)$,
      \begin{align*}
		F^\u(t,\XX) =&  F^\u(0,\XX)+\int_0^t F^\u(s^-,\XX)d\XX_s\\
  &+\sum_{0<s\leq t}F^\u(s,\XX) -F^\u(s^-,\XX) -\nabla F^\u(s^-,\XX) \Delta X_{s}-\nabla^2F^\u(s^-,\XX) \Delta \X^{(2)}_{s}.\nonumber 
		\end{align*}
The integral term is a rough integral of  $\big (\nabla F^\u(\cdot,\XX),\nabla^2 F^\u(\cdot,\XX)\big) \in \mathcal{V}^{p,\frac{p}{2}}_{\XX}$  with respect to $\XX$.
  \end{enumerate}


\end{lemma}




\section{Universal approximation theorem for vertically differentiable path functionals}\label{sec: uat differential}
In this section, we exploit the approximation properties of the signature of weakly geometric \cadlag $p$ rough paths to derive a universal approximation theorem (UAT) for non-anticipative Marcus canonical path functionals which are  vertically differentiable (Theorem \ref{3th: Nachbin for path functionals}).

This result for path functionals is analogous to the classic Nachbin theorem, which provides an analog to the Stone-Weierstrass theorem for algebras of $C^K$ functions on  $\Rset^d$, for $K\in \Nset$ (see~\cite{N:49}). 





\subsection{The subspace of the tracking-jumps-extended paths}


First, we introduce the subset of paths considered for deriving the UAT. We call them \textit{tracking jumps-extended paths}. The distinctive feature of these paths is that they always admit a Marcus transformed path that is time-extended (see Remark~\ref{3rem: Marcus tracking-jumps paths}\ref{ii}). This is a key aspect both for the development of the proof of Theorem~\ref{3th: Nachbin for path functionals} and the main results in Sections~\ref{3sec: functional Ito formula} and~\ref{sec: functional taylor}.

The notion of tracking jumps-extended paths relies on the more general one of 
extended weakly geometric \cadlag rough path, which we give below. Roughly speaking this space consists of all the weakly geometric  \cadlag  $p$-rough paths with values in $G^{[p]}(\Rset^{d+1})$ obtained through the addition of an auxiliary path component of finite variation to some $\XX\in D^p([0,1],G^{[p]}(\Rset^{d}))$. When $p\in [1,2)$, this extension is quite straightforward. When $p\in [2,3)$ instead, 
one needs to ensure consistency between the Young and the (level 2) rough integration (see Section \ref{sec: rough=young}), while preserving the group-valued constraint. For the explanation of the index $0$ used here we refer to Notation~\ref{notation: index 0} below.
\begin{definition}\label{def: Marcus extended rough paths}
    Fix $Z\in D^1([0,1],\Rset)$ and $\widehat{\XX}\in D^p([0,1],G^{[p]}(\Rset^{d+1})).$
    \begin{enumerate}
        \item If $p\in [1,2)$, we say that $\wXX$ is a $Z$-extended weakly geometric \cadlag $p$-rough path if for all $i=1,\dots,d$, 
    \begin{align*}
        \langle \e_i,\wXX\rangle = \langle \e_i,\XX\rangle, \quad \text{and }\quad   \langle \e_{0},\wXX\rangle = Z,
    \end{align*}
     for some $\XX\in D^p([0,1],G^1(\Rset^d))$. 
     \item If $p\in [2,3)$,    
    we say that $\wXX$ is a $Z$-extended weakly geometric \cadlag $p$-rough path if for all $i,j=1,\dots,d$, 
    \begin{align*}
        \langle \e_i,\wXX\rangle = \langle \e_i,\XX\rangle, \qquad   \langle \e_{(ji)},\wXX\rangle = \langle \e_{(ji)},\XX\rangle, \qquad  \langle \e_0,\wXX\rangle = Z, 
    \end{align*}
    and for all $i=0,\dots,d$,
     \begin{align}\label{eq: components extended paths}
   \langle \e_{(i,0)},\wXX\rangle =\int_0^\cdot  \langle \e_i,\wXX_{0,s^-}\rangle dZ_s+\frac{1}{2} \sum_{0<s\leq \cdot}\Delta  \langle \e_i,\wXX_s\rangle \Delta Z_s.
    \end{align}
    for some $\XX\in D^p([0,1],G^2(\Rset^d))$, and the integral in~\eqref{eq: components extended paths} is of Young type.
    \end{enumerate}

\end{definition}

\begin{notation}\label{notation: index 0}
Unless explicitly mentioned, we use throughout the paper the index $0$ to denote the additional auxiliary component $Z$ of $\wXX$.
\end{notation}


\begin{remark}\phantomsection\label{rem: extended paths}
\begin{enumerate}

\item Let $p\in [2,3)$. Notice that by definition any $Z$-extended weakly geometric \cadlag $p$-rough path $\wXX$ lies in $G^2(\Rset^{d+1})$. Therefore, by the 
shuffle property~\eqref{3eq:shuffle}, for all $i=0,1,\dots,d$, $t\in [0,1]$,  $$\langle \e_{(0,i)},\widehat{\mathbf{X}}_t\rangle=Z_t \langle \e_{i},\widehat{\mathbf{X}}_t\rangle-\langle \e_{(i,0)},\widehat{\mathbf{X}}_t\rangle.$$
Moreover, since $Z\in D^1([0,1],\R)$ and $\langle \e_i,\XX\rangle \in D^p([0,1],\R)$, the Young integral in~\eqref{eq: components extended paths} is well defined and for all $t\in [0,1]$, 
\begin{align*}
  \sum_{0<s\leq t}|\Delta \langle \e_i,\wXX_s\rangle \Delta Z_s|\leq \left(\sum_{0<s\leq t}|\Delta \langle \e_i,\wXX_s\rangle|^{3}\right)^{1/3}\left(\sum_{0<s\leq t}| \Delta Z_s|^{\frac{3}{2}}\right)^{2/3}<\infty.
  \end{align*}
This implies that the path defined in equation~\eqref{eq: components extended paths} is of finite variation and the definition is well-posed. 

\item \label{item 4 remark extended path} One can see that given $Z\in D^1([0,1],\R)$ and $\XX\in D^p([0,1],G^{[p]}(\Rset^d))$, it is always possible to build a $Z$-extended weakly geometric $p$-rough path $\wXX$ as in Definition~\ref{def: Marcus extended rough paths}. The reverse is trivially true.

\end{enumerate}

\end{remark}

\noindent Now, we are ready to introduce the set of tracking jumps-extended paths.






 \begin{definition}\label{3def: tracking-jumps paths}
    We say that $\wXX\in {D}^p([0,1],G^{[p]}(\Rset^{d+1}))$  is a \textit{tracking-jumps-extended weakly geometric \cadlag $p$-rough path} if it is the $Z$-extension of some $\XX\in {D}^p([0,1],G^{[p]}(\Rset^{d}))$, for a \cadlag strictly increasing  piecewise linear function
    $ Z:[0,1]\rightarrow[0,1]$ such that $Z_0=0$, $Z_1=1$, and
 \begin{align*}
     \{s\in (0,1] \ : \ \Delta Z_s\neq 0\}= \{s\in (0,1] \ : \ \Delta \XX_s\neq 0\}.
 \end{align*}
 We call such a path $Z$ 
 \textit{tracking-jumps-path} of $\XX$ and denote the set of such $Z$-extended \cadlag 

 (continuous) paths by $\widehat{D}^p([0,1],G^{[p]}(\Rset^{d+1}))$ ($\widehat{C}^p([0,1],G^{[p]}(\Rset^{d+1}))$). 
 \end{definition}
 \begin{remark}\label{3rem: Marcus tracking-jumps paths}
 \begin{enumerate}
   \item \label{3item rem tracking-jumpsp ii} Given $\XX\in {D}^p([0,1],G^{[p]}(\Rset^{d}))$ it is always possible to build (non-uniquely) a tracking-jumps path associated with it. If $\XX$ is continuous, the tracking-jumps path is unique and given by the identity path $\text{Id}_u:=u$ for all $u\in [0,1]$. For $\XX$ \cadlag, there exists more than one tracking-jumps-extension $\wXX$.  We refer to every Id-extended continuous path as \textit{time-extended path}.

    Notice in particular that the existence of a tracking-jumps-extension is related only to the \cadlag property of the original path. 

     \item \label{ii}  Observe  that for all $\wXX\in \widehat{D}^p([0,1],G^{[p]}(\Rset^{d+1}))$  there always exists a Marcus-transformed path of $\wXX$ with respect to some pair $(R,\psi_R)$, which is a time-extended weakly geometric continuous $p$-rough path.
Indeed, since a tracking-jumps path is simply a strictly increasing piecewise linear path $Z$ such that $Z(0)=0$ and $Z(1)=1$ and jumps whenever the other components of the path do,  a pair $(R,\psi_R)$ can be chosen to ensure a Marcus-transformed path for which the transformed component $\widetilde{Z}$ satisfies $\widetilde{Z}_u=u$ for all $u\in [0,1]$.



 \end{enumerate}

 \end{remark}





\subsection{UAT for vertically differentiable path functionals} 
To present the main result of the section (Theorem~\ref{3th: Nachbin for path functionals}), we shall introduce some notation and new definitions. Since we will be mostly concerned with paths with values in $G^{[p]}(\Rset^{d+1})$, we introduce the relevant notions by considering directly the space $\Rset^{d+1}$.

\begin{notation}\label{3notation derivatives lie algebra}
     Let $K\in \Nset$ and $\mathfrak{g}^K(\Rset^{d+1})$ be the free step-$K$ nilpotent Lie algebra over $\Rset^{d+1}$ (see Section~\ref{3sec: algebra}). Recall that for every $  \bxi:=(0,\bxi^{(1)},\dots,\bxi^{(K)}) \in \mathfrak{g}^K(\Rset^{d+1})$, $$\bxi^{(j)}:=\pi_{j}(\bxi)\in \underbrace{[\Rset^{d+1},[\Rset^{d+1},\dots ,[\Rset^{d+1},\Rset^{d+1}]]]}_{(j-1)\text{ brackets}},$$  for $j=1,\dots, K$. Set $M:=\text{dim}(\mathfrak{g}^K(\Rset^{d+1}))=\sum_{j=1}^K M_j$ and 
\begin{align*}
    M_j:=\text{dim}(\underbrace{[\Rset^{d+1},[\Rset^{d+1},\dots ,[\Rset^{d+1},\Rset^{d+1}]]]}_{(j-1)\text{ brackets}}).
\end{align*}
For $\beta \in \Nset_0^{M}$, we write $\beta=(\beta_1,\dots,\beta_K)$, with $\beta_j\in \Nset_0^{M_j}$, and set
\begin{align}\label{3eq: beta weighted}|\beta|:=\sum_{j=1}^K  \sum_{i=1}^{M_j}\beta^i_j,\qquad \text{and}\quad |\beta|_{\mathfrak{g}^K(\Rset^{d+1})}:=\sum_{j=1}^K  \sum_{i=1}^{M_j}j\beta^i_j. 
\end{align}Furthermore, let  $\partial^{\beta_j}_{\bxi^{(j)}}$ denote the differential operator  such that 
$$\partial^{\beta_j}_{\bxi^{(j)}}f(\bxi):=\frac{\partial^{|\beta_j|}f}{\partial ^{\beta_j^1}\bxi^{(j),1}\dots\partial ^{\beta_{j}^{M_j}}\bxi^{(j),M_j} }(\bxi),$$ 
for $\bxi^{(j),l}$ denoting the $l$-th component of $\bxi^{(j)}$, $|\beta_j|:=\sum_{i=1}^{M_j}\beta^i_j$, and 
$f:\mathcal{U}\rightarrow \R$ some sufficiently regular map defined on some open set $\mathcal{U}\subseteq \mathfrak{g}^K(\Rset^{d+1})$,  with $\bxi\in \mathcal{U}$. 

\noindent Finally, denote by
$D^\beta_{\bxi}:=\partial_{\bxi^{(1)}}^{\beta_1}\dots \partial_{\bxi^{(K)}}^{\beta_K}$ the operator given by a consecutive application of $\partial_{\bxi^{(1)}}^{\beta_1},\dots, \partial_{\bxi^{(K)}}^{\beta_K}$.





\end{notation}





 \noindent Recall that $G((\Rset^{d+1}))$ denotes the set of group-like elements, introduced in equation~\eqref{3eq: G group inf}.

\begin{assumpt}\label{assumpt 1}
     $F:[0,1]\times D^{p}([0,1],G^{[p]}(\Rset^{d+1}))\rightarrow \Rset$ is a Marcus canonical  non-anticipative path functional such that for all $(t,\XX)\in [0,1]\times {C}^p([0,1],G^{[p]}(\Rset^{d+1}))$,
    \begin{align}\label{eq: F=g assumpt}
        F(t,\XX)=g(\X_t),
    \end{align}
    for some $g:G((\Rset^{d+1}))\rightarrow\Rset$, and $\X$ denoting the signature of $\XX$.
\end{assumpt}
\begin{remark}\label{remark F tilde F}
\begin{enumerate}
    \item 
    By the definition of Marcus canonical  path functionals and the signature of \cadlag rough paths, the equality~\eqref{eq: F=g assumpt} is valid in fact on $[0,1]\times {D}^{p}([0,1],G^{[p]}(\Rset^{d+1}))$.

 \item \label{remark F tilde F ii} Let $S$ be the map such that for all $\XX\in {C}^p([0,1],G^{[p]}(\Rset^{d+1})) $, $S(\XX):=\X_1$. For $t\in [0,1]$, let $\widehat{C}^p_t([0,1],G^{[p]}(\Rset^{d+1}))$ denote the space of time-extended paths stopped at time $t$. One can show that on  the set
 \begin{align*}
     \bigcup_{t\in [0,1]}\widehat{C}_t^p([0,1],G^{[p]}(\Rset^{d+1}))
 \end{align*}
 $S$ is an injective map (see e.g., the proof of Proposition 3.6 in \cite{CPS:22}). Therefore, the restriction of 
 the map $S$ to its image, denoted as $\mathcal{S}$, is a bijection.
 Furthermore, consider the map $\widetilde{F}:   \bigcup_{t\in [0,1]}\widehat{C}_t^p([0,1],G^{[p]}(\Rset^{d+1}))\rightarrow\Rset $ given by $ \widetilde{F}(\wXX^t):=  F(t,\wXX^t)$
and notice that $F$ admits a representation of the form
 \begin{align}\label{eq: bar g}
     F(t,\wXX^t)=\bar g(\wX_t),
 \end{align}
 for $\bar{g}:\mathcal{S}\rightarrow \Rset$ given by $\bar{g}:=\widetilde{F}\circ S^{-1}$ and every (stopped) time-extended continuous path $\wXX^t$. {\color{blue} Notice that the above reasoning applies in fact to the larger set of \cadlag paths}.
 However, in general, the set $\mathcal{S}\subsetneq G((\Rset^{d+1}))$ might not be big enough for the application of the reasonings in the proofs of Lemma~\ref{lemma: partial derivatives gk} and Theorem~\ref{3th: Nachbin for path functionals}, which involve some ideas from Lie group theory (see \cite{BLU:07}).
 \end{enumerate}

\end{remark}
\noindent The proof of the following lemma is given in Appendix~\ref{proof of lemma: partial derivatives gk}.  
\begin{lemma}\label{lemma: partial derivatives gk}
    Let $F\in \Mcalp^K$, for some $K\in \Nset$. Fix $\XX\in[0,1]\times  C^p([0,1],G^{[p]}(\Rset^d))$ and denote by $\X$ its signature. Under Assumption~\ref{assumpt 1}, the map
    \begin{align}\label{eq: gk assumpt lemma}
        g^{\XX,K}:&[0,1]\times  \mathfrak{g}^K(\Rset^{d+1})\rightarrow\Rset\\
          & \qquad (t,\bxi)\mapsto g^{\XX,K}(t,\bxi):= g(\X_t\otimes \exp(\bxi,0\dots,0)) \nonumber
    \end{align}
 is well defined and its derivatives at zero $D^\beta_{\bxi}g^{\XX,K}(t,\bxi)|_{\bxi=0}$ exist for all $|\beta|_{\mathfrak{g}^K(\Rset^{d+1})}\leq K$. 
\end{lemma}
\noindent For the development of the following results, we need the map $g^{\XX,K}$ to satisfy some stronger continuity conditions in the next assumption.
\begin{assumpt}\label{assumpt 2}
   For all $ \XX\in C^p([0,1],G^{[p]}(\Rset^d))$, the map
\begin{align*}
       [0,1]\times \mathcal{U}(0)\ni  (t,\bxi)\mapsto D^\beta_{\bxi} g^{\XX,K}(t,\bxi)
    \end{align*}
    is jointly continuous for all $|\beta|_{\mathfrak{g}^K(\Rset^{d+1})}\leq K$, and  some open neighborhood $\mathcal{U}(0)$ of $0\in \mathfrak{g}^K(\Rset^{d+1})$. 


\end{assumpt}
    \begin{remark}
 Under Assumption~\ref{assumpt 2}, the map $\mathcal{U}(0)\ni \bxi\mapsto D^\beta g^{\XX,K}(t,\bxi)$ does not depend on the order of the partial derivatives (see Step 2 in the proof of Theorem~\ref{3th: Nachbin for path functionals}).
\end{remark}

\begin{definition}\label{3def: C^K path functionals}
    Let  $F:[0,1]\times D^{p}([0,1],G^{[p]}(\Rset^{d+1}))\rightarrow \Rset$. We write $F\in C^K$ if $F\in \Mcalp^K$ and Assumptions~\ref{assumpt 1} and~\ref{assumpt 2} are satisfied.
\end{definition}
\noindent An example of path functional satisfying the assumptions of Definition~\ref{3def: C^K path functionals} is given by the linear functionals of the signature $F^\u$, for some $\u \in T(\Rset^{d+1})$ (see Section~\ref{3sec: linear functions as Marcus}). Then, by Proposition~\ref{prop: derivative linear func} $F^\u\in C^K$ for all $K\in \Nset$, and the map~\eqref{eq: gk assumpt lemma} explicitly reads as
     \begin{align*}
          g^{\XX,K}(t,\bxi):= \langle \u,\X_t\otimes \exp(\bxi,0\dots,0)\rangle,
     \end{align*}
     for all $(t,\bxi)$ and $\XX$.

\begin{remark}\label{remark: CK functionals}
    For $m\in \Nset_0$, $K\in \Nset$ and a $(\Rset^d)^{\otimes m}$-valued
     path functional $F$, we write $F\in C^K$
     if its components
    are $C^K$. Notice that if $F\in C^K$, then for all $l=1,\dots,K$, $\nabla^lF\in C^{K-l}$.
\end{remark}




Now we state the main result of the section stating that any path functionals $F \in C^K$ when evaluated at a {tracking jumps}-extended path $\wXX$ (Definition~\ref{3def: tracking-jumps paths}), can be uniformly approximated in time, along with its derivatives, by linear functionals of the signature and its derivatives.






\begin{theorem}\label{3th: Nachbin for path functionals}
 Let $F:[0,1]\times D^{p}([0,1],G^{[p]}(\Rset^{d+1}))\rightarrow \Rset$. Assume $F\in C^K$.
Then, for all  $\widehat \XX\in \widehat{D}^p([0,1], G^{[p]}(\Rset^{d+1}))$ there exists $(\u_n)_{n\in \Nset}\in T(\Rset^{d+1})$ (possibly depending on $\widehat \XX$) such that
    \begin{align}\label{3eq: uat derivatives}
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{j=0}^K\|\nabla ^jF(t,\widehat \XX)-\nabla ^jF^{\u_n}(t,\widehat \XX)\|=0.
    \end{align}
\end{theorem}

 The proof of Theorem \ref{3th: Nachbin for path functionals} is given in Appendix~\ref{3sec: proof Nachbin}. 














































\section{Functional \Ito-formula}\label{3sec: functional Ito formula}
\subsection{The case \texorpdfstring{$p\in [1,2)$}{p in [1,2)}}
In this section, we present the functional \Ito-formula for maps of \cadlag rough paths of finite $p$-variation, for $p\in[1,2)$.


\begin{theorem}\label{3th: Ito formula p 12}
  Let $p\in[1,2)$ and $F:[0,1]\times D^{p}([0,1],G^{1}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^2$-non-anticipative Marcus canonical  path functional such that $F$ and $\nabla ^{}F$ are $[p,2)$\text{-}var continuous. Then, for every $ \wXX\in \widehat{D}^{p}([0,1],G^{1}(\Rset^{d+1}))$ the path $\nabla F(\cdot,\wXX)$ is a \cadlag path of finite $p'$-variation, for all $p'> p$ such that 
  $\frac{1}{p'}+\frac{1}{p}>1$, 
  and for all
$t\in [0,1]$, 
    \begin{align}\label{3eq: ito formula p 12}
        F(t,  \wXX)-&F( 0, \wXX)=\int_0^t \nabla F(s^-,  \wXX)d \wXX_s\\
         &+\sum_{0<s\leq t}F(s,\wXX)-F(s^-,\wXX)-\nabla ^{}F(s^-,\wXX) \Delta \wXX_s. \nonumber 
    \end{align}
      The integral in~\eqref{3eq: ito formula p 12} is  a Young integral and the summation term is well defined as an absolutely summable series.
\end{theorem}
To prove Theorem~\ref{3th: Ito formula p 12} we make use of the following lemma, proved in Appendix \ref{proof lemma ito formula p12}.




\begin{lemma}\label{3lemma: ito formula uniformly bounded p 12}.
Let $p\in[1,2)$, $F:[0,1]\times D^{p}([0,1],G^{1}(\Rset^{d+1}))\rightarrow \Rset$ be such that $F\in \Mcal_1^2$ and $\widehat \XX\in  \widehat C^{1}([0,1],G^1(\Rset^{d+1}))$ a time-extended piecewise linear path. Assume that there exists $(\u_n)_{n\in\Nset}\subset T(\Rset^{d+1})$ such that 
\begin{align}\label{eq: approx F and derivatives p 12}
     \lim_{n\rightarrow\infty} \sup_{t\in [0,1]}\sum_{j=0}^2\|\nabla ^jF(t,\widehat \XX)-\nabla ^jF^{\u_n}(t,\widehat \XX)\|=0.
\end{align}
Then,  
\begin{enumerate}
    \item \label{3item: lemma 1 i} $\sup_{n\in \Nset}\|\nabla F^{\u_n}(\cdot,\widehat \XX)\|_{1\text{-}var}<\infty$;
    \item \label{3item: lemma 1 ii}  for all $p'>1$, $\lim_{n\rightarrow\infty}d_{p'}\big(\nabla F^{\u_n}(\cdot,\widehat \XX), \nabla F(\cdot,\wXX)\big)=0.$ 
\end{enumerate}
    \end{lemma}









\begin{proof}[Proof of Theorem~\ref{3th: Ito formula p 12}] We split the proof into three main steps. Step 1 proves the assertion for functionals evaluated at a time-extended piecewise linear path. Then, Step 2 extends it to the whole space of time-extended continuous paths by a density argument.  Finally, Step 3 extablishes the general result by exploiting that the functionals considered are of Marcus type and an adaptation of the proof of Theorem 38 in~\cite{FS:17}, which deals only with functional given as the solution of Marcus-RDE.

\paragraph{Step 1:} Let $\widehat \XX\in  \widehat C^{1}([0,1],G^1(\Rset^{d+1}))$ be a time-extended peicewise linear path. Since $F$ is a $C^2$-non-anticipative path functional, by  Theorem~\ref{3th: Nachbin for path functionals} there exists a sequence $(\u_n)_{n\in\Nset}\subset T(\Rset^{d+1})$ such that the convergence in equation \eqref{eq: approx F and derivatives p 12} holds true.
By Lemma~\ref{3lemma: ito formula uniformly bounded p 12}~\ref{3item: lemma 1 i} and Lemma 5.12 in~\cite{FV:10}, $  \|\nabla F(\cdot ,\wXX)\|_{1\text{-}var}<\infty$ and thus in particular 
\begin{align}\label{3eq: finite p' var }
  \|\nabla F(\cdot ,\wXX)\|_{p'\text{-}var}<\infty,
\end{align}
for all $p'\geq1$. 
Fix $p'>1$. By Lemma~\ref{3lemma: ito formula uniformly bounded p 12}~\ref{3item: lemma 1 ii} $\lim_{n\rightarrow\infty}d_{p'}\big(\langle \u_n^{(1)},\widehat{\mathbb{X}}_{\cdot}\rangle,\nabla F(\cdot ,\wXX)\big)=0.$ Moreover, by Proposition 6.11 in~\cite{FV:10}, for all $n\in \Nset$,
\begin{align*}
    d_1\bigg(&\int_0^\cdot \langle \u^{(1)}_n,\widehat{\mathbb{X}}_{s}\rangle d\widehat{\XX}_{s}, \int_0^\cdot \nabla F(s,\widehat{\XX}) d\widehat{\XX}_{s}\bigg) \\&
    \leq C \bigg( \dcc\big(\langle \u_n^{(1)},\widehat{\mathbb{X}}_0\rangle,\nabla F(0,\widehat{\XX})\big)+d_{p'}\big(\langle \u_n^{(1)},\widehat{\mathbb{X}}_{\cdot}\rangle,\nabla F(\cdot ,\wXX)\big)\bigg),
\end{align*}
for some $C>0$. Since for all $n\in \Nset$, $j=0,\dots,2$, $\nabla ^jF^{\u_n}(t,\widehat \XX)=\langle \u_n^{(j)},\widehat \X_t\rangle$, where $\wX$ denotes the signature of $\wXX$, and by  equation~\eqref{eq: u,signature p12} for every $n\in \Nset$ and $t\in [0,1]$,  $\langle \u_n,\widehat{\mathbb{X}}_{t}\rangle =  \langle \u_n,\widehat{\mathbb{X}}_{0}\rangle+\int_0^t \langle \u^{(1)}_n,\widehat{\mathbb{X}}_{s}\rangle  d\widehat{\XX}_{s}$, the claim follows.

\paragraph{Step 2:} Fix $\widehat \XX \in  \widehat C^{p}([0,1],G^{1}(\Rset^{d+1})) $. By Theorem 5.23 in~\cite{FV:10}, there exists a sequence  of piecewise linear time-extended paths $(\widehat \XX^M)_{M\in \N}$ such that 
    \begin{align}\label{3eq: approximation w.g.p 12}
        \lim_{M\rightarrow\infty }\sup_{t\in [0,1]}d_{CC}(\widehat \XX^M_t,\widehat \XX_t)=0, \qquad \text{and}\qquad    \sup_{M\in \Nset}\|\widehat \XX^M\|_{p\text{-}var}\leq C\|\widehat \XX\|_{p\text{-}var},
    \end{align}
    for some $C>0$. By Step 1, for every fixed $M$ and $t\in [0,1]$, it holds that 
        \begin{align*}
        F(t, \widehat \XX^M)-F(0, \widehat \XX^M)=\int_0^t \nabla^{} F(s, \widehat \XX^M)d\widehat \XX^M_s.
    \end{align*}
    By conditions~\eqref{3eq: approximation w.g.p 12} and interpolation (see Lemma 5.12 and Lemma 5.27 in~\cite{FV:10}), for all $p'>p$, $  \lim_{M\rightarrow\infty }d_{p'}(\widehat \XX^M, \widehat \XX)=0.$

Since by Step 1 (see equation~\eqref{3eq: finite p' var }) for all $M$, $\|\nabla ^{}F(\cdot,\widehat \XX^M)\|_{p'\text{-}var}<\infty$, for all $p'\geq1$, and  $\nabla ^{}F$ is  $[p,2)$\text{-}var continuous by assumption, $\|\nabla ^{}F(\cdot,\widehat \XX)\|_{p'\text{-}var}<\infty$ for all $p'>p$ such that $\frac{1}{p'}+\frac{1}{p}>1$.

 Fix $p''>p'>p$ such that  $\frac{1}{p''}+\frac{1}{p'}>1$ and observe that $\wXX,\wXX^M\in \widehat{C}^{p'}([0,1], G^1(\Rset^{d+1}))$,  for all $M\in \Nset$,  and since  $  \nabla F(\cdot,\widehat \XX),\nabla F(\cdot,\widehat \XX^M)\in {C}^{p''}([0,1], \Rset^{d+1})$ as well, the Young integral of the integrands $\nabla F(\cdot,\widehat \XX),\nabla F(\cdot,\widehat \XX^M)$ with respect to $\wXX,\wXX^M$, respectively, is well defined. Finally, by Proposition 6.11 in~\cite{FV:10}, for all $M\in \Nset$,
\begin{align*}
   d_{p'}\bigg(&\int_0^\cdot \nabla^{} F(s, \widehat \XX^M)d\widehat \XX^M_s,\int_0^\cdot  \nabla^{} F(s, \widehat \XX)d\widehat \XX_s\bigg)\\
    &\leq  {C}\bigg(d_{p'}(\widehat \XX^M, \widehat \XX)+d_{CC}\big(\nabla^{} F(0, \widehat \XX^M),\nabla F(0, \widehat \XX)\big)+d_{p''}\big(\nabla F(\cdot, \widehat \XX^M),\nabla F(\cdot, \widehat \XX)\big)\bigg),
\end{align*}
for some ${C}>0$.  The claim follows as in Step 1.

\paragraph{Step 3:} Let $\wXX\in \widehat{D}^p([0,1],G^1(\Rset^{d+1}))$. For notational convenience,
let  $\ZZ\in \widehat{C}^p([0,1],G^{1}(\Rset^{d+1})$ denote the time-extended Marcus-transformed path of $\wXX$ and  let $\mu_t\in [0,1]$ be such that $\ZZ_{\mu_t}=\wXX_{t}$ for all $t\in [0,1]$ (see Notation~\ref{3notation: mut}).  By Step 1 and Step 2, $\nabla F(\cdot,\ZZ)$ is a continuous path of finite $p'$-variation, for all $p'> p$ such that 
  $\frac{1}{p'}+\frac{1}{p}>1$. Since $\nabla F$ is a Marcus canonical  path functional, for all $t\in [0,1]$,
  \begin{align*}
      \nabla F(t,\wXX)=\nabla F(\mu_t,\ZZ),
  \end{align*}
  implying by definition of $\mu_t$ that $\nabla F(\cdot,\wXX)$ is a \cadlag path of finite $p'$-variation. 

\noindent Next, assume first that $\wXX$ admits only one jump at time $a\in (0,1]$. Suppose that $t<a$. By the arguments in Step 2 applied to $\ZZ$, 
   \begin{align*}
       F(\mu_t,\ZZ)= F(0,\ZZ)+\int_0^{\mu_t}\nabla F(s,\ZZ)d\ZZ_s.
   \end{align*}
Observe that 
$\nabla F\in \Mcal_1^1\subset  \Mcal_1^0 $ implies that $\nabla F$ is an invariant under reparametrization path functional (see Proposition~\ref{3prop: F Marcus canonical then F invariant}). This, combined with the property of the Young integral, yields that the functional
\begin{align*}
    G: [&0,1]\times C^{p}([0,1],G^{1}(\Rset^{d+1}))\rightarrow \Rset \\
    &(t,\YY)\mapsto G(t,\YY):=\int_{0}^t\nabla F(s,\YY)d\YY_s
\end{align*}
is also invariant under reparametrization. Thus, for $t<a$,   $\int_0^{\mu_t}\nabla F(s,\ZZ)d\ZZ_s=\int_0^{t}\nabla F(s^-,\wXX)d\wXX_s$, as the stopped path $\ZZ^{\mu_t}$ is nothing but a time-reparametrization of the continuous path $\wXX^t$.
Since $F(\mu_t,\ZZ)=F(t,\wXX)$, $F(0,\ZZ)=F(0,\XX)$, the claim follows. Next, suppose that $t\geq a$ and observe that
          \begin{align*}
       &F(\mu_t,\ZZ)- F(\mu_a,\ZZ)=\int_{\mu_a}^{\mu_t}\nabla F(s,\ZZ)d\ZZ_s=\int_{a}^t\nabla F(s^-,\wXX)d\wXX_s,\\
        &F(\mu_a,  \ZZ)-F(\mu_{a^-},  \ZZ)=F(a,  \wXX)-F({a^-},\wXX),\\
        &F(\mu_{a^-},  \ZZ)-F(0,  \ZZ)=\int_0^{\mu_{a^-}} \nabla^{} F(s,   \ZZ)d \ZZ_s=\int_{0}^{a} \nabla^{} F(s^-,   \wXX)d  \wXX_{s}-\nabla^{} F(a^-,   \wXX)\Delta \wXX_a.
   \end{align*}
        The claim follows by combining all three terms.
        The argument extends trivially to a \cadlag paths with finitely many jumps. Finally, let $\wXX$ be a \cadlag path with countable many jumps. By the arguments in Step 2 applied to $\ZZ$, for $\varepsilon>0$, there  exists  $\eta>0$ and a partition ${\pi}_{[0,\mu_t]}$ with $|{\pi}_{[0,\mu_t]}|<\eta $ such that 
         \begin{align*}
             \big\|F(\mu_t,  \ZZ)-F(0, \ZZ)-\sum_{s_{i}\in {\pi}_{[0,\mu_t]}}\nabla F( s_{i},\ZZ)\ZZ_{ s_{i}, s_{{i+1}}}\big \|<\frac{\varepsilon}{2}.
        \end{align*}
           Since $\wXX$ has finite $p$-variation, for $p\in [1,2)$, we can find a finite set $B(\varepsilon,t)\subset[0,t]$ of jump times of  $\wXX$ such that $ \sum_{s\leq t, \ s \notin B(\varepsilon,t)} \|\Delta \wXX_s\|^2<\frac{\varepsilon}{2}.$ 
         Without loss of generality, we may assume that if $t_j\in B(\varepsilon,t)$, then $\mu_{t_j^-},\mu_{t_j}\in {\pi}_{[0,\mu_t]}$. Thus, repeating earlier arguments, there exists a partition ${\pi}_{[0,t]}$  such that
           \begin{align}\label{3eq: ito cadlag p12 sum big jumps}
             \big \|&F(t,  \wXX)-F(0, \wXX)-\sum_{{s_i}\in {\pi}_{[0,t]}}\nabla F({s_i},{\wXX}){\wXX}_{{s_i},{s_{i+1}}}\\
             & \quad \quad -\sum_{ s\in B(\varepsilon,t)} F(s,\wXX)-F(s^-,\wXX)-\nabla ^{}F(s^-,\wXX) \Delta \wXX_s\big\|<\frac{\varepsilon}{2}.\nonumber 
        \end{align}
        Next, let $(\u_n)_{n\in \N}\subset T(\Rset^{d+1})$ be such that $ \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{j=0}^2\|\nabla ^jF(t,\widehat \XX)-\langle \u_n^{(j)},\widehat \X_t\rangle\|=0,$ from Theorem~\ref{3th: Nachbin for path functionals}. By Remark~\ref{3rem: after proof Nachbin}\ref{3rem: after proof Nachbin i}, for all $n\in \Nset$,
           \begin{align*}
            \sum_{s\notin B(\varepsilon,t)} &\|\langle \u_n,\wX_s\rangle -\langle \u_n,\wX_{s^-}\rangle-\langle \u^{(1)}_n,\wX_{s^-}\rangle \Delta \wXX_s\|\\
          &  \leq
             \sup_{n\in\Nset} \sup_{s\notin B(\varepsilon,t)}\sup_{\theta \in [0,1]}\|\langle\u_n^{(2)},\widehat \X_{s^-} \otimes \exp( \theta\log^{(1)}(\Delta  \widehat\XX_{s}))\rangle\|
             \sum_{s\notin B(\varepsilon,t)} \|\Delta \wXX_s\|^2<\infty,
        \end{align*}
       an application of the dominated convergence theorem yields that
        \begin{align*}
            \sum_{s\notin B(\varepsilon,t)} \|F(s,\wXX)-F(s^-,\wXX)-\nabla ^{}F(s^-,\wXX) \Delta \wXX_s\|<\infty.
        \end{align*}
       Thus, repeating the above argument, we can take $\varepsilon>0$  such that  
         \begin{align}\label{3eq: RRS ito p 12}
          F(t,  \wXX)-F(0, \XX)= &\lim_{(RRS)|\pi_{[0,t]}|\rightarrow 0}\sum_{{s_i}\in \bar{\pi}_{[0,t]}}\nabla F({s_i},{\wXX}){\wXX}_{{s_i},{s_{i+1}}}\\
              &-\sum_{0<s\leq t} F(s,\wXX)-F(s^-,\wXX)-\nabla ^{}F(s^-,\wXX) \Delta \wXX_s. \nonumber 
             \end{align}
             Since $\wXX$ is a \cadlag path, by Proposition 2.4 in~\cite{FZ:17}, the convergence in equation~\eqref{3eq: RRS ito p 12} holds in Mesh Riemann-Stieltracking-jumpses sense (see Definition~\ref{3def: MRS RRS}) and the claim follows. 



\end{proof}

\begin{remark}
 \label{3rem: Ito formula p12} An inspection of the above proof shows that we can replace the hypothesis of $F$ being $[p,2)$-var continuous with the assumption that for every $(\XX^n, \XX)_{n\in\Nset}\subset C^p([0,1],G^{[p]}(\Rset^{d}))$,
 $$\lim_{n\rightarrow\infty}\sup_{t\in [0,1]}\dcc(\XX^n_t,\XX_t)=0 $$ implies $$\lim_{n\rightarrow\infty}\sup_{t\in[0,1]}\dcc(F(t,\XX^n),F(t,\XX))=0,$$ 







\end{remark}









\subsection{The case \texorpdfstring{$p\in [2,3)$}{p in [2,3)}}\label{sec: into formula p23}
We present the functional \Ito-formula for maps of \cadlag $p$-rough paths, for $p\in [2,3)$. 









   \begin{theorem}\label{3th: Ito formula p 23}
     Let $p\in[2,3)$ and $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^3$-non-anticipative Marcus canonical  path functional such that $F,\nabla F, \nabla^2 F$, and $   R^{\nabla F,\nabla^2F}$ are $[p,3)$\text{-}var continuous. Then, for every Marcus-like $\widehat \XX\in \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1})) $, it holds that $ \big( \nabla F(\cdot ,\wXX), \nabla^{2}F(\cdot ,\wXX)\big)\in \mathcal{V}^{p',r}_{\wXX}$, for all $p'>p$ such that $\frac{1}{p'}+\frac{2}{p}>1$ and $r\geq 1$ given by $ \frac{1}{r}=\frac{1}{p}+\frac{1}{p'},$  and for all
$t\in [0,1]$, 
    \begin{align}\label{3eq: ito formula p 23}
        F(t, \wXX)-&F(0, \widehat \XX)=\int_0^t \nabla F(s^-, \widehat \XX)d\widehat \XX_s\\
       & +\sum_{0<s\leq t}F(s,\wXX)-F(s^-,\wXX)-\nabla F(s^-,\wXX) \Delta \widehat{X}_s-\nabla ^{2}F(s^-,\wXX) \Delta \wX^{(2)}_s.\nonumber 
    \end{align}
    The integral in~\eqref{3eq: ito formula p 23} is  a rough integral and the summation term is well defined as an absolutely summable series.
\end{theorem}
The proof of Theorem~\ref{3th: Ito formula p 23} will make use of the following lemma, where algebraic properties of the signature of piecewise linear paths are exploited to infer some key analytical properties. Its proof is given in Appendix \ref{proof lemma ito p23}.






\begin{lemma}\label{3lemma: ito formula uniformly bounded p 23}
    Let $p\in[2,3)$, $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be such that $F\in  \mathcal{M}^3_{2}$ and $\widehat \XX\in  \widehat C^{1}([0,1],G^2(\Rset^{d+1}))$ be the truncated signature at level $2$ of a time-extended piecewise linear path. Assume that there exists $(\u_n)_{n\in\Nset}\subset T(\Rset^{d+1})$ such that 
\begin{align}\label{3eq: approx F and derivatives p 23}
     \lim_{n\rightarrow\infty} \sup_{t\in [0,1]}\sum_{j=0}^3\|\nabla ^jF^{\u_n}(t,\widehat \XX)-\nabla ^jF(t,\widehat \XX)\|=0.
\end{align}
Then, 
\begin{enumerate}
    \item \label{3item lemma 2 i} $\sup_{n\in \Nset}\bigg(\| \nabla ^2F^{\u_n}(\cdot,\widehat \XX)\|_{1\text{-}var}+\|R^{\u_n^{(1)},\u_n^{(2)}}((\cdot,\cdot),\wXX)\|_{\frac{1}{2}\text{-}var}\bigg)<\infty$;
    \item \label{3item lemma 2 ii} for all $p'>1$, $r>\frac{1}{2}$, 
   \begin{align*}
       &\lim_{n\rightarrow\infty} d_{p'}\big(\nabla ^2F^{\u_n}(\cdot,\widehat \XX),\nabla^{2}F(\cdot,\wXX )\big)=0, \\
       &\lim_{n\rightarrow\infty}d_{r}\big(R^{\u_n^{(1)},\u_n^{(2)}}((\cdot,\cdot),\wXX),R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX)\big)=0.
   \end{align*}
\end{enumerate}
    \end{lemma}





\begin{proof}[Proof of Theorem~\ref{3th: Ito formula p 23}]The structure of the proof is very similar to the one of Theorem~\ref{3th: Ito formula p 12}. Therefore, we emphasize only the main differences.

\paragraph{Step 1:}  Let $\widehat \XX\in  \widehat C^{1}([0,1],G^2(\Rset^{d+1}))$ be the truncated signature at level $2$ of a time-extended piecewise linear path. Since $F$ is a $C^3$, by  Theorem~\ref{3th: Nachbin for path functionals}, there exists a sequence $(\u_n)_{n\in\Nset}\subset T(\Rset^{d+1})$ such that the convergence in equation \eqref{3eq: approx F and derivatives p 23} holds true.
By Lemma~\ref{3lemma: ito formula uniformly bounded p 23}~\ref{3item lemma 2 i} and Lemma 5.12 in~\cite{FV:10},
\begin{align}\label{3eq: ito F^2 and R good control}
     \|\nabla^{2}F(\cdot ,\wXX)\|_{1\text{-}var}+\|R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX)\|_{\frac{1}{2}\text{-}var}<\infty,
\end{align}
implying that $ \big( \nabla F(\cdot ,\wXX), \nabla^{2}F(\cdot ,\wXX)\big)\in \mathcal{V}^{p',r}_{\wXX}$, for all $p'>p$ such that $\frac{1}{p'}+\frac{2}{p}>1$. 

Fix such a $p'$ and notice that $r>\frac{p}{2}>\frac{1}{2}$. By Lemma~\ref{3lemma: ito formula uniformly bounded p 23}~\ref{3item lemma 2 ii},
 \begin{align*}
       \lim_{n\rightarrow\infty} d_{p'}\big(\nabla^{2}F(\cdot,\wXX ),\nabla ^2F^{\u_n}(\cdot,\widehat \XX)\big)=0, \qquad 
       \lim_{n\rightarrow\infty}d_{r}\big(R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX),R^{\u_n^{(1)},\u_n^{(2)}}((\cdot,\cdot),\wXX)\big)=0. \nonumber
   \end{align*}
Moreover, an application of Theorem 8.10 in~\cite{FV:10} and  Proposition 2.7 in~\cite{ALP:23} yields that for all $n\in \Nset$, 
\begin{align*}
    d_p\bigg(\int_0^\cdot &\langle \u^{(1)}_n,\wX_{s}\rangle d\wXX_{s}, \int_0^\cdot \nabla F(s,\wXX) d\wXX_{s}\bigg) \\
    \leq & C\bigg(\dcc\big(\langle \u_n^{(1)},\wX_0\rangle,\nabla F(0,\wXX)\big)+\dcc\big(\langle \u_n^{(2)},\wX_0\rangle,\nabla^2 F(0,\wXX)\big)\bigg.  \nonumber \\
    &  \ \bigg. \quad +d_{p'}\big(\langle \u_n^{(2)},\wX\rangle,\nabla^{2}F(\cdot ,\wXX)\big)+d_{r}\big(R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX),R^{\u_n^{(1)},\u_n^{(2)}}((\cdot,\cdot),\wXX)\big)\bigg)\nonumber
\end{align*}
for some $C>0$.
Since by equation~\eqref{eq: u,signature p23} for every $n\in \Nset$ and $t\in [0,1]$, it holds that $\langle \u_n,\widehat{\mathbb{X}}_{t}\rangle = \langle \u_n,\widehat{\mathbb{X}}_{0}\rangle+  \int_0^t \langle \u^{(1)}_n,\widehat{\mathbb{X}}_{s}\rangle  d\widehat{\XX}_{s},$ and the claim follows.

\paragraph{Step 2:} Fix $\widehat \XX \in  \widehat C^{p}([0,1],G^{2}(\Rset^{d+1})) $. By Theorem 8.12 in~\cite{FV:10}, there exists a sequence  of piecewise linear time-extended paths such that their truncated signature at level $2$, denoted by $(\widehat \XX^M)_M$, satisfy
    \begin{align}\label{3approximation w.g.p 23}
        \lim_{M\rightarrow\infty }\sup_{t\in [0,1]}\dcc(\widehat \XX^M_t,\wXX_t)=0, \qquad \text{and}\qquad    \sup_{M\in \Nset}\|\widehat \XX^M\|_{p\text{-}var}\leq C\|\widehat \XX\|_{p\text{-}var},
    \end{align}
    for some $C>0$. By Step 1, for every fixed $M$ and $t\in [0,1]$, 
        \begin{align*}
        F(t, \widehat \XX^M)-F(0, \widehat \XX^M)=\int_0^t \nabla F(s, \widehat \XX^M)d\widehat \XX^M_s.
    \end{align*}

 By conditions~\eqref{3approximation w.g.p 23} and interpolation (see Lemma 5.12 and Lemma 8.16 in~\cite{FV:10}), for all $q>p$, $  \lim_{M\rightarrow\infty }d_{q}(\widehat \XX^M, \widehat \XX)=0.$ Fix $p'$ and $r$ as in Step 1 and notice that since for all $M$, $ \big(  \nabla  F(\cdot,\widehat \XX^M), \nabla ^{2} F(\cdot,\widehat \XX^M)\big)\in \mathcal{V}^{p',r}_{\wXX},$ and $\nabla F, \nabla^2 F$ and $R^{\nabla F,\nabla ^2F}$ are by assumption $[p,3)$\text{-}var continuous, $ \big(  \nabla  F(\cdot,\widehat \XX), \nabla ^{2} F(\cdot,\widehat \XX)\big)\in \mathcal{V}^{p',r}_{\wXX}$ too.




Next, fix $p''>p'>p $ such that $\frac{2}{p'}+\frac{1}{p''}>1$. Observe that for all $M\in \Nset$, $\wXX^M,\wXX\in \widehat{D}^{p'}([0,1], G^2(\Rset^{d+1}))$ and by~\eqref{3eq: ito F^2 and R good control},  $ \big(  \nabla  F(\cdot,\widehat \XX^M), \nabla ^{2} F(\cdot,\widehat \XX^M)\big)\in \mathcal{V}^{p'',r}_{\wXX^M}$. Therefore, since  $\nabla F, \nabla^2 F$ and $R^{\nabla F,\nabla ^2F}$ are $[p,3)$\text{-}var continuous,  $ \big(  \nabla  F(\cdot,\widehat \XX), \nabla ^{2} F(\cdot,\widehat \XX)\big)\in \mathcal{V}^{p'',r}_{\wXX}.$ 
 Finally, applying Theorem 8.10 of ~\cite{FV:10} and Proposition 2.7 of ~\cite{ALP:23} yields that there exists a constant $C>0$, such that for all $M\in \Nset$,
 \begin{align}\label{3eq: proof  step 2 ito p23 }
    d_{p'}\bigg(\int_0^\cdot & \nabla F(s,\wXX^M) d\wXX^M_{s}, \int_0^\cdot \nabla F(s,\wXX) d\wXX_{s}\bigg) \\
    \leq & C\bigg(d_{p'}\big(\wXX^M,\wXX \big)+\dcc\big(\nabla F(0,\wXX^M),\nabla F(0,\wXX)\big)+\dcc\big(\nabla^2 F(0,\wXX^M),\nabla^2 F(0,\wXX)\big)\bigg.  \nonumber \\
    &  \ \bigg. \quad +d_{p''}\big(\nabla^{2}F(\cdot ,\wXX^M),\nabla^{2}F(\cdot ,\wXX)\big)+d_{r}\big(R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX^M),R^{\nabla F,\nabla^2 F}((\cdot,\cdot),\wXX)\big)\bigg).\nonumber
\end{align}
Since $F$ is $[p,3)$ var continuous, the claim follows.
\paragraph{Step 3:} 

Fix $\wXX\in \widehat{D}^p([0,1],G^1(\Rset^{d+1}))$, with $\wXX$ Marcus-like and set $\widehat{X}:=\pi_1(\wXX)$. For notational convenience, let us denote by $\ZZ\in \widehat{C}^p([0,1],G^{2}(\Rset^{d+1}))$ the time-extended Marcus-transformed path of $\wXX$ and  let $\mu_t\in [0,1]$ be such that $\ZZ_{\mu_t}=\wXX_{t}$ for all $t\in [0,1]$ (see Notation~\ref{3notation: mut}). It holds that $ \big( \nabla F(\cdot ,\wXX), \nabla^{2}F(\cdot ,\wXX)\big)\in \mathcal{V}^{p',r}_{\wXX}$.
Next, assume first that $\wXX$ admits only one jump at time $a\in (0,1]$. If $t<a$, the claim follows as in the Young case. If $t\geq a$, it suffices to notice that  for level $2$ rough integration, 
          \begin{align*}
        &F(\mu_{a^-},  \ZZ)-F(0,  \ZZ)=\int_{0}^{a} \nabla^{} F(s^-,   \wXX)d  \wXX_{s}-\nabla F(a^-,\wXX) \Delta \widehat{X}_a-\nabla ^{2}F(s^-,\wXX) \Delta \wX^{(2)}_a.
   \end{align*}
        The argument extends trivially to \cadlag paths with finitely many jumps. Finally, for $\wXX$ a \cadlag path with countable many jumps, since $\wXX$ has finite $p$-variation, for $p\in [2,3)$, there exists a finite set $B(\varepsilon,t)\subset[0,t]$ of jump times of  $\wXX$ such that $ \sum_{s\leq t, \ s \notin B(\varepsilon,t)} \|\Delta \widehat{X}_s
        \|^3<\frac{\varepsilon}{2},$ for $\varepsilon>0$. This very last step of the proof follows from Proposition 2.6 in~\cite{FZ:17}.






\end{proof}
\begin{remark}\phantomsection\label{3rem: Ito formula p23}
\begin{enumerate}
    \item \label{3rem: Ito formula p23 item i} An inspection of the above proof shows that we can replace the hypothesis of $F$, $\nabla F$ being $[p,3)$-var continuous with the assumption that for every sequence $(\XX^n, \XX)_{n\in\Nset}\subset C^p([0,1],G^{[p]}(\Rset^{d}))$,
 $$\lim_{n\rightarrow\infty}\sup_{t\in [0,1]}\dcc(\XX^n_t,\XX_t)=0 $$ implies $$\lim_{n\rightarrow\infty}\sup_{t\in[0,1]}\dcc(F(t,\XX^n),F(t,\XX))=0 ,\qquad \lim_{n\rightarrow\infty}\sup_{t\in[0,1]}\dcc(\nabla F(t,\XX^n),\nabla F(t,\XX))=0.$$ 
 \item \label{3rem: Ito formula p23 item ii} Instead of assuming $R^{\nabla^1F,\nabla^2 F}$ to be $[p,3)$-var continuous, one can also suppose that $F,\nabla F, \nabla^2 F$, and $ \nabla^3F$ are $[p,3)$\text{-}var continuous. Indeed,  for every (signature at level $2$ of) a piecewise linear time-extended path $\wXX^M$ as in Step 2, by Therem~\ref{3th: Nachbin for path functionals} and equation~\eqref{eq: reminder linear}, we get
 \begin{align*}
     \|R^{\nabla^1F,\nabla^2 F}((s,t),\wXX^M)\|&=\|\nabla^1F(t,\wXX^M)-\nabla^1F(s,\wXX^M)-\nabla^2F(s,\wXX^M)\widehat{X}^M_{s,t}\|\\
     &\leq C \sup_{s\in [0,1]}\|\nabla^3F(u,\wXX^M)\|\|\widehat{X}^M_{s,t}\|^2,
 \end{align*}
 for $\widehat{X}_{s,t}:=\pi_1(\wXX_{s,t})$, $(s,t)\in \Delta_1$ and $C>0.$ Therefore, if $\nabla^3F$ is $[p,3)$-var continuous, the sequence $ \|R^{\nabla^1F,\nabla^2 F}((\cdot,\cdot),\wXX^M)\|$ is uniformly bounded in $p/2$-variation. By interpolation  for all $p'>p$,
 \begin{align*}
     \lim_{M\rightarrow\infty }d_{\frac{p'}{2}}\big(R^{\nabla F,\nabla ^2F}((\cdot,\cdot),\wXX^M),R^{\nabla F,\nabla ^2F}((\cdot,\cdot),\wXX)\big)=0.
 \end{align*}

\item We highlight that the consideration of tracking-jumps-extended paths is necessary not only for deriving the approximation result in Theorem~\ref{3th: Nachbin for path functionals}, but also for expressing the dependence on a non-anticipative path functional on the parameter $t$. Consider, for instance, a path functional 
 $F$ such that for all $(t,\XX)\in [0,1]\times {D}^p([0,1],G^{2}(\Rset^{d+1}))$,
\begin{align*}
    F(t,\XX)=\sin(\langle \e_0,\XX_t\rangle).
\end{align*}
Then, for a tracking-jumps-extended path $\wXX$, $ F(t,\wXX)=\sin(Z(t))$, computing the vertical derivative as described in \eqref{eq: vertical derivativ} and \eqref{3eq: value vertical derivatives higher order}, we get 
$U^0F(t,\wXX)=\cos(Z(t))$, $U^0U^0F(t,\wXX)=-\sin(Z(t))$, and all the other (first and second order) vertical derivatives are equal to $0$. Since the hypothesis of Theorem~\ref{3th: Ito formula p 23} are satisfied, we get that
\begin{align*}
    \sin(Z_t)-\sin(Z_0)=\int_0^t\cos(Z_{s^-})dZ_s
     +\sum_{0<s\leq t} \sin (Z_{s})-\sin(Z_{s^-})-\cos(Z_{s^-})\Delta Z_s,
\end{align*}
which coincides with the change of variable formula for paths of finite variation. In particular, if $\wXX$ is continuous, the path functional explicitly reads as $F(t,\XX)=\sin(t)$, and the consideration of time-extended paths is necessary in order to embed the functional $F$ in the present framework.


    \item Theorems~\ref{3th: Ito formula p 12} and~\ref{3th: Ito formula p 23} provide an \Ito-formula for $C^2$ and $C^3$ non-anticipative Marcus canonical  path functional, respectively (see Definition~\ref{3def: C^K path functionals}). Therefore, our framework includes all the path functionals for which for all $i=0,\dots,2$ (or $i=0,\dots,3$) the maps $ [0,1]\ni t\mapsto \nabla^{i}F(t,\wXX)$ (or equivalently the map $t\mapsto \tilde{F}(\wXX^t)$ introduced in Remark \ref{remark F tilde F}\ref{remark F tilde F ii}) are continuous if $\wXX\in \widehat{C}^p([0,1],G^{[p]}(\Rset^{d+1}))$, and \cadlag if $\wXX\in \widehat{D}^p([0,1],G^{[p]}(\Rset^{d+1}))$ (see Definition~\ref{3def: C^K path functionals}). This in particular implies that functionals of the form $F(t,\XX):=\XX_{s\wedge t}$, for some fixed $s\in (0,1]$ are not included in our setup. A similar argument applies to the functional $F(t,\XX):=\XX_{t^-}$, as the map $[0,1]\ni t\mapsto F(t,\XX)$ is \caglad for $\XX$ \cadlag.  Notice furthermore that such functionals are not Marcus canonical  as condition \ref{item def Mcpf i} in Definition \ref{3def: Marcus canonical path functional} is not satisfied. Similarly, condition  \ref{item def Mcpf i} is satisfied for neither the functionals
    $F(t,\XX):= \XX^2_{\XX^1_t}1_{\{\XX^1_t\in[0,1]\}} $ nor   the delayed functional, $F(t,\XX):=\XX_{t-\delta}$, for some $\delta>0$. This is also the case in the setting of ~\cite{CRF:13} (see  Example 6 therein), however for different reasons.





\item\label{remark reduced} If in particular for each $\XX\in  D^p([0,1],G^2(\Rset^{d+1}))$, the functional $F$ and its derivatives depend only on $\pi_1(\XX)$, and the second order vertical derivative $\nabla ^2F(\cdot,\XX)$ is a path with values in the subspace of symmetric matrices, a rough functional \Ito-formula can be derived by neglecting the information provided by the area of $\XX$, i.e. $\text{Anti}(\X^{(2)})$, and considering instead a rough integral with respect to the \textit{canonical reduced rough path} (see Definition 5.3 in \cite{FH:14})
\begin{align}\label{eq: reduced rp canonical}
    \XX^{\mathcal{R}}:=(X,\mathbb{S}^X)
\end{align}
where $X:=\pi_1(\XX)$ and $\mathbb{S}^X:\Delta_1\rightarrow\text{Sym}((\Rset^{d+1})^{\otimes 2})$ is given by $\mathbb{S}^X_{s,t}:=\frac{1}{2}X_{s,t}^{\otimes 2}$ for each $(s,t)\in \Delta_1$. The proof technique is the same as the one in Theorem \ref{3th: Ito formula p 23}. Moreover, in this specific case, the \Ito-formula can be deduced by considering the  variation topology on the space $C^p([0,1],\Rset^d)$ instead of the one on $C^p([0,1],G^2(\Rset^d))$ as described in Definition \ref{3def: var continuous funcitonals}.





\item Following \cite{P:24}, an \Ito-formula for non-anticipative functionals of paths with values in $\Rset^d$ is derived subsequently  in \cite{B:24} using rough integrals with respect to \textit{continuous reduced rough paths} of $\Rset^d$-valued paths of arbitrary regularity. This alternative approach adopts the notion of functional vertical derivatives proposed in \cite{D:09}, and consequently the higher-order functional vertical derivatives always take value  in the space of symmetric tensors,  as highlighted in Remark \ref{rem: non commutativity derivate}. The corresponding   rough integrals are  such functionals with respect to the canonical reduced rough paths derived from the powers of the increments of $\pi_1(\XX)$. We remark that due to the symmetry of the vertical derivatives within this framework, a Taylor expansion based on the signature of non-anticipative path functionals cannot be derived (see also Remark \ref{remark: taylor p23}\ref{rem: valentin dupire}).


















\end{enumerate}


\end{remark}



\subsection{Connections to the literature}\label{sec: connections litarature}

\paragraph{The \Ito-formula for rough paths.}  We will see that the functional \Ito-formula in Theorem~\ref{3th: Ito formula p 23} matches the existing  \Ito-formulas for rough paths in the literature. Throughout, we fix $p\in [2,3)$.
\begin{itemize}
    \item Let $f\in C^3(\Rset^{d+1})$ and consider the path functional given by
    \begin{align*}
        [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))\ni (t,\wXX)\mapsto F(t,\wXX):=f(\widehat{X}_t),
    \end{align*}
    where we set $\widehat{X}:=\pi_1(\wXX)$.
    Observe that $F$ is a $C^3$-non-anticipative Marcus canonical  path functional such that for all $i=1,2,3$, $(t,\wXX)\in  [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))$,
    \begin{align*}
        \nabla^i F(t,\wXX)=\nabla^i f(\widehat{X}_t),
    \end{align*}
where  $\nabla^i f$ denotes the $(\Rset^{d+1})^{\otimes i}$-valued maps given by the $i$-th (standard) partial derivatives of the map $f$. Moreover, from  properties of regular functions on $\Rset^{d+1}$, $F,\nabla F, \nabla^2 F$, and $   R^{\nabla F,\nabla^2F}$ are 
$[p,3)$\text{-}var continuous. Therefore, applying Theorem \ref{3th: Ito formula p 23}
yields that for all $ (t,\wXX)$ with $\wXX$-Marcus-like, 
\begin{align}\label{3eq: ito formula f non path dependent}
        f(\widehat{X}_t)-&f(\widehat{X}_0)=\int_0^t \nabla f(\widehat{X}_{s^-})d \wXX_s\\
       & +\sum_{0<s\leq t}f(\widehat{X}_s)-f(\widehat{X}_{s^-})-\nabla f(\widehat{X}_{s^-}) \Delta \widehat{X}_s-\nabla ^{2}f(\widehat{X}_{s^-}) \frac{1}{2}\Delta \widehat{X}_s^{\otimes2 }.\nonumber 
    \end{align}
      Notice that the considerations in Remark \ref{3rem: Ito formula p23}\ref{remark reduced} apply here. 
    The formula in equation~\eqref{3eq: ito formula f non path dependent} has been derived in Theorem 2.12 of ~\cite{FZ:17} by  
    exploiting the Taylor expansion of the regular function $f$ on $\Rset^{d+1}$, a completely different techniques from the one used in Theorem~\ref{3th: Ito formula p 23}.


    \item Let $f\in C^3(\Rset)$ and consider the path functional given by
    \begin{align}\label{eq: f compones sig}
        [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))\ni (t,\wXX)\mapsto F(t,\wXX):=f(\langle \u,\wX_t\rangle),
        \end{align}
        for some $\u\in T(\Rset^{d+1})$. 
        Applying the rules of derivation for compound functions yields that $F$ is a $C^3$-non-anticipative Marcus canonical  path functional such that 
    \begin{align*}
        &\nabla F(t,\wXX)=f'(\langle \u,\wX_t\rangle )\langle \u^{(1)},\wX_t\rangle,\\
           &\nabla^2 F(t,\wXX)=f''(\langle \u,\wX_t\rangle )\langle \u^{(1)},\wX_t\rangle
           \langle \u^{(1)},\wX_t\rangle^\top+f'(\langle \u,\wX_t\rangle )\langle \u^{(2)},\wX_t\rangle ,\\
            &\nabla^3 F(t,\wXX)=f'''(\langle \u,\wX_t\rangle )\langle \u^{(1)},\wX_t\rangle\langle \u^{(1)},\wX_t\rangle^\top \langle \u^{(1)},\wX_t\rangle^\top\\
            &\qquad \qquad \qquad +3f''(\langle \u,\wX_t\rangle )\langle \u^{(2)},\wX_t\rangle\langle \u^{(1)},\wX_t\rangle^\top 
             +f'(\langle \u,\wX_t\rangle )\langle \u^{(3)},\wX_t\rangle,
    \end{align*}
    for all $(t,\wXX)\in  [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))$, with $f',f'',f'''$ denoting the first, the second, and the third derivatives of $f$, respectively.  A further application of the properties of regular functions on $\Rset$ yields that $F,\nabla F, \nabla^2 F$ and $   R^{\nabla F,\nabla^2F}$ are $[p,3)$\text{-}var continuous. Therefore the assertion of Theorem~\ref{3th: Ito formula p 23} holds for all $ (t,\wXX)\in [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))$, with $\wXX$-Marcus-like.   In particular, if  $\wXX\in (t,\wXX)\in [0,1]\times \widehat{C}^{p}([0,1],G^{2}(\Rset^{d+1}))$, the functional \Ito-formula in equation~\eqref{3eq: ito formula p 23} coincides with the \Ito-formula for controlled rough paths stated in Theorem 7.7 of ~\cite{FH:14}. 
Observe that the above reasoning can be easily generalized to path functionals of the form 
    \begin{align*}
         [0,1]\times \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1}))\ni (t,\wXX)\mapsto F(t,\wXX):=g(\langle \u_1,\wX_t\rangle,\dots,\langle \u_m,\wX_t\rangle),
    \end{align*}
 for some $g\in C^3(\Rset^m)$,  $\u_1,\dots\u_m\in T(\Rset^{d+1})$. 
    \end{itemize}


\paragraph{Föllmer, (RIE) and stochastic integration theories.} We elaborate on the connections of the results in Section~\ref{3sec: functional Ito formula} with Föllmer (\cite{F:81}), (RIE) (~\cite{PP:16},~\cite{ALP:23}), and stochastic integration (\cite{JS:87}) theories, whose main concepts have been summarized in Appendix~\ref{3appendix: integration theories}. The proof of the following corollary is given in Appendix \ref{proof 3coro: ito formula follmer}.
\begin{corollary}[Föllmer]\label{3coro: ito formula follmer}
     Let $p\in[2,3)$, $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^3$-non anticipative Marcus canonical  path functional such that $F,\nabla F, \nabla^2 F$ and $   R^{\nabla F,\nabla^2F}$ are $[p,3)$\text{-}var continuous, and  $(\pi^n_{[0,1]})_{n\in\Nset}$ a sequence of partitions with vanishing mesh size. Let $\widehat{X}\in \widehat{D}^p([0,1],\Rset^{d+1})$ be a path with finite quadratic variation in the sense of Föllmer along  $(\pi^n_{[0,1]})_{n\in\Nset}$,  $[\widehat X,\widehat X]^c$ its continuous quadratic variation, and  $\widehat \XX\in \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1})) $ a Marcus-like weakly geometric rough path such that $\pi_1(\wXX)=\widehat{X}$.
     Assume that for all $t\in [0,1]$, 
     $\nabla^2 F(t,\wXX)=\text{Sym}(\nabla^2 F(t,\wXX))$.
     Then, the following limit exists,
     \begin{align}\label{3eq: coro follmer limit integral}
        \int_0^t\nabla F(s^-,\wXX)d\widehat{X}_s:=\lim_{n\rightarrow\infty }\sum_{s^n_i\in \pi^n_{[0,1]}}\nabla F(s^n_i,\wXX) \widehat{X}_{s^n_i,s^n_{i+1}},
    \end{align} 
and
    \begin{align}\label{3eq: ito formula follmer}
        F(t, \wXX)-F(0, \widehat \XX)=&\int_0^t\nabla F(s^-,\wXX)d\widehat{X}_s+\frac{1}{2}\int_0^t\nabla^2F(s^-,\wXX)d[\widehat{X},\widehat{X}]^c_s\\
       & +\sum_{0<s\leq t}F(s,\wXX)-F(s^-,\wXX)-\nabla F(s^-,\wXX) \Delta \widehat{X}_s.\nonumber 
    \end{align}
     The integral in~\eqref{3eq: ito formula follmer} with respect to the path $[\widehat{X},\widehat{X}]^c$ is understood as a Young integral, and the summation term is well defined as an absolutely summable series.
\end{corollary}







Next,  consider the special case of \cadlag rough paths over some $\widehat{X}\in \widehat{D}([0,1],\Rset^{d+1})$ which satisfies (RIE) with respect to some $p\in (2,3)$ and some sequence of nested partitions $(\pi^n_{[0,1]})_{n\in\Nset}$ (Property~\ref{3property RIE}). Recall from Proposition~\ref{3prop: RIE integal properties} that any path that satisfies (RIE) along a sequence of partition also has quadratic variation in the sense of Föllmer along the same partition. 
The proof of the next corollary is given in Appendix \ref{proof 3coro: ito RIE}.  Furthermore, we refer to Remark \ref{rem: ito=dupire}\ref{rem: ito=dupire i} for a comparison on its conditions with those in Corollary \ref{3coro: ito formula follmer}.
\begin{corollary}[(RIE) property]\label{3coro: ito RIE }

     Let $p\in(2,3)$ and $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^3$-non-anticipative Marcus canonical  path functional such that $F,\nabla F, \nabla^2 F$, and $   R^{\nabla F,\nabla^2F}$ are $[p,3)$\text{-}var continuous, and  $(\pi^n_{[0,1]})_{n\in\Nset}$ be a sequence of nested partitions with vanishing mesh size. Let $\widehat{X}\in \widehat{D}([0,1],\Rset^{d+1})$ be a tracking-jumps-extended path which satisfies (RIE) with respect to $p$ and $(\pi^n_{[0,1]})_{n\in\Nset}$,  $[\widehat X,\widehat X]^c$ be its continuous quadratic variation, and $\widehat \XX\in \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1})) $ the rough path specified in Proposition \ref{3prop: RIE integal properties}\ref{i RIE} such that $\pi_1(\wXX)=\widehat{X}$. Then, for all $t\in [0,1]$,
    \begin{align}\label{3eq: ito formula RIE}
        F(t, \wXX)-F(0, \widehat \XX)=&\int_0^t\nabla F(s^-,\wXX)d\widehat{X}_s+\frac{1}{2}\int_0^t\nabla^2F(s^-,\wXX)d[\widehat{X},\widehat{X}]^c_s\\
       & +\sum_{0<s\leq t}F(s,\wXX)-F(s^-,\wXX)-\nabla F(s^-,\wXX) \Delta \widehat{X}_s.\nonumber 
    \end{align}
    The first integral of~\eqref{3eq: ito formula RIE} is interpreted as in~\eqref{3eq: coro follmer limit integral}, the second is a Young integral with respect to $[X,X]^c$, and the summation term is well defined as an absolutely summable series.
\end{corollary}




Now, let us  analyze path functionals evaluated at some random rough paths. More precisely,  consider the  Marcus lift of some \cadlag semimartingale,  given by $ \mathbf{X}_t:=(1,X_{t}-X_0,\mathbb{X}^{(2)}_{0,t}),$
for all $t\in[0,1]$, where,
\[
	\mathbb{X}^{(2)}_{0,t}:=\int_0^t X_{0,s^-}\otimes dX_s+\frac{1}{2}[X,X]^c_{t}+\frac{1}{2}\sum_{0< s \leq t}\Delta X_s\otimes\Delta X_s. 
	\]
    Here the integral is an \Ito-integral and $[X,X]^c$ denotes the continuous quadratic variation of $X$ (Proposition 16 in \cite{FS:17}). The proof of the following corollary follows directly from  Theorem~\ref{3th: Ito formula p 23}, Lemma 4.35 in~\cite{CF:19}.



\begin{corollary}[Semimartingales (stochastic)]\label{3coro: ito sotchastic}
 For $p\in(2,3)$, consider  a $C^3$-non-anticipative Marcus canonical  path functional  $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ such that $F,\nabla F, \nabla^2 F$, and $   R^{\nabla F,\nabla^2F}$ are $[p,3)$\text{-}var continuous. Let $\wXX$  denote the Marcus lift a tracking-jumps-extended \cadlag semimartingale $\widehat{X}$.  Assume that the processes $\nabla F(\cdot,\wXX):=(\nabla F(t,\wXX))_{t\in [0,1]},\nabla^2 F(\cdot,\wXX):=(\nabla^2 F(\cdot,\wXX))_{t\in [0,1]}$ are locally bounded and predictable. Then, for all $t\in [0,1]$, a.s. 
     \begin{align}\label{3eq: ito formula stochastic}
        F(t,\wXX)-F(0,\wXX)=&\int_0^t\nabla F(s^{-},\wXX)d\widehat{X}_s+ \frac{1}{2}\int_0^t\nabla^{2}F(s^-,\wXX)d[\widehat{X},\widehat{X}]^c_s\\
        & +\sum_{0<s\leq t}F(s,\wXX)-F(s^{-},\wXX)-\nabla F(s^-,\wXX)\Delta \widehat{X}_s.\nonumber  \end{align}
 The first integral   of~\eqref{3eq: ito formula stochastic} is an \Ito-integral, the second  is a Young integral with respect to $[\widehat{X},\widehat{X}]^c$, and  the summation term is well defined as an a.s. absolutely summable series.
        \end{corollary}
     We conclude this section with some remarks on the above corollaries.

\begin{remark}\phantomsection\label{rem: ito=dupire}

\begin{enumerate}


\item \label{rem: ito=dupire i} The \Ito-formula~\eqref{3eq: ito formula RIE} coincides with the formula derived in Corollary~\ref{3coro: ito formula follmer}. Observe that the former has been deduced under weaker assumptions on $\nabla^2 F$, but stronger ones on the path $\widehat{X}$. Specifically, in Corollary~\ref{3coro: ito formula follmer}, we assumed that for all $t\in [0,1]$, 
     $\nabla^2 F(t,\wXX)=\text{Sym}(\nabla^2 F(t,\wXX))$ to ensure the convergence of the limit in~\eqref{3eq: coro follmer limit integral}. In contrast, the latter convergence is achieved without any assumptions on the antisymmetric part of 
  $\nabla^2F$ when $\widehat{X}$ satisfies property (RIE). Property (RIE) is indeed a stronger requirement for a path than having finite quadratic variation in the sense of Föllmer (see Proposition~\ref{3prop: RIE integal properties}).






\item \label{item rem: ito=dupire i}



 The formula in~\eqref{3eq: ito formula stochastic} and the one derived in Theorem 31 of \cite{D:09} coincide within their common domain of validity, provided that $\nabla F$ and $\nabla ^2F$, as computed in our framework with respect to the direction $i=1,\dots,d$  and evaluated at continuous paths, are equal with their functional derivative representations. A necessary condition for this to be satisfied is that $F(\cdot,\wXX)=F(\cdot,\pi_1(\wXX))$ for all $\wXX$. Notice that in such a case, for all $t\in [0,1]$,
\begin{align}\label{eq: vertical time=horizontal}
    U^0F(t,\pi_1(\wXX))=\mathcal{D}F(t,\pi_1(\XX)),
\end{align}
where  the LHS is the vertical derivative of $F$ at $(t,\wXX)$ with respect to the time component of $\wXX$ as computed in \eqref{eq: vertical derivativ}, and   the RHS is the so-called \textit{horizontal derivatives} of $F$ at $(t,\pi_1(\XX))$ considered in \cite{D:09} and defined via
\begin{align}\label{eq: horizontal derivative}
        \mathcal{D}F(t,\pi_1(\XX)):=\lim_{h\searrow0}F(t+h,\pi_1(\XX)^t),
    \end{align}
    whenever the limit exists. Equality \eqref{eq: vertical time=horizontal} can be proved by matching the two formulas and noticing that by the consistency between Young and level 2 rough integration (see Section \ref{sec: rough=young}), for all $t\in [0,1]$,
    \begin{align*}
        \int_0^t U^0F(s,\pi_1(\wXX))ds=\int_0^t \mathcal{D}F(s,\pi_1(\XX))ds.
    \end{align*}


    Notice that $\mathcal{D}F$ is a functional of the \textit{non-time extended} path $\XX$ given by removing the time component of $\wXX$ (see Remark \ref{rem: extended paths}\ref{item 4 remark extended path}). Indeed, a key difference between the two approaches is  that  the current framework captures the dependence on the time of the functionals   by time-extending the path $\XX$ and considering functionals 
 of time-extended paths (see e.g., Remark \ref{remark: non marucs like}\ref{remark: non marucs like ii}). In \cite{D:09}  this dependence is instead expressed  via the horizontal derivative. Moreover, by conditions \ref{item def Mcpf i},\ref{item def Mcpf ii} in Definition \ref{3def: Marcus canonical path functional}, for every non-anticipative Marcus canonical  path functional $F$ and time-extended continuous path $\wXX$, the horizontal derivative \eqref{eq: horizontal derivative} is always  $0$. Indeed, for every $\varepsilon>0$ such that $ 1-\varepsilon\geq t$,    
 \begin{align*}
     F(t+\varepsilon,\wXX^t)=& F(t+\varepsilon,(\wXX^t)^{t+\varepsilon})\\=&F(t+\varepsilon,(\wXX^t)^{t+\varepsilon, \rhd})\\
     =&F(t+\varepsilon,\wXX^t_\phi)\\=&F(\phi(t+\varepsilon),\wXX^{t}),
 \end{align*}
 for some time-reparametrization $\phi$ such that $\phi([0,t+\varepsilon])=[0,t]$.







 Finally,  the framework in~\cite{D:09} for deriving a functional \Ito-formula requires continuity of both the functionals and their derivatives with respect to the supremum norm.
As pointed out in the introduction, this excludes several important examples of non-anticipative functionals, such as linear functionals of the signature, which are covered in the present framework. 
More generally, the regularity conditions on the functionals and their derivatives expressed with respect to a stronger topology ($p$-variation versus uniform topology) allow here for the consideration of a larger set of regular functionals.













\end{enumerate}

\end{remark}













\section{Functional Taylor expansion}\label{sec: functional taylor} 

Taylor expansion is  fundamental in classical calculus, offering explicit polynomial approximations of smooth functions. This section is to derive a \textit{functional Taylor expansion} of sufficiently regular Marcus canonical path functionals in terms of the signature. The core idea behind its derivation is to iteratively apply the \Ito-formulas  in Theorem \ref{3th: Ito formula p 12} and Theorem \ref{3th: Ito formula p 23}.

\subsection{The case \texorpdfstring{$p\in [1,2)$}{}}





\begin{theorem}\label{th: taylor 12}
   Let $p\in[1,2)$, $K\geq2$  and $F:[0,1]\times D^{p}([0,1],G^{1}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^K$ non-anticipative Marcus canonical  path functional. Assume that   $F,\nabla F, \dots, \nabla ^{K-1}F $ are $[p,2)$\text{-}var continuous. Let $\widehat \XX\in \widehat D^{p}([0,1],G^{1}(\Rset^{d+1})) $, denote by $\wX$ its signature and by $\ZZ$ its time-extended Marcus-transformed path with respect to some pair $(R,\psi_R)$. Then, for all 
$t\in [0,1]$,
   \begin{align}\label{3eq: taylor expansion p12}
    F(t,\widehat \XX)=&\sum_{j=0}^{K-2}\nabla^{j}F (0,\widehat \XX)\widehat \X^{(j)}_{0,t}+ \mathcal{R}^F_{K-1}(t,\widehat \XX),
\end{align}
where, $$\mathcal{R}^F_{K-1}(t,\wXX):=\int_0^{\psi_{R}^{-1}(\tau_{\wXX,R}(t))}\int_0^{t_1}\dots \int_{0}^{t_{K-2}}\nabla^{ K-1} F(t_{K-1}, \ZZ)d \ZZ_{t_{K-1}} \dots  d \ZZ_{t_1}$$  is defined as iterated Young integrals.
\end{theorem}
The proof of the  theorem is given in the Appendix \ref{prof th: taylor 12}.
\begin{remark}
\begin{enumerate}
    \item Notice that for $\wXX$ continuous, the remainder term becomes  
    $$\mathcal{R}^F_{K-1}(t,\wXX):=\int_0^{t}\int_0^{t_1}\dots \int_{0}^{t_{K-2}}\nabla^{ K-1} F(t_{K-1}, \wXX)d \wXX_{t_{K-1}} \dots  d \wXX_{t_1}.$$


    \item 
    Since the proof of Theorems \ref{th: taylor 12} relies on Theorem \ref{3th: Ito formula p 12},  possible modifications of the conditions on the functional $F$ discussed in Remark \ref{3rem: Ito formula p12} also apply here.
    \end{enumerate}
\end{remark}



\subsection{The case \texorpdfstring{$p\in [2,3)$}{}}\label{sec: taylor p23}


\begin{theorem}\label{3th: taylor p23 continuous}
     Let $p\in[2,3)$, $K\geq 3$, and $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^K$ non-anticipative Marcus canonical  path functional. Assume that  
     $F,\nabla ^{}F, \dots, \nabla ^{K-1}F $, and $R^{\nabla^{K-2} F,\nabla^{K-1} F}$ are $[p,3)$\text{-}var continuous. Let $\widehat \XX\in \widehat D^{p}([0,1],G^{2}(\Rset^{d+1})) $, denote by $\wX$ its signature, and by $\ZZ$ its time-extended Marcus-transformed path with respect to some pair $(R,\psi_R)$. Then, for all 
$t\in [0,1]$,  
   \begin{align}\label{3eq: taylor expansion p23}
    F(t,\widehat \XX)=&\sum_{j=0}^{K-3}\nabla^{j}F (0,\widehat \XX)\widehat \X^{(j)}_{0,t}+ \mathcal{R}^F_{K-2}(t,\widehat \XX),
\end{align}
where $$\mathcal{R}^F_{K-2}(t,\wXX):=\int_0^{\psi_R(\tau_{\wXX,R}(t))}\int_0^{t_1}\dots \int_{0}^{t_{K-3}}\nabla^{ K-1} F(t_{K-1}, \ZZ)d \ZZ_{t_{K-1}} \dots  d  \ZZ_{t_1}$$ is defined as iterated rough integral.
\end{theorem}










The proof of the  theorem is given in the Appendix \ref{prof 3th: taylor p23 continuous}.
\begin{remark}\phantomsection\label{remark: taylor p23}
\begin{enumerate}
\item Notice that for $\wXX$ continuous, the remainder term explicitly reads as 
    $$\mathcal{R}^F_{K-1}(t,\wXX):=\int_0^{t}\int_0^{t_1}\dots \int_{0}^{t_{K-2}}\nabla^{ K-1} F(t_{K-1}, \wXX)d \wXX_{t_{K-1}} \dots  d \wXX_{t_1}.$$


Moreover, the iterated rough integrals determining this remainder term are defined as follows. Set $G^{-1}(\cdot,\wXX):=\nabla ^{K-1}F(\cdot,\wXX)$, $G^0(\cdot,\wXX):=\nabla ^{K-2}F(\cdot,\wXX)$, and 
\begin{align}\label{3eq: Gj}
G^j(\cdot,\wXX):=\int_0^\cdot\int_0^{t_{1}}\dots \int_0^{t_{j-1}} \nabla ^{K-2}F(t_{j},\wXX)d\wXX_{t_{j}}\dots d\wXX_{t_{1}},
\end{align}
for $j=1,\dots,K-2$. Then,  $G^j(\cdot,\wXX)$ is the rough integral of $(G^{j-1}(\cdot,\wXX),G^{j-2}(\cdot,\wXX))$ with respect to $\wXX$.
    \item \label{rem: weaken assumptions TF p 23}  Since the proofs of Theorem~\ref{3th: taylor p23 continuous} rely on Theorem~\ref{3th: Ito formula p 23}, discussions in Remark~\ref{3rem: Ito formula p23}\ref{3rem: Ito formula p23 item i} regarding a possible modifications of the conditions on the functional $F$ also apply here.
    \item  \label{rem: valentin dupire}   Adopting and combining the pathwise framework pioneered by \cite{F:81}  with the (functional) differential calculus introduced in \cite{D:09},  a pathwise functional Taylor expansion in terms of signature for \textit{continuous one-dimensional time-extended} paths of finite quadratic variations  has been proved in \cite{DT:23}.  (See Theorem 3.10 therein).
However, recalling  Remark~\ref{rem: non commutativity derivate} on the commutativity of the derivation order, the dependence in \cite{DT:23}  with respect to the time and path component is captured via the horizontal and vertical derivatives, respectively. Indeed, in their framework, only the horizontal and vertical derivatives do not commute (see also the discussions at page ~33 in \cite{CR:12}  and on page~10 in \cite{BD}). Therefore, considering time-extended one-dimensional paths, they can indeed recover all terms in the signature that appear in the expansion. In a multidimensional setting, however, since the higher-order (mixed) vertical derivatives commute, any expansion in terms of the signature can not be obtained.

The Taylor expansion thus further emphasizes the importance of establishing a differential calculus on path functionals that allows a non-commutative order of differentiation, without which it would not be possible to achieve Taylor expansions in terms of the signature in higher dimension. 









\end{enumerate}



\end{remark}


















\subsection{Analytic non-anticipative path functionals }

Building on the Taylor expansions in Theorem \ref{3th: taylor p23 continuous},  we mimic here the classical analysis approach to the study of smooth functions and introduce a notion of analytical path functional. We will address these concepts in the case of \cadlag $p$-rough path for $p\in [2,3)$. (Note that for a  simpler setting of \cadlag $p$-rough path for $p\in [1,2)$, it can be similarly formulated). 

We start by  the definition of the concatenation path. 
\begin{definition}
 Let $\XX=\exp^{(2)}(X,A^X)$ and $ \YY=\exp^{(2)}(Y,A^Y)\in D([0,1],G^{2}(\Rset^d))$. We define the \textit{concatenation path} of $\XX$ and $\YY$ at time $t\in[0,1]$ as the path $$\XX \oplus_t \YY \in D([0,1],G^{2}(\Rset^d)),$$ defined as follows: for all $u\in[0,1]$
    \begin{align*}
        (\XX \oplus_t \YY)_u:=\exp^{([p])}((X_u,A^X_u)1_{\{u\leq t\}})\otimes \exp^{([p])}((Y_u-Y_t+X_t,A^Y_u-A^Y_t-A^X_t)1_{\{u>t\}}). 
    \end{align*}

\end{definition}
 Next, we use the concept of concatenation path to derive the Taylor expansion of a path functional within a neighborhood of a given path.  The proof  of the following corollary is exactly the same as the proof of Theorem~\ref{3th: taylor p23 continuous}, hence omitted.


\begin{corollary}
 Let $p\in[2,3)$, $K \geq 3$ and $F:[0,1]\times D^{p}([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^K$ non-anticipative path functional such that $F,\nabla ^{}F, \dots, \nabla ^{K-1}F $, and $R^{\nabla^{K-2} F,\nabla^{K-1} F}$ are $[p,3)$\text{-}var continuous. Then, for all $\wXX\in \widehat{C}^p([0,1],G^{2}(\Rset^{d+1}))$,  $\wYY\in \widehat{C}^p([0,1],G^{2}(\Rset^{d+1}))$, $t,s\in [0,1]$, $t\leq s$, it holds that
    \begin{align}\label{3eq: taylor p23 concatenated}
    F(s,\wXX \oplus_t \wYY )=&\sum_{j=0}^{K-3}\nabla^{j}F (t,\wXX)\wY^{(j)}_{t,s}+ \mathcal{R}^F_{K-2}(s,\wXX \oplus_t \wYY),
\end{align}
where $\mathcal{R}^F_{K-2}(s,\wXX \oplus_t \wYY):=\int_t^s\int_t^{s_1}\dots \int_{t}^{s_{K-4}}\nabla^{K-2} F(s_{K-2},\wXX \oplus_t \wYY)d\wYY_{s_{K-2}} \dots d\wYY_{s_1}$, and $\wY$ denotes the signature of $\wYY$. 
\end{corollary}
\begin{remark}
 The formula~\eqref{3eq: taylor p23 concatenated} for $F$ evaluated at a \cadlag concatenation path can be derived as in the Step 3 of the proof of Theorem \ref{3th: taylor p23 continuous}, and results in an expansion whose remainder term $\mathcal{R}^F_{K-2}$ is expressed in terms of the time-extended Marcus-transformed path of the concatenation path. 
\end{remark}

Recall from Remark~\ref{remark: taylor p23}\ref{rem: weaken assumptions TF p 23} that the formula~\eqref{3eq: taylor p23 concatenated} can be derived also under the assumption of  $F$ being a $C^K$-non-anticipative path functional such that $$F,\nabla ^{}F, \dots, \nabla ^{K-1}F, \nabla ^{K}F$$ are $[p,3)$\text{-}var continuous. Now, we use this slightly stronger assumption in order to introduce the notion of analytical and entire path functional. In the following, we say that a Marcus canonical path functional is $C^\infty$  if it is $C^K$, for all $K\in \Nset$.

\begin{definition}
    Let $p\in [2,3)$ and $F:[0,1]\times D^p([0,1],G^{2}(\Rset^{d+1}))\rightarrow \Rset$ be a $C^\infty$ non-anticipative Marcus canonical  path functional. Assume  that all its vertical derivatives  $\nabla ^{j}F$ are $[p,3)$\text{-}var continuous. Fix $(t,\wXX)\in [0,1]\times \widehat{D}^p([0,1],G^{2}(\Rset^{d+1}))$. 
     \begin{enumerate}
      \item We say that $F$
 is \textit{real analytic} at $(t,\wXX)$ if there exists $\delta>0$ such that for all $(s,\wYY)\in[t,1]\times  \widehat{D}^p([0,1],G^{2}(\Rset^{d+1}))$ with  
 $|s-t|+\|\wYY\|_{p\text{-}var[t,s]}<\delta$,
 \begin{align*}
     F(s,\wXX \oplus_t \wYY)=&\sum_{j=0}^{\infty }\nabla^{j}F (t,\wXX)\wY^{(j)}_{t,s}.
 \end{align*}
\item We say that $F$
 is \textit{entire} if for all $(t,\wXX)\in  \widehat{D}^p([0,1],G^{2}(\Rset^{d+1}))$, 
 \begin{align*}
     F(t,\wXX)=\sum_{j=0}^{\infty }\nabla^{ j}F (0,\wXX)\wX^{(j)}_{0,t}.
     \end{align*}
    \end{enumerate}





 \end{definition}

 \begin{example}
   Let $\u\in T^N(\Rset^{d+1})$, for some $N\in \N$ and consider the linear functional of the signature $F^\u$ (see Section~\ref{3sec: linear functions as Marcus}). Then, by Proposition~\ref{prop: derivative linear func}, $F^\u$ is an entire functional and for all $(t,\wXX)\in  \widehat{D}^p([0,1],G^{2}(\Rset^{d+1}))$, setting $F^\u(t,\wXX):=\langle \u,\wX_t\rangle$, it holds that
 \begin{align}\label{eq: linear func pw expansion}
\langle \u,\wX_t\rangle=\sum_{j=0}^{N}\langle \u^{(j)},\wX_0\rangle \wX^{(j)}_{0,t}.
     \end{align}
    Equation~\eqref{eq: linear func pw expansion} coincides with the Chen's relation.
     More generally, we can also consider path functional of the form $F(t,\wXX):=f(\langle \u,\X_t\rangle)$ for an entire function $f:\Rset\rightarrow\Rset$. Similar computations as in~\eqref{eq: f compones sig} show that $F$ is an entire path functional.






\end{example}














