\section{Proofs of Section~\ref{sec: uat differential}}
 Before presenting the proofs of the main results of the section, we list some key notions and introduce a lighter notation. Recall from Section \ref{3sec: algebra} that
\begin{align*}
    G((\Rset^{d+1})):=\{\x\in T((\Rset^{d+1})) \ | \ \pi_{\leq N }(\x)\in G^N(\Rset^{d+1}) \text{ for all }N\in \Nset \},
\end{align*}
for $G^N(\Rset^{d+1}):=\exp^{(N)}(\mathfrak{g}^N(\Rset^{d+1}))$. Notice that $G^N(\Rset^{d+1})$ is a Carnot group (see Definition 2.2.1 in \cite{BLU:07}). 
Moreover, set
\begin{align*}
    \mathfrak{g}((\Rset^{d+1})):=\{ \x\in T((\Rset^{d+1})) \ | \ \pi_{\leq N }(\x)\in \mathfrak{g}^N(\Rset^{d+1}) \text{ for all }N\in \Nset \}.
\end{align*}
Then $G((\Rset^{d+1}))=\exp(\mathfrak{g}((\Rset^{d+1})))$ (see e.g., \cite{BBHRN:24}, \cite{S:22}) and is closed with respect to the tensor multiplication $\otimes$.

    Fix $F\in C^K$ and let $g$ be the map for which Assumption~\ref{assumpt 1} holds. For $\XX\in {C}^p([0,1], G^{[p]}(\Rset^{d+1}))$, let $g^{\XX,K}$ be the map introduced in equation~\eqref{eq: gk assumpt lemma}. To simplify the notation, we write $g^K:=g^{\XX,K}$ whenever no confusion arises, and write $\mathfrak{g}^K$  and $|\beta|_{\mathfrak{g}^K}$ in place of $\mathfrak{g}^K(\Rset^{d+1})$ and $|\beta|_{\mathfrak{g}^K(\Rset^{d+1})}$ (see  Notation~\ref{3notation derivatives lie algebra}), respectively. Finally, we denote with the index $0$ the first component of $\XX$.




\subsection{Proof of Lemma~\ref{lemma: partial derivatives gk}}\label{proof of lemma: partial derivatives gk}
 Fix $\XX\in {C}^p([0,1], G^{[p]}(\Rset^{d+1}))$ and let $(t,\bxi)\in [0,1]\times \mathfrak{g}^K$. By definition of signature and $G((\Rset^{d+1}))$,  
$$\X_t\otimes \exp(\bxi,0,\dots,0)\in G((\Rset^{d+1})).$$
Therefore, by Assumption~\ref{assumpt 1}, the map $g^K$ is well defined.  Next, fix $t\in [0,1]$. We show that for all $j=1,\dots,K$ and $|\beta|_{\mathfrak{g}^K}=j$, the derivatives $D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0}$ exist. 


The claim follows if we prove that for all $j=1,\dots,K$, $i_1,\dots,i_j=0,1,\dots,d$, 
\begin{align}\label{eq: derivatives F equal deriv g}
  U^{i_{j}}\dots U^{i_1}F(t,\XX)=
  \frac{d^j}{dh_{j}\dots dh_1}g(\X_t\otimes \exp(h_{j}\e_{i_{j}})\otimes \dots \otimes \exp(h_1\e_{i_1}))|_{h_{j}=\dots=h_1=0}.
\end{align}
Indeed,  by assumption $F\in \Mcalp^K$, the quantities $ U^{i_{j}}\dots U^{i_1}F(t,\XX)$ are well defined.  Furthermore, by Propositions 20.1.7 (see in particular equation (20.20)) and 20.1.9 (see also Proposition 20.1.4) in \cite{BLU:07}, 
setting
\begin{align*}
    L(t,h_1\e_{i_1},\dots,h_j\e_{i_j}):=g(\X_t\otimes \exp(h_{j}\e_{i_{j}})\otimes \dots \otimes \exp(h_1\e_{i_1})),
\end{align*}
it holds that for all $|\beta|_{\mathfrak{g}^K}=j$, 
\begin{align*}
    D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0}\in\text{span}\Big\{\frac{d^j}{dh_{j}\dots dh_1}L(t,h_1\e_{i_1},\dots,h_j\e_{i_j})|_{h_1=\dots=h_j=0},\ i_1,\dots,i_j=0,\dots,d\Big\},
\end{align*}
from which we deduce that $ D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0}$ exists.
In order to show~\eqref{eq: derivatives F equal deriv g}, we
apply the iterative procedure to compute the higher order vertical derivatives of $F$. 


Fix $\delta>0$ and for $i_K=0,1,\dots,d$, $h_K\in (-\delta,\delta)$ set
\begin{align*}
    &\XX^{[i_K]}(h_K):=\XX+h_{i_{K}} \e_{i_{K}}1_{\{\cdot \geq \mu_t^{[0]}\}},\\
    &\YY^{[i_K]}(h_K):=\reallywidetilde{\XX^{[i_K]}(h_K)},\\
    & \mu_t^{[i_K]}(h_K):=\psi_{R_K}^{-1}(\tau_{\XX^{[i_K]}(h_K),R_K}(t)),
\end{align*}
for some pair $(R_K,\psi_{R_K})$ that might depend on $h_K$.
For $j=K-1,\dots,1$, $i_j=0,1,\dots,d$, $h_j\in (-\delta,\delta)$, set
\begin{align*}
    &\XX^{[i_K,\dots,i_j]}(h_K,\dots,h_j):=\YY^{[i_K,\dots,i_{j+1}]}(h_K,\dots,h_{j+1})+h_{j} \e_{i_{j}}1_{\{\cdot \geq \mu_t^{[i_K,\dots,i_{j+1}]}\}},\\
    &\YY^{[i_K,\dots,i_j]}(h_K,\dots,h_j):=\reallywidetilde{\XX^{[i_K,\dots,i_j]}(h_K,\dots,h_j)},\\
    & \mu_t^{[i_K,\dots,i_j]}(h_K,\dots,h_j):=\psi_{R_j}^{-1}(\tau_{\XX^{[i_K,\dots,i_j]}(h_K,\dots,h_j),R_j}(\mu_t^{[i_K,\dots,i_{j+1}]}(h_K,\dots,h_{j+1}))),
\end{align*}
for $\reallywidetilde{\XX^{[i_K,\dots,i_j]}(h_K,\dots,h_j)}$ denoting the Marcus-transformed path of  $\XX^{[i_K,\dots,i_j]}(h_K,\dots,h_j)$ with respect to some pair $(R_j,\psi_{R_j})$ that might depend on $(h_K,\dots,h_j)$. 

Then, by definition of higher-order vertical derivatives (see Definition~\ref{def: higher order derivatives}), it holds that  for all $j=1,\dots,K$, 
\begin{align*}
    &U^{i_{j}}\dots U^{i_1}F(t,\XX)\\
    &=\frac{d^j}{dh_j\dots dh_1}F(\mu_t^{[i_K,\dots,i_1]}(0,\dots,0,h_j,\dots,h_1),\YY^{[i_K,\dots,i_j]}(0,\dots,0,h_j,\dots,h_1))|_{h_j=\dots=h_1=0}. 
\end{align*}
Finally, Assumption~\ref{assumpt 1} and a direct computation of the signature at time $\mu_t^{[i_K,\dots,i_1]}(h_K,\dots,h_1)$ of the continuous path $\YY^{[i_K,\dots,i_j]}(h_K,\dots,h_1)$ yield that
\begin{align*}
    F(\mu_t^{[i_K,\dots,i_1]}(h_K,\dots,h_1),\YY^{[i_K,\dots,i_j]}(h_K,\dots,h_1))=g(\X_t\otimes \exp(h_{j}\e_{i_{j}})\otimes \dots \otimes \exp(h_1\e_{i_1})).
    \end{align*}
The claim follows.\qed






\subsection{Proof of Theorem~\ref{3th: Nachbin for path functionals}}\label{3sec: proof Nachbin}
Before delving into the proof of Theorem~\ref{3th: Nachbin for path functionals} we outline its main steps. Recall the simplified notation introduced at the beginning of the present section.
\paragraph{Sketch of the proof.} Fix $\wXX\in \widehat{C}^p([0,1], G^{[p]}(\Rset^{d+1}))$.
\paragraph{Step 1:} We show that for $t\in[0,1]$, $i_1,\dots,i_j\in \{0,\dots,d\}^j$, $j=1,\dots,K$, 
        \begin{align*}
        &F(t,\wXX)=g^K(t,0),\\
           &U^{i_j}\dots U^{i_1}F(t,\wXX)\in \text{span}\{D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0} \ : \ \beta\in \Nset^M_0, \ |\beta|_{\mathfrak{g}^K}=j\}.
        \end{align*}

    \paragraph{Step 2:} Since $F\in C^K$, Assumption~\ref{assumpt 2}
     and an adaptation of the proof of the Weierstrass theorem (see Theorem 1.6.2 in~\cite{N:85}) to the present setting yield that there exists a sequence of polynomials $(p_n)_{n\in\Nset}$ on $[0,1]\times \mathcal{U}(0)$ such that  
 \begin{align*}
        \lim_{n\rightarrow\infty}\sup_{t\in [0,1]}\sup_{{\bxi}\in H}\sum_{\beta\in \Nset^M_0,\ |\beta|_{\mathfrak{g}^K}\leq K}\|D^\beta_{\bxi} g^K(t,{\bxi})-D^\beta_{\bxi} p_n(t,{\bxi})\|=0,
    \end{align*}
      for some compact set $H\subset \mathcal{U}(0)$ such that $0\in H$.


      \paragraph{Step 3:} We define $\YY\in {\widehat C}^p([0,1], G^{[p]}(\Rset^{d+2}))$ as the time-extended path of $\wXX$ (Section~\ref{sec: uat differential} and in particular Remark~\ref{rem: extended paths}~\ref{item 4 remark extended path}), and denote this auxiliary component by the index $-1$ and its signature by $\Y$. Let $p$  be a polynomial on $[0,1]\times \mathcal{U}(0)$. Notice that the map
      \begin{align*}
          [0,1]\ni t\mapsto  \tilde{p}(t)(\cdot):= \Big(\mathcal{U}(0)\ni {\bxi}\mapsto  p(t,{\bxi})\Big)
      \end{align*}
      belongs to $C\big([0,1],  C^{K}(\mathcal{U}(0))\big)$, where $C^K(\mathcal{U}(0))$ denotes the set of $K$ times differentiable functions on $\mathcal{U}(0)$, which we endow with the topology of uniform convergence on compacts of the function and all its derivatives up to order $K$. We exploit the Stone-Weierstrass theorem for vector-valued maps (see e.g., Theorem 3.3 in~\cite{CSTuat:23}) to show that there exists a sequence $(\v_n)_{n\in \Nset}\subset T(\Rset^{d+2})$ whose indices are in $\{-1,0,\dots,d\}$ such that
    \begin{align}\label{3eq: convergence VVSW}
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sup_{{\bxi}\in H}\sum_{\beta\in \Nset^M_0,\ |\beta|\leq K}\|D^\beta_{\bxi} p(t,{\bxi})-D^\beta_{\bxi}\langle \v_n,\Y_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle\|=0,
    \end{align}
    where $i:g^K(\Rset^{d+1})\rightarrow g^K(\Rset^{d+2})$ denotes the embedding of $g^K(\Rset^{d+1})$ into $g^K(\Rset^{d+2})$ obtained by setting equal to $0$ all the additional components.  

    \paragraph{Step 4:} A combination of Step 2 and Step 3 yields the existence of a sequence $(\v_n)_{n\in \Nset}\subset T(\Rset^{d+2})$ whose indices are in $\{-1,0,\dots,d\}$ such that
    \begin{align}\label{3eq: convergence step 4 }
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{\beta\in \Nset^M_0,\ |\beta|_{\mathfrak{g}^K}\leq K}\|D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0}-D^\beta_{\bxi}\langle \v_n,\Y_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle|_{{\bxi}=0}\|=0.
    \end{align}


   \paragraph{Step 5:} We show that there exists  a sequence $(\u_n)_{n\in \Nset}\subset T(\Rset^{d+1})$ whose indices are in $\{0,\dots,d\}$ such that for all $n\in\Nset$, $t\in [0,1]$, $\beta\in \Nset^M_0$, $|\beta|_{\mathfrak{g}^K}\leq K$,
$$D^\beta_{\bxi}\langle \v_n,\Y_t\otimes \exp(i(\bxi),0,\dots,0)\rangle|_{{\bxi}=0}=D^\beta_{\bxi}\langle \u_n,\wX_t\otimes \exp(\bxi,0,\dots,0)\rangle_{|{\bxi}=0}.$$



\paragraph{\textbf{Step 6:}}For $\u\in T(\Rset^{d+1})$, consider the path functional given by
\begin{align*}
      [0,1]\times D^p([0,1],G^{[p]}(\Rset^d))\ni (t,\XX)\mapsto F^\u(t,\XX):=\langle \u,\X_t\rangle.
\end{align*}
Recall that for such functional, the map $g^K$ in~\eqref{eq: gk assumpt lemma} reads as $g^K(t,\bxi):=\langle \u,\wX_t\otimes \exp(\bxi,0,\dots,0)\rangle$. An application of Step 1 to the functional $F^\u$ yields that for all $t\in[0,1]$, $i_1,\dots,i_j\in \{0,\dots,d\}^j$, $j=1,\dots,K$, 
        \begin{align*}
        &F^\u(t,\wXX)=\langle \u,\wX_t\rangle,\\
           &U^{i_j}\dots U^{i_1}F^\u(t,\wXX)\in \text{span}\{D^\beta_{\bxi} \langle \u,\wX_t\otimes \exp(\bxi,0,\dots,0)\rangle|_{{\bxi}=0} \ : \ \beta\in \Nset^M_0, \ |\beta|_{\mathfrak{g}^K}=j\},
        \end{align*}
which concludes the first part of the proof. 


\paragraph{\textbf{Step 7:}} For $\wXX\in \widehat{D} ^p([0,1], G^{[p]}(\Rset^{d+1}))$, we deduce the claim by exploiting the Marcus property of the functionals.













\begin{proof}
Fix $\wXX\in \widehat{{C}}^p([0,1], G^{[p]}(\Rset^{d+1}))$. 

\paragraph{\underline{Step 1}:} 
First of all notice that $F(t,\XX)=g(\X_t)=g^K(t,0)$ by Assumption~\ref{assumpt 1} and definition of $g^K$ in~\eqref{eq: gk assumpt lemma}. Then, an inspection of the proof of Lemma~\ref{lemma: partial derivatives gk} shows that for all $j=1,\dots,K$, $i_1,\dots,i_j=0,\dots,d$ 
\begin{align*}
  U^{i_{j}}\dots U^{i_1}F(t,\wXX)=\frac{d^j}{dh_{j}\dots dh_1}g(\wX_t\otimes \exp(h_{j}\e_{i_{j}})\otimes \dots \otimes \exp(h_1\e_{i_1}))|_{h_{j}=\dots=h_1=0}.
\end{align*}
Since by Propositions 20.1.4 and 20.1.5 (see in particular equation 20.19), in~\cite{BLU:07}, for all $j=1,\dots,K$,
 \begin{align}\label{3eq: span Dbeta g }
     \frac{d^j}{dh_{j}\dots dh_1} g(\wX_t\otimes \exp(h_{j}\e_{i_{j}})\otimes \dots& \otimes \exp(h_1\e_{i_1}))|_{h_{j}=\dots=h_1=0} \\
     &\in \text{span}\{D^\beta_{\bxi} g^K(t,{\bxi})|_{{\bxi}=0}
      \ : \beta\in \Nset^M_0,\ |\beta|_{\mathfrak{g}^K=j}\}.\nonumber 
 \end{align} The claim follows. 

\paragraph{\underline{Step 2}:} It follows directly by the assumption on $g^K$ and a simple adaptation of the proof of Theorem 1.6.2 in~\cite{N:85} to the present setting.

\paragraph{\underline{Step 3}:} Let $p$ be a polynomial on $[0,1]\times \mathcal{U}(0)$, $\YY\in \widehat{C}^p([0,1], G^{[p]}(\Rset^{d+2}))$ be the time-extended path of $\wXX$, and denote the  auxiliary time component by the index $-1$ and its signature by $\Y$. Consider the following set of maps
$$\mathcal{W}:=span\left\{ t \mapsto\left ( \mathcal{U}(0)\ni {\bxi}\mapsto  w(t)({\bxi}):=  \langle e_I, {\mathbb{Y}}_t \otimes \exp ( i({\bxi}),0,\dots,0)\rangle \right), |I | \geq 0\right\}.$$
We verify the hypothesis of the Stone -Weiestrass theorem for vector-valued maps to show the convergence in equation~\eqref{3eq: convergence VVSW}. We must prove that $\mathcal{W}$ satisfies the following conditions: \begin{enumerate}
	    \item \label{3VVSW 1} it is a $\mathcal{A}$-submodule of $C([0,1],C^K(\mathcal{U}(0)))$, for some point separating subalgebra $\mathcal{A }\subseteq C([0,1])$ that vanishes nowhere; 
 \item \label{3VVSW 2} for all $t\in [0,1]$, $\mathcal{W}(t):=\{w(t) \ \colon \ w\in \mathcal{W}\}$ is dense in $C^K(\mathcal{U}(0))$.
	\end{enumerate}
~\ref{3VVSW 1}:    Notice that $\mathcal{W} \subseteq C([0,1], C^{K} (\mathcal{U}(0))$, as the functions in $\mathcal{W}$ are simply linear combinations of polynomials in ${\bxi}$ whose coefficients are continuous in $t$. Let $\mathcal{A}$ denote the space of polynomials on $[0,1]$. Then, $\mathcal{W}$ is an $\mathcal{A}$-submodule since the map $[0,1]\ni t \mapsto p(t) w(t) \in  \mathcal{W}$ for every  $w\in \mathcal{W}$ and $p$ polynomial on $[0,1]$.

\noindent~\ref{3VVSW 2}: Fix $t\in [0,1]$. We show that the set $\mathcal{W}(t)$,  which explicitly reads as 
    \begin{align}\label{3eq: W(t)}
        \mathcal{W}(t)=\text{span}\{ \mathcal{U}(0)\ni{\bxi}\mapsto\langle \epsilon_I,{\mathbb{Y}}_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle\colon |I|\geq0\},
    \end{align}
 is dense in $C^{K}( \mathcal{U}(0))$.  To this end, we apply the Nachbin theorem (see~\cite{N:49}). We need to verify that the set $\mathcal{W}(t)$ satisfies the following properties:
 \begin{enumerate}
	    \item\label{3Nachbin 1} it is a linear subspace of $C^K(\mathcal{U}(0))$;
	    \item\label{3Nachbin 2}it is a sub-algebra that contains a
	non-zero constant function and separates points;
	    \item\label{3Nachbin 3} for all $\bxi\in \mathcal{U}(0)$, $\y\in \mathfrak{g}^K(\Rset^{d+1})$ with $\y\neq 0$, there exists $f\in \mathcal{W}(t)$ such that $\nabla_{\bxi} f(\bxi) \y \neq 0$.
	\end{enumerate}
~\ref{3Nachbin 1}: It is clear.

 \noindent~\ref{3Nachbin 2}: The shuffle properties of group-like elements yields that $\mathcal{W}(t)$ is a sub-algebra (see equation \eqref{3eq:shuffle}). Moreover, it contains a map constantly equal to $1$:  $$\mathcal{U}(0)\ni{\bxi}\mapsto\langle \epsilon_\emptyset,{\mathbb{Y}}_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle,$$ and separates point. Indeed, let ${\bxi}_1,{\bxi}_2\in \mathcal{U}(0)$ with ${\bxi}_1\neq {\bxi}_2$. If for some $i=0,\dots,d$, $\langle\e_i,{\bxi}_1\rangle \neq \langle\e_i,{\bxi}_2\rangle $, then $$\langle \e_i,\Y_t\otimes \exp(i({\bxi}_1),0,\dots,0)\rangle \neq \langle \e_i,\Y_t\otimes \exp(i({\bxi}_2),0,\dots,0)\rangle.$$ Otherwise, let $J:=(i_1,\dots,i_j)\in \{0,\dots,d\}^j$ $j=2,\dots,K$ be such that $\langle \e_J,{\bxi}_1\rangle \neq \langle \e_J,{\bxi}_2\rangle$ and $\langle \e_I,{\bxi}_1\rangle=\langle \e_I,{\bxi}_1\rangle$ for all $I\in \{0,\dots,d\}^i $ with $i<j$. Then,
     $$\langle \e_J,\Y_t\otimes \exp(i({\bxi}_1),0,\dots,0)\rangle \neq \langle \e_J,\Y_t\otimes \exp(i({\bxi}_2),0,\dots,0)\rangle.$$ 
\noindent~\ref{3Nachbin 3}: Let ${\bxi}\in \mathcal{U}(0)$ and $\y\in \mathfrak g^K(\Rset^{d+1})$ with $\y\neq 0$. 
If for some $i=0,\dots,d$, $\langle \e_i,\y\rangle\neq 0$, then 
\begin{align*}
    \nabla_{{\bxi}}\langle \e_i,\mathbb{Y}_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle  \y =\langle \e_i,\y\rangle\neq 0.
 \end{align*}
If instead for all $i=0,\dots,d$, $\langle \e_i,\y\rangle\neq 0$, let $J:=(i_1,\dots,i_j)\in \{0,\dots,d\}^j$ $j=2,\dots,K$ be such that $\langle \e_J,\y\rangle \neq 0$ and $\langle \e_I,\y\rangle  =0$ for all $I\in \{0,\dots,d\}^i $ with $i<j$. Then,
\begin{align*}
    \nabla_{{\bxi}}\langle \e_J,\mathbb{Y}_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle  \y =\langle \e_J,\y\rangle\neq 0.
 \end{align*}
The claim follows.
\paragraph{\underline{Step 4}:} A direct consequence of  Step 2 and Step 3.
\paragraph{\underline{Step 5}:} Let $(\v_n)_{n\in \Nset}\subset T(\Rset^{d+2})$ be the sequence  whose indices are in $\{-1,0,\dots,d\}$ and for which the convergence in~\eqref{3eq: convergence step 4 } holds. The assertion follows if we prove that
\begin{enumerate}
    \item \label{3lask K indices } we can extract a subsequence, that without loss of generality still denoted as $(\v_n)_{n\in\Nset}$, whose last $K$ indices of each of its terms differ from $-1$. 
\end{enumerate}
Recall that here $-1$ denotes the index corresponding to the auxiliary time component of $\mathbf{Y}$. Indeed, in such a case, one can find a sequence $(\u_n)_{n\in\Nset}\subset  T(\Rset^{d+1})$ whose indices are in $\{0,\dots,d\}$ such that for all $n\in \Nset$, $t\in [0,1]$, $\beta\in \Nset^M_0$, $|\beta|_{\mathfrak{g}^K}\leq K$,
\begin{align*}
    &\langle \mathbf{v}_n, \mathbb{Y}_t \rangle= \langle \mathbf{u}_n,  {\wX}_t \rangle,\\
     &D^\beta_{\bxi}\langle \v_n,\Y_t\otimes \exp(i({\bxi}),0,\dots,0)\rangle|_{{\bxi}=0}=D^\beta_{\bxi}\langle \u_n,\wX_t\otimes \exp({\bxi},0,\dots,0)\rangle_{|{\bxi}=0},
\end{align*}
concluding the proof.

In order to prove~\ref{3lask K indices }, assume first  that for all $j=1,\dots,K$, there exist $i_j\in \{0,\dots,d\}$ and $t_j\in [0,1]$ such that 
    \begin{align}\label{3eq: gradientneq0}
        \langle \e_{i_j}^{\otimes j},\nabla^j F(t_j, \wXX)\rangle \neq 0.
    \end{align}
Under this assumption, condition~\ref{3lask K indices } is verified. Indeed, otherwise, for some $j=1,\dots,K$, and some $N\in\Nset$, the last $j$-th component of each $\v_n$ with $n\geq N$ would be equal to $-1$. This would imply that for all $n\geq N$ and $t\in [0,1]$,
\begin{align*}
    D^\beta_{{\bxi}}\langle \mathbf{v}_n, \mathbb{Y}_t \otimes \exp (i({\bxi}),0,\dots,0)\rangle _{|{\bxi}=0}=0,
\end{align*}
for all  $\beta\in \Nset_0^M$ with $|\beta|_{\mathfrak{g}^K}=j$.
In particular, by Step 4, for all $t\in [0,1]$
  \begin{align}\label{eq: gbeta}
      D^\beta_{{\bxi}}g^K(t,{\bxi})|_{{\bxi}=0}=0.
    \end{align}
   Finally, by Step 1, \eqref{eq: gbeta} 
  contradicts~\eqref{3eq: gradientneq0} and the claim follows.

Assume  that condition~\eqref{3eq: gradientneq0} does not hold. This means that there exist $1 \leq m_1<\dots<m_l\leq K$ such that for all $i\in \{0,\dots,d\}$ and for all $t\in [0,1]$,  $  \langle \e_{i}^{\otimes m_k},\nabla^{m_k} F(t, \wXX)\rangle =0$, for all $k=1,\dots,l$. Let $M$ be the biggest of such $m_k$ and
consider the functional  ${F}_0:[0,1]\times D^{p}([0,1],G^{[p]}(\Rset^{d+1}))\rightarrow \Rset$ defined via $${F}_0(t,\XX):=F(t,\XX)+\langle \e_0^{\otimes M},\X_t\rangle,$$ 
 for all $(t,\XX)\in [0,1]\times D^{p}([0,1],G^{[p]}(\Rset^{d+1}))$, with $\X_t$ denoting the signature of $\XX$ at time $t$. Notice that  for all $t\in (0,1]$, and for all $m_k$, $  \langle \e_{0}^{\otimes m_k},\nabla^{m_k} {F}_0(t, \wXX)\rangle =\langle \e_0^{\otimes M-m_k},\wX_t\rangle\neq 0$.
Therefore, 
\begin{enumerate}
\item [a)] if $M=1$, condition~\eqref{3eq: gradientneq0} is verified for the functional ${F}_0$. An application of the previous steps to the functional $F_0$ yields that there exists a sequence $(\u^0_n)_{n\in \Nset}\subset T(\Rset^{d+1})$ whose indices are in $\{0,\dots,d\}$ such that
    \begin{align*}
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{\beta\in \Nset^M_0,\ |\beta|_{\mathfrak{g}^K}\leq K}\|D^\beta_{\bxi}g^K(t,{\bxi})|_{{\bxi}=0}&+D^\beta_{\bxi}\langle \e_0^{\otimes M},\wX_t\otimes \exp(\bxi,0,\dots,0)\rangle|_{\bxi=0}\\
       &- D^\beta_{\bxi}\langle \u^0_n,\wX_t\otimes \exp(\bxi,0,\dots,0)\rangle|_{{\bxi}=0}\|=0.
    \end{align*}
  The claim follows by considering the sequence $\u_n:=\u^0_n-\e_0^{\otimes M}$,  $n\in \Nset$;
    \item [b)] if $M>1$ and for all $1\leq j<M$, $i_j$ for which $F$ satisfies condition~\eqref{3eq: gradientneq0} at $\wXX$ is different from $0$, then condition~\eqref{3eq: gradientneq0} is verified for the functional ${F}_0$ and the claim follows as in a).
\item [c)] if $M>1$ and for some $1\leq j<M$, $i_j$ for which $F$ satisfies condition~\eqref{3eq: gradientneq0} is equal to $0$, denote such $js$ by $1\leq j_1<\dots<j_l<M$, $1\leq l<M$.
    If for all $k=1,\dots,l$
    \begin{align*}
        \langle \e_{0}^{\otimes j_{k}},\nabla^{j_{k}} F(t, \wXX)\rangle+\langle \e_0^{\otimes M-{j_{k}}},\wX_t\rangle \neq  0,
    \end{align*}
     for some $t\in [0,1]$, the claim follows as in a). Otherwise, let $J$ be the smallest of the $j_k$ for which  for all $t\in [0,1]$,
\begin{align*}
        \langle \e_{0}^{\otimes j_{k}},\nabla^{j_{k}} F(t, \wXX)\rangle+\langle \e_0^{\otimes M-{j_{k}}},\wX_t\rangle = 0.
    \end{align*}
  Consider the path functional $F_1(t,\XX):=F(t,\XX)+\alpha_1\langle \e_0^{\otimes M},\X_t\rangle$  for  $\alpha_1\in \Rset$, $\alpha_1\notin\{ 1,0\}$. Observe that for all $j_k\geq J$ and for all $t\in (0,1]$,
$  \langle \e_{0}^{\otimes j_k},\nabla^{j_k} F_1(t, \wXX)\rangle \neq 0.$


 Finally, if for some $j_{k}$, with $j_k<J$
   \begin{align*}
        \langle \e_{0}^{\otimes j_{k}},\nabla^{j_{k}} F(t, \wXX)\rangle+\alpha_1
        \langle \e_0^{\otimes M-{j_{k}}},\wX_t\rangle = 0,
    \end{align*}
  for all $t\in [0,1]$, let $J_1<J$ 
 be the smallest of such $j_k$. Consider the path functional $F_2(t,\XX):=F(t,\XX)+\alpha_2\alpha_1\langle \e_0^{\otimes M},\X_t\rangle$  for  $\alpha_2\in \Rset$, $\alpha_2\notin\{ 1,0,\frac{1}{\alpha_1}\}$ and observe  that for all $j_k\geq J_1$  and for all $t\in (0,1]$,
$  \langle \e_{0}^{\otimes j_k},\nabla^{j_k} F_2(t, \wXX)\rangle \neq 0.$ An iterative application of this reasoning yields that condition~\eqref{3eq: gradientneq0} is verified for a functional  of the form $\widetilde{F}(t,\XX):=F(t,\XX)+\alpha\langle \e_0^{\otimes M},\X_t\rangle$  for some  properly choosen $\alpha\in \Rset$, $\alpha\neq 0$. The claim follows as in a).
\end{enumerate}


\paragraph{\textbf{\underline{Step 6}:}} It is a simple application of Step 1 to the functional $F^\u$.


\paragraph{\textbf{\underline{Step 7}:}} Fix $\wXX\in \widehat{D}^p([0,1], G^{[p]}(\Rset^{d+1}))$ and denote by $\ZZ$ the Marcus-transformed path such that $\ZZ\in \widehat{C}^p([0,1], G^{[p]}(\Rset^{d+1}))$. Recall that by definition of tracking-jumps-extended paths, such  Marcus transformed path always exists (see Remark~\ref{3rem: Marcus tracking-jumps paths}). An application of the previous steps of the proof to $\ZZ$ yields that there exists $(\u_n)_{n\in \Nset}\in T(\Rset^{d+1})$ such that
    \begin{align}\label{3eq: Nachbin approximation Marcus cadlag }
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{j=0}^K\|\nabla ^jF(t, \ZZ)-\nabla ^jF^{\u_n}(t, \ZZ)\|=0. 
    \end{align}
    Thus, in particular, 
\begin{align*}
        \lim_{n\rightarrow\infty }\sup_{t\in [0,1]}\sum_{j=0}^K\|\nabla ^jF(\mu_t, \ZZ)-\nabla ^jF^{\u_n}(\mu_t, \ZZ)\|=0, 
    \end{align*}
    for $\mu_t$ introduced in Notation~\ref{3notation: mut}. Since we deal here with Marcus canonical  path functionals, the claim follows.
\end{proof}

\begin{remark}\phantomsection \label{3rem: after proof Nachbin}
\begin{enumerate}
    \item \label{3rem: after proof Nachbin i}Let $\wXX\in \widehat{D}^p([0,1], G^{[p]}(\Rset^{d+1}))$ and $(\u_n)_{n\in\Nset}\in T(\Rset^{d+1})$ be the sequence such that the convergence in equation~\eqref{3eq: Nachbin approximation Marcus cadlag } holds. Observe that by the construction of the Marcus transformed path, for all $j=0,\dots,K$,
    \begin{align*}
        \sup_{s\in [0,1]}\sup_{n\in \Nset}\sup_{\theta\in [0,1]}\|\langle \u_n^{(j)},\wX_{s^-}\otimes \exp(\theta \log^{([p])}(\Delta \wXX_s))\rangle\|<\infty.
    \end{align*}

\end{enumerate}


\end{remark}



