\subsection{Proof of Lemma \ref{3lemma: ito formula uniformly bounded p 12}}\label{proof lemma ito formula p12}
Recall that for all $n\in \Nset$, $j=0,\dots,2$, $\nabla ^jF^{\u_n}(t,\widehat \XX)=\langle \u_n^{(j)},\widehat \X_t\rangle$, where $\wX$ denotes the signature of $\wXX$.


~\ref{3item: lemma 1 i}: Let $(t_i)_i\subset [0,1]$ be the grid such that $\widehat \XX$ is a linear path on $[t_i,t_{i+1}]$. Notice that by Chen's relation and the invariance property of the signature under reparametrization (see e.g., the proof of Proposition~\ref{prop: derivative linear func}) for every $u\in [t_i,t_{i+1}]$,  $$  \widehat \X_u=\widehat \X_{t_i}\otimes \exp(\theta \widehat  \XX_{t_i,t_{i+1}}),$$
    for some $\theta \in [0,1]$.  Fix $s_1,s_2\in [t_i,t_{i+1}]$, $s_1\leq s_2 $, for some $i$. Then,  
    \begin{align*}
        \langle\u_n^{(1)},\widehat \X_{s_2} \rangle-\langle\u_n^{(1)},\widehat \X_{s_1} \rangle=g(1)-g(0),
    \end{align*}
    for $g:[0,1]\rightarrow\Rset^d$ such that  $ g(\theta):= \langle\u_n^{(1)},\widehat \X_{s_1}\otimes \exp(\theta \widehat  \XX_{s_1,s_2})\rangle $, for all $\theta \in [0,1]$.
    Thus, a first-order Taylor expansion of each of the components of $g$ at $0$ yields that 
    \begin{align}\label{3eq: mean value}
        \|\langle\u_n^{(1)},\widehat \X_{s_2} \rangle-\langle\u_n^{(1)},\widehat \X_{s_1} \rangle\|\leq \sup_{\theta\in [0,1]}\|\langle\u_n^{(2)},\widehat \X_{s_1} \otimes \exp( \theta \widehat\XX_{s_1,s_2})\rangle\|\|  \widehat \XX_{s_1,s_2}\|.
    \end{align}
    Since by~\eqref{eq: approx F and derivatives p 12}, 
    \begin{align*}
       \sup_{n\in\Nset} \sup_{s_1,s_2\in [t_i,t_{i+1}]}\sup_{\theta \in [0,1]}\|\langle\u_n^{(2)},\widehat \X_{s_1} \otimes \exp( \theta \widehat\XX_{s_1,s_2})\rangle\|<\infty,
    \end{align*}
    equation~\eqref{3eq: mean value} and $\|\widehat \XX\|_{1\text{-}var}<\infty $ yield that $  \sup_{n\in \Nset}\|\langle \u_n^{(1)},\widehat \X_\cdot\rangle\|_{1\text{-}var[t_i,t_{i+1}]}<\infty.$
    Repeating the same reasoning on every $[t_i,t_{i+1}]$, the claim follows.

 ~\ref{3item: lemma 1 ii}: It follows from~\ref{3item: lemma 1 i}, \eqref{eq: approx F and derivatives p 12}, and interpolation (see Lemma 5.12 and Lemma 5.27 in~\cite{FV:10}).
\qed

\subsection{Proof of Lemma \ref{3lemma: ito formula uniformly bounded p 23}}\label{proof lemma ito p23}

     ~\ref{3item lemma 2 i}: Let $(t_i)_i\subset [0,1]$ be the grid such that $\widehat X:=\pi_1(\wXX)$ is a linear path on $[t_i,t_{i+1}]$, and notice that for every $u\in [t_i,t_{i+1}]$, $  \widehat \X_u=\widehat \X_{t_i}\otimes \exp(\theta \widehat{X}_{t_i,t_{i+1}}),$
