    \subsection{Proof of Corollary \ref{3coro: ito formula follmer}}\label{proof 3coro: ito formula follmer}

Let $\widehat \XX\in \widehat{D}^{p}([0,1],G^{2}(\Rset^{d+1})) $ be a Marcus-like weakly geometric rough path such that $\pi_1(\wXX)=\widehat{X}$.  By Theorem~\ref{3th: Nachbin for path functionals},
\begin{align*}
    \{s\in(0,1] \ \colon \ \Delta \nabla ^2 F(s,\wXX)\neq 0\}=\{s\in(0,1] \ \colon \ \Delta \wXX_s\neq 0\},
\end{align*}
and $\widehat{\XX}$ is Marcus-like, 
by Remark~\ref{3rem: quadratic variation}, 
\begin{align}\label{eq: convergence integral qv follmer}
    \lim_{n\rightarrow\infty }\sum_{s^n_i\in \pi^n_{[0,1]}}\nabla^2 F(s^n_i,\wXX) \widehat{X}^{\otimes 2}_{s^n_i,s^n_{i+1}}=\int_0^t\nabla^2F(s,\wXX)d[\widehat{X},\widehat{X}]^c_s+\sum_{0<s\leq t}\nabla^2F(s,\wXX)\Delta \widehat{X}^{\otimes 2}_{s}.
\end{align}
Moreover,  by Theorem~\ref{3th: Ito formula p 23}, $\big( \nabla F(\cdot ,\wXX), \nabla^{2}F(\cdot ,\wXX)\big)\in \mathcal{V}^{p',r}_{\wXX}$, for all $p'>p$ such that $\frac{1}{p'}+\frac{2}{p}>1$. Since for all $t\in [0,1]$, 
     $\nabla^2 F(t,\wXX)=\text{Sym}(\nabla^2 F(t,\wXX))$, the existence of the limit in equation~\eqref{3eq: coro follmer limit integral} follows by definition of the rough integral. Finally,  formula~\eqref{3eq: ito formula follmer} is derived from equation~\eqref{3eq: ito formula p 23}.
\qed 

