\section{Proofs of Section \ref{sec: functional taylor}}


\subsection{Proof of Theorem \ref{th: taylor 12}}\label{prof th: taylor 12}
We first prove the result for $F$ evaluated at some continuous path (Step 1) and then extend it to \cadlag paths by applying the Marcus transformation (Step 2).

\paragraph{Step 1}: Let $\widehat \XX\in  \widehat C^{p}([0,1],G^1(\Rset^{d+1}))$. We prove the assertion by induction. If $K=2$, then the expansion~\eqref{3eq: taylor expansion p12} is simply the statement of Theorem~\ref{3th: Ito formula p 12}. Assume $K>2$ and that the assertion holds  for all $l=2,\dots,K-1$. By assumption $F$ is $C^K$, and is in particular $C^{K-1}$, thus by the induction hypothesis, 
\begin{align*}
    F(t,\widehat \XX)=&\sum_{j=0}^{K-3}\nabla^{j}F (0,\widehat \XX)\widehat \X^{(j)}_{0,t}+ \mathcal{R}^F_{K-2}(t,\widehat \XX),
\end{align*}
for $\mathcal{R}^F_{K-2}(t,\widehat \XX):=\int_0^{t}\int_0^{t_1}\dots \int_{0}^{t_{K-3}}\nabla^{ K-2} F(t_{K-2}, \widehat \XX)d \widehat \XX_{t_{K-2}} \dots  d \widehat \XX_{t_1}$.
    Next, since $\nabla^{K-2}F$ is $C^2$ (see Remark~\ref{remark: CK functionals}) and $\nabla ^{K-2}F, \nabla ^{K-1}F $ are $[p,2)$\text{-}var continuous, a component-wise application of Theorem \ref{3th: Ito formula p 12} to $ \nabla^{K-2}F$ yields that for all $s\in [0,1]$,
    \begin{align}\label{3eq: Taylor p12 linear from  k-2 to k-1}
         \nabla^{K-2}F(s,\widehat \XX)=  \nabla^{K-2} F(0,\widehat \XX)+\int_0^s \nabla^{K-1} F(r,\widehat \XX)d\widehat \XX_r.
    \end{align}
    The claim follows by replacing the expression in equation~\eqref{3eq: Taylor p12 linear from  k-2 to k-1} into  
   $\mathcal{R}^F_{K-2}(t,\widehat \XX)$.

   \paragraph{Step 2}: Let $(t,\widehat \XX)\in [0,1]\times  \widehat D^{p}([0,1],G^{1}(\Rset^{d+1})) $ and $\ZZ$ the time-extended Marcus-transformed path of $\wXX$. By Step 1 the expansion~\eqref{3eq: taylor expansion p12} holds when evaluating the $F$ at $(\psi_{R}^{-1}(\tau_{\wXX,R}(t)),\ZZ)$. Since for all $j=0,\dots,K-2$, $\nabla^jF$, $\wX^{(j)}$ are Marcus canonical  path functional, the claim follows.
\subsection{Proof of Theorem \ref{3th: taylor p23 continuous}}\label{prof 3th: taylor p23 continuous}



We split the proof into three steps. We first derive the Taylor expansion for functionals evaluated at the truncated signature at level $2$ of a time-extended piecewise linear path (Step 1). 
Then, we extend it to continuous paths by a density argument  (Step 2), and finally, we address the general \cadlag case  (Step 3). Starting from functionals evaluated at the truncated signature at level $2$ of a time-extended piecewise linear path simplifies the proof development as it enables working with Young integrals (and thus Riemann sums) instead of truly rough integrals (and thus compensated Riemann sums, see Proposition~\ref{3prop: rough integral}) in the derivation of the remainder term $\mathcal{R}_{K-2}^F$. This is possible because any rough integral with respect to the level-2 signature of a $\Rset^d$-valued path of finite variation is simply a Young integral with respect to the path itself (see e.g., Lemma~\ref{lemma: consistency}).




\paragraph{Step 1:}   Let $\widehat \XX\in  \widehat C^{1}([0,1],G^2(\Rset^{d+1}))$ be the truncated signature at level $2$ of a time-extended piecewise linear path. We prove the assertion by induction. If $K=3$, then the expansion in equation~\eqref{3eq: taylor expansion p23} is simply the statement of Theorem~\ref{3th: Ito formula p 23}. Assume $K>3$ and that the assertion holds true for all $j=3,\dots,K-1$. Since $F$ is in $C^K$, it is in particular in $C^{K-1}$. By the induction hypothesis,  \begin{align*}
    F(t,\wXX)=&\sum_{j=0}^{K-4}\nabla^{j}F (0,\widehat \XX)\widehat \X^{(j)}_{0,t}+ \mathcal{R}^F_{K-3}(t,\widehat \XX),
\end{align*}
for $\mathcal{R}^F_{K-3}(t,\widehat \XX):=\int_0^{t}\int_0^{t_1}\dots \int_{0}^{t_{K-4}}\nabla^{ K-3} F(t_{K-3}, \widehat \XX) d \widehat \XX_{t_{K-3}} \dots  d \widehat \XX_{t_1}$. Thus, the claim follows
if we prove that 
\begin{align}\label{3eq: eq: eq3 step1 proof taylor p23}
    \mathcal{R}^F_{K-3}(t,\widehat \XX)=\nabla^{K-3}F(0,\wXX)\wX^{(K-3)}_{0,t}+\mathcal{R}^F_{K-2}(t,\widehat \XX).
\end{align} Since $\nabla^{K-3}F$ is a $C^3$ non-anticipative Marcus canonical  path functional (see Remark~\ref{remark: CK functionals}), and $\nabla ^{K-3}F,\nabla ^{K-2}F,\nabla ^{K-1}F $, and $R^{\nabla^{K-2} F,\nabla^{K-1} F}$ are $[p,3)$\text{-}var continuous, a component-wise application of Theorem~\ref{3th: Ito formula p 23} to $ \nabla^{K-3}F$ yields that for all $s\in [0,1]$,
    \begin{align}\label{3eq: Taylor p23 linear from  k-3 to k-2}
         \nabla^{K-3}F(s,\widehat \XX)=  \nabla^{K-3} F(0,\widehat \XX)+\int_0^s \nabla^{K-2} F(r,\widehat \XX)d\widehat \XX_r.
    \end{align}
Finally, since any rough integral with respect to $\wXX$ is nothing else than a Young integral with respect to $\pi_1(\wXX)$, (see e.g., Lemma~\ref{lemma: consistency}), the claim follows by replacing the expression in equation~\eqref{3eq: Taylor p23 linear from  k-3 to k-2} into $\mathcal{R}^F_{K-3}(t,\widehat \XX)$.




\paragraph{Step 2:}  Fix $\widehat \XX \in  \widehat C^{p}([0,1],G^{2}(\Rset^{d+1})) $. By Theorem 5.23 in~\cite{FV:10}, there exists a sequence of piecewise linear time-extended paths such that their truncated signature at level $2$, denoted by $(\widehat \XX^M)_{M\in \Nset}$, satisfies
    \begin{align*}
        \lim_{M\rightarrow\infty }d_{CC}\sup_{t\in[0,1]}(\widehat \XX^M_t,\widehat \XX_t)=0, \qquad \text{and}\qquad    \sup_{M\in \Nset}\|\widehat \XX^M\|_{p\text{-}var}\leq C\|\|\widehat \XX\|_{p\text{-}var},
    \end{align*}
    for some $C>0$. 
    By Step 1, for every fixed $M$ and $t\in [0,1]$, 
       \begin{align*}
    F(t,\widehat \XX^M)=&\sum_{j=0}^{K-3}\nabla^{j}F (0,\widehat \XX^M)\widehat \X^{M,(j)}_{0,t}+ \mathcal{R}^F_{K-2}(t,\widehat \XX^{M}).
\end{align*}
Thus, since for all $j=0,\dots,K-3$, $ \nabla ^{j}F $ and  $\wX^{(j)}$ are $[p,3)$\text{-}var continuous (see Proposition~\ref{prop: derivative linear func}), the claim follows if we prove that for every $t\in [0,1]$,
\begin{align*}
    \lim_{M\rightarrow\infty} \mathcal{R}^F_{K-2}(t,\wXX^{M})= \mathcal{R}^F_{K-2}(t,\wXX).
\end{align*}
To this end,  set $G^{-1}:=\nabla ^{K-1}F$, $G^0:=\nabla ^{K-2}F$ and define for $j=1,\dots,K-2$, 
\begin{align*}
G^j(t,\wXX):=\int_0^t\int_0^{t_{1}}\dots \int_0^{t_{j-1}} \nabla ^{K-2}F(t_{j},\wXX)d\wXX_{t_{j}}\dots d\wXX_{t_{1}}.
\end{align*}
We show that there exists $p:=p^{(0)}<p^{(1)}<\dots p^{(K-2)}<3$ such that for all $j=1,\dots,K-2$, 
\begin{align}\label{3eq: p^j taylor convergence}
&\lim_{M\rightarrow\infty }d_{p^{(j)}}(G^{j-2}(\cdot,\widehat \XX^M), G^{j-2} (\cdot,\widehat \XX))=0,\\
        & \lim_{M\rightarrow\infty }d_{p^{(j)}/2}\big(R^{G^{j-1},G^{j-2}}((\cdot,\cdot),\wXX^M),R^{G^{j-1},G^{j-2}}((\cdot,\cdot),\wXX)\big)=0,\nonumber
\end{align}
and $\lim_{M\rightarrow\infty}d_{CC}(G^{j-1}(0,\wXX^M),G^{j-1}(0,\wXX^M))=0.$
Then, a similar argument as in the Step 2 of the proof of Theorem~\ref{3th: Ito formula p 23} (see equation~\eqref{3eq: proof  step 2 ito p23 }) yields that  for all $j=1,\dots,K-2$, 
\begin{align}\label{3eq: convergence dpj final}
\lim_{M\rightarrow\infty}d_{p^{(j)}\text{-}var}\big( G^j(\cdot,\wXX^M), G^j(\cdot ,\wXX))=0.
\end{align}
Since $G^{K-2}=\mathcal{R}_{K-2}^F$, the claim follows. 

We reason by induction. Let $j=1$ and fix $p^{(1)}>p$.  By interpolation, $$\lim_{M\rightarrow\infty}d_{p^{(1)}\text{-}var}\big(\wXX^M,\wXX)=0.$$ Since by assumption $G^{-1}$, $G^0$, and $R^{G^{0},G^{-1}}$ are $[p,3)$-var continuous, the claim follows. 


Assume that the assertion holds  for all $l=1,\dots,j$, with $K-3\geq j>1$, and fix $p^{(j+1)}>p^{(j)}>p^{(j-1)}$. By the induction hypothesis, 
\begin{align}\label{3eq: p3 taylor induction}
\lim_{M\rightarrow\infty}d_{p^{(j)}\text{-}var}\big( G^{j-1}(\cdot,\wXX^M), G^{j-1}(\cdot ,\wXX)\big)=0.
\end{align}
Moreover, an application of equation (2.3.3) in Theorem 31 in~\cite{FS:17} yields that 
$$  \sup_{M\in \Nset }  \|R^{G^{j},G^{j-1}} ((\cdot,\cdot),\wXX^M)\|_{p^{(j)}/2\text{-}var}<\infty.$$
Therefore, by interpolation
\begin{align*}
    \lim_{M\rightarrow\infty }d_{p^{(j+1)}/2}\big(R^{G^{j},G^{j-1}}((\cdot,\cdot),\wXX^M),R^{G^{j},G^{j-1}}((\cdot,\cdot),\wXX)\big)=0.
\end{align*}
Since the convergence in 
\eqref{3eq: p3 taylor induction} holds  also with respect to $d_{p^{(j+1)}}$, the claim follows.

\paragraph{Step 3:} It follows as the Step 2 in the proof of Theorem \ref{th: taylor 12}.
\qed




\section{Auxiliary remarks}\label{3appendix: integration theories}

\subsection{Young and (level 2) rough integration}\label{sec: rough=young}
In this section, we review the notion of the Young and the (level 2) rough integral and discuss their consistency. First, we review relevant notions of convergence.








\begin{definition}[\cite{FZ:17}] \label{3def: MRS RRS}For $\Xi:\Delta_1\rightarrow\Rset^m$ and  a partition $\pi_{[0,1]}$  of the interval $[0,1]$, we say that the quantity $\sum_{s_i\in \pi_{[0,1]}}\Xi_{s_i,s_{i-1}}$ converges to $K\in \Rset^d$, 
\begin{enumerate}
    \item in the Mesh Riemann-Stieltjes
(MRS) sense: if for any $\varepsilon>0$, there exists $\delta>0$ such that for all $\pi_{[0,1]}$ with $|\pi_{[0,1]}|<\delta$,  $|\sum_{s_i\in \pi_{[0,1]}}\Xi_{s_i,s_{i-1}}-K|\leq \varepsilon$.
\item in the Refinement Riemann-Stieltjes (RRS) sense: 
if for any $\varepsilon>0$ there exists a partition $\pi^\varepsilon_{[0,1]}$ such that for any refinement $\pi_{[0,1]}$ of $\pi^\varepsilon_{[0,1]}$,  $|\sum_{s_i\in \pi_{[0,1]}}\Xi_{s_i,s_{i-1}}-K|\leq \varepsilon$.
\end{enumerate}
\end{definition}

\noindent  For $\XX\in D^{p}([0,1],G^{[p]}(\Rset^{d}))$, $(s,t)\in \Delta_1$, set   $X_{s,t}:=:\pi_1(\XX_{s,t})$ and $\X^{(2)}_{s,t}:=\pi_2(\XX_{s,t})$ if $p\in[2,3)$.




\begin{proposition}\label{prop:young}(Young integration, \textit{Proposition} 2.4 in~\cite{FZ:17}).
       Fix $p\in [1,2)$ and let $\XX\in D^{p}([0,1],G^{1}(\Rset^{d}))$ and $Y\in D^{p'}([0,1],\mathcal{L}(\Rset^d,\Rset^m))$, for some $p'$ such that $\frac{1}{p}+\frac{1}{p'}>1$. Then, for all $t\in [0,1]$, the limit
     \begin{align}\label{3eq: Young integral}
         \int_0^tY_{s^-}d\XX_s:=\lim_{(MRS)|\pi_{[0,t]}|\rightarrow0}\sum_{s_i\in \pi_{[0,t]}} Y_{s_i}X_{s_i,s_{i+1}}
     \end{align}
     exists. Moreover,
    $\int_0^\cdot Y_{s^-}d\XX_s\in D^{p}([0,1],\Rset^{m})$. We call the limit in~\eqref{3eq: Young integral} the \textit{Young integral} of $Y$ with respect to $\XX$.


\end{proposition}






Recall from Definition \ref{3def: controlled path qr} that for $p\in [2,3)$, $\XX\in D^{p}([0,1],G^{2}(\Rset^{d}))$, $p'\geq p$ such that $  \frac{2}{p}+\frac{1}{p'}>1$,  and $r\geq 1$ given by $ \frac{1}{r}=\frac{1}{p}+\frac{1}{p'},$  $\mathcal{V}^{p',r}_{\XX}$ denotes the space of controlled rough paths with respect to $X=\pi_1(\XX)$.



\begin{proposition}\label{3prop: rough integral}(Level 2 rough integration, \textit{Proposition} 2.4 in~\cite{ALP:23})
     Let $\XX\in D^{p}([0,1],G^{2}(\Rset^{d}))$ and $(Y,Y')\in \mathcal{V}^{p',r}_{\XX}$, for some $p'\geq p$ such that $\frac{2}{p}+\frac{1}{p'}>1$ and $r\geq 1$ given by $ \frac{1}{r}=\frac{1}{p}+\frac{1}{p'}$ . Then, for all $t\in [0,1]$, the limit
     \begin{align}\label{3eq: rough integral}
         \int_0^tY_{s^-}d\XX_s:=\lim_{(MRS)|\pi_{[0,t]}|\rightarrow0}\sum_{s_i\in \pi_{[0,t]}}\big( Y_{s_i}X_{s_i,s_{i+1}}+Y'_{s_i}\X_{s_i,s_{i+1}}^{(2)}\big),
     \end{align}
     exists. Moreover,  $(\int_0^\cdot Y_{s^-}d\wXX_s,Y)\in \mathcal{V}^{p',r}_{\wXX}$.  We call the limit in~\eqref{3eq: rough integral} the \textit{rough integral} of $(Y,Y')$ with respect to $\XX$.
\end{proposition}

\begin{notation}
    Throughout the paper, whenever the involved paths are continuous, we write $\int_0^\cdot Y_sd\XX_s$ in~\eqref{3eq: Young integral} or~\eqref{3eq: rough integral}.
\end{notation}












Fix $X\in D^1([0,1],G^1(\Rset^d))$, and for all $t\in [0,1]$ let
\begin{align}\label{eq: lift young integral}
  \XX_t:=\left (1,X_t-X_0,\int_0^tX_{0,s^-}\otimes dX_{s}+\frac{1}{2}\sum_{0< s \leq t}(\Delta X_s)^{\otimes 2}\right ),
\end{align}
where  $\int_0^\cdot X_{0,s^-}\otimes dX_s$ denotes the 
Young integral of $X_{0,\cdot}$ with respect to $X$. By Proposition \ref{prop:young} and the geometric properties of the Young integral (e.g., Proposition 2.4 in~\cite{FZ:17}), $\XX\in D^1([0,1],G^2(\Rset^d))$. Since for any $p>1$, $D^1([0,1],G^2(\Rset^d))\subseteq D^p([0,1],G^2(\Rset^d))$, $\XX$ can be interpreted as a weakly geometric \cadlag $p$-rough path, for any $p\in [2,3)$.





\begin{lemma}\label{lemma: consistency}
	Let  
 $\XX$ be defined as in equation~\eqref{eq: lift young integral}, for some $X\in D^1([0,1],G^1(\Rset^d))$, and let $ (Y,Y')\in \mathcal{V}^{p',r}_{\wXX},$  with $p'>p$, for some $p\in[2,3)$ such that $\frac{1}{p'}+\frac{2}{p}>1$. Then, 
 \begin{align}\label{eq: Rough = Marcus}
     \int_0^tY_{s^-}d\mathbf{X}_s=\int_0^tY_{s^-}d{X}_s+\frac{1}{2}\sum_{0<s\leq t}Y_{s^-}'(\Delta X_s)^{\otimes 2},
 \end{align}
 where the integral on the LHS denotes the rough integral of $(Y,Y')$ with respect to $\XX$, while the integrals on the RHS are Young integrals of $Y$ with respect to $X$, and $Y'$ with respect to the path $[0,1]\ni t\mapsto \sum_{0<s\leq t}(\Delta X_s)^{\otimes 2}$, respectively.
\end{lemma}
\begin{proof}
Notice that the path $[0,1]\ni t\mapsto \sum_{0<s\leq t}(\Delta X_s)^{\otimes 2}$ is of finite variation, implying that the second integral on the RHS of equation~\eqref{eq: Rough = Marcus} is well defined. Next, set for all $(s,t)\in \Delta_1$, $ \Y_{s,t}:=\int_s^tX_{s,r^-}\otimes dX_r$
and fix $u\in (0,1]$. By the definitions of rough and Young integral (see equations~\eqref{3eq: rough integral},~\eqref{3eq: Young integral}, respectively),
we need to show that
\[
\lim_{(MRS) |\pi_{[0,u]}|\rightarrow0}\sum_{s_{i}\in \pi_{[0,u]}}Y'_{s_i}\Y_{s_{i},s_{i+1}}=0.
\]
The claim follows by a similar reasoning as in  Theorem~35 of ~\cite{FS:17}.
\end{proof}





























\subsection{Paths of finite quadratic variation in the sense of Föllmer}
In this section, we briefly revisit the concept of path of finite quadratic variation in the sense of~\cite{F:81}.   

\begin{definition}\label{3def: quadratic variation}
   Let $\mathcal{B}([0,1])$ denote the Borel $\sigma$-algebra on $[0,1]$. Let $X\in D([0,1],\Rset)$ and $\pi^n_{[0,1]}$, $n\in \N$, a sequence of partitions with vanishing mesh size. We say that $X$ has finite \textit{quadratic variation along} $(\pi^n_{[0,1]})_{n\in\Nset} $ \textit{in the sense of \Follmer} if the sequence of measures $(\nu_n)_{n\in\N}$ on $([0,1],\mathcal{B}([0,1])$ defined by
    \begin{align*}
        \nu_n:=\sum_{s^n_i\in \pi^n_{[0,1]}}\|X_{s^n_i,s^n_{i+1}}\|\delta_{s^n_i}
    \end{align*}
    converges weakly to a measure $\nu$ such that the map
    \begin{align}\label{3eq: jumps quadratic variation}
       [0,1]\ni  t\mapsto [X]_t^c:=\nu([0,t])-\sum_{0<s\leq t}\|\Delta X_s\|^2
    \end{align}
    is continuous and increasing.  We then call the function $[X]^c$ and the function $[X]$ given by $[X]_t:=\nu([0,t])$ the \textit{continuous quadratic variation} and \textit{quadratic variation} of $X$ along $(\pi^n_{[0,1]})_{n\in\Nset}$, respectively. We say that a path $X\in D([0,1],\Rset^d)$, $d\geq1$, has finite quadratic variation along $(\pi^n_{[0,1]})_{n\in\Nset}$ if for all $i,j\in \{1,\dots,d\}$, the condition above holds for $X^i$ and $X^i+X^j$. In this case, we set
    \begin{align*}
        [X^i,X^j]:=\frac{1}{2}([X^i+X^j]-[X^i]-[X^j]),
    \end{align*}
 and similarly for $[X^i,X^j]^c$.
\end{definition}
\begin{remark}\label{3rem: quadratic variation}
  Notice that for all $i,j\in \{1,\dots,d\}$, $[X^i,X^j]=[X^j,X^i]$ and the map $[0,1]\ni t\mapsto [X,X]_t\in (\Rset^d)^{\otimes 2}$ is a \cadlag path of finite $1$-variation. Thus, for any $Z\in D([0,1],\mathcal{L}((\Rset^d)^{\otimes 2},\Rset^m))$, $m\in \Nset$, the Young integral of $Z$ with respect to $[X,X]$  is well defined. 
  \end{remark}
 A similar argument as in the proof of Théorème in~\cite{F:81} yields the following result. 

  \begin{proposition}
      Let $Z\in D([0,1],\mathcal{L}((\Rset^d)^{\otimes 2},\Rset^m))$, $m\in \Nset$ and $X\in D([0,1],\Rset)$ be a path of finite
quadratic variation along some sequence of partition $(\pi^n_{[0,1]})_{n\in\Nset} $ in the sense of \Follmer. Assume that 
    \begin{align*}
         \{s\in (0,1] \ \colon \ \Delta Z_s\neq 0\}\subseteq  \{s\in (0,1] \ \colon \ \Delta X_s\neq 0\}.
    \end{align*}
    Then, for all $t\in (0,1]$, 
    \begin{align}\label{3eq: integral qv=Young}
    \lim_{n\rightarrow\infty}\sum_{s^n_i\in \pi^n_{[0,1]} }Z_{s^n_i}X^{\otimes 2}_{s^n_i\wedge t ,s^n_{i+1}\wedge t}=\int_0^t Z_{s^-} d[X,X]_s,
    \end{align}
    where the intergral on the right-hand side is a Young integral.
    \end{proposition}

\begin{remark}
    In view of~\eqref{3eq: jumps quadratic variation},
\begin{align*}
    \int_0^t Z_{s^-} d[X,X]_s=\int_0^t Z_{s^-} d[X,X]^c_s+\sum_{0<s\leq t} Z_{s^-} \Delta X_s^{\otimes 2}.
\end{align*}
We refer also to Lemma 5.11 in~\cite{FH:14} for a proof of the equality~\eqref{3eq: integral qv=Young} when $X$ is continuous, and Lemma 2.6 in~\cite{H:17} when $X$ is \cadlag and $Z=f(X)$, for some suitably chosen $\R^m$-valued function $f$.
\end{remark} 


















\subsection{Paths satisfying (RIE) property}
Another line of research that lies between rough and Föllmer integration theory  exploits the so-called RIE property of a path with a given sequence of partition (see \cite{PP:16} and~\cite{ALP:23}). 

\begin{definition}
    A sequence of partitions $(\pi^n_{[0,1]})_{n\in\Nset}$  is called
nested if $\pi^n_{[0,1]}\subseteq \pi^{n+1}_{[0,1]}$ for all $n\in\Nset$.
\end{definition}

\begin{property}[RIE]\label{3property RIE}
Let $p\in (2,3)$ and $(\pi^n_{[0,1]})_{n\in\Nset}$ a sequence of nested partitions with vanishing mesh size. For $X\in D([0,1],\Rset^d)$, define $X^n:[0,1]\rightarrow\Rset^d$ by 
\begin{align*}
    X^n_u:=X_1 1_{\{u=1\}}+\sum_{s^n_i\in \pi^n_{[0,1]}}X_{s^n_i}1_{\{s^n_{i}\leq u<s^n_{i+1}\}},
\end{align*}
for all $u\in [0,1]$, $n\in\Nset$. Assume that 
\begin{enumerate}
    \item The sequence $(X^n)_{n\in\N}$ converges uniformly to $X$ as $n\rightarrow\infty$.
    \item The Riemann sums
    \begin{align}\label{riem sums rie}
        \int_0^tX^n_{u^-}dX_u:=\sum_{s^n_i\in \pi^n_{[0,1]}}X_{s^n_i}X_{s^n_i\wedge t, s^n_{i+1}\wedge t}
    \end{align}
    converges uniformly as $n\rightarrow\infty$ to a limit denoted by $\int_0^tX_{u^-} dX_u$, for all $t\in [0,1]$. 
    \item There exists a control function $w$  such that
    \begin{align}\label{3eq: def RIE iii}
        \sup_{(s,t)\in \Delta_1}\frac{\|X_{s,t}\|^p}{w(s,t)}+\sup_{n\in \N}\sup_{t^n_i<t^n_j\in \pi^n_{[0,1]}}\frac{\|\int_{t^n_i}^{t^n_j}X^n_{u^-}dX_u-X_{t^n_i}X_{t^n_i,t^n_j}\|^p}{w(t^n_i,t^n_j)}\leq 1,
    \end{align}
    with the convention of $\frac{0}{0}:=0$.
\end{enumerate}
\end{property}

\begin{definition}[\cite{ALP:23}]
      A path $X\in D([0,1],\R^d)$ is said to \textit{satisfy} (RIE) with respect to $p\in (2,3)$ and $(\pi^n_{[0,1]})_{n\in\Nset}$ if $p$, $(\pi^n_{[0,1]})_{n\in\Nset}$,  and $X$ together satisfy property (RIE).
\end{definition}


By Proposition 2.18 in~\cite{ALP:23} every path $X\in D([0,1],\R^d)$ that satisfies (RIE) property with respect to some $p\in (2,3)$ and some sequence of nested partition $(\pi^n_{[0,1]})_{n\in\Nset}$  has finite quadratic variation $[X,X]$ along $(\pi^n_{[0,1]})_{n\in\Nset}$ in the sense of Föllmer.

 \begin{proposition}\label{3prop: RIE integal properties}
      Let $p\in (2,3)$, $(\pi^n_{[0,1]})_{n\in\Nset}$ a sequence of nested partition with vanishing mesh size and $X\in D([0,1],\R^d)$  with $X_0=0$ satisfying (RIE) with respect to $p$ and $(\pi^n_{[0,1]})_{n\in\Nset}$. Then, the following conditions are satisfied.
      \begin{enumerate}
          \item \label{i RIE}\label{item RIE 2} For $t\in [0,1]$, take  $\int_0^t X_{u^-}dX_s$ the limit of the Riemann sums $(\int_0^tX^n_{s^-}dX_s)_{n\in \Nset}$  in Property (RIE)~\ref{3property RIE} (ii). For $(s,t)\in \Delta_1$, set $\int_s^t X_{u^-}dX_u:=\int_0^tX_{u^-}dX_u-\int_0^sX_{u^-}dX_u$, and define
    \begin{align*}
        \X^{(2)}_{s,t}:=\int_s^t X_{u^-}dX_u-X_sX_{s,t}+\frac{1}{2}[X,X]_{s,t},    \end{align*}
        and $\XX_t:=(1,X_t,  \X^{(2)}_{0,t})$. Then, $\XX\in D^p([0,1],G^2(\Rset^{d}))$.

   \item\label{item RIE 3}  Let $(Y,Y')\in \mathcal{V}^{q,r}_{\XX}$, for some $q\geq p$. Assume that 
          \begin{align*}
              &\{s\in (0,1] \ \colon \ \Delta Y_s\neq 0\}\subseteq \bigcup_{n\in \N}\pi^n_{[0,1]}, \quad \{s\in (0,1] \ \colon \ \Delta Y'_s\neq 0\}\subseteq  \{s\in (0,1] \ \colon \ \Delta X_s\neq 0\}.
          \end{align*}
          Then, for all $t\in [0,1]$, 
            \begin{align}\label{3eq: limit rough integral RIE}
              \int_0^t Y_{s^-}d\XX_s= \int_0^t Y_{s^-}dX_s+ \frac{1}{2}\int_0^t Y'_{s^-}d[X,X]_s,
          \end{align}
          where $  \int_0^t Y_{s^-} dX_s:= \lim_{n\rightarrow\infty }\sum_{s^n_i\in \pi^n_{[0,1]}}Y_{s^n_i} X_{s^n_i\wedge t, s^n_{i+1}\wedge t},$
is a well defined limit along the sequence of partition $(\pi^n_{[0,1]})_{n\in\Nset}$.
      \end{enumerate}
\end{proposition}

\begin{proof}


~\ref{item RIE 2}:  By Proposition 2.18 in~\cite{ALP:23} (in 
 particular equation (2.14)),  it holds that $\XX\in D([0,1],G^2(\Rset^{d}))$. Moreover, $\XX$ has finite $p$-variation by Lemma 2.13 in~\cite{ALP:23} and  Remark~\ref{3rem: quadratic variation}. 

~\ref{item RIE 3}: It follows by the definition of the rough integral with respect to $\XX$ (see equation~\eqref{3eq: rough integral}), Theorem 2.15 in~\cite{ALP:23}, and Remark~\ref{3rem: quadratic variation}.

\end{proof}
























