\subsection{Positive divisors associated with \texorpdfstring{$\slalg_{r+1}$}{sl3} Parafermions}
\label{subsec: parafermions and sl3}
For this section, let $r\geq1$ be any integer and let $\mathcal{S}_r(k)$ be the subring of the fusion ring of $K(\slalg_{r+1},k)$ generated by the simple modules comprising the set
\(
\{M^{0,0-a_{\bullet}}\mid a_{\bullet}=(a_1,\ldots,a_r)\in\{0,1,\ldots,k-1\}^{\oplus r}\}.
\)
Section~\ref{subsec: Ar rank and cw} introduces the rank formulas for the coinvariant bundles and the conformal weights of simple modules in $\mathcal{S}_r(k)$. We study the positivity of $\mathcal{S}_2(k)$ in Section~\ref{subsec: A2 positivity}, and extend the analysis to all $\mathcal{S}_r(k)$ with $r \geq 3$ in Section~\ref{subsec: Ar positivity}.

\subsubsection{Rank formula and conformal weights}
\label{subsec: Ar rank and cw}
\begin{proposition}
\label{prop: rank sl3}
Given any tuple $a_{\bullet},b_{\bullet},c_{\bullet},d_{\bullet}\in \{0,1,\ldots,k-1\}^{\oplus r}$, we have
\[
\text{rank }\mathbb{V}_{0,4}(K(\slalg_{r+1},k);M^{0,0-a_{\bullet}}\otimes M^{0,0-b_{\bullet}}\otimes M^{0,0-c_{\bullet}}\otimes M^{0,0-d_{\bullet}})
=\begin{cases}
1&\text{ if } a_{\bullet}+b_{\bullet}+c_{\bullet}+d_{\bullet}=x_{\bullet}k\\
0&\text{ else,}
\end{cases}
\]
where $x_{\bullet}=(x_1,\dots,x_r)\in\{1,2,3\}^{\oplus r}$.
\end{proposition}
\begin{proof}
The fusion rule for simple modules in $\mathcal{S}_r(k)$ is given as follows:
\[
M^{0,0-a_{\bullet}}\boxtimes M^{0,0-b_{\bullet}} = M^{0,0-\overline{a_{\bullet}+b_{\bullet}}},
\]
where $\overline{a_{\bullet}}:=(a_1\mod k,\ldots,a_r\mod k)$. Therefore, the dual of $M^{0,0-a_{\bullet}}$ is $M^{0,0-(k-a_{\bullet})}$ and the rank is 
\[
\sum_{t_{\bullet}}\mu(M^{0,0-a_{\bullet}}\otimes M^{0,0-b_{\bullet}}\otimes M^{0,0-t_{\bullet}})\mu(M^{0,0-a_{\bullet}}\otimes M^{0,0-b_{\bullet}}\otimes M^{0,0-(k-t_{\bullet})}).
\]
For the sum to be nonzero, we need $t_i=a_i+b_i\mod k$ and $k-t_i=c_i+d_i\mod k$, that is, $a_i+b_i+c_i+d_i=0\mod k$ for each $1\leq i\leq r$. Given $a_i+b_i+c_i+d_i=0\mod k$ for each $i$, there is a unique $t_{\bullet}$ for which the corresponding summand is nonzero. Hence, the rank is either zero or one.
\end{proof}
To understand the positivity of the subrings $\mathcal{S}_r$, we first need to understand the conformal weights. 
\begin{proposition}
\label{prop: slr cw}
Given $a_{\bullet}=(a_1,\ldots,a_r)\in\{0,1,\ldots,k-1\}^{\oplus r}$, conformal weight of $M^{0,0-a_{\bullet}}$ is 
\[
a_s-\frac{1}{k}\left(\sum_{i=1}^r a^2_i-\sum_{1\leq i<j\leq r}a_ia_j\right).
\]
with $s:=\min\{1\leq i\leq r\mid a_i=\max_{1\leq j\leq r}a_j\}$.
\end{proposition}
\begin{proof}
Since $M^{0,0-a_{\bullet}}\cong M^{k\Lambda_s,k\Lambda_s-a_{\bullet}}$ with the integer $s$ defined as above, it follows from Proposition~\ref{prop: slr cw}.
\end{proof}
\begin{remark}\label{rem: conformal weight}
The conformal weight is $Sym{(n-1)}$-invariant fixing $s$. Moreover, if there are two indices $s$ and $s'$ so that $a_{s}=a_{s'}$, then 
\[
a_s-\frac{1}{k}\left(\sum_{i=1}^r a^2_i-\sum_{1\leq i<j\leq r}a_ia_j\right)=a_{s'}-\frac{1}{k}\left(\sum_{i=1}^r a^2_i-\sum_{1\leq i<j\leq r}a_ia_j\right).
\]
Moreover, given any tuple $a_{\bullet}=(a_1,\ldots,a_r)$, denoting $\sigma\in S_r$ so that $b_i:=a_{\sigma(j)}$ with $b_1\leq\cdots\leq b_r$, we have 
\[
\text{ conformal weight of }M^{0,0-a_{\bullet}}
=\text{ conformal weight of }M^{0,0-b_{\bullet}},
\]
as we do not record the index of $a_{\bullet}$ which achieves the maximum $\max_{1\leq i\leq r}a_i$ but only the maximum itself for $a_s$ and the rest of the formula is $Sym(r)$-invariant.

For any $a_{\bullet},b_{\bullet},c_{\bullet},d_{\bullet}\in \{0,1,\ldots,k-1\}^{\oplus r}$, we can assume each of the tuple are a non-decreasing order of integers. Moreover, we may assume that $a_1\geq b_1\geq c_1\geq d_1$ while calculating degree of $c_1\mathbb{V}_{0,4}(K(\slalg_{r+1},k);M^{0,0-a_{\bullet}}\otimes M^{0,0-b_{\bullet}}\otimes M^{0,0-c_{\bullet}}\otimes M^{0,0-d_{\bullet}})$ because of the obvious symmetry of tensor products.

Finally, if $a_1=0$ for the tuple $a_{\bullet}=(a_1,\ldots,a_r)$, then the conformal weight of the $K(\slalg_{r+1},k)$-module $M^{0,0-a_{\bullet}}$
\[
(\max_{1\leq t\leq r}a_t)-\frac{1}{k}\left(\sum_{i=1}^r a^2_i-\sum_{1\leq i<j\leq r}a_ia_j\right)
=(\max_{1\leq t\leq r}a_t)-\frac{1}{k}\left(\sum_{i=2}^r a^2_i-\sum_{2\leq i<j\leq r}a_ia_j\right)
\]
is equal to the conformal weight of the $K(\slalg_{r},k)$-module $M^{0,0-b_{\bullet}}$ with $b_{\bullet}=(a_2,a_3,\ldots,a_{r})$. 
\end{remark}

\begin{corollary}
\label{cor: max cw for sl3}
Let $r\geq 2$ and $ k\geq 1$ be any integers. The simple module in $\mathcal{S}_2^{sim}(k)$ with maximal conformal weight is $M^{0,0-(\lfloor 2k/3\rfloor,\lfloor k/3\rfloor)}$ and for $\mathcal{S}_{r}^{sim}(k)$ with $r\geq3$ is $M^{0,0-(k-1,\ldots,k-1)}$. The conformal weight of simple modules in $\mathcal{S}_2(k)$ (resp., $\mathcal{S}_{r}(k)$ for all $r\geq3$) is less than or equal to $k/3$ (resp., $\frac{1}{k}(k-1)(k+(k-1)r(r-2))$ ) and all non-trivial simple modules have conformal weight greater than or equal to $(k-1)/k$. 
\end{corollary}
\begin{proof}
This result follows from the proposition above by doing a simple analysis. In particular, the nonzero minimum is achieved at $(\delta_{1j},\delta_{2,j},\ldots,\delta_{rj})$ for any fixed $1\leq j\leq r$. Similarly, for $r=2$, the maximum is achieved at $(2k/3,k/3)$ and for all $r\geq3$ at $(k-1,\ldots,k-1)$.
\end{proof}
\subsubsection{\texorpdfstring{$F$}{F}-positive and positive subrings in the \texorpdfstring{$\slalg_3$}{sl\_3} Parafermion fusion ring}
\label{subsec: A2 positivity}
The reliance on the maximality of the tuple \(a_{\bullet}\) renders the analysis of positivity in the subrings \(\mathcal{S}_r\) highly sensitive to the parameter \(r\). Additionally, the exponential growth of \(|\mathcal{W}_r|\) with respect to \(r\) at any fixed level significantly contributes to the combinatorial complexity (see Remark~\ref{rem: number of modules grow exp}). In this paper, we demonstrate that the subring \(\mathcal{S}_2(k)\) is \(F\)-positive for levels \(k \leq 10\), and moreover, positive for \(k \leq 5\).
\begin{proposition}
\label{prop: F-positive for sl3}
The subring $\mathcal{S}_2(k)$ is $F$-positive for any integer $k\leq 10$.  
\end{proposition}
\begin{proof}
We wish to prove that the divisor $\mathbb{D}$ on $\overline{\mathrm{M}}_{0,4}$ corresponding to simple modules $M^{0,0-(a_1,a_2)}$, $M^{0,0-(b_1,b_2)}$, $M^{0,0-(c_1,c_2)}$, and $M^{0,0-(d_1,d_2)}$ in $\mathcal{S}_2(k)$ has non-negative degree. First, we may assume that $a_1+b_1+c_1+d_1=x_1k$ and $a_2+b_2+c_2+d_2=x_2k$ for some integers $0\leq x_1,x_2\leq 3$ by Proposition~\ref{prop: rank sl3}. If $x_1+x_2=1$, then one of them must be zero, and the question reduces to the $F$-positivity of $\mathcal{S}_1(k)$ by Remark~\ref{rem: conformal weight} and the answer is affirmative (cf. Theorem~\ref{thm: positive for sl2}). The case $x_1=x_2=1$ is discussed in Lemma~\ref{lem: sl3 x1=x2=1}. If $x_1\ne x_2$, we may assume that $x_1\geq x_2$ since $c^{0,0-(a_1,a_2)}=c^{0,0-(a_2,a_1)}$ by Remark~\ref{rem: conformal weight} and twitching $(a_i,b_i)$ to $(b_i,a_i)$ for all four modules does not change the fusion rules. 
The remaining cases are checked via a computer program for level $k\leq 10$ (see \cite{Parafermionsgithub}). 
\end{proof}

\begin{lemma}
\label{lem: sl3 x1=x2=1}
Let $k\geq 1$ be any integer.
Let $M^{0,0-(y_1,y_2)}$, for $y\in\{a,b,c,d\}$, be simple modules in $\mathcal{S}_2(k)$ so that $a_1+b_1+c_1+d_1=a_2+b_2+c_2+d_2= k$. The corresponding coinvariant divisor on $\overline{\mathrm{M}}_{0,4}$ is either trivial or ample.
\end{lemma}
\begin{proof}
Consider simple modules $M^{0,0-(a_1,a_2)}$, $M^{0,0-(b_1,b_2)}$, $M^{0,0-(c_1,c_2)}$ and $M^{0,0-(b_1,b_2)}$ of the $K(\slalg_{3},k)$ parafermions. By Proposition~\ref{prop: rank sl3}, the degree of the associated coinvariant divisor $\mathbb{D}$ on $\overline{\mathrm{M}}_{0,4}$ is given by 
\begin{align}
\deg\mathbb{D} &= c^{0,0-(a_1,a_2)}+c^{0,0-(b_1,b_2)}+c^{0,0-(c_1,c_2)}+c^{0,0-(d_1,d_2)}\nonumber\\
&\qquad-c^{0,0-(\overline{a_1+b_1},\overline{a_2+b_2})}-c^{0,0-(\overline{a_1+c_1},\overline{a_2+c_2})}-c^{0,0-(\overline{a_1+d_1},\overline{a_2+d_2})},
\end{align}
where $\overline{a}$ denotes the residue of $a$ modulo $k$. We do a case-by-case analysis to show that the degree is non-negative.
Explicitly, we show that the degree is strictly positive if and only if one of the following two conditions holds:  
(1) \(\alpha_1 + \beta_1 = k\) and \(\gamma_2 + \delta_2 = k\) for some \(\alpha, \beta, \gamma, \delta \in \{a, b, c, d\}\); or  
(2) \(y_1 \neq y_2\) for all \(y \in \{a, b, c, d\}\), with \(\operatorname{sign}(a_1 - a_2) = \operatorname{sign}(y_1 - y_2)\) for exactly one \(y \in \{b, c, d\}\), and \(\operatorname{sign}(a_1 - a_2) = -\operatorname{sign}(z_1 - z_2)\) for all \(z \in \{b, c, d\} \setminus \{y\}\). In all other cases, the degree is zero. We define \(x_i := a_i + b_i + c_i + d_i\) for \(i = 1, 2\).

\begin{enumerate}[(\text{Case }1)]
    \item $\ga_1+\gb_1=k$ and $\gamma_2+\delta_2=k$ for some $\ga,\gb,\gamma,\delta\in\{a,b,c,d\}$: If $\{\ga,\gb,\gamma,\delta\}\ne\{a,b,c,d\}$, then we get the trivial divisor. To see why, assume that $d\notin\{\ga,\gb,\gamma,\delta\}$ and then $M^{0,0-(d_1,d_2)}=M^{0,0-(0,0)}$. So, it is safe to assume that $a_1+b_1=k=c_2+d_2$ with all four integers non-negative. Then the degree is:
    \begin{align*}
    \deg\mathbb{D} &= a_1-\frac{a_1^2}{k}+b_1-\frac{b_1^2}{k}+c_2-\frac{c_2^2}{k}+d_2-\frac{d_2^2}{k}-c^{0,0-(0,0)}-c^{0,0-(a_1,c_2)}-c^{0,0-(a_1,d_2)}\\
    % &=2k-\frac{a_1^2+b_1^2+c_2^2+d_2^2}{k}-\max(a_1,c_2)-\max(a_1,d_2)+\frac{2a_1^2+c_2^2+d_2^2-a_1c_2-a_1d_2}{k}\\
    % &=2k-a_1-\max(a_1,c_2)-\max(a_1,d_2)+\frac{a_1^2-b_1^2}{k}\\
    % &=k+a_1+b_1-a_1+\frac{k(a_1-b_1)}{k}-\max(a_1,c_2)-\max(a_1,d_2)\\
    &=k+a_1-\max(a_1,c_2)-\max(a_1,d_2)\\
    &=\begin{cases}
    b_1&\text{ if } c_2,d_2\leq a_1\\
    a_1 &\text{ if } c_2,d_2\geq a_1\\
    \min(c_2,d_2)&\text{ else.}
    \end{cases}
    \end{align*}
\item Assume that $y_i+z_i<k$ for all off-diagonal terms $(y,z)\in\{a,b,c,d\}^{\times 2}$ and all $i=1,2$: The degree is:
    \begin{align*}
    \deg\mathbb{D} 
    % &= c^{0,0-(a_1,a_2)}+c^{0,0-(b_1,b_2)}-c^{0,0-(c_1,c_2)}-c^{0,0-(d_1,d_2)}\\
    % &\qquad-c^{0,0-(a_1+b_1,a_2+b_2)}+c^{0,0-(a_1+c_1,a_2+c_2)}+c^{0,0-(a_1+d_1,a_2+d_2)}\\
    % &=\max(a_1,a_2)+\max(b_1,b_2)+\max(c_1,c_2)+\max(d_1,d_2)\\ &-\max(a_1+b_1,a_2+b_2)-\max(a_1+c_1,a_2+c_2)-\max(a_1+d_1,a_2+d_2)\\
    % &+\frac{1}{k}\left(\sum_{y\in\{b,c,d\}}(a_1+y_1)^2+(a_2+y_2)^2-(a_1+y_1)(a_2+y_2)+\sum_{z\in\{a,b,c,d\}}z_1z_2-z_1^2-z_2^2\right)\\
    &=(a_1+a_2)+\max(a_1,a_2)+\max(b_1,b_2)+\max(c_1,c_2)+\max(d_1,d_2)\\ &-\max(a_1+b_1,a_2+b_2)-\max(a_1+c_1,a_2+c_2)-\max(a_1+d_1,a_2+d_2).
    \end{align*}
    We work on sub-cases:
    \begin{itemize}
    \item ($y_1=y_2=y$ for all $y\in\{a,b,c,d\}$) The degree is $2a+k-3a-(k-a)=0$.
    \item ($y_1=y_2$ for three elements in $\{a,b,c,d\}$) Since $x_1=x_2$, this case reduces to the previous one. 
    \item ($y_1=y_2$ for any two elements in $\{a,b,c,d\}$) By symmetry, we may assume that $c_1=c_2=c$, $d_1=d_2=d$, $a_1>a_2$ and $b_1<b_2$. Then, the degree is $a_1+a_2+a_1+b_2+c+d-\max(a_1+b_1,a_2+b_2)-a_1-c-a_1-d=a_2+b_2-\max(a_1+b_1,a_2+b_2)=(k-c-d)-\max(k-c-d,k-c-d)=0.$
    \item ($y_1=y_2$ for exactly one element in $\{a,b,c,d\}$) Assume that $d_1=d_2=d$. We have cases:
    \begin{itemize}
        \item $a_1>a_2,b_1>b_2,c_1<c_2$: The degree is $a_1+a_2+a_1+b_1+c_2+d-(a_1+b_1)-\max(a_1+c_1,a_2+c_2)-(a_1+d)=a_2+c_2-\max(a_1+c_1,a_2+c_2)$. Note that $c_2-c_1=(a_1-a_2)+(b_1+b_2)>(a_1-a_2)$ and therefore, $\max(a_1+c_1,a_2+c_2)=a_2+c_2$ and the degree is zero. 
        \item Any other case reduces to the case above by symmetry. For example, the case $a_1>a_2, c_1>c_2, b_1<b_2$ reduces to the previous case since any coinvariant divisor $\mathbb{D}_{0,4}(V,M^{1}\otimes\cdots\otimes M^4)$ is invariant under the action of $Sym(4)$ on the indices of modules $M^i$. 
        \item The reverse case of $a_1<a_2,b_1<b_2,c_1>c_2$ reduces to the first case since $c^{0-(a_1,a_2)}=c^{0-(a_2,a_1)}$ and the fusion rule remains the same if we switch the tuples for all four modules in consideration. 
    \end{itemize}
    \item ($y_1\ne y_2$ for all $y$ in $\{a,b,c,d\}$) We again break into cases:
    \begin{itemize}
        \item ($a_1>a_2,b_1>b_2,c_1<c_2,d_1<d_2$): 
        % The degree is $a_1+a_2+a_1+b_1+c_2+d_2-a_1-b_1-\max(a_1+c_1,a_2+c_2)-\max(a_1+d_1,a_2+d_2)=a_1+a_2+c_2+d_2-\max(a_1+c_1,a_2+c_2)-\max(a_1+d_1,a_2+d_2)$. 
        The degree is 
        \[
        \deg\mathbb{D}=\begin{cases}
        b_1-b_2 &\text{ if } a_1+c_1\geq a_2+c_2,a_1+d_1\geq a_2+d_2\\
        a_1-a_2 &\text{ if } a_1+c_1\leq a_2+c_2,a_1+d_1\leq a_2+d_2\\
        c_2-c_1 &\text{ if } a_1+c_1\geq a_2+c_2,a_1+d_1\leq a_2+d_2\\
        d_2-d_1 &\text{ if } a_1+c_1\leq a_2+c_2,a_1+d_1\geq a_2+d_2.
        \end{cases}
        \]
        \item ($a_1>a_2,b_1>b_2,c_1>c_2,d_2<d_2$): 
        % The degree is $a_1+a_2+a_1+b_1+c_1+d_2-a_1-b_1-a_1-c_1-\max(a_1+d_1,a_2+d_2)=a_2+d_2-\max(a_1+d_1,a_2+d_2)$.
        The degree is $a_2+d_2-\max(a_1+d_1,a_2+d_2)$.
        Since $d_2-d_1=(a_1-a_2)+(b_1-b_2)+(c_1-c_2)<a_1-a_2$, the degree is zero. 
        \item Symmetries available to us reduce all cases to the one above. For example, the case $(a_1>a_2,b_1<b_2,c_1<c_2,d_1<d_2)$ reduces to the first case above by first switching $(y_1,y_2)$ to  $(y_2,y_1)$ for all $y\in\{a,b,c,d\}$ and then applying $(1,4)\in Sym(4)$ to the divisor. 
    \end{itemize}
    \end{itemize}
    \end{enumerate}
\end{proof}
\begin{corollary}
\label{cor: sl3 maximal cw nef result}
Let $1\leq k\leq 10$ be any integer. The symmetric coinvariant divisor corresponding to the simple $K(\slalg_3,k)$-module $M^{0,0-(\lfloor 2k/3\rfloor,\lfloor k/3\rfloor)}$ is nef. 
\end{corollary}
\begin{proof}
Since the module $M^{0,0-(\lfloor 2k/3\rfloor,\lfloor k/3\rfloor)}$ has maximal conformal weight, the result follows from Theorem~\ref{thm: intro1.ii}.
\end{proof}
\begin{theorem}
\label{thm: positive for sl3}
The subring $\mathcal{S}_2(k)$ is positive for any positive integer $k\leq 5$.  
\end{theorem}
\begin{proof}
If $k=1$, then the only module we need to consider is $M^{0,0}$, and the divisor is trivial as it trivially intersects all F-curves. 
For any integer $k\geq2$, consider $n$ many modules $M^{0,0-(a_i,b_i)}$, for integers $1\leq i\leq n$, with $0\leq a_i,b_i\leq k-1$ so that $\sum_i a_i = \sum_i b_i=0\mod k$. By Theorem~\ref{thm: POV}, we can assume that none of the $n$ modules are trivial. 

Then, $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_3,k);\otimes M^{0,0-(a_i,b_i)})$ can written as 
\[
\mathbb{D}=\sum_{j=1}^nc^{0,0-(a_j,b_j)}\psi_j-\sum_{\substack{I\s[n]\\2\leq |I|\leq n/2}} b_{0,I}\delta_{0,I},\text{ where}
\] 
\begin{align*}
b_{0,I} 
&= \sum_{W\in \mathcal{S}_2(k)} c^W\ \text{rank}\mathbb{V}_{0,|I|+1}(K(\slalg_3,k);\otimes_{i\in I} M^{0,0-(a_i,b_i)}\otimes W)\ \text{rank}\mathbb{V}_{0,|I^c|+1}(K(\slalg_3,k);\otimes_{i\notin I} M^{0,0-(a_i,b_i)}\otimes W')\\
&\leq f_{\max} \text{rank}\mathbb{V}_{0,n}(K(\slalg_3,k);\otimes_{i\in [n]} M^{0,0-(a_i,b_i)}) = f_{\max}.
\end{align*}
Note that 
$\sum_{j=1}^nc^{0,0-(a_j,b_j)}\psi_j \geq f_{\min}\psi.
$
% \begin{align*}
% \sum_{j=1}^nc^{0,0-(a_j,b_j)}\psi_j \geq f_{\min}\psi.
% % =f_{\min}\sum_{\substack{I\s[n]\\ 2\leq |I|\leq n/2}}\frac{|I|(n-|I|)}{n-1}\delta_{0,I}.
% \end{align*}
Since $K:=K_{\overline{\mathrm{M}}_{0,n}}=\psi-2\Delta$, for any $c\in\qq_{\geq0}$
\begin{align*}
\frac{1}{f_{\min}}(\mathbb{D}-cK)&\geq (1-\frac{c}{f_{\min}})\psi +\frac{2c-f_{\max}}{f_{\min}}\Delta.
\end{align*}
In order to conclude that $\mathbb{D}$ is nef from Theorem~\ref{thm: intro1.i}, it remains to find some $c$ so that $\frac{f_{\max}}{2}\leq c\leq f_{\min}$. From Proposition~\ref{prop: slr cw}, we know that $\frac{k-1}{k}=f_{\min}\leq c^{0,-(a_i,b_i)}\leq f_{\max}\leq \frac{k}{3}$. Therefore, we need $\frac{k^2}{3(k-1)}\leq 2$, which is true for $k\leq 4$. For $k=5$, an explicit calculation yields $f_{\max}=8/5$ and $f_{\min}=4/5$, that is, $f_{\max}/f_{\min}=2$.
\end{proof}
\begin{remark}
In Proposition~\ref{prop: non F-positive}
, we show that $\mathbb{D}^{r,1}_{0,km}:=\mathbb{D}_{0,km}(K(\slalg_{r+1},k),{M^{0,0-(1,\ldots,1)}}^{\otimes km})$ intersects $F$-curves $F_{1,1,kt+k-3}$ strictly negatively for all integers $r\geq3$, $k\geq4$ and $0\leq t\leq m-1$. Given similar methods should work for $r=2$, one may ask why are divisors $\mathbb{D}^{2,1}_{0,4m}$ and $\mathbb{D}^{2,1}_{0,5m}$ nef as indicated by the Theorem above. A simple calculation shows that for any integers $\epsilon\in\{1,\ldots,k-3\}$, $k,m\geq1$ and $0\leq t\leq m-1$, the intersection number
\[
\mathbb{D}^{2,1}_{0,km}\cdot F_{1,1,kt+\epsilon}
= 2 cw(1)+cw(\epsilon)+cw(k-2-\epsilon)-cw(2)-2 cw(\epsilon+1),
\]
where $cw(a):=c^{0,0-(a,a)}=\frac{a(k-a)}{k}$, is equal to zero and the proof of Proposition~\ref{prop: non F-positive} does not apply for $r=2$. 
\end{remark}
\begin{remark}
As seen above, the combinatorial complexity owing to conformal weights limits our understanding of positivity of the subring $\mathcal{S}_2(k)$ for general $k$. However, there is a subring  $\mathcal{S}'_2(k)$ of $\mathcal{S}_2(k)$ that is propositional to $\mathcal{S}_1(k)$ and therefore, all coinvariant divisors with representations in  $\mathcal{S}'_2(k)$ are again nef by Theorems~\ref{thm: intro1.iii} and~\ref{thm: positive for sl2}. The subring $\mathcal{S}'_2(k)$ is defined as 
\[
\mathcal{S}'_2(k):=\langle M^{0,0-(a,a)}\mid 0\leq a\leq k-1\rangle,
\]
and the isomorphism of rings $f:\mathcal{S}'_2(k)\to \mathcal{S}_1(k): M^{0,0-(a,a)}\mapsto M^{k,a}$ gives proportionality since $cw(M^{0,0-(a,a)})=a-\frac{a^2}{k}=cw(M^{k,a})$. One checks that $M^{0,0-a}\cong M^{k,a}$. However, the generalized map $f:\mathcal{S}'_{r}(k)\to\mathcal{S}_{r-1}(k):M^{0,0-(a,\ldots,a)}\mapsto M^{0,0-(a,\ldots,a)}$ is an injection but does not satisfy proportionality, since 
\[
cw(M^{0,0-(a,\ldots,a)})-
cw(f(M^{0,0-(a,\ldots,a)}))
=a+\frac{a^2r}{2k}(r-3)-a+\frac{a^2(r-1)}{2k}(r-4)=\frac{2a^2}{k}(r-2).
\]
\end{remark}
\begin{question}
The remark shows that all coinvariant divisors with representations in a subring of $\mathcal{S}_2(k)$ are nef for all level $k\geq 1$. Is it true that $\mathcal{S}_2(k)$ is positive for all level $k\geq 6$?    
\end{question}
\begin{corollary}
\label{cor: lambda twisted nef classes for sl3} Let $1\leq k\leq 5$ and $g,n\geq0$ be any integers. There is a rational number $q\geq0$ so that the divisor $(q'\lambda+\mathbb{D})$ is nef for all $q'\in\qq_{\geq q}$ and any coinvariant divisor $\mathbb{D}$ on $\overline{\mathrm{M}}_{g,n}$ with modules in $\mathcal{S}_2(k)$.
\end{corollary}
\begin{proof}
It follows directly from Proposition~\ref{prop: lambda twist nef high higher genus} and Theorem~\ref{thm: positive for sl3}.
\end{proof}


\subsubsection{Symmetric coinvariant divisors associated to \texorpdfstring{$\slalg_3$}{sl\_3} Parafermions}
\label{sec: symm sl3 para}
Given that the subrings $\mathcal{S}_2(k)$ are positive for integers $1\leq k\leq 5$, it is natural to ask if the coinvariant divisors they define are ample. It is difficult to study such notions for an arbitrary coinvariant divisor owing to complexity of the conformal weights. In this subsection, we answer this question of all symmetric coinvariant divisors $\mathbb{D}_{0,n}(K(\slalg_3,k), M^{\otimes n})$ on $\tilde{M}_{0,n}=\overline{M}_{0,n}/Sym_n$, where $M$ is any simple module in $\mathcal{S}_{2}(k)$. The general approach is to intersect these divisors with $F$-curves $F_{1,1,i}$ for all integers $1\leq i\leq g$, with $n=2g+2$ or $n=2g+3$, as they form a basis of $N_1(\tilde{M}_{0,n})$.
\begin{proposition}
The symmetric divisor $\mathbb{D}_{0,n}(K(\slalg_3,2),M^{\otimes n})$ for a simple module $M\in\mathcal{S}_2(2)$ is trivial if and only if $M$ is the trivial module or $n$ is odd. Otherwise, then the intersection of the divisor with $F$-curves $F_{1,1,i}$ is
\[
\mathbb{D}_{0,n}(K(\slalg_3,2),M^{\otimes n})\cdot F_{1,1,i}=\begin{cases}
    0&\text{ if $i$ is odd}\\
    2&\text{ if $i$ is even}.
\end{cases}
\]
\end{proposition}
\begin{proof}
The subring $\mathcal{S}_2(2)$ is generated by simple modules $M_0:=M^{0,0-(0,0)}, M_1:=M^{0,0-(1,0)}, M_2:=M^{0,0-(0,1)}$, $M_3:=M^{0,0-(1,1)}$, where the conformal weight of $M_0$ is zero and the other three have conformal weight equal to $1/2$. Also, all four simple modules are self dual. Note that the divisor $\mathbb{D}_{0,n}(M_0^{\otimes n})$ is trivial, for any $n\geq1$. Let $M_a$ be any of the other three simple modules. The rank of the bundle $\mathbb{V}_{0,n}(K(\slalg_3,2),M_a^{\otimes n})$ is given by
\[
\mu(M_a^{\otimes n})=\sum_{M_b}\mu(M_a^{\otimes(n-2)}\otimes M_b)\mu(M_a^{\otimes 2}\otimes M_b)=\mu(M^{\otimes(n-2)})=\mu(M^{\otimes(n\mod 2)})=\begin{cases}
1 & \text{$n$ is even}\\
0 & \text{$n$ is odd}.
\end{cases}.
\]
Let $n=2g+2$ be an even integer and let $1\leq i\leq g$ be written as $i=2t+\epsilon$, where $t\geq0$ and $\epsilon\in\{0,1\}$ are integers.
\begin{align*}
\mathbb{D}_{0,n}(K(\slalg_3,2),M_a^{\otimes n})\cdot F_{1,1,2t+\epsilon} 
&=\sum_{x,y}d(M_a^{\otimes2}\otimes M_x\otimes M_y)\mu(M_a^{\otimes 2t+\epsilon}\otimes M_x)\mu(M_a^{\otimes(2g-\epsilon)}\otimes M_y)\\
&=\sum_{x,y}d(M_a^{\otimes2}\otimes M_x\otimes M_y)\mu(M_a^{\otimes \epsilon}\otimes M_x)\mu(M_a^{\otimes\epsilon}\otimes M_y).
\end{align*}
If $\epsilon=0$, then $\mathbb{D}_{0,n}(K(\slalg_3,2),M_a^{\otimes n})\cdot F_{1,1,2t+\epsilon} = d(M_a^{\otimes 2}\otimes M_0^{\otimes 2})=d(M_a^{\otimes 2})=0.$ If $\epsilon=1$, then $\mathbb{D}_{0,n}(K(\slalg_3,2),M_a^{\otimes n})\cdot F_{1,1,2t+\epsilon} = d(M_a^{\otimes 4})=4(1/2)-3(0)=2.$
\end{proof}
\begin{proposition}
The symmetric coinvariant divisor $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_{3},3), M^{\otimes n})$ associated to a non-trivial simple module $M:=M^{0,0-(a,b)}$ is trivial unless $3$ divides $n$. If $3\mid n$, for any integer $0\leq t\leq (2/3)n$  
\[
\mathbb{D}\cdot F_{1,1,3t+\epsilon} = \begin{cases}
3\max(a,b)+ab-a^2-b^2&\text{ if $\epsilon=2$},\\
0&\text{ if $\epsilon=0,1$ }.
\end{cases}
\]\end{proposition}
\begin{proof}
Given a non-trivial simple module $M:=M^{(a,b)}$ in $\mathcal{S}_2(3)$, for a choice of integers $m,t\geq0$ and $\delta,\epsilon\in\{0,1,2\}$,
\[
\mathbb{D}_{0,3m+\delta}(K(\slalg_3,3),M^{\otimes (3m+\delta)})\cdot F_{1,1,3t+\epsilon}
=d({M^{(a,b)}}^{\otimes2}\otimes M^{(\overline{\epsilon a},\overline{\epsilon a})}\otimes M^{((\overline{\delta-\epsilon-2)a},\overline{\delta-\epsilon-2)b}))})
\]
is equal to zero if $\delta\ne0$ or $\epsilon\ne2$. For $\epsilon=2$, the intersection number equals to $(3\cdot cw(M))$. 
