\begin{proposition}
For a simple module $M\in\mathcal{S}_2(4)$, the symmetric divisor $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_3,4),M^{\otimes n})$ if (a) $M$ is the trivial module, (b) $M$ has conformal weight $3/4$, or (c) $n$ is odd. Assume $n$ is even. Then $\mathbb{D}$ is ample if $M$ is self-dual and $M$ is not the trivial module. Finally, $M$ is a simple module with conformal weight $5/4$, then 
\[
\mathbb{D}_{0,n}({M}^{\otimes n})\cdot F_{1,1,i}=\begin{cases}
0 &\text{ if $i$ is even}\\
>0 &\text{ if $i$ is odd}.
\end{cases}
\]
\end{proposition}
\begin{proof}
The subring $\mathcal{S}_2(4)$ is generated by simple modules $M^{(a,b)}:=M^{0,0-(a,b)}$, where $0\leq a,b\leq 3$, partitioned into four subsets based on their conformal weight.  
\[
\mathcal{S}_2(4)^{sim}=c^0\sqcup c^{3/4}\sqcup c^{5/4}\sqcup c^{1}, \text{ with }c^0=\{M^{(0,0)}\},\quad c^{1}=\{M^{(2,0)},M^{(2,2)}\},
\]
\[
c^{3/4}=\{M^{(1,0)}, M^{(3,0)},M^{(1,1)},M^{(3,3)}\}, \quad c^{5/4}=\{M^{(1,2)}, M^{(3,2)},M^{(1,2)},M^{(3,1)},M^{(2,3)},M^{(2,1)}\},
\]
where the conformal weight of any module in $c^x$ equals $x$. If $M^{(a_1,b_1)}$ is self dual then, 
\[
\mu:=\mu(M^{(a_1,b_1)}\otimes M^{(a_1,b_1)}\otimes M^{(a_2,b_2)}\otimes M^{(a_3,b_3)})
\]
is $1$ if and only if (a) $M^{(a_2,b_2)}$ and $M^{(a_3,b_3)}$  are dual to each other, or (b) both modules $M^{(a_2,b_2)}$ and $M^{(a_3,b_3)}$ are self-dual. If $M^{(a_1,b_1)}$ is not self-dual, then $\mu=1$ if and only if $a_2+a_3=2\mod 4$ and $(b_2+b_3)$ is even. Similarly, one calculates that $d:=d(M^{(a_1,b_1)}\otimes M^{(a_1,b_1)}\otimes M^{(a_2,b_2)}\otimes M^{(a_3,b_3)})$ is non-zero if any of the following holds:
\begin{itemize}
\item $M^{(a_1,b_1)}$ is self-dual,
\item $M^{(a_1,b_1)}$ has conformal weight $5/4$, or
\item $M^{(a_1,b_1)}$ has conformal weight $3/4$ and $(a_2,b_2)\ne(a_1,b_1)$.
\end{itemize}
Note that $\mathbb{D}_{0,n}({M^{(0,0)}}^{\otimes n})$ is trivial. If $M^{(a,b)}$ is self-dual and not the trivial module, then 
\[
\mathbb{D}_{0,n}({M^{(a,b)}}^{\otimes n})\cdot F_{1,1,i}=\begin{cases}
0 &\text{ if $n$ is odd}\\
>0 &\text{ if $n$ is even},
\end{cases}
\]
and if $M^{(a,b)}$ is not self-dual, then $\mathbb{D}_{0,n}({M^{(a,b)}}^{\otimes n})$ is trivial for any odd integer $n$ and if $n$ is even, then 
\[
\mathbb{D}_{0,n}({M^{(a,b)}}^{\otimes n})\cdot F_{1,1,i}=\begin{cases}
0 &\text{ if $M^{a,b}\in c^{3/4}$}\\
0 &\text{ if $M^{a,b}\in c^{5/4}$ and $i$ is even}\\
>0 &\text{ if $M^{a,b}\in c^{5/4}$ and $i$ is odd}.
\end{cases}
\]
This completes the proof.
\end{proof}
\begin{proposition}
A symmetric coinvariant divisor $\mathbb{D}^M:=\mathbb{D}_{0,n}(K(\slalg_3,5),M^{\otimes n})$, with a simple module $M\in\mathcal{S}_2(5)\setminus\{0\}$, is trivial if $5$ does not divide $n$. If $n=5m$ for some integer $m\geq1$, then $\mathbb{D}^M$ contracts all $F$-curves other than $F_{1,1,5t+4}$ for all integers $0\leq t\leq m-1$ if the conformal weight of $M$ is equal to $4/5$. All other symmetric divisors contract only curves of type $F_{1,1,5t+3}$ for all integers $0\leq t\leq m-1$.
\end{proposition}
\begin{proof}
Given a non-trivial simple module $M^{(a_1,b_1)}$ in $\mathcal{S}_2(5)$, the intersection of the symmetric divisor $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_3,k),{M^{(a_1,b_1)}}^{\otimes n})$ with the $F$-curves $F_{1,1,i}$ is 
\begin{align*}
\mathbb{D}\cdot F_{1,1,i}
&=\sum d({M^{(a_1,b_1)}}^{\otimes 2}\otimes M^{(a_2,b_2)}\otimes M^{(a_3,b_3)})\mu({M^{(a_1,b_1)}}^{\otimes i}\otimes {M^{(a_2,b_2)}}')\mu({M^{(a_1,b_1)}}^{\otimes (n-2-i)}\otimes {M^{(a_3,b_3)}}').
\end{align*}
Note that the smallest integer $x\geq1$ for which $xa_1=xb_1=0$ modulo $5$ is $x=5$, and therefore, 
\[
\mathbb{D}\cdot F_{1,1,i} 
= d({M^{(a_1,b_1)}}^{\otimes 2}\otimes M^{(\overline{\epsilon a_1},\overline{\epsilon b_1})}\otimes M^{(\overline{(\delta-\epsilon-2)a_1},\overline{(\delta-\epsilon-2)b_1})}),
\]
where $n = 5m+\delta$ and $i=5t+\epsilon$ for some integers $m,t\geq0$, $\delta,\epsilon\in\{0,1,\ldots,4\}$. Calculating rank of the bundle $\mathbb{V}_{0,4}(K(\slalg_3,k),{M^{(a_1,b_1)}}^{\otimes 2}\otimes M^{(\overline{\epsilon a_1},\overline{\epsilon b_1})}\otimes M^{(\overline{(\delta-\epsilon-2)a_1},\overline{(\delta-\epsilon-2)b_1})})$ one sees that $\mathbb{D}\cdot F_{1,1,i}=0$ if $\delta\ne0$.

Let $\delta=0$. Then, $\mathbb{D}\cdot F_{1,1,5t+\epsilon} 
= d({M^{(a_1,b_1)}}^{\otimes 2}\otimes M^{(\overline{\epsilon a_1},\overline{\epsilon b_1})}\otimes M^{(\overline{(-\epsilon-2)a_1},\overline{(-\epsilon-2)b_1})})$ is zero if $\epsilon=0$. In order to calculate the intersections for $\epsilon\geq1$, we need some information about the conformal weight of the modules: The set of simple modules admit a partition 
\[
\mathcal{S}_2(5)^{sim}=c^0\sqcup c^{4/5}\sqcup c^{6/5}\sqcup c^{7/5}\sqcup c^{8/5},
\]
an analysis of the fusion rules among these modules give the following data:
\begin{align*}
\mathbb{D}_{0,n}(K(\slalg_3,5),M^{\otimes 5m})\cdot F_{1,1,5t+1}=\mathbb{D}_{0,n}(K(\slalg_3,5),M^{\otimes 5m})\cdot F_{1,1,5t+2} =\begin{cases}
0 & \text{ if $M\in c^0\sqcup c^{4/5}$}\\
1 & \text{ if $M\in c^{7/5}$}\\
2 & \text{ if $M\in c^{6/5}\sqcup c^{8/5}$},
\end{cases}
\end{align*}
\begin{align*}
\mathbb{D}_{0,n}(K(\slalg_3,5),M^{\otimes 5m})\cdot F_{1,1,5t+3}=0\quad\text{for all $M\in\mathcal{S}_3(5)^{sim}$, and }
\end{align*}
\begin{align*}
\mathbb{D}_{0,n}(K(\slalg_3,5),M^{\otimes 5m})\cdot F_{1,1,5t+4}
=\begin{cases}
0 & \text{ if $M\in c^0$}\\
2 & \text{ if $M\in c^{4/5}$}\\
4 & \text{ if $M\in c^{6/5}\sqcup c^{7/5}$}\\
5 & \text{ if $M\in c^{8/5}$}.
\end{cases}
\end{align*}
This completes the proof.
\end{proof}
