\subsubsection{Coinvariant divisors associated to \texorpdfstring{$\mathfrak{sl}_{r+1}$}{sl\_r+1} Parafermions for \texorpdfstring{$r \geq 3$}{r >= 3}}
\label{subsec: Ar positivity}
We conclude this section by proving that the subrings $\mathcal{S}_r(k)$ are not positive for any integers $r \geq 3$ and $k \geq 4$. The proof is based on exhibiting a subring
\(
\mathcal{S}'_r(k) := \left\langle M^{0,0-(a_1,\ldots,a_r)} \,\middle|\, a_1 = \cdots = a_r = a,\ 0 \leq a \leq r-1 \right\rangle \subset \mathcal{S}_r(k)
\)
that fails to be $F$-positive. For levels $k = 2, 3$, we show that the corresponding symmetric coinvariant divisors are nef and compute their intersection numbers with $F$-curves generating a basis for $N^1(\tilde{\mathrm{M}}_{0,n})$.


\begin{proposition}
\label{prop: non F-positive}
Let $k\geq4$ be any integer. The coinvariant divisors associated to  representations in $\mathcal{S}_r(k)$ are nef if and only if $r \leq 2$.
\end{proposition}
\begin{notation}
Let $M_a$ denote the simple module $M^{0,0-(a,\ldots,a)}$ in $\mathcal{S}'_r(k)$. The symbol $d(a_1,\ldots,a_4)$ denotes the degree of the divisor $\mathbb{D}_{0,4}(K(\slalg_{r+1},k),\otimes_{i=1}^4M_{a_i})$ on $\overline{\mathrm{M}}_{0,4}\cong\pp^1$. The rank of the bundle $\mathbb{V}_{0,n}(K(\slalg_{r+1},k),\otimes_{i=1}^nM_{a_i})$ on $\overline{\mathrm{M}}_{0,n}$ is denoted by $\mu(\otimes_{i=1}^n M_{a_i})$. The conformal weight of the module $M_a$ is written as $cw(a)$ and a simple computation gives $cw(a)=a+\frac{a^2r}{2k}(r-3)$. For any integers $x$ and $a$, we let $\overline{xa}$ denote $xa$ modulo $k$. Finally, we denote the symmetric divisor $\mathbb{D}_{0,n}(K(\slalg_{r+1},k),M_a^{\otimes n})$ on $\tilde{\mathrm{M}}_{0,n}=\overline{\mathrm{M}}_{0,n}/Sym_n$ by $\mathbb{D}_{0,n}^{r,a}$.
\end{notation}
\begin{proof}[Proof of Proposition~\ref{prop: non F-positive}]
One direction is a corollary to Theorems~\ref{thm: positive for sl2} and~\ref{thm: positive for sl3}. For the converse, it suffices to provide a coinvariant divisor $\mathbb{D}$ associated to representations in $\mathcal{S}_r(k)^{sim}$ that intersects an $F$-curve strictly negatively. 
We only need to consider symmetric divisors $\mathbb{D}_{0,n}^{r,a}$ on $\tilde{\mathrm{M}}_{0,n}$. One can show that all such divisors are trivial if  $k$ does not divide $n$. Let $n=km$ for some integer $m\geq1$.
\[
\mathbb{D}^{r,a}_{0,km}\cdot F_{1,1,kt+\epsilon} = d(a,a, \overline{\epsilon a},\overline{(-2-\epsilon)a})
=2cw(a)+cw(\overline{\epsilon a})+cw(\overline{(-2-\epsilon)a})-cw(\overline{2a})-2 cw(\overline{(\epsilon+1)a}).
\]
If $a=1$, then $\overline{\epsilon a}=\epsilon$, $\overline{(-2-\epsilon) a}=k-2-\epsilon$, for any integer $1\leq \epsilon\leq k-2$. Furthermore, If $\epsilon\leq k-3$, then the bundle $\mathbb{V}_{0,4}(K(\slalg_{r+1},k), M_1^{\otimes2}\otimes M_{\epsilon}\otimes M_{k-2-\epsilon})$ is non-trivial. Therefore, for any $1\leq \epsilon\leq k-3$
\begin{align*}
\mathbb{D}^{r,1}_{0,km}\cdot F_{1,1,kt+\epsilon} 
&=2cw(1)+cw(\epsilon)+cw(k-2-\epsilon)-cw(2)-2 cw(\epsilon+1)\\
&=\frac{1}{2}(k-2(2+\epsilon))(r-1)(r-2).
\end{align*}
Note that, for $t=0$ and $\epsilon=k-3$, 
$\mathbb{D}^{r,a}_{0,km}\cdot F_{1,1,k-3}<0$, and this completes the proof.
\end{proof}
The condition $k \geq 4$ ensures the existence of a positive integer $\epsilon$ satisfying $1 \leq \epsilon \leq k - 3$. The necessity for $r\geq3$ comes from the definition of the conformal weight. In the propositions below, we discuss positivity of the symmetric divisors associated to representations in $\mathcal{S}_r(k)$ for levels $k=2$ and $k=3$ and integers $r\geq3$.
\begin{proposition}
\label{prop: Sr k2}
For any integer $r\geq3$, the symmetric divisor $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_{r+1},2), M^{\otimes n})$ associated to a non-trivial simple module $M:=M^{0,0-(a_1,\ldots,a_r)}\in\mathcal{S}_r(2)$ is trivial if $n$ is odd. For $n$ even, letting $q:=a_1+\cdots+a_r$, 
\[
\mathbb{D}\cdot F_{1,1,i} = \begin{cases}
(q-1)(q-2)+2&\text{ if $i$ is odd},\\
0&\text{ if $i$ is even}.
\end{cases}
\]
\end{proposition}
\begin{proof}
All simple modules in $\mathcal{S}_r(2)$ are self-dual. The conformal weight of $M := M^{0,0-(a_1,\ldots,a_r)}$ is $\frac{(q - 1)(q - 2) + 2}{4}$. Writing $n = 2g + 2 + \delta$ and $i = 2t + \epsilon$ for integers $g, t \geq 0$ and $\delta, \epsilon \in \{0, 1\}$, we compute
\[
\mathbb{D} \cdot F_{1,1,i} = d\left( M^{\otimes 2} \otimes M^{(\overline{\epsilon a_1},\ldots,\overline{\epsilon a_r})} \otimes M^{(\overline{(\delta + \epsilon) a_1}, \ldots, \overline{(\delta + \epsilon) a_r})} \right).
\]
The intersection number is non-zero if and only if $\epsilon = 1$ and $\delta = 0$, in which case it equals $4 \cdot cw(M)$. 
\end{proof}
\begin{proposition}
\label{prop: Sr k3}
For any integer $r\geq3$, the symmetric coinvariant divisor $\mathbb{D}:=\mathbb{D}_{0,n}(K(\slalg_{r+1},3), M^{\otimes n})$ associated to a non-trivial simple module $M:=M^{0,0-(a_1,\ldots,a_r)}\in\mathcal{S}_r(3)$ is trivial if $3\not\mid n$. If $3\mid n$, for any $0\leq t\leq (2/3)n$  
\[
\mathbb{D}\cdot F_{1,1,3t+\epsilon} = \begin{cases}
3 cw(M)&\text{ if $\epsilon=2$},\\
0&\text{ if $\epsilon=0,1$ }.
\end{cases}
\]\end{proposition}
\begin{proof}
The proof is similar and therefore omitted.
\end{proof}
\begin{remark}
It was communicated to the author by Daebeom Choi that the divisors discussed in Propositions~\ref{prop: Sr k2} and~\ref{prop: Sr k3} are semi-ample in characteristic~$p$ (see~\cite{DaebeomInPrep}). It would be interesting to investigate the corresponding morphisms.
\end{remark}
\subsection{Proof of Proposition~\ref{prop: degree for sl2}}
\label{subsec: parafermions and proof of degree formula}
In this subsection, we prove Proposition~\ref{prop: degree for sl2}. We restate the proposition below for the reader's convenience.
\begin{proposition}
Let $k\geq1$ be an integer and let $i\in\{a,b,c,d\}$ so that $0\leq i'<i\leq k$ for each $i$ and $a\leq b\leq c\leq d$. Then, the degree $d$ of the divisor $\mathbb{D}_{0,4}(K(\slalg_2, k); M^{a,a'}\otimes (M^{b,b'})'  \otimes (M^{c,c'})'\otimes (M^{d,d'})')$ is given in terms of its rank $\mu$ and the sum of the conformal weights $c_{\Sigma}:=\sum_{i} cw(M^{i,i'})$ as follows:
\begin{equation*}
 -d+\mu c_{\Sigma} = \begin{cases}
0&\text{ if }\frac{b+c+d-a}{2}\ne b'+c'+d'-a'\mod k,\\
\Lambda &\text{ else,}
 \end{cases}
\end{equation*}
where 
\[
\Lambda = \sum_{i\in\{b,c,d\}}\left(\sum_{\substack{m_i\leq t\leq M_i\\ (a+i)\in2\zz}}cw\left(M^{t,\ \overline{a'-i'+\frac{t-a+i}{2}}}\right)\right)
\]
and $$M_i=\min(a+i,\ b+c+d-i,\ 2k-a-i,\ 2k-b-c-d+i),$$ $$m_i=\max(|i-a|,\ |\ga-\gb|),$$ with $\{\ga,\gb\}=\{b,c,d\}\setminus\{i\}$.
\end{proposition}

\begin{lemma}
Consider the three modules $M^{c,c'}, M^{d,d'}, m_{t,t'}$ for integers $0\leq a<a'\leq k$, where $a\in\{c,d,t\}$. Then, 
\[
\text{rank } \mathbb{D}_{0,4}(K(\slalg_2; k); M^{c,c'}\otimes M^{d,d'}\otimes (M^{t,t'})') =
\text{rank } \mathbb{D}_{0,4}(K(\slalg; k); (M^{c,c'})'\otimes (M^{d,d'})'\otimes M^{t,t'}).
\]
\end{lemma}
\begin{proof}
Note that $(M^{a,a'})'\cong m_{a,a-a'}$ for any $a\in\{c,d,t\}$ and therefore
\[
\text{rank } \mathbb{D}_{0,4}(K(\slalg_2; k); (M^{c,c'})'\otimes (M^{d,d'})'\otimes (M^{t,t'})') = 1
\]
if and only if $|d-c|\leq t\leq\min(c+d,2k-c-d)$ and $t=c+d\mod2$ with $$t-t'=\frac{1}{2}(2c-2c'+2d-2d'-c-d+t)\mod k.$$ The last condition reduces to $t' = \frac{1}{2}(2c'+2d'-c-d+t)\mod k.$ These conditions are necessary and sufficient for 
\[
\text{rank } \mathbb{V}_{0,4}(K(\slalg_2; k); M^{c,c'}\otimes M^{d,d'}\otimes (M_{t,t'})') = 1.
\]
Since the rank of these bundles is either zero or one, the result follows.
\end{proof}

Degree of the bundle 
\(
\mathbb{D}:=\mathbb{D}_{0,4}(K(\slalg_2; k); M^{a,a'}\otimes (M^{b,b'})'  \otimes (M^{c,c'})'\otimes (M^{d,d'})')
\)
is given by 
\begin{align*}
d+\mu c_{\Sigma}= \sum_{t}cw(M^{t,t'})\mu(M^{a,a'}\otimes (M^{b,b'})'\otimes (M^{t,t'})')\mu((M^{c,c'})'\otimes (M^{d,d'})'\otimes M^{t,t'}) +(b\leftrightarrow c) + (b\leftrightarrow d),
\end{align*}
where $\mu$ and $d$ are rank and degree, respectively, of the line bundle $\mathbb{D}$ and $c_{\Sigma}$ is sum of the conformal weights of the modules $M^{h,h'}$ where $h$ runs over the set $\{a,b,c,d\}$. Here, we are using the fact that conformal weight is invariant under taking the contragradient dual. Finally, $(b\leftrightarrow c)$ is the same as the sum over $t$ with positions of $b$ and $c$ switched, and similarly for $(b\leftrightarrow d)$. By the Lemma above, we have 
\begin{align*}
&\sum_{t}c(M^{t,t'})\mu(M^{a,a'}\otimes (M^{b,b'})'\otimes (M^{t,t'})')
\mu((M^{c,c'})'\otimes (M^{d,d'})'\otimes M^{t,t'})\\
&\qquad =\sum_{t}c(M^{t,t'})\mu(M^{a,a'}\otimes (M^{b,b'})'\otimes (M^{t,t'})')\mu(M^{c,c'}\otimes M^{d,d'}\otimes (M^{t,t'})').
\end{align*}
For a summand corresponding to $t$ to be nonzero, the first rank element requires that $t$ satisfy the following 
\[
|b-a|\leq t\leq\min(a+b,2k-a-b), t= a+b\mod2, 
t' = a'-b'+\frac{t-a+b}{2}\mod k
\]
and the second rank element requires that 
\[
|d-c|\leq t\leq\min(c+d,2k-c-d), t= c+d\mod2, 
t' = c'+d'+\frac{t-c+d}{2}\mod k.
\]
Combining these conditions, a nonzero contribution from a summand occurs only when $t$ satisfies the following:
\begin{align*}
\max(|b-a|,|d-c|)\leq &t\leq\min(a+b,c+d,2k-a-b,2k-c-d)\\
&t=a+b=c+d\mod2
\end{align*}
along with 
\[
t' = a'-b'+\frac{t-a+b}{2}\mod k=c'+d'+\frac{t-c+d}{2}\mod k
\]
and finally, we need the modules in consideration to satisfy the relation
\[
\frac{b+c+d-a}{2}=b'+c'+d'-a'\mod k.
\]
This completes the proof of the proposition.

\begin{example}
Let $\mathbb{D}:=\mathbb{D}_{0,4}(K(\slalg_2,k),\bigotimes_{p=1}^4 M^{2t_p,t_p})$, where $\sum t_i\geq k$, and $t_2+t_3\leq t_1+t_4$. Since all four modules are self-dual, we can directly apply the proposition above. After some calculations, we have
\[
m_{2t_2}=2t_4-2t_3,\quad  m_{2t_3}=2t_4-2t_2,\quad m_{2t_4}=2t_4-2t_1,
\]
\[
M_{2t_2}=2k-2t_3-2t_4,\quad  M_{2t_3}=2k-2t_2-2t_4,\quad M_{2t_4}=2k-2t_1-2t_4.
\]
Moreover, from Proposition~\ref{prop: rank formula sl2}, we have $\mu = 1+M_{2t_2}-m_{2t_2}=(1+k-2t_4)$, 
\[
\Lambda = \frac{\mu}{k+2}\left(2k+k^2+\sum_{p=1}^4(t_p^2-(k+1)t_p)\right),\quad  d=\mu (-k+\sum_{p=1}^4 t_p).
\]
\end{example}
\begin{example}
\label{exmp: fusion ring not F-poisitive}
The fusion rules for the parafermion VOA \( K(\mathfrak{sl}_2,3) \) imply that the subring of the fusion ring \( \mathcal{R}(K(\mathfrak{sl}_2,3)) \) generated by the union of the subrings \( \mathcal{T}(3) = \langle M^{0,0}, M^{2,1} \rangle \) and \( \mathcal{S}_1(3) = \langle M^{0,0}, M^{3,1}, M^{3,2} \rangle \) is, in fact, the entire fusion ring. Indeed, the relations
\[
M^{2,1} \boxtimes M^{3,1} = M^{1,0}, \quad \text{and} \quad M^{1,0} \boxtimes M^{3,1} = M^{2,0}
\]
show that all remaining simple modules can be generated from elements in \( \mathcal{T}(3) \cup \mathcal{S}_1(3) \). Using the degree formula discussed above, one verifies that the following coinvariant divisors on \( \overline{\mathrm{M}}_{0,4} \) have degree equal to \(-1\):
\[
\mathbb{D}_{0,4}(K(\mathfrak{sl}_2,3), {M^{1,0}}^{\otimes 2} \otimes {M^{2,0}}^{\otimes 2}), \quad 
\mathbb{D}_{0,4}(K(\mathfrak{sl}_2,3), {M^{1,0}}^{\otimes 3} \otimes M^{2,1}), \quad 
\mathbb{D}_{0,4}(K(\mathfrak{sl}_2,3), {M^{2,0}}^{\otimes 3} \otimes M^{2,1}).
\]
Therefore, by definition, the fusion ring \( \mathcal{R}(K(\mathfrak{sl}_2,3)) \) is not \( F \)-positive and hence not positive.
\end{example}

