% DOCUMENT

\begin{document}

\titletwo

% ABSTRACT

\begin{abstract}
This paper introduces a novel binary stability property for voting rules---called \hyperref[b]{binary self-selectivity}---by which a society considering whether to replace its voting rule using itself in pairwise elections will choose not to do so. In \Cref{th}, we show that a \hyperref[n]{neutral} voting rule is \hyperref[b]{binary self-selective} if and only if it is \hyperref[s]{universally self-selective}. We then use this equivalence to show, in \Cref{col1}, that under the unrestricted strict preference domain, a \hyperref[u]{unanimous} and \hyperref[n]{neutral} voting rule is \hyperref[b]{binary self-selective} if and only if it is \hyperref[d]{dictatorial}. In \Cref{col2,col3}, we show that whenever there is a strong Condorcet winner; a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule is \hyperref[b]{binary self-selective} (or \hyperref[s]{universally self-selective}) if and only if it is the \hyperref[con]{Condorcet voting rule}.
\end{abstract}

\keywords{voting, binary self-selectivity, dictatorship, Condorcet.}

\jelcodes{D71, D82.}

\wordcount{5,253}

% CONTENT

\section{Introduction}\label{sec.int}

\textsc{Historically}, virtually all countries that have decided whether to change their voting rule have done so in a binary fashion. For example, in 1918, Switzerland held a referendum to decide between keeping a three-round majoritarian system or introducing proportional representation, which was the option chosen by 66.8\% of the popular vote. In 1993, New Zealand held a referendum in which voters chose to replace the first-past-the-post method for a mixed-member proportional representation method with a 53.6\% of the popular vote. More recently, in 2011, the United Kingdom choose to keep the first-past-the-post method in a referendum against the instant run-off method with a 67.9\% of the popular vote. In all these three referenda---and in most such referenda across the world---the choice was binary: namely, between keeping or replacing the country's existing voting rule in a head-to-head contest.

In this paper, we introduce a novel \hyperref[b]{binary self-selectivity} axiom that draws its inspiration from \textcite{koray_00}, who proposed a consistency property---called \hyperref[s]{universal self-selectivity}---by which a \hyperref[n]{neutral} voting rule used by society to select one alternative among many should also select itself when used to select a voting rule among any finite set of \hyperref[n]{neutral} voting rules it belongs to. \citeauthor{koray_00}'s (\citeyear{koray_00}, Theorem 2, p. 990) central result states that under the unrestricted domain of strict preferences, a \hyperref[n]{neutral} and \hyperref[u]{unanimous} voting rule is \hyperref[s]{universally self-selective} if and only if it is \hyperref[d]{dictatorial}.

In his paper, \textcite{koray_00} assumes that a voting rule must select itself among any finite set of \hyperref[n]{neutral} voting rules it belongs to. However, most societies decide on their voting rule by voting in favor or against some alternative voting rule: that is, in binary elections. One may then naturally wonder whether \citeauthor{koray_00}'s (\citeyear{koray_00}, Theorem 2, p. 990) result holds when demanding that a \hyperref[n]{neutral} voting rule selects itself only from sets of voting rules containing itself and \emph{just one} other \hyperref[n]{neutral} voting rule. This paper addresses this question, as we modify \citeauthor{koray_00}'s \citeyearpar{koray_00} \hyperref[s]{universal self-selectivity} by assuming that society chooses whether to replace its voting rule in a binary fashion.

In \Cref{th}, we show that replacing \hyperref[s]{universal self-selectivity} for \hyperref[b]{binary self-selectivity} makes no difference, for a \hyperref[n]{neutral} voting rule is \hyperref[b]{binary self-selective} if and only if it is \hyperref[s]{universally self-selective}. Hence, in \Cref{col1}, we show that \hyperref[d]{dictatorships} are the only \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[b]{binary self-selective} voting rules. Further, we also show in \Cref{col2,col3} that under the restricted domain of strict preferences with a strong Condorcet winner; a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule is \hyperref[b]{binary self-selective} (or \hyperref[s]{universally self-selective}) if and only if it is the \hyperref[con]{Condorcet voting rule} (i.e., the majority voting rule). All in all, \hyperref[b]{binary self-selectivity} is a more natural modeling choice than \hyperref[s]{universal self-selectivity}, but it is not a technical requirement to obtain our results. 

Our results reinforce the long-standing idea that the \hyperref[con]{Condorcet voting rule} is special and the most desirable voting rule whenever it produces a unique winner. Notably, \textcite[Theorem 2, p. 965]{dasguptamaskin_08} show that the majority voting rule satisfies five highly desirable axioms---\hyperref[p]{Pareto}, \hyperref[a]{anonymity}, \hyperref[n]{neutrality}, \hyperref[iia]{independence of irrelevant alternatives} and \emph{decisiveness}---over a larger class of preference domains than any other voting rule. In a related paper, \textcite[Theorem 2, p. 467]{dasguptamaskin_20} show that \emph{group strategy-proofness}, \hyperref[p]{Pareto}, \hyperref[a]{anonymity}, \hyperref[n]{neutrality}, \hyperref[iia]{independence of irrelevant alternatives} and \emph{decisiveness} uniquely characterize the majority voting rule on any domain of preferences for which there exists a voting rule satisfying these axioms (namely, on any restricted domain without Condorcet cycles). In our paper, we add to this body of work by showing that whenever a strong Condorcet winner exists, the majority voting rule is the only democratic and stable voting rule.

\citeauthor{koray_00}'s \citeyearpar{koray_00} analysis has been extended in a few directions. Notably, several authors have successfully escaped his impossibility result. For example, \textcite{unel_99} restricts the domain of voting rules to single-peaked preference profiles, and \textcite{korayslinko_08,kermankoray_24} restrict the set of rival functions society shall choose from. However, some authors have shown that certain restricting assumptions are not enough to escape \citeauthor{koray_00}'s \citeyearpar{koray_00} impossibility result. For example, \textcite{korayunel_03} restrict the set of rival functions to \emph{tops-only} ones; whereas \textcite{koraysenocak_24} introduce a weaker notion of stability called \emph{selection-closedness}. Finally, some authors have explored other related issues, such as the manipulability of \hyperref[s]{universally self-selective} voting rules \parencite{diss_15}, the \hyperref[s]{universal self-selectivity} of triplets of voting rules \parencite{dissmerlin_10,disslouichimerlinsmaoui_12}, the properties of \emph{dynamically stable} sets of constitutions \parencite{houy_07}, or the stability of the French and (failed) European constitutions \parencite{houy_06}.

Other authors have also analyzed closely related problems, using simple games \parencite{vonneumannmorgenstern_44} as voting rules. Notably, \textcite{barberajackson_04} introduce a model of binary ex-ante self-stability, inspired by \textcite{rae_69}, in which every voter's preference is modeled through some probability distribution indicating the likelihood this voter will favor reform. Their seminal contribution has been extended in several directions. For example, \textcite{azrielikim_16} expand their model to weighted majority voting rules; \textcite{jeongkim_23} present the concepts of interim and ex-post self-stability; \textcite{jeongkim_24} bridge the gap between ex post and ex ante stability; \textcite{kulttimiettinen_07} characterize the \textcite{vonneumannmorgenstern_44} stable set of majority voting rules; \textcite{coelho_05} characterizes the set of voting rules satisfying the maximin criterion; \textcite{kulttimiettinen_09} consider constitutions with arbitrary many voting rules; \textcite{lagunoff_09} introduces a dynamic model of stability; and \textcite{hermidarivera_24} introduces the notion of minimal stability.

The rest of the paper is organized as follows: \Cref{sec.env} defines the environment, \Cref{sec.ax} introduces the axioms, and \Cref{sec.res} contains the results.

\section{Environment}\label{sec.env}

The \emph{environment} is a $4$-tuple $(N,A_\tau,\mathcal{R}(A_\tau),\sigma)$. Let $N=\{1,\dots,n\}$ be a \emph{finite voter set}, where $n\geqslant2$. Let $A_\tau=\{a_1,\dots,a_\tau\}$ be a \emph{finite alternative set}, where $\tau\in\mathbb{N}=\{1,2,\dots\}$. Let
\begin{gather}
    \mathcal{R}(A_\tau)=\bigl\{R\mid R=(R_i)_{i\in N}:R_i\text{ is \emph{voter $i$'s weak order} over }A_\tau\bigr\}
\end{gather}
be the \emph{set of all weak preference profiles over some alternative set} whose \emph{strict part} is $\mathcal{P}(A_\tau)=\{P\mid P=(P_i)_{i\in N}\}$: namely, for all alternatives $x,y\in A_\tau$ and all voters $i\in N$, we have $x R_iy$ if and only if voter $i$ \emph{weakly prefers} $x$ over $y$, and $x P_iy$ if and only if voter $i$ \emph{strictly prefers} $x$ over $y$. Finally, given any $\tau\in\mathbb{N}$ and any \emph{set of admissible preference profiles} $\mathcal{A}(A_\tau)\subseteq\mathcal{P}(A_\tau)$, let
\begin{gather}
    \sigma:\bigcup_{\tau\in\mathbb{N}}\mathcal{A}(A_\tau)\to\bigcup_{\tau\in\mathbb{N}}A_\tau
\end{gather}
be a \emph{voting rule} so that $\sigma(P)\in A_\tau$ for all $\tau\in\mathbb{N}$ and all profiles $P\in\mathcal{A}(A_\tau)$.

\section{Axioms}\label{sec.ax}

On the one hand, the \hyperref[u]{unanimity}, \hyperref[d]{dictatorship}, \hyperref[a]{anonymity} and \hyperref[n]{neutrality} axioms are well-known axioms that barely need an introduction; on the other hand, the \hyperref[b]{binary self-selectivity} axiom is a natural adaptation of \citeauthor{koray_00}'s (\citeyear{koray_00}, p. 985) \hyperref[s]{universal self-selectivity} to binary environments in which society chooses whether to replace its existing voting rule in head-to-head contests with all other voting rules.

Let $\Sigma=\{\sigma\mid\sigma\text{ is a voting rule}\}$.

Given any $\tau\in\mathbb{N}$ and any profile $P\in\mathcal{P}(A_\tau)$, let $t_i(P)$ be \emph{voter $i$'s top-ranked alternative at profile $P$}.

\begin{axiom}[Unanimity]\label{u}
    A voting rule $\sigma$ is \emph{unanimous} if and only if it always selects the unanimously top-ranked alternative whenever there is one. Formally, if and only if
\begin{gather}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall x\in A_\tau)[((\forall i\in N)(t_i(P)=x))\Rightarrow(\sigma(P)=x)]
\end{gather}
\end{axiom}

Let $\Sigma_u=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[u]{unanimous}}\}$.

\begin{axiom}[Dictatorship]\label{d}
    A voting rule $\sigma$ is \emph{dictatorial} if and only if it always selects the same voter's top-ranked alternative. Formally, if and only if
\begin{gather}\label{eq.d}
    (\exists i\in N)[(\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\sigma(P)=t_i(P))]
\end{gather}
\end{axiom}

Given any voter $i\in N$, let $\delta_i$ be his \hyperref[d]{dictatorship}: namely, $\delta_i(P)=t_i(P)$ for all $\tau\in\mathbb{N}$ and all profiles $P\in\mathcal{A}(A_\tau)$.

Let $\Delta=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[d]{dictatorial}}\}$.

Let $\Pi=\{\pi:N\to N\mid\pi\text{ is bijective}\}$ be the \emph{set of all permutations of the voter set}. Then, given any $\tau\in\mathbb{N}$, any profile $P\in\mathcal{P}(A_\tau)$ and any permutation $\pi\in\Pi$, let the profile $\pi P=(P_{\pi(i)})_{i\in N}\in\mathcal{P}(A_\tau)$ satisfy, for all voters $i\in N$ and all alternatives $x,y\in A_\tau$, $x\pi P_iy$ if and only if $xP_{\pi(i)}y$.

\begin{axiom}[Anonymity]\label{a}
    A voting rule $\sigma$ is \emph{anonymous} if and only if it is independent of voters' identities. Formally, if and only if
\begin{gather}\label{eq.a}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall\pi\in\Pi)[\sigma(P)=\sigma(\pi P)]
\end{gather}
\end{axiom}

Let $\Sigma_a=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[a]{anonymous}}\}$.

Given any $\tau\in\mathbb{N}$, let $M_\tau=\{\mu:A_\tau\to A_\tau\mid\mu\text{ is bijective}\}$ be the \emph{set of all permutations of the alternative set}. Then, given any profile $P\in\mathcal{P}(A_\tau)$ and any permutation $\mu\in M_\tau$, let the profile $\mu P\in\mathcal{P}(A_\tau)$ satisfy, for all voters $i\in N$ and all alternatives $x,y\in A_\tau$, $\mu(x)\mu P_i\mu(y)$ if and only if $x P_iy$.

\begin{axiom}[Neutrality]\label{n}
    A voting rule $\sigma$ is \emph{neutral} if and only if it is independent of alternatives' labels. Formally, if and only if
\begin{gather}\label{eq.n}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall\mu\in M_\tau)[\mu(\sigma(P))=\sigma(\mu P)]
\end{gather}
\end{axiom}

Let $\Sigma_n=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[n]{neutral}}\}$.

The domain of \hyperref[n]{neutral} voting rules can be easily extended to strict preference profiles on any finite non-empty set. Given any set $X$ with cardinality $\tau$, let $B(X)=\{\beta:X\to A_\tau\mid\beta\text{ is bijective}\}$ be the \emph{set of all bijections} from $X$ onto $A_\tau$. Given any profile $P\in\mathcal{P}(X)$ and any bijection $\beta\in B(X)$, let the profile $\beta P\in\mathcal{P}(A_\tau)$ satisfy, for all voters $i\in N$ and all elements $a,b\in X$, $aP_ib$ if and only if $\beta(a)\beta P_i\beta(b)$. Then, given any two bijections $\beta,\tilde{\beta}\in B(X)$, any profile $P\in\mathcal{P}(X)$ and any \hyperref[n]{neutral} voting rule $\sigma\in \Sigma_n$, it follows that $\beta^{-1}(\sigma(\beta P))=\tilde{\beta}^{-1}(\sigma(\tilde{\beta}P))$ as long as $\beta P,\tilde{\beta}P\in\mathcal{A}(A_\tau)$. Hence, set $\sigma(P)=\beta^{-1}(\sigma(\beta P))$ for all profiles $P\in\mathcal{P}(X)$ and some bijection $\beta\in B(X)$.

In order to introduce the \hyperref[b]{binary self-selectivity} axiom, we now specify voters' preferences over voting rules. We do so by taking the consequentialist approach, by which preferences over voting rules are derived from the alternatives they choose; rather than the non-consequentialist approach, by which preferences over voting rules are defined independently of the alternatives.

Given any $\tau\in\mathbb{N}$, any profile $P\in\mathcal{P}(A_\tau)$ naturally induces a preference profile over any finite set $T\subsetneq\Sigma_n$. Given any $\tau\in\mathbb{N}$ and any profile $P\in\mathcal{P}(A_\tau)$, let the weak profile $\boldsymbol{R}^{T\!P}\in\mathcal{R}(T)$ satisfy, for all voters $i\in N$ and all voting rules $\sigma,\sigma'\in T$, $\sigma \boldsymbol{R}_i^{T\!P}\sigma'$ if and only if $\sigma(P)P_i\sigma'(P)$.

Given any finite set $T\subsetneq\Sigma_n$ and any profile $P\in\mathcal{P}(A_\tau)$, a profile $\boldsymbol{P}\in\mathcal{P}(T)$ is \emph{compatible} with the weak profile $\boldsymbol{R}^{T\!P}$ if and only if for all voting rules $\sigma,\sigma'\in T$ and all voters $i\in N$, we have that $\sigma \boldsymbol{P}_i\sigma'$ implies $\sigma \boldsymbol{R}_i^{T\!P}\sigma'$ (i.e., if and only if $\boldsymbol{P}$ can be obtained from $\boldsymbol{R}^{T\!P}$ by linearly ordering the elements in each indifference class). Then, given any $\tau\in\mathbb{N}$, any finite set $T\subsetneq \Sigma_n$ and any profile $P\in\mathcal{A}(A_\tau)$, let $\mathcal{A}(T,P)=\{\boldsymbol{P}\in\mathcal{A}(T)\mid\boldsymbol{P}\text{ is compatible with }\boldsymbol{R}^{T\!P}\}$.

\begin{axiom}[Binary self-selectivity]\label{b}
    A \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n$ is \emph{binary self-selective} if and only if given any other \hyperref[n]{neutral} voting rule and any preference profile over the alternatives, there exists a compatible preference profile at which it selects itself. Formally, if and only if
\begin{gather}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall\sigma'\in\Sigma_n\backslash\{\sigma\})[(\exists\boldsymbol{P}\in\mathcal{A}(\{\sigma,\sigma'\},P))(\sigma(\boldsymbol{P})=\sigma)]
\end{gather}
\end{axiom}

Let $\Sigma_b=\{\sigma\in \Sigma\mid\sigma\text{ is \hyperref[b]{binary self-selective}}\}$.

We now introduce \citeauthor{koray_00}'s (\citeyear{koray_00}) \hyperref[s]{universal self-selectivity} axiom, but on any domain (rather than only on the unrestricted domain of strict preferences). Given any \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n$, let $\mathcal{T}(\sigma)=\{T\subsetneq\Sigma_n\mid(\sigma\in T)\wedge(|T|<\infty)\}$ be the \emph{collection of all finite sets of \hyperref[n]{neutral} voting rules containing the voting rule $\sigma$}.

\begin{axiom}[Universal self-selectivity]\label{s}
    A \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n$ is \emph{universally self-selective} if and only if given any finite set of \hyperref[n]{neutral} voting rules it belongs to and any preference profile over the alternatives, there exists a compatible preference profile at which it selects itself. Formally, if and only if
\begin{gather}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall T\in\mathcal{T}(\sigma))[(\exists\boldsymbol{P}\in\mathcal{A}(T,P))(\sigma(\boldsymbol{P})=\sigma)]
\end{gather}
\end{axiom}

Let $\Sigma_s=\{\sigma\in \Sigma\mid\sigma\text{ is \hyperref[s]{universally self-selective}}\}$.

\begin{exampleb}
    Consider a society with five voters $N=\{1,\dots,5\}$ and four alternatives $A_4=\{x,y,z,w\}$. Let $p$ be the \emph{plurality rule} that selects the alternative top-ranked by the largest number of voters if there is only one, and voter $1$'s top-ranked alternative otherwise; and let $b$ be the \emph{Borda rule} that selects the alternative with the highest Borda count with scoring vector $(\tau,\tau-1,\dots,1)$ if there is only one, and voter $4$'s top-ranked alternative otherwise.
