\section{Results}\label{sec.res}

\begin{theorem}\label{th}
    Given any set of admissible preference profiles, a \hyperref[n]{neutral} voting rule is \hyperref[b]{binary self-selective} if and only if it is \hyperref[s]{universally self-selective}. Formally,
\begin{gather}
    [(\forall\tau\in\mathbb{N})(\mathcal{A}(A_\tau)\subseteq\mathcal{P}(A_\tau))]\Rightarrow[(\sigma\in\Sigma_n)\Rightarrow((\sigma\in\Sigma_b)\iff(\sigma\in\Sigma_s))]
\end{gather}
\end{theorem}

\begin{proof}
    Consider any $\tau\in\mathbb{N}$ and any set of admissible preference profiles $\mathcal{A}(A_\tau)\subseteq\mathcal{P}(A_\tau)$. Then, there are two statements to show:
\begin{enumerate}
    \item $(\sigma\in\Sigma_n)\Rightarrow((\sigma\in\Sigma_s)\Rightarrow(\sigma\in\Sigma_b))$, 
    \item $(\sigma\in\Sigma_n)\Rightarrow((\sigma\in\Sigma_b)\Rightarrow(\sigma\in\Sigma_s))$.
\end{enumerate}

\begin{statement}\label{s1}
    $(\sigma\in\Sigma_n)\Rightarrow((\sigma\in\Sigma_s)\Rightarrow(\sigma\in\Sigma_b))$.
\end{statement}

    The proof is direct. Consider any \hyperref[n]{neutral} and \hyperref[s]{universally self-selective} voting rule $\sigma\in\Sigma_n\cap\Sigma_s$ as well as any set $T=\{\sigma,\sigma'\}$, where $\sigma'\in\Sigma_n\backslash\{\sigma\}$. By the \hyperref[s]{universal self-selectivity} axiom, $\sigma(\boldsymbol{P})=\sigma$ for some compatible preference profile $\boldsymbol{P}\in\mathcal{A}(T,P)$. But then, $\sigma\in\Sigma_b$.

\begin{statement}\label{s2}
    $(\sigma\in\Sigma_n)\Rightarrow((\sigma\in\Sigma_b)\Rightarrow(\sigma\in\Sigma_s))$.
\end{statement}

    We now introduce one new axiom that will be useful to prove \Cref{s2}.

\begin{axiom}[Independence of irrelevant alternatives]\label{iia}
    A voting rule $\sigma$ is \emph{independent of irrelevant alternatives} if and only if removing a set of losing alternatives does not change the winning alternative. Formally, if and only if
\begin{gather}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall B\subseteq A_\tau\backslash\{\sigma(P)\})(\sigma(P)=\sigma(P|_{A_\tau\backslash B}))
\end{gather}
\end{axiom}

    Let $\Sigma_i=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[iia]{independent of irrelevant alternatives}}\}$.

    Now, the proof of \Cref{s2} follows from these two claims:
\begin{enumerate}[label=2.\arabic*.]
    \item $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$,
    \item $\Sigma_n\cap\Sigma_b\subseteq\Sigma_s$.
\end{enumerate}

\begin{claim}\label{c21}
    $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$.
\end{claim}

    The proof is by contradiction. Consider any \hyperref[n]{neutral}, \hyperref[b]{binary self-selective} and \emph{not} \hyperref[iia]{independent of irrelevant alternatives} voting rule $\sigma\in(\Sigma_n\cap\Sigma_b)\backslash\Sigma_i$, any profile $P\in\mathcal{A}(A_\tau)$, and any set $B\subseteq A_\tau\backslash\{\sigma(P)\}$. If $A_\tau\backslash B=\{\sigma(P)\}$ or $B=\emptyset$, it trivially follows that $\sigma(P)=\sigma(P|_{A_\tau\backslash B})$. Hence, consider any alternative $y\in A_\tau\backslash\{\sigma(P)\}$ and let $A_\tau\backslash B=\{\sigma(P),y\}$ as well as $B\neq\emptyset$.

    Consider any \hyperref[n]{neutral} voting rule $\sigma'\in\Sigma_n$ satisfying $\sigma'(P)=y$. Let $T=\{\sigma,\sigma'\}$ and $T(P)=\{\sigma(P),\sigma'(P)\}$. Consequently, $\mathcal{P}(T,P)=\{\boldsymbol{P}\}$; and by the \hyperref[b]{binary self-selectivity} axiom, $\mathcal{P}(T,P)\cap\mathcal{A}(T,P)\neq\emptyset$. Hence, $\mathcal{A}(T,P)=\{\boldsymbol{P}\}$. Let $\beta:T(P)\to T$ satisfy $\beta(\sigma(P))=\sigma$ and $\beta(y)=\sigma'$. Then, $\beta P|_{\{\sigma(P),y\}}=\boldsymbol{P}$. Thus, the \hyperref[n]{neutrality} and \hyperref[b]{binary self-selectivity} axioms together imply that $\sigma=\sigma(\boldsymbol{P})=\sigma(\beta P|_{\{\sigma(P),y\}})=\beta(\sigma(P|_{\{\sigma(P),y\}}))$, further implying that $\sigma(P|_{\{\sigma(P),y\}})=\beta^{-1}(\sigma)=\sigma(P)$.

    Consider any $\tau'\in\mathbb{N}$ satisfying $\tau'>\tau$, and any profile $P'\in\mathcal{A}(A_{\tau'})$ satisfying $P'|_{A_\tau}=P$ and $\sigma(P')\in A_\tau$. Since $\sigma\notin\Sigma_i$, suppose that $\sigma(P')\neq\sigma(P)$. Consider any alternative $z\in A_{\tau'}\backslash\{\sigma(P')\}$ and let $C\subseteq A_{\tau'}$ satisfy $A_{\tau'}\backslash C=\{\sigma(P'),z\}$. Consider any \hyperref[n]{neutral} voting rule $\sigma''\in\Sigma_n$ satisfying $\sigma''(P')=z$. Let $T'=\{\sigma,\sigma''\}$ and $T'(P')=\{\sigma(P'),\sigma''(P')\}$. Consequently, $\mathcal{P}(T',P')=\{\boldsymbol{P}'\}$; and by the \hyperref[b]{binary self-selectivity} axiom, $\mathcal{P}(T',P')\cap\mathcal{A}(T',P')\neq\emptyset$. Then, $\mathcal{A}(T',P')=\{\boldsymbol{P}'\}$. Let $\tilde{\beta}:T'(P')\to T'$ satisfy $\tilde{\beta}(\sigma(P'))=\sigma$ and $\tilde{\beta}(z)=\sigma''$. Then, $\tilde{\beta} P'|_{\{\sigma(P'),z\}}=\boldsymbol{P}'$. Thus, the \hyperref[n]{neutrality} and \hyperref[b]{binary self-selectivity} axioms together imply that $\sigma=\sigma(\boldsymbol{P}')=\sigma(\tilde{\beta} P'|_{\{\sigma(P'),z\}})=\tilde{\beta}(\sigma(P'|_{\{\sigma(P'),z\}}))$, further implying that $\sigma(P'|_{\{\sigma(P'),z\}})=\tilde{\beta}^{-1}(\sigma)=\sigma(P')$.

    Since $P'|_{A_\tau}=P$ and $\{\sigma(P),\sigma(P')\}\subseteq A_\tau$, it follows that $P|_{\{\sigma(P),\sigma(P')\}}=P'|_{\{\sigma(P),\sigma(P')\}}$. Therefore, $\sigma(P)=\sigma(P|_{\{\sigma(P),\sigma(P')\}})=\sigma(P'|_{\{\sigma(P),\sigma(P')\}})=\sigma(P')$, which contradicts the assumption that $\sigma(P')\neq\sigma(P)$. Hence, $\sigma\in\Sigma_i$. Thus, $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$.

\begin{claim}\label{c22}
    $\Sigma_n\cap\Sigma_b\subseteq\Sigma_s$.
\end{claim}

    The proof is by contradiction. Consider any \hyperref[n]{neutral}, \hyperref[b]{binary self-selective} and non-\hyperref[s]{universally self-selective} voting rule $\sigma\in(\Sigma_n\cap\Sigma_b)\backslash\Sigma_s$. Then, there exists some set $T\in\mathcal{T}(\sigma)$ and some admissible profile $P\in\mathcal{A}(A_\tau)$ such that $\sigma(\boldsymbol{P})\neq\sigma$ for all compatible profiles $\boldsymbol{P}\in\mathcal{A}(T,P)$. Fix any such set $T\in\mathcal{T}(\sigma)$ and any such admissible profile $P\in\mathcal{A}(A_\tau)$. By \Cref{c21}, $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$. Therefore, $\sigma\in\Sigma_i$. Now, by the \hyperref[iia]{independence of irrelevant alternatives} axiom, $\sigma(\boldsymbol{P}|_{\{\sigma,\sigma(\boldsymbol{P})\}})=\sigma(\boldsymbol{P})\neq\sigma$ for all compatible profiles $\boldsymbol{P}\in\mathcal{A}(T,P)$. Hence, by the \hyperref[b]{binary self-selectivity} axiom, there exists some compatible profile $\boldsymbol{P}'\in\mathcal{A}(\{\sigma,\sigma(\boldsymbol{P})\},P)$ such that $\sigma(\boldsymbol{P}')=\sigma\neq\sigma(\boldsymbol{P})$. Thus, $\boldsymbol{P}'\neq\boldsymbol{P}|_{\{\sigma,\sigma(\boldsymbol{P})\}}$. And further, $\sigma(P)=(\sigma(\boldsymbol{P}))(P)$. Now, let $\mu:T\to T$ satisfy $\mu(\sigma)=\sigma(\boldsymbol{P})$, $\mu(\sigma(\boldsymbol{P}))=\sigma$ and $\mu(\sigma')=\sigma'$ for all voting rules $\sigma'\in T\backslash\{\sigma,\sigma(\boldsymbol{P})\}$. By the \hyperref[n]{neutrality} axiom, $\sigma(\mu\boldsymbol{P})=\mu(\sigma(\boldsymbol{P}))=\sigma$. And moreover, $\mu\boldsymbol{P}\in\mathcal{A}(T,P)$. But this contradicts the assumption that there exists no compatible profile $\boldsymbol{P}\in\mathcal{A}(T,P)$ satisfying $\sigma(\boldsymbol{P})=\sigma$. Therefore, $\Sigma_n\cap\Sigma_b\subseteq\Sigma_s$.
\end{proof}

\begin{corollary}\label{col1}
    Under the unrestricted strict preference domain, a \hyperref[u]{unanimous} and \hyperref[n]{neutral} voting rule is \hyperref[b]{binary self-selective} if and only if it is \hyperref[d]{dictatorial}. Formally,
\begin{gather}
    [(\forall\tau\in\mathbb{N})(\mathcal{A}(A_\tau)=\mathcal{P}(A_\tau))]\Rightarrow[(\sigma\in\Sigma_u\cap\Sigma_n)\Rightarrow((\sigma\in\Delta)\iff(\sigma\in\Sigma_b))]
\end{gather}
\end{corollary}

\begin{cproof}
    Let $\mathcal{A}(A_\tau)=\mathcal{P}(A_\tau)$ for all $\tau\in\mathbb{N}$. Then, by \textcite[Theorem 2, p. 990]{koray_00}, a \hyperref[u]{unanimous} and \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_u\cap\Sigma_n$ satisfies $\sigma\in\Sigma_s$ if and only if $\sigma\in\Delta$. By \Cref{th}, a \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n$ satisfies $\sigma\in\Sigma_b$ if and only if $\sigma\in\Sigma_s$. Therefore, a \hyperref[u]{unanimous} and \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_u\cap\Sigma_n$ satisfies $\sigma\in\Sigma_b$ if and only if $\sigma\in\Delta$.
\end{cproof}

\Cref{th,col1} show that substituting \hyperref[s]{universal self-selectivity} for \hyperref[b]{binary self-selectivity} is not enough to escape \citeauthor{koray_00}'s (\citeyear{koray_00}, Theorem 2, p. 990) impossibility result. Yet, in \Cref{col2,col3}, we obtain two novel and closely related characterizations of the \hyperref[con]{Condorcet voting rule} on the domain of preference profiles with a strong Condorcet winner.

Given any $\tau\in\mathbb{N}$ and any profile $R\in\mathcal{R}(A_\tau)$, let $N_R(x,y)=\{i\in N\mid xR_iy\}$ be the \emph{set of voters who (weakly) prefer $x$ to $y$}, and let $n_R(x,y)=|N_R(x,y)|$ be \emph{its cardinality}. Given any profile $P\in\mathcal{P}(A_\tau)$, let $C_P=\{x\in A_\tau\mid(\forall y\in A_\tau\backslash\{x\})(n_P(x,y)>n/2)\}$ be the \emph{set of strong Condorcet winners at $P$}. Then, $C_P\in\{\emptyset,c_P\}$ (i.e., $C_P$ is either empty or a singleton). Let $\mathcal{C}(A_\tau)=\{P\in\mathcal{P}(A_\tau)\mid C_P\neq\emptyset\}$ be the \emph{set of strict preference profiles on $A_\tau$ with a strong Condorcet winner}.

\begin{definition}[Condorcet voting rule]\label{con}
    Given any strict preference profile with a strong Condorcet winner, the \emph{Condorcet voting rule} $c$ always selects it. Formally,
\begin{gather}
    (\forall\tau\in\mathbb{N})[(\mathcal{A}(A_\tau)=\mathcal{C}(A_\tau))\wedge((\forall P\in\mathcal{A}(A_\tau))(c(P)=c_P))]
\end{gather}
\end{definition}

\begin{theorem}\label{col2}
    Under the strict preference domain with a strong Condorcet winner; a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule is \hyperref[b]{binary self-selective} if and only if it is the \hyperref[con]{Condorcet voting rule}. Formally,
\begin{gather}
    [(\forall\tau\in\mathbb{N})(\mathcal{A}(A_\tau)=\mathcal{C}(A_\tau))]\Rightarrow[(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma=c)\iff(\sigma\in\Sigma_b))]
\end{gather}
\end{theorem}

\begin{proof}
    Let $\mathcal{A}(A_\tau)=\mathcal{C}(A_\tau)$ for all $\tau\in\mathbb{N}$. Then, there are three statements to show:
\begin{enumerate}
    \item $c\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$,
    \item $(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma=c)\Rightarrow(\sigma\in\Sigma_b))$,
    \item $(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma\in\Sigma_b)\Rightarrow(\sigma=c))$.
\end{enumerate}

\begin{statement}\label{s1'}
    $c\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$.
\end{statement}

    The proof is direct. Fix any $\tau\in\mathbb{N}$. Consider any profile $P\in\mathcal{C}(A_\tau)$ satisfying $t_i(P)=x$ for all voters $i\in N$. Then, $c(P)=c_P=x$. Hence, $c\in\Sigma_u$. Consider any profile $P\in\mathcal{C}(A_\tau)$ and any permutation $\mu\in M_\tau$. Then, $\mu(c(P))=\mu(c_P)=c_{\mu P}=c(\mu P)$. Hence, $c\in\Sigma_n$. Consider any profile $P\in\mathcal{C}(A_\tau)$ and any permutation $\pi\in\Pi$. Then, $c(P)=c_P=c_{\pi P}=c(\pi P)$. Hence, $c\in\Sigma_a$. Therefore, $c\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$.

\begin{statement}\label{s2'}
    $(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma=c)\Rightarrow(\sigma\in\Sigma_b))$.
\end{statement}

    The proof is direct. By \Cref{s1'}, $c\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$. Thus, we only need to show that $c\in\Sigma_b$. Notice that if $A_2=\{x,y\}$; then, for all profiles $P\in\mathcal{C}(A_2)$, we have $c(P)=x$ if and only if $n_P(x,y)>n/2$. Consider any $\tau\in\mathbb{N}$, any profile $P\in\mathcal{C}(A_\tau)$, and any \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n\backslash\{c\}$. Fix $T=\{c,\sigma\}$. Then, $n_{P}(c(P),\sigma(P))>n/2$. Thus, $n_{\boldsymbol{R}^{T\!P}}(c,\sigma)>n/2$. Therefore, there exists some compatible profile $\boldsymbol{P}\in\mathcal{C}(T,P)$ such that $n_{\boldsymbol{P}}(c,\sigma)>n/2$. Then, $c(\boldsymbol{P})=c$. Thus, $c\in\Sigma_b$. 

\begin{statement}\label{s3'}
    $(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma\in\Sigma_b)\Rightarrow(\sigma=c))$.
\end{statement}

    We now introduce one new axiom that will be useful to prove \Cref{s3'}.

\begin{axiom}[Pareto]\label{p}
    A voting rule $\sigma$ is \emph{Paretian} if and only if it never selects strictly Pareto dominated alternatives. Formally, if and only if
\begin{gather}\label{eq.p}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{A}(A_\tau))(\forall x,y\in A_\tau)[((\forall i\in N)(xP_iy))\Rightarrow(\sigma(P)\neq y)]
\end{gather}    
\end{axiom}

    Let $\Sigma_p=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[p]{Paretian}}\}$.

    Let $A_2=\{x,y\}$ and let $\Sigma_2=\{\sigma\in\Sigma\mid(\forall P\in\mathcal{C}(A_2))[(\sigma(P)=x)\iff(n_P(x,y)>n/2)]\}$ be the \emph{set of voting rules that select the alternative that is top-ranked by the largest number of voters whenever there are just two alternatives}. By \Cref{s1'}, $c\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$. Thus, the proof of \Cref{s3'} follows directly from these four claims:
\begin{enumerate}[label=3.\arabic*.]
    \item[3.1.] $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$,
    \item[3.2.] $\Sigma_u\cap\Sigma_i\subseteq\Sigma_p$,
    \item[3.3.] $\Sigma_n\cap\Sigma_a\cap\Sigma_i\cap\Sigma_p\subseteq\Sigma_2$,
    \item[3.4.] $\Sigma_2\cap\Sigma_b=\{c\}$.
\end{enumerate}

\begin{claim}\label{c31'}
    $\Sigma_n\cap\Sigma_b\subseteq\Sigma_i$.
\end{claim}

    The proof follows directly from \Cref{c21} in the proof of \Cref{th}.

\begin{claim}\label{c32'}
    $\Sigma_u\cap\Sigma_i\subseteq\Sigma_p$.
\end{claim}

    The proof is by contradiction. Consider any $\tau\in\mathbb{N}$, any profile $P\in\mathcal{C}(A_\tau)$ and any \hyperref[u]{unanimous} and \hyperref[iia]{independent of irrelevant alternatives} voting rule $\sigma\in\Sigma_u\cap\Sigma_i$ satisfying $\sigma(P)=x$. Let alternative $y\in A_\tau\backslash\{x\}$ satisfy $yP_ix$ for all voters $i\in N$. Then, the \hyperref[iia]{independence of irrelevant alternatives} axiom implies $\sigma(P|_{\{x,y\}})=x$; whereas the \hyperref[u]{unanimity} axiom implies $\sigma(P|_{\{x,y\}})=y$, which is a contradiction. Thus, $\Sigma_u\cap\Sigma_i\subseteq\Sigma_p$.

\begin{claim}\label{c33'}
    $\Sigma_n\cap\Sigma_a\cap\Sigma_i\cap\Sigma_p\subseteq\Sigma_2$.
\end{claim}

    The proof is by contradiction. Consider any \hyperref[n]{neutral}, \hyperref[a]{anonymous}, \hyperref[iia]{independent of irrelevant alternatives} and \hyperref[p]{Paretian} voting rule $\sigma\in(\Sigma_n\cap\Sigma_a\cap\Sigma_i\cap\Sigma_p)\backslash\Sigma_2$. Then, there exists some profile $P\in\mathcal{C}(A_2)$ satisfying $\sigma(P)=x$ and $n_P(x,y)<n_P(y,x).$ Fix any such profile $P\in\mathcal{C}(A_2)$ and consider any coalition $T\subseteq N$ satisfying $|T|=n_P(y,x)$ as well as $yP_ix$ for all voters $i\in N\backslash T$. Then, let $A_3=\{x,y,z\}$ and consider the profile $P'\in\mathcal{C}(A_3)$ satisfying $P'|_{\{x,y\}}=P$; $yP'_iz$ for all voters $i\in N$; $xP'_iz$ for all voters $i\in T$; and $zP'_ix$ for all voters $i\in N\backslash T$. Since $P'|_{\{x,y\}}=P$, it follows that $\sigma(P'|_{\{x,y\}})=\sigma(P)=x$. By the \hyperref[p]{Pareto} axiom, $\sigma(P')\neq z$. By the \hyperref[iia]{independence of irrelevant alternatives} axiom, $\sigma(P')=\sigma(P'|_{\{x,y\}})=x=\sigma(P'|_{\{x,z\}})$. Let $\beta:\{x,z\}\to\{x,y\}$ satisfy $\beta(x)=y$ and $\beta(z)=x$. By the \hyperref[n]{neutrality} axiom, $\sigma(\beta P'|_{\{x,z\}})=\beta(\sigma(P'|_{\{x,z\}}))=\beta(x)=y$. Further, there exists some permutation $\pi\in\Pi$ such that $\pi\beta P'|_{\{x,z\}}=P$. Fix such a permutation $\pi\in\Pi$. Then, $\sigma(\pi\beta P'|_{\{x,z\}})=\sigma(P)=x$. But by the \hyperref[a]{anonymity} axiom, $\sigma(\pi\beta P'|_{\{x,z\}})=\sigma(\beta P'|_{\{x,z\}})=y$, which is a contradiction. Thus, $\Sigma_n\cap\Sigma_a\cap\Sigma_i\cap\Sigma_p\subseteq\Sigma_2$.

\begin{claim}\label{c34'}
    $\Sigma_2\cap\Sigma_b=\{c\}$.
\end{claim}

    The proof is by contradiction. Consider any \hyperref[b]{binary self-selective} voting rule $\sigma\in(\Sigma_2\cap\Sigma_b)\backslash\{c\}$. Then, there exists some $\tau\in\mathbb{N}$ and some profile $P\in\mathcal{C}(A_\tau)$ such that $\sigma(P)\neq c_P$. Fix any such profile $P\in\mathcal{C}(A_\tau)$. Let $T=\{c,\sigma\}$. Then, $n_P(c(P),\sigma(P))>n/2$. Thus, $\mathcal{C}(T,P)=\{\boldsymbol{P}\}$, where $n_{\boldsymbol{P}}(c,\sigma)>n/2$. Since $\sigma\in\Sigma_2$, it follows that $\sigma(\boldsymbol{P})=c$, thus contradicting the assumption that $\sigma\in\Sigma_b$. Hence, $\sigma\notin\Sigma_b$. Therefore, $\Sigma_2\cap\Sigma_b=\{c\}$.
\end{proof}

\begin{corollary}\label{col3}
    Under the strict preference domain with a strong Condorcet winner; a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule is \hyperref[s]{universally self-selective} if and only if it is the \hyperref[con]{Condorcet voting rule}. Formally,
\begin{gather}
    [(\forall\tau\in\mathbb{N})(\mathcal{A}(A_\tau)=\mathcal{C}(A_\tau))]\Rightarrow[(\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a)\Rightarrow((\sigma=c)\iff(\sigma\in\Sigma_s))]
\end{gather}
\end{corollary}

\begin{cproof}
    The proof is direct. Let $\mathcal{A}(A_\tau)=\mathcal{C}(A_\tau)$ for all $\tau\in\mathbb{N}$. By \cref{col2}, a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule $\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$ satisfies $\sigma\in\Sigma_b$ if and only if $\sigma=c$. By \Cref{th}, a \hyperref[n]{neutral} voting rule $\sigma\in\Sigma_n$ satisfies $\sigma\in\Sigma_b$ if and only if $\sigma\in\Sigma_s$. Therefore, a \hyperref[u]{unanimous}, \hyperref[n]{neutral} and \hyperref[a]{anonymous} voting rule $\sigma\in\Sigma_u\cap\Sigma_n\cap\Sigma_a$ satisfies $\sigma\in\Sigma_s$ if and only if $\sigma=c$.
\end{cproof}

