We say a $B$-module $M$ is a \emph{weight module} if 
\[ M = \bigoplus_{\frm \in \Maxspec(R)} M_\frm \quad\text{where}\quad M_\frm = \{ m \in M \mid \frm \cdot m = 0\}.\]
We call $M_\frm$ a \emph{weight space} for $M$. The \emph{support} of $M$ is defined as
\[ \supp(M) = \{ \frm \in \Maxspec(R) \mid M_\frm \neq 0\}.\]

The category of weight modules for $B$ is denoted by $(B,R)\wmod$. Let $\cO \in \Maxspec(R)/\ZZ^n$ be an orbit. We denote by $(B,R)\wmod_\cO$ the full subcategory of modules $M \in (B,R)\wmod$ such that $\supp(M) \subseteq \cO$. If $M \in (B,R)\wmod$, then $B_{\pm \be_i} M_{\frm} \subseteq M_{\sigma_i^{\pm 1}(\frm)}$ for each $\frm \in \supp(M)$ and each $i \in [n]$. It follows that
\[ (B,R)\wmod \simeq \prod_{\cO \in \Maxspec(R)/\ZZ^n} (B,R)\wmod_{\cO}.\]

Our goal will be to describe the simple objects of $(B,R)\wmod_\cO$ corresponding to a torsion-free orbit. Our results restrict to those of higher rank GWAs and, more generally, TGWAs of Cartan type $(A_1)^n$ \cite{MT}.

\begin{definition}\label{defn.ibreak}
Let $i \in [n]$. Set
\begin{align}\label{eq.css}
\css_i(B) = \Spec(R/H_iJ_i) = \{ \bp \in \Spec(R) \mid \bp \supset H_iJ_i
\}.
\end{align}
Then $\frm \in \Maxspec(M)$ is an \emph{$i$-break}, or \emph{break with respect to $i$}, if $\sigma_i(\frm) \in \css_i(B)$.
\end{definition}

The term ``$i$-break" here should not be confused with that of $j$-breaks and $h$-breaks in \cite{GRW1}.

\begin{lemma}\label{lem.invariant-breaks}
Let $\frm\in\Maxspec(M)$ be an $i$-break, and let $i\neq k\in[n]$. Then $\sigma_k^{\pm 1}(\frm)$ is also an $i$-break.
\end{lemma}
\begin{proof}
If $\sigma_i(\frm)\in \css_i(B)$, then $\sigma_i(\frm)\supset H_iJ_i$, so $\sigma_i(\sigma_k^{\pm 1}(\frm))=\sigma_k^{\pm 1}\sigma_i(\frm)\supset \sigma_k^{\pm 1}(H_iJ_i)=H_iJ_i$,
hence the result follows.
\end{proof}



\begin{proposition}\label{prop.dim-weight}
Suppose that $\cO=\ZZ^n\cdot \frm \subset \Maxspec(R)/\ZZ^n$ is a torsion-free orbit and $M\in (B,R)\wmodO$. 
\begin{enumerate}
    \item \label{dim1} If $w\in M_{\frm}$ is a weight vector and $N=B\cdot w\subseteq M$, then $\dim_{R/\bsigma^{\balpha}(\frm)}N_{\bsigma^{\balpha}(\frm)}\leq 1$ for all $\balpha\in \ZZ^n$.
    \item \label{dim2} If $M$ is simple, then 
    $\dim_{R/\bsigma^{\balpha}(\frm)}M_{\bsigma^{\balpha}(\frm)}\leq 1$ for all $\balpha\in \ZZ^n$.
\end{enumerate}
\end{proposition}
\begin{proof}
\eqref{dim1}
Since $\cO$ is a torsion-free orbit, we have $B_{\balpha} w=N_{\bsigma^{\balpha}(\frm)}$ for all $\balpha\in\ZZ^n$. Let $u, u'\in N_{\bsigma^{\balpha}(\frm)}$, then there exist $r,r'\in I^{(\balpha)}$ such that $u:=r\bt^{\balpha}\cdot w$, $u':=r'\bt^{\balpha}\cdot w$. It follows that
\[r' u-ru'= r'r\bt^{\balpha}w -rr'\bt^{\balpha}w=0,\]
hence $u$ and $u'$ are linearly dependent over $R$, and since $u', u\in N_{\bsigma^{\balpha}(\frm)}$, the linear dependence descends to show that $u$ and $u'$ are linearly dependent over $R/\bsigma^{\balpha}(\frm)$.

\eqref{dim2} For any nonzero weight vector $0\neq w\in M$, we have $B\cdot w= M$ because $M$ is simple. The result then follows from part \eqref{dim1}.
\end{proof}



\begin{lemma}\label{lem:cross-break}
Let $\cO$ be a torsion-free orbit and let $\frm\in\cO$ be an $i$-break. Let $M$ be a simple weight module. Then $B_{\be_i}M_{\frm} = 0$ and $B_{-\be_i}M_{\sigma_i(\frm)}=0$.
\end{lemma}
\begin{proof}
We prove that $B_{\be_i}M_{\frm} = 0$; the other proof is similar. If $M_{\frm} = 0$, then the statement is obvious. Now
let $0\neq w\in M_{\frm}$, and $j_i \in J_i$. Suppose that $w':=j_it_i\cdot w\neq 0$. Then for all $h_i \in H_i$ we have 
\[\sigma_i\inv(h_i)t_i\inv\cdot w'=\sigma_i\inv(h_i)t_i\inv j_it_i\cdot w=\sigma_i\inv(h_i)\sigma_i\inv(j_i)\cdot w=\sigma_i\inv(h_i j_i)\cdot w=0\]
where the last equality follows because $\frm$ is an $i$-break, which means that $\sigma_i\inv(H_i J_i) \subset \frm$.
Since $\cO$ is a torsion-free orbit, $(B w')_\frm=B_{-\be_i} w'=\sigma\inv(H_i)t_i\inv\cdot w'=0$, so $w\not\in B_{-\be_i}w'$. Hence $w\not\in B w'$ and so $0\neq B w'\subsetneq M$ is a nontrivial proper weight submodule, contradicting the simplicity of $M$.
\end{proof}

Let $\cO \in \Maxspec(R)/\ZZ^n$ be a torsion-free orbit and let $\beta_i\subseteq \cO$ be the set of $i$-breaks for some $i \in [n]$.
By Lemma \ref{lem.invariant-breaks}, there is an action of $\Gamma_i=\langle \sigma_1,\ldots,\sigma_{i-1},\sigma_{i+1},\ldots,\sigma_n\rangle\simeq \ZZ^{n-1}$ on $\beta_i$. We consider the set $\overline{\beta}_i=\beta_i/\Gamma_i$ and we think of the elements of $\overline{\beta}_i$ as hyperplanes, normal to the direction of $\be_i$, in the rank $n$ lattice given by $\cO$.
For each $i$, we define a partial order on $\cO$ by setting $\frm \prec_i \sigma_i(\frm)$ for all $\frm\in \cO$ and extending transitively. Notice that this ordering is well defined because $\cO$ is torsion-free. This partial order induces a total order on $\overline{\beta}_i$ by setting $[\frm]\prec_i[\frn]$ if there exist $\gamma_1,\gamma_2\in\Gamma_i$ with $\gamma_1(\frm)\prec_i\gamma_2(\frn)$. We define
\[
\overline{\beta}'_i = \begin{cases} \{\infty_i\} & \text{if $\overline{\beta}_i=\emptyset$} \\
\overline{\beta}_i\cup\{\infty_i\} 
    & \text{if $\overline{\beta}_i$ contains a maximal element with respect to $\prec_i$} \\
\overline{\beta}_i
    & \text{otherwise.}
\end{cases}\]
For $[\frn]\in\overline{\beta}_i'$, we let $[\frn]^-$ be the maximal element of $\overline{\beta}_i'$ such that $[\frn]^-\prec_i[\frn]$, or $[\frn]^-=-\infty_i$ if $[\frn]$ was a minimal element of $\overline{\beta}_i'$. We extend the partial ordering on $\cO$ to $\cO\cup\{\pm\infty_i\}$ in the obvious way, i.e., for all $\frm\in\cO$ we have $-\infty_i\prec_i \frm\prec_i \infty_i$. Also, by abuse of notation, for $\frm\in\cO$ and $[\frn]\in\overline{\beta}_i'$ we say that $\frm\preceq_i[\frn]$ (resp. $[\frn]\preceq_i \frm$) if there exists $\gamma\in\Gamma_i$ such that $\frm\preceq_i\gamma\frn$ (resp. $\gamma\frn\preceq_i\frm$). This denotes on which side of the hyperplane $[\frn]$ the lattice point $\frm$ sits, and in case of equality it means that $\frm\in[\frn]$ is a point on the hyperplane. We give an explicit example of picturing a torsion-free orbit and its breaks in Figure~\ref{fig2}.

