Our analysis of simple weight modules below follows \cite{hart1} for TGWAs. 
Let $\frm$ be a maximal ideal. Define
\[ G_\frm = \{ \balpha \in \ZZ^n \mid B_{-\balpha}B_\balpha \not\subset \frm \}.\]
In \cite{hart1}, this set was called $\widetilde{G_\frm}$.  



\begin{lemma}\label{lem.Gm}
Let $\frm\in\cO$, then there exists a unique $n$-tuple $([\frn_1],\ldots,[\frn_n])\in \prod_{i=1}^n\overline{\beta}'_i$ such that $[\frn_i]^-\prec_i\frm\preceq_i[\frn_i]$ for all $i$. Then 
\[G_\frm=\{\balpha\in\ZZ^n~|~[\frn_i]^-\prec_i\sigma_i^{\alpha_i}(\frm)\preceq_i[\frn_i]\quad\text{for all }i=1,\ldots,n\}.\]
\end{lemma}
\begin{proof}
Recall that $B_\balpha=I^{(\balpha)}t^{\balpha}=\prod_i I_i^{\alpha_i}t_i^{\alpha_i}$, and $B_{-\balpha}=I^{(-\balpha)}t^{-\balpha}=\prod_i I_i^{-\alpha_i}t_i^{-\alpha_i}$, then
\[ B_{-\balpha}B_\balpha=\left(\prod_i I_i^{-\alpha_i}t_i^{-\alpha_i}\right)\left(\prod_i I_i^{\alpha_i}t_i^{\alpha_i}\right)=\prod_iI_i^{-\alpha_i}\sigma_i^{-\alpha_i}\left(I_i^{\alpha_i}\right).\]
Since $\frm$ is maximal, $B_{-\balpha}B_\balpha\subset\frm$ if and only if there is $i$ such that $I_i^{-\alpha_i}\sigma_i^{-\alpha_i}\left(I_i^{\alpha_i}\right)\subset \frm$. Equivalently,  $B_{-\balpha}B_\balpha\not\subset\frm$ if and only for all $i$, $I_i^{-\alpha_i}\sigma_i^{-\alpha_i}\left(I_i^{\alpha_i}\right)\not\subset \frm$. We have
\[
I_i^{-\alpha_i}\sigma_i^{-\alpha_i}\left(I_i^{\alpha_i}\right)
    = \begin{cases}
    R & \text{ if }\alpha_i=0 \\ 
    \prod_{k=1}^{\alpha_i} \sigma_i^{-k}(H_iJ_i) & \text{ if }\alpha_i>0 \\ 
    \prod_{k=1}^{-\alpha_i} \sigma_i^{k-1}(H_iJ_i) & \text{ if }\alpha_i<0.\end{cases}\]
Let $\balpha=(\alpha_1,\ldots,\alpha_n)\in G_\frm$. If for an index $i$ we have $\alpha_i=0$, then this is the same as $R\not\subset\frm$, which is always satisfied just like the fact that $[\frn_i]^-\prec_i\sigma_i^{0}(\frm)\preceq_i[\frn_i]$ is always true. If $\alpha_i>0$, then this says that 
\begin{align*}
\prod_{k=1}^{\alpha_i} \sigma_i^{-k}(H_iJ_i)\not\subset\frm & \iff \sigma_i^{-k}(H_iJ_i)\not\subset\frm \qquad \forall~k=1,\ldots,\alpha_i \\
& \iff H_iJ_i\not\subset\sigma_i(\sigma_i^{k-1}(\frm)) \qquad \forall~k=1,\ldots,\alpha_i \\
& \iff\sigma_i^{k-1}(\frm) \text{ is not an $i$-break }\qquad \forall ~k=1,\ldots,\alpha_i \\ 
& \iff \sigma_i^{k-1}(\frm)\prec_i[n_i] \qquad \forall~k=1,\ldots,\alpha_i \\ 
& \iff \sigma_i^{k}(\frm)\preceq_i[n_i]\qquad \forall~k=0,\ldots,\alpha_i.
\end{align*}
Finally, if $\alpha_i<0$, then this says that 
\begin{align*}\prod_{k=1}^{-\alpha_i} \sigma_i^{k-1}(H_iJ_i)\not\subset\frm & \iff \sigma_i^{k-1}(H_iJ_i)\not\subset\frm \qquad \forall~k=1,\ldots,-\alpha_i \\
& \iff H_iJ_i\not\subset\sigma_i(\sigma_i^{-k}(\frm)) \qquad \forall~k=1,\ldots,-\alpha_i \\
& \iff\sigma_i^{k}(\frm) \text{ is not an $i$-break }\qquad \forall ~k=-1,\ldots,\alpha_i \\ 
& \iff [n_i]^-\prec_i \sigma_i^{k}(\frm) \qquad \forall~k=-1,\ldots,\alpha_i.
\qedhere\end{align*}
\end{proof}
\begin{definition}\label{def.balpha}
Let $\frm$ be a maximal ideal. For every $\balpha \in G_\frm$, since $B_{-\balpha} B_\balpha\not\subset\frm$, we choose $b_\balpha \in B_\balpha$ and $b_\balpha^* \in B_{-\balpha}$ such that $b_\balpha^* b_\balpha \notin \frm$.
As $\frm$ is maximal, then there exists $r \in R$ such that $1-rb_\balpha^*b_\balpha \in \frm$. Set $b_\balpha' = rb_\balpha^* \in B_{-\balpha}$ so that 
\begin{align}\label{eq.brel}
    b_\balpha'b_\balpha \equiv 1 \pmod{\frm}.
\end{align}
\end{definition}

\begin{lemma}\label{lem:basis}
Let $M$ be a simple weight module over $B$, such that $M_\frm\neq 0$, and let $0\neq v_{\frm}\in M_\frm$ be a weight vector, so that $\{v_\frm\}$ is a $\kk$-basis for $M_\frm$. Then the set 
$\{b_\balpha v_\frm~|~\balpha \in G_\frm\}$
is a basis for $M$ over $\kk$.
\end{lemma}
\begin{proof}First of all, notice that $b_\balpha v_\frm\neq 0$ for all $\balpha\in G_\frm$ because, since $b'_{\balpha} b_\balpha\equiv 1 \pmod{\frm}$, we have
$$b'_\balpha(b_\balpha v_{\frm})=(b'_\balpha b_\balpha )v_{\frm}=v_{\frm}\neq 0.$$
Then, for $\balpha\neq \bbeta$ we have that $b_\balpha v_\frm$ and $b_\bbeta v_\frm$ belong to the different weight spaces $M_{\bsigma^{\balpha}(\frm)}$ and $M_{\bsigma^{\bbeta}(\frm)}$ respectively, so they are linearly independent over $R$, hence over $\kk$. Further, by Proposition \ref{prop.dim-weight}, since each weight space of $M$ is one-dimensional, $\{b_\balpha v_\frm\}$ is a $R/\bsigma^{\balpha}(\frm)$-basis for $M_{\bsigma^{\balpha}(\frm)}$ for all $\balpha\in G_\frm$. All that is left to prove, then, is that if $\bgamma\in \ZZ^n\setminus G_\frm$, then $M_{\bsigma^\bgamma(\frm)}=0$. Let $\bgamma=(\gamma_1,\ldots,\gamma_n)\in \ZZ^n\setminus G_\frm$, then by Lemma \ref{lem.Gm} there is an $i$ such that either $\sigma_i^{\gamma_i}(\frm)\succ_i[\frn_i]$ or such that $\sigma_i^{\gamma_i}(\frm)\preceq_i[\frn_i]^-$ (notice that for this $i$, $\gamma_i \neq 0$). We suppose we are in the first of these two cases and therefore that $\gamma_i>0$, the proof for the other case (with $\gamma_i<0$) being analogous. Let $0\leq k<\gamma_i$ be such that $\bsigma_i^{k}(\frm)\in[\frn_i]$, so that in particular $\bsigma_i^{k}(\frm)$ is an $i$-break. We have
\[
M_{\bsigma^{\bgamma}(\frm)}=B_{\bgamma}v_\frm=\left(\prod_{j=1}^n B_{\gamma_j\be_j}\right)v_{\frm}=\left(\prod_{j\neq i} B_{\gamma_j\be_j}\right)B_{\gamma_i\be_i}v_{\frm}=\left(\prod_{j\neq i} B_{\gamma_j\be_j}\right)B_{(\gamma_i-k-1)\be_i}B_{\be_i}B_{k\be_i}v_{\frm}.
\]
Now, $B_{k\be_i}v_{\frm}=M_{\sigma_i^{k}(\frm)}$ and, since $\sigma_i^{k}(\frm)$ is an $i$-break we have by Lemma \ref{lem:cross-break} that 
$$B_{\be_i}B_{k\be_i}v_{\frm}=B_{\be_i} M_{\sigma_i^{k}(\frm)}=0$$
hence $M_{\bsigma^{\bgamma}(\frm)}=0$.
\end{proof}




