The following lemma is an analogue of \cite[Prop 7.2]{MPT}.

\begin{lemma}\label{lem:exist}Let $\frm$ be a maximal ideal, then there exists a simple weight module $M$ over $B$ such that $M_\frm\neq 0$.
\end{lemma}
\begin{proof}Define the left $B$-module $N:=B\otimes_R R/\frm=\bigoplus_{\balpha\in\ZZ^n}B_\balpha\otimes_R R/\frm$. Let $r\in R$, and let $0\neq x_\balpha t^{\balpha}\in B_\balpha$, then
$$r\cdot x_\balpha t^\balpha\otimes (1_R+\frm)=x_{\balpha} t^{\balpha}\otimes \bsigma^{-\balpha}(r)(1_R+\frm)$$
which equals zero if and only if $\bsigma^{-\balpha}(r)\in\frm$ if and only if $r\in\sigma^{\balpha}(\frm)$. This proves that $N$ is a weight module, with $N_{\bsigma^{\balpha}(\frm)}=B_\balpha\otimes_R R/\frm$. Further, we have that $N_\frm=B_{\bzero}\otimes_R R/\frm=R\otimes_R R/\frm\simeq R/\frm\neq 0$ is a nonzero weight space and $N=BN_\frm$. Now define a weight submodule 
$$N':=\left\{\sum S~|~S\subset N \text{ is a weight submodule and }S\cap N_\frm=0\right\}.$$ We claim that $M=N/N'$ is the required simple weight module for $B$ with $M_\frm\neq 0$. Since $N'_{\frm}=0$, it is clear that $M_\frm\neq 0$. Suppose we have a non trivial weight submodule $0\neq K\subseteq N/N'$. This is the same as a weight submodule $N'\subsetneq K\subseteq N$, but since $N'\subsetneq K$ we have $K_\frm\neq 0$, which implies that $K_\frm=N_\frm=B_{\bzero}\otimes_R R/\frm$, hence $K=BK\supset BK_\frm=BN_\frm=N$, which implies that $K=N$. This proves that $M=N/N'$ is indeed a simple weight module.
\end{proof}


\begin{theorem}\label{thm.weight}
Let $\cO\in\Maxspec(R)/\ZZ^n$ be a torsion-free orbit, let $\beta_i \subseteq \cO$ be the set of $i$-breaks for each $i$, and keep the notation above. The isomorphism classes of simple modules in $(B,R)\wmodO$ are in bijection with the set $\prod_{i=1}^n\overline{\beta}'_i$. If $M\in (B,R)\wmodO$ is simple, it corresponds to the unique $n$-tuple $([\frn_1],\ldots,[\frn_n])\in \prod_{i=1}^n\overline{\beta}'_i$ such that $\supp(M)=\{\frm\in\cO~|~[\frn_i]^-\prec_i\frm\preceq_i[\frn_i]\text{ for all }i=1,\ldots,n\}$.
\end{theorem}
\begin{proof}
Consider the map from isomorphism classes of simple weight modules to $n$-tuples of breaks as in the statement. This map is well defined because, by Lemma \ref{lem:basis}, if $M$ is a simple weight module with $M_{\frm}\neq 0\neq M_{\frm'}$, then $\frm'=\bsigma^{\bbeta}(\frm)$ for some $\bbeta\in G_{\frm}$, hence, by Lemma \ref{lem.Gm}, $\frm'$ satisfies the same inequalities with respect to the breaks $[\frn_i]$ as $\frm$ does. Also, this map is surjective by Lemma \ref{lem:exist}, so we only need to show that it is injective. Suppose that we have two simple weight modules $M$ and $M'$ that map to the same $n$-tuple of breaks, then they have the same support. Let $\frm$ be a maximal ideal such that $M_\frm\neq 0\neq M'_\frm$ and we can choose $b_\balpha$, $\balpha\in G_\frm$, and $0\neq v_\frm\in M_\frm$, $0\neq v'_\frm\in M'_\frm$ such that $\{b_\balpha v_\frm~|~\balpha\in G_\frm\}$ is a $\kk$-basis for $M$ and $\{b_\balpha v'_\frm~|~\balpha\in G_\frm\}$ is a $\kk$-basis for $M'$. Then, the map defined by $b_\balpha v_\frm\mapsto b_\balpha v'_\frm$ for all $\balpha\in G_\frm$ is the required isomorphism of weight modules.
\end{proof}


\begin{definition}
\label{def.simplemod}
For each $\underline{[\frn]}=([\frn_1],\ldots,[\frn_n])\in \prod_{i=1}^n\overline{\beta}'_i$, denote by $M(\cO,\underline{[\frn]})$ the corresponding simple weight module.
\end{definition}


We can give a somewhat explicit description of the structure constants for the action of $B$ on $M(\cO,\underline{[\frn]})$, depending on the choice of $b_\balpha,b'_\balpha$, compare the following result to \cite[Thm 5.4]{hart1} for TGWAs.

\begin{proposition}
    Let $\underline{[\frn]}=([\frn_1],\ldots,[\frn_n])\in \prod_{i=1}^n\overline{\beta}'_i$. 
    Choose $\frm$ to be a maximal ideal such that $[\frn_i]^-\prec_i\frm\preceq_i[\frn_i]$ for all $i$, and choose $b_\balpha,b'_\balpha$, $\balpha\in G_\frm$ as in Definition \ref{def.balpha}. We have an isomorphism of $R$-modules
\[M(\cO,\underline{[\frn]})\simeq\bigoplus_{\balpha\in G_\frm}\left(R/\bsigma^{\balpha}(\frm)\right)( v_{\frm,\balpha})\qquad \]
 with $B$-action defined by 
\[
j_it_i  v_{\frm,\balpha} = \begin{cases}
    j_i x_{\balpha,i} v_{\frm,\balpha+\be_i} & \balpha+\be_i \in G_\frm \\
     0 & \text{otherwise,}
 \end{cases} \qquad
\sigma_i\inv(h_i)t_i\inv  v_{\frm,\balpha} = \begin{cases}
    \sigma_i\inv(h_i)y_{\balpha,i} v_{\frm,\balpha-\be_i} & \balpha-\be_i \in G_\frm \\
     0 & \text{otherwise,}
 \end{cases}
\]
for all $j_i \in J_i$ and $h_i \in H_i$
where $x_{\balpha,i} = t_i b_\balpha b_{\balpha+\be_i}'$
and
$y_{\balpha,i} = t_i\inv b_\balpha b_{\balpha-\be_i}'$ are elements of $B_\bzero=R$.
\end{proposition}
\begin{proof}
Let $\frm$ be a maximal ideal as in the statement, and choose $b_\balpha, b'_\balpha$ for $\balpha\in G_\frm$. Let $0\neq v_\frm$ be any vector in $M(\cO,\underline{[\frn]})_\frm$, and define $v_{\frm,\balpha}:=b_\balpha v_\frm$ for all $\balpha\in G_\frm$. By Lemma \ref{lem:basis}, $\{v_{\frm,\balpha}~|~\balpha\in G_\frm \}$ is a $\kk$-basis of $M(\cO,\underline{[\frn]})$, and since $b_\balpha\in B_\balpha$, it is clear that $v_{\frm,\balpha}\in M(\cO,\underline{[\frn]})_{\sigma^{\balpha}(\frm)}$, hence the isomorphism as $R$-modules.
Now, if $\balpha\in G_\frm$, $\balpha+\be_i\not\in G_\frm$, then $\bsigma^{\balpha}(\frm)$ is an $i$-break by Lemma \ref{lem.Gm}, hence by Lemma \ref{lem:cross-break} we have indeed that $j_it_i  v_{\frm,\balpha}=0$. If $\balpha+\be_i\in G_\frm$, then, since $b_{\balpha+\be_i}'b_{\balpha+\be_i}\equiv 1 \pmod \frm$,
$$ j_it_i  v_{\frm,\balpha}=j_it_i b_{\balpha} v_{\frm}=j_it_ib_{\balpha}b_{\balpha+\be_i}'b_{\balpha+\be_i}v_{\frm}=j_i x_{\balpha,i} v_{\frm,\balpha+\be_i}.$$
If $\balpha\in G_\frm$, $\balpha-\be_i\not\in G_\frm$, then $\sigma_i\inv\sigma^{\balpha}(\frm)$ is an $i$-break by Lemma \ref{lem.Gm}, hence by Lemma \ref{lem:cross-break} we have indeed that $\sigma_i\inv(h_i)t_i\inv  v_{\frm,\balpha}=0$. If $\balpha-\be_i\in G_\frm$, then, since $b_{\balpha-\be_i}'b_{\balpha-\be_i}\equiv 1 \pmod \frm$,
\[\sigma_i\inv(h_i)t_i\inv  v_{\frm,\balpha}=\sigma_i\inv(h_i)t_i\inv b_{\balpha} v_{\frm}=\sigma_i\inv(h_i)t_i\inv b_{\balpha}b_{\balpha-\be_i}'b_{\balpha-\be_i}v_{\frm}=  \sigma_i\inv(h_i)y_{\balpha,i} v_{\frm,\balpha-\be_i}.\qedhere\]
\end{proof}





Let $M\in (B,R)\wmodO$ with $\cO=\ZZ^n\cdot \frm$ a torsion-free orbit. As in the rank one case \cite{GRW1}, $M$ may be given the structure of a $\ZZ^n$-graded $B$-module by defining $M_\balpha=M_{\sigma^\balpha(\frm)}$ for all $\balpha\in\ZZ^n$. The grading, however, is not canonical. Choosing different points in the orbit to correspond to $\bzero$ recovers shifts of $M$ in the graded module category. However, as shown in \cite{GRW1}, a (non-simple) graded module need not necessarily be an $R$-weight module. 

\begin{proposition}
Let $M$ be a simple $\ZZ^n$-graded $B$-module. Then $M$ is an $R$-weight module.
\end{proposition}
\begin{proof}
Write $M=\bigoplus_{\balpha\in\ZZ^n}M_\balpha$ so that $B_\bbeta M_\balpha\subseteq M_{\balpha+\bbeta}$ for all $\balpha,\bbeta \in \ZZ^n$. If $\balpha\in\ZZ^n$ such that $M_\balpha\neq 0$, then $M_\balpha$ is an $R$-submodule since $RM_\balpha=B_\bzero M_\balpha\subseteq M_\balpha$. We claim $M_\balpha$ is a simple $R$-module. 

Suppose $N_\balpha$ is a proper, nontrivial submodule of $M_\balpha$. Note that $(BN_\balpha)_\balpha=N_\balpha$ and $0\neq BN_\balpha\subsetneq M$, so $BN_\balpha$ is a nontrivial $B$-submodule of $M$, contradicting the simplicity of $M$. This proves the claim, so $M_\balpha\simeq R/\frm$ as $R$-modules for some $\frm\in\Maxspec(R)$. 

By simplicity, $M=BM_\balpha$. Hence, for all $\bbeta \in \ZZ^n$, $M_\bbeta = B_{\bbeta-\balpha}M_\balpha$. 
If $r\in \bsigma^{\bbeta-\balpha}(\frm)$, then $\bsigma^{\balpha-\bbeta}(r) \in \frm$, so
\[rM_\bbeta=rB_{\bbeta-\balpha}M_\balpha=B_{\bbeta-\balpha}\sigma^{\balpha-\bbeta}(r)M_\balpha=0.\]
Thus, $M_\bbeta\subseteq M_{\bsigma^{\bbeta-\balpha}(\frm)}$ and so
\[M=\bigoplus_{\bbeta\in \ZZ^n}M_\bbeta\subseteq \bigoplus_{\bbeta\in\ZZ^n}M_{\bsigma^{\bbeta-\balpha}(\frm)}\subseteq M.\]
It follows that $M=\bigoplus_{\bbeta\in\ZZ^n}M_{\bsigma^{\bbeta-\balpha}(\frm)}$ is a weight module.
\end{proof}

\section{Twisted tensor products of BR algebras}
\label{sec.twtensor}

The goal of this section is to show that the class of BR algebras is closed under taking certain twisted tensor products. Restricting to ordinary tensor products then gives new examples of $\ZZ^n$-graded simple rings.

\begin{definition}[\cite{cap}]\label{def.twtensor}
Let $B$ and $D$ be algebras with multiplication maps $\mu_B$ and $\mu_D$, respectively. A \emph{twisted tensor product} of $B$ and $D$ is an algebra $W$ along with injections $\iota_B:B \to W$ and $\iota_D:D \to W$ such that there is a linear isomorphism $B \tensor D \to W$ given by $b \tensor d \mapsto \iota_B(b) \cdot \iota_D(d)$.
A \emph{twisting map} for the pair $(B,D)$ is a $\kk$-linear map $\tau:D \tensor B \to B \tensor D$ such that $\tau(d \tensor 1)=1 \tensor d$ and $\tau(1 \tensor b) = b \tensor 1$. 
\end{definition}

Given a twisting map for algebras $B$ and $D$, one can define a twisted tensor product as follows. Let $W = B \otimes D$ (as a $\kk$-vector space) and define a map $\mu_W: W \otimes W \to W$ by
\[ 
\mu_W : = (\mu_B \tensor \mu_D) \circ (1_B \tensor \tau \tensor 1_D).
\] 
By \cite[Proposition 2.3]{cap}, $\mu_W$ defines an associative multiplication operation on $C$ if and only if
\[ \tau \circ (\mu_D \tensor \mu_B) 
    = \mu_W \circ (\tau \tensor \tau) \circ (1_D \tensor \tau \tensor 1_B)
    = (\mu_B \tensor \mu_D) \circ (1_B \tensor \tau \tensor 1_D)\circ (\tau \tensor \tau) \circ (1_D \tensor \tau \tensor 1_B).
\]
If this holds, then $W$ is a twisted tensor product of $B$ and $D$ with canonical injections $\iota_B: B \to B \otimes D$ and $\iota_D: D \to B \otimes D$. We write $W = B \otimes_{\tau} D$ for this twisted tensor product.

We will assume the following hypothesis throughout this section.

\begin{hypothesis}\label{hyp.twtensor}
Let $R$ and $S$ be algebras. Let $A = R_\bp[\bu^{\pm 1};\bsigma]$ be a skew Laurent extension over $R$ and let $B = R_{\bp}(\bu,\bsigma,\bH,\bJ) \subseteq A$ a BR algebra of rank $m$ with canonical ideals $I^{(\balpha)}$ for $\balpha \in \ZZ^m$.
Let $C = S_{\bq}[\bv^{\pm 1};\bphi]$ be a skew Laurent extension over $S$ and let $D = S_{\bq}(\bv,\bphi,\bK,\bL) \subset C$ be a BR algebra of rank $n$ with canonical ideals $\cI^{(\bbeta)}$ for $\bbeta \in \ZZ^n$. 
Set $\bsigma = (\sigma_1, \dots, \sigma_m)$ and $\bphi = (\varphi_1, \dots ,\varphi_n)$. For each $i \in [m]$, suppose that $\sigma_i$ lifts to an automorphism $\widetilde{\sigma_i}$ of $R \otimes S$ such that $\widetilde{\sigma_i}(1 \otimes \cI^{(\bbeta)}) \subseteq 1 \otimes \cI^{(\bbeta)}$ for all $\bbeta \in \ZZ^n$.
Similarly, suppose that for each $k \in [n]$, $\varphi_k$ lifts to an automorphism $\widetilde{\varphi_k}$ of $R \otimes S$ such that $\widetilde{\varphi_k}(I^{(\balpha)} \otimes 1) \subseteq I^{(\balpha)} \otimes 1$ for all $\balpha \in \ZZ^m$.
Assume further that all of the $\widetilde{\sigma_i}$ and $\widetilde{\varphi_k}$ commute with one another.
\end{hypothesis}


\begin{remark}\label{rmk.autrestr}
Assume Hypothesis~\ref{hyp.twtensor}. 
\begin{enumerate}
    \item One may always lift the $\sigma_i$ and $\varphi_k$ trivially to commuting automorphisms $\widetilde{\sigma_i} = \sigma_i \otimes \id_S$ and $\widetilde{\varphi_k} = \id_R \otimes \varphi_k$.
    \item By taking $\bbeta = \bzero$, it is clear that the restriction of $\widetilde{\sigma_i}$ to $1 \otimes S$ yields an automorphism of $S$, which we also denote by $\widetilde{\sigma_i}$ by an abuse of notation. Similarly, the restriction of $\widetilde{\varphi_k}$ to $R \otimes 1$ yields an automorphism of $R$.
\end{enumerate}
\end{remark}

For $i \in [m]$ and $k \in [n]$, choose $d_{ik} \in \kk^\times$. For $\bbeta \in \ZZ^m$ and $\balpha \in  \ZZ^n$, define 
\begin{align}\label{eq.dba}
d_{\bbeta,\balpha} = \prod_{\substack{\beta_i \in \bbeta \\ \alpha_k \in \balpha}} {d_{ik}^{\beta_i\alpha_k}}.
\end{align}
We define a $\kk$-linear map $\tau: C \tensor A \to A \tensor C$ as follows. If $b_{\bbeta} u^{\bbeta} \in A_{\bbeta}$ and $a_{\balpha} v^{\balpha} \in C_{\balpha}$, then
\begin{align}\label{eq.SLtau}
\tau( a_\balpha \bv^\balpha \tensor b_\bbeta \bu^\bbeta) = d_{\bbeta,\balpha} \widetilde{\bphi}^\balpha(b_\bbeta) \bu^\bbeta \tensor \widetilde{\bsigma}^{-\bbeta}(a_\balpha) \bv^\balpha,
\end{align}
where $\widetilde{\bphi}^\balpha = \widetilde\varphi_1^{\alpha_1} \cdots \widetilde\varphi_n^{\alpha_n}$ and $\widetilde{\bsigma}^{-\bbeta} = \widetilde\sigma_1^{-\beta_1} \widetilde\cdots \sigma_m^{-\beta_m}$. 
The map $\tau$ restricts to a well-defined map $D \tensor B \to B \tensor D$ by our assumption on the automorphisms $\widetilde{\sigma_i}$ and $\widetilde{\varphi_k}$ preserving the canonical ideals.

\begin{lemma}
The map $\tau$ defined in \eqref{eq.SLtau} satisfies the associativity conditions.
\end{lemma}
\begin{proof}
Let $a_\balpha,b_\bbeta,c_\bgamma,d_\bdelta$ belong to the correct rings. Then
\begin{align*}
(\mu_B &\tensor \mu_{\cB})(1 \tensor \tau \tensor 1)(\tau \tensor \tau)(1 \tensor \tau \tensor 1)(a_\balpha \bv^\balpha \tensor b_\bbeta \bv^\bbeta \tensor c_\bgamma \bu^\bgamma \tensor d_\bdelta \bu^\bdelta) \\
	&= d_{\bbeta,\bgamma}(\mu_A \tensor \mu_B)(1 \tensor \tau \tensor 1)(\tau \tensor \tau)(a_\balpha \bv^\balpha \tensor \widetilde{\bphi}^\bbeta(c_\bgamma) \bu^\bgamma \tensor \widetilde{\bsigma}^{-\bgamma}(b_\bbeta) \bv^\bbeta  \tensor d_\bdelta \bu^\bdelta) \\
	&= d_{\bbeta,\bgamma}d_{\balpha,\bgamma}d_{\bbeta,\bdelta}(\mu_A \tensor \mu_B)(1 \tensor \tau \tensor 1)(\widetilde{\bphi}^{\balpha+\bbeta}(c_\bgamma) \bu^\bgamma \tensor \widetilde{\bsigma}^{-\bgamma}(a_\balpha) \bv^\balpha \tensor \widetilde{\bphi}^{\bbeta}(d_\bdelta) \bu^\bdelta   
    \tensor  \widetilde{\bsigma}^{-(\bgamma+\bdelta)}(b_\bbeta) \bv^\bbeta) \\
	&= d_{\balpha+\bbeta,\bgamma+\bdelta}(\mu_B \tensor \mu_{\cB})( 
    \widetilde{\bphi}^{\balpha+\bbeta}(c_\bgamma) \bu^\bgamma \tensor \widetilde{\bphi}^{\balpha+\bbeta}(d_\bdelta) \bu^\bdelta 
    \tensor \widetilde{\bsigma}^{-(\bgamma+\bdelta)}(a_\balpha) \bv^\balpha \tensor   
    \widetilde{\bsigma}^{-(\bgamma+\bdelta)}(b_\bbeta) \bv^\bbeta) \\
	&= d_{\balpha+\bbeta,\bgamma+\bdelta} \left( \widetilde{\bphi}^{\balpha+\bbeta}(c_\bgamma\widetilde{\bsigma}^\bgamma(d_\bdelta)) \bu^{\bgamma+\bdelta} \tensor 
	\widetilde{\bsigma}^{-(\bgamma+\bdelta)}(a_\balpha\widetilde{\bphi}^\balpha(b_\bbeta)) \bv^{\balpha+\bbeta} \right) \\
    &= \tau\left( a_\balpha \widetilde{\bphi}^\balpha(b_\bbeta) \bv^{\balpha+\bbeta} \tensor c_\bgamma\widetilde{\bsigma}^\bgamma(d_\bdelta) \bu^{\bgamma+\bdelta} \right) \\
    &= \tau \circ (\mu_{\cB} \tensor \mu_B)(a_\balpha \bv^\balpha \tensor b_\bbeta \bv^\bbeta \tensor c_\bgamma \bu^\bgamma \tensor d_\bdelta \bu^\bdelta).\qedhere
\end{align*}
\end{proof}

We now construct a BR algebra $W$ and show that $B \tensor_\tau D \iso W$.
Let $\bd=(d_{ij})$ and set
\[ \br = \begin{pmatrix}\bp & \bd \\ \bd^T & \bq\end{pmatrix}.\]
Set $\bpi=(\pi_1,\hdots,\pi_{m+n})$ where $\pi_i$ is the extension of $\sigma_i$ to $R \tensor S$ for $i\in [m]$ and $\pi_{m+j}$ is the extension of $\varphi_j$ for $j \in [n]$. 
The $\pi_i$ then commute by hypothesis. Let $(R \tensor S)_\br[\bt^{\pm 1},\bpi]$ be the rank $m+n$ skew Laurent extension corresponding to this data.

\begin{lemma}\label{lem.twtensor}
Keep the above notation and let $\tau$ be as in \eqref{eq.SLtau}. Then $A\tensor_\tau C \iso (R \tensor S)_\br[\bt^{\pm 1},\bpi]$.
\end{lemma}
\begin{proof}
Define a map $\phi:(R \tensor S)_\br[\bt^{\pm 1},\bpi] \to A\tensor_\tau  C$ that is the identity on $R \tensor S$ and
\[
\phi(t_i) = \begin{cases}
    u_i \tensor 1 & \text{if $i\leq m$} \\
    1 \tensor  v_{i-m} & \text{if $m < i \leq m+n$.}
\end{cases}
\]
If suffices to check $\phi$ on the defining relations of $(R \tensor S)_\br[\bt^{\pm 1},\bpi]$. For $i \leq m$ we have
\begin{align*}
    \phi(t_i)\phi(r \tensor r') - \phi(\pi_i(r \tensor r'))\phi(t_i).
\end{align*}
A similar result holds for $i > m$.
If $i,k \leq m$, then it is clear that $\phi(t_k)\phi(t_i) = r_{ik}\phi(t_i)\phi(t_k)$,
as is the case when $i,k>m$. Finally, for $i \leq m$ and $k > m$, we have
\[ \phi(t_k)\phi(t_i) 
    = (1 \tensor v_{k-m}) \tensor (u_i \tensor 1)
    = d_{\be_i,\be_{k-m}} t_i \tensor t_{k-m}
    = r_{ik} (u_i \tensor 1) \tensor (1 \tensor v_{k-m})
    = r_{ik} \phi(t_i)\phi(t_k).
\]
The result follows.
\end{proof}

Now define tuples of ideals $\bM$ and $\bN$ of $R \tensor S$ as follows: 
\begin{align*}
\bM &= (M_1,\ldots, M_{m+n}) = (H_1 \tensor S,\hdots,H_m\tensor S,R \tensor K_1,\hdots,R \tensor K_n) \\
\bN &= (N_1,\ldots, N_{m+n}) =  (J_1 \tensor S,\hdots,J_m\tensor S,R \tensor L_1,\hdots,R \tensor L_n).
\end{align*}
By hypothesis, the $\pi_i$ commute. Moreover, $\pi_i(M_k)=M_k$ and $\pi_i(N_k)=N_k$ for $i \neq k$. Define the BR algebra $W = (R \tensor S)_\br(\bs,\bpi,\bM,\bN)$, which is a subalgebra of $(R \tensor S)_\br[\bs^{\pm 1},\bpi]$.

\begin{theorem}\label{thm.twtensor}
Assume Hypothesis \ref{hyp.twtensor} and let $\tau$ be as in \eqref{eq.SLtau}. Then $B \tensor_\tau D \iso W$.
\end{theorem}
\begin{proof}
It is clear that $B \tensor_\tau D$ is a subalgebra of $A \tensor_\tau C$. Let $\phi$ be the map given in Lemma \ref{lem.twtensor} and consider the restriction $\Phi=\phi\restrict{W}$. By Remark \ref{rmk.autrestr}(2), $\Phi$ is a well-defined map $W \to B \tensor_\tau D$. That $\Phi$ is injective follows from the injectivity of $\phi$. 

Let $j_i \in J_i$ so that $j_iu_i$ is a generator for $B$, $1 \leq i \leq m$. Then $j_i \tensor 1 \in N_i$ so $\Phi((j_i \tensor 1)t_i) = j_iu_i \tensor 1$. Similarly we obtain $\sigma_i\inv(h_i)u_i\inv \tensor 1 \in \im\Phi$ for each $i$ and all $h_i \in H_i$, as well as $1 \tensor l_iv_i, 1 \tensor \varphi_i\inv(k_i)v_i\inv \in \im\Phi$ for all $i$, $1 \leq i \leq n$ and all $l_i \in L_i$, $k_i \in K_i$. It follows from Lemma \ref{lem.BRgen} that the subalgebras $B \tensor 1$ and $1 \tensor D$ are in the image of $\Phi$.

Now let $\sum b_\bbeta \tensor d_\bdelta \in B \tensor_\tau D$ where $\bbeta$ ranges over $\ZZ^m$ and $\bdelta$ ranges over $\ZZ^n$. For each $\bbeta$, $b_\bbeta \in B_\bbeta$ and so $b_\bbeta \tensor 1 \in B \tensor_\tau D$. Similarly, $1 \tensor d_\bdelta \in B \tensor_\tau D$. 
It follows from \eqref{eq.SLtau} that $b_\bbeta \tensor d_\bdelta = (b_\bbeta \tensor 1)(1 \tensor d_\bdelta) \in B \tensor_\tau D$. Thus, $\Phi$ is surjective.
\end{proof}

\begin{corollary}\label{cor.tensor}
Assume Hypothesis \ref{hyp.twtensor}. Then the (untwisted) tensor product $B \tensor D$ is a BR algebra of rank $m+n$.
\end{corollary}

We now construct new examples of $\ZZ^n$-graded simple rings, for all $n \geq 1$. 

\begin{proposition}
[{\cite[Proposition 2.18 (3)]{BR}}, {\cite[Proposition 2.3]{GRW1}}]
\label{prop.simple}
Let $B=R(t,\sigma,H,J)$ be a BR algebra of rank one and set $\css(B)=\css_1(B)$. Then $B$ is simple if and only if 
\begin{itemize}
    \item $R$ has no proper, nontrivial $\sigma$-invariant ideals ($R$ is $\sigma$-simple), and
    \item $\sigma^i(\css(B))\cap\css(B) = \emptyset$ for all $i \neq 0$ ($B$ is $\sigma$-lonely).
\end{itemize}
\end{proposition}

\begin{example}
Set $R=\kk[u^{\pm 1},v^{\pm 1}]$ and define $\sigma \in \Aut(R)$ by $\sigma(u)=pu$ and $\sigma(v)=qv$ with $p,q \in \kk^\times$ such that $G=\grp{p,q}$ is a torsion-free abelian group of rank two. Then $R$ is $\sigma$-simple \cite[Theorem 2.4]{sham}. Set $H=R$ and $J=(u+v,(u+1)^2)$. It is clear that $\css(B)=\{ (u+1,v-1) \}$. Then $\sigma^i(\css(B)) = \{ (u+p^{-i},v-q^{-i}) \}$, so $B$ is $\sigma$-lonely. It follows that $B=R(t,\sigma,H,J)$ is simple.

Since we have assumed that $G$ is torsion-free, then $\sigma$ has infinite order. Hence, by \cite[Lemma 2.1]{GRW1}, $\cnt(B)=\cnt(R)^{\grp{\sigma}}$. An easy check shows that $\cnt(R)^{\grp{\sigma}}=\kk$. It is well-known that the tensor product of two simple algebras, one of which is central simple, is again simple. Thus, $A=\bigotimes_{k=1}^n B$ is a simple BR algebra of rank $n$ by Corollary \ref{cor.tensor}.
\end{example}


\section{A simplicity criterion}
\label{sec.simplicity}

In what follows, we assume that $R$ is a commutative noetherian domain and $B=R_{\bp}(\bt,\bsigma,\bH,\bJ)$ is a BR algebra of rank $n$. The enterprising reader could attempt to remove the domain hypothesis, which simplifies many of our arguments.

Let $\Gamma$ be the subgroup of $\Aut(R)$ generated by $\{\sigma_i: i \in [n]\}$. We say $R$ is \emph{$\Gamma$-simple} if for any ideal $I$, $\sigma(I)=I$ for all $\sigma \in \Gamma$ implies $I=0$ or $I=R$. 

In this section we give a simplicity criterion for BR algebras. We are motivated by the following result of Hartwig and \"{O}inert, and we will follow their methods. This criterion reduces to the one given by Bavula for GWAs \cite[Theorem 4.5]{B3}.

\begin{theorem}[Hartwig, \"{O}inert {\cite[Theorem 7.20]{HO}}]
Let $A=A_\mu(R,\sigma,t)$ be a regularly graded TGWA which is $R$-finitistic of type $(A_1)^n$. Then $A$ is simple if and only if the following hold:
\begin{enumerate}
    \item $R$ is $\Gamma$-simple;
    \item $Z(A) \subset R$;
    \item $R\sigma_i^d(t_i)+Rt_i = R$ for all $i \in 1,\hdots,n$ and all $d \in \ZZ_{>0}$.
\end{enumerate}
\end{theorem}

For $\balpha,\bbeta \in \ZZ^n$, let
\begin{align}\label{eq.pba}
p_{\bbeta,\balpha} = \prod_{\substack{\beta_i \in \bbeta \\ \alpha_k \in \balpha}} {p_{ik}^{\beta_i\alpha_k}}.
\end{align}
Observe that $p_{\be_i,\be_k} = p_{ik}$ and $p_{\bbeta,\balpha}\inv = p_{\balpha,\bbeta}$. In general, we have $t^\balpha t^\bbeta = p_{\bbeta,\balpha} t^\bbeta t^\balpha$.
We write $\balpha > 0$ to indicate $\alpha_i \geq 0$ for all $i$ and $\balpha \neq \bzero$.

For $b = \sum_{\bbeta \in \ZZ^n} b_\bbeta t^{\bbeta} \in B$, we define $\supp(b)=\{ \bbeta : b_\bbeta \neq 0\}$. We denote the cardinality of $\supp(b)$ by $|\supp(b)|$. By definition, $|\supp(b)|<\infty$.

\begin{lemma}\label{lem.multset}
The multiplicative set 
\[ \cX=\left( \{a t^\balpha~|~a\in I^{(\balpha)}, \balpha > 0\}\cup\{1\} \right)\setminus\{0\}.\]
is a left and right Ore set of $B$.
\end{lemma}

\begin{proof}
We will prove that $\cX$ is a right Ore set. The proof that it is a left Ore set is similar. Suppose $x=at^{\balpha} \in I^{(\balpha)}t^\balpha$ for some $\balpha > 0$ and let $g \in B$. We claim that $xB \cap g\cX \neq \emptyset$.

Let $w = \prod_{\bbeta \in \supp(g)} \sigma^{-\bbeta}(a)$. Set $\bgamma=(\gamma_i)$ where for each $i \in [n]$,
\[ \gamma_i = \min\left( \{ \bbeta_i : \bbeta \in \supp(g)\} \cup \{0\} \right).\]
Choose $ct^{\balpha-\bgamma} \in \cX$ so that $wct^{\balpha-\bgamma} \in \cX$.

Let $b_{\bdelta} t^{\bdelta}$ be a nonzero summand in $g$. Set $\widehat{w} = (\sigma^{-\bdelta}(a))\inv w$. Then
\begin{align*}
(b_{\bdelta} t^{\bdelta})(wct^{\balpha-\bgamma})
	&= (b_{\bdelta} t^{\bdelta})(\sigma^{-\bdelta}(a) \widehat{w} ct^{\balpha-\bgamma}) \\
	&= a b_{\bdelta} \sigma^{\bdelta}(\widehat{w}c) t^{\bdelta+\balpha-\bgamma} \\
	&= (a t^{\balpha}) \sigma^{-\balpha}(b_{\bdelta}) \sigma^{\bdelta-\balpha}(\widehat{w}c) t^{\bdelta-\bgamma}.
\end{align*}
Since $c \in I^{(\balpha-\bgamma)}$, then $\sigma^{\bdelta-\balpha}(c) \in I^{(\bdelta-\bgamma)}$ so that $\sigma^{-\balpha}(b_{\bdelta}) \sigma^{\bdelta-\balpha}(\widehat{w}c) t^{\bdelta-\bgamma} \in B$.
Thus, $g(wct^{\balpha-\bgamma}) \in (at^{\balpha})B$, as desired.
\end{proof}

\begin{theorem}\label{thm.loc}
Let $Q=Q(R)$ be the fraction field of $R$. Then $B\cX\inv \iso Q_\bp[\bt^{\pm 1}; \bsigma]$.
\end{theorem}
\begin{proof}
Let $r \in R$ and choose $a \in J_1$ so that $ra \in J_1$. Then $rat_1 \in \cX$ so we have
\[ (at_1)(rat_1)\inv = (at_1)(t_1\inv a\inv r\inv) = r\inv \in B\cX\inv.\]
This implies, in particular, that $a\inv \in B\cX\inv$, so that $a\inv (at_1) \in b\cX\inv$. Similarly, $t_i\inv \in B\cX\inv$ for all $i$. Thus, $Q_\bp[\bt^{\pm 1}; \bsigma] \subset B\cX\inv$.

On the other hand, it is clear that we have the inclusion $B \hookrightarrow Q_\bp[\bt^{\pm 1}; \bsigma]$. Any element of strictly positive degree in $B$ can be written as $at^\balpha$ for some $a \in I^{(\balpha)}$ and $\balpha > 0$. Then $(t^\balpha)\inv a\inv$ is its inverse, and this element is contained in $Q_\bp[\bt^{\pm 1}; \bsigma]$. Hence, each positive degree element of $B$ is a unit in $Q_\bp[\bt^{\pm 1}; \bsigma]$ and so by the universal property of localization, we have the inclusion $B\cX\inv \hookrightarrow Q_\bp[\bt^{\pm 1}; \bsigma]$.
\end{proof}

Henceforth, we set $C=B\cX\inv$. By Theorem \ref{thm.loc}, $C$ is the graded quotient ring of $B$ and is, trivially, a TGWA of type $(A_1)^n$.
Consequently, we may apply results from \cite[Section 7]{HO} directly to this ring. However, as some of our notation is diferent and because we will occasionally need to refer to elements of the proofs, we maintain these arguments for the benefit of the reader.

Let $K$ be an ideal in $B$, then by \cite[Lemma 7.9]{HO},
\begin{align}\label{eq.ideal}
CKC = \{x\inv ay\inv : x,y \in \cX, a \in K\}.
\end{align}

\begin{lemma}\label{lem.cnt1}
\begin{enumerate}
\item For any nonzero $c \in C$, there exists a nonzero element $r \in R$ such that $rc \in B$.
\item If $BxB=B$ for all $x \in \cX$, then $\cnt(B)=\cnt(C)$.
\end{enumerate}
\end{lemma}
\begin{proof}
(1) Let $c \in C$ be nonzero. Then $c=(j_{i_1}t_{i_1})^{-1}\cdots(j_{i_k}t_{i_k})^{-1}b'$ for some $b' \in B$. Note that the $t_{i_k}$ need not be distinct. Since $(j_{i_1}t_{i_1})\inv=t_{i_1}^{-1} j_{i_1}\inv$, then 
\[ \sigma_{i_1}\inv(j_{i_1}\inv)(t_{i_1}^{-1} j_{i_1}\inv) = t_{i_1}^{-1} j_{i_1}j_{i_1}\inv = t_{i_1}^{-1}.\]
By repeated applications of this, we may assume, up to multiplication by an element in $R$, that $c = t_{i_1}\inv \cdots t_{i_k}\inv b$ for some $b \in B$. Let $v \in H_{i_k}$ and set $v' = (\sigma_{i_1}\inv \circ \cdots \sigma_{i_{k-1}}\inv \circ \sigma_{i_k}\inv)(v) \in R$. Then
\[ v' c =  t_{i_1}\inv \cdots t_{i_{k-1}}\inv \sigma_{i_k}\inv(v)t_{i_k}\inv b.\]
But $\sigma_{i_k}\inv(v)t_{i_k}\inv \in B$. The result now follows by induction. 

(2) That $\cnt(B) \subset \cnt(C)$ is clear. Let $c \in \cnt(C)$. Write $c=x\inv b$ for some $x \in \cX$, $b \in B$. Since $1=\sum u_i x v_i$ for some $u_i,v_i \in B$, then
\[ c = (1)c = \sum u_i x v_i c = \sum u_i (xc) v_i = \sum u_i b v_i \in B.\]
Thus, $c \in B$, so $c \in \cnt(B)$.
\end{proof}

The $\ZZ^n$-grading on $B$ extends naturally to $C$ and so does the notion of support. The ring $C$ is, trivially, a TGWA. Therefore, Lemma \ref{lem.simp1} and \ref{lem.cnt2} follow from corresponding results in \cite{HO}. However, as our notation is different, we include their short proofs here.

\begin{lemma}\label{lem.simp1}
Assume $R$ is $\Gamma$-simple.
Let $c \in C$ be nonzero. Then there exists an element $c' \in C$ satisfying:
\begin{enumerate}
\item $c' \in CcC$,
\item $(c')_\bzero=1$, and
\item $|\supp(c')| \leq |\supp(c)|$.
\end{enumerate}
\end{lemma}
\begin{proof}
Write $c$ according to the $\ZZ^n$-grading and choose $\balpha \in \ZZ^n$ such that $c_\balpha \neq 0$. Because $B$ (and hence $C$) is a domain, then we can replace $c$ by $ct^{-\balpha}$ so that we may assume that $c_\bzero \neq 0$. Now by Lemma \ref{lem.cnt1} (1), there exists a nonzero $r \in R = B_\bzero$ such that $rc \in B$. Since $B$ is a graded domain, then $rc_0 \neq 0$. 

Consider the set
\[ K = \left\lbrace s \in R ~\middle|~ s + \sum_{\balpha \in \supp(c) \backslash\{0\}} d_\balpha \in CcC \text{ for some }d_\balpha \in C_\balpha\right\rbrace.\]
Taking $d_\balpha = rb_\balpha$ for each $\balpha \in \supp(c) \backslash\{0\}$ shows that $rc_0 \in K$. Thus, $K$ is a nonzero ideal of $R$. 

We now show that $K$ is $\Gamma$-invariant. Let $s \in K$, so $s+\sum_{\balpha \in \supp(c) \backslash\{0\}} d_\balpha \in CcC$ for some $d_\balpha \in C_\balpha$. Then
\[
CcC \ni t_i \left(s+\sum_{\balpha \in \supp(c) \backslash\{0\}} d_\balpha\right)t_i\inv = \sigma_i(s) + \sum_{\balpha \in \supp(c) \backslash\{0\}} t_i d_\balpha t_i\inv.
\]
Clearly, $t_id_\balpha t_i\inv C_\balpha$ for each $\balpha$. This shows that $\sigma_i(s) \in K$. Similarly one shows that $\sigma_i\inv(s) \in K$. Thus, $K$ is a nonzero $\Gamma$-invariant ideal of $R$, so by $\Gamma$-simplicity, we have $K=R$. Thus, $1 \in K$, so there exists $d_\balpha \in C_\balpha$ such that $c':=1 + \sum_{\balpha \in \supp(c) \backslash\{0\}} d_\balpha \in CcC$. It is clear that $c'$ satisfies the three properties.
\end{proof}

We say a subalgebra $A'$ of an algebra $A$ is \emph{essential} if $A' \cap I \neq \{0\}$ for every nonzero ideal $I$ of $A$.
Since $C$ is a TGWA (of type $(A_1)^n$), then \cite[Theorem 7.8]{HO} immediately implies the following. (In that result, take $A$ to be $C$, so that the $B$ in that result is also $C$.)

\begin{lemma}\label{lem.cnt2}
Let $R$ be $\Gamma$-simple. Then $\cnt(C)$ is an essential subalgebra of $C$.
\end{lemma}
\begin{proof}
Let $K$ be a nonzero ideal of $C$. Choose $c \in K$ such that $c \neq 0$ and $|\supp(c)|$ is as small as possible. Let $c' \in CcC \subset K$ be the corresponding element determined by Lemma \ref{lem.simp1}. Note that by minimality we have $|\supp(c')|=|\supp(c)|$. 

Let $r \in R$. Then $(c'r-rc')_\bzero = r-r=0$, so $|\supp(c'r-rc')|<|\supp(c')|$. Since $c'r-rc' \in J$, then minimality implies that $c'r-rc'=0$. Choose $i \in \{1,\hdots,n\}$. Then $(t_ic't_i\inv - c')_0 = 1-1=0$, so the same argument as above implies that $t_ic'=c't_i$. It follows that $c' \in \cnt(C)$.
\end{proof}

The previous lemma shows a bit more. In particular, $c' \in K \cap \cnt(C) \cap \left(1+ \sum_{\balpha \in \ZZ^n\backslash\{0\}} C_\balpha\right)$.

\begin{lemma}\label{lem.simp2}
The BR algebra $B$ is simple if and only if the following conditions hold:
\begin{enumerate}
\item $C$ is simple
\item $BxB=B$ for all $x \in \cX$.
\end{enumerate}
\end{lemma}
\begin{proof}
Suppose that $B$ is simple. Then clearly (2) holds. Let $K$ be a nonzero ideal in $C$ and let $b \in K$ be nonzero. Then there exists $x \in \cX$ such that $xb \in B$. Then $0 \neq xb \in B \cap K$. Thus, $B \cap K$ is a nonzero ideal of $B$ and so $1 \in B \cap K \subset K$. It follows that $C$ is simple.

Now assume that the two conditions hold. Let $K$ be an ideal of $B$. Then $CKC$ is a two-sided ideal of $C$, so $1 \in CKC$. Now by \eqref{eq.ideal}, $1=x\inv a y\inv $ for some $x,y \in \cX$ and $a \in K$. That is, $xy = a \in K$. The second condition implies that $B=BxyB=BaB \subset K$. Thus $K=B$.
\end{proof}

\begin{lemma}\label{lem.cntequiv}
Consider the following:
\begin{enumerate}
\item \label{cnt1} $\cnt(B)$ is a field,
\item \label{cnt2} $\cnt(B) \subset R$, and
\item \label{cnt3} $\cnt(B) = R^\Gamma$.
\end{enumerate}
Then $\eqref{cnt1} \Rightarrow \eqref{cnt2} \Rightarrow \eqref{cnt3}$. If $R$ is $\Gamma$-simple, then all three are equivalent.
\end{lemma}
\begin{proof}
$\eqref{cnt1} \Rightarrow \eqref{cnt2}$
Suppose there exists some nonzero $a \in \cnt(B)_\balpha$ for some $\balpha \in \ZZ^n \backslash \{\bzero\}$. Then $1+a \in \cnt(B)$ and so there exists some $b \in \cnt(B)$ that is a multiplicative inverse for $1+a$. Let $<$ be an ordering on $\ZZ^n$. We may assume that $\balpha > 0$. Write $b = b_{\beta_1} + \cdots + b_{\beta_k}$ where $0 \neq b_{\beta_i} \in B_{\beta_i}$ with each $\beta_i \in \ZZ^n$. Assume $\beta_1 < \dots < \beta_k$. Hence, the term of lowest degree in $(1+a)b$ is $1b_{\beta_1}$ and the term of highest degree is $ab_{\beta_k} \neq 0$. It follows that $k=1$ and so $b_{\beta_1} + ab_{\beta_1}=1$ but this contradicts $\balpha+\beta_1>\beta_1$. Thus, $\cnt(A) \subset R$.

$\eqref{cnt2} \Rightarrow \eqref{cnt3}$
Let $r \in \cnt(B) \subset R$. Then for any $at_i \in B_{\be_i}$ we have $r(at_i)=(at_i)r$ or, equivalently, $(r-\sigma_i(r))at_i$ (here we use the fact that $R$ is commutative). Since $R$ is a domain, so is $B$ and hence $\sigma_i(r)=r$. 

Now assume that $R$ is $\Gamma$-simple. We claim $\eqref{cnt3} \Rightarrow \eqref{cnt1}$. Let $r \in \cnt(B)=R^\Gamma$. Then $Rr=rR$ is a $\Gamma$-invariant ideal of $R$. Thus, if $r\neq 0$, then $Rr=R$, so $r$ is invertible.
\end{proof}

\begin{lemma}\label{lem.simp3}
If $B$ is simple, then $R$ is $\Gamma$-simple.
\end{lemma}
\begin{proof}
Let $K$ be a proper $\Gamma$-invariant ideal of $R$. Since $R=B_0$, we have
\[
(BKB) \cap R = \sum_{\balpha \in \ZZ^n} B_{\balpha} K B_{-\balpha}
	= \sum_{\balpha \in \ZZ^n}\sigma^{\balpha}(K) B_{\balpha} B_{-\balpha}
	\subset KR \subset K.
\]
Hence, $BKB$ is a proper ideal of $B$, so $BKB=\{0\}$. That is, $K=\{0\}$.
\end{proof}

We are now ready to prove our simplicity criteria.

\begin{theorem}\label{thm.HBRsimple}
The BR algebra $B$ is simple if and only if the following conditions hold:
\begin{enumerate}
\item \label{spr1} $BxB=B$ for all $x \in \cX$,
\item \label{spr2} $R$ is $\Gamma$-simple, and
\item \label{spr3} $\cnt(B) \subset R$.
\end{enumerate}
\end{theorem}
\begin{proof}
Suppose $B$ is simple. Condition \eqref{spr1} is clear while
condition \eqref{spr2} follows from Lemma \ref{lem.simp3}. Since $B$ is simple, then $\cnt(B)$ is a field. Thus condition \eqref{spr3} follows from Lemma \ref{lem.cntequiv}.

Now suppose that the three conditions hold. Since we have assumed condition \eqref{spr1}, then by Lemma \ref{lem.simp2} it suffices to prove that $C$ is simple. Let $K$ be a nonzero ideal of $C$. By Lemma \ref{lem.cnt2}, $K \cap \cnt(C) \cap \left(1+ \sum_{\balpha \in \ZZ^n\backslash\{0\}} C_\balpha\right) \neq \emptyset$. Conditions \eqref{spr1} and \eqref{spr3} along with Lemma \ref{lem.cnt1}(2) imply that $\cnt(C)=\cnt(B) \subset R$. But then $\cnt(C) \cap \left(1+ \sum_{\balpha \in \ZZ^n\backslash\{0\}} C_\balpha\right)  = \{1\}$, so $1 \in K$.
\end{proof}

Unfortunately, Theorem \ref{thm.HBRsimple}~\eqref{spr1}
is difficult to check in practice. In what follows, we present
an alternative condition in the spirit of Proposition \ref{prop.simple}.
This condition is implied by Theorem \ref{thm.HBRsimple}~\eqref{spr1}
and we conjecture that it is equivalent in the context of that theorem.

\begin{lemma}
Let $i\in [n]$, then the following are equivalent:
\begin{enumerate}
    \item $\css_i(B)\cap \sigma_i^{k}(\css_i(B))=\emptyset$ for all $k\in\ZZ_{>0}$,
    \item $H_iJ_i+\sigma_i^k(H_iJ_i)=R$ for all $k\in\ZZ_{>0}$,
    \item $BI_i^{(k)}t_i^kB=B$ for all $k\in\ZZ_{>0}$.
\end{enumerate}
\end{lemma}
\begin{proof}
(1)$\iff$(2). We prove the contrapositives. First we observe that the following statements are equivalent:
\begin{itemize}
    \item $\css_i(B)\cap \sigma_i^{k}(\css_i(B))\neq\emptyset$,
    \item there are $\bp,\bq\in\Spec(R)$ such that $\bp=\sigma_i^k(\bq)$, $H_iJ_i\subset \bp$, and $H_iJ_i\subset \bq$, 
    \item $H_iJ_i\subset \bp$ and $\sigma_i^k(H_iJ_i)\subset \bp$, 
    \item $H_iJ_i+\sigma_i^k(H_iJ_i)\subset \bp$. 
\end{itemize}
Hence, if $\css_i(B)\cap \sigma_i^{k}(\css_i(B))\neq\emptyset$, then there is a prime ideal $\bp$ with $H_iJ_i+\sigma_i^k(H_iJ_i)\subset \bp\subsetneq R$. Conversely, if $H_iJ_i+\sigma_i^k(H_iJ_i)\subsetneq R$, then by Zorn's Lemma there is a maximal ideal $\frm\in\Spec(R)$ with $H_iJ_i+\sigma_i^k(H_iJ_i)\subset \frm$, hence $\css_i(B)\cap \sigma_i^{k}(\css_i(B))\neq\emptyset$.

(2)$\iff$(3). First, we claim that $BI_i^{(k)}t_i^kB\cap B_{(k-1)\be_i}=\sum_{\ell\in\ZZ}I_i^{(\ell)}t_i^\ell I_i^{(k)}t_i^k I_i^{(-\ell-1)}t_i^{-\ell-1}$. It is clear that we have the inclusion $\supset$, so suppose that $y \in BI_i^{(k)}t_i^kB\cap B_{(k-1)\be_i}$. Then, there exists $a_k \in I_i^{(k)}$, $b_\balpha \in I^{(\balpha)}$ and $c_{-(\balpha+\be_i)} \in I^{({-(\balpha+\be_i)})}$ for some $\balpha \in \ZZ^n$
such that
\begin{align*}
y &= \sum_{\balpha \in \ZZ^n} \left( b_\balpha \bt^\balpha \right)a_kt_i^k \left(c_{-(\balpha+\be_i)} \bt^{-(\balpha+\be_i)} \right) \\
&= \sum_{\balpha \in \ZZ^n} \gamma_\balpha (b_{\alpha_i} t_i^{\alpha_i}) \left( \sigma_i\inv(b_{\widehat{\balpha}}) \bt^{\balpha-\alpha_i\be_i} \right)a_kt_i^k \left(c_{-(\balpha+\be_i)} \bt^{-(\balpha+\be_i)} \right) \\
&= \sum_{\balpha \in \ZZ^n} \gamma_\balpha' (b_{\alpha_i} t_i^{\alpha_i}) \left(  (\sigma_i\inv(b_{\widehat{\balpha}}) \sigma^{\balpha-\alpha_i\be_i}(a_k))t_i^k \right)\left(\sigma^{\balpha-\alpha_i\be_i}(c_{-(\balpha+\be_i)}) t_i^{-\alpha_i - 1} \right)
\end{align*}
where $b_{\widehat{\balpha}}=b_{\alpha_i}\inv b_\balpha$ and some $\gamma_\balpha,\gamma_\balpha' \in \kk^\times$.
Now it is clear that $\gamma_\balpha' b_{\alpha_i} \in I_i^{(\alpha_i)}$, $\sigma_i\inv(b_{\widehat{\balpha}}) \sigma^{\balpha-\alpha_i \be_i}(a_k) \in I_i^{(k)}$, and $\sigma^{\balpha-\alpha_i\be_i}(c_{-(\balpha+\be_i)}) \in I_i^{(-\alpha_i - 1)}$. Setting $\alpha_i=\ell$ proves the claim.

Now, to simplify notation, fix $i$ and set $J=J_i$, $H=H_i$, $I=I_i$, $t=t_i$, and $\sigma=\sigma_i$. Then we have
\begin{align*}
BI^{(k)}t^kB\cap B_{(k-1)\be_i}
    &=\sum_{\ell\in\ZZ}I^{(\ell)}t^\ell I^{(k)}t^k I^{(-\ell-1)}t^{-\ell-1}\\
    &=\sum_{\ell\geq 1}I^{(\ell)}\sigma^{\ell}(I^{(k)})\sigma^{\ell+k}(I^{(-\ell-1)})t^{k-1}
        +RI^{(k)}\sigma^k(I^{(-1)})t^{k-1}+I^{(-1)}\sigma^{-1}(I^{(k)})t^{k-1}R \\
        &\qquad +\sum_{\ell\leq -2}I^{(\ell)}\sigma^{\ell}(I^{(k)})\sigma^{\ell+k}(I^{(-\ell-1)})t^{k-1}\\
    &=\sum_{\ell\geq 1}J\cdots \sigma^{\ell+k-1}(J)\sigma^{\ell+k}(\sigma^{-1}(H)\cdots \sigma^{-\ell-1}(H))t^{k-1}\\
        &\qquad + R J\cdots \sigma^{k-1}(J)\sigma^k\sigma^{-1}(H)t^{k-1}+R\sigma^{-1}(H)\sigma^{-1}(J\cdots \sigma^{k-1}(J))t^{k-1}\\
        &\qquad +\sum_{\ell\leq -2}\sigma^{-1}(H)\cdots \sigma^{\ell}(H)\sigma^{\ell}(J\cdots \sigma^{k-1}(J))\sigma^{\ell+k}(J\cdots \sigma^{-\ell-2}(J))t^{k-1}\\
    &=\sum_{\ell\geq 1}J\cdots \sigma^{\ell+k-1}(J)\sigma^{k-1}(H)\cdots \sigma^{\ell+k-1}(H))t^{k-1} \\
        &\qquad + R J\cdots \sigma^{k-1}(J)\sigma^{k-1}(H)t^{k-1}+R\sigma^{-1}(H)\sigma^{-1}(J)\cdots \sigma^{k-2}(J)t^{k-1} \\
        &\qquad +\sum_{\ell\leq -2}\sigma^{-1}(H)\cdots \sigma^{\ell}(H)\sigma^{\ell}(J)\cdots \sigma^{k-2}(J)t^{k-1}\\
    &= R\sigma^{k-1}(HJ) I^{(k-1)}t^{k-1}+R\sigma^{-1}(HJ) I^{(k-1)}t^{k-1}\\
    &= R(\sigma^{k-1}(HJ)+\sigma^{-1}(HJ)) I^{(k-1)}t^{k-1}.
\end{align*}
Since $\sigma^{k-1}(HJ)+\sigma^{-1}(HJ)=R$ if and only if $HJ+\sigma^k(HJ)=R$, this gives us the desired equivalence as in the proof of \cite[Lemma 7.19]{HO}.
\end{proof}

It is clear that the condition $BI_i^{(k)}t_i^kB=B$ for all $i\in [n]$, $k\in\ZZ_{>0}$ is implied by $BxB=B$ for all $x\in\cX$, but the reverse direction is not clear. 
Going forward, it would be good to develop further tools for analyzing the simplicity of BR algebras of rank $n>1$.

