\section{The limits of extrapolation}
\label{app:limits}
In this appendix, we set to prove Propositions \ref{prop_nogo2}, \ref{prop_nogo1} in the main text. Both proofs will rely on the following construction.
\begin{lemma}
\label{lemma_construction}
Given a set of non-zero real numbers $\{c_k\}_{k=0}^n$ and $\{E_k\}_{k=0}^n\subset \R$, there exists a timeline $P(t)$ with realization $(\C^{2n},\rho, H,M)$ such that $\mbox{spec}(H)=\{E_k\}_{k=1}^n\cup\{0\}$ and
\begin{equation}
\alpha(t):=P(1|t)-P(0|t)= \frac{\sum_kc_k\frac{e^{-iE_kt}+e^{iE_kt}}{2}}{\sum_l|c_l|}.
\end{equation}
\end{lemma}
\begin{proof}
Define $\ket{\phi(c)}:=\frac{1}{\sqrt{2}}(\ket{0}+\sign(c)\ket{1})$, and consider the quantum state $\rho\in B(\C^{2}\otimes \C^{n})$, given by
\begin{align}
&\rho=\frac{1}{\sum_l|c_l|}\sum_{k=0}^n|c_k|\proj{\phi(c_k)}\otimes \proj{k}.
\label{state_c}
\end{align}
and the Hamiltonian
\begin{equation}
H=\proj{1}\otimes \sum_kE_k\proj{k}.
\label{hamil_E}
\end{equation}
We also introduce the dichotomic operator
\begin{equation}
A:=\left(\ket{0}\bra{1}+\ket{1}\bra{0}\right)\otimes\id_n,
\label{dicho_gen}
\end{equation}
which defines the two-outcome POVM $M$ through $M_a:=\frac{1}{2}(\id+(-1)^aA)$. It can be verified that the timeline with realization $(\C^{2n},\rho, H,M)$ satisfies
\begin{equation}\label{eqn:trace1}
P(1|t)-p(0|t)=\tr(e^{-iHt}\rho e^{iHt} A)=\frac{\sum_kc_k\frac{e^{-iE_kt}+e^{iE_kt}}{2}}{\sum_l|c_l|}.
\end{equation}

\end{proof}

Now we are well equipped to prove Propositions \ref{prop_nogo2}, \ref{prop_nogo1}.



\begin{proof}[Proof of Proposition \ref{prop_nogo2}]

For $n=2m, m\in \N$, set 
\begin{align}
&E_k=\frac{n-2k}{nT},\nonumber\\
&c_k=\frac{1}{2^n}\left(\begin{array}{c}n\\k\end{array}\right)(-1)^k,
\end{align}
for $k=0,...,n$. Note that $\sum_k|c_k|=1$. By Lemma \ref{lemma_construction}, there exists a timeline $P_n(t)$ complying with the hard energy support constraint $\mbox{spec}(H)\subset \left[-\frac{1}{T},\frac{1}{T}\right]$ such that
\begin{align}
&P_n(1|t)-P_n(0|t)\nonumber\\
&=\frac{1}{2}\sum_{k=0}^n \frac{1}{2^n}\left(\begin{array}{c}n\\k\end{array}\right)\left((-e^{-\frac{it}{nT}})^k(e^{\frac{it}{nT}})^{n-k}\right.\nonumber\\
&\left. +(-e^{\frac{it}{nT}})^k(e^{-\frac{it}{nT}})^{n-k}\right)\nonumber\\
&=\frac{1}{2}\left(\sin\left(\frac{t}{nT}\right)^n+\sin\left(-\frac{t}{nT}\right)^n\right),\nonumber\\
&=\sin\left(\frac{t}{nT}\right)^n,
\label{asin}
\end{align}
for all $t$. In the last line, we invoked that $\sin(\bullet)$ is an odd function and that $n$ is even.

Note that the spectrum of $H$ is actually contained in $\left[-\frac{1}{T},\frac{1}{T}\right]$. This Hamiltonian generates exactly the same timeline as $H^+:=H+\frac{1}{T}$, whose spectrum is indeed contained in $\left[0,\frac{2}{T}\right]$. For mathematical convenience, though, we will continue the proof with $H$ instead of $H^+$.


%Exchanging the two outcomes of the POVM in the realization of $P_n(t)$, we obtain the timeline $\overline{P}_n(t)$, which predicts
\begin{equation}\label{asin2}
\overline{P}_n(1|t)-\overline{P}_n(0|t)=-\sin\left(\frac{t}{nT}\right)^n,
\end{equation}
for all $t$.

% For $t\in [0,T]$, eqs. (\ref{asin}), (\ref{asin2}) tell us that
% \begin{align}
% &\sum_a\left|P_n(a|t)-\frac{1}{2}\right|\leq \sin\left(\frac{1}{n}\right)^n,\nonumber\\
% &\sum_a\left|\overline{P}_n(a|t)-\frac{1}{2}\right|\leq \sin\left(\frac{1}{n}\right)^n.
% \end{align}
% Hence, we set 
% \begin{equation}
% \delta= \sin\left(\frac{1}{n}\right)^n.
% \end{equation}

For $t\in [0,T]$, eq. (\ref{asin}) tell us that
\begin{align}
&\sum_a\left|P_n(a|t)-\frac{1}{2}\right|= \sin\left(\frac{1}{n}\right)^n,
\end{align}
Hence, we set 
\begin{equation}
\delta= \sin\left(\frac{1}{n}\right)^n.
\end{equation}


On the other hand, for a fixed extrapolation time $\tau>T$, by eq. (\ref{asin}) it holds that
\begin{equation}
\delta'\geq \left|P_n(0|t)-\frac{1}{2}\right|=\frac{1}{2}\sin\left(\frac{\tau}{nT}\right)^n.
\end{equation}
Recall that $n=2m$, so the right-hand side is non-negative.

For large $n$, we have 
\begin{equation}
\delta\approx \frac{1}{n^n}, \delta'\gtrsim \frac{1}{2}\left(\frac{\tau}{Tn}\right)^n.
\end{equation}
The first relation implies that $n\approx e^{W\left(\log\left(\frac{1}{\delta}\right)\right)}$, where $W$ denotes Lambert's $W$ function, i.e., $W(s)e^{W(s)}=s$. For large $s$, this function behaves as \cite{LambertW}:
\begin{equation}
W(s)\approx \log(s)-\log(\log(s))+o(1),
\end{equation}
which implies $n\approx \frac{\log\left(\frac{1}{\delta}\right)}{\log\log\left(\frac{1}{\delta}\right)}$. Hence,
\begin{equation}
\frac{\delta'}{\delta}\gtrsim \frac{1}{2}\left(\frac{\tau}{T}\right)^n\approx \frac{1}{2}\left(\frac{\tau}{T}\right)^{\frac{\log\left(\frac{1}{\delta}\right)}{\log\log\left(\frac{1}{\delta}\right)}}.
\end{equation}


\end{proof}


\begin{proof}[Proof of Proposition \ref{prop_nogo1}]


For arbitrary $\lambda>1$, $n\in\N$, define 
\begin{align}
&E_k=\frac{k}{nT},\nonumber\\
&c_k=\left(\begin{array}{c}n\\k\end{array}\right)(1-\lambda)^{n-k}\lambda^k,
\end{align}
for $k=0,...,n$. Invoking Lemma \ref{lemma_construction}, we have that there exists a timeline $P_{\lambda,n}(t)$, compatible with the hard energy constraint $\mbox{spec}(H)\subset \left[0,\frac{1}{T}\right]$, such that
\begin{align}
&P_{\lambda,n}(1|t)-P_{\lambda,n}(0|t)\nonumber\\
&=\frac{1}{2}\frac{\sum_{k=0}^n\left(\begin{array}{c}n\\k\end{array}\right)(1-\lambda)^{n-k}\left(\lambda^ke^{-it\frac{k}{TN}}+\lambda^ke^{it\frac{k}{TN}}\right)}{\sum_{j=0}^n\left(\begin{array}{c}n\\j\end{array}\right)\lambda^j(\lambda-1)^{n-j}}\nonumber\\
&=\frac{1}{2}\frac{(1-\lambda+\lambda e^{-i\frac{t}{nT}})^n+(1-\lambda+\lambda e^{i\frac{t}{nT}})^n}{(2\lambda-1)^n}.
\label{done_sum}
\end{align}

This can be rewritten as:
\begin{align}
&P_{\lambda,n}(1|t)-P_{\lambda,n}(0|t)=\frac{\cos\left(\frac{\lambda t}{T}\right)+\epsilon_n\left(\lambda,\frac{t}{T}\right)}{(2\lambda-1)^n},
\label{super_osc}
\end{align}
with
\begin{align}
&\epsilon_n\left(\lambda,\frac{t}{T}\right):=\frac{1}{2}\left[(1-\lambda+\lambda e^{-i\frac{t}{nT}})^n\right.\nonumber\\
&+\left.(1-\lambda+\lambda e^{i\frac{t}{nT}})^n\right]-\cos(\frac{\lambda t}{T}).
\label{eqn:deltanu}
\end{align}
As a consequence of the identity $e^x=\lim_{n\to\infty}(1+x/n)^n$, we have that $\lim_{n\to \infty}\epsilon_n\left(\lambda,\tilde{t}\right)=0$, for all $\tilde{t}\in\R$. 

Therefore, there exists a number $n_0(\lambda)\in\N$ such that, for $n\geq n_0(\lambda)$ and $t\in [0, T]$, it holds that
\begin{equation}\label{epsilon1}
|\epsilon_n\left(\lambda,\tilde{t}\right)|\leq 1,
\end{equation}
for $\tilde{t}\in[0,1]$. For $n\geq n_0(\lambda)$ we hence have that
\begin{align}
&\sum_a\left|P_{\lambda,n}(a|t)-\frac{1}{2}\right|=|P_{\lambda,n}(1|t)-P_{\lambda,n}(0|t)|\nonumber\\
&\leq \frac{2}{(2\lambda+1)^n}=:\delta_n(\lambda).
\end{align}
Then, for any $N$, the timeline $P_{\lambda,n}$ fits the noisy dataset $\mathbf{O}(N,T,\delta_n(\lambda))$, see eq. (\ref{def_dataset_O}).

Now, set $\tau=\pi n T$. Then, by eq. (\ref{done_sum}), we have that
\begin{equation}
P_{\lambda,n}(1|\tau)-P_{\lambda,n}(0|\tau)=\frac{(1-2\lambda)^n}{(2\lambda-1)^n}=(-1)^n.
\end{equation}
Namely, $P_{\lambda,n}(a|\tau)=\frac{(-1)^{a+n+1}+1}{2}$.
If we swap the POVM elements of the realization of $P_{\lambda,n}$, we obtain another timeline $\overline{P}_{\lambda,n}$, which also fits $\mathbf{O}(N,T,\delta_n(\lambda))$ and predicts that 
\begin{equation}
\overline{P}_{\lambda,n}(a|\tau)=\frac{(-1)^{a+n+1}+1}{2}.
\end{equation}


In sum, for $\delta=\delta_n(\lambda)$, $n\geq n(\lambda)$, there is Knightian uncertainty at $\tau=\pi n$ independently of the number $N$ of measurement times. Call $\delta^\star_n$ the minimum noise that predicts a Knightian uncertainty at $\tau=\pi n T$. We have proven that
\begin{align}
&\lim_{n\to\infty}\frac{\log(\delta^\star_n)}{n}\nonumber\\
&\leq \lim_{n\to\infty}\frac{\log(\delta_n(\lambda))}{n}\nonumber\\
&=-(2\lambda+1).
\end{align}
Since $\lambda>1$ is arbitrary, it follows that $\delta^\star_n$ is the inverse of a function $g(n)$, superexponential in $n$ (and hence, superexponential in $\tau$).


\end{proof}




\section{Self-testing datasets}
\label{app:ST}

The self-testing properties are based on the insight that certain (noisy) statistics essentially fix the energy distribution of the state generating them, as captured by the following lemma.


\begin{lemma}
\label{lemma_density_noise}
Let $N\in\N$, let $\ket{\psi}$ be a normalized state with respect to some Hamiltonian $H$. Suppose that the hard support constraint holds, i.e., $\mbox{supp}(\sigma(E))\in[0,E^+]$, where $\sigma(E)dE$ is the energy density of $\ket{\psi}$, and that
\begin{equation} \label{eq:overlap}
|\bra{\psi}e^{iH(t_0-t_k)}\ket{\psi}|\leq \epsilon, k=1,...,N-1,
\end{equation}
with
\begin{equation}
t_k:=\frac{2\pi (N-1)k}{N E^+}.
\end{equation}
Then,  
\begin{equation} \label{eq:energy_density}
\sum_{k=0}^{N-1} \int_{\frac{E^+(k-\epsilon^{1/4})}{N-1}}^{\frac{E^+(k+\epsilon^{1/4})}{N-1}}\sigma(E) dE \gtrapprox 1 -O(\sqrt{\epsilon}).
\end{equation}
\end{lemma}

Lemma~\ref{lemma_density} follows as $\epsilon \rightarrow 0$.

\begin{proof}
Condition~\eqref{eq:overlap} implies that
\begin{equation}
\left| \int_0^{E^+} e^{i \frac{2 \pi (N-1) k E}{NE^+}}\sigma(E) dE \right| \leq \epsilon, \ k=1, \ldots, N-1.
\end{equation}
Now let us consider the auxiliary function
\begin{align}
V(E) :&= \sin \left( \frac{\pi (N-1) E}{E^+}\right)  \prod_{j=1}^{N-2} \sin \left( \frac{j \pi}{N} -  \frac{\pi (N-1) E}{N E^+} \right) 
\label{def_V}
\end{align}
Notice that $V(E)=0$ iff $E=\frac{E^+ k}{N-1}$. Moreover, $V(E) \geq 0$ for $E\in [0,E^+]$. This can be seen by noticing that, for very small $E>0$, all factors in the product (\ref{def_V}) are positive. The first factor changes sign at $E\in\{\frac{E^+k}{N-1}:k=1,...,N-2\}$, while factors of the form 
\begin{equation}
V_j(E):=\sin \left( \frac{j \pi}{N} -  \frac{\pi (N-1) E}{N E^+} \right)
\end{equation}
only change sign at $E=\frac{E^+j}{N-1}$. Each sign change of the first factor is therefore canceled by the sign change of $V_j(E)$, and so $V(E)$ remains non-negative in $[0,E^+]$. 

In addition, if one expands the sine functions in eq. (\ref{def_V}) as sums of imaginary exponentials, one sees that $V(E)$ is a linear combination of the functions 
\begin{equation}
\{e^{i\frac{2\pi (N-1) kEj}{NE^+}}:j=1,...,N-1\}    
\end{equation}
and their complex conjugates. More specifically,
\begin{equation}
    V(E)=\frac{1}{2^{N-1}}\sum_{j=1}^{N-1} \mu_{j}^+ e^{i \frac{2 \pi (N-1) j E}{NE^+}} + \mu_{j}^- e^{-i \frac{2 \pi (N-1) j E}{NE^+}},
\end{equation}
where each $\mu_j^{\pm}=\frac{1}{i^{N-1}}\sum_k c_k  e^{i \frac{k \pi}{N}}$, where $c_k$ is an integer that counts the number of terms with the respective exponential, taking the sign into account; notice that $k$ may be negative.

The above implies that
\begin{align}
\int_0^{E^+} &V(E) \sigma(E) dE \nonumber \\ 
&= \frac{1}{2^{N-1}} \sum_{j=1}^{N-1} \mu_j^+ \int_0^{E^+}  e^{i \frac{2 \pi (N-1) j E}{NE^+}} \sigma(E) dE \nonumber \\
& \qquad \qquad \ \ + \mu_{j}^- \int_0^{E^+} e^{-i \frac{2 \pi (N-1) j E}{NE^+}} \sigma(E) dE \nonumber\\ 
&\leq \frac{1}{2^{N-1}} \sum_{j=1}^{N-1} |\mu_j^+ |\epsilon  + |\mu_{j}^-|\epsilon \nonumber\\
&\leq \epsilon, \label{eq:ve}
\end{align}
where in the second to last inequality we take the absolute value and use the triangle inequality; the last inequality follows as there are ${2^{N-1}}$ terms in the decomposition of $V(E)$ in total and each has an absolute value $\frac{1}{{2^{N-1}}}$.

Let us further define the energy range $E_{\delta} = \bigcup_{k=1}^{N-1} [\frac{E^+(k-1)}{N-1}+\delta, \frac{E^+k}{N-1} -\delta]$. Since $V(E)$ is positive, we have that
\begin{equation}
    \epsilon \geq \int_{E_{\delta}} V(E) \sigma(E) dE
\end{equation}
It is now helpful to rewrite 
\begin{equation}
V(E)= \frac{\sin^2 \left( \frac{\pi (N-1) E}{E^+}\right)}{2^{N-1} \sin \left(\frac{\pi (N-1) E}{N E^+} \right) \sin \left( \frac{\pi}{N} + \frac{\pi (N-1) E}{NE^+}\right)}.
\end{equation}
For $E\in [0, E^+]$, one has that 
\begin{equation}
0 \leq \sin \left(\frac{\pi (N-1) E}{N E^+} \right) ,\sin \left( \frac{\pi}{N} + \frac{\pi (N-1) E}{NE^+}\right) \leq 1.
\end{equation}
This implies that 
\begin{align}
    \epsilon &\geq \int_{E_{\delta}} V(E) \sigma(E) dE \\
    &\geq \int_{E_{\delta}} \frac{1}{2^{N-1}} \sin^2 \left( \frac{\pi (N-1) E}{E^+} \right) \sigma(E) dE.
\end{align}
Let $\delta = \frac{\epsilon^{1/4} E^+}{\pi (N-1)}$, then on $E_\delta$ we have 
\begin{align}
    \int_{E_{\delta}} \frac{1}{2^{N-1}} \sin^2 &\left( \frac{\pi (N-1) E}{E^+} \right) \sigma(E) dE \nonumber \\
    &\geq \frac{1}{2^{N-1}} \sin^2 \left( \epsilon^{1/4} \right) \int_{E_{\delta}}  \sigma(E) dE 
\end{align}
and, for small $\epsilon$,
\begin{equation}
 \int_{E_{\delta}}  \sigma(E) dE  \lesssim O(\sqrt{\epsilon} \cdot 2^{N-1}).
\end{equation}




\end{proof}


Towards the proof of the self-testing result in Proposition~\ref{prop_self_test}, let us first prove the following two lemmas.

\begin{lemma}
\label{lemma_POVM_annihilation}
Let $\tr(\rho M)\leq \epsilon$, for $0\leq M\leq \id$. Then,
\begin{equation}
\|M\rho\|_1\leq \sqrt{\epsilon}.
\end{equation}
\end{lemma}
\begin{proof}
Let $\ket{\psi}$ be a purification of $\rho$. Then,
\begin{equation}
\epsilon \geq \bra{\psi}(M\otimes \id)\ket{\psi}\geq \bra{\psi}(M^2\otimes \id)\ket{\psi}.
\end{equation}
Thus, $\|(M\otimes \id)\ket{\psi}\|_2\leq \sqrt{\epsilon}$ and, furthermore, 
\begin{equation}
\|(M\otimes \id)\ket{\psi}\|_2 = \|(M\otimes \id)\ket{\psi}\bra{\psi}\|_1\geq \|M\rho\|_1,
\end{equation}
which proves the lemma.
\end{proof}

\begin{lemma}
\label{lem:overlap}
Let $P \in S(E^+)$ satisfy \eqref{eq:approx_data} for $j=1, \ldots, N-1$ with a pure state realization $(\H,\psi,H,M)$, then the states $\ket{\psi(t_j)}=e^{iHt_j}\ket{\psi}$ evolved to times $t_j$, for $j=1, \ldots, N-1 $ satisfy
\begin{equation}
    |\braket{\psi}{\psi(t_j)}| \leq \sqrt{2\delta-\delta^2}.
\end{equation}
\end{lemma}

\begin{proof}
First, notice that \eqref{eq:approx_data} implies that for any $j=1, \ldots, N-1$, we can lower bound \begin{equation}
    \tr({M}_0 (\ketbra{\psi}{\psi}-\ketbra{\psi(t_j)}{\psi(t_j)})) \geq 1-\delta. \label{eq:1}
\end{equation}
At the same time
\begin{align}
  \tr({M}_0 (\ketbra{\psi}{\psi} &-\ketbra{\psi(t_j)}{\psi(t_j)})) \nonumber \\
  &\leq \frac{1}{2} \| \ketbra{\psi}{\psi}-\ketbra{\psi(t_j)}{\psi(t_j)}))\|_1 \nonumber\\
  &=\sqrt{1- |\braket{\psi}{\psi(t_j)}|^2}.
\end{align}
Combining this with \eqref{eq:1} completes the proof.    
\end{proof}

We are now in a position to prove Proposition~\ref{prop_self_test} from the main text.

\begin{proof}[Proof of Proposition~\ref{prop_self_test}]
First, we note that any realisation $(\H,\rho,H,M)$ can be purified to a realisation $(\H,\psi,H,M)$. For the latter, we have by Lemma~\ref{lem:overlap} that 
$|\braket{\psi}{\psi(t_j)}| \leq O(\sqrt{\delta})$.
By Lemma~\ref{lemma_density_noise}, this implies for the energy density $\sigma(E) dE$ of $\ket{\psi}$ that 
\begin{equation} \label{eq:energy_density}
\sum_{k=0}^{N-1}\int_{\frac{E^+(k-\delta^{1/8})}{N-1}}^{\frac{E^+(k+\delta^{1/8})}{N-1}}\sigma(E) dE \gtrapprox 1-O(\delta^{1/4}), \ k=0,\ldots,(N-1).
\end{equation}

%This implies that in the binned energy basis from \eqref{binned}, we can rewrite 
%\begin{equation}
%   \ket{\psi} = \sum_{k=0}^{N-1} \sum_j \ket{\psi_j (\frac{E^+ k}{N-1} )} \ket{\phi_j(k)},
%\end{equation}
%where the $\{\ket{\psi_j \left(\frac{E^+ k}{N-1} \right)}\}_j$ are an orthonormal basis of eigenvectors of $H$ with eigenvalues $\frac{E^+ k}{N-1}$ respectively; the coefficients of size $\frac{1}{\sqrt{N}}- O(\sqrt[4]{\delta})$ have been absorbed into the (subnormalized) $\{\ket{\phi_j(k)}\}_j$. 
For $k=0,\ldots,N-1$, define the orthogonal projectors
\begin{equation}
\Pi_k := \int_{\frac{E^+ (k-\delta^{1/8})}{N-1}}^{\frac{E^+ (k+\delta^{1/8})}{N-1}} \ketbra{E}{E} dE,
\end{equation}
(extending the spectrum to the negative at $k=0$ is just a notational convenience), and call $\Pi$ their sum. We next introduce the state
\begin{equation}
\ket{\psi'}:=\frac{\Pi\ket{\psi}}{\|\Pi\ket{\psi}\|_2}.
\end{equation}
By eq. (\ref{eq:energy_density}), we have that $\ket{\psi}, \ket{\psi'}$ are very similar for small $\delta$. More concretely,
\begin{equation}
\|\proj{\psi}-\proj{\psi'}\|_1\leq O(\delta^{1/8}).
\label{diff_psi_psi_prime}
\end{equation}
Let us further introduce the Hamiltonian 
\begin{align} \label{binned}
    H':= \sum_{k=0}^{N-1} \frac{E^+ k}{N-1} \Pi_k,
\end{align}
and denote by $\ket{\psi'(t)}$ ($\ket{\psi(t)}$) the state that results from propagating $\ket{\psi'}$ ($\ket{\psi}$) with $H'$ ($H$) for a time $t$.

For $\delta t^{1/8}\leq \frac{\pi (N-1)}{E^+}$, through the same discretization arguments used in section \ref{sec:charact}, we arrive at
\begin{align}
&|\bra{\psi'(t)}e^{-iHt}\ket{\psi'}|\geq \cos\left(\frac{E^+\delta^{1/8}t}{N-1}\right),
\end{align}
which implies that
\begin{equation}
\|\proj{\psi'(t)}-e^{-iHt}\proj{\psi'}e^{iHt}\|_1\leq O(t\delta^{1/8}).
\end{equation}
Thus,
\begin{align}
&\|\proj{\psi(t)}-\proj{\psi'(t)}\|_1\nonumber\\
&\leq \|e^{-iHt}\proj{\psi}e^{iHt}-e^{-iHt}\proj{\psi'}e^{iHt}\|_1\nonumber\\
&+\|e^{-iHt}\proj{\psi'}e^{iHt}-\proj{\psi'(t)}\|_1\nonumber\\
&\leq O(\delta^{1/8})+O(\delta^{1/8}t).
\end{align}
In particular, we have that
\begin{align}
&\|\proj{\psi(t_l)}-\proj{\psi'(t_l)}\|_1\leq O(\delta^{1/8}),
\label{diff_psi_psi_prime_t}
\end{align}
for $l=0,...,N-1$.
Due to the last equation and the fact that $P$ fits $\mathbf{D}_N$, it holds that
\begin{align}
&\tr(M_1\proj{\psi'(0)})\leq O(\delta^{1/8}),\nonumber\\
&\tr(M_0\proj{\psi'(t_l)})\leq O(\delta^{1/8}),l\not=0.
\label{primed_stats}
\end{align}

The state $\ket{\psi'}$ can be written as 
\begin{align}
    \ket{\psi'} = \sum_k \ket{\psi_j (k)} \ket{\phi_j(k)}_A,
\end{align}
where the states $\{\ket{\psi_j (k)}\}_j$ are an orthonormal basis of the energy eigenspace of $H'$ with eigenvalue $\frac{E^+k}{N-1}$, and the states $\ket{\phi_j(k)}$ are non-normalised, non-orthogonal states of $\rho$'s purifying system $\mathcal{H}_A$.
Now, the trace-class operators 
$\Phi_k:=\sum_j \ketbra{\phi_j(k)}{\phi_j(k)}$ satisfy
\begin{align}
    \| \Phi_{k_1}-\Phi_{k_2} \|_1 
    & \!= \! \frac{1}{N} \| \!\!\!\sum_{k,s=0}^{N-1} \!e^{\frac{2\pi i (k_1-k)s}{N}} \Phi_k \! - \!\! \! \sum_{k,s=0}^{N-1} \! e^{\frac{2\pi i (k_2-k)s}{N}} \Phi_k\|_1 \nonumber\\
    &\leq 2 \| \sum_{k=0}^{N-1} e^{\frac{-2\pi i k s}{N}} \Phi_k \|_1, 
\end{align}
where in the first line we used the geometrical series and in the second the triangle inequality. We further find, due to the polar decomposition, that
\begin{align}
    \| \sum_{k=0}^{N-1} e^{\frac{-2\pi i k s}{N}} \Phi_k \|_1 &= \max_{U, \text{ unitary}} |\tr( U \sum_{k=0}^{N-1} e^{\frac{-2\pi i k s}{N}} \Phi_k)| \nonumber \\
    &= \max_{U, \text{ unitary}} |\tr(\id \otimes U e^{-i H't_s} \ketbra{\psi'}{\psi'})| \nonumber \\    
   &\leq O(\delta^{1/16}).
\end{align} 
The explanation for the last inequality is as follows:
\begin{align}
&|\tr((\id \otimes U) e^{-i H't_s} \ketbra{\psi'}{\psi'})|\nonumber\\
&\leq |\tr((M_0 \otimes U) e^{-i H't_s} \ketbra{\psi'}{\psi'})|\nonumber\\
&+|\tr((M_1 \otimes U) e^{-i H't_s} \ketbra{\psi'}{\psi'})|\nonumber\\
&= |\tr((\id \otimes U)(M_0\otimes \id)| e^{-i H't_s} \ketbra{\psi'}{\psi'})\nonumber\\
&+|\tr((\id \otimes U) e^{-i H't_s} \ketbra{\psi'}{\psi'}(M_1\otimes \id)|.
\end{align}
Each of the last two terms is bounded by $O(\delta^{1/16})$. Indeed, by eq. (\ref{primed_stats}) we have that
\begin{align}
&\|(M_0\otimes \id)\ket{\psi'(t_s)}\|_2^2\nonumber\\
&=\bra{\psi'(t_s)}((M_0)^2\otimes \id)\ket{\psi'(t_s)}\nonumber\\
&\leq\bra{\psi'(t_s)}(M_0\otimes\id)\ket{\psi'(t_s)}\leq O(\delta^{1/8}),
\end{align}
and similarly for the second term. We conclude that
\begin{align}
\|\Phi_{k_1}-\Phi_{k_2} \|_1\leq O(\delta^{1/16}). 
\label{eq:phi}
\end{align}

Now, for each $k$, let us consider the vectors 
\begin{equation} 
    \ket{\psi_k'}= \sum_j \ket{\psi_j(k)} \ket{\phi_j(k)}.
\end{equation}
$\ket{\psi_k'}$ is a purification of $\Phi_k$, with purifying system $\mathcal{H}_k$ (the eigenspace of $H'$ to eigenvalue $\frac{E^+ k}{N-1}$).
Since $\tr(\sum_k\Phi_k)=1$, by \eqref{eq:phi} it follows that
\begin{equation}
|\tr(\Phi_k)-\frac{1}{N}|\leq O(\delta^{1/16}),\forall k.
\label{norm_approx}
\end{equation}
Let $k$ be such that $\mbox{dim}(\H_k)=\min_j\mbox{dim}(\H_j)$, and let $P_k$ be the projector onto the support of $\Phi_k$. Define:
\begin{align}
&\Phi''_j:= \frac{P\Phi_jP}{N\tr(\Phi_jP)},\mbox{ for }j\not=k,\nonumber\\
&\Phi''_k:= \frac{\Phi_k}{N\tr(\Phi_kk)},\nonumber\\
&\ket{\psi''_j}:= \frac{1}{\sqrt{N}}\frac{(\id\otimes P)\ket{\psi_j}}{\|(\id\otimes P)\ket{\psi_j}\|_2},\mbox{ for }j\not=k,\nonumber\\
&\ket{\psi''_k}:= \frac{1}{\sqrt{N}}\frac{\ket{\psi_k}}{\|\ket{\psi_k}\|_2}.
\end{align}
It can be verified that $\tr_{\H}(\proj{\psi''_j})=\Phi''_j$, for all $j$. In addition, by eqs. (\ref{eq:phi}) and (\ref{norm_approx}), we have that 
\begin{align}
&\|\Phi_j-\Phi''_k\|_1\leq O(\delta^{1/16}),\nonumber\\
&\|\ket{\psi''_j}-\ket{\psi_j}\|_2\leq O(\delta^{1/32}),
\end{align}
for $j=1,...,N$.
By assumption, the Schmidt number of the vectors $\{\ket{\psi''_j}\}_j$ is smaller than or equal to $d:=\mbox{dim}(\H_k)$. Call $d_k$ the dimension of the support of $\Phi_k$. Next, we modify the vector $\ket{\psi''_j}$ so that its reduced state in system $A$ is exactly equal to $\Phi_k$. 

To do so, we invoke Uhlmann's theorem \cite{nielsen00}: given the two states $\rho_k:=N\Phi''_k$, $\rho_j:=N\Phi''_j$, there exist purifications $\ket{\omega_k},\ket{\omega_j}\in \C^{d}\otimes \C^{d_k}$ such that
\begin{align}
&|\braket{\omega_k}{\omega_j}|^2=F(\rho_k,\rho_j)\nonumber\\
&:=\tr(\sqrt{\rho_1^{1/2}\rho_2\rho_1^{1/2}})^2.
\end{align}
Since all purifications are equivalent modulo local unitaries and $\mbox{dim}(\H_j)\geq d_k$, there exists an isometry $U_j$ such that
\begin{equation}
\sqrt{N}\ket{\psi''_j}=(U_j\otimes \id)\ket{\omega_j}.
\end{equation}
We therefore define the state
\begin{equation}
\ket{\tilde{\psi}_j}:=\frac{1}{\sqrt{N}}(U_j\otimes \id)\ket{\omega_k};
\end{equation}
from the arguments above, we have that
\begin{align}
&|\braket{\tilde{\psi}_j}{\psi''_j}|=\sqrt{F(\rho_k,\rho_j)}\nonumber\\
&\leq 1-\frac{N}{2}\|\Phi''_k-\Phi''_j\|_1=1-O(\delta^{1/16}).
\end{align}
Putting everything together, we have that the state
\begin{equation}
\ket{\tilde{\psi}}:=\frac{1}{\sqrt{N}}\sum_j\ket{\tilde{\psi}_j}
\end{equation}
satisfies
\begin{equation}
\|\ket{\tilde{\psi}}-\ket{\psi'}\|_2\leq O(\delta^{1/32}).
\label{diff_tilde_sin_tilde}
\end{equation}
Moreover, 
\begin{equation}
\tr_{\H}(\proj{\tilde{\psi}_j})=\Phi''_k=:\tilde{\Phi}.
\end{equation}

Let $\tilde{\Phi}=\sum_l \frac{\lambda_l}{N}\ketbra{\varphi_l}{\varphi_l}$ be the spectral decomposition of $\tilde{\Phi}$. Then, for $k\in\{0,...,N-1\}$, there must exist an orthonormal set of vectors $\{\ket{\hat{\psi}_l(k)}\}_l\subset \H_k$ and $\{\lambda_l\}_l\subset \R^+$, with $\sum_l\lambda_l=1$, such that
\begin{equation}
\ket{\tilde{\psi}_k}=\frac{1}{\sqrt{N}}\sum_{l}\sqrt{\lambda_l}\ket{\hat{\psi}_l(k)}\ket{\varphi_l}.
\end{equation}
Hence, we can write 
\begin{equation}
\tilde{\rho} =\tr_A(\proj{\tilde{\psi}})= \sum_l \lambda_l \ketbra{\hat{\psi}_l}{\hat{\psi}_l},
\label{decomp_rho_tilde}
\end{equation}
with
\begin{equation}
\ket{\hat{\psi}_l}:=\frac{1}{\sqrt{N}}\sum_{k=0}^{N-1}\ket{\hat{\psi}_l(k)}.
\end{equation}
Also, for $\rho':=\tr_A(\proj{\psi'})$, it holds that
\begin{align}
&\|\rho'-\tilde{\rho}\|_1\leq \|\proj{\psi'}-\proj{\tilde{\psi}}\|_1\nonumber\\
&\leq O(\delta^{1/32}),
\label{diff_rho_prime_rho_tilde}
\end{align}
where the last equality follows from eq. (\ref{diff_tilde_sin_tilde}). 

Combined with eq. (\ref{primed_stats}), the last relation implies that
\begin{align}
&\tr(M_1\tilde{\rho})\leq O(\delta^{1/32}),\nonumber\\
&\tr(M_0e^{-iHt_l}\tilde{\rho}e^{iHt_l})\leq O(\delta^{1/32}),l\not=0.
\end{align}
By Lemma \ref{lemma_POVM_annihilation}, this implies that
\begin{align}
&\|M_1\tilde{\rho}\|_1\leq O(\delta^{1/64}),\nonumber\\
&\|M_0e^{-iHt_l}\tilde{\rho}e^{iHt_l}\|_1\leq O(\delta^{1/64}),l\not=0.
\label{stats_tilde_rho}
\end{align}

We therefore introduce the modified POVM:
\begin{align}
&\tilde{M}_0:=\sum_j \proj{\hat{\psi}_j},\nonumber\\
&\tilde{M}_1:=\id-\tilde{M}_0,
\end{align}
which by decomposition (\ref{decomp_rho_tilde}) and eq. (\ref{stats_tilde_rho}) satisfies
\begin{align}
&\|(\tilde{M}_a-M_a)e^{-iHt_l}\tilde{\rho}e^{iHt_l}\|_1\leq O(\delta^{1/64}),
\label{N_times}
\end{align}
for $l=0,...,N-1$, $a=0,1$. In fact, the inequality above holds for general times $t$. Indeed, note that
\begin{align}
&e^{-iH't}\tilde{\rho}e^{i{H'}t}= \nonumber \\
&\sum_{l,m=0}^{N-1}\braket{\bar{\psi}^N(t_l)}{\bar{\psi}^N(t)}\braket{\bar{\psi}^N(t)}{\bar{\psi}^N(t_m)}e^{-i{H'}t_l}\tilde{\rho}e^{i{H'}t_m}.
\label{eq:anytime}
\end{align}
From this and eq. (\ref{N_times}) we thus infer that
\begin{align}
&\|(\tilde{M}_a-M_a)e^{-iHt}\tilde{\rho}e^{iHt}\|_1\leq O(\delta^{1/64}),
\label{all_times}
\end{align}
for all $t\in\R$, $a\in\{0,1\}$.

Call $H^\perp$ the orthogonal complement of the subspace spanned by $\{\hat{\psi}_l(k)\}_{l,k}\subset \H$, and let $\ket{\alpha_j}_j$ be an orthonormal basis thereof. Define the isometry
$V: \H \rightarrow \mathbb{C}^N \otimes \mathbb{C}^2 \otimes l_2(\C)$
\begin{align}
    V \ket{\hat{\psi}_l(k)} &:= \ket{k} \ket{0} \ket{l} \ \forall k,l \nonumber \\
    V \ket{\alpha_j} &:= \ket{0} \ket{1} \ket{j} \ \forall j,
\end{align}
 Applying this isometry we get 
 \begin{align}
 V \tilde{M}_a e^{-iH't} \tilde{\rho} e^{-iH't} V^\dagger = \bar{M}^N_a e^{-i\bar{H}^Nt} \bar{\rho} e^{-i\bar{H}^Nt} \otimes \gamma_{\text{junk}},
\end{align}
where $\gamma_{\text{junk}}=\ketbra{0}{0} \otimes \sum_j \lambda_j \ketbra{j}{j}$. 

To prove the statement of the lemma, it remains to bound the quantity
\begin{equation}
\|M_ae^{-iHt}\rho e^{iHt}-\tilde{M}_ae^{-iH't}\tilde{\rho} e^{iH't}\|_1.
\end{equation}
From eq. (\ref{diff_psi_psi_prime_t}) and the contractiveness of the trace, we have that
\begin{equation}
\|e^{-iHt}\rho e^{iHt}-e^{-iH't}\rho'e^{-iH't}\|_1\leq O(\delta^{1/8})+O(\delta^{1/8}t).
\end{equation}
Invoking eqs. (\ref{diff_rho_prime_rho_tilde}), (\ref{all_times}) and the triangular inequality, we conclude:
\begin{equation}
\|M_ae^{-iHt}\rho e^{iHt}-\tilde{M}_ae^{-iH't}\tilde{\rho} e^{iH't}\|_1\leq O(\delta^{1/8}t)+O(\delta^{1/64}).
\end{equation}


\end{proof}



\section{An aha! dataset generated by two-level systems}
\label{app:aha_2}
Let $A=2$ and consider the single-measurement dataset $\tilde{P}_1$:
\begin{equation}
\tilde{P}_1(a|0)=\tilde{P}_1\left(a|\frac{\pi}{E^+}\right)=\frac{1}{2},a=0,1,
\end{equation}
depicted in Figure \ref{fig:weird_effects} with two blue points. 


\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{aha_2_dim.pdf}
    \caption{\textbf{An aha! dataset in two-level quantum systems.} The datasets $\tilde{P}_1,\tilde{P}_2$ are respectively depicted by blue and green dots. Purple curves denote the timeline with realization $(\C^3,\ket{\bar{\psi}^3},\bar{H}^3,\bar{M})$, and its complement complements. $\tilde{P}_2$ is shown to be an aha! dataset for $\tilde{P}_1$ at $\tau=\frac{2\pi}{E^+}$.}
    \label{fig:weird_effects}
\end{figure}


Let $\tau:=\frac{2\pi}{E^+}$, and consider the realization $(\C^3,\ket{\bar{\psi}^3},\bar{H}^3,\bar{M})$, with
\begin{align}
\bar{M}_{0|1}=e^{-i\bar{H}^3\tau_2}\frac{7\id+9\proj{\bar{\psi}_3}}{16}e^{i\bar{H}^3\tau_2}.
\end{align}
The timeline with realization $(\C^3,\ket{\bar{\psi}^3},\bar{H}^3,\bar{M})$ fits $\tilde{P}_1$, predicting $P(a|1,\tau)=\delta_{a,0}$. The complementary timeline, obtained through the exchange $a=1\leftrightarrow a=2$, predicts the complementary distribution $\delta_{a,1}$. By taking convex combinations of these two timelines, we can obtain any datapoint at $\tau$, and so $\tilde{P}_1$ has Knightian uncertainty at time $\tau$. This is denoted in Figure \ref{fig:weird_effects} by a vertical purple dotted line.

Now, add the dataset $\tilde{P}_2(a|t_j):=\mathbf{D}_2(a|t_j)$, depicted in Figure \ref{fig:weird_effects} with green dots, and consider the full dataset $\tilde{P}$, with $\tilde{P}(a|x,t_j)=\tilde{P}_x(a|t_j)$, for $x=1,2$.

By Proposition \ref{prop_self_test}, any realization $(\H,\rho,H,M)$ of $\tilde{P}_2$ has the property that 
\begin{equation}
\rho(t)=V^\dagger e^{-i\bar{H}^2t}(\proj{\bar{\psi}^2}\otimes\gamma) e^{i\bar{H}^2t} V,    
\end{equation}
for some isometry $V$ and state $\gamma$. Since $e^{-i\bar{H}^2\tau}=1$, this means that $\rho(0)=\rho(\tau)$, and consequently all timelines $P$ fitting $\tilde{P}$ satisfy $P(a|1,\tau_2)=\tilde{P}(a|1,0)=\frac{1}{2}$. Thanks to the addition of the dataset $\tilde{P}_2$, we have hence gone from a scenario of total uncertainty to a scenario of total certainty. It follows that $\tilde{P}_2$ is an aha! dataset for $\tilde{P}_1$.

\section{Proof of Lemma \ref{lemma_T_m_approx}}
\label{app:T_m_approx}
The proof relies on the following, general lemma.
\begin{lemma}
Let $Y\subset \R^n$ be a closed, convex cone with non-empty interior and let $\hat{n}\in\R^n$. Consider the following convex optimization problem:
\begin{align}
f^\star:=&\min \vec{f}\cdot \vec{y}\nonumber\\
\mbox{such that }&\vec{y}\in Y, \vec{y}\cdot \hat{n}=1,\nonumber\\
&\mathbb{A}\cdot \vec{y}\leq \vec{b}.
\label{problem_abstract}
\end{align}
Suppose that there exist $r>0$, and feasible $\vec{y}^0$ such that 
\begin{equation}
\vec{b}-\mathbb{A}\dot \vec{y}^0>r \left(\begin{array}{c}1\\1\\\vdots\\1\end{array}\right).
\label{special_interior}
\end{equation}

%  and, for any vector $\vec{v}$ and matrix $C$, let $\|C\|$ and $\|\vec{v}\|_*$ denote
% \begin{align}
% &\|C\|=\max_{\|\vec{u}\|\leq 1}\|C\vec{u}\|_\infty,\nonumber\\
% &\|\bar{v}\|_*=\max_{\|\vec{u}\|\leq 1}|\vec{u}\cdot \vec{v}|.
% \end{align}

Let $\|\|$ be any vector norm, and let $\vec{y}^+\in\R^n$ be such that 
\begin{enumerate}
    \item $\mathbb{A}\cdot\vec{y}^+\leq \vec{b}$.
    \item $\|\vec{y}^+-\vec{y}\|\leq \epsilon$, for some $\vec{y}\in Y$ with $\hat{n}\cdot \vec{y}=1$.
\end{enumerate}
Then, $\vec{f}\cdot{y}^+$ is lower bounded by 
\begin{equation}
f^\star-\epsilon\left(\max_{\|\vec{u}\|\leq 1}\|A\vec{u}\|_\infty\frac{\vec{f}\cdot\vec{y}^0-f^\star}{r}+\max_{\|\vec{u}\|\leq 1}|\vec{f}\cdot\vec{u}|\right).
\label{bound_accuracy}
\end{equation}

\end{lemma}
\begin{proof}
First we show that problem (\ref{problem_abstract}) has no duality gap. Take any point $\vec{y}$ belonging to the interior of $Y\cap\{\vec{y}:\vec{y}\cdot \hat{n}=1\}$. Then, there exists $\lambda\in (0,1)$ such that the interior point
\begin{equation}
\vec{y}^\lambda:=\lambda \vec{y}^0+(1-\lambda)\vec{y}
\end{equation}
satisfies the condition $\vec{b}>\mathbb{A}\cdot\vec{y}^\lambda$. Problem (\ref{problem_abstract}) therefore admits a strictly feasible point, and thus, by Slater's criterion \cite{Nocedal2006}, has no duality gap.

The dual of Problem (\ref{problem_abstract}) can be shown to be:
\begin{align}
f^\star:=&\max -\lambda-\vec{\mu}\cdot(\vec{b}+\mathbb{A}\vec{z})\nonumber\\
\mbox{such that }&\vec{f}+\lambda\hat{n}+\mathbb{A}^T\vec{\mu}\in Y^*,\nonumber\\
&\vec{\mu}\geq 0.
\label{abstract_dual}
\end{align}
For any $\delta>0$, there exists a feasible point of (\ref{abstract_dual}), with objective value greater than $f^\star-\delta$. Let $(\lambda,\vec{\mu})$ be any such point. Then we have that
\begin{align}
&0\leq (\vec{f}+\lambda\hat{n}+\mathbb{A}^T\vec{\mu})\cdot \vec{y}^0\nonumber\\
&=\vec{f}\cdot \vec{y}^0+\lambda +\vec{\mu}\cdot \mathbb{A}\cdot \vec{y}^0\nonumber\\
&\leq \vec{f}\dot \vec{y}^0+\lambda+\vec{\mu}\cdot \vec{b}-r\sum_j\mu_j\nonumber\\
&\leq \vec{f}\cdot \vec{y}^0-f^\star +\delta-r\sum_j\mu_j.
\end{align}
It follows that
\begin{equation}
\sum_j\mu_j\leq \frac{1}{r}\left(\vec{f}\cdot \vec{y}^0-\vec{f}^\star +\delta\right).
\end{equation}
Since $\{\mu_j\}_j$ is bounded, then so is $\lambda$; indeed, by assumption,
\begin{equation}
-f^\star -\vec{\mu}A\vec{z}\leq \lambda\leq -f^\star+\delta-\vec{\mu}A\vec{z}.
\end{equation}
Since in the vicinity of the optimal objective value all dual variables are bounded, it follows that the dual problem (\ref{abstract_dual}) has an optimal solution $(\lambda^\star,\vec{\mu}^\star)$. Moreover, it satisfies
\begin{equation}
\|\vec{\mu}^\star\|_1\leq \frac{1}{r}\left(\vec{f}\cdot \vec{y}^0-\vec{f}^\star\right).
\label{bound_mu}
\end{equation}

Now, let $\vec{y}^+$ satisfy the conditions of the lemma. Then, there exists $\vec{y}\in Y$ satisfying $\vec{y}\cdot \hat{n}=1$, such that $\vec{y}^+=\vec{y}+\vec{\varepsilon}$, with $\|\vec{\varepsilon}\|\leq \epsilon$. Thus, we have:
\begin{align}
&0\leq \vec{f}\cdot\vec{y}+\lambda^\star+\vec{\mu}^\star\cdot \mathbb{A}\vec{y}\nonumber\\
&=\vec{f}\cdot\vec{y}^++\lambda^\star+\vec{\mu}^\star\cdot\mathbb{A}\cdot\vec{y}^+-\vec{\mu}^\star\cdot \mathbb{A}\vec{\varepsilon}-\vec{f}\cdot \vec{\varepsilon}\nonumber\\
&\leq \vec{f}\cdot\vec{y}^++\lambda^\star+\vec{\mu}^\star\cdot\mathbb{A}\vec{z}+\vec{\mu}^\star\cdot\vec{b}-\vec{\mu}^\star\cdot \mathbb{A}\vec{\varepsilon}-\vec{f}\cdot \vec{\varepsilon}\nonumber\\
&= \vec{f}\cdot \vec{y}^+-\vec{f}^\star-\vec{\mu}^\star\cdot \mathbb{A}\vec{\varepsilon}-\vec{f}\cdot \vec{\varepsilon}.
\end{align}
Invoking the bound (\ref{bound_mu}) on $\|\vec{\mu}^\star\|_1$, we arrive at eq. (\ref{bound_accuracy}).
\end{proof}

To apply this result to our extrapolation scenario, consider an extrapolation problem $(\tilde{P},\delta,f)$ and choose a target set of datasets $T\subset \D^{N+1}$. Note that $\D^{N+1}$ has no interior, due to equality constraints of the form: 
\begin{equation}
\sum_aP(a|x,t_j)=\sum_aP(a|x',t_k).
\end{equation}
Let us then choose a lower dimensional representation $\D^{N+1}$ that is free from such linear constraints, e.g.: 
\begin{align}
&\left(P(a|x,t_j):a=1,...,A-1,\right.\nonumber\\
&\left.x=1,...,X, j=1,...,N+1\right)
\end{align}
We add an extra dimension to express normalization. We obtain the set of vectors of the form:
\begin{align}
&\mathbb{D}_{N+1}:=\left\{(1,\left(P(a|x,t_j):a=1,...,A-1,\right.\right.\nonumber\\
&\left.\left. x=1,...,X, j=1,...,N+1\right):P\in \D^{N+1}\right\}.
\end{align}
There exists an invertible linear transformation $C$ mapping $\D^{N+1}$ to $\mathbb{D}_{N+1}$. Let $Y$ denote the cone generated by the transformed target datasets $CT$ and define the vector $\hat{n}:=(1,0,...,0)$. Note that $C^{-1}\bar{y}\in T$ for any $y\in Y$ with $\vec{y}\cdot\hat{n}=1$. We next define the vector $\vec{f}$ through the identity $\vec{f}\cdot \vec{y}=f(C^{-1}\vec{y})$. With these definitions, we account for the first two lines of problem (\ref{problem_abstract}). 

We still need to encode the constraints
\begin{equation}
\sum_a|P(a|x,t_j)-\tilde{P}(a|x,t_j)|\leq \delta(x,j),\forall x, j=1,...,N.
\end{equation}
These constraints are equivalent to
\begin{align}
&\sum_a g(a,x,j)P(a|x,t_j)\leq \delta(x,j)+\sum_a\tilde{P}(a|x,t_j)g(a,x,j),\nonumber\\
&\forall x, j=1,...,N,
\label{linearized_cons}
\end{align}
for all functions 
\begin{equation}
g:\{1,...,|A|\}\times\{1,...,|X|\}\times \{1,...,N\}\to\{-1,1\}.    
\end{equation}



In turn, those can be represented by the constraint
\begin{equation}
\mathbb{A}'\cdot{P}\leq \vec{b},
\end{equation}
where 
\begin{align}
&\mathbb{A}'_{(a,x,j,g),(a',x',k)}:=\delta_{a,a'}\delta_{x,x'}\delta_{jk}(1-\delta_{j,N+1})g(a,x,j),\nonumber\\
&b_{(x,j,g)}:=\delta(x,j)+\sum_a\tilde{P}(a|x,t_j)g(a,x,j).
\end{align}
Define
\begin{equation}
\mathbb{A}:=\mathbb{A}'C^{-1}.
\end{equation}
Then we have one-to-one mapping between all $\vec{P}\in T$ fitting the noisy dataset $(\tilde{P},\delta)$ and all vectors $\vec{y}\in Y$ satisfying $\vec{y}\cdot \hat{n}=1$ and $\mathbb{A}\leq \vec{b}$. We have just reformulated the extrapolation problem as an instance of problem (\ref{problem_abstract}).

To invoke the lemma, we just need to choose a norm $\|\|$. We take the norm defined by
\begin{equation}
\|\vec{s}\|:=\|C^{-1}\vec{s}\|',
\end{equation}
with $\|\|':=l_\infty(l_1(\R^{A})^{X(N+1)})$. That is:
\begin{equation}
\|q\|'=\max_{x,j}\sum_a|q(a|x,t_j)|.
\end{equation}
With this norm, 
\begin{equation}
\max_{\|\vec{v}\|\leq 1}\|\mathbb{A}\vec{v}\|_{\infty}=1.    
\end{equation}
In addition,
\begin{equation}
\max_{\|\vec{v}\|\leq 1}|\vec{f}\cdot \vec{v}|\leq \sum_{x}\max_{a}|f(a|x)|.
\end{equation}

We can reformulate our relaxation bounds as: for any $P^+\in T_m$, there exists $P\in T$ such that
\begin{equation}
\|P^+-P\|'\leq \epsilon_m.
\end{equation}

Consequently, if there exists $P^0\in T$ such that 
\begin{equation}
\delta(x,j)-\sum_{a}|P^0(a|x,t_j)-\tilde{P}(a|x,t_j)|\geq r>0,
\end{equation}
for all $x,j$, then we can invoke the lemma and conclude that
\begin{equation}
f(P^+)\geq f^\star-\epsilon_m\left(\frac{f(P^0(\tau))-f^\star}{r}+\sum_{x}\max_{a}|f(a|x)|\right).
\end{equation}
Replacing $f^\star$ by $\mu^-$, we arrive at the statement of Lemma \ref{lemma_T_m_approx}. The proof for $\mu^+$ is analogous.


\section{Proof of Lemma \ref{lemma_speed_conv_A_hierarhy}}
\label{app:proof_conv_A}
Let $Q\in A_m(\bar{E};E^+)$ and let $\tilde{M},(p_j)_j,\gamma$ represent the objects appearing in the definition of $A_m(\bar{E};E^+)$. Note that, for condition (\ref{aver_spec}) to hold, it must be the case that
\begin{equation}
p_m\leq \frac{\bar{E}}{E^+}.
\label{bound_occu}
\end{equation}

Define the matrix
\begin{equation}
\Lambda:=\left(\begin{array}{cc}\mbox{diag}(p_1^{-1/2},...,p_{m-1}^{-1/2})&0\\0&\gamma^{-1/2}\end{array}\right),
\end{equation}
where, for simplicity, we have assumed that $p_j>0$, for all $j$ and that $\gamma>0$ (the general case can be derived, e.g., by perturbing both objects to make them positive or positive definite, respectively). Then we have that
\begin{equation}
M_{a|x}:=\Lambda \tilde{M}_{a|x} \Lambda^\dagger
\end{equation}
define POVMs. Next, define the vectors
\begin{equation}
\ket{\psi^+_j}:=\frac{1}{\sqrt{p_m}}\gamma^{1/2}\ket{j}.
\end{equation}
Then we have that
\begin{equation}
\braket{\psi^+_j}{\psi^+_k}=\frac{1}{p_m}\gamma_{jk};
\end{equation}
in particular, $\{\ket{\psi^+_j}\}_j$ are normalized.

Define $P(a|x,t_j):=f(a|x,j,\tilde{M})$. Then it is immediate to verify that
\begin{equation}
P(a|x,t_j)=\bra{\psi_j}M_{a|x}\ket{\psi_j},
\end{equation}
with
\begin{equation}
\ket{\psi_j}:=\sum_{k=0}^{m-1}\sqrt{p_k}e^{-iE_kt_j}\ket{k}\oplus\sqrt{p_{m}}\ket{\psi^+_j}.
\end{equation}
We next define the normalized vector
\begin{equation}
\ket{\psi}=\sum_{j=0}^{m-1}\sqrt{\frac{p_j}{1-p_m}}\ket{j}.
\end{equation}
Note that the average energy of this state equals
\begin{align}
&\sum_{k=0}^{m-1}\frac{p_k}{1-p_m}E_k=\sum_{k=0}^{m-1}p_kE_k+p_m\sum_{k=0}^{m-1}\frac{p_k}{1-p_k}E_k\nonumber\\
&\leq \sum_{k=0}^{m-1}p_kE_k+p_mE_m\leq \bar{E}.
\end{align}
For $H:=\sum_{k=0}^{m-1}E_k\proj{E_k}$, it can be verified that
\begin{equation}
\bra{\psi_j}e^{-iHt_j}\ket{\psi}= \sqrt{1-p_m}.
\label{diffe_vectors}
\end{equation}
Define 
\begin{equation}
\check{P}(a|x,t_j):=\bra{\psi}e^{iHt_j}M_{a|x}e^{-iHt_j}\ket{\psi}.
\end{equation}
By construction, $\check{P}\in A(\bar{E})$.

From eq. (\ref{diffe_vectors}), we have that
\begin{align}
&\sum_a|P(a|x,t_j)-\check{P}(a|x,t_j)|\nonumber\\
&\leq \|e^{-iHt_j}\proj{\psi}e^{iHt_j}-\proj{\psi_j}\|_1=2\sqrt{p_m}\nonumber\\
&\leq 2\sqrt{\frac{\bar{E}}{E^+}},
\end{align}
where we invoked eq. (\ref{bound_occu}) in the last inequality. Thus, 
\begin{align}
&\sum_a|Q(a|x,t_j)-\check{P}(a|x,t_j)|\nonumber\\
&\leq \sum_a|Q(a|x,t_j)-P(a|x,t_j)|+|P(a|x,t_j)-\check{P}(a|x,t_j)|\nonumber\\
&\leq 2\sin\left(\frac{E^+ |t_j|}{m}\right)+2\sqrt{\frac{\bar{E}}{E^+}}.
\end{align}

This concludes the proof of Lemma \ref{lemma_speed_conv_A_hierarhy}.


\section{Decay matrices}
\label{app:overlaps}
The goal of this section is to arrive at a practical characterization of the set below.
\begin{defin}
Let $t_1,...,t_N, E^+\in\R$. The cone $G(E^+,\vec{t})$ is the closure of the set of matrices $\gamma$ of the form:
\begin{equation}
\gamma_{jk}=\int_{E^+}^\infty dE \rho^+(E)e^{-iE(t_j-t_k)},
\end{equation}
where $\rho^+(E)dE$ is a (possibly non-normalized) measure.     
\end{defin}
Note that, for each $\gamma\in G(E^+,\vec{t})$ and each $\delta>0$, there exists a (non-normalized) state $\ket{\psi^+}$ and a Hamiltonian $H^+\geq E^+$ such that eq. (\ref{hamil2gamma}) holds up to error $\delta>0$.

We next show that $G(E^+,\vec{t})$ is, in fact, independent of $E^+$. From now on, we will thus designate $G(E^+,\vec{t})$ as $G(\vec{t})$.
\begin{lemma}
\label{lemma_indent_Gs}
$G(E^+,\vec{t})=G(-\infty,\vec{t})$.    
\end{lemma}
\begin{proof}
Clearly $G(E^+,\vec{t})\subset G(-\infty,\vec{t})$, so we next prove the opposite inclusion relation. 

Let $\gamma\in G(-\infty,\vec{t})$. Then, for any $\delta>0$, there exists a measure $\rho(E)dE$ over the reals such that the matrix
\begin{equation}
\gamma'_{jk}:=\int_{-\infty}^\infty dE \rho(E)e^{-iE(t_j-t_k)}
\label{measu_inf}
\end{equation}
satisfies
\begin{equation}
|\gamma_{jk}-\gamma'_{jk}|\leq \delta,\forall j,k.
\end{equation}
Since $(\gamma'_{jk})_{jk}$ is a conic combination of matrices of the form
\begin{equation}
(e^{-iE(t_k-t_j)})_{jk},
\end{equation}
for $E\in \R$, by Caratheodory's theorem we can choose $\rho(E)dE$ to be of the form
\begin{equation}
\rho(E)=\sum_{j=1}^L\lambda_j\delta(E-E_j),
\end{equation}
with $L\leq\frac{N(N-1)}{2}+1$. Now, let $E_1=\min_j E_j$. If $E_1\geq E^+$, then $\gamma'\in G(E^+,\vec{t})$ and we are done. Otherwise, choose $\Delta\geq E^+-E_1$ such that
\begin{equation}
|e^{-i\Delta t_j}-1|<\delta, \forall j.
\end{equation}
The existence of such an energy difference $\Delta$ is guaranteed from the fact that the trajectory
\begin{equation}
(e^{-i\Delta t_1},...,e^{-i\Delta t_N}):\Delta\in\R
\end{equation}
is almost periodic in $[0,2\pi)^N$ \cite{chávez2020}. Next, define the distribution
\begin{equation}
\rho^+(E):=\rho(E-\Delta).
\end{equation}
By definition, $\rho^+(E)$ has support in $[E^+,\infty)$. Moreover,
\begin{align}
\gamma^+_{jk}&:=\sum_l\lambda_l e^{-i(E_l-\Delta)(t_j-t_k)}\nonumber\\
&=\sum_l\lambda_l e^{-iE_l(t_j-t_k)}+r^\delta_{jk}\nonumber\\
&=\gamma'_{jk}+r^\delta_{jk},
\end{align}
with
\begin{equation}
|r^\delta_{jk}|\leq \delta\sum_l\lambda_l\leq (\gamma_{11}+\delta)\delta,
\end{equation}
where we invoked the relations $|\gamma_{11}-\gamma'_{11}|\leq \delta$ and $\gamma'_{11}=\sum_l\lambda_l$.

Thus, for any $\delta>0$, there exists $\gamma^+\in G(E^+,\vec{t})$ such that
\begin{equation}
|\gamma_{jk}-\gamma^+_{jk}|\leq \delta+(\gamma_{11}+\delta)\delta.
\end{equation}
Since $G(E^+,\vec{t})$ is closed, it follows that $\gamma\in G(E^+,\vec{t})$.

\end{proof}



What kind of constraints is $G(\vec{t})$ subject to? Clearly, for any $\vec{t}=(t_1,...,t_N)$, we have that $G(\vec{t})\subset C_N$, see Definition \ref{defin_C_N}. However, as we will next see, for general $\vec{t}$ it is not the case that $G(\vec{t})= C_N$.




\subsection{The general case}
Given measurement times $t_1,...,t_N$, let $n$ denote the smallest natural number such that
\begin{equation}
t_k=\sum_{j=1}^n a_{kj}s_j+t_0, \mbox{ for } k=1,...,N,
\label{rational_decomp}
\end{equation}
where $\{a_{kj}\}_{kj}\subset \Z$, $t_0\in\R$, $\{s_j\}_j\subset \R$. Note that it must hold that the generators $\{s_j\}_j$ are \emph{non-congruent} numbers, i.e., there does not exist a non-zero vector of rational numbers $(q_j)_j$ such that
\begin{equation}
\sum_{j=1}^nq_js_j=0.
\label{congruency}
\end{equation}
Otherwise, one could express one of the numbers $\{s_j\}_j$ as a rational linear combination of the others. Dividing the rest by the minimum common denominator, we would then have another decomposition like (\ref{rational_decomp}) with one generator less.

\begin{lemma}
\label{lemma_all_Gs}
Let $t_1,...,t_N$ admit a decomposition like (\ref{rational_decomp}), with non-congruent $\{s_j\}_j$. Then, $G(\vec{t})$ equals the cone $Z(a)$ of matrices generated by
\begin{equation}
\gamma_{jk}(z)=\prod_{l=1}^nz_l^{a_{kl}-a_{jl}},
\label{gamma_convex}
\end{equation}
with $z\in \mathbb{T}^n:=\{z\in\C^n:|z_l|=1, \forall l\}$.
\end{lemma}
\begin{proof}
Let $\gamma\in G(\vec{t})$. Then, for any $\delta>0$, there exists a (non-normalized) measure $\rho(E)dE$ such that the matrix $\gamma'$, defined by
\begin{align}
\gamma'_{jk}:=\int \rho(E)dE e^{-iE(t_k-t_j)},
\end{align}
satisfies $|\gamma_{jk}-\gamma'_{jk}|\leq \delta$, for all $j,k$. Expressing $\{t_j\}_j$ in terms of $t_0$ and the generators, we have that
\begin{align}
\gamma'_{jk}=\int \rho(E)dE e^{-iE(\sum_l(a_{jl}-a_{kl})s_l)},
\end{align}
Define $z_l(E):=e^{-iEs_l}$. Then we have that
\begin{align}
\gamma'_{jk}=\int \rho(E)dE \prod_lz_l(E)^{a_{kl}-a_{jl}}.
\end{align}
Thus, $\gamma'\in Z(a)$. Since $\delta>0$ is arbitrary, this proves that $G(\vec{t})\subset Z(a)$.

Conversely, suppose that $\gamma \in Z(a)$. Then there exists a measure $\rho(z)dz$ with support in $\mathbb{T}^n$ such that 
\begin{equation}
\gamma_{jk}=\int \rho(z)dz\gamma_{jk}(z).
\end{equation}

Since $\{s_j\}_j$ are not congruent, the trajectory 
\begin{equation}
(e^{-iEs_1},...,e^{-iEs_n}):E\in\R
\end{equation}
is dense in $\mathbb{T}^n$. This implies that, for any $\delta$, there exists $E(z)\in \R$ such that 
\begin{equation}
|\gamma_{jk}(z)-e^{-iE(z)(t_j-t_k)}|\leq \delta,
\end{equation}
for all $j,k$. Thus, the matrix $\gamma'\in G(\vec{t})$, defined through
\begin{equation}
\gamma'_{jk}=\int \rho(z)dze^{-iE(z)(t_j-t_k)},
\end{equation}
satisfies
\begin{equation}
|\gamma'_{jk}-\gamma_{jk}|\leq \delta\int \rho(z)dz=\delta \gamma_{11}.
\end{equation}
Since $\delta$ can be made arbitrarily small, we then have that $Z(a)\subset G(\vec{t})$.

\end{proof}

\begin{remark}
\label{remark_func2pol}
There is a one-to-one correspondence between the set $F$ of linear functionals $h:Z(a)\to \R$ and the set of symmetric trigonometric polynomials of the form
\begin{equation}
h(z,z*)=\sum_{\vec{j}\in {\cal Z}(a)}h(\vec{j})z^{\vec{j}},
\label{polyZ}
\end{equation}
where $z^{\vec{j}}=\prod_{k=1}^nz^{j_k}$ and ${\cal Z}(a)\subset \mathbb{Z}^n$ is defined by
\begin{equation}
{\cal Z}(a)=\{(a_{j,l}-a_{k,l})_l:j,k=1,...,n\}.
\end{equation}
Indeed, define $\vec{a}^j:=(a_{j,l})_l$ and let $\gamma\in Z(a)$, with measure $\sigma(z)dz$. For any matrix $H$, it holds that
\begin{align}
&\sum_{jk}H_{jk}\gamma_{jk}\nonumber\\
&=\int dz\sigma(z)\sum_{jk}H_{jk}z^{\vec{a}^j-\vec{a}^k}\nonumber\\
&=\int dz\sigma(z)h(z,z^*),
\end{align}
where $h(z,z^*)$ is a polynomial of the form (\ref{polyZ}). If $\sum_{jk}H_{jk}\gamma_{jk}\in \R$ for all $\gamma\in Z(a)$, then $h$ must be symmetric, i.e., $h(z,z^*)\in \R$, for all $z\in \mathbb{T}^n$. In turn, any symmetric polynomial $h$ defines a linear functional on $Z(a)$ by 
\begin{equation}
\gamma(h):=\sum_{\vec{j}\in {\cal Z}(a)}h_{\vec{j}}\gamma_{k(\vec{j}),l(\vec{j})},
\end{equation}
where $k(\vec{j}),l(\vec{j})$ are any pair of functions such that $\vec{a}^{l(\vec{j})}-\vec{a}^{k(\vec{j})}=\vec{j}$, for $\vec{j}\in {\cal Z}(a)$.

\end{remark}


\begin{remark}
\label{remark_id_G}
For all $a$, $\id\in Z(a)$. In effect, consider the distribution $\sigma(z)dz$, with
\begin{equation}
\sigma(z)=\frac{1}{R^n}\sum_{j_1,....,j_n=0}^{R-1}\prod_{l=1}^n\delta\left(z_l-e^{-i\frac{2\pi j_l}{R}}\right),
\end{equation}
where $R=2\max_{j,k,l}|a_{kl}-a_{jl}|$. It can be verified that 
\begin{equation}
\int dz\sigma(z)\gamma_{jk}(z)=\delta_{jk}.    
\end{equation}

\end{remark}



The cone $Z(a)$ can be characterized through
the Lasserre-Parrilo hierarchy of SDP relaxations \cite{lasserre} \cite{parrilo}. In a nutshell, one would consider the set $\R\langle (z_1,...,z_n)\rangle$ of polynomials in the complex variables $(z_1,...,z_n)$ of module $1$ and their complex conjugates $(\bar{z}_1,....,\bar{z}_N)=(z^{-1}_1,....,z^{-1}_N)$. Next, given some distribution $\rho(z)dz$ of weight $p_{n}$, one thinks of the properties of \emph{momenta} $y$ of the form
\begin{equation}
y(k_1,...,k_n)=\langle\prod_{j=1}^nz^{k_j}\rangle_\rho,
\end{equation}
where $k_1,...,k_n\in\Z$. For any $m\in\N$, it turns out that the \emph{moment matrix}
\begin{equation}
(W_m(y))_{\vec{j},\vec{k}}=y(k_1-j_1,...,k_n-j_n),
\end{equation}
labeled by the vectors $\vec{j},\vec{k}\in\{-m,...,m\}^n$, is positive semidefinite, see \cite{lasserre}. We relate the momenta $y$ with the matrix $\gamma$ through
\begin{equation}
y(a_{k,1}-a_{j,1},...,a_{k,n}-a_{j,n})=\gamma_{jk},\forall j,k.
\end{equation}
We are ready to provide an SDP relaxation for $G(\vec{t})$.
\begin{defin}
Let $\vec{t}$ admit a minimal decomposition  (\ref{rational_decomp}), and let $m\geq \max_{i,j,k,l}|a_{ij}-a_{kl}|$. $G_m(\vec{t})$ is the set of all $N\times N$ matrices $\gamma$ such that there exists $(y(\vec{k}))_{\vec{k}\in\{-m,...,m\}^n}\in \C^{(2m+1)^n}$, with
\begin{align}
&W_m(y)\geq 0,\nonumber\\
&y(a_{k,1}-a_{j,1},...,a_{k,n}-a_{j,n})=\gamma_{jk},\forall j,k.
\end{align}
\end{defin}
From the above, it follows that $G(\vec{t})\subset G_m(\vec{t})$. Moreover, $\lim_{m\to\infty}G_m(\vec{t})=G(\vec{t})$ \cite{lasserre, parrilo}. 

\begin{remark}
\label{remark_func2pol_m}
The argument of remark \ref{remark_func2pol} generalizes to $G_m(\vec{t})$: the set of linear functionals on $G_m(\vec{t})$ is also in one-to-one correspondence with the set of symmetric polynomials $h(z,z^*)$. 
\end{remark}


The work of \cite{bounds_lasserre} provides bounds on the convergence of the Lasserre-Parrilo hierarchy when applied to solve polynomial optimization problems within $\mathbb{T}^n$. Such bounds allow us to prove the following convenient result.
\begin{prop}
\label{prop_G_lasserre}
Let $\gamma\in G_m(\vec{t})$, and define
\begin{equation}
d:=\left\lceil\frac{1}{2}\max_{j,k}|a_{jl}-a_{kl}|\right\rceil.
\label{def_d_K}
\end{equation}
Then, for $m\geq 3d$ and $\varepsilon\leq 1$, with
\begin{align}
&\varepsilon:=N(N-1)\left[\left(1-\frac{6d^2}{m^2}\right)^{-n}-1\right]\approx,\nonumber\\
&\approx \frac{6d^2n N(N-1)}{m^2},
\label{def_varepsilon_d}
\end{align}
it holds that the matrix
\begin{equation}
\tilde{\gamma}=\frac{1}{1+\varepsilon}\gamma +\frac{\varepsilon}{1+\varepsilon}\gamma_{11}\id_N
\label{def_tilde_gamma}
\end{equation}
satisfies $\tilde{\gamma}\in G(\vec{t})$.

\end{prop}
In other words: for large $m$, it is enough to mix $\gamma\in G_m(\vec{t})$ a little bit with the $\gamma_{11}$-scaled identity matrix to arrive at a feasible decay matrix $\tilde{\gamma}$.

To prove the proposition, we first need to prove a minor lemma.
\begin{lemma}
\label{lemma_min2norm}
Let $h(z,z^*)$ be a symmetric, trigonometric polynomial with no constant term, i.e.,
\begin{equation}
h(z,z^*)=\sum_{\vec{j}\in Z}h_{\vec{j}}z^{\vec{j}}+h^*_{\vec{j}}z^{\vec{j}}z^{-\vec{j}},
\end{equation}
where $Z\subset \Z^n\setminus\{\vec{0}\}$ is such that, if $\vec{j}\in Z$, then $-\vec{j}\not\in Z$. Then,
\begin{equation}
-\min_{z\in \mathbb{T}^n}h(z,z^*)\geq \max_{\vec{j}\in Z}|h_{\vec{j}}|.
\label{upper_bound_min}
\end{equation}
Thus,
\begin{equation}
\|h\|_F:=\sum_{\vec{j}}|h_{\vec{j}}|\leq -|Z|\min_{z\in \mathbb{T}^n}h(z,z^*).
\label{min2norm}
\end{equation}
\end{lemma}
\begin{proof}
Let $\vec{s}\in Z$ be such that $|h_{\vec{s}}|\geq |h_{\vec{k}}|$, $\forall \vec{k}\in Z$, let $\theta\in\R$ be the complex phase of $h_{\vec{s}}$ (i.e., $h_{\vec{s}}=|h_{\vec{s}}|e^{i\theta}$) and let $R\in \N$ be such that $R\geq 2|j_k|$, for all $\vec{j}\in Z$. Consider the probability distribution
\begin{align}
&\sigma(z)dz\nonumber\\
&=\frac{1}{(2R+1)^n}\sum_{\vec{k}\in \{-R,...,R\}^n\}}\left(1-\cos\left(\frac{2\pi\vec{k}\cdot \vec{s}}{2R+1}-\theta\right)\right)\nonumber\\
&\cdot\prod_{l=1}^n\delta\left(z_l-e^{-i\frac{2\pi k_l}{R}}\right)dz.
\end{align}
One can verify that $\sigma(z)dz$ is indeed non-negative and normalized. Moreover, 
\begin{equation}
\int_{\mathbb{T}^n} \sigma(z)h(z,z^*)dz=-|h_{\vec{s}}|.
\end{equation}
This implies eq. (\ref{upper_bound_min}).

Eq. (\ref{min2norm}) follows from eq. (\ref{upper_bound_min}) and the obvious inequality 
\begin{align}
\sum_{\vec{j}\in Z}|h_{\vec{j}}|\leq |Z|\max_{\vec{j}}|h_{\vec{j}}|.
\end{align}

\end{proof}

\begin{proof}[Proof of Proposition \ref{prop_G_lasserre}]
Let $\gamma\in G_m(\vec{t})$ and let $\tilde{\gamma}$ be as defined by eq. (\ref{def_tilde_gamma}). Assume that $\tilde{\gamma}\not\in G(\vec{t})$. Since $G(\vec{t})$ is convex and closed, by the Hahn-Banach theorem there exists a functional $h$, which by Remark \ref{remark_func2pol} we can identify with a symmetric trigonometric polynomial with support in ${\cal Z}(a)$, such that
\begin{equation}
\hat{\gamma}(h)\geq 0, \forall \hat{\gamma}\in G(\vec{t}),
\label{separation}
\end{equation}
and $\tilde{\gamma}(h)<0$.

Let us decompose $h$ as $h(z,z^*)=\lambda+h'(z,z^*)$, with $\lambda\in\R$ and $h'(z,z^*)$ having no constant term. By eq. (\ref{separation}) and the identity $Z(a)=G(\vec{t})$, the polynomial $h$ must satisfy $h(z,z^*)\geq 0$, for all $z\in \mathbb{T]}_n$. 

By Lemma \ref{lemma_min2norm}, $\min_{z}h'(z,z)<0$ if $h'(z,z)\not=0$, which implies that $\lambda>0$. Re-scaling $h$, we can choose $\lambda=1$. In that case, also by Lemma \ref{lemma_min2norm}, we have that
\begin{equation}
\|h'\|_F\leq -N(N-1)\min_{z\in \mathbb{T}^n} h'(z,z^*) \leq N(N-1).
\label{bound_F_norm}
\end{equation}
Recall that $\gamma\in G_m(\vec{t})$. Adapting \cite[Theorem 1]{bounds_lasserre} to a scenario with unnormalized moment matrices, we have that
\begin{equation}
\gamma(h)\geq -\epsilon\gamma_{11},
\end{equation}
for
\begin{equation}
\epsilon\leq \|h'\|_F\left[\left(1-\frac{6r^2}{m^2}\right)^{-n}-1\right],
\end{equation}
where $r:=\left\lceil\frac{\mbox{deg}(h)}{2}\right\rceil$. Note that $r=d$, as defined in eq. (\ref{def_d_K}).
By eq. (\ref{bound_F_norm}) we thus have that $\epsilon\leq\varepsilon$. It follows that
\begin{align}
&\tilde{\gamma}(h)=\frac{\varepsilon}{1+\varepsilon}\gamma_{11}+\frac{\gamma(h)}{1+\varepsilon}\nonumber\\
&\geq \frac{1}{1+\varepsilon}\gamma_{11}(\varepsilon-\epsilon)\geq 0.
\end{align}
Thus, $\tilde{\gamma}(h)\geq 0$ and we reach a contradiction. This implies that $\tilde{\gamma}\in G(\vec{t})$.

\end{proof}


\subsection{Exact SDP representability}
In the previous section, we provided a simple recipe to generate a complete hierarchy of SDP relaxations for $G(\vec{t})$. In this section, we examine under which circumstances the set $G(\vec{t})$ admits an exact SDP representation, i.e., no hierarchies are needed. 


\subsubsection{Equidistant times}
\label{app:equidistant}
Suppose that the decomposition (\ref{rational_decomp}) is such that $n=1$. That is, 
\begin{equation}
t_k=a_k s+t_0,
\label{chipped_eq}
\end{equation}
with $a_1,...,a_N\in\N$. We next show that the corresponding set $G(\vec{t})$ admits an SDP representation. 

In fact, for ease of notation, we will provide an SDP representation of $G(\vec{t})$ when $\vec{t}$ is a vector of equidistant times, i.e., there exist $\Delta,t_0'$ such that
\begin{equation}
t_k=k \Delta+t'_0.
\label{full_eq}
\end{equation}
Note that the times (\ref{full_eq}) are a superset of (\ref{chipped_eq}), for $s=\Delta$ and $t'_0=t_0+\Delta(\min_k a_k+1)$. Thus, decay matrices for the measurement times (\ref{chipped_eq}) are submatrices of decay matrices for the measurement times (\ref{full_eq}).


Let then $t_k=k\Delta+t'_0$, for $k=1,...,N$. If $\gamma\in G(\vec{t})$, then there exists some unnormalized measure $\rho(E)dE$ such that 
\begin{equation}
\gamma_{jk}=\int_{-\infty}^{\infty}dE \rho(E)e^{-iE\Delta(k-j)},
\end{equation}
which implies that
\begin{equation}
\gamma_{jk}=g(k-j),
\end{equation}
for some function $g$.

As it turns out, that and positive semidefiniteness are the only features characterizing $G(\vec{t})$ in this scenario.
\begin{lemma}
For $\vec{t}=(\Delta,2\Delta,...,N\Delta)+t'_0$, define the SDP-representable set of matrices:
\begin{equation}
\tilde{G}(\vec{t})=\{\gamma:\gamma\geq 0, \exists y,\gamma_{jk}=y(k-j),\forall j,k\}.
\end{equation}  
Then, $G(\vec{t})=\tilde{G}(\vec{t})$.
\end{lemma}
\begin{proof}
Clearly, $\tilde{G}(\vec{t})\supset G(\vec{t})$; to prove the lemma, it suffices to show that $\tilde{G}(\vec{t})\subset G(\vec{t})$. 

We will proceed by contradiction: suppose that $\gamma\in \tilde{G}(\vec{t})$, $\gamma\not\in \tilde{G}(\vec{t})$. By the Hahn-Banach theorem and Remarks \ref{remark_func2pol}, \ref{remark_func2pol_m}, there exists a symmetric trigonometric polynomial $p(z,z^*)$ of degree smaller than or equal to $N-1$ such that
\begin{enumerate}
    \item $p(z,z^*)\geq0$, for all $z\in\mathbb{T}$, or, equivalently, $\check{\gamma}(p)\geq 0$, for all $\check{\gamma}\in G(\vec{t})$.
    \item $\gamma(p)<0$.    
\end{enumerate}



% By Lemma \ref{lemma_all_Gs}, we have that $\gamma\in G(\vec{t})$ iff there exists some function $y:\{-(N-1),...,N-1\}\to\C$ such that
% \begin{equation}
% y(k)=\int_{|z|=1} dz \sigma(z) z^k, k=-(N-1),...,N-1,
