% p(z,\bar{z}):=\sum_{k=-(N-1)}^{N-1}p_k z^k    
% \end{equation}
% must satisfy $p(z,\overline{z})\geq 0$, for all $|z|=1$. Conversely, any such non-negative polynomial defines an element of $D^*$. 

By \cite[Lemma 2.4]{helton2006positivepolynomialsscalarmatrix}, any such non-negative polynomial $p$ must satisfy
\begin{equation}
p(z,\bar{z})=q(z)^*q(z),
\end{equation}
where $q(z)=\sum_{k=0}^{N-1}q_kz^k$ for some complex numbers $(q_k)_k$. We thus have that
\begin{equation}
\gamma(p)=\sum_{jk}q_j^*q_k\gamma_{k-j}=\sum_{jk}q_j^*q_k\gamma_{jk}=\bra{q}\gamma\ket{q}\geq 0.
\end{equation}
We reach a contradiction, which means that $\gamma\in G(\vec{t})$.

\end{proof}


\subsubsection{Non-congruent time differences}
\label{app:non-congruent}
Suppose that the $N$ measurement times $t_1,..., t_N$ are such that $\{t_k-t_N\}_{k=1}^{N-1}$ are non-congruent numbers. Then we can express the $N$ times as
\begin{align}
t_k=&s_k+t_N, \mbox{ for } k=1,...,N-1,\nonumber\\
&t_N,\mbox{ otherwise}.
\end{align}
By Lemma \ref{lemma_all_Gs}, we thus have that the set of normalized decay matrices $\bar{G}(\vec{t}):=G(\vec{t})\cap\{\gamma:\gamma_{11}=1\}$ equals the set of convex combinations of matrices $\gamma_{jk}(z)$ of the form
\begin{equation}
\gamma_{jk}(z)=\prod_{j=l}^{N-1}z_l^{\delta_{k,l}-\delta_{j,l}},
\end{equation}
with $z\in\mathbb{T}^{N-1}$.

For arbitrary $z\in\mathbb{T}^{N-1}$, $\tilde{z}_N\in \mathbb{T}$, define $\tilde{z}:=\left(\frac{z_1}{\tilde{z}_N},\frac{z_2}{\tilde{z}_N},...,\tilde{z}_N\right)\in\mathbb{T}^N$. Then, $\gamma(z)=\tilde{\gamma}(\tilde{z})$, with
\begin{equation}
\tilde{\gamma}_{jk}(\tilde{z}):=\prod_{j=l}^{N}\tilde{z}_l^{\delta_{k,l}-\delta_{j,l}}.
\end{equation}

Recapping, we have that $\bar{G}(\vec{t})$ equals the following set:
\begin{defin}
$\mbox{CUT}^N_\infty$ is the convex hull of the set of matrices $\{\tilde{\gamma}(z):z\in\mathbb{T}^N\}$.
\end{defin}

This set has appeared earlier in the literature \cite{lifting,lifting2}. Call $\bar{C}_N$ the normalization of the set $C_N$ of correlation matrices, i.e., $\bar{C}_N=\{\gamma\geq 0:\gamma_{jj}=1,\forall j\}$. In \cite{lifting} it is shown that
\begin{equation}
\mbox{CUT}^3_\infty=\bar{C}_3.
\end{equation}
Therefore, for $t_1-t_3,t_2-t_3$ non-congruent, $G(\vec{t})=C_3$, and thus it is is SDP representable. In \cite{lifting} it is observed that $\bar{C}_4$ is strictly greater than $\mbox{CUT}^4_\infty$: in fact, the set  $\mbox{CUT}^4_\infty$ is shown in \cite{lifting,lifting2} to satisfy some extra inequalities. Nonetheless, $\mbox{CUT}^4_\infty$ is conjectured to be SDP representable \cite{lifting2}. More precisely, the conjecture in \cite{lifting2} implies that $\mbox{CUT}^4_\infty=G_2(\vec{t})$.

\subsection{$G(\vec{t})$ is discontinuous}
Consider an scenario with three equidistant times $\vec{t}=(0,\Delta,2\Delta)$. By Appendix \ref{app:equidistant}, we have that
\begin{equation}
\bar{G}(\vec{t})=\{\gamma\geq 0:\gamma_{jk}=g(j-k), g(0)=1\}.
\end{equation}


Now, for any $\delta>0$, there exists $\vec{t}'$, with $\|\vec{t}'-\vec{t}\|_{\infty}<\delta$ such that the real numbers $\vec{t}'_1-\vec{t}'_3$, $\vec{t}'_2-\vec{t}'_3$ are non-congruent. This implies, by section \ref{app:non-congruent}, that
\begin{equation}
\bar{G}(\vec{t}')=\{\gamma\geq 0:\gamma_{jj}=1,\forall j\}.
\end{equation}
Note that this set is independent of $\delta$. In particular, it includes the matrix
\begin{equation}
\gamma=\left(\begin{array}{ccc}1&1&0\\1&1&0\\0&0&1\end{array}\right).
\end{equation}
$\gamma_{12}\not=\gamma_{23}$, and so $\gamma\not\in \bar{G}(\vec{t})$. Thus, $\lim_{\vec{t}'\to\vec{t}}\not=\bar{G}(\vec{t})$.




\section{Proof of Lemma \ref{lemma_high_energy}}
\label{app:proof_high_energy}
Clearly, conditions (\ref{cond_soft1}-\ref{cond_soft4}) define a relaxation of $S(\vec{E};E^+,\epsilon)$. To prove the opposite implication, namely, that any $P$ satisfying the conditions must belong to $S(\vec{E};E^+,\epsilon)$, we assume that $p_1,...,p_{n}>0$ and $\gamma>0$; the case where some $p_k$'s are zero or $\gamma$ has zero eigenvalues can be dealt with by perturbing wither $\vec{p}$ or $\gamma$. In that last regard, we refer the reader to Remark \ref{remark_id_G}, which implies that, for any $\gamma\in G(\vec{t})$ and $\lambda\in [0,1]$, it holds that $\lambda\gamma+(1-\lambda)\gamma_{11}\id\in G(\vec{t})$.

Since $\gamma\in G(\vec{t})$, there exist \footnote{Technically speaking, $G(\vec{t})$ is the \emph{closure} of all matrices $\gamma$ admitting such a decomposition. Again for the sake of simplicity, we assume that such a decomposition exists for $\gamma$: otherwise, one could perturb $\gamma$ infinitesimally to be on the safe side.} a Hilbert space $\H^+$, $H^+\in B(\H^+)$, with $H^+\geq E^+$, and an unnormalized state $\ket{\psi^+}\in\H^+$ such that eq. (\ref{hamil2gamma}) holds, see Appendix \ref{app:overlaps}. 

Define $\Lambda:=\sum_{j=1}^Ne^{-iH^+t_j}\ket{\psi^+}\bra{j}$, and note that $\gamma=\Lambda^\dagger\Lambda$. Since $\gamma>0$, the rank of $\Lambda$ is $N$. Let thus $\Lambda^{-1}$ denote its left inverse, i.e., 
\begin{equation}
\Lambda^{-1}\Lambda\ket{j}=\ket{j}, \mbox{ for } j=1,...,N.
\end{equation}
The matrix $\Lambda\Lambda^{-1}:={\cal P}$ is a projector onto the space spanned by $\H^+_E:=\{e^{-iH^+t_j}\ket{\psi^+}\}_j$.

Then, the matrices
\begin{align}
&\hat{M}_{a|x}:=\nonumber\\
&\left(\begin{array}{cc}\mbox{diag}(\vec{p}^{-1/2})&0\\0&\Lambda^{-1}\end{array}\right)^\dagger \tilde{M}_{a|x}\left(\begin{array}{cc}\mbox{diag}(\vec{p}^{-1/2})&0\\0&\Lambda^{-1}\end{array}\right)
\end{align}
are positive semidefinite. Moreover, by eq. (\ref{cond_soft3}), they also satisfy 
\begin{equation}
\sum_a \hat{M}_{a|x}=\left(\begin{array}{cc}\id&0\\0&(\Lambda^{-1})^\dagger\gamma\Lambda^{-1}\end{array}\right)=\left(\begin{array}{cc}\id&0\\0&{\cal P}\end{array}\right).
\end{equation}
The matrices 
\begin{equation}
M_{a|x}:=\hat{M}_{a|x},a\not=0,M_{0|x}=\hat{M}_{0|x}+\left(\begin{array}{cc}0&0\\0&\id-{\cal P}\end{array}\right)
\end{equation}
are therefore positive semidefinite and satisfy $\sum_{a}M_{a|x}=\id$ -they are POVMs.

Next, define the Hamiltonian $H:=\sum_{k=0}^{m-1} E_k\proj{k}\oplus H^+$ and the vector
\begin{equation}
\ket{\psi}:=\sum_{k=0}^{m-1}\sqrt{p_k}\ket{k}+\sqrt{p_n}\ket{\psi^+}.
\end{equation}
Then it is immediate that
\begin{equation}
e^{-iHt_j}\ket{\psi}=\sum_{k=0}^{n-1}\sqrt{p_k}e^{-iE_kt_j}\ket{k}\oplus\sqrt{p_n}\Lambda\ket{j}.
\end{equation}
Thus,
\begin{align}
&\bra{\psi}e^{iHt_j}M_{a|x}e^{-iHt_j}\ket{\psi}=\bra{\psi}e^{iHt_j}\hat{M}_{a|x}e^{-iHt_j}\ket{\psi}=\nonumber\\
&=\bra{\tilde{\psi}_j}\tilde{M}_{a|x}\ket{\tilde{\psi}_j}\nonumber\\
&=p(a|x,j,\tilde{M})=P(a|x,t_j).
\end{align}


\section{Proof of Proposition \ref{prop_asymptotic}}
\label{app:proof_asymptotic}
The goal of this appendix is proving an exact version of Proposition \ref{prop_asymptotic} in the main text. The exact result reads:
\begin{prop}
\label{prop_not_asymptotic}
Let $P\in S^k_m(E^+;\epsilon,\vec{t})$, and let $n$ denote the smallest natural number such that
\begin{equation}
t_k=\sum_{j=1}^n a_{kj}s_j+t_0, \mbox{ for } k=1,...,N,
\label{rational_decomp}
\end{equation}
for some $\{s_j\}_j\subset \R$, $\{a_{kj}\}_{j,k}\subset \Z$. Define
\begin{equation}
d:=\left\lceil\frac{1}{2}\max_{j,k,l}|a_{jl}-a_{kl}|\right\rceil.
\label{def_d_K}
\end{equation}
and
\begin{equation}
\varepsilon_k:=N(N-1)\left[\left(1-\frac{6d^2}{k^2}\right)^{-n}-1\right].
\label{def_varepsilon_k}
\end{equation}
Let $n\geq 3d$ and $\varepsilon\leq 1$. Then, there exists $\hat{P}\in  S(E^+;\epsilon,\vec{t})$ such that
\begin{equation}
\|\check{P}(t_j)-P(t_j)\|\leq \frac{2\varepsilon_k}{1+\varepsilon_k}+2\sin\left(\frac{E^+\texttt{t}}{m}\right),\forall j.
\end{equation}
\end{prop}
Taking the limits $k\gg 1$, $m\gg 1$, we arrive at the statement of Proposition \ref{prop_asymptotic}.

To prove the proposition above, we will need the following lemma:
\begin{lemma}
\label{lemma_S_sup_m2S}
Let $P\in S^k(\vec{E};E^+,\epsilon,\vec{t})$. Then, there exists $\hat{P}\in S(\vec{E};E^+,\epsilon,\vec{t})$ such that
\begin{equation}
\|P-\hat{P}\|\leq \frac{2\varepsilon_k}{1+\varepsilon_k},
\end{equation}
with $\varepsilon_k$ as given in eq. (\ref{def_varepsilon_k}).
\end{lemma}
\begin{proof}
Let $\{\tilde{M}_{a|x}\}_{a,x}$ be positive semidefinite matrices such that $P(a|x,t_j)=p(a|x,j,\tilde{M})$ and
\begin{equation}
\sum_a \tilde{M}_{a|x}=\left(\begin{array}{cc}\mbox{diag}(p_0,...,p_{n-1})&0\\
0&\gamma\end{array}\right),
\end{equation}
with $\gamma\in G_k(\vec{t})$. By Proposition \ref{prop_G_lasserre}, we have that
\begin{equation}
\hat{\gamma}:=\frac{1}{1+\varepsilon_k}(\gamma +\varepsilon_k\gamma_{11}\id)\in G(\vec{t}).
\end{equation}
Now, define the matrices
\begin{align}
&\hat{M}_{a|x}:=\frac{1}{1+\varepsilon_k}\tilde{M}_{a|x}\nonumber\\
&+\frac{\varepsilon_k}{|A|(1+\varepsilon_k)}\left(\begin{array}{cc}\mbox{diag}(1-\gamma_{11},0,...0)&0\\0&\gamma_{11}\id\end{array}\right).
\end{align}
These matrices are positive semidefinite. In addition, they satisfy
\begin{equation}
\sum_{a}\hat{M}_{a|x}=\left(\begin{array}{cc}D&0\\0&\hat{\gamma}\end{array}\right),
\end{equation}
for some diagonal matrix $D$. Thus, $\hat{P}(a|x,t_j):=p(a|x,j,\hat{M})$ satisfies $\hat{P}\in S(\vec{E};E^+,\epsilon,\vec{t})$ by Lemma \ref{lemma_high_energy}.

Finally, note that
\begin{equation}
P(a|x,t_j)-\hat{P}(a|x,t_j)=\frac{\varepsilon_k}{1+\varepsilon_k}\left(P(a|x,t_j)-\frac{1}{|A|}\right).
\end{equation}
It follows that
\begin{equation}
\sum_a|P(a|x,t_j)-\hat{P}(a|x,t_j)|\leq \frac{2\varepsilon_k}{1+\varepsilon_k},
\end{equation}
which proves the statement of the lemma.

\end{proof}






\begin{proof}[Proof of Proposition \ref{prop_not_asymptotic}]
Let $P\in S^k_m(E^+;\epsilon,\vec{t})$. By definition, for $0\leq E_0\leq...\leq E_{n-1}$, there exists $\tilde{P}\in S^k(\vec{E};E^+\epsilon,\vec{t})$ such that
\begin{equation}
\|\tilde{P}(t_j)-P(t_j)\|\leq 2\sin\left(\frac{E^+\texttt{t}}{m}\right),\forall j.
\end{equation}
By Lemma \ref{lemma_S_sup_m2S}, we have that there exists $\hat{P}\in S(\vec{E};E^+\epsilon,\vec{t})\subset S(E^+;\epsilon,\vec{t})$ such that 
\begin{equation}
\|\check{P}(t_j)-\tilde{P}(t_j)\|\leq \frac{2\varepsilon_k}{1+\varepsilon_k},\forall j.
\end{equation}
By the triangular inequality, it hence follows that
\begin{equation}
\|\check{P}(t_j)-P(t_j)\|\leq \frac{2\varepsilon_k}{1+\varepsilon_k}+2\sin\left(\frac{E^+\texttt{t}}{m}\right).
\end{equation}


\end{proof}



\section{Proof of Lemma \ref{lemma:discontinuity_soft}}
\label{app:discontinuity_soft}
Let $(\H,\ket{\psi},H,M)$ be a pure-state realization of $P$. The initial state of the system at $t_0=0$ is of the form
\begin{equation}
\ket{\psi(0)}=\sqrt{p^-}\ket{\psi^-(0)}+\sqrt{p^+}\ket{\psi^+(0)}\label{eq:initial}
\end{equation}
The conditions $P(0|0)\approx 1$, $P(0|\Delta)\approx 0$ guarantee that the states $\ket{\psi(0)}, \ket{\psi(\Delta)}$ must be almost orthogonal. This can be quantified as follows:
\begin{align}
      1-2\delta&\leq |P(0|0)-P(0|\Delta)|
      \leq\sqrt{1-\abs{\braket{\psi(\Delta)}{\psi(0)}}^2},      
\end{align}
which implies
\begin{equation}
    \abs{\braket{\psi(\Delta)}{\psi(0)}}\leq O(\sqrt{\delta})\label{eq:overlapD0}.
\end{equation}

We next argue that $\ket{\psi^-(0)}, \ket{\psi^-(\Delta)}$ are very close to each other if $E^+ \Delta$ is small. Indeed:
\begin{align}
    &\mbox{Re}\left(\braket{\psi^-(0)}{\psi^-(\Delta)}\right)\nonumber\\
    &=\mbox{Re}\left(\bra{\psi^-(0)}e^{-iH\Delta}\ket{\psi^-(0)}\right)\nonumber\\
    &=\int_0^{E^+}dE\sigma^-(E)\cos{(E\Delta)}\nonumber\\
    &\geq\cos(E^+\Delta)
    = 1- O((E^+\Delta)^2)\label{eq:overlapminusD0}
\end{align}
where $dE\sigma^-(E)$ is the energy distribution of $\ket{\psi^-(0)}$ and we used $\Delta\leq\frac{\pi}{2E^+}$ to arrive at the third expression.

Using these two pieces of information, we can also estimate the value of $\braket{\psi^+(0)}{\psi^+(\Delta)}$. Starting from (\ref{eq:overlapD0}), we have that
\begin{align}
    &O(\sqrt{\delta})\geq\abs{\braket{\psi(\Delta)}{\psi(0)}}\geq \mbox{Re}\left(\braket{\psi(\Delta)}{\psi(0)}\right)\nonumber\\
    &= p^-\Re{\braket{\psi^-(\Delta)}{\psi^-(0)}}+p^+\Re{\bracket{\psi^+(\Delta)}{\psi^+(0)}}\nonumber\\
    &\geq \frac{1}{2}\Re{\braket{\psi^-(\Delta)}{\psi^-(0)}}+\frac{1}{2}\Re{\braket{\psi^+(\Delta)}{\psi^+(0)}}.
\end{align}
The last inequality stems from the fact that $p^-\geq \frac{1}{2}$ and that the first term on the second line is positive and close to $1$ by eq. (\ref{eq:overlapminusD0}). It follows that the second term must be negative so that the inequality holds for small $\delta$: giving less weight to the positive part can thus only decrease the mixture.

Combining the last expression with (\ref{eq:overlapminusD0}), we get
\begin{equation}
    1+\Re{\braket{\psi^+(\Delta)}{\psi^+(0)}}\leq O(\sqrt{\delta})+O(( E^+\Delta)^2)\label{eq:eq2}
\end{equation}
For low $\Delta E^+,\delta$, this equation implies that 
\begin{equation}
\ket{\psi^+(\Delta)}\approx -\ket{\psi^+(0)}.
\end{equation}
More precisely,
\begin{align}
    &\norm{\ket{\psi^+(\Delta)}+\ket{\psi^+(0)}}_2^2\nonumber\\
    &=2(1+\Re{\bracket{\psi^+(\Delta)}{\psi^+(0)}})\nonumber\\
    &\leq O(\sqrt{\delta})+O((E^+\Delta)^2).
\end{align}
Note that 
\begin{align}
&\norm{\ket{\psi^+(2\Delta)}+\ket{\psi^+(\Delta)}}^2_2\nonumber\\
&=\norm{e^{-iH\Delta}(\ket{\psi^+(\Delta)}+\ket{\psi^+(0)})}^2_2\nonumber\\
&=\norm{\ket{\psi^+(\Delta)}+\ket{\psi^+(0)}}^2_2\nonumber\\
&\leq O(\sqrt{\delta})+O((E^+\Delta)^2).
\end{align}
It follows that
\begin{align}
    &\norm{\ket{\psi^+(2\Delta)}-\ket{\psi^+(0)}}_2\nonumber\\
    &\leq \norm{\ket{\psi^+(2\Delta)}+\ket{\psi^+(\Delta)}}_2+\norm{\ket{\psi^+(\Delta)}+\ket{\psi^+(0)}}_2\nonumber\\
    %&\leq\big(\norm{\ket{\psi^+(2\Delta)}+\ket{\psi^+(\Delta)}}_2+\norm{\ket{\psi^+(\Delta)}+\ket{\psi^+(0)}}_2\big)^2\\
    &\leq \sqrt{O(\sqrt{\delta})+O((E^+\Delta)^2)}\label{eq:eq4}.
\end{align}
Similarly, invoking (\ref{eq:overlapminusD0}) we find that
\begin{align}
&\norm{\ket{\psi^-(2\Delta)}-\ket{\psi^-(0)}}_2\nonumber\\
&\leq \norm{\ket{\psi^-(2\Delta)}-\ket{\psi^-(\Delta)}}_2+\norm{\ket{\psi^-(\Delta)}-\ket{\psi^-(0)}}_2\nonumber\\
&\leq O(E^+\Delta).
\label{eq:eq5}
\end{align}



Combining (\ref{eq:eq4}) and (\ref{eq:eq5}) allows us to bound the state vectors. That is,
\begin{align}
&\norm{\ket{\psi(2\Delta)}-\ket{\psi(0)}}_2\nonumber\\
&=\left\|\sqrt{p^-}(\ket{\psi^-(2\Delta)}-\ket{\psi^-(0)})\right.\nonumber\\
&\left.+\sqrt{p^+}(\ket{\psi^+(2\Delta)}-\ket{\psi^+(0)})\right\|_2\nonumber\\
&\leq \sqrt{O(\sqrt{\delta})+O((E^+\Delta)^2)}.
\end{align}
Hence,
\begin{align}
&\abs{P(0|2\Delta)-P(0|0)}\nonumber\\
&=\abs{\bra{\psi(2\Delta)}M_a\ket{\psi(2\Delta)}-\bra{\psi(0)}M_a\ket{\psi(0)}}\nonumber\\
&=|\bra{\psi(2\Delta)}M_a(\ket{\psi(2\Delta)}-\ket{\psi(0)})\nonumber\\
&-(\bra{\psi(0)}-\bra{\psi(2\Delta)})M_a\ket{\psi(0)}|\nonumber\\
&\leq 2\norm{\ket{\psi(2\Delta)}-\ket{\psi(0)}}_2\nonumber\\
&\leq \sqrt{O(\sqrt{\delta})+O(( E^+\Delta)^2)}.
\end{align}
Taking into account that $1-P(0|0)\leq \delta$, we arrive at the statement of the Lemma.


