\title{The Bott-Duffin drazin inverse and its application}

\author{
\name{Lu Zheng\textsuperscript{a}\thanks{CONTACT Xiangyu Zhang. Email: xiangyuz021@163.com}, Xiangyu Zhang\textsuperscript{b,$\ast$}, Kezheng Zuo\textsuperscript{a} and Jing Zhou\textsuperscript{a}}
\affil{\textsuperscript{a} Teaching Section of Mathematics, Hubei Engineering Institute, Huangshi, China;}
 \affil{\textsuperscript{b} Jiaozhou Vocational Education Center School, Qingdao, China}}
\maketitle

\begin{abstract}
  The paper introduce a new type of generalized inverse, called Bott-Duffin drazin inverse  (or,
  in short, BDD-inverse) of a complex square matrix, and give some of its
  properties, characterizations and representations. Furthermore,
  We discuss the problem of the minimum P-norm solution of the constraint matrix equation by using the Bott-Duffin drazin inverse, and give Cramer's rule for this minimum P-norm solution.
\end{abstract}

\begin{keywords}
  Bott-Duffin inverse;  Bott-Duffin drazin inverse; constraint matrix equation; Cramer's rule 
\end{keywords}


\section{Introduction}
The notation $\mathbb{C}^{m\times{n}}$ represents the set of $m\times{n}$ complex matrices.
$L\leq\mathbb{C}^{n}$ means $L$ is a subspace of $\mathbb{C}^{n}$.
$\textup{rank}{(A)}$ is the rank of $A\in\mathbb{C}^{m\times{n}}$.
The smallest nonnegative integer $k$ for which $\textup{rank}{({A}^{k})}=\textup{rank}{({A}^{k+1})}$ is called the index of $A\in\mathbb{C}^{n\times{n}}$ and is denoted by $\textup{Ind}{(A)}$.
Bott and Duffin {\cite{bott1953algebra}} introduced the constrained inverse of the square matrix in electric network theory, namely the Bott-Duffin inverse.
When $A\in\mathbb{C}^{n\times{n}}$, $L\leq\mathbb{C}^{n}$ and $AP_{L}+P_{L^{\perp}}$ is invertible,
the Bott-Duffin inverse of $A$ with respect to $L$, denoted by $A_{(L)}^{(-1)}$, is defined by $A_{(L)}^{(-1)}=P_{L}{(AP_{L}+P_{L^{\perp}})}^{-1}$.
After this, many authors conducted further research on the Bott-Duffin inverse ({see}\cite{ben1963generalized,chen1990g,wei2003condition,pian2005algebraic,hughes2014minimality,tempo2018emerging,wu2023new}).
\par  It is interesting to mention that when $AP_{L}+ P_{L^{\perp}}$ is singular, Chen {\cite{yonglin1990generalized}} naturally defines the generalized Bott-Duffin inverse of $A\in\mathbb{C}^{n\times{n}}$ (denoted by $A_{(L)}^{(\dagger)}$) and extends the Bott-Duffin inverse to the general case.
Inspired by the paper of Chen {\cite{yonglin1990generalized}}, it is worth considering that if $AP_{L}+P_{L^{\perp}}$ is drazin invertible, can a new generalized inverse be obtained?
Therefore, our main aim is to introduce and investigate a new generalized
inverse, namely the Bott-Duffin drazin inverse.
\begin{definition}\label{D1}
  Let $A\in\mathbb{C}^{n\times{n}}$, $L\leq\mathbb{C}^{n}$. If $\textup{Ind}(AP_L + P_{L^\perp})=k$, then 
  \begin{equation}\label{E1}
    A_{(L)}^{(D)}=P_{L}{(AP_{L}+P_{L^{\perp}})}^{D},
  \end{equation}
  is called the Bott-Duffin drazin inverse of $A$ with respect to $L$.
\end{definition}
\par Let us now recall notions of several generalized inverses and notations.
\par As usual, $\mathbb{C}_{r}^{m\times{n}}$ stands for the set of all ${m\times{n}}$
complex matrices of rank $r$ while $I_{n}$ represents the identity matrix in $\mathbb{C}^{n\times{n}}$.
For $A\in\mathbb{C}^{m\times{n}}$,  the symbols $A^{\ast}$, $A^{-1}$, $\mathcal{R}{(A)}$ and $\mathcal{N}{(A)}$
stand for the conjugate transpose, the inverse ${(m=n)}$, the range space and the null space of $A$.
\par  The matrix formed by replacing column $i$ of $A$ with $b$ is denoted by $A{(i\rightarrow b)}$, where $A\in\mathbb{C}^{m\times{n}}$
and $b\in\mathbb{C}^{m}$.
Moreover, $O$ will refer to  the null matrix. $L^{\perp}$ is the orthogonal complement subspace of $L$. The dimension of $L$ is denoted by $\dim(L)$.
For two subspaces $S$ and $T$ such that $S\oplus T=\mathbb{C}^{n}$,
$P_{S,T}$ stands for the oblique projector onto $S$ along $T$.
The orthogonal projector onto a subspace $S$ will be indicated by $P_{S}$.
A matrix $X\in\mathbb{C}^{n\times{m}}$ that satisfies the equality $XAX=X$ is called the $\{2\}$-inverse of $A$.
\par  The Moore-Penrose inverse of $A\in\mathbb{C}^{m\times{n}}$ is the unique matrix ${A^{\dagger}}\in\mathbb{C}^{n\times{m}}$
satisfying the following four equations (see {\cite{penrose1955generalized,ben2003generalized,wang2018generalized}}):
\[AA^{\dagger}A=A,~A^{\dagger}AA^{\dagger}=A^{\dagger},~{(AA^{\dagger})}^{\ast}=AA^{\dagger}~\text{and}~{(A^{\dagger}A)}^{\ast}=A^{\dagger}A.\]
\par We recall that the Drazin inverse of $A\in\mathbb{C}^{n\times{n}}$
is the unique matrix $A^{D}\in\mathbb{C}^{n\times{n}}$ satisfying
the following three equations (see {\cite{ben2003generalized}}):
\begin{equation}\label{dra}
A^{D}AA^{D}=A^{D},~AA^{D}=A^{D}A~\text{and}~A^{D}A^{k+1}=A^{k},
\end{equation}
where $k=\textup{Ind}{(A)}$. We use the symbol $A^{\pi}$ represents $I_{n}-AA^{D}$, where $A\in\mathbb{C}^{n\times{n}}$.
\par If $X\in\mathbb{C}^{n\times{m}}$ satisfies the following three equations:
\[XAX=X,~\mathcal{R}{(X)}=S~\text{and}~\mathcal{N}{(X)}=T,\]
where $S,T\leq\mathbb{C}^{n}$, then $X$ is unique and is defined by $A_{S,T}^{(2)}$ (see {\cite{ben2003generalized,wang2018generalized}}).
\vspace{0.5em}
\par The main contributions of this paper are summarized as follows:
\begin{enumerate}
\item We give the equivalent conditions of $\textup{Ind}{(AP_{L}+P_{L^{\perp}})}=k$ and some properties of the BDD-inverse.
In particular, it shows that BDD-inverse is an outer inverse with prescribed range and null space.
\item Some characterizations of the BDD-inverse are obtained by using range space, null space, matrix equation, projectors.
\item The BDD-inverse is characterized by the rank equation, and some representations of the BDD-inverse are given.
In addition, the representation of the BDD-inverse is given by restricting $P_{L}AP_{L}$ in a specific subspace.
\item We use the BDD-inverse to study the problem of the minimum P-norm solution of the constrained matrix equations. Furthermore, we give Cramer's rule for the minimum P-norm solution.
\end{enumerate}

\par The rest of this paper is organized as follows: In Section 2, several  auxiliary lemmas are given.
In Section 3, we derive some equivalence conditions of $\textup{Ind}{(AP_{L}+P_{L^{\perp}})}$, and several properties of BDD-inverse of square matrix are given.
Section 4 provides some characteristics of BDD-inverse of square matrix.
Section 5 offers some representations of BDD-inverse of square matrix.
Finally, Section 6 is devoted to the study of the minimum P-norm solution of the constraint equation, and gives the Cramer's rule for its solution.
\section{Premliminaries}
\noindent First, we introduce some basic lemmas.
\begin{lemma}\label{tri}\emph{\cite{zhang2023exact}}
Let $M=\begin{bmatrix}A & B \\O & E\end{bmatrix}$
and $N=\begin{bmatrix}E & O \\ B & A\end{bmatrix}\in\mathbb{C}^{n\times{n}}$,
where $A$ and $E$ are square matrices such that $r=\operatorname{ind}(A)$
and $s=\operatorname{ind}(E)$. Then
\[M^{D}=\begin{bmatrix}
  A^{D} & X \\
  O & E^{D}
\end{bmatrix}~\text{and}~
  N^{D}=\begin{bmatrix}
  E^{D} & O \\
  X & A^{D}
  \end{bmatrix},\]  
where
  \[X=\sum_{i=0}^{s-1} A^{(i+2) D} B E^{i}E^{\pi}+A^{\pi}\sum_{i=0}^{r-1} A^{i} B E^{(i+2) D}-A^{D} B E^{D}.\]
\end{lemma}

\begin{lemma}\label{aco}\emph{\cite{bu2013some}}
  Let $M=\begin{bmatrix}
    A & O\\
    C & O
    \end{bmatrix}\in\mathbb{C}^{n \times n}, A~\text {is a square matrix, then}$
    \[M^{D}=\begin{bmatrix}
    A^{D} & O \\
    C{(A^{D})}^{2} & O
    \end{bmatrix}.\]
\end{lemma}

%\begin{lemma}\label{JKO}\emph{\cite{sun2016formulas}}
%Let $PQ=O$, where $P,~Q \in\mathbb{C}^{n\times{n}}$, $\textup{ind}{(P)}=r$ and $\textup{ind}{(Q)}=s$. Then
%\[{(P+Q)}^{D}=Q^{\pi}\sum_{i=0}^{s-1} Q^{i}{\left(P^{D}\right)}^{i+1}+\sum_{i=0}^{r-1}{\left(Q^{D}\right)}^{i+1} P^{i} P^{\pi} . \]
%\end{lemma}

\begin{lemma}\label{pq0}\emph{\cite{hartwig2001some}}
Let $M,~N\in\mathbb{C}^{n\times{n}}$ and $MN=NM=O$. Then
\[{(M+N)}^{D}=M^{D}+N^{D}.\]
\end{lemma}

\begin{lemma}\label{ccc}\emph{\cite[Theorem 7.8.4]{campbell2009generalized}}
Let $M,~N\in\mathbb{C}^{n\times{n}}$. Then
\[{(M N)}^{D}=M{({(N M)}^{2})}^{D} N .\]
\end{lemma}

Let $A\in\mathbb{C}^{n\times n}$ and $L\leq \mathbb{C}^{n}$.
To discuss some properties and characteristics of the BDD-inverse, we will consider a suitable matrix factorization of $A$ with respect to $L$.
Since there exists a unitary matrix $U \in \mathbb{C}^{n\times n}$ such that
  \begin{equation}\label{E2}
  P_L = U \begin{bmatrix}
    I_l & O \\
    O & O
    \end{bmatrix} U^*,
  \end{equation}
    where $ l = \dim(L)$. A matrix $A$ can be written as
    \begin{equation}\label{E3}
    A = U \begin{bmatrix} 
      A_L & B_L \\
      C_L& E_L
      \end{bmatrix} U^*,
    \end{equation}
    where $A_L \in \mathbb{C}^{l \times l}$, $B_L \in \mathbb{C}^{l \times (n-l)}$, $C_L \in \mathbb{C}^{(n-l) \times l}$and $E_L \in \mathbb{C}^{(n-l) \times (n-l)}$.

\noindent In the following, we provide the matrix block representation of $A_{(L)}^{(D)}$. 


\begin{lemma}\label{ler}
    Let $P_{L}$ and $A$ be given by $(\ref*{E2})$ and $(\ref*{E3})$, respectively.
    \begin{equation}\label{E4}
    A^{(D)}_{(L)}=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}U^*.
    \end{equation}
    \textbf{\textit{Proof.}}
    \textup{Using $(\ref*{E2})$ and $(\ref*{E3})$, we get
\begin{equation}\label{E5}
AP_{L}+P_{L^\perp} = U \begin{bmatrix} 
  A_L & O \\
  C_L& I_{n-l}
  \end{bmatrix} U^*.
\end{equation}
It follows from $(\ref*{E5})$ and Lemma $\ref*{tri}$ that
\[{(AP_{L}+P_{L^\perp})}^{D}=U\begin{bmatrix}{A_{L}}^{D}&O\\X_{1}&I_{n-l}\end{bmatrix}U^*,\]
where $X_{1}=C_{L}(\sum_{i= 0}^{k-1}{A_{L}}^{i}{A_{L}}^{\pi}-{A_{L}}^{D})\text{ and }k=\operatorname{ind}(A_{L})$.
By using (\ref*{E1}), we can get (\ref*{E4})}.
\end{lemma}  

\begin{lemma}\label{mab}\emph{\cite{ma2019characterizations}}
  For $A,B,D,E\in\mathbb{C}^{n\times{n}}$ and $M=\begin{bmatrix} A& AD \\EA& B\end{bmatrix}\in\mathbb{C}^{2n\times{2n}}$,
then
  \[\textup{rank}{(M)}=\textup{rank}{(A)}+\textup{rank}{(B-EAD)}.\]
\end{lemma}

\begin{comment}
\begin{lemma}\label{limt}\emph{\cite{meyer1974limits,ji1994alternative,yuan2016compute}}
  The Drazin inverse of matrix $A\in\mathbb{C}^{n\times{n}}$ with index k can be expressed as the limit
\begin{align*}
A^{D}&=\lim_{\lambda\to 0}{(\lambda{I_{n}}+A^{k+1})}^{-1}A^{k}
\\&=\lim_{\lambda\to 0}{(\lambda{I_{n}}+A)}^{-(k+1)}A^{k}
\\&=\lim_{\lambda\to 0}A^{k}{(\lambda{I_{n}}+A^{k+1})}^{-1}.
\end{align*}
\end{lemma}
