\begin{lemma} [Gramer's~rule]\label{Gramer}
  Let $A\in\mathbb{C}^{n \times n}$ be nonsingular and let $b\in\mathbb{C}^{n}$. Then the unique solution $x=\left[x_{1}, x_{2}, \ldots, x_{n}\right]^{T}$ of the system of linear equations $Ax=b$ is given by
  \[x_{i}=\frac{{\det} A(i \rightarrow b)}{{\det} A}, \quad i=1,2, \ldots, n \text {. }\]
\end{lemma}

\section{The properties of BDD-inverse}
In this section, we study the equivalence condition of $\textup{Ind}{(AP_{L}+P_{L^{\perp}})}=k$
and some basic properties of the BDD-inverse.
\begin{theorem}\label{T1}
Let $A\in\mathbb{C}^{n\times{n}}$, $L\leq\mathbb{C}^n$ and $k~(k\neq{1})$ is some positive integer. The following statements are equivalent:
\\$(a)$ $\textup{Ind}{(AP_{L}+P_{L^{\perp}})}=k$;
\\$(b)$ $\textup{Ind}{(P_{L}A+P_{L^{\perp}})}=k$;
\\$(c)$ $\textup{Ind}{(P_{L}AP_{L}+P_{L^{\perp}})}=k$;
\\$(d)$ $\textup{Ind}{(P_{L}AP_{L})}=k$;
\\$(e)$ $\textup{Ind}{(P_{L}A^{*}P_{L})}=k$.
\end{theorem} 

\begin{proof}
${(a)}\Leftrightarrow{(b)}$
It follows from (\ref{E5}) that
\[\textup{rank}{(AP_{L}+P_{L^\perp})} =\textup{rank}\begin{bmatrix} 
  {A_L} & O \\
  C_{L}& I_{n-l}
  \end{bmatrix}=\textup{rank}{(A_{L})}+\textup{rank}{(I_{n-l})},\]
  \[\textup{rank}{({(AP_{L}+P_{L^\perp})}^{2})} =\textup{rank}\begin{bmatrix} 
    {A_L}^{2} & O \\
    C_{L}A_{L}+C_{L}& I_{n-l}
    \end{bmatrix}=\textup{rank}{({A_{L}}^{2})}+\textup{rank}{(I_{n-l})}.\]
    Through mathematical induction, we get $\textup{rank}{({(AP_{L}+P_{L^\perp})}^{k})}=
    \textup{rank}{({A_{L}}^{k})}+\textup{rank}{(I_{n-l})}$ and $\textup{rank}{({(AP_{L}+P_{L^\perp})}^{k+1})}=
    \textup{rank}{({A_{L}}^{k+1})}+\textup{rank}{(I_{n-l})}$. Therefore, 
    $\textup{Ind}{(AP_{L}+P_{L^{\perp}})}=k\Leftrightarrow\textup{rank}{({A_{L}}^{k})}=\textup{rank}{({A_{L}}^{k+1})}$.
Similarly, we can conclude that $\textup{Ind}{(P_{L}A+P_{L^{\perp}})}=k\Leftrightarrow\textup{rank}{({A_{L}}^{k})}=\textup{rank}{({A_{L}}^{k+1})}\Leftrightarrow\textup{Ind}{(AP_{L}+P_{L^{\perp}})}=k$.\\
The rest of the proof follows similarly.
  \end{proof}

\noindent Now, we establish some interesting properties of BDD-inverse of $A\in\mathbb{C}^{n\times{n}}$.
\begin{theorem}\label{T2}
      Let $A\in\mathbb{C}^{n\times{n}}$, $L\leq\mathbb{C}^{n}$ and let $k=\textup{Ind}{(AP_{L}+P_{L^{\perp}})}$, $S=\mathcal{R}{({(P_{L}AP_{L})}^{k})}$ and $T=\mathcal{N}{({(P_{L}AP_{L})}^{k})}$, then the following statements hold:
    \vspace{0.2em}
    \\$(a)$ $A_{(L)}^{(D)}={P_L}A_{(L)}^{(D)}=A_{(L)}^{(D)}P_L={P_L}A_{(L)}^{(D)}P_{L}$;
    \\$(b)$ $\mathcal{R} {(A_{(L)}^{(D)})}=S$ and $\mathcal{N}{(A_{(L)}^{(D)})}=T$;
    \\$(c)$ $A_{(L)}^{(D)}=A_{(L)}^{(D)}AA_{(L)}^{(D)}=A_{(L)}^{(D)}A{P_L}A_{(L)}^{(D)}=A_{(L)}^{(D)}{P_L}AA_{(L)}^{(D)}=A_{(L)}^{(D)}{P_L}A{P_L}A_{(L)}^{(D)}$;
    \\$(d)$ $AA_{(L)}^{(D)}=P_{\mathcal{R}{({(AP_{L})}^{k+1})},T}~and~A_{(L)}^{(D)}A=P_{S,\mathcal{N}{({(P_{L}A)}^{k+1})}}$;
    \\$(e)$ $A_{(L)}^{(D)}AP_{L}=P_{L}AA_{(L)}^{(D)}=P_{S,T}$;
    %and $P_{T,S}AP_{L}=P_{L}AP_{T,S}=P_{L}AP_{L}$.
    \\$(f)$ $A_{(L)}^{(D)}=A_{S,T}^{(2)}={(AP_L)}_{S,T}^{(2)}={(P_{L}A)}_{S,T}^{(2)}={({P_L}A{P_L})}_{S,T}^{(2)}$;
    \\$(g)$ ${(A^{*})}_{(L)}^{(D)}={(A_{(L)}^{(D)})}^{*}$;
    \\$(h)$
    $A^{(D)}_{(L)}={({P_{L}AP_{L}})}^{D}=P_L{({P_L}A{P_L})}^{D}={({P_L}A{P_L})}^{D}P_L$\\
    $~~~~~~~~~~~~=P_L{({P_L}A{P_L} + P_{L^\perp})}^{D}={({P_L}A{P_L} + P_{L^\perp})}^{D}P_L$
    \\$~~~~~~~~~~~~={({P_L}A{P_L} + P_{L^\perp})}^{D}-P_{L^\perp}={(P_{L}A+P_{L^{\perp}})}^{D}P_{L}$
   \\$~~~~~~~~~~~~=P_{L}{(AP_{L})}^{D}={(P_{L}A)}^{D}P_{L}=P_{L}({(AP_{L})}^{2})^{D}AP_{L}$
    \\$~~~~~~~~~~~~=P_{L}A{({(P_{L}A)}^{2})}^{D}P_{L}$.
  \end{theorem}

 \begin{proof}
$(a)$.  Premultiplying ${(\ref{E1})}$ with $P_{L}$, we have $A_{(L)}^{(D)}={P_L}A_{(L)}^{(D)}$.
Using $(\ref{E2})$ and $(\ref{E4})$, we have
\begin{align*}
A^{(D)}_{(L)}P_{L}
&=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}
\begin{bmatrix}
  I_l & O \\
  O & O
\end{bmatrix}U^*\\
&=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}U^*=A^{(D)}_{(L)}.
\end{align*}
It follows from $A_{(L)}^{(D)}={P_L}A_{(L)}^{(D)}=A_{(L)}^{(D)}P_L$ that $A_{(L)}^{(D)}=P_{L}A_{(L)}^{(D)}P_L$.

\vspace*{0.5em}
\noindent $(b)$. By $(\ref{E1})$, we get
\begin{align*} 
  \mathcal{R}(A_{(L)}^{(D)})
  &=P_{L}\mathcal{R}{({(AP_L + P_{L^\perp})}^{D})}\\
  &=P_{L}\mathcal{R}{({(AP_L + P_{L^\perp})}^{k})}\\
  &=\mathcal{R}{({(P_{L}AP_{L})}^{k})}=S.
  \end{align*}
It follows that $\textup{rank}{(A_{(L)}^{(D)})}=\textup{rank}{({(P_{L}AP_{L})}^{k})}$.
From ${(\ref{E1})}$ and ${(\ref{dra})}$, we have 
\begin{align*}
\mathcal{N}{(A_{(L)}^{(D)})}&=\mathcal{N}{(P_{L}{(AP_L + P_{L^\perp})}^{D})}\\
&\subset\mathcal{N}{({(P_{L}AP_{L})}^{k+1}{(AP_L + P_{L^\perp})}^{D})}\\
&=\mathcal{N}{(P_{L}{{(AP_L + P_{L^\perp})}^{k+1}}{(AP_L + P_{L^\perp})}^{D})}\\
&=\mathcal{N}{(P_{L}{{(AP_L + P_{L^\perp})}^{k}})}\\
&=\mathcal{N}{({{(P_{L}AP_{L})}^{k}})}.
\end{align*}
Since $\mathcal{N}{(A_{(L)}^{(D)})}\subset\mathcal{N}{({{(P_{L}AP_{L})}^{k}})}=T$ and
$\textup{rank}{(A_{(L)}^{(D)})}=\textup{rank}{({(P_{L}AP_{L})}^{k})}$, it is easily obtained that $\mathcal{N}(A_{(L)}^{(D)})=T$.

\vspace*{0.5em}
\noindent $(c)$. From $(\ref{E3})$ and $(\ref*{E4})$, we infer that
\begin{align*}
A_{(L)}^{(D)}AA_{(L)}^{(D)}
&=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}\begin{bmatrix} 
    A_L & B_L \\
    C_L& E_L
    \end{bmatrix}\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}U^*\\
&=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}U^*=A_{(L)}^{(D)}.
\end{align*}
Using ${(a)}$ and $A_{(L)}^{(D)}=A_{(L)}^{(D)}AA_{(L)}^{(D)}$, we directly get
$A_{(L)}^{(D)}=A_{(L)}^{(D)}AA_{(L)}^{(D)}=A_{(L)}^{(D)}AP_{L}A_{(L)}^{(D)}
=A_{(L)}^{(D)}P_{L}AP_{L}A_{(L)}^{(D)}=A_{(L)}^{(D)}P_{L}AA_{(L)}^{(D)}$.

\vspace*{0.5em}
\noindent  ${(d)}$. From the first equation in ${(c)}$, we obtain $AA_{(L)}^{(D)}AA_{(L)}^{(D)}=AA_{(L)}^{(D)}$.
Also, ${(b)}$ implies that $\mathcal{R}{(AA_{(L)}^{(D)})}=A\mathcal{R}{(A_{(L)}^{(D)})}=AS=\mathcal{R}{({(AP_{L})}^{k+1})}$ and
$\mathcal{N}{(AA_{(L)}^{(D)})}=\mathcal{N}{(A_{(L)}^{(D)})}=T$.
Thus $AA_{(L)}^{(D)}=P_{\mathcal{R}{({{(AP_{L})}^{k+1}})},T}$.
Similarly, we have $A_{(L)}^{(D)}A=P_{S,{({A^*}T^\perp)}^\perp}$.
Now, from the equality ${{(A^{*}T^\perp)}^\perp}={{(A^{*}\mathcal{R}{({(P_{L}A^{*}P_{L})}^{k})})}^{\perp}}=
{\mathcal{R}{({(A^{*}P_{L})}^{k+1})}^{\perp}}=\mathcal{N}{({(P_{L}A)}^{k+1})}$,
it follows that $A_{(L)}^{(D)}A=P_{S,\mathcal{N}{({(P_{L}A)}^{k+1})}}$.

\vspace*{0.5em}
\noindent ${(e)}$. 
By ${(c)}$, we have
\[P_{L}AA_{(L)}^{(D)}P_{L}AA_{(L)}^{(D)}=P_{L}AA_{(L)}^{(D)}\]and
\[\mathcal{N}(A_{(L)}^{(D)})=\mathcal{N}(A_{(L)}^{(D)}P_{L}AA_{(L)}^{(D)})\geq\mathcal{N}(P_{L}AA_{(L)}^{(D)}).\]
Since $\mathcal{N}{(P_{L}AA_{(L)}^{(D)})}\geq\mathcal{N}{(A_{(L)}^{(D)})}$
and ${(b)}$, we get $\mathcal{N}{(P_{L}AA_{(L)}^{(D)})}=\mathcal{N}{(A_{(L)}^{(D)})}=T$
and $\textup{rank}{(P_{L}AA_{(L)}^{(D)})}=\textup{rank}{({(P_{L}AP_{L})}^{k})}$.
Using $(\ref{E1})$, we have
\begin{align*}
\mathcal{R}{(P_{L}AA_{(L)}^{(D)})}&=P_{L}AP_{L}\mathcal{R}{({(AP_L + P_{L^\perp})}^{D})}\\
&=P_{L}AP_{L}\mathcal{R}{({(AP_L + P_{L^\perp})}^{k})}\\
&=\mathcal{R}{({(P_{L}AP_{L})}^{k+1})}
\end{align*}
Considering $\mathcal{R}{(P_{L}AA_{(L)}^{(D)})}\leq\mathcal{R}{({(P_{L}AP_{L})}^{k})}$
and $\textup{rank}{(P_{L}AA_{(L)}^{(D)})}=\textup{rank}{({(P_{L}AP_{L})}^{k})}$,
it implies that $\mathcal{R}{(P_{L}AA_{(L)}^{(D)})}=S$.
Hence $P_{L}AA_{(L)}^{(D)}=P_{S,T}$. Analogously, we can prove $A_{(L)}^{(D)}AP_{L}=P_{S,T}$.

\vspace{0.5em}
\noindent ${(f)}$. It is apparent from ${(a)}$, ${(b)}$ and ${(c)}$.

\vspace{0.5em}
\noindent ${(g)}$. By ${(f)}$, we have $A_{(L)}^{(D)}=A_{S,T}^{(2)}$.
Thus, ${(A^{*})}_{(L)}^{(D)}={(A^{*})}_{\mathcal{R}{({(P_{L}{A^*}P_{L})}^{k})},\mathcal{N}{({(P_{L}{A}^{*}P_{L})}^{k})}}^{(2)}={(A^{*})}_{T^{\perp},S^{\perp}}^{(2)}={(A_{S,T}^{(2)})}^{*}={(A_{(L)}^{(D)})}^{*}$.

\vspace{0.5em}
\noindent ${(h)}$. Notice that for $\textup{Ind}{(B)}=k$, $B^{D}=B_{\mathcal{R}{(B^{k})},\mathcal{N}{(B^{k})}}^{(2)}$ (see {\cite{wang2018generalized}}).
Using the fourth equation in $(f)$, we have $A_{(L)}^{(D)}={(P_{L}AP_{L})}_{S,T}^{(2)}={(P_{L}AP_{L})}^{D}$.
From ${(a)}$, we know that $A_{(L)}^{(D)}={(P_{L}AP_{L})}^{D}=P_{L}{(P_{L}AP_{L})}^{D}={(P_{L}AP_{L})}^{D}P_{L}$.
Furthermore, using  ${(\ref{E1})}$ we have that 
\begin{align*}
A_{(L)}^{(D)}&={(P_{L}AP_{L})}^{D}={(P_{L}(P_{L}AP_{L})P_{L})}^{D}\\
&={({P_L}A{P_L})}^{(D)}_{(L)}=P_{L}{({P_L}A{P_L} + P_{L^\perp})}^{D}.
\end{align*}
By Lemma $\ref{pq0}$, we can verify that ${({P_L}A{P_L} + P_{L^\perp})}^{D}={({P_L}A{P_L})}^{D}+ P_{L^\perp}$.
Therefore, $A_{(L)}^{(D)}={({P_L}A{P_L})}^{D}={({P_L}A{P_L} + P_{L^\perp})}^{D}-P_{L^\perp}$.
By ${(a)}$, we can deduce that 
$A_{(L)}^{(D)}=A_{(L)}^{(D)}P_{L}={({({P_L}A{P_L} + P_{L^\perp})}^{D}-P_{L^\perp})}P_{L}={({P_L}A{P_L} + P_{L^\perp})}^{D}P_{L}$.
 Based on $(\ref{E2})$, $(\ref{E3})$ and Lemma $\ref{tri}$ we inferred that
\begin{align*}
  {(P_{L}A+P_{L^{\perp}})}^{D}P_{L}
&=U{\begin{bmatrix} 
  A_L & B_L \\
  O& I_{n-l}
  \end{bmatrix}}^{D}\begin{bmatrix}
    I_l & O \\
    O & O
    \end{bmatrix}U^*\\
&=U\begin{bmatrix} 
  {A_L}^{D} & X_2 \\
  O& I_{n-l}
  \end{bmatrix}\begin{bmatrix}
    I_l & O \\
    O & O
    \end{bmatrix}U^*\\
&= U\begin{bmatrix} 
  {A_L}^{D} & O \\
  O& O
  \end{bmatrix}U^*=A_{(L)}^{(D)},
\end{align*}
where $X_{2}={A_{L}}^{\pi}\sum_{i=0}^{k-1}{A_{L}}^{i}B_{L}-{A_{L}}^{D}B_{L}$.

\par Let $P_{L}$, $A$ and $A_{(L)}^{(D)}$ are expressed as in (\ref{E2}), (\ref{E3}) and (\ref{E4}), respectively.
From Lemma {\ref{aco}}, we derive
\begin{align*}
P_{L}{(AP_{L})}^{D}&=U \begin{bmatrix}
  I_l & O \\
  O & O\end{bmatrix}
  {\begin{bmatrix}
    A_{L} & O\\
    C_{L} & O
    \end{bmatrix}}^{D}U^*\\
&=U \begin{bmatrix}
  I_l & O \\
  O & O\end{bmatrix}
  \begin{bmatrix}
    {A_{L}}^{D} & O \\
    C_{L}{({A_{L}}^{D})}^{2} & O
    \end{bmatrix}U^*\\
&=U\begin{bmatrix}
  {A_{L}}^{D} & O \\
  O & O
  \end{bmatrix}U^*=A_{(L)}^{(D)}
  \end{align*}
and
\begin{align*}
  {(P_{L}A)}^{D}P_{L}&=U{\begin{bmatrix}
    A_{L} & B_{L}  \\
    O & O
    \end{bmatrix}}^{D}\begin{bmatrix}
      I_l & O \\
      O & O\end{bmatrix}U^*\\
  &=U\begin{bmatrix}
    {A_{L}}^{D} & {({A_{L}}^{D})}^{2}B_{L}  \\
    O & O
    \end{bmatrix}\begin{bmatrix}
      I_l & O \\
      O & O\end{bmatrix}U^*\\
  &=U\begin{bmatrix}
    {A_{L}}^{D} & O \\
    O & O
    \end{bmatrix}U^*=A_{(L)}^{(D)}.
\end{align*}    
We note that from Lemma {\ref{ccc}} it is easy to obtain
$A_{(L)}^{(D)}=P_{L}{({(AP_{L})}^{2})}^{D}AP_{L}=P_{L}A{({(P_{L}A)}^{2})}^{D}P_{L}$.
\end{proof}

