\end{example}


\noindent Below, we use matrix decomposition to give some other representations of $A_{(L)}^{(D)}$.

\begin{theorem}\label{ww}
Let $A\in\mathbb{C}^{n\times{n}}$, $L\leq \mathbb{C}^{n}$. Then
\begin{align*}
A_{(L)}^{(D)}&=P_{L}{(I_{n}-W_{2})}{(AP_{L})}^{D}\\
&={(P_{L}A)}^{D}{(I_{n}-W_{1})}P_{L}\\
&={(I_{n}-W_{1})}A^{\dagger}{(I_{n}-W_{2})},
\end{align*}
where $W_{1},~W_{2}$ are defined as in (\ref{WY3}).
\end{theorem}

\begin{proof}
From ${(d)}$ of Theorem $\ref{T2}$, $(\ref{E2})$, $(\ref{E3})$ and $(\ref{E4})$, we can deduce that
\[I_{n}-W_{1}=U\begin{bmatrix}{A_{L}}^{D}A_{L}&{A_{L}}^{D}B_{L}\\O&O \end{bmatrix}U^*~
\textup{and}~I_{n}-W_{2}=U\begin{bmatrix}A_{L}{A_{L}}^{D}&O\\C_{L}{A_{L}}^{D}&O \end{bmatrix}U^*.\]
By Lemma $\ref{aco}$, we directly get
\begin{align*}
  P_{L}{(I_{n}-W_{2})}{(AP_{L})}^{D}&=U \begin{bmatrix}
  I_l & O \\
  O & O\end{bmatrix}\begin{bmatrix}A_{L}{A_{L}}^{D}&O\\C_{L}{A_{L}}^{D}&O \end{bmatrix}{\begin{bmatrix}{A_{L}}&O\\C_{L}&O\end{bmatrix}}^{D}U^*\\
&=U\begin{bmatrix}{A_{L}A_{L}}^{D}&O\\O&O \end{bmatrix}\begin{bmatrix}
  {A_{L}}^{D} & O \\
  C_{L}({A_{L}}^{D})^{2} & O
  \end{bmatrix}U^*\\
&=U\begin{bmatrix}{A_{L}}^{D}&O\\O&O \end{bmatrix}U^*=A^{(D)}_{(L)}
\end{align*}
and
\begin{align*}
  {(P_{L}A)}^{D}{(I_{n}-W_{1})}P_{L}
  &=U{\begin{bmatrix}{A_{L}}&B_{L}\\O&O\end{bmatrix}}^{D}
  \begin{bmatrix}{A_{L}}^{D}A_{L}&{A_{L}}^{D}B_{L}\\O&O \end{bmatrix}\begin{bmatrix}
    I_l & O \\
