\noindent  Below, we give the limit representation of $A_{(L)}^{(D)}$.
\begin{theorem}
  Let $A\in\mathbb{C}^{n\times{n}}$, $L\leqslant\mathbb{C}^{n}$ and $k=\textup{Ind}{(P_{L}AP_{L})}\geq{2}$. Then
 \vspace{0.2em}
\\$(a)~A_{(L)}^{(D)}=\lim\limits_{\lambda\to{0}}P_{L}{(\lambda{I_n}+{(AP_{L})}^{k+1})}^{-1}{(AP_{L})}^{k}$;
\\$(b)~A_{(L)}^{(D)}=\lim\limits_{\lambda\to{0}}{(P_{L}A)}^{k}{(\lambda{I_n}+{(P_{L}A)}^{k+1})}^{-1}P_{L}$;
\\$(c)~A_{(L)}^{(D)}=\lim\limits_{\lambda\to{0}}{(\lambda{I_n}+P_{L}AP_{L})}^{-(k+1)}{(P_{L}A)}^{k}P_{L}$.
\end{theorem}

\begin{proof}
It follows from Lemma $\ref{limt}$ that
\begin{equation}\label{lambda}
{A_L}^{D}=\lim_{\lambda\to 0}{(\lambda{I_{l}}+{A_L}^{k+1})}^{-1}{A_L}^{k}.
\end{equation} 
Let $Q=P_{L}{(\lambda{I_n}+{(AP_{L})}^{k+1})}^{-1}{(AP_{L})}^{k}$.
By {(\ref{E2})} and {(\ref{E3})}, we obtain
\begin{align*}
Q&=U \begin{bmatrix}
  I_l & O \\
  O & O\end{bmatrix}{\begin{bmatrix}
    \lambda{I_l}+{A_L}^{k+1} & O \\
    C_{L}{A_{L}}^{k} & \lambda{I_{n-l}}\end{bmatrix}}^{-1}
    \begin{bmatrix}
      {A_L}^k & O \\
      C_{L}{A_{L}}^{k-1} & O\end{bmatrix}U^*\\
&=U \begin{bmatrix}
  I_l & O \\
  O & O\end{bmatrix}\begin{bmatrix}
  {(\lambda{I_l}+{A_L}^{k+1})}^{-1} & O \\
  -\frac{1}{\lambda} C_{L}{A_{L}}^{k}{(\lambda{I_l}+{A_L}^{k+1})}^{-1} & \frac{1}{\lambda}{I_{n-l}}
  \end{bmatrix}\begin{bmatrix}
    {A_L}^k & O \\
    C_{L}{A_{L}}^{k-1} & O\end{bmatrix}U^*\\
&=U \begin{bmatrix}
  {(\lambda{I_l}+{A_L}^{k+1})}^{-1}{A_{L}}^{k} & O \\
  O & O\end{bmatrix}U^*.
\end{align*}
According to (\ref{lambda}) and (\ref{E4}) we have
\begin{align*}
  \lim_{\lambda\to 0}Q&=\lim_{\lambda\to 0}U \begin{bmatrix}
    {(\lambda{I_l}+{A_L}^{k+1})}^{-1}{A_{L}}^{k} & O \\
    O & O\end{bmatrix}U^*\\
    &=U \begin{bmatrix}
      {A_L}^{D} & O \\
      O & O\end{bmatrix}U^*=A_{(L)}^{(D)}.
\end{align*}
\noindent The rest of the proof follows similarly.
\end{proof}

