& +\left.P^{-1} {(P_{L}AP_{L})}^{k-1}\left(I-A_{(L)}^{(D)} AP_{L}\right) P P^{-1} z\right]\\
= & \left(P^{-1} A_{(L)}^{(D)} P P^{-1} b\right)^{\mathrm{T}}\left(P^{-1}A_{(L)}^{(D)}  P P^{-1} b\right)+\left[P^{-1} {(P_{L}AP_{L})}^{k-1}\left(I-A_{(L)}^{(D)} AP_{L}\right) P P^{-1} z\right]^{\mathrm{T}}\\
&\times P^{-1} {(P_{L}AP_{L})}^{k-1}\left(I-A_{(L)}^{(D)} AP_{L}\right) P P^{-1} z+\left(P^{-1} b\right)^{\mathrm{T}}\\
&\times{\left\{\left(P^{-1} A_{(L)}^{(D)} P\right)^{\mathrm{T}}\left[P^{-1} {(P_{L}AP_{L})}^{k-1}\left(I- A_{(L)}^{(D)}AP_{L}\right) P\right]\right\}} 
P^{-1} z+\left(P^{-1} z\right)^{\mathrm{T}}\\
&\times\left\{\left[P^{-1} {(P_{L}AP_{L})}^{k-1}\left(I-A_{(L)}^{(D)}AP_{L}\right) P\right]^{\mathrm{T}}\left(P^{-1} A_{(L)}^{(D)} P\right)\right\} P^{-1} b\\
