    \end{array}\right]\left[\begin{array}{c}x\\y\end{array}\right]=\left[\begin{array}{c}b\\{O}\end{array}\right].\]
Using (\ref{fg1}), we have that
\[\left[\begin{array}{c}x\\y\end{array}\right]=\left[\begin{array}{cc}
  A_{(L)}^{(D)}& P_{T,S}G^{\dagger} \\
  F^{\dagger}P_{T,S}& -F^{\dagger}P_{T,S}P_{L}AP_{L}G^{\dagger}
  \end{array}\right]\left[\begin{array}{c}b\\{O}\end{array}\right]=\left[\begin{array}{c}A_{(L)}^{(D)}b\\{O}\end{array}\right].\] 
  Applying Lemma {\ref{Gramer}}, we can obtain (\ref{ng1}).
  \end{proof}

