\title{Polarization ratios of turbulent Langmuir/$\mathcal{Z}$-mode waves generated by electron beams \\ in magnetized solar wind plasmas}

\correspondingauthor{Catherine Krafft}
\email{catherine.krafft@universite-paris-saclay.fr}


\author{F.J. Polanco-Rodríguez\orcidlink{0009-0005-2951-697X}}
\affiliation{Laboratoire de Physique des Plasmas (LPP), CNRS, Sorbonne Université, \\ 
Observatoire de Paris, Université Paris-Saclay,\\ Ecole polytechnique, Institut Polytechnique de Paris, 91120 Palaiseau, France}

