            \end{cases}
            $};
            \node[elliptic state] (5) at (8,-2.4) {\tiny$
            \begin{cases}
                (X^2+2X+1)^n \cdot (3X + 1) = 1 \\
                (X^2+2X+1)^n \cdot (X + 3) + (X^2)^n \cdot X = 0
            \end{cases}
            $};
           \path[->] (1) edge [loop above, looseness=6] node [align=center]  {\footnotesize$0$} (1)
