\section{Hierarchical subtraction workflow \label{apdxa}}

The description of the hierarchical subtraction workflow is summarized as pseudocode in Algorithm \ref{alg} and (partly) visualized in Fig.~\ref{fig:algorithm}. 

\begin{algorithm}[H]
  \caption{Hierarchical subtraction for overlapping GW signals \label{alg}}
  \begin{algorithmic}

  \State \textbf{Input:} GW Data $d = h_A + h_B + n$, Neural Density Estimator $q$, Initial temperature $T = 10$, Max number of iterations $N_{\mathrm{it}} = 30$, Max number of retrial $N_\mathrm{trial}=100$, Convergence JSD threshold $\text{JSD}_\text{thre}=10^{-4}$ nat
  %Number of ensemble $N_{en} = 200$, Total samples $N = 16000$

  \State \textbf{Initialize:}
  \State Draw $\{ \theta_A^{(0)} \} \sim q(\theta \mid d)$ %\Comment{$\{ \theta_A^{(0)} \}$ contains $N_{en}$ sets of parameters}
  \State Compute $\{ \log L^{(0)} \} = \max_{\{\phi_{c, A}^{(0)}\}} ( - \frac{1}{2} \| d - h(\{\theta_{A}^{(0)}\}) \|^2$ )
  \State Add phase $\{ \theta_A^{(0)} \} = \{ \theta_A^{(0)} \} \cup \{\phi_{c, A}^{(0)}\}_\mathrm{maxL}$
  \State $\{ \theta_A^{'(0)} \} = \text{Resampling}(\{ \theta_A^{(0)} \}, \{ \log L^{(0)} \}, T)$
  \State Compute $\bar{L}^{(0)} = \textrm{mean} (\{ \log L^{(0)} \})$

  \State $\text{DoResampling} = 1$, $\text{DoMetropolis} = 0$, 
  \State $X = A$, $Y = B$, $\{ \theta_X^{'(0)} \} = \{ \theta_A^{'(0)} \}$
  \State $n_{\mathrm{it}} = 1$
  \State \textbf{Hierarchical subtraction and sampling:}
  \While{$n_{\mathrm{it}} < N_{\mathrm{it}}$}
      %, $\bar{L}^{(n_{\mathrm{it}})} = -\infty$
      \State Sample $\{ \theta_Y^{(n_{\mathrm{it}})} \} \sim q(\theta \mid d - h(\theta_X^{'(n_{\mathrm{it}}-1)}))$
          \State $\{ \log L^{(n_{\mathrm{it}})} \} =$
          \State $~~~~\max_{\{\phi_{c, Y}^{(n_{\mathrm{it}})}\}} \left( -\frac{1}{2} \| d - h(\{\theta_X^{(n_{\mathrm{it}}-1)}\}) - h(\{\theta_Y^{(n_{\mathrm{it}})}\}) \|^2 \right)$
          \State $\{ \theta_Y^{(n_{\mathrm{it}})} \} = \{ \theta_Y^{(n_{\mathrm{it}})} \} \cup \{\phi_{c, Y}^{(n_{\mathrm{it}})}\}_\mathrm{maxL}$
          \State $\bar{L}^{(n_{\mathrm{it}})} = \textrm{mean} (\{ \log L^{(n_{\mathrm{it}})} \})$
      \State $n_\mathrm{trial} = 0$
      \While{$\bar{L}^{(n_{\mathrm{it}})} < \bar{L}^{(n_{\mathrm{it}}-1)}$ and $\text{DoResampling}$}
          %\State Sample $\{ \theta_Y^{(n_{\mathrm{it}})} \} \sim q(\theta \mid d - h(\theta_X^{'(n_{\mathrm{it}}-1)}))$
          %\State $\{ \log L^{(n_{\mathrm{it}})} \} =$
          %\State $~~~~\max_{\{\phi_{c, Y}^{(n_{\mathrm{it}})}\}} \left( -\frac{1}{2} \| d - h(\{\theta_X^{(n_{\mathrm{it}}-1)}\}) - h(\{\theta_Y^{(n_{\mathrm{it}})}\}) \|^2 \right)$
          %\State $\{ \theta_Y^{(n_{\mathrm{it}})} \} = \{ \theta_Y^{(n_{\mathrm{it}})} \} \cup \{\phi_{c, Y}^{(n_{\mathrm{it}})}\}_\mathrm{maxL}$
          %\State $\bar{L}^{(n_{\mathrm{it}})} = \textrm{mean} (\{ \log L^{(n_{\mathrm{it}})} \})$
          \State Repeat line 13-17
          \State $n_\mathrm{trial} = n_\mathrm{trial} + 1$
          \If{$n_\mathrm{trial} == N_\mathrm{trial}$}
              \State $\text{DoResampling} = 0$, $\text{DoMetropolis} = 1$
          \EndIf
      \EndWhile

      \If{$\text{DoResampling}$}
          \State $\{ \theta_Y^{'(n_{\mathrm{it}})} \} = \text{Resampling}(\{ \theta_Y^{(n_{\mathrm{it}})} \}, \{ \log L^{(n_{\mathrm{it}})} \}, T)$
          \State $T = \text{ExponentialAnnealing}(T)$ 
      \ElsIf{$\text{DoMetropolis}$}
          \State $(\{ \theta_Y^{'(n_{\mathrm{it}})}\}, \{\theta_X^{'(n_{\mathrm{it}}-1)} \}) = $
          \State \( \begin{aligned}
            \text{MetropolisSampling}(&\\
            &(\{ \theta_Y^{'(n_{\mathrm{it}})}\}, \{\theta_X^{'(n_{\mathrm{it}}-1)} \}), \\
            & (\{ \theta_Y^{'(n_{\mathrm{it}}-2)}\}, \{\theta_X^{'(n_{\mathrm{it}}-1)} \}),  \\
            &\{\log L^{(n_{\mathrm{it}})}\}, \\
            &\{\log L^{(n_{\mathrm{it}}-1)}\} \\
            &)
        \end{aligned} \)
      \EndIf

      \If{$\text{JSD}(\{ \theta_Y^{'(n_{\mathrm{it}})} \}, \{ \theta_Y^{'(n_{\mathrm{it}}-2)} \}) < \text{JSD}_\text{thre}$ \\ \hspace{1cm}and $\text{JSD}(\{ \theta_X^{'(n_{\mathrm{it}}-1)} \}, \{ \theta_X^{'(n_{\mathrm{it}}-3)} \}) < \text{JSD}_\text{thre}$ \\ \hspace{1cm}and $\text{DoMetropolis}$}
          \State $\theta_Y = \{ \theta_Y^{'(n_{\mathrm{it}})} \}$, $\theta_X = \{ \theta_X^{'(n_{\mathrm{it}}-1)} \}$
          \State \textbf{Output:} Hierarchical subtraction converges at iteration $n_{\mathrm{it}}$.
          \State \textbf{Exit}
      \Else
          \State Swap: $(X, Y) = (Y, X)$
          \State $n_{\mathrm{it}} = n_{\mathrm{it}} + 1$
      \EndIf      
  \EndWhile
  \State \textbf{Output:} Hierarchical subtraction does not converge within $N_{\mathrm{it}}$ iterations.
  \end{algorithmic}
\end{algorithm}



