  \includegraphics[width=0.95\textwidth]{gibbs_illustration.pdf}
  \caption{\label{fig:algorithm} Hierarchical subtraction workflow excluding the convergence part, more details are given in the main text and Algorithm \ref{alg}. The original data $d$ contains two signals $A$ and $B$, and we assume $A$ is first found by the NDE. Each initial sample is used to generate a signal for subtraction, and they evolve together as an ensemble in the hierarchical subtraction iteration. At first several iterations, resampling is used to remove low-likelihood elements in the ensemble. Then the resampling will be replaced by Metropolis sampling that leads the sampler to convergence. Concatenations of $\theta_{A, i}^{'}$ and $\theta_{B, i}^{'}$ for $i$ ranging from 1 to $N_\mathrm{en}$ are the final posterior samples for signal $A$ and $B$, respectively. }
\end{figure*}

