    \section{Hyperbolicity}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    This section recalls three notions of hyperbolicity: $\delta$-hyperbolicity, $(\delta)$-hyperbolicity, and the $\CAT(-1)$ condition. The relationship between these notions is relevant to the construction of visual metrics and is discussed as well. Additional background can be found in the texts of Bridson--Haefliger~\cite{bridsonhaefliger}, Buyalo--Schroeder~\cite{buyaloschroeder}, and Ghys--de la Harpe~\cite{ghysdelaharpe}.

\subsection{$\delta$-hyperbolicity}

        \begin{defn}[Geodesics]
            Let $X$ be a metric space. A {\it geodesic} from $x \in X$ to $y \in X$ is a map $c:[0,\ell] \rightarrow X$ so that $c(0) = x$, $c(\ell) = y$ and $d\bigl(c(t), c(t')\bigr) = |t - t'|$ for all $t, t' \in [0,\ell]$. The image of $c$ in $X$ is called a {\it geodesic segment} from $x$ to $y$. A metric space $X$ is a {\it geodesic metric space} if there is a geodesic segment from $x$ to $y$ for all $x,y \in X$. A {\it geodesic triangle} in a metric space $X$ consists of three points in $X$ together with a choice of a geodesic segment (a {\it side}) between each pair of distinct points.
        \end{defn}

            The first notion of hyperbolicity applies to geodesic metric spaces and is given as follows.
            \begin{wrapfigure}{r}{0.25\textwidth}
                 \begin{center}
                    \begin{overpic}[width=.25\textwidth,tics=5]{figure-deltathin.pdf} %Add `grid' to see the grid.
                        \put(64,42){\small{$\delta$}}
                    \end{overpic}
                 % \includegraphics[width=0.23\textwidth]{figure-deltathin.pdf}
                 \end{center}
            \end{wrapfigure}

        \begin{defn}[$\delta$-slim triangles and $\delta$-hyperbolicity]
            Let $\delta>0$. A geodesic triangle in a metric space is {\it $\delta$-slim} if each of its three sides is contained in the $\delta$-neighborhood of the union of the other two sides. A geodesic metric space $X$ is {\it $\delta$-hyperbolic} if every triangle in $X$ is $\delta$-slim. A finitely generated group is {\it $\delta$-hyperbolic} (or {\it hyperbolic}) if it acts geometrically, ie properly discontinuously and cocompactly by isometries, on a $\delta$-hyperbolic metric space.
        \end{defn}

        \begin{example}
            A geodesic metric space is $0$-hyperbolic if and only if it is a metric tree.
        \end{example}

        \begin{example}
            The Cayley graph of the free product $\Z/n\Z \, * \, \Z/n\Z = \la \, a,b \,|\, a^n,\,  b^n \, \ra$ with respect to the generating set $\{a,b\}$ is $n$-hyperbolic, and $n$ is not the optimal $\delta$.
        \end{example}

            Foundational to geometric group theory is that hyperbolicity is preserved by quasi-isometries.

    \begin{defn}
        Let $K \geq 1$ and $C \geq 0$. A map $f:X \rightarrow X'$ is a {\it $(K,C)$-quasi-isometry} if the following two conditions hold.
        \begin{enumerate}
            \item For all $x,y \in X$,
            \[\frac{1}{K}d(x,y) - C \leq d\bigl(f(x),f(y)\bigr) \leq Kd(x,y) +C.\]
            \item For all $x' \in X'$ there exists $x \in X$ so that $d\bigl(f(x),x'\bigr) \leq C$.
        \end{enumerate}
    \end{defn}



        \begin{thm}[Quasi-isometry invariance] \cite[Theorem III.H.1.9]{bridsonhaefliger}
            Let $X$ and $X'$ be quasi-isometric geodesic metric spaces. If $X$ is $\delta$-hyperbolic, then $X'$ is $\delta'$-hyperbolic. \qed
        \end{thm}






    \subsection{Gromov product}

            The Gromov product is sometimes referred to as the {\it Gromov overlap function} and has natural geometric interpretations in a hyperbolic metric space. The Gromov product is central to defining metrics on the boundary of such a space.

        \begin{defn}[Gromov product]
            Let $X$ be a metric space, and let $p \in X$. The {\it Gromov product} of $x,y \in X$ based at $p$ is denoted $(x,y)_p$ and is given by the formula
                \[(x,y)_p := \frac{1}{2}\Bigl( d(p,x) + d(p,y) - d(x,y) \Bigr). \]
        \end{defn}

        \begin{example}
            The Gromov product has a simple meaning in a tree: the quantity $(x,y)_p$ equals the distance from $p$ to the geodesic $[x,y]$. Further, the Gromov product $(x,y)_p$ measures the distance the geodesics $[p,x]$ and $[p,y]$ fellow-travel before diverging.
        \end{example}

