    \section{The boundary of a hyperbolic space}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 The boundary of a hyperbolic metric space is a topological space that captures the set of directions to infinity in the space. This section recalls two definitions of the boundary and its topology. The first definition applies to geodesic metric spaces and is given in terms of geodesic rays. The second definition applies to arbitrary $(\delta)$-hyperbolic metric spaces and is given in terms of sequences of points. Visual metrics on the boundary will be defined with respect to the second definition. Throughout this section, let $X$ be a $(\delta)$-hyperbolic metric space.


    \subsection{Definition via rays}

        \begin{defn}
            Let $X$ be a metric space. Let $c,c':[0,\infty) \rightarrow X$ be geodesic rays in $X$. The rays $c$ and $c'$ are {\it asymptotic} if there exists a constant $D\geq 0$ so that $d\bigl(c(t),c'(t)\bigr) \leq D$ for all $t \in [0,\infty)$.
        \end{defn}

        Being asymptotic is an equivalence relation on geodesic rays, leading to the following definition.

        \begin{defn}
            Let $X$ be a geodesic metric space. The {\it boundary} of $X$, denoted $\partial X$, is the set of equivalence classes of geodesic rays in $X$, where two rays are equivalent if they are asymptotic. If $c:[0,\infty)\rightarrow X$ is a geodesic ray, let $c(\infty)$ denote the equivalence class of $c$.
        \end{defn}

        \begin{remark}[Quasi-geodesic rays]
            In a hyperbolic metric space, the boundary can equivalently be defined in terms of quasi-geodesic rays. Recall, a map $c:[0,\infty) \rightarrow X$ is a {\it quasi-geodesic ray} if $c$ is a quasi-isometric embedding. Quasi-geodesic rays are defined to be {\it asymptotic} if the Hausdorff distance between their images is finite. Let $\partial_q X$ denote the set of equivalence classes of quasi-geodesic rays. Then, the map $\partial X \rightarrow \partial_q X$ is a bijection; see \cite[Lemma III.H.3.1]{bridsonhaefliger}.
        \end{remark}

        \begin{example}
            The boundary of the line $\R$ with the standard metric consists of two points. The boundary of the infinite ladder graph below, where edges have length one, also consists of two points. Additional examples are given at the end of this section.

            \begin{figure}[h]
                \begin{centering}
	            \begin{overpic}[width=.6\textwidth,tics=5]{figure-ladder.pdf} %Add `grid' to see the grid.

                \end{overpic}
	           \caption{\small{A metric space with visual boundary consisting of two points. }}
	           %\label{figure-sequence_ex}
                \end{centering}
            \end{figure}
        \end{example}


    \subsection{Topology on the boundary}

        The boundary of $X$ admits a topology that compactifies the metric space $X$. We first specify notation for the union of $X$ and its boundary.

        \begin{defn}
            Let $X$ be a metric space. A {\it generalized geodesic ray} in $X$ is a geodesic $c:I \rightarrow X$, where either $I = [0,R]$ for some $R\geq 0$ or $I = [0,\infty)$. If $I = [0,R]$, define $c(t) := c(R)$ for all $t \in [R,\infty]$. Let
            \[\overline{X} = X \cup \p X = \{\, c(\infty) \,|\, c \textrm{ is a generalized geodesic ray} \,\}.\]
        \end{defn}

    The topology on $\overline{X}$ can be defined via convergence. Take the topology on the set of generalized geodesic rays to be the topology of uniform convergence on compact sets. Then take the quotient topology on $\overline{X}$.

    The topology on $\overline{X}$ can alternatively be specified via the {\it neighborhood topology}, by specifying a collection of neighborhoods of each point in $\overline{X}$. These neighborhoods need not be open in the boundary; see~\Cref{ex:NotOpen}. Nonetheless, they satisfy four natural axioms, recalled here for completeness, from which a topology can be defined; see \cite[Chapter 1.2]{bourbaki}. That these topologies are the same follows from ~\cite[Lemma III.H.3.6]{bridsonhaefliger}.

    \begin{defn}[Neighborhood topology]
        Let $X$ be a set, and let $\cN$ be a function from $X$ to $\cP\bigl(\cP(X)\bigr)$, where $\cP(X)$ denotes the powerset of $X$. Elements of $\cN(x)$ are called {\it neighborhoods} of $x$. Then $\cN$ is called a {\it neighborhood topology} if it satisfies the following four axioms:
            \begin{enumerate}
                \item If $N \in \cN(x)$, then $x \in N$.
                \item If $N \subset N'$ and $N \in \cN(x)$, then $N' \in \cN(x)$.
                \item If $N, N' \in \cN(x)$, then $N \cap N' \in \cN(x)$.
                \item If $N \in \cN(x)$, then there exists $M \in \cN(x)$ so that if $y \in M$, then $N \in \cN(y)$.

                This axiom captures the notion that a neighborhood of a point $x$ is also a neighborhood of every point sufficiently close to $x$.
            \end{enumerate}
        If $\cN$ is a neighborhood topology, then a topology on $X$ can be specified by $U \subset X$ is {\it open} if $U$ is a neighborhood of every point in $U$. In this topology, every element of $\cN(x)$ is a {\it neighborhood} of $x$ in the sense that if $V \in \cN(x)$, then there exists an open set $U$ so that $x \in U \subset V$.
    \end{defn}

    \begin{defn}[Neighborhoods of a point] \label{defn:neighborhoods}
        Let $X$ be a hyperbolic proper geodesic metric space, and let $p \in X$. Let $\cN$ be the function from $X$ to $\cP\bigl(\cP(X)\bigr)$ defined as follows. For each $x \in \overline{X}$, let $\cN(x)$ the the collection of subsets of $\overline{X}$ that contain a set in $\cN'(x)$ given as follows.

        \begin{enumerate}
            \item (Points in $X$.) If $x \in X$, let $\cN'(x)$ be the family of metric balls centered $x$.

\vskip.07in

            \item (Points in $\p X$.) Fix $k>2\delta$.

            Let $c(\infty) \in \p X$. Fix $c_0:[0,\infty) \rightarrow X$ a geodesic ray with $c_0(0) =p$ and $c_0(\infty) = c(\infty)$. For each $n \in \Z_+$, let
            \[ V_n(c_0):= \left\{
                            \begin{array}{c}
                                \\
                                \,\, c'(\infty) \,\, \\
                                \\
                            \end{array}
                            :
                             \begin{array}{c}
                                c' \textrm{ is a generalized geodesic ray }\\
                                c'(0) =p \\
                                d\bigl(c'(n), c_0(n) \bigr) < k\\
                            \end{array}
                            \right\}\]
            Let $\cN'\bigl(c(\infty)\bigr) = \bigl\{V_n(c_0) \,|\, n \in \Z_+\bigr\}$.
        \end{enumerate}
    \end{defn}

