    \begin{example}[\cite{bridsonhaefliger}, Example III.H.3.16]
        The following example of Bridson--Haefliger illustrates why both an infimum and a $\liminf$ are needed to make the above definition well-defined. Consider the metric graph $X$ above, which can be viewed as the Cayley graph for the direct product $\Z \times \Z/2\Z$ (with the bigons collapsed to an edge). The boundary $\p X$ consists of two points, denoted $a^{+\infty}$ and $a^{-\infty}$. Then, $x_n \rightarrow a^{-\infty}$ while $y_n,z_n,w_n \rightarrow a^{+\infty}$. However, $\lim_{i,j \rightarrow \infty} (x_i,w_j)_p$ does not exist. Moreover, $\liminf_{i,j \rightarrow \infty}(x_i,y_j)_p \neq \liminf_{i,j \rightarrow \infty}(x_i,z_j)_p$.
    \end{example}



    \begin{remark}
        The Gromov product takes values in $[0,\infty]$, and $(\eta,\eta')_p = \infty$ if and only if $\eta,\eta' \in \p X$ and $\eta = \eta'$.
    \end{remark}

    The $\delta$-inequality extends to the boundary of $X$, as shown below in Lemma~\ref{lemma:delta_ineq_boundary}. This key property is needed to prove the existence of visual metrics on $\p X$. The proof uses the next helpful lemma, proven using a diagonal sequence argument, which says that, while the extension of the Gromov product to the boundary involves taking an infimum and a $\liminf$, there exist sequences that realize this infimum and via a limit rather than a $\liminf$.

    \begin{lem} \label{lemma:exist_seq}
        Let $X$ be a $(\delta)$-hyperbolic metric space. For all $\eta, \eta' \in \p X$, there exist sequences $\{x_n\}, \{x_n'\}$ of points in $X$ so that $\{x_n\} \in \eta$, $\{x_n'\} \in \eta'$, and
                \[(\eta,\eta')_p = \lim_{n \rightarrow \infty} (x_n,x_n')_p.\]
    \end{lem}

    We note that the above argument can be extended to any finite set of points in the boundary. The previous lemma is used to prove the next, which extends the $\delta$-inequality to the boundary.

    \begin{lem} \label{lemma:delta_ineq_boundary}
         Let $X$ be a $(\delta)$-hyperbolic metric space. For all $p \in X$ and $\eta, \eta', \eta'' \in \p X$
            \[ (\eta,\eta')_p \geq \min \bigl\{(\eta, \eta'')_p, (\eta'', \eta')_p\bigr\} - \delta. \]
    \end{lem}
    \begin{proof}
        Let $p \in X$ and $\eta, \eta', \eta'' \in \p X$.
        It follows from Lemma~\ref{lemma:exist_seq} and its proof that there exist sequences $\{x_i\} \in \eta$, $\{x_i'\} \in \eta'$, and $\{x_i''\} \in \eta''$ so that
             \[  (\eta,\eta')_p = \lim_{i \rightarrow \infty} (x_i,x_i')_p, \quad \quad
                    (\eta,\eta'')_p = \lim_{i \rightarrow \infty} (x_i,x_i'')_p, \quad \quad
                    (\eta',\eta'')_p = \lim_{i \rightarrow \infty} (x_i',x_i'')_p.\]
        Then, by the $\delta$-inequality,
            \begin{eqnarray*}
                (\eta, \eta')_p &=& \lim_{i \rightarrow \infty} (x_i,x_i')_p\\
                 &\geq &  \lim_{i \rightarrow \infty} \min \bigl\{ (x_i,x_i'')_p, (x_i'', x_i')_p \bigr\} - \delta \\
                 & \geq & \min \bigl\{ \lim_{i \rightarrow \infty} (x_i,x_i'')_p, \lim_{i \rightarrow \infty} (x_i'',x_i')_p\bigr\} - \delta \\
                 &= & \min \bigl\{ (\eta, \eta'')_p, (\eta'', \eta')_p  \bigr\} - \delta,
            \end{eqnarray*}
            as desired.
    \end{proof}




























