    \begin{lem} \cite[Lemma 1.2.18]{mackaytyson} \label{lemma:annuli}
        Let $Z$ and $Z'$ be metric spaces. A homeomorphism $f:Z \rightarrow Z'$ is $\phi$-quasisymmetric if and only if whenever
            \[ B_1:= B_{r_1}(z) \subset B_{r_2}(z) =: B_2\]
        are concentric balls in $Z$, there exist concentric balls
            \[ B_1':= B_{r_1'}(f(z)) \subset B_{r_2'}(f(z)) =: B_2' \]
        so that
            \[B_1' \subset f(B_1) \subset f(B_2) \subset B_2' \quad \quad \textrm{ and } \quad \quad \frac{r_2'}{r_1'} \leq \phi \left( \frac{r_2}{r_1} \right).  \]
    \end{lem}



    Simple computations show that many familiar, well-behaved maps are quasisymmetries.

    \begin{example}[Bilipschitz maps are quasisymmetries]
        A map $f:(Z,d) \rightarrow (Z', d')$ between metric spaces is {\it $K$-bilipschitz} if for all $x,y \in Z$,
            \[ \frac{1}{K}d(x,y) \leq d\bigl( f(x), f(y)\bigr) \leq Kd(x,y). \]
        A bilipschitz map distorts distances by at most a uniform multiplicative factor. If $f$ is $K$-bilipschitz, then $f$ is a quasisymmetry with control function $\phi(t) = K^2t$. Indeed,
        \[ \frac{d\bigl( f(x),f(y) \bigr)}{d\bigl( f(x),f(z) \bigr)}  \leq \frac{Kd(x,y)}{\frac{1}{K}d(x,z)} \leq K^2\cdot\frac{d(x,y)}{d(x,z)}.\]
    \end{example}

    \vskip.1in

        \begin{center}
            {\it ``Informally, one can define an embedding to be bilipschitz if it distorts both the shape and size of an object by a bounded amount, while quasisymmetry only preserves the approximate shape."

            - Heinonen~\cite[Page 79]{heinonen-Lectures}}
        \end{center}




    \begin{example}[Snowflake maps are quasisymmetries]
        Recall the definition of snowflaking, also used in the construction of visual metrics. Let $(Z,d)$ be a metric space. Let $\epsilon \in (0,1)$. The {\it snowflake of $(Z,d)$ with parameter~$\epsilon$} is the metric space $(Z,d^{\epsilon})$ where $d^{\epsilon}:Z\times Z \rightarrow [0,\infty)$ is given by
        \[d^{\epsilon}(z_1,z_2) = d(z_1,z_2)^{\epsilon}.\]

        If $(Z,d)$ is a metric space and $(Z,d^\epsilon)$ is its $\epsilon$-snowflake for some $\epsilon \in (0,1)$, then the identity map is a quasisymmetry with control function $\phi(t) = t^\epsilon$. Indeed, suppose $x,y,z \in Z$ with $x \neq z$.
            \[\textrm{If } \quad \frac{d(x,y)}{d(x,z)} \leq t \quad \textrm{then, } \quad \frac{d^{\epsilon}(x,y)}{d^{\epsilon}(x,z)}= \frac{d(x,y)^\epsilon}{d(x,z)^\epsilon} = \left(\frac{d(x,y)}{d(x,z)} \right)^{\epsilon} \leq t^{\epsilon}.\]
        \end{example}





    The above examples imply the following lemma. The isometry type of the visual metric on the boundary of a hyperbolic metric space depends on the choices in its construction: the basepoint $p$ in the Gromov product and on the choice of visual metric parameter. The quasisymmetry type is nonetheless well-defined.

    \begin{lem} \cite[Chapter 2.2]{buyaloschroeder}
       Let $X$ be a $\delta$-hyperbolic geodesic metric space.
       \begin{enumerate}
           \item Let $d_a$ and $d_{a'}$ be visual metrics on $\p X$ defined with respect to basepoints $p$ and $p'$, respectively. Then $(\p X,d_a)$ and $(\p X, d_{a'})$ are bilipschitz equivalent.
           \item Visual metrics $d_a$ and $d_{a'}$ on $\p X$ defined with respect to a basepoint $p$ and visual metric parameters $a$ and $a'$ are H\"{o}lder equivalent. That is, there exists a constant $K$ so that for all $\eta, \eta' \in \p X$,
                \[ \frac{1}{K}d_a^{\alpha}(\eta,\eta') \leq d_{a'}(\eta,\eta') \leq Kd_a^{\alpha}(\eta,\eta')\]
            where $\alpha = \frac{\log a'}{\log a}$.
       \end{enumerate}
    \end{lem}
    \begin{proof}
        Conclusion~(1) follows from the fact that for all $\eta, \eta' \in \p X$,
            \[|(\eta,\eta')_p - (\eta, \eta')_{p'}| \leq d_X(p,p').\]
        Indeed, it follows from the definition of the Gromov product together with the triangle inequality that for all $x_i,x_j,p,p' \in X$,
        $|(x_i,x_j)_p - (x_i,x_j)_{p'}| \leq d(p,p')$. The inequality above then follows from \Cref{lemma:exist_seq}.

        Conclusion~(2) follows from definitions and the relationship $a' = a^{\alpha}$.
    \end{proof}

    \begin{lem}\cite[Theorem 2.2]{tukiavaisala} \cite[Lemma 5.2.13]{buyaloschroeder}
        Suppose $f:X \rightarrow Y$ is a $\phi$-quasisymmetry and $g:Y \rightarrow Z$ is a $\psi$-quasisymmetry. Then $f^{-1}: Y \rightarrow X$ is a $\phi'$-quasisymmetry with $\phi'(t) = \frac{1}{\phi^{-1}(\frac{1}{t})}$. The composition $g \circ f: X \rightarrow Z$ is a $(\psi \circ \phi)$-quasisymmetry. In particular, quasisymmetry is an equivalence relation on metric spaces. \qed
    \end{lem}

    We note one immediate feature of quasisymmetries that distinguish them from the maps in the next subsection. Quasisymmetries take bounded spaces to bounded spaces.



    \begin{prop} \cite[Theorem 2.5]{tukiavaisala} \cite[Proposition 10.8]{heinonen-Lectures} \label{prop:QSBounded}
        If $f:X \rightarrow Y$ is a $\phi$-quasisymmetry and $B \subset X$ is a subset so that $0 <  \diam B < \infty$, then $\diam f(B) <\infty$.
        %and             \[ \frac{1}{2\phi \left( \frac{\diam B}{\diam A}\right)} \leq \frac{\diam f(A)}{\diam f(B)} \leq \phi\left(\frac{2\diam A}{\diam B}\right).  \]
    \end{prop}
    \begin{proof}
        Suppose that $B \subset X$ with $0 <  \diam B < \infty$. Let $b_1, b_1' \in B$ so that
            \[ \frac{1}{2}\diam B \leq d(b_1,b_1').   \]
        Let $b \in B$. It follows from the choice of the points $b_1, b_1'$ that
            \[d(b_1,b) \leq \diam B \leq 2 \cdot d(b_1,b_1').\]
        This yields the ratio
            \[\frac{d(b_1,b)}{d(b_1,b_1')} \leq 2.\]
        Since $f$ is a $\phi$-quasisymmetry,
            \[\frac{d\bigl(f(b_1), f(b) \bigr)}{d \bigl( f(b_1), f(b_1')\bigr)} \leq \phi(2). \]
        Thus,
            \[ d\bigl(f(b), f(b_1)\bigr) \leq \phi(2) \cdot d \bigl( f(b_1),f(b_2) \bigr).\]
        Therefore, $f(B)$ is bounded, as desired.
    \end{proof}

    There is a stronger version of the proposition above, appearing in \cite[Proposition 10.8]{heinonen-Lectures} and \cite[Theorem 2.5]{tukiavaisala}, which is used to prove that the doubling property is a quasisymmetry invariant; see \Cref{sec:qs_invariants}.



    \subsection{Relation to quasi-conformal and quasi-M\"{o}bius maps}

        There are two other well-studied notions related to quasisymmetries:

        \begin{enumerate}
            \item Quasi-conformal maps, defined by a local, infinitesimal condition on relative distances:

            \begin{defn}
                Let $f:Z \rightarrow Z'$ be a homeomorphism between metric spaces. Let $p \in Z$. The {\it dilatation} of $f$ at $p$ is
                \[ H(f,p):= \limsup_{r \rightarrow 0} \frac{\sup \bigl\{ d\bigl(f(x),f(p)\bigr) \,|\, x \in B_r(p) \bigr\}}{\inf \bigl\{ d\bigl(f(x),f(p)\bigr) \,|\, x \notin B_r(p) \bigr\}}. \]
                The homeomorphism $f$ is {\it $C$-quasi-conformal} if $H(f,p) \leq C$ for all $p \in X$. The map is {\it quasi-conformal} if it is $C$-quasi-conformal for some $C$.
            \end{defn}

            \item Quasi-M\"{o}bius maps, defined with respect to the cross-ratio:

            \begin{defn} \cite{vaisala-QM}
                Let $(Z,d)$ be a metric space. The {\it cross-ratio} of four pairwise distinct points $z_1, z_2, z_3, z_4 \in Z$ is
                    \[[z_1,z_2,z_3,z_4] := \frac{d(z_1,z_3)d(z_2,z_4)}{d(z_1,z_4)d(z_2,z_3)}.\]

                Let $f:Z \rightarrow Z'$ be a homeomorphism between metric spaces. The map $f$ is {\it quasi-M\"{o}bius} if there exists a homeomorphism $\phi:[0,\infty) \rightarrow [0,\infty)$ so that for every set of four pairwise distinct points $z_1, z_2, z_3, z_4 \in Z$,
                    \[ [f(z_1), f(z_2), f(z_3), f(z_4)] \leq \phi \bigl( [z_1,z_2,z_3,z_4] \bigr)]. \]
            \end{defn}
        \end{enumerate}

        For general metric spaces, the following implications hold~\cite{vaisala-QM}:
            \[ \textrm{Quasisymmetric} \Rightarrow \textrm{Quasi-M\"{o}bius} \Rightarrow \textrm{Quasi-conformal},\]
        and these notions need not agree in general. For example, quasisymmetries take bounded spaces to bounded spaces by \Cref{prop:QSBounded}, while maps in the other families need not. The familiar map $f:\C \rightarrow \C$ given by $f(z) = \frac{z-i}{z+i}$, which takes the upper halfplane to the unit disk, is a M\"{o}bius transformation and is thus both quasi-M\"{o}bius and quasi-conformal, but is not quasisymmetric.
        If $f:Z \rightarrow Z'$ is a quasi-M\"{o}bius homeomorphism between metric spaces and both $Z$ and $Z'$ are unbounded, then $f$ is quasisymmetric. Moreover, these two notions agree for boundaries of hyperbolic groups~\cite[Proposition 2.6]{haissinsky-QM}.

       The work of Heinonen--Koskela~\cite{heinonenkoskela} presents additional motivations for these notions and conditions under which they agree. These ideas were used in a fundamental way in the quasi-isometric rigidity work of Bourdon--Pajot~\cite{bourdonpajot} for right-angled Fuchsian buildings, and in subsequent work of Xie~\cite{xie06} for Fuchsian buildings.


        These distinct families of maps yield different perspectives on the analytic structure of the boundary of a hyperbolic group. Quasi-conformal maps are often studied and motivated through the lens of classical hyperbolic geometry, complex analysis, and conformal mappings. We refer the reader to \cite[Chapter 22]{drutukapovich} for a detailed discussion on quasi-conformal maps in geometric group theory and to \cite{haissinsky-QM} for quasi-M\"{o}bius maps. In particular, quasi-M\"{o}bius maps are useful to re-construct quasi-isometries of spaces via boundary maps.









    \subsection{Quasi-isometries and quasisymmetries} \label{sec:QIandQS}

    In this section we discuss the following foundational theorem. See the text of Buyalo--Schroeder~\cite[Theorem 5.2.17; Chapter 7]{buyaloschroeder} for variants for spaces without a geometric group action.

    \begin{thm} \cite{paulin} \label{thm:QI_QS}
        Let $X$ and $X'$ be proper geodesic hyperbolic metric spaces admitting geometric actions by hyperbolic groups. Let $d_a$ and $d_a'$ be visual metrics on $\p X$ and $\p X'$, respectively. Then the spaces $X$ and $X'$ are quasi-isometric if and only if the boundaries $(\p X, d_a)$ and $(\p X', d_a')$ are quasisymmetric.
    \end{thm}

    The proof utilizes the quasi-M\"{o}bius notion on the boundary $\p X$ and its relationship to distances in the space $X$. Indeed, this condition captures, up to a few $\delta$, the distance between geodesics connecting points on the boundary.
    These ideas can be illustrated in the simple case where $X$ is a tree and the visual metric is given by $d(\eta, \eta') = e^{-(\eta,\eta')_p}$ for some $p \in X$. Suppose $x,y,z,w\in \p X$ are pairwise disjoint. Suppose $\{x_i\}, \{y_i\}, \{w_i\}, \{z_i\}$ are points in $X$ so that
    \[ x_i \rightarrow x, \quad y_i \rightarrow y, \quad z_i \rightarrow z, \quad w_i \rightarrow w.\]
        Then,
        \begin{eqnarray*}
            \log[x,y,z,w] &=& \log\bigl(d(x,z)\bigr) + \log\bigl(d(y,w)\bigr)
            - \log\bigl(d(x,w)\bigr)-\log\bigl(d(y,z)\bigr) \\
            &=& -(x,z)_p - (y,w)_p + (x,w)_p + (y,z)_p \\
            &=& \frac{1}{2}\Bigl(d(x_i,z_i) + d(y_i,w_i) - d(w_i,x_i) - d(y_i,z_i) \Bigr)
              \end{eqnarray*}
        for large enough $i$. This last quantity corresponds to a distance in the tree between geodesics between points in $\{x,y,z,w\}$ (up to a sign); see \Cref{figure-quasiMobius}.

