    \section{Round trees and arcs in the boundary} \label{sec:round_trees}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



    In this section we describe the round tree technique, and then we survey its applications. We refer the reader to \cite[Chapter 4]{mackaytyson} for a general discussion of lower bounds on conformal dimension.


\subsection{The product of a Cantor set and an interval}

    We present a motivating special case before giving more general results.
    Recall that the Hausdorff dimension of the two-thirds Cantor set equals $\frac{\log 2}{\log 3}$, while its conformal dimension equals zero. The next example illustrates that taking the product with an interval has a remarkable consequence: the resultant space is one that achieves the conformal dimension. See \Cref{figure-CantorProduct}.

    \begin{figure}
                \begin{centering}
	            \begin{overpic}[width=.8\textwidth, tics=5]{figure-CantorProduct.pdf} %Add `grid' to see the grid.
                    \put(10,2){\small{$\Cdim(\cC) = 0$}}
                    \put(10,8){\small{$\Hdim(\cC) = \frac{\log 2}{\log 3}$}}
                    \put(60,2){\small{$\Cdim\bigl(\cC\times [0,1]\bigr) =  1+ \frac{\log 2}{\log 3}$}}
                    \put(60,8){\small{$\Hdim\bigl(\cC \times [0,1]\bigr) = 1+ \frac{\log 2}{\log 3}$}}
                \end{overpic}
	           \caption{\small{A stabilization occurs with respect to conformal dimension upon taking the product with an interval. While the conformal dimension of the two-thirds Cantor set is zero, the conformal dimension of the product of the Cantor set and the interval is achieved by the Hausdorff dimension of this space.}}
	           \label{figure-CantorProduct}
                \end{centering}
            \end{figure}




    \begin{thm} \label{thm:cantorInterval}
        Let $\cC$ be the two-thirds Cantor set, and let $Z = \cC \times [0,1]$ equipped with the product metric. Then
            \[\Cdim(Z) = \Hdim(Z) = \Hdim (\cC) + 1 = \frac{\log 2}{\log 3} + 1.\]
    \end{thm}
    \begin{proof}
        The definition of conformal dimension implies $\Cdim(Z) \leq \Hdim(Z)$.
        The Hausdorff dimension of $Z$ follows from the calculations in \Cref{ex:HDimCantor} together with \cite[Example 7.6]{falconer}. The remainder of the proof follows the arguments of \cite[Lemme 1.6]{bourdon95} and \cite[Proposition 4.1.3]{mackaytyson}, restricted to this special case.

        Suppose towards a contradiction that $\Cdim(Z) < \Hdim(Z)$. Then, there exists a metric space $(Z',d')$ of Hausdorff dimension strictly less than $p:=1+ \frac{\log 2}{\log 3} = \Hdim(Z)$ and a quasisymmetry $f:Z \rightarrow Z'$.

        Let $\cE$ be the following natural curve family in $Z$:
            \[\cE:= \bigl\{ \{z\} \times [0,1] \,\,|\,\, z \in \cC \bigr\}.\]
        We will use the following two properties of the set $\cE$:

        \begin{enumerate}
            \item The diameter of each $E \in \cE$ is uniformly bounded from below, as $\diam(E) = 1$.

            Consequently, there exists $c'>0$ so that
                \[\diam\bigl(f(E)\bigr) \geq c'\]
            for each $E \in \cE$. Indeed, the map $f$ is a homeomorphism by definition, and since $Z$ and $Z'$ are compact, $f^{-1}$ is uniformly continuous. So, if $\epsilon = \frac{1}{2}$, then there exists $\delta>0$ so that if $d(f(x),f(x'))<\delta$, then $d(x,x')<\frac{1}{2}$. This implies the image of $E \in \cE$ cannot have diameter less than $\delta$, as desired.

            \item There is a probability measure $\mu$ on $\cE$ induced from the natural probability measure $\mu_{\cC}$ on the Cantor set (see \Cref{ex:HDimCantor}). Recall that with respect to the measure $\mu_{\cC}$, if $B_r(z)$ is a ball of radius $r$ in the Cantor set, then $\mu_{\cC}\bigl(B_r(z)\bigr) \leq (6r)^{\log 2/\log 3}$. Thus, there exist constants $A>0$ and $\alpha \geq 0$ so that with respect to the measure $\mu$, if $B_r(z) \subset Z$ is a ball of radius $r$ in $Z$, then
                \[ \mu \bigl\{ E \in \cE \,\,|\,\, E \cap B_r(z) \neq \emptyset  \bigr\} \leq Ar^{\alpha}. \]
            Indeed, $A = 6^{\log 2 / \log 3}$ and $\alpha = \frac{\log 2}{\log 3}$ in this case.

            We record a relationship between $\alpha$ and $p = 1 + \alpha$ used later in the proof. Let $p'$ be the H\"{o}lder conjugate of $p$, so that $\frac{1}{p} + \frac{1}{p'} = 1$ and $p' = \frac{p}{p-1}$. Then $\alpha p' = p$.
        \end{enumerate}

        Let $\epsilon >0$. Since $\Hdim(Z') <p$, there exists a cover of $Z'$ by a collection of balls $\{B_i'\}_{i \in I'}$ so that $B_i'$ has radius $r_i'$ and
            $ \sum_{i \in I'} (r_i')^p <\epsilon$; see \Cref{rem:balls}.
        By \Cref{lemma:ballscover} there exists a subfamility $\{B_i'\}_{i \in I} \subset \{B_i'\}_{i \in I'}$ so that the elements of $\{B_i'\}_{i \in I}$ are pairwise disjoint and $Z = \bigcup_{i \in I} 5B_i'$. (Recall that if $B = B_r(z)$, then $KB = B_{Kr}(z)$.)
        Then,
            \[ \sum_{i \in I} (r_i')^p < \epsilon.  \]
       % Choose $\epsilon$ small enough so that $f(E)$ is not contained in $10B_i'$ for $i \in I$.

        The quasisymmetry $f$ yields a corresponding family of balls in the metric space $Z$. More specifically, by Lemma~\ref{lemma:annuli} there exists a constant $H$ and balls $\{B_i\}_{i \in I}$ in the metric space $Z$ so that
            \[B_i \subset f^{-1}(B_i') \subset f^{-1}(5B_i') \subset HB_i.\]
        Since $f$ is a homeomorphism, balls in the family $\{B_i\}_{i \in I}$ are pairwise disjoint.

        For each $i \in I$, define a function
            \[h_i: \cE \rightarrow \{0,1\}\]
        given by
            \begin{equation*}
            h_i(E)=
            \begin{cases}
                 1 & f(E) \cap 5B_i' \neq \emptyset\\
                 0 & \text{otherwise}
             \end{cases}
            \end{equation*}

        \begin{claim} \label{claim:c'}
            $\displaystyle \frac{1}{10}c' \leq \sum_{i \in I} r_i'h_i(E).$
        \end{claim}
        \begin{proof}[Proof of Claim.]
            Let $E \in \cE$. Then, we have the following inequalities. The first holds from the definition of $c'$, and the second holds since $\{5B_i'\}_{i \in I}$ covers $Z'$. The final equality follows from the definition of $h_i(E)$.
            \[c' \leq \diam\bigl(f(E)\bigr) \leq \sum_{f(E) \cap 5B_i' \neq \emptyset} \diam(5B_i') \leq \sum_{f(E) \cap 5B_i' \neq \emptyset} 10r_i' = \sum_{i \in I} 10r_i'h_i(E). \]
        \end{proof}

        The proof will conclude after the next sequence of inequalities. We provide justification below.
            \begin{eqnarray}
                \frac{1}{10}c' & \leq & \int_{\cE} \, \sum_{i \in I} r_i' h_i(E) \, d\mu(E)  \label{L1} \\
                & \leq & \sum_{i \in I} r_i' \, \mu \bigl\{ E \in \cE \,|\, f(E) \cap 5B_i' \neq \emptyset \bigr\} \label{L2}  \\
                & \leq & \sum_{i \in I} r_i' \mu \bigl\{ E \in \cE \,|\, E \cap HB_i \neq \emptyset \bigr\} \label{L3} \\
                & \leq & \sum_{i \in I} r_i' A(Hr_i)^{\alpha} \label{L4} \\
                & = & AH^{\alpha} \sum_{i \in I} r_i' r_i^{\alpha} \label{L5} \\
                & \leq & AH^{\alpha} \left( \sum_{i \in I} (r_i')^p \right)^{1/p}\left( \sum_{i \in I} (r_i^{\alpha})^{p'} \right)^{1/p'} \label{L6} \\
                & \leq & AH^{\alpha} \left( \sum_{i \in I} (r_i')^p \right)^{1/p}\left( \sum_{i \in I} r_i^p \right)^{1/p'} \label{L7} \\
                & \leq & AH^{\alpha} \epsilon^{1/p} \bigl(\cH^p(Z) \bigr)^{1/p'}.\label{L8}
            \end{eqnarray}

            Inequality~\ref{L1} follows from integrating both sides of the inequality of \Cref{claim:c'} with respect to the measure $\mu$. Inequality~\ref{L2} follows from the definition of $h_i$.  Inequality~\ref{L3} holds since $f$ is a homeomorphism and $f^{-1}(5B_i') \subset HB_i$. Inequality~\ref{L4} comes from the second property of the curve family. Inequality~\ref{L5} rearranges terms. Inequality~\ref{L6} follows from the H\"{o}lder Inequality. Inequality~\ref{L7} applies that $\alpha p' = p$ as discussed above. Finally, Inequality~\ref{L8} comes from the assumptions on $r_i'$ given above, and the fact that the Hausdorff measure of $Z$ is less than the term involving the $r_i$ because the sets in the collection $\{B_i\}_{i \in I}$ are pairwise disjoint and $p$ is the Hausdorff dimension of $Z$.

            The inequalities combine to $\frac{1}{10}c' \leq AH^{\alpha}\epsilon^{1/p}\bigl( \cH^p(Z)\bigr)^{1/p'}$, a contradiction as $\epsilon$ can be taken arbitrarily small, while the other constants are fixed.
    \end{proof}

    The proof of the previous theorem applied the following useful lemma.

    \begin{lem} \cite[Theorem 1.2]{heinonen-Lectures} \label{lemma:ballscover}
        Let $(Z,d)$ be a metric space. Let $\cF$ be a family of balls in $Z$ so that $Z = \bigcup_{B \in \cF} B$. Assume that the diameters of the balls in $\cF$ are uniformly bounded from above. Then, there exists a subfamily $\cG \subset \cF$ so that the elements of $\cG$ are pairwise disjoint and $Z = \bigcup_{B \in \cG} 5B$.
    \end{lem}

    We now state two generalizations of \Cref{thm:cantorInterval}. Their proofs are modeled on an argument due to Pansu \cite[Proposition 2.9]{pansu}, \cite[Lemma 6.3]{pansu89b} and follow the same reasoning as in the theorem above. The curve family and its measure allows one to compare covers by balls of the two spaces $Z$ and $Z'$ related by a quasisymmetry $f:Z \rightarrow Z'$. The H\"{o}lder inequality is useful to introduce the exponents appearing in the Hausdorff dimension computations.

    \begin{prop} \cite[Lemma 1.6]{bourdon95}
        Let $(Z,d)$ be a compact metric space. Suppose there exists the following:
            \begin{enumerate}
                \item A family of curves $\cC = \{\gamma_i \,|\, i \in I\}$ in $Z$ with diameters uniformly bounded from below.
                \item A probability measure $\mu$ on $\cC$ and constants $A>0$ and $\alpha \geq 0$ so that for every ball of radius $r$ in $Z$,
                    \[ \mu \{\gamma \in \cC\,|\, \gamma \cap B \neq \emptyset \} \leq Ar^{\alpha}.\]
            \end{enumerate}
            Let $\tau$ denote the packing dimension of $Z$. Then
            \[\Cdim(Z) \geq \frac{\tau}{\tau - \alpha} \quad \quad \textrm{ with } \tau-\alpha \geq 1.\]
    \end{prop}

    The second generalization uses a measure on the metric space to replace the radius of a ball.

    \begin{prop} \cite[Proposition 4.1.3]{mackaytyson}
        Let $(Z,d,\mu)$ be a compact, doubling metric measure space, and let $1<p<\infty$. Suppose that there exists a family $\cE$ of connected sets in $Z$ and a probability measure $\mu$ on $\cE$ with the following properties:
            \begin{enumerate}
                \item There exists $c>0$ so that $\diam E \geq c$ for all $E \in \cE$.
                \item There exists $A>0$ and $r_0>0$ so that
                    \[\nu\{E \in \cE \,|\, E \cap B \neq \emptyset\} \leq A\mu(B)^{1/p'} \]
                    for all balls $B$ in $Z$ of radius at most $r_0$.
            \end{enumerate}
        Then, $\Cdim(Z) \geq p$, where $p$ and $p'$ are H\"{o}lder conjugates.
    \end{prop}





\subsection{Gromov's round trees}

    \begin{figure}[t]
    \begin{centering}
	\begin{overpic}[width=.3\textwidth, tics=5]{figure-GromovRoundTree.pdf} %Add `grid' to see the grid.
        \put(-5,90){$\Hy^3$}
    \end{overpic}
	\caption{\small{Gromov's round trees. }}
	\label{figure-GromovRoundTree}
    \end{centering}
    \end{figure}

    Gromov's round tree construction is a tool to build a family of arcs homeomorphic to the product of a Cantor set and an interval in the boundary of a hyperbolic metric space~\cite[Section 7.C3]{gromov93}. We start with Gromov's original definition and then present a combinatorial point of view. In particular, Mackay's {\it combinatorial round trees}, are useful in building subcomplexes of hyperbolic groups that are quasi-isometric to a round tree.



    \begin{example} \cite[Page 136]{gromov93}
        Gromov begins with the following example. Let $T \subset \Hy^2 \subset \Hy^3$ be a quasi-isometrically embedded rooted tree with boundary the Cantor set. Rotate $T$ around a geodesic as indicated in \Cref{figure-GromovRoundTree}.  The resultant space $\cR$ decomposes into unions of quasi-isometric copies of the hyperbolic plane, which intersect in disks. The boundary $\p \cR$ is homeomorphic to the product of a Cantor set and the circle.
    \end{example}



    \begin{defn} \cite[Page 137]{gromov93}
        A {\it two-dimensional round tree} $X_0$ is a two-dimensional space of negative curvature which admits an isometric action of $S^1$ with a single fixed point $x_0$ so that there is an isometrically embedded tree $T \subset X_0$ which intersects every $S^1$ orbit at exactly one point.
    \end{defn}

    Gromov's discussion focuses on the case that the metric is locally the metric of $\Hy^2$ away from the singular locus. This assumption is typically dropped in applications. To obtain bounds on conformal dimension, one does not require the full $S^1$-action; one can take a subcomplex with boundary the product of the Cantor set and an interval. Such subcomplexes are also referred to as round trees.

    Alternatively, one can construct a round tree by starting with a sector of the hyperbolic plane, viewed in the unit disk model. See \Cref{figure-GromovRoundTree_sector}. Take $b$ copies of this sector and glue them together by isometries along the intersection of the disk in the hyperbolic plane of radius $\ell$ with each sector. For each of the $b$ sectors, take $b-1$ additional sectors, and glue them together by isometries along the intersection of the disk in the hyperbolic plane of radius $2\ell$ with each sector. Continue in this way to obtain a round tree, built from sectors in the hyperbolic plane that naturally branch according to the $b$-valent rooted tree with edges of length $\ell$. The boundary is homeomorphic to the product of a Cantor set and an interval. Crucially, the Hausdorff dimension of the boundary of the round tree, and hence its conformal dimension by \Cref{thm:cantorInterval}, can be computed with respect to the degree of the tree and the distance between vertices.

     \begin{figure}[t]
    \begin{centering}
	\begin{overpic}[width=.3\textwidth, tics=5]{figure-roundtree_sector.pdf} %Add `grid' to see the grid.

    \end{overpic}
	\caption{\small{A portion of a round tree obtained by gluing sectors of the hyperbolic plane (viewed in the disk model) along initial subcomplexes. The boundary of the limiting object is homeomorphic to the product of the Cantor set and an interval. }}
	\label{figure-GromovRoundTree_sector}
    \end{centering}
    \end{figure}



    To obtain lower bounds on conformal dimension, one seeks to quasi-isometrically embed a round tree in a hyperbolic metric space. Mackay~\cite{mackay16} gave a combinatorial version of round trees that are well-suited to polyhedral complexes. The results below generalize work of Bourdon~\cite{bourdon95} and Mackay~\cite{mackay}.

    If $A'\subset A$ is a subcomplex of a polygonal complex $A$, then the {\it star} of $A'$ in $A$, denoted $\St(A')$, is the union of all closed cells in $A$ that nontrivially intersect $A'$.  Let $\N = \Z_{\geq 1}$.

    \begin{defn}[Combinatorial round tree] \cite[Definition 7.1]{mackay16} \label{defn:RT}
        A polygonal $2$-complex $A$ is a {\it combinatorial round tree} with vertical branching $V \in \N$ and horizontal branching at most $H \in \N$ if the following holds. Let $T = \{1,2, \ldots, V\}$.   Then
            \[ A = \bigcup_{\ba \in T^{\N}} A_{\ba}, \]
        where
        \begin{enumerate}
            \item The complex $A$ has a basepoint $x_0$ contained in the boundary of a unique $2$-cell $A_0' \subset A$.
            \item Each complex $A_{\ba}$ is an infinite planar $2$-complex homeomorphic to a half-plane whose boundary is the union of two rays $L_{\ba}$ and $R_{\ba}$ with $L_{\ba} \cap R_{\ba} = \{x_0\}$.

            \item Let $A_0$ be a union of $2$-cells so that $A_0' \subseteq A_0$ and $A_0$ is homeomorphic to a closed disk.
            For $n>0$, the {\it round tree at step $n$} is defined as $A_n = \St(A_{n-1})$. Given $\ba = (a_1, a_2, \ldots) \in T^\N$, let $\ba_n = (a_1, \ldots, a_n) \in T^n$. If $\ba,\ba' \in T^\N$ satisfy $\ba_n = \ba'_n$ and $\ba_{n+1} \neq \ba'_{n+1}$, then
                \[ A_n \cap A_{\ba} \subseteq A_{\ba'} \cap A_{\ba} \subseteq A_{n+1} \cap A_{\ba}.\]
            \item Each $2$-cell $P \subseteq A_n$ meets at most $VH$ $2$-cells in $A_{n+1} \backslash A_n$.
        \end{enumerate}
    \end{defn}

    \begin{remark}
         A combinatorial round tree has the following structure, as  explained by Mackay \cite{mackay16}. Each complex $A_n$ is the union of $V^n$ distinct planar $2$-complexes $\{A_{\ba_n}\}_{\ba_n \in T^n}$. Each complex $A_{\ba_n} \subset A_n$ is homeomorphic to a disk. The complexes $A_{\ba_n} \subset A_n$ are glued together along their initial subcomplexes in a branching fashion. The boundary of $A_{\ba_n}$ decomposes as a union of three paths: $L_{\ba} \cap A_n$, $R_{\ba} \cap A_n$, and a connected path $E_{\ba_n}$. The complex $A_{\ba_{n+1}}$ is built from $A_{\ba_n}$ by attaching $2$-cells in $V$ strips along the path $E_{\ba_n}$. In each strip, each $2$-cell in $A_{\ba_n}$ is adjacent to at most $H$ new $2$-cells.
    \end{remark}

   Lower bounds on the conformal dimension of a hyperbolic polygonal complex then follow from the following theorem.

    \begin{thm} \cite[Theorem 7.2]{mackay16} \label{thm:mackayRT}
        Let $X$ be a hyperbolic polygonal $2$-complex. Suppose there is a combinatorial round tree $A$ with vertical branching $V \geq 2$ and horizontal branching $H \geq 2$. Suppose that $A^{(1)}$, with the natural length metric giving each edge length one, admits a quasi-isometric embedding into $X$. Then
            \[ \Cdim(\p X) \geq 1 + \frac{\log V}{\log H}.\]
    \end{thm}

    In the proof of the theorem above, one embeds a tree in the dual graph to the polygons. The Hausdorff dimension of the Cantor set boundary can be bounded in terms of $V$ and $H$.




\subsection{Bourdon buildings}

    Bourdon~\cite{bourdon95} utilized Gromov's round trees to give lower bounds on the conformal dimension of certain right-angled Fuchsian buildings, which are often referred to as {\it Bourdon buildings}. A discussion of constructing round trees in these examples also appears in Gromov's article. The boundary of each building is homeomorphic to the Menger curve~\cite{benakli, dymaraosajda}. Bourdon's result presented the first family of hyperbolic groups with one-dimensional topological boundary for which the conformal dimension tends to infinity.

    Subsequent work of Bourdon~\cite{bourdon} computed the conformal dimension of the buildings exactly. Interestingly, non-isometric buildings can have equal conformal dimension. Moreover, the result proved that the conformal dimension values over all spaces in this family forms a dense subset of $(1, \infty)$. Bourdon--Pajot~\cite{bourdonpajot} then proved a strong form of quasi-isometric rigidity in this setting, showing that any quasi-isometry between two such buildings is bounded distance from an isometry. Thus, in contrast to the setting of the rank-1 symmetric spaces, the homeomorphism type of the boundary together with its conformal dimension is not a complete quasi-isometry invariant within this family of spaces. See \cite{bourdonpajot-survey} for additional discussion of these examples and their context.

    \begin{defn}[Bourdon building $I_{p,q}$]
        Let $p \geq 5$ and $q \geq 3$ be integers. The {\it Bourdon building} $I_{p,q}$ is a $\CAT(-1)$ polyhedral complex where each $2$-cell is isometric to a regular right-angled hyperbolic $p$-gon. Each edge of each polygon is contained in exactly $q$ distinct polygons. The link of each vertex is isomorphic to the complete bipartite graph $K_{q,q}$ with two vertex sets of size $q$. As shown by Bourdon~\cite[Proposition 2.2.1]{bourdon}, there is a unique polyhedral complex with these properties.
    \end{defn}

        Note that if $q=2$, so the link of each vertex is a $4$-cycle, then the resulting space is isometric to the hyperbolic plane. As $K_{2,2}$ is a subgraph of $K_{q,q}$ for $q>2$ in many ways, the building contains many (isometrically embedded) copies of the hyperbolic plane.

        The following graph product acts geometrically on the building $I_{p,q}$,
            \[\Gamma_{p,q}:= \la \, s_1, \ldots, s_p \,|\, s_i^q, [s_i, s_{i+1}] \,\ra.\]
        A fundamental domain for the action is a single polygon in the building, and one can view each generator as acting by rotation around a convex subcomplex containing an edge of a polygon.

        \begin{thm} \cite[Theorem 1.1]{bourdon}
            Let $I_{p,q}$ be a building as described above, and let $d_a$ be a visual metric on its boundary. Then
            \[ \Cdim(\p I_{p,q}, d_a) = 1 + \frac{\log (q-1)}{\arccosh\left( \frac{p-2}{2}\right)}. \]
        \end{thm}

        Bourdon notes that for $p' = (p-2)^2$ and $q'-1 = (q-1)^2$, the boundaries of the associated buildings have equal conformal dimension. For example, $\Cdim(\p I_{5,3}) = \Cdim(\p I_{9,5})$. See also \cite[Section 3.5]{mackaytyson} for additional discussion of these examples.

    \begin{figure}[t]
    \begin{centering}
	\begin{overpic}[width=.5\textwidth,  tics=5]{figure-BourdonBuildingGraPh.pdf} %Add `grid' to see the grid.
        \put(32,29){\small{$v$}}
        \put(5,10){\small{$A$}}
        \put(82,5){\small{$\Lk(v)$}}
    \end{overpic}
	\caption{\small{Building a round tree in a Bourdon building $I_{5,3}$. The complex is extended along strips at each vertex; this construction at $v$ is possible as the link of a vertex $v$ contains many 4-cycles that intersect only in an edge.}}
	\label{figure-BourdonBuilding}
    \end{centering}
    \end{figure}

        We indicate some of the intuition behind constructing round trees in this example. See \Cref{figure-BourdonBuilding}. The round tree $A$ is built recursively, by building branching sectors one strip at a time. The link of each vertex in the building is sufficiently rich that each strip can be extended to $q-1$ new strips. Suppose an initial portion of the round tree $A$ has been constructed and $P$ is a polygon on the outer boundary of this complex. There are various cases to consider, but to give one example, suppose $v \in P$ is a outer vertex, so that its incident edges are not glued to other polygons in the subcomplex previously constructed. The link of $v$ is $K_{q,q}$, and only one edge of this link corresponds to a polygon already in the subcomplex. This edge $e$ lies in $q-1$ $4$-cycles in the link that pairwise intersect only in $e$. These $4$-cycles correspond to polygons that can be added to the subcomplex to build pieces of $q-1$ new strips at the vertex $v$. One must then verify various compatibility conditions, as the complex is extended over various vertices.


\subsection{Mackay's applications}

    Mackay's work uses the round tree techniques in two quite different settings. The first result is remarkably general. Mackay produces round trees in the boundary of any one-ended hyperbolic group that does not split over a two-ended subgroup. As a consequence, Mackay proves the conformal dimension of any such group is strictly greater than one.
    The second application is to produce bounds on the conformal dimension of groups satisfying certain small cancellation conditions. As a consequence, Mackay obtains bounds on the conformal dimension of random groups, proving there are infinitely many quasi-isometry classes as certain parameters vary. The results are as follows.

    \begin{thm} \cite[Corollary 1.2]{mackay10}
        Suppose that $G$ is a hyperbolic group whose boundary is non-empty, connected, and has no local cut points. Then the conformal dimension of $\p G$ is strictly greater than one.
    \end{thm}

    The strategy to prove the above theorem begins with the existence of a quasi-arc in the boundary, as discussed in \Cref{sec:qs_invariants}. Mackay then performs a splitting operation, using the topology of the boundary, to obtain two arcs. He applies an arc straightening procedure to obtain two uniform quasi-arcs and repeats the process until the product of a Cantor set and an interval appears in the boundary. We note that Carrasco--Mackay characterized hyperbolic groups without $2$-torsion whose boundaries have conformal dimension equal to one~\cite{carrascomackay}. These groups admit a hierarchy over elementary edge groups that terminates in virtually cyclic or virtually Fuchsian vertex groups. This work uses combinatorial modulus techniques.

    For a detailed description on conformal dimension of boundaries of random groups we refer the reader to the survey of Mackay~\cite{mackay-survey};  we indicate some of the results below. First, recall the definition of the density model of a random group.

    \begin{defn}[Density model of random groups]
        Fix $m \geq 2$ and $S$ a generating set with $m$ elements. Fix a {\it density} $d \in (0,1)$. Consider all cyclically reduced words of length $\ell$ in $\la S \ra$. Consider all presentations which choose as relators $(2m-1)^{d\ell}$ of these words uniformly and independently at random. A property $\cP$ holds {\it generically} if the proportion of all such presentations at length $\ell$ which satisfy $\cP$ goes to $1$ as $\ell \rightarrow \infty$.
    \end{defn}


    \begin{thm} \cite[Theorem 1.3]{mackay16}
        There exists a constant $C>1$ so that for fixed $m \geq 2$, if $G$ is a random group at density $0<d<\frac{1}{8}$, then asymptotically almost surely
            \[ \frac{\log(2m-1) d\ell}{C|\log d|} \leq \Cdim(\p G). \]
        In particular, for each $d<\frac{1}{8}$, as $\ell \rightarrow \infty$, generic groups pass through infinitely many quasi-isometry classes.
    \end{thm}

    The bounds above extend those given by Mackay in \cite[Theorem 1.4]{mackay} for $0<d<\frac{1}{16}$. The theorem bounds has been further extended by Oppenheim~\cite{oppenheim} and Frost~\cite{frost} to $0<d<\frac{1}{2}$.

    Mackay uses round trees to produce these lower bounds on conformal dimension. The strategy to find round trees in the Cayley $2$-complex is to realize groups in this family as small cancellation groups that satisfy certain useful conditions on the relators. For example, in \cite{mackay} Mackay asks that there exists some $N\geq 12$ so that every reduced word in $\la S \ra$ of length $N$ appears at least once in a cyclic conjugate of a relator (or its inverse). The round tree is built recursively. At each step, the boundary arc of each previous strip is split into segments of length 6. At each endpoint the subcomplex is first extended by adding $b$ new outward edge paths of length 3. Because each word of length 12 appears in some relator, there exist polygons in the Cayley 2-complex to fill in these extensions to build $b$ new strips in the round tree. See \cite[Section 5]{mackay} and \cite[Figure 4]{mackay}.

    This approach was generalized in \cite{mackay16} and \cite{frost} by asking that all words of length $\frac{3d\ell}{4}$ appear in the presentation a.a.s, and subdividing the boundary arc into segments of length $\frac{d\ell}{4}$. See \cite[Figure 17]{mackay-survey}.




\subsection{Relatively hyperbolic Coxeter groups}

    In joint work with Elizabeth Field, Radhika Gupta, and Robbie Lyman, the author used the round tree technique to produce the first non-trivial conformal dimension bounds for the Bowditch boundary of non-hyperbolic relatively hyperbolic groups. As explained below, one application proved there are infinitely many quasi-isometry classes among hyperbolic groups with Pontryagin sphere boundary.

    We considered the following family of Coxeter groups.

    \begin{defn}[Coxeter group]
        Let $\Gamma$ be a finite, simplicial graph with vertex set $V\G = \{s_1, \ldots, s_m\}$ and edge set $E\G$. Assume that each unoriented edge $\{s_i,s_j\} \in E\Gamma$ is labeled by a positive integer $m_{ij} \geq 2$. The \emph{Coxeter group $W_\Gamma$ with defining graph $\Gamma$} is the group given by the presentation
    \[ W_\Gamma = \langle \, s_1, \ldots, s_m \mid s_i^2 = 1,\ (s_is_j)^{m_{ij}} = 1 \textrm{ for all } s_i \in V\G, \{s_i,s_j\} \in E\G \, \rangle. \]
    The generators $s_i$ are called \emph{standard} or \emph{Coxeter} generators of $W_\Gamma$.
    \end{defn}

    \begin{defn}[Family of groups $\cW$]
        Let $\cW$ be the family of Coxeter groups with defining graph a complete graph and so that each edge label is at least $3$.
    \end{defn}

    Groups in this family have been previously considered, and we note relevant properties.

    \begin{itemize}
        \item The Davis--Moussong complex for $W_\Gamma \in \cW$ is a $\CAT(0)$-polygonal complex where each 2-cell is a regular Euclidean polygon and each vertex link is a complete graph on $n$ vertices. The group acts geometrically on this complex; each generator acts by a reflection across a convex wall, which is isometric to a regular tree \cite{davis}.

        \item If $W_\Gamma \in \cW$ and there is no triangle in $\Gamma$ with all three edges labeled three, then $W_\Gamma$ is hyperbolic. Otherwise, $W_\Gamma$ is hyperbolic relative to virtually abelian groups of rank two. In this case, the group is $\CAT(0)$ with isolated flats \cite{wise96}, \cite{hruska04} \cite[Moussong's Theorem; Corollary 12.6.3]{davis}.

        Let $\cP$ be the collection of stabilizers of two-dimensional flats in the Davis complex (and let $\cP$ be empty if $W_\Gamma$ is hyperbolic). Then $(W_\Gamma, \cP)$ is a relatively hyperbolic group pair.


        \item If $|V\Gamma| = 4$, then $W_\Gamma$ is Kleinian, and the $\CAT(0)$ boundary of $W_\Gamma$ is homeomorphic to the Sierpinski carpet \cite{andreev, schroeder, ruane-sier, haulmarkhruskasathaye}.

        One can view groups in this family $\cW$ as being constructed from Kleinian groups. This point of view is detailed \cite{fieldguptalymanstark} and motivated the construction of a $\CAT(-1)$ space that the group pair $(W_\Gamma, \cP)$ acts on geometrically finitely.

        \item If $|V\Gamma|\geq 5$, then the $\CAT(0)$ boundary of $W_\Gamma$ is homeomorphic to the Menger curve as shown by Haulmark--Hruska--Sathaye~\cite{haulmarkhruskasathaye}. This family of groups gave the first examples of non-hyperbolic $\CAT(0)$ groups with Menger curve boundary.

        \item Bourdon--Kleiner used $\ell_p$-cohomology to produce upper bounds on the conformal dimension of hyperbolic groups in this family \cite{bourdonkleiner15}. In particular, they showed that if $W_\Gamma \in \cW$ is defined on a complete graph with $m$ vertices and every edge label is at least $M \geq 4$, then
        \[ \Cdim(\p W_\Gamma) \leq 1 + \frac{\log(m-1)}{\log(2M-5)}.\]
    \end{itemize}

    We produced upper and lower bounds on the conformal dimension of the Bowditch boundary of the relatively hyperbolic group pair $(W_\Gamma, \cP)$.

    \begin{remark}[Bowditch boundary]
        Bowditch~\cite{bowditch12} proved that a relatively hyperbolic group pair $(G, \cP)$ admits a well-defined boundary, called the {\it Bowditch boundary} and denoted $\p(G, \cP)$. This compact topological space is the visual boundary of any {\it cusped Cayley graph} for $G$, where a combinatorial horoball is attached to each coset of each peripheral subgroup~\cite{grovesmanning08}. The cusped Cayley graph is a proper geodesic $\delta$-hyperbolic metric space, and hence the boundary $\p(W_\Gamma, \cP)$ admits a family of visual metrics. Since each group in $\cP$ is not itself nontrivially relatively hyperbolic, the quasisymmetry type of $\p(W_\Gamma, \cP)$ is a quasi-isometry invariant of the group $W_\Gamma$ \cite{behrstockdrutumosher, groff13, healyhruska}. Thus, the conformal dimension of $\p(W_\Gamma, \cP)$ is a quasi-isometry invariant of the group $W_\Gamma \in \cW$.
    \end{remark}


    The lower bounds on the conformal dimension of $\p(W_\Gamma, \cP)$ were obtained by quasi-isometrically embedding round trees in the Davis--Moussong complex for these groups. As the groups are not hyperbolic, the complex was constructed to avoid large intersections with flats. The bounds are as follows.

\begin{thm} \cite[Theorem A]{fieldguptalymanstark} \label{thm:CoxBounds}
    Let $\Gamma$ be a complete graph with $m \geq  11$ vertices and edge labels $m_{ij} \geq 3$. Let $M = \max{m_{ij}}$. Then
        \[\Cdim\bigl(\p (W_\G, \cP)\bigr) \geq 1 + \frac{\log \bigl(\lfloor\frac{m-5}{3}\rfloor\bigr)}{\log (2M-1)}.\]
\end{thm}

    In particular, the theorem shows that if the maximum edge labels are fixed, then the conformal dimension goes to infinity as the number of vertices in the defining graph does. This implies there are infinitely many quasi-isometry classes among any such family of Coxeter groups. Combining this result with work of Bourdon--Kleiner~\cite{bourdonkleiner15} proved that the conformal dimension of the boundaries of hyperbolic groups in this family achieves a dense set in $(1,\infty)$.



    \begin{remark}[Round tree construction]
        Similar to the results of Bourdon and Mackay discussed above, the construction of the round tree subcomplexes was recursive and followed from the richness of each vertex link and its high symmetry. In particular, one can locally build strips by extending along an edge path. As the number of vertices in the defining graph increases, the number of strips that can be constructed increases. The subtlety in the construction lies in ensuring that the subcomplex is convex in the 1-skeleton. The main tool to study convexity in Coxeter group is the structure of walls in the Davis--Moussong complex, and this is utilized in the proof.
    \end{remark}

    Additional motivation for studying this family of groups $\cW$ was to provide lower bounds on the conformal dimension of the boundary of arbitrary hyperbolic Coxeter groups with edge labels at least three. Indeed, if $\Gamma$ is a simplicial graph and $\Lambda \subset \Gamma$ is an induced subgraph, then if $W_\Gamma$ is hyperbolic, $W_\Lambda \leq W_\Gamma$ is a quasi-convex subgroup. Thus, if $W_\Gamma$ is a hyperbolic Coxeter group whose nerve contains an induced complete graph $\Gamma'$, then the lower bound on the conformal dimension of $\p W_{\Gamma'}$ yields a lower bound on the conformal dimension of $\p W_{\Gamma}$.

    \begin{remark}[Pontryagin sphere boundaries] \label{rem:Pont}
        The Pontryagin sphere is a compact 2-dimensional fractal that arises as the boundary of $3$-dimensional hyperbolic pseudo-manifolds, where the link at each point in the space is either a sphere or a torus. This space can be viewed as an inverse limit of an inverse system of tori. Alternatively, the space obtained by gluing opposite sides of each boundary square in the standard square Sierpinski carpet is homeomorphic to the Pontryagin sphere. See \cite{jakobsche,swiatkowski-trees, zawislak, fischer, DoubaLeeMarquisRuffoni} for details of its construction.

        The Pontryagin sphere arises as the boundary of Coxeter groups, as shown by Fischer~\cite{fischer} in the right-angled case and by \'Swi\k{a}tkowski~\cite{swiatkowski-trees} more generally.  That is, the boundary of a hyperbolic Coxeter group whose nerve is a closed surface of genus at least one is homeomorphic to the Pontryagin sphere~\cite[Theorem 2]{swiatkowski-trees}. Every complete graph embeds as an induced subgraph in the 1-skeleton of a triangulation of a surface, and edge labels can be chosen so that the nerve of the corresponding Coxeter group is homeomorphic to the surface. Therefore, \Cref{thm:CoxBounds} implies there are infinitely many quasi-isometry classes among hyperbolic Coxeter groups with Pontryagin sphere boundary. Work with Cashen--Dani--Schreve~\cite{cashendanischrevestark} proves the analogous statement for right-angled Coxeter groups, by embedding round trees in the Davis complex within a particular infinite family of these groups.

        The quasi-isometry classification, abstract commensurability classification, and questions of rigidity for hyperbolic groups with Pontryagin sphere boundary are broadly open.
    \end{remark}



