\section*{Appendix: Some useful combinatorial identities}
The Newton binomial formula  holds for any $a\in\mathbb{C}$:

\begin{equation}\label{bin1}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}a^k= (a-1)^{n}.
\end{equation}
When $a=1$, it reduces to
\begin{equation}\label{bin2}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}= 0,\quad n>0.
\end{equation}
If $n=0$, for any $a$ we have
\begin{equation}\label{bin3}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}a^k= 1 \ .
\end{equation}
Then, for $a=1$ and $n\in \mathbb{N}\cup \{0\}$ we have the identity
\begin{equation}\label{bin4}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}=(-1)^n \delta_{n0}=\delta_{n0}.
\end{equation}
Taking formally the derivative with respect to $a$ in \eqref{bin1} and multiplying both sides by $a$, we obtain
\begin{equation}\label{bin5}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}ka^{k}= na(a-1)^{n-1} \ .
\end{equation}
Thus, if $a=1$ we get
\begin{equation}\label{bin6}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}k = 0,\quad n> 1.
\end{equation}
Again, putting $n=1$ in formula \eqref{bin6}, the r.h.s. equals 1, therefore
\begin{equation}\label{bin7}
\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k  =(-1)^n \delta_{n1}=-\delta_{n1}.
\end{equation}
Taking the second derivative in \eqref{bin1}, we deduce the relation
\begin{equation}\label{bin8}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}k(k-1)a^{k-2}= n(n-1)(a-1)^{n-2},
\end{equation}
which can also be written as
\begin{equation}\label{bin9}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}k^2a^{k}-\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}ka^{k}= n(n-1)a^2(a-1)^{n-2}.
\end{equation}
Equivalently, we have
\begin{equation}\label{bin10}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}k^2a^{k}=na(na-1)(a-1)^{n-2}.
\end{equation}
If $a=1$, the previous formula reduces to
\begin{equation}\label{bin11}
\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}k^2=0,\quad n>2.
\end{equation}
However, if $n=1$, we have
\begin{equation}\label{bin12}
\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k^2 =(-1)^n \delta_{n1}=-\delta_{n1}
\end{equation}
and, if $n=2$
\begin{equation}\label{bin13}
\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k^2 =2(-1)^n \delta_{n2}=2\delta_{n2}.
\end{equation}
Thus, we obtain the formula
\begin{equation}\label{bin14}
\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k^2 =2\delta_{n2}-\delta_{n1}=\begin{cases}
0 ,& n=0\\
-1,& n=1\\
2,& n=2\\
0,& n>2
\end{cases} \ .
\end{equation}
In particular, for the case under study, we deduce
\begin{align}
\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}\Lambda_k =&\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k^2 +(a-1)\sum_{k=0}^{n}(-1)^{k}\binom{n}{k}k +b\sum_{k=0}^{n}(-1)^{k}\binom{n}{k} \notag \\ =&2\delta_{n2}-\delta_{n1}-(a-1)\delta_{n1}+b\delta_{n0} 
= 2\delta_{n2}-a\delta_{n1}+b\delta_{n0}.
\end{align}


