\section{\textbf{\ Preliminaries}}

\subsection{\textbf{Standard Model of Arithmetic}}

\text{ \ \ }\newline

We work in the first order language $\mathcal{L}_{\mathrm{PA}%
}=\{0,S,+,\times \}$.

\begin{definition}
Peano Arithmetic (\textbf{PA}) is defined by the following axioms over $%
\mathcal{L}_{\mathrm{PA}}$:%
\begin{equation*}
\begin{tabular}{|l|l|}
\hline
\textbf{PA1} & ($0$ is not a successor) $\displaystyle\forall x\;\bigl(%
S(x)\neq 0\bigr).$ \\ \hline
\textbf{PA2} & (Injectivity of $S$) $\displaystyle\forall x,y\;\bigl(%
S(x)=S(y)\rightarrow x=y\bigr).$ \\ \hline
\textbf{PA3} & (Addition base) $\displaystyle\forall x\;\bigl(x+0=x\bigr).$
\\ \hline
\textbf{PA4} & (Addition step) $\displaystyle\forall x,y\;\bigl(x+S(y)=S(x+y)%
\bigr).$ \\ \hline
\textbf{PA5} & (Multiplication base) $\displaystyle\forall x\;\bigl(x\times
0=0\bigr).$ \\ \hline
\textbf{PA6} & (Multiplication step) $\displaystyle\forall x,y\;\bigl(%
x\times S(y)=(x\times y)+x\bigr).$ \\ \hline
\textbf{PA7} & (Induction schema) For every formula $\varphi (x,\bar{y})$ in 
$\mathcal{L}_{\mathrm{PA}}$, \\ \hline
& $\bigl[\varphi (0,\bar{y})\wedge \forall x\bigl(\varphi (x,\bar{y}%
)\rightarrow \varphi (S(x),\bar{y})\bigr)\bigr]\;\longrightarrow \;\forall
x\,\varphi (x,\bar{y}).$ \\ \hline
\end{tabular}%
\end{equation*}
\end{definition}

\begin{definition}
A \emph{deterministic effective Turing machine} 
\begin{equation*}
\mathbf{M}_{e}=(Q,\Sigma ,\Gamma ,\delta ,q_{0},q_{\mathrm{accept}},q_{%
\mathrm{reject}}),
\end{equation*}

where

\begin{itemize}
\item $Q$ is a finite set of states.

\item $\Sigma $ is a finite input alphabet.

\item $\Gamma\supseteq\Sigma\cup\{\sqcup\}$ is the tape alphabet, with blank
symbol $\sqcup\notin\Sigma$.

\item $\delta:Q\times\Gamma\to Q\times\Gamma\times\{L,R\}$ is the transition
function, which is total and single valued (deterministic).

\item $q_0\in Q$ is the start state.

\item $q_{\mathrm{accept}}\in Q$ and $q_{\mathrm{reject}}\in Q$ are distinct
halting states. Furthermore, for all $a\in \Gamma $,%
\begin{equation*}
\delta (q_{\mathrm{accept}},a)\;=\;(q_{\mathrm{accept}},\,a,\,R),\quad
\delta (q_{\mathrm{reject}},a)\;=\;(q_{\mathrm{reject}},\,a,\,R).
\end{equation*}
\end{itemize}
\end{definition}

\subsection{\textbf{Computable Natural Numbers}}

\text{ \ \ }\newline

We fix a standard, effective enumeration $\{\mathbf{M}_{e}\}_{e\in \mathbb{N}%
}$ of all (deterministic) Turing machines. Each machine $\mathbf{M}_{e}$ on
input $x\in \mathbb{N}$ either halts with an output $\mathbf{M}_{e}(x)\in 
\mathbb{N}$ or diverges (never halts). See \cite{turing36} or \cite{rogers67}%
.

\begin{definition}
The set of \emph{computable natural numbers} is%
\begin{equation*}
\mathbb{N}_{\mathrm{comp}}\;=\;\bigl\{\,n\in \mathbb{N}\;\bigm|\;\exists
e\in \mathbb{N}\;[\,\mathbf{M}_{e}(0)\downarrow =n\,]\bigr\}.
\end{equation*}

Equivalently,%
\begin{equation*}
\mathbb{N}_{\mathrm{comp}}\;=\;\bigl\{\varphi _{e}(0)\mid e\in \mathbb{N}%
,\;\varphi _{e}(0)\downarrow \bigr\},
\end{equation*}

where $\varphi _{e}(0)\downarrow $ denotes that $\mathbf{M}_{e}$ halts on
input 0.
\end{definition}

\begin{example}[Trivial enumeration]
Define $\mathbf{M}_{n}$ to ignore its input and simply write down the
numeral on its tape, then halt. Clearly $\mathbf{M}_{n}(0)\downarrow =n$, so
every $n\in \mathbb{N}$ lies in $\mathbb{N}_{\mathrm{comp}}$.
\end{example}

\begin{example}[Halting problem defined number]
Let%
\begin{equation*}
h\;=\;\min \{\,n\mid \mathbf{M}_{n}(n)\uparrow \},
\end{equation*}

the least index of a machine that does not halt on its own code. By
construction $h$ exists in the standard model of $\mathbb{N}$, but no Turing
machine can output $h$, since that would decide the halting problem. Hence $%
h\notin \mathbb{N}_{\mathrm{comp}}$ in any constructive or
computability-theoretic sense.
\end{example}

\begin{theorem}
In the standard model of arithmetic,%
\begin{equation*}
\mathbb{N}_{\mathrm{comp}}=\mathbb{N}.
\end{equation*}
\end{theorem}

\begin{proof}
For each $n\in \mathbb{N}$, use the trivial machine $\mathbf{M}_{n}$ of
Example 3.1. It halts and outputs $n$, so $n\in \mathbb{N}_{\mathrm{comp}}$.
Conversely, by definition $\mathbb{N}_{\mathrm{comp}}\subseteq \mathbb{N}$.
\end{proof}

\begin{proposition}
$\mathbb{N}_{\mathrm{comp}}$ is closed under computable operations: if $f:%
\mathbb{N}\rightarrow \mathbb{N}$ is computed by $\mathbf{M}_{e}$, then%
\begin{equation*}
n\in \mathbb{N}_{\mathrm{comp}}\quad \Longrightarrow \quad f(n)\in \mathbb{N}%
_{\mathrm{comp}}.
\end{equation*}
\end{proposition}

\begin{proof}
Run $\mathbf{M}_{e}$ on input $n$; since both the enumeration index machine
for $n$ and $\mathbf{M}_{e}$ halt, their composition halts and outputs $f(n)$%
.
\end{proof}

\begin{remark}
While in classical computability theory $\mathbb{N}_{\mathrm{comp}}=\mathbb{N%
}$, distinctions arise in constructive frameworks, non-standard models, and
in relative computability, where one compares degrees of unsociability.
\end{remark}

\subsection{\textbf{Non-standard Models of Arithmetic}}

\text{ \ \ }\newline

Classically, the \emph{standard model} of arithmetic is $\mathbb{N}%
=(\,\{0,1,2,\dots \};0,S,+,\times )$, satisfying the Peano's axioms.
Non-standard models are those that satisfy the same first-order theory but
contain "infinite{}" or non-standard{} elements beyond the usual naturals.

\begin{definition}
The language $\mathcal{L}_{\mathrm{PA}} = \{0, S, +, \times\}$ has constant $%
0$, unary successor $S$, and binary symbols $+$, $\times$.
\end{definition}

\begin{definition}
$\mathrm{PA}$ is the $\mathcal{L}_{\mathrm{PA}}$ theory consisting of:

\begin{enumerate}
\item Axioms for $(\mathbb{N};0,S,+,\times)$ as a discretely ordered
semi ring.

\item Induction schema: for each formula $\varphi(x,\bar y)$,

\begin{equation*}
\bigl[\varphi (0,\bar{y})\wedge \forall x\,(\varphi (x,\bar{y})\rightarrow
\varphi (Sx,\bar{y}))\bigr]\;\rightarrow \;\forall x\,\varphi (x,\bar{y}).
\end{equation*}
\end{enumerate}
\end{definition}

\begin{theorem}[Compactness Construction]
There exists a model $\mathcal{M}\models\mathrm{PA}$ with an element $c$
such that $\mathcal{M}\models c > n$ for every standard numeral $n$.
\end{theorem}

\begin{proof}
Enrich the language by a new constant $c$. Add axioms $\{c>0,\;c>S0,\;c>SS0,%
\;\dots \}$. Every finite subset of these axioms is satisfiable in $\mathbb{N%
}$ by interpreting $c$ sufficiently large. By Compactness, there is a model $%
\mathcal{M}$ in which $c$ exceeds every standard natural. Restricting back
to $\mathcal{L}_{\mathrm{PA}}$ yields a non-standard model.
\end{proof}

\begin{example}[Ultra power of $\mathbb{N}$]
Let $\ \mathcal{U}$ be a non principal ultra filter on $\mathbb{N}$. Form $%
\displaystyle\mathbb{N}^{\ast }=\prod_{i\in \mathbb{N}}\mathbb{N}\big/%
\mathcal{U}$. By Compactness Construction's Theorem, $\mathbb{N}^{\ast }$ is
an elementary extension of $\mathbb{N}$ and contains classes $%
[\,(0,1,2,\dots )\,]_{\mathcal{U}}$ that dominate all constant sequences.
\end{example}

\begin{lemma}[Overspill Lemma]
Let $\mathcal{M}\models\mathrm{PA}$ be non-standard, and $X\subseteq M$ a
definable initial segment. If $X$ contains all standard naturals, then there
is a non-standard $a\in X$.
\end{lemma}

\begin{proof}
Otherwise $\lnot \exists x\,(\lnot \mathrm{st}(x)\wedge x\in X)$ is a
first-order property contradicting the fact that $\mathrm{PA}$ cannot
isolate standard from non-standard points.
\end{proof}

\begin{proposition}
Every countable Non-standard model $\mathcal{M}$ of $\mathrm{PA}$ is
recursively saturated and has proper elementary end-extensions.
\end{proposition}

\begin{proof}
Recursive saturation follows from a back and forth construction respecting
recursive types. Existence of end extensions uses Friedman's Embedding
Theorem.
\end{proof}

\begin{definition}
An extension $\mathcal{M}\preccurlyeq _{e}\mathcal{N}$ is an \emph{elementary%
} end-extension if $\mathcal{M}\preccurlyeq \mathcal{N}$ and no new element
of $\mathcal{N}$ is below any element of $\mathcal{M}$.
\end{definition}

\begin{theorem}[Keisler-Morley]
Every model of $\mathrm{PA}$ has a proper elementary end-extension.
\end{theorem}

