\begin{eqnarray*}
x_{1} &\equiv
&-t-t^{2}-2t^{3}-5t^{4}-14t^{5}-42t^{5}-132t^{7}-429t^{8}-1430t^{9}\left( 
\mathrm{mod}\text{ }t^{10}\right) \\
&&\text{or} \\
x_{2}
&=&-1+t^{2}+2t^{3}+5t^{4}+14t^{5}+42t^{5}+132t^{7}+429t^{8}+1430t^{9}\left( 
