  X_{11}=x_{11},X_{21}=x_{21}) \\ & \qquad\times\mathbb{P}_\theta(X_{32}=x_{32}\mid X_{11}=x_{11},X_{31}=x_{31}),
\end{align*}
for all $(x_{ik})_{1\leq i\leq 3,\,1\leq k\leq 2}$ in $\mathcal{X}^6$. We suppose that $\mathbb{P}_\theta(X_{11}=0,\,X_{12}=0)>0$.
% \\ Our objective is to show that our two approaches to model \textcolor{blue}{silencing} produce different results.

\paragraph{Conditioning approach}
Let us denote by $\mathbb{P}^{\text{alt,cond}}_\theta$ the law $\mathbb{P}^{\text{alt},0}_\theta$ obtained using the conditioning approach. By definition:
\begin{multline*}
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{21}=x_{21},X_{31}=x_{31},X_{22}=x_{22},X_{32}=x_{32}) \\
  =\mathbb{P}_\theta(X_{21}=x_{21},X_{31}=x_{31},X_{22}=x_{22},X_{32}=x_{32}\mid
  X_{11}=X_{12}=0) % \\ & =\mathbb{P}_\theta(X_{31}=x_{31}) \mathbb{P}_\theta(X_{32}=x_{32}\mid X_{11}=0,X_{31}=x_{31}) \\ &
  % \qquad\times\frac{\mathbb{P}_\theta(X_{21}=x_{21}) \mathbb{P}_\theta(X_{12}=0\mid
  % X_{11}=0,X_{21}=x_{21})}{\sum_{y_{21}}\mathbb{P}_\theta(X_{21}=y_{21})\mathbb{P}_\theta(X_{12}=0\mid X_{11}=0,X_{21}=y_{21})}
  % \\ & \qquad\times\mathbb{P}_\theta(X_{22}=x_{22}\mid X_{21}=x_{21}).
  % \end{aligned}
\end{multline*}
Using the independence of the random variables $X_{11}$ $X_{21}$ and $X_{31}$ we obtain after some computation
\begin{multline}
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{21}=x_{21},X_{31}=x_{31},X_{22}=x_{22},X_{32}=x_{32}) \\
    =\mathbb{P}_\theta(X_{31}=x_{31}) \mathbb{P}_\theta(X_{32}=x_{32}\mid X_{11}=0,X_{31}=x_{31}) \\
    \times \mathbb{P}_{\theta}(X_{21}=x_{21}\mid X_{11}=X_{12}=0)\mathbb{P}_\theta(X_{22}=x_{22}\mid X_{21}=x_{21}).
    \label{eq:ex-cond}
\end{multline}
We derive the following results
\begin{align}
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{31}=x_{31}) & =\mathbb{P}_\theta(X_{31}=x_{31}), \notag \\
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{32}=x_{32}\mid X_{31}=x_{31}) & =\mathbb{P}_\theta(X_{32}=x_{32}\mid X_{11}=0,X_{31}=x_{31}),
  \notag \\
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{21}=x_{21}) & =\mathbb{P}_\theta(X_{21}=x_{21}\mid X_{12}=X_{11}=0), \label{eq:ex-fin} \\
  \mathbb{P}^{\text{alt,cond}}_\theta(X_{22}=x_{22}\mid X_{21}=x_{21}) & =\mathbb{P}_\theta(X_{22}=x_{22}\mid X_{21}=x_{21}). \notag
\end{align}
In other words, the Bayesian dependency network associated with the model $\mathbb{P}^{\text{alt,cond}}_\theta$ is given by
Figure~\ref{fig:ex-reseau-cond}. This network is obtained by deleting from the network in Figure~\ref{fig:ex-reseau-bayes},  all edges originating from or directed towards one of the two vertices
$X_{11}$ and $X_{12}$. In the sequel, we call the edges \emph{incident edges to $X_{11}$ and to $X_{12}$.}

