% Note that the chosen goodness-of-fit test is neither described nor explicitely
% performed in any of the previous references: at best, a $p$-value is calculated. This is why we describe in detail below how the test
% should be performed. We will focus on statistics constructed from average gene expressions of the alt dataset.

Below we describe the goodness-of-fit test used in~\citep{Vallat2013}, which can be adapted to any quantitative model. The idea is to
test whether the number of up- and down-regulated genes correctly predicted by the model
$\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}$ is significantly greater than what would be obtained if up- and down-regulated genes
were chosen at random. We consider an alteration of gene 1 only, with parameter $\beta$.
% Let $X^\text{alt}$ be a random variable with values in $N\times K$-dimensional real matrices.

More precisely, for any positive $\epsilon$, we define a partition of gene-date pairs based on the two probabilities
$\mathbb{P}_{\hat{\theta}_P}$ and $\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}$ as follows:
\begin{align}
  \mathcal{U} & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}:\mathbb{E}_{\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}}(X_{i,k})\geq (1+\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\}, \notag \\
  \mathcal{D} & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}:\mathbb{E}_{\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}}(X_{i,k})\leq(1-\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\}, \notag \\
  \mathcal{C} & :=\Big\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: \\ & \qquad\qquad\qquad\qquad \left.(1-\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})<\mathbb{E}_{\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}}(X_{i,k})<(1+\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\}. \label{eq:def-UDC}
\end{align}
The set $\mathcal{U}$ (resp.\ $\mathcal{D}$, resp.\ $\mathcal{C}$) is the set of \emph{up-regulated} (resp. \emph{down-regulated},
\emph{constant}) gene-date pairs, i.e. those whose average expression is higher in the \emph{alt} model than in the initial model at
the date considered. The sets $\mathcal{U}$, $\mathcal{D}$ and $\mathcal{C}$ contain neither gene 1 nor the first date, because gene
expression is identical in both models at this date. % Obviously, $\mathcal{C}=\emptyset$ if $\varepsilon=0$.
Note that these sets are
constructed solely on the basis of the estimated parameter
$\hat{\theta}_P$, considered here as a constant.\\
Then, we consider  the following test statistic constructed from a \emph{alt} sample $\mathbf{X}^\text{alt}=(X^\text{alt}_1,\ldots,X^\text{alt}_{P^\text{alt}})$ of size $P^\text{alt}$:
\begin{equation}
  \label{eq:statistique-S}
  % S=\frac{\#\left\{(i,k)\in\mathcal{U}:\bar{X}^\text{BI}_{i,k}>\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})\right\}
  %   +\#\left\{(i,k)\in\mathcal{D}:\bar{X}^\text{BI}_{i,k}\leq\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k}) \right\}}{(N-1)(K-1)},
S=S(\mathbf{X}^\text{alt}):=\frac{\text{Card}(\mathcal{U}\cap\hat{\cal U}^\text{alt})+\text{Card}(\mathcal{D}\cap\hat{\cal
      D}^\text{alt})+\text{Card}(\mathcal{C}\cap\hat{\cal C}^\text{alt})}{(N-1)(K-1)},
\end{equation}
where
\begin{align*}
  \hat{\mathcal{U}}^\text{alt} & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: \bar{X}^\text{alt}_{i,k}\geq (1+\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\}, \\
  \hat{\mathcal{D}}^\text{alt} & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: \bar{X}^\text{alt}_{i,k}\leq(1-\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\}, \\
  \hat{\mathcal{C}}^\text{alt} & :=\Big\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: \\ & \qquad\qquad\qquad\qquad
                                                     \left.(1-\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})<
                                                     \bar{X}^\text{alt}_{i,k}<(1+\varepsilon)\mathbb{E}_{\mathbb{P}_{\hat{\theta}_P}}(X_{i,k})
  \right\},
\end{align*}
with
\[
\bar{X}^\text{alt}_{i,k}:=\frac{1}{P^\text{alt}}\sum_{p=1}^{P^\text{alt}} (X^\text{alt}_p)_{i,k}.
\]
The $S$ statistic counts the proportion of mean up-regulated, down-regulated or constant gene-date pairs in the \emph{alt} sample
that agree with the model.

We consider the null and alternative hypotheses
\begin{description}
\item[\textmd{(H0)}] the distribution of $X^{\text{alt}}$ is $\mathbb{P}^{\text{alt},\beta}_{\hat{\theta}_P}$,
\item[\textmd{(H1)}] the law of $S(\mathbf{X}^\text{alt})$ is $\mu_0$,
\end{description}
where $\mu_0$ is the distribution of
\[
  S':=\frac{\text{Card}(\mathcal{U}\cap{\cal U}')+\text{Card}(\mathcal{D}\cap{\cal
      D}')+\text{Card}(\mathcal{C}\cap{\cal C}')}{(N-1)(K-1)},
\]
where
\begin{align*}
  \mathcal{U}' & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: Z_{i,k}=u\right\}, \\
  \mathcal{D}' & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: Z_{i,k}=d\right\}, \\
  \mathcal{C}' & :=\left\{
    (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: Z_{i,k}=c\right\}
\end{align*}
and $\big(Z_{i,k}, (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}\big)$ is a sequence of i.i.d.\ random variable with values in
$\{u,d,c\}$ and distribution $(p_u,p_d,p_c)$ where
%Dans~\citep{Vallat2013}, les auteurs consid\`erent la loi $\mu_0$ de %$S$ que l'on obtiendrait en tirant ind\'ependamment les
%g\`enes up-r\'egul\'es, down-r\'egul\'es et constants avec des %probabilit\'es
\[
  p_u:=\frac{\text{Card}(\mathcal{U})}{(N-1)(K-1)},\quad
  p_d:=\frac{\text{Card}(\mathcal{D})}{(N-1)(K-1)},\quad p_c:=1-p_u-p_d.
\]
Note that $S'$ is obtained from $S$ by replacing $\hat{\mathcal{U}}^\text{alt}$,
$\hat{\mathcal{D}}^\text{alt}$ and $\hat{\mathcal{C}}^\text{alt}$ with ``purely'' random sets $\mathcal{U}'$, $\mathcal{D}'$ and
$\mathcal{C}'$. In particular, the random variables $\text{Card}(\mathcal{U}\cap{\cal U}')$,
$\text{Card}(\mathcal{D}\cap{\cal D}')$ and  $\text{Card}(\mathcal{C}\cap{\cal C}')$ are independent, with binomial laws of
parameters $(\text{Card}(\mathcal{U}),p_u)$, $(\text{Card}(\mathcal{D}),p_d)$ and $(\text{Card}(\mathcal{C}),p_c)$, respectively.

Hypothesis (H0) will be rejected for low values of the statistic $S$. Hence the critical region associated with the test of
significance level $\alpha$ (typically, $\alpha=5 \%$) is an interval $R=[0,u_\alpha]$, where $u_\alpha>0$ is determined by the condition
\begin{equation}
  \label{eq:region-rejet}
  \mathbb{P}_{\hat{\theta}_p}^{\text{alt},\beta}\left( S(\mathbf{X}^\text{alt})\in R\right)\leq\alpha,
\end{equation}
If $\hat{s}:=S(\mathbf{x}^\text{alt})$ is smaller than $u_\alpha$, (H0) is rejected. Otherwise, the $p$-value of the test is
$\mathbb{P}_{\hat{\theta}_p}^{\text{alt},\beta}\left( S(\mathbf{X}^\text{alt})\leq
  \hat{s}\right)$ and the power of the test is given by the type II error $\mu_0(R^c)$,
which will be small if the sample size is large enough.


