\subsection{Gaussian graphical models}
\label{sec:GGM}

% Gaussian graphical models offer no natural mechanistic interpretation.
There are many variants of these models but we will
concentrate on the simplest, for which we show below that the model of gene knock-out is explicit and its
impact on the gene regulatory network can be fully characterized. As an application, we will implement the model validation test
of Section~\ref{sec:validation}.\\
We assume that the vector $\mathbf{X}$ of gene expressions
defined by~\eqref{eq:def-X} follows a multivariate normal distribution
 $\mathcal{N}(m,\Sigma)$ where
$m=(m_{ik})_{1\leq i\leq N,1\leq k\leq K}$ is the mean and  $\Sigma=(\sigma_{ikj\ell})_{1\leq i,j\leq N,1\leq k,\ell\leq K}$ the covariance matrix that is supposed to be positive definite.
Under these conditions, $\mathbb{P}_\theta=\mathcal{N}(m,\Sigma)$ where the model parameter is $\theta=(m,\Sigma)$.  The precision
matrix is $\Sigma^{-1}$ and it is well-known (cf.\ e.g.~\citep[Eq.\,(27.6)]{Kendall1973}) that the
partial correlation matrix is given by % we define the matrix $C=(c_{ikj\ell})_{1\leq i,j\leq N,1\leq k,\ell\leq K}$ as
\[
C=- D\Sigma^{-1}D,\quad\text{where}\quad D=\text{diag}\left(\frac{1}{\sqrt{\Sigma^{-1}_{11}}},\ldots, \frac{1}{\sqrt{\Sigma^{-1}_{NN}}}\right).
\]
% It is known that $C$ is the partial correlation matrix (cf. annexe~\ref{sec:annexe}) defined as
% \[
%   c_{ikj\ell}=\text{cor}\left(X_{ik},X_{j\ell}\ \left|\ \left(X_{i'k'}\right)_{(i',k')\neq(i,k),(j,\ell)}\right.\right).
% \]
% This quantity is the correlation of the residuals in the regressions of $X_{ik}$ and $X_{j\ell}$ with respect to the other variables $(X_{i'k'})_{(i',k')\neq(i,k),(j,\ell)}$
% $(X_{i'k'})_{(i',k')\neq(i,k),(j,\ell)}$
% \textcolor{blue}{ligne trop longue} (cf. Proposition \ref{prop:precision-matrix}).
The gene network is the graph $G=(E,V)$ where the set $E$ of vertices
is made up of gene-time pairs $(i,k)$ where $1\leq i\leq N$ and $1\leq k\leq K$, and $V$  is the set of pairs $\{(i,k),(j,\ell)\}$ such that  $c_{ikj\ell}\neq 0$. In other words, gene $i$ at time $t_k$ is linked to gene $j$  at time
$t_\ell$ if and only $X_{ik}$ et $X_{j\ell}$   are not conditionally independent given all other gene expressions.
% A mechanistic interpretation of the edge is only possible when $k\not=\ell$.
% That is why it is in general not possible to define the model as mechanistic.\\

For simplicity, we consider the alteration of gene 1 of parameter $\beta\geq 0$. Since the model is
non-mechanistic, only the conditioning approach of Section~\ref{sec:cond} is relevant.
% Using the notations from Section~\ref{sec:general}, we denote the resulting law by $\mathbb{P}^\text{alt}_{(m,\Sigma)}$.
To simplify notations, we order pairs $(i,k)\in\{1,\ldots,N\}\times\{1,\ldots,K\}$ according to the lexicographic order and we
decompose by blocks the matrix $\Sigma$ and the vector $m$ as follows
\[
  \Sigma=
  \begin{pmatrix}
    \Sigma_{11} & \Sigma_{12} \\ \Sigma_{21} & \Sigma_{22}
  \end{pmatrix}\quad\text{and}\quad m=
  \begin{pmatrix}
    m_1 \\ m_2
  \end{pmatrix},
\]
where $\Sigma_{11}$ (resp.\ $\Sigma_{12}$, $\Sigma_{21}$, $\Sigma_{22}$) is a  matrix $K\times K$ (resp.\ $K\times (N-1)K$,
$(N-1)K\times K$, $(N-1)K\times (N-1)K$) and $m_1$ (resp.\ $m_2$) is a  $K$ (resp.\ $(N-1)K$)-dimensional vector.

\begin{prop}
  \label{prop:GGM}
  \begin{description}
  \item[\textmd{(i)}] The law $\mathbb{P}^{\text{alt},\beta}_{(m,\Sigma)}$ is Gaussian
    \[
      \mathbb{P}^{\text{alt},\beta}_{(m,\Sigma)}=\mathcal{N}\left(
        \begin{pmatrix}
          \beta m_1 \\ \mu(\beta)
        \end{pmatrix},
        \begin{pmatrix}
          \beta^2 \Sigma_{11} & \beta^2\Sigma_{12} \\ \beta^2\Sigma_{21} & \Gamma(\beta)
        \end{pmatrix}
      \right)
    \]
    where
    \begin{equation}
      \label{eq:def-mu}
      \mu(\beta)=m_2-(1-\beta)\Sigma_{21}\Sigma_{11}^{-1}m_1
    \end{equation}
    and
    \begin{equation}
      \label{eq:def-Gamma}
      \Gamma(\beta)=\Sigma_{22}-(1-\beta^2)\Sigma_{21}\Sigma_{11}^{-1}\Sigma_{12}.
    \end{equation}
  \item[\textmd{(ii)}] In addition, $\Gamma(0)^{-1}=(\Sigma^{-1})_{22}$.
  \end{description}
\end{prop}
\noindent Proposition~\ref{prop:GGM} will be proved in Appendix ~\ref{sec:annexe}.\\
Note that, if $\beta=0$, the \emph{alt} model is given by
\[
  \mathbb{P}^{\text{alt},0}_{(m,\Sigma)}=\mathcal{N}\left(
    \begin{pmatrix}
      0 \\ \mu(0)
    \end{pmatrix},
    \begin{pmatrix}
      0 & 0 \\ 0 & \Gamma(0).
    \end{pmatrix}
  \right)
\]
In particular, Item~(ii) means that the gene network of the knock-out model ($\beta=0$) is identical to the initial network in which
gene 1 and all incidental edges are deleted.

The previous result allows us to explicitly determine the sets of up-regulated, down-regulated and constant gene-date pairs defined
in~\eqref{eq:def-UDC} which take the form, after some algebra:
\begin{align*}
