  \right\}, \\
  \mathcal{D} & :=\left\{
                (i,k)\in\{2,\ldots,N\}\times\{2,\ldots,K\}: \varepsilon (\hat{m}_2)_{i,k}\leq(\hat{\Sigma}_{21}\hat{\Sigma}_{11}^{-1}\hat{m}_1)_{i,k}
  \right\}, \\
  \mathcal{C} & :=\left\{
