\paragraph{Description of conditional and mechanistic \emph{alt} models} ~

For simplicity, we consider the alteration of gene 1 of parameter $\beta = 0$, i.e.\ the knock-out of gene 1. From the model's
distribution~\eqref{eq:reseau-bayes}, it is straightforward to construct the alteration model using the conditioning approach of
Section~\ref{sec:cond}, denoted by $(X^\text{cond}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}.$ The arguments developed to study the
example of Section~\ref{sec:exemple} can be easily extended to show that any dynamic Bayesian network is a mechanistic model. Hence
the mechanistic approach of Section~\ref{sec:meca} can also be applied to construct a gene alteration model
$(X^\text{meca}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$ as in Section~\ref{sec:exemple}.

% We denote by $(X^\text{cond}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$, resp.\
% $(X^\text{meca}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$ the gene expression values of the \textcolor{blue}{silencing model} obtained by the conditional
% (resp. mechanistic) method.
We denote by % $G_\text{stat}=(V_\text{stat},E_\text{stat})$ the static network associated with the dynamic
% Bayesian network $G=(V,E)$ (recall that $V=\{1,\ldots,N\}\times\{1,\ldots,K\}$ and $V_\text{stat}=\{1,\ldots,N\}$). We also denote by
$G'_\text{stat}$ the graph obtained from $G_\text{stat}$ by removing vertex 1 and all edges incident to 1. We call a
\emph{connected component} of $G_\text{stat}$ \emph{upstream} of gene 1 (resp. \emph{downstream} of gene 1) a connected component $\mathcal{C}$
of $G'_\text{stat}$ such that
\[
\forall j\in \mathcal{C},\quad (1,j)\not\in E_\text{stat} \quad(\text{resp.\ }(j,1)\not\in E_\text{stat}).
\]
According to the acyclicity assumption of the Bayesian network, a connected component ${\cal C}$ of $G'_\text{stat}$ is necessarily either upstream
or downstream of gene 1, or both when there is no edge connecting gene 1 to ${\cal C}$.

\begin{prop}
  \label{prop:bayes-1}
  Let $\mathcal{C}$  be a connected component downstream of gene 1. Then
  \begin{equation}
    \label{eq:thm-bayes-1}
    (X^\textnormal{cond}_{ik})_{i\in \mathcal{C},\,1\leq k\leq K} \stackrel{(d)}{=} (X^\textnormal{meca}_{ik})_{i\in \mathcal{C},\,1\leq k\leq K}
  \end{equation}
  and these two vectors have the same law as the random vector $ (X_{ik})_{i\in \mathcal{C},\,1\leq k\leq K}$ conditionally on $(X_{1k})_{1\leq k\leq K}=0$.\\
  In addition,
  % \textcolor{blue}{ Il me semble que, dans le membre de droite, c'est $X_{ik}$ au lieu de $X^\textnormal{meca}_{ik}$ ? }
  %  and
   $(X^\textnormal{cond}_{ik})_{i\in \mathcal{C},\,1\leq k\leq K}$ is independent of
  $(X^\textnormal{cond}_{ik})_{i\in \{2,\ldots,N\}\setminus\mathcal{C},\,1\leq k\leq K}$.
  An identical result holds true for  $X^\textnormal{meca}$.
\end{prop}

\begin{prop}
  \label{prop:bayes-2}
  Let $\mathcal{C}$  be a connected component upstream of gene 1. Then
  \begin{equation}
    \label{eq:bayes-2}
    (X^\textnormal{meca}_{ik})_{i\in \mathcal{C},\,1\leq k\leq K} \stackrel{(d)}{=} (X_{ik})_{i\in \mathcal{C},\,1\leq k\leq K}
  \end{equation}
   and $(X^\textnormal{meca}_{ik})_{i\in \mathcal{C},\,1\leq k\leq K}$ is independent of
  $(X^\textnormal{meca}_{ik})_{i\in \{2,\ldots,N\}\setminus\mathcal{C},\,1\leq k\leq K}$.
\end{prop}

\noindent
The proof of these results is given in Appendix~\ref{sec:bayes-annexe}. % These results assume \textcolor{blue}{total silencing of gene 1. We could extend
% them to the case of partial silencing} of gene 1, but the results would be weaker: \eqref{eq:thm-bayes-1}
% and~\eqref{eq:bayes-2} would remain true but the independence properties would fail. We leave the details to the interested reader.


We have already given in Section~\ref{sec:exemple} an example where the law of genes in a connected component upstream of gene 1 is
not the same in the conditional and the mechanistic approaches. In particular, the conditional model does not satisfy the
relationship~\eqref{eq:bayes-2} in general. Similarly, the independence property of Proposition \ref{prop:bayes-2} is not true in
general for the conditional model,, as the following example shows.

We consider the gene expression model with $N=3$ and $K=2$ where $X_{11}$, $X_{21}$, $X_{22}$,
$X_{31}$ and $X_{32}$ are i.i.d. with Bernoulli distribution with parameter $1/2$ and
\[
  X_{12}=|X_{21}-X_{31}|.
\]
It is easy to verify that this model is a dynamic Bayesian network, the static network of which is shown in
Figure~\ref{fig:exemple-2}.

