\paragraph{Improved estimation of initial model parameters using \emph{alt} data} ~

% The implementation of the validation test described in Section~\ref{sec:validation} does not pose any difficulty in the case of the Bayesian network models considered here.
% Details are left to the reader.\\
Bayesian networks are usually inferred by \emph{a posteriori} likelihood maximization on graphs. Let us recall the method. Let
$(\mathbb{Q}(G),\, G\in \mathcal{G})$ be an \emph{a priori} distribution over all oriented acyclic graphs and a dataset
$\mathbf{x}\in D^{NKP}$ as in~\eqref{eq:def-dataset-initial}. We maximise the \emph{a posteriori} log-likelihood with respect to
$(G,p^G)$:
\[
  \mathcal{L}(G,p^G\mid \mathbf{x}):=\log  \mathbb{P}_{(G,p^G)}(\mathbf{X}=\mathbf{x})+\log \mathbb{Q}(G).
\]
Classical choices for the \emph{a priori} distribution $\mathbb{Q}$ are those leading to an AIC or BIC type penalty in order to
select
networks with few edges \citep{Filkov2005}.\\
% This maximization is an NP-hard problem when all possible graphs are considered. It can be made easier, for example, by limiting the
% number of parents for each node, or by using heuristic \textit{hill-climbing} with random initialization \citep{Hartemink2000,Yu2002}.
% However, a large amount of data is required to make such an inference.\\
If an \emph{alt} dataset $\mathbf{x}^\text{alt}$ corresponding to a total silencing experiment of gene 1 is available, the method of
improvement of the parameter estimation of the initial model proposed in Section~\ref{sec:affinage} can be applied. Using the
previous notations and~\eqref{eq:amelioration-estimation}, the new \emph{a posteriori} log-likelihood to be maximized is expressed as
\[
  \mathcal{L}^\text{cond}(G,p^G\mid \mathbf{x},\mathbf{x}^\text{alt}):=\mathcal{L}(G,p^G\mid \mathbf{x})+
  % \log \mathbb{P}_{(G,p^G)}(\mathbf{X}=\mathbf{x})+
  \log\mathbb{P}^\text{alt}_{(G,p^G)}(\mathbf{X}^\text{cond}=\mathbf{x}^\text{alt})
  % +\log \mathbb{Q}(G).
\]
for the conditional model and
\[
  \mathcal{L}^\text{meca}(G,p^G\mid \mathbf{x},\mathbf{x}^\text{alt}):=\mathcal{L}(G,p^G\mid \mathbf{x})+
  % \log \mathbb{P}_{(G,p^G)}(\mathbf{X}=\mathbf{x})+
  \log\mathbb{P}^\text{alt}_{(G,p^G)}(\mathbf{X}^\text{meca}=\mathbf{x}^\text{alt}). % +\log \mathbb{Q}(G).
\]
for the mechanistic model.


\subsubsection{Penalized linear regression}
\label{sec:lasso}

We consider the linear, mechanistic, Gaussian model with delay (called LiRE model in~\citep{Rodolphe2025}), which generalizes the one
introduced in~\citep{Schleiss2021}. This model can be seen either as the discretization of a model based on differential equations or as
a regression model.

% \textcolor{blue}{faut-il indiquer :\\
% 1) qu'on peut voir soit comme la discr\'etisation d'un
% mod\`ele bas\'e sur des \'equations diff\'erentielles, soit comme un mod\`ele de r\'egression. \\
% 2)
% (Lin\'eaires \`a Retard Echelonn\'e), qui n'a plus de sens en anglais?}



\paragraph{Definition of the LiRE model} ~

In this model, gene expressions satisfy the following inductive relationships:
\begin{align}
X_{ik} &:= \mu_{ik} +
\sum_{j=1}^{N}  \sum_{\ell=1}^{k-1}
a_{\ell} \omega_{ij} X_{j (k-\ell)}+G_{ik}
\label{Eq:Probabilistic_model_one_time}
\end{align}
for all gene $i\in\{1,\ldots,N\}$ and time $k\in\{1,\ldots,K\}$, where $\mu_{ik}$ is the average expression of gene $i$ at time $k$,
in the absence of influence from other genes, $\omega_{ij}$ is the intrinsic (time-independent) force exerted by gene $j$
on the expression of gene $i$, $a_\ell$ is a (gene independent) coefficient that only depends on time differences and $G_{ik}$ stands for the noise.\\
The coefficients $a_\ell$ are assumed to be nonnegative, but $\omega_{ij}$ can be positive (resp.\ negative) if gene $j$ activates
(resp.\ inhibits) gene $i$ and null if gene $j$ has no influence on gene $i$. The term $a_\ell \omega_{ij}$ is the contribution made
by gene $j$ at time $k-\ell$ to the expression of gene $i$ at time $k$. This particular form dissociates the effects of time from
inter-gene effects. It is justified by the fact that the measurement dates $t_1,\ldots,t_K$ are regularly spaced. Replacing the
vector $(a_\ell)_\ell$ by a matrix of parameters depending both on the delay $\ell$ and the measurement time $k$ allows to consider
the case where the times of measurement are not regularly distributed~\citep{Schleiss2021}.

The associated gene network is the directed graph in which an edge points from $j$ to $i$ if and only $\omega_{ij}\neq 0$. Finally,
the random variables $(G_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$ are assumed to be Gaussian centered independent, and the variance
$\sigma^2_i$ of $G_{ik}$ does not depend on $k$. In particular, the initial expressions
$(X_{i1})_{1\leq i\leq N}=(\mu_{i1}+G_{i1})_{1\leq i\leq N}$ of the genes are independent. We set:
\[
\Sigma:=
  \begin{pmatrix}
    \sigma_1^2 & \hdots & 0 \\
    \vdots & \ddots & \vdots \\
    0 & \hdots & \sigma_N^2
  \end{pmatrix}
\]
and
\[
\Lambda := \operatorname{diag}( \underbrace{
\Sigma, \cdots,\Sigma
}_{K \mbox{ times}}).
\]
In order for the model to be identifiable, we assume that $\sum_{\ell=1}^{K-1}a_\ell=1$.
The parameter space of the model is then
$\Theta= \mathbb{R}^{NK} \times {\cal S}_{K-2} \times \left( \mathbb{R}^{N^2} \setminus \{0\} \right) \times
\left(\mathbb{R}_{+}^{\star}\right)^{N}$, where ${\cal S}_d$ is the simplex of dimension $d$, and
\[
  \theta= \left( (\mu_{ik})_{1\leq i\leq N,\, 1\leq
      k\leq K}, (a_\ell)_{1\leq \ell\leq K-1}, (\omega_{ij})_{1\leq i,j\leq N}, (\sigma_{i})_{1\leq i\leq N} \right).
\]
is an element of $\Theta$.\\
Recall that $\mathbb{P}_\theta$ represents the distribution of $\mathbf{X}=(X_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$
 when the parameter is $\theta\in\Theta$.
In the following, we adopt the vector representation
\[
  \mathbf{X}=(X_{1,1}, \ldots, X_{N,1}, \ldots, X_{1,K}, \ldots, X_{N,K}).
\]
We also define
\[
  \mu=(\mu_{1,1}, \ldots, \mu_{N,1}, \ldots, \mu_{1,K}, \ldots, \mu_{N,K})
\]
and $H$ the matrix defined by blocks as follows
\[
H:=
   \begin{pmatrix}
   I & 0 & \hdots & 0 & 0 \\
   -a_1 \Omega & I & \hdots & 0 & 0 \\
   \vdots & \vdots & \ddots & \vdots & \vdots \\
   -a_{T-2} \Omega & -a_{T-3} \Omega & \hdots & I  & 0\\
   -a_{T-1} \Omega & -a_{T-2} \Omega & \hdots  & -a_1 \Omega & I
   \end{pmatrix},
\]
where $I$ denotes the $N\times N$ identity matrix and $\Omega=(\omega_{ij})_{1\leq i,j\leq N}$. The following result
characterizes the probability measure $\mathbb{P}_\theta$.

\begin{thm} \label{Th:Vecteurs_gaussiens_E_X}
 For any $\theta\in\Theta$, $\mathbb{P}_{\theta}$ is  the multivariate Gaussian distribution
\begin{align}
  \mathbb{P}_{\theta}
  = \mathcal{N}(\Upsilon,
  \Gamma) \ , \label{Eq:X_gaussien}
\end{align}
where
\begin{equation}
  \label{eq:Upsilon-Gamma}
  \Upsilon
  :=H^{-1} \mu\quad\text{et}\quad
  \Gamma:=H^{-1} \Lambda
  \left(H^{-1}\right)^{\top}.
\end{equation}
\end{thm}


\paragraph{Mechanistic model of gene alteration} ~

% {\color{magenta} changer tous les $\beta$ en $1-\beta$}

Consider the alteration of gene 1 with parameter $\beta$. The LiRE model is mechanistic, so we can apply the method
defined in Section~\ref{sec:meca}. Let $(X^\text{meca}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$ be the model obtained:
\begin{align}
  X_{ik}^\text{meca}
  = \mu_{ik} + \beta \sum_{\ell=1}^{k-1}
  a_\ell \omega_{i1}
  X_{1,k-\ell}^\text{meca}
  +\sum_{j=2}^{N}  \sum_{\ell=1}^{k-1}
  a_\ell \omega_{ij}
  X_{j,k-\ell}^\text{meca}
  + G_{ik}  \label{Eq:x_meca_ARN_transcript}
\end{align}
for any $i \in \{1,\ldots,N\}$ and $k\in \{1,\ldots,K\}$.\\
We recognize a LiRE model where the matrix $\Omega$  has been replaced by $\Omega D_\beta$, where  $D_\beta$ is the $NK\times NK$ matrix defined by
\begin{align}
D_\beta = \operatorname{diag}(v)
% \underbrace{ v, \ldots ,v}_{K \mbox{ fois}}
  , \label{Eq:D_alpha_t}
\end{align}
and $v= (\beta,1,\ldots,1)\in\mathbb{R}^N$. Other parameters $\mu$, $a$ and $\sigma$ remain unchanged. Hence, we deduce from
\eqref{Eq:x_meca_ARN_transcript} that the law $\mathbb{P}^\text{alt,$\beta$,meca}_\theta$ of the mechanistic model of alteration of
gene 1 with parameter $\beta$ is
\begin{equation}
  \label{eq:modele-LiRE-meca}
  \mathbb{P}^\text{alt,$\beta$,meca}_\theta
  =\mathbb{P}_{( a,\Omega D_\beta, \mu,\sigma)}.
\end{equation}
Relation \eqref{eq:modele-LiRE-meca} implies that the gene network associated with the mechanistic alteration model is the same as in
the initial model, except when $\beta=0$ (gene knock-out). In this case, all edges starting from gene 1 are deleted.



\paragraph{Conditional model of gene alteration} ~

It is convenient to operate with a vector $W=(W^{(1)},W^{(2)})$ whose coordinates are those of $\mathbf{X}$ permuted:
\[
  W^{(1)}=(X_{11},\ldots,X_{1K})\quad\text{et}\quad W^{(2)}=(X_{21},\ldots,X_{2K},X_{31},\ldots,X_{NK}).
\]
Alteration concerns only the $W^{(1)}$ component.\\
 According to Theorem~\ref{Th:Vecteurs_gaussiens_E_X},
\[W \sim \mathcal{N}
\left(
\Upsilon_W,\Gamma_W
\right),\]
where
\[
\Upsilon_W=\left(\Upsilon^{(1)}_{W},\Upsilon^{(2)}_{W}\right) \quad\mbox{and}\quad
\Gamma_W=\left[\begin{array}{cc}
   \Gamma_W^{(11)} & \Gamma_W^{(12)} \\
   \Gamma_W^{(21)} & \Gamma_W^{(22)}
\end{array}\right]
\]
are obtained by permuting the rows and columns of $\Upsilon$ et $\Gamma$, $\Upsilon_W^{(1)}\in\mathbb{R}^K$,
$\Upsilon_W^{(2)}\in\mathbb{R}^{(N-1)K}$ and $\Gamma_W^{(11)}$ (resp.\  $\Gamma_W^{(12)}$, $\Gamma_W^{(21)}$ and $\Gamma_W^{(22)}$)
is a $K\times K$  (resp.\ $K\times
(N-1)K$, $(N-1)K\times K$ and $(N-1)K\times (N-1)K$) matrix.\\
Let us denote by
\[
{W}^{\text{cond}}
:= \left( {W}^{\text{cond},1},
{W}^{\text{cond},2} \right)
\]
The random vector obtained in the alteration of gene 1 with parameter $\beta$ using the conditional model of
Section~\ref{sec:cond}.%  Set
