%   $\sigma_1>0$. We deduce, by recurrence on $k$ that $(X_{11},\ldots,X_{1k})$  has a density with respect to the Lebesgue measure.
% \end{rem}

\begin{thm}
  \label{Th:Silencing_conditionnal}
   Let $\mathbb{P}^{\text{alt},\beta,\text{cond}}_\theta$ denote the law of  $W^{\text{cond}}$, then
  \[
    \mathbb{P}^{\text{alt},\beta,\text{cond}}_{\theta}
    = \mathcal{N}\left(
      \Upsilon_{W}^{\text{cond}},
      \Gamma_{W}^{\text{cond}}
    \right)
  \]
  where
  \begin{equation}
    \label{eq:Upsilon-cond}
    \Upsilon_{W}^{\text{cond}}=\left(\beta \Upsilon^{(1)}_{W}\, ,\, \Upsilon_{W}^{(2)} -(1-\beta) \Gamma^{(21)}_W
      \left(\Gamma^{(11)}_W\right)^{-1} \Upsilon^{(1)}_{W}\right)
  \end{equation}
  and
  \begin{equation}
    \label{eq:Gamma-cond}
    \Gamma_{W}^{\text{cond}}=
    \begin{pmatrix}
      \beta^2 \Gamma^{(11)}_W & \beta^2 \Gamma^{(12)}_W \\
      \beta^2 \Gamma^{(21)}_W & \Gamma_W^{(22)}-(1-\beta^2)\Gamma^{(21)}_W\left(\Gamma^{(11)}_W\right)^{-1}\Gamma^{(12)}_W
    \end{pmatrix}.
  \end{equation}
\end{thm}
We recover a similar expression as in Proposition~\ref{prop:GGM}.
This result is proven in the more general context of simultaneous alteration of several genes in~\citep{Rodolphe2025}.
