\paragraph{Improved estimation of initial model parameters using \emph{alt} data} ~


The method proposed in~\citep{Rodolphe2025} for
estimating the parameters of the LiRE model is based on a posteriori likelihood maximization with the prior
density:

\begin{align}
\pi(\theta) =
\prod_{i=1}^{N} \left(\left(\frac{\tau_i}{2\sigma_i^2}\right)^N
\exp \left(-
\frac{\tau_i}{\sigma_i^2}\sum_{j=1}^N|\omega_{ij}|
\right)\right),
\end{align}
where $\tau=(\tau_1,\cdots,\tau_N) \in \left(\mathbb{R}^{\star}_{+}\right)^{N}$ is a parameter defined by the user.
In other words, conditionally on $\sigma$, the $\omega_{ij}$ follow independent Laplace laws. A flat a priori is assumed for the other parameters $\mu$, $a$ and $\sigma$.\\
Therefore, denoting by $f_\theta$ the density of the distribution of $\mathbf{X}$ under $\mathbb{P}_\theta$, inference of the parameter $\theta$
is performed by maximizing the a posteriori log-likelihood of observations $\mathbf{x}$.
\begin{align}
  & \mathcal{L}(\theta\mid \mathbf{x}) =\sum_{p=1}^{P}\log f_\theta\big((x_{i,k,p})_{1\leq i\leq N,\,1\leq k\leq
    K}\big)+\log\pi(\theta) \label{eq:vrais-LiRE} \\
                                     &= - \frac{1}{2}
\sum_{i=1}^{N} \frac{1}{\sigma_i^{2}} \left(
\sum_{k=1}^K\sum_{p=1}^{P}\left(x_{i,k,p} - \mu_{ik}-
\sum_{j=1}^{N}\sum_{\ell=1}^{k-1}a_\ell \omega_{ij} x_{j,k-\ell,p}\right)^{2}
+ 2\tau_i \sum_{j=1}^N|\omega_{ij}|
\right) \notag \\
&  \phantom{=}- \left(\frac{PK+2N}{2}\right) \sum_{i=1}^{N} \ln \sigma_i^2
+ N\sum_{i=1}^{N} \ln\frac{\tau_i}{2}. \notag
\end{align}
The maximization algorithm of $\mathcal{L}(\theta\mid\mathbf{x})$ used in~\citep{Rodolphe2025} consists in successively optimizing
on the 4 parameters $\mu$, $\sigma$, $a$ and $\Omega$ while fixing the others. Optimization in $\mu$ and $\sigma$ is explicit, that
in $a$ can be expressed as a least-squares problem with a positivity constraint and that in $\Omega$ can be reduced to $N$ lasso
problems~\citep{Tibshirani1996}, each involving a vector of the form $(\omega_{i1},\ldots,\omega_{iN})$.
%
The choice of the parameters $\tau_i$ can be made by cross-validation.


% Since the laws of the two alt models above are Gaussian and explicit, the validation test described in Section~\ref{sec:validation} can
% be carried out in the same way as for Gaussian graphical models (see Section~\ref{sec:GGM}). In the sequel, we focus on the problem of
% improvement of estimation from a alt dataset:
If we are given an additional dataset $\mathbf{x}^\text{alt}$ of size $P^\text{alt}$ from an alteration experiment of gene 1 with
parameter $\beta$, we can apply the method in Section~\ref{sec:affinage}. Let $f_\theta^{\text{alt,}\beta\text{,meca}}$ stand for the
density of $\mathbf{X}$ under $\mathbb{P}^\text{alt,$\beta$,meca}_\theta$. Using~\eqref{eq:vrais-LiRE}, the new a posteriori
log-likelihood is expressed in the case of the mechanistic approach as
\begin{multline*}
  \mathcal{L}^\text{meca}(\theta\mid \mathbf{x},\mathbf{x}^\text{alt})=\sum_{p=1}^P\log f_\theta\big((x_{i,k,p})_{1\leq i\leq N,\,1\leq k\leq K}\big)
  \\ +\sum_{p=1}^{P^\text{alt}}\log f_\theta^{\text{alt,}\beta\text{,meca}}\left((x^\text{alt}_{i,k,p})_{1\leq i\leq N,\,1\leq k\leq K}\right)+\log\pi(\theta).
\end{multline*}
Using~\eqref{eq:modele-LiRE-meca} and Theorem~\ref{Th:Vecteurs_gaussiens_E_X}, we obtain
\begin{align*}
  & \mathcal{L}^\text{meca}(\theta\mid \mathbf{x},\mathbf{x}^\text{alt}) = - \frac{1}{2}
\sum_{i=1}^{N} \frac{1}{\sigma_i^{2}} \left(
\sum_{k=1}^K\sum_{p=1}^{P}\left(x_{i,k,p} - \mu_{ik}-
    \sum_{j=1}^{N}\sum_{\ell=1}^{k-1}a_\ell \omega_{ij} x_{j,k-\ell,p}\right)^{2} \right. \\
  & +\sum_{k=1}^K\sum_{p=1}^{P^\text{alt}}\left(x^\text{alt}_{i,k,p} - \mu_{ik}-\beta\sum_{\ell=1}^{k-1}a_\ell \omega_{i1} x^\text{alt}_{1,k-\ell,p}-
    \sum_{j=2}^{N}\sum_{\ell=1}^{k-1}a_\ell \omega_{ij} x^\text{alt}_{j,k-\ell,p}\right)^{2} \\
  & \left. + 2\tau_i \sum_{j=1}^N|\omega_{ij}|\right)- \left(\frac{PK+P^\text{alt}K+2N}{2}\right) \sum_{i=1}^{N} \ln \sigma_i^2
    + N\sum_{i=1}^{N} \ln\frac{\tau_i}{2}.
\end{align*}
% \textcolor{blue}{Je pense que la formule n'est pas exacte, \`a rediscuter}


Maximization of this log-likelihood can be achieved using the same iterative method as for inference: explicit optimization in $\mu$ and $\sigma$, optimization in $a$ by least squares with a positivity
constraint and optimization in $\Omega$ by \emph{lasso}.

In the case of the conditional approach, % let $f_\theta^{\text{BI,}\beta\text{,cond}}$  be the density of $\mathbf{X}$ under
% $\mathbb{Q}^\text{BI,$\beta$,cond}_\theta$.
% The aim is to maximize
the log-likelihood
% \begin{multline*}
%   \mathcal{L}^\text{cond}(\theta\mid \mathbf{x},\mathbf{x}^\text{BI})=\sum_{p=1}^P\log f_\theta\big((x_{i,k,p})_{1\leq i\leq N,\,1\leq k\leq K}\big)
%   \\ +\sum_{p=1}^{P^\text{BI}}\log f_\theta^{\text{BI,}\beta\text{,cond}}\left((x^\text{BI}_{i,k,p})_{1\leq i\leq N,\,1\leq k\leq K}\right)+\log\pi(\theta).
% \end{multline*}
% \textcolor{blue}{ Il faut remplacer $G$ par $\theta$ dans le membre de droite ?}
can be computed explicitely according to Theorem~\ref{Th:Silencing_conditionnal}, but its expression lacks the structure that allows successive
optimization in each parameter as above. Hence likelihood maximization is difficult for this model.


