\section{Conditional laws of Gaussian vectors and proof of Proposition~\ref{prop:GGM}}
\label{sec:annexe}
\label{sec:preuve-GGM}

Let $m$ and $d$ denote integers such that $1\leq m< d$. We consider a Gaussian vector $Y\in\mathbb{R}^d$ with mean $\mu$ and
covariance matrix $\Gamma$. Write $Y=(Y_1,Y_2)$ where $Y_1\in\mathbb{R}^m$ is the vector of the first $m$ coordinates of $Y$ and
$Y_2\in\mathbb{R}^{d-m}$ is the vector of the last $d-m$ coordinates. In a similar way, we decompose the vector $\mu$ and the matrix
$\Gamma$:
\begin{equation}
  \label{eq:decomp-Gamma}
  \mu=(\mu_{1},\mu_{2}) \quad \text{et}\quad
  \Gamma=
  \begin{pmatrix}
    \Gamma_{11} & \Gamma_{12} \\ \Gamma_{21} & \Gamma_{22},
  \end{pmatrix}
\end{equation}
where $\mu_1\in\mathbb{R}^m$, $\mu_2\in\mathbb{R}^{d-m}$, $\Gamma_{11}$ (resp.\ $\Gamma_{12}$, $\Gamma_{21}$, $\Gamma_{22}$) is a
$m\times m$ (resp.\ $m\times(d-m)$, $(d-m)\times m$, $(d-m)\times(d-m)$) matrix. The following result describes the conditional
distribution of $Y_1$ given $Y_2$~\citep[Prop.\,3.13]{Eaton1983}.

\begin{thm}
  \label{thm:conditional_Gaussian} If $\Gamma$ is invertible, then for any $y_2\in\mathbb{R}^{d-m}$,
  \[
    \textnormal{Law} (Y_1 \mid Y_2=y_2)
    =\mathcal{N}_m(\mu_{1|2}(y_2) , \Gamma_{1|2} ),
  \]
  where
  \begin{align*}
    \mu_{1|2}(y_2) & = \mu_{1} + \Gamma_{12} \Gamma_{22}^{-1}(y_2-\mu_2) \\
    \Gamma_{1|2} & =\Gamma_{11}-\Gamma_{12} \Gamma_{22}^{-1}\Gamma_{21}.
  \end{align*}
\end{thm}
The case $\beta=0$ in Point~(i) of Proposition~\ref{prop:GGM} is an immediate consequence of the last formula
(exchanging the role of $Y_1$ and $Y_2$). We leave to the reader the general case.

The proof of Theorem~\ref{thm:conditional_Gaussian} is based on the calculation of the precision matrix $\Gamma^{-1}$ given by the
following proposition.

\begin{prop}
  \label{prop:precision-matrix} If $\Gamma$ is invertible, then
  \[
    \Gamma^{-1} =
    \begin{pmatrix}
      \Gamma_{1|2}^{-1} & -\Gamma_{1|2}^{-1} \Gamma_{12}\Gamma_{22}^{-1} \\
      - \Gamma_{22}^{-1} \Gamma_{21} \Gamma_{1|2}^{-1} & \Gamma_{22}^{-1}+
      \Gamma_{22}^{-1} \Gamma_{21}\Gamma_{1|2}^{-1} \Gamma_{12} \Gamma_{22}^{-1}
    \end{pmatrix}
  \]
  where $\Gamma_{2|1} =\Gamma_{22}-\Gamma_{21} \Gamma_{11}^{-1}\Gamma_{12}$.
\end{prop}

Writing as in~\eqref{eq:decomp-Gamma}
\[
  \Gamma^{-1}=
\begin{pmatrix}
  (\Gamma^{-1})_{11} & (\Gamma^{-1})_{12} \\ (\Gamma^{-1})_{21} & (\Gamma^{-1})_{22}
\end{pmatrix},
\]
we deduce from Proposition \ref{prop:precision-matrix} that $(\Gamma^{-1})_{11}=\Gamma_{1|2}^{-1}$, hence Point~(ii)
of Proposition~\ref{prop:GGM} follows.


\section{Proof Propositions~\ref{prop:bayes-1} and ~\ref{prop:bayes-2} }
\label{sec:bayes-annexe}

We consider only the case of a dynamic Bayesian model with discrete values (as usual for gene networks). A similar proof can be done
in the case where gene expressions are continuous variables.

\subsection{Proof of Proposition~\ref{prop:bayes-1}}
\label{sec:proof-prop-bayes-1}

Throughout, $\mathcal{C}$ denotes a connected component of $G_\text{stat}$ downstream of gene 1.
\medskip

\noindent\textit{Step 1. Study of the conditional model}

As defined by the Bayesian model
\begin{align*}
  \mathbb{P} & \left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} ,\ (X_{1k})_{1\leq k\leq
      K}=(x_{1k})_{1\leq k\leq K},\right. \\ & \left. \qquad\qquad\qquad\qquad\qquad(X_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq
      K}=(x_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq K}\right) \\
 & =\mathbb{P}\left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} \mid (X_{1k})_{1\leq k\leq
      K}=(x_{1k})_{1\leq k\leq K}\right) \\ & \times \mathbb{P}\left((X_{1k})_{1\leq k\leq
      K}=(x_{1k})_{1\leq k\leq K},\ (X_{jk})_{j\not\in\mathcal{C}\cup\{1\}),\, 1\leq k\leq
      K}=(x_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq K}\right)
\end{align*}
for all $(x_{1k})_{1\leq k\leq K}$, $(x_{ik})_{i\in\mathcal{C},\,
  1\leq k\leq K}$ and $(x_{jk})_{j\not\in\mathcal{C}\cup\{1\},\,
  1\leq k\leq K}$.
  Recall that the law of the conditional model $(X^\text{cond}_{ik})_{1\leq i\leq N,\,1\leq k\leq K}$ is the conditional law of $(X_{ik})_{2\leq i\leq N,\,1\leq k\leq K}$ given $(X_{1k})_{1\leq k\leq K}=0$.
  From the previous formula, we deduce that
  \begin{multline*}
  \mathbb{P} \left((X^\text{cond}_{ik})_{2\leq i\leq N,\, 1\leq k\leq K} =(x_{ik})_{2\leq i\leq N,\, 1\leq k\leq K}\right) \\
  \begin{aligned}
    & =\mathbb{P}\left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} \mid (X_{1k})_{1\leq k\leq
      K}=0\right) \\ & \times \mathbb{P}\left((X_{jk})_{j\not\in\mathcal{C}\cup\{1\}),\, 1\leq k\leq
      K}=(x_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq K}\mid (X_{1k})_{1\leq k\leq
      K}=0\right).
  \end{aligned}
  \end{multline*}
Hence $(X^\text{cond}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K}$ is independent of  $(X^\text{cond}_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq
  K}$ and
\begin{multline*}
  \mathbb{P}\left((X^\text{cond}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K}\right) \\
  =\mathbb{P}\left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} \mid (X_{1k})_{1\leq k\leq
      K}=0\right).
\end{multline*}
\medskip
\noindent\textit{Step 2. Study of the mechanistic model}

It is easy to show, as we did in Section~\ref{sec:exemple}, that the dynamic Bayesian model
model described in Section~\ref{sec:bayes} can be written as a mechanistic model of the form
\[
  X_{i,k+1}=F_{i,k}\big((X_{\ell,k})_{\ell\in A(i)};\,U_{i,k}\big),
\]
for all $i\in\{1,\ldots, N\}$ and $k\in\{1,\ldots, K-1\}$, where $F_{i,k}((x_{\ell,k})_{\ell\in A(i)};\cdot)$
is the generalized inverse distribution function
of the conditional law of $X_{i,k+1}$ given $(X_{\ell,k})_{\ell\in A(i)}=(x_{\ell,k})_{\ell\in A(i)}$ and
 the variables $U_{i,k}$ are i.i.d. uniform on $[0,1]$. We deduce that the mechanistic model for total silencing of gene 1 is given by
\begin{align}
  X^\text{meca}_{1,k+1} & =0, \notag \\
  X^\text{meca}_{i,1} & =X_{i1}, \label{eq:CI-bayes} \\
  X^\text{meca}_{i,k+1} & =\hat{F}_{i,k}\big((X^\text{meca}_{\ell,k})_{\ell\in A(i)\setminus\{1\}};\,U_{i,k}\big), \label{eq:rec-meca-sil}
\end{align}
for all  $i\in\{2,\ldots, N\}$ and $k\in\{1,\ldots, K-1\}$, where
\begin{equation}
  \label{eq:def-hat-F}
  \hat{F}_{i,k}\big((x_{\ell,k})_{\ell\in A(i)\setminus\{1\}};u_{ik}\big)=
  \begin{cases}
    F_{i,k}\big(0,(x_{\ell,k})_{\ell\in A(i)\setminus\{1\}};u_{ik}\big)
    & \text{if } 1\in A(i)\\
    F_{i,k}\big((x_{\ell,k})_{\ell\in A(i)};u_{ik}\big) & \text{if } 1\not\in A(i).
  \end{cases}
\end{equation}
%
