%  Let $\mathcal{C}$ be a connected component of $G_\text{stat}$ downstream  gene 1.\\
%   car cette information a été donnée au début de la preuve.}
Since $A(i)\cap\mathcal{C}=\emptyset$ for all  $i\not\in\mathcal{C}\cup\{1\}$, the relations
\begin{equation}
  \label{eq:preuve-bayes}
  X^\text{meca}_{i,k+1} =\hat{F}_{i,k}\big((X^\text{meca}_{\ell,k})_{\ell\in A(i)\setminus\{1\}};\,U_{i,k}\big)
\end{equation}
satisfied for any $i\not\in\mathcal{C}\cup\{1\}$ and $1\leq k\leq K-1$
imply
\begin{equation}
  \label{eq:indep-1}
\sigma\left((X^\text{meca}_{ik})_{i\not\in\mathcal{C}\cup\{1\},\,1\leq k\leq K}\right)\subset
\sigma\left((X_{i1})_{i\not\in\mathcal{C}\cup\{1\}},
(U_{ik})_{i\not\in\mathcal{C}\cup\{1\},\,1\leq k\leq
  K-1}
\right)
\end{equation}
where $\sigma\big((Z_j)_{j\in J}\big)$ stands for the $\sigma$-algebra generated of the random variables $(Z_j)_{j\in J}$.

 Similarly, since for all $i\in\mathcal{C}$ we have  $A(i)\subset \mathcal{C}\cup\{1\}$ the relations~\eqref{eq:preuve-bayes} with
 $i\in\mathcal{C}$, $ 1\leq k\leq K-1$ imply
\begin{equation}
  \label{eq:indep-2}
\sigma\left((X^\text{meca}_{ik})_{i\in\mathcal{C},\,1\leq k\leq K}\right)\subset
\sigma\left((X_{i1})_{i\in\mathcal{C}},
(U_{ik})_{i\in\mathcal{C},\,1\leq k\leq
  K-1}
\right).
\end{equation}
Since the families of random variables $(U_{ik})_{1\leq i\leq N, 1\leq k\leq K}$, $(X_{i1})_{i\in\mathcal{C}}$ and

\noindent
$(X_{i1})_{i\not\in\mathcal{C}\cup\{1\}}$ are independent, we deduce that $(X^\text{meca}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K}$ is independent of
$(X^\text{meca}_{jk})_{j\not\in\mathcal{C}\cup\{1\},\, 1\leq k\leq K}$.
\medskip

\noindent\textit{Step 3. Conclusion}
To complete the proof of Proposition~\ref{prop:bayes-1}
it remains to show that
\begin{multline*}
  \mathbb{P}\left((X^\text{meca}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K}\right) \\
  =\mathbb{P}\left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq K} \mid (X_{1k})_{1\leq k\leq
      K}=0\right).
\end{multline*}
We will establish this identity by showing by induction on $\ell$ belonging to $\{1,\ldots,K\}$
\begin{multline}
  \mathbb{P}\left((X^\text{meca}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell}\right) \\
  =\mathbb{P}\left((X_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell} \mid (X_{1k})_{1\leq k\leq
      \ell}=0\right). \label{eq:formule-Pierre}
\end{multline}

The property is easily verified when
$\ell=1$ , using~\eqref{eq:CI-bayes} and the fact that the random variables $(X_{i1})_{1\leq i\leq N}$ are independent.\\
 Assume that~\eqref{eq:formule-Pierre} is true for
  $\ell\in\{1,\ldots, K-1\}$  and let us prove it for $\ell+1$.
 Using~\eqref{eq:rec-meca-sil},~\eqref{eq:def-hat-F} and~\eqref{eq:formule-Pierre}, we have for all  $(x_{ik})_{i\in\mathcal{C},\,
  1\leq k\leq \ell+1}$,
