    \ell+1}\right) \\
  & =\mathbb{P}\left((X^\text{meca}_{i,\ell+1})_{i\in\mathcal{C}} =(x_{i,\ell+1})_{i\in\mathcal{C}}\mid
    (X^\text{meca}_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell} =(x_{ik})_{i\in\mathcal{C},\, 1\leq k\leq \ell}\right) \\
