\section{Preliminaries}

In this section we introduce all of the basic structures that we will use 
throughout the rest of the paper. 


\subsection{Miniflags}\label{subsec:miniflags}
In this paper we will study the induced action of a linear map $A\in \GL(d,\R)$ 
on certain space of flags. 
We will write $\Gr(k,d)$ for the Grassmannian of $k$-planes in $\R^d$. 
For $1\le k\le d-1$, we will write $\PF(k-1,k+1)$ for the space of partial flags 
of the form $0\subseteq V_{k-1}\subset V_{k+1}\subseteq \R^d$ where $\dim V_{i}=i$. 
Associated to a partial flag $(V_{k-1},V_{k+1})$ is the \emph{miniflag}, $\mc F(V_{k-1},V_{k+1})$,
of all subspaces $V_k$ satisfying $V_{k-1}\subset V_k\subset V_{k+1}$. 
We will say that the \emph{core dimension} of
$\mc F(V_{k-1},V_{k+1})$ is $k-1$. 
Note that the miniflags are the fibers of the obvious map $\PF(k-1,k,k+1)\to \PF(k-1,k+1)$ 
where we forget about the $k$-dimensional subspace. So, thinking of 
$\PF(k-1,k,k+1)$ as a fiber bundle over $\PF(k-1,k+1)$, the fibers are precisely the miniflags, and the 
miniflags are indexed by $\PF(k-1,k+1)$.
Note also that there is a natural correspondence between 
the miniflag $\mc F(V_{k-1},V_{k+1})$ and the (one-dimensional)
projective space of $V_{k+1}\ominus V_{k-1}$,
where $V_{k+1}\ominus V_{k-1}$ denotes $V_{k+1}\cap V_{k-1}^\perp$. 

\subsection{Basic Facts Concerning Entropy}

Below we will define a notion of entropy and introduce its properties.
Given a measure $\mu$ on $\Homeo(M,N)$, its entropy quantifies the smallest extent to which 
the measures $f_*\nu$ vary for $f$ distributed according to $\mu$. 
If there is a measure $\nu$ on $M$ such that $f_*\nu$ is 
the same for $\mu$-a.e.\ $f$, the entropy of the action of $\mu$ will be zero.
The definitions below appear in \cite[Sec.~2]{gorodetski2023nonstationary}. 

\begin{definition}\label{defn:KL}
Suppose that $M$ is a standard Borel space and that $\nu$ and $\wt{\nu}$ 
are Borel probability measures on $M$. We define the 
\emph{Kullback-Leibler divergence} of $\nu$ with respect $\wt{\nu}$ by
\[
\dKL(\nu\vert\wt{\nu})=\begin{cases}
\int_M \log \frac{d\nu}{d\wt{\nu}}\left(\frac{d\nu}{d\wt{\nu}}\right)\,d\wt{\nu}=
\int_M\log(\frac{d\nu}{d\wt{\nu}})\,d\nu &\text{ if }\nu\ll\wt{\nu};\\
+\infty & \text{ else}.
\end{cases}
\]
This is also known as the \emph{relative entropy}.
\end{definition}

Suppose that $M$ and $N$ are closed manifolds and that $\mu$ is a measure 
on $\Homeo(M,N)$. Given measures $\nu$ on 
$M$ and $\nu'$ on $N$, we can define the \emph{mean relative entropy} 
$\Phi_{\mu}(\nu\vert \nu')$ of these measures by
\begin{equation}
\Phi_{\mu}(\nu\vert\nu')=\int \dKL(f_*\nu\vert \nu')\,d\mu(f). 
\end{equation}

If $\mu$ is a probability measure on $\Homeo(M,N)$ and $\nu$ is a probability measure on $M$,
we define the convolution of $\mu$ with $\nu$ by:
\begin{equation}
\mu*\nu=\int_{\Homeo(M,N)} f_*\nu\,d\mu(f).
\end{equation}
As is often done, we also use the notation $\mu_2*\mu_1$ to refer to the 
push-forward of $\mu_2\otimes\mu_1$
under the map $(f_2,f_1)\mapsto f_2\circ f_1$.

A claim we shall use below is the following.

\begin{lem}\label{lem:min_Phi_nu_nu_prime}
\cite[Lem.~2.8]{gorodetski2023nonstationary} 
Suppose $\mu$ is a compactly supported probability on $\Homeo(M,N)$. 
For a fixed probability measure $\nu$ on $M$,
\[
\inf_{\nu'}\,\Phi_{\mu}(\nu\vert\nu')=\Phi_{\mu}(\nu\vert\mu*\nu),
\]
where the infimum is taken over probability measures on $N$.
That is, the mean relative entropy is minimized by the ``mean push-forward", $\nu'=\mu*\nu$ 
\end{lem}

\noindent This leads us to define the Furstenberg entropy as follows. 


\begin{definition}\label{defn:furstenberg_entropy}\cite[Def.~2.3]{gorodetski2023nonstationary}
Suppose that $M$ and $N$ are two closed manifolds and that $\mu$ is a probability 
measure on $\Homeo(M,N)$. We define the \emph{Furstenberg entropy} of $\nu$ by:
\[
\Phi_{\mu}(\nu)= \Phi_\mu(\nu|\mu*\nu)=\int \dKL(f_*\nu\vert \mu*\nu)\,d\mu(f).
\]
\end{definition}
This is a measure of the extent to which the push-forwards $f_*\nu$ 
vary as $f$ runs over the support of $\mu$.
In this notation, Lemma \ref{lem:min_Phi_nu_nu_prime} states $\Phi_\mu(\nu|\nu')\ge
\Phi_\mu(\nu)$ with equality if and
only if $\nu'=\mu*\nu$. 

\begin{definition}\label{defn:pushforward_entropy}
Suppose that $\mu$ is a probability measure on the space of homeomorphisms $\Homeo(M,N)$. 
Then we define the \emph{push-forward entropy} of $\mu$ (when
maps distributed as $\mu$ act on $M$) by
\[
\EP(\mu)=\inf_\nu\, \Phi_\mu(\nu),
\]
where the infimum is taken over probability measures on $M$.
\end{definition}
The push-forward entropy only vanishes if there is a probability measure $\nu$ on $M$ such that
$f_*\nu=\mu*\nu$ for $\mu$-a.e.\ $f$\cite[Lem.~2.5]{gorodetski2023nonstationary}. 

\begin{lem}[Concavity of entropy]\label{lem:convexity_entropy}
Suppose that $M$ and $N$ are closed manifolds and that $\mu$ is a 
compactly supported measure on $\Homeo(M,N)$. 
Suppose we represent $\mu$ as a convex combination of a family of probability 
measures $\{\mu_{\lambda}\}_{\lambda\in\Lambda}$ 
indexed by a probability space $(\Lambda,\eta)$ where each $\mu_{\lambda}$ is a 
probability measure on $\Homeo(M,N)$. 
In other words, $\mu=\int_{\Lambda} \mu_{\lambda}\,d\eta(\lambda)$. Then
\begin{equation}
\EP(\mu)\ge \int_{\Lambda} \EP(\mu_{\lambda})\,d\nu(\lambda). 
\end{equation}
\end{lem}
\begin{proof}
This follows from the inequalities stated above. In particular, we will repeatedly 
use that $\Phi_{\mu}(\nu\vert \nu')$ is minimized when $\nu'=\mu*\nu$ 
(Lemma \ref{lem:min_Phi_nu_nu_prime}). 
\begin{align*}
\EP(\mu)=\inf_\nu\,\Phi_{\mu}(\nu)&=\inf_{\nu}\,\Phi_{\mu}(\nu\vert \mu*\nu)\\
&=\inf_{\nu}\, \int_{\Homeo(M,N)} \dKL(f_*\nu\vert \mu*\nu)\,d\mu(f)\\
&=\inf_{\nu}\, \int_{\Lambda} \int_{f} \dKL(f_*\nu\vert \mu*\nu)\,d\mu_{\lambda}(f)\,d\eta(\lambda)\\
&=\inf_{\nu}\,\int_{\Lambda} \Phi_{\mu_{\lambda}}(\nu\vert \mu*\nu)\,d\eta(\lambda)\\
&\ge \int_{\Lambda} \inf_{\nu}\, \Phi_{\mu_{\lambda}}(\nu\vert \mu*\nu)\,d\eta(\lambda)\\
&\ge \int_{\Lambda} \inf_{\nu}\,\Phi_{\mu_{\lambda}}(\nu\vert \mu_{\lambda}* \nu)\,d\eta(\lambda)\\
&= \int_{\Lambda} \inf_{\nu}\, \Phi_{\mu_{\lambda}}(\nu)\,d\eta(\lambda)\\
&=\int_{\Lambda} \EP(\mu_{\lambda})\,d\eta(\lambda).
\end{align*}
\end{proof}

The following lemma is one of the key tools of \cite{gorodetski2023nonstationary}: 
the push-forward entropy of a convolution is superadditive. 

\begin{lem}[Superadditivity of entropy]\label{lem:additivity_of_entropy_gap}
Suppose that $\mu_1$ is a probability measure on $\Homeo(M_1,M_2)$ and that 
$\mu_2$ is a probability measure on $\Homeo(M_2,M_3)$. Then 
\[
\EP(\mu_2*\mu_1)\ge \EP(\mu_1)+\EP(\mu_2).
\]
\end{lem}

\begin{proof}
Proposition 2.10 in \cite{gorodetski2023nonstationary} gives that 
\[
\Phi_{\mu_2*\mu_1}(\nu)=\Phi_{\mu_1}(\nu)+\Phi_{\mu_2}(\mu_1*\nu).
\]
In particular, we see that 
\[
\EP(\mu_2*\mu_1)=\inf_{\nu}\,\Phi_{\mu_2*\mu_1}(\nu)\ge \inf_{\nu}\, 
\Phi_{\mu_1}(\nu)+\inf_{\nu'}\,\Phi_{\mu_2}(\nu')=\EP(\mu_1)+\EP(\mu_2).
\]
\end{proof}

\subsection{The relationship between entropy and volume distortion}

\begin{lem}[Entropy causes volume distortion \cite{gorodetski2023nonstationary}]
\label{lem:entropy_volume_distortion} 
Suppose that $M_1$ and $M_2$ 
are two Riemannian manifolds with unit volume, and that $\mu$ is a measure on $\Diff^1(M_1,M_2)$. Then 
\[
\int \log \mc{N}(f)\,d\mu(f)\ge \Phi_{\mu}(\vol)\ge \EP(\mu),
\]
where 
\[
\mc{N}(f)=\max_{x\in M_1} \abs{\Jac(f)_x}^{-1}
\]
is the maximum of the volume distortion of $f$. 



\end{lem}

\begin{proof}
An identical argument appears in the proof of \cite[Thm.~1.6]{gorodetski2023nonstationary}. 
Write $m_1$ for the volume on $M_1$ and $m_2$ for the volume on $M_2$. Let 
\[
\mc{N}(f)=\max_{x\in M_1} \abs{\Jac(f)_x}^{-1}=\max_{y\in M_2} \frac{d(f_*m_1)}{dm_2}(y). 
\] 
Hence from the definition of $d_{KL}$ (Def.~\ref{defn:KL}),
\[
\log \mc{N}(f)\ge d_{KL}(f_*m_1\vert m_2). 
\]
Thus taking expectations over $f$, which is distributed according to $\mu$:
\[
\E_{\mu}\left[\log \mc{N}(f)\right]\ge \E_{\mu}\left[d_{KL}(f_*m_1\vert m_2)\right]
\ge \E_{\mu}\left[d_{KL}(f_*m_1\vert \mu*m_1)\right]\ge \Phi_{\mu}(m_1)\ge \EP(\mu),
\]
where we have used that $\mu*m_1$ minimized the mean of the Kullback-Leibler 
divergences in the second inequality. 
\end{proof}
In fact, we will only use the above formula for maps of one-dimensional projective spaces. 

\subsection{Miniflag volume distortion and singular values}
Let $\mc{F}(V_{i-1},V_{i+1})$ be a miniflag. The entropy of a map controls the mean volume
distortion. If $M_1$ and $M_2$ are two Riemannian manifolds, and 
$f\colon M_1\to M_2$ is a diffeomorphism, we will 
write $(J(f)^{-1})_{\max}$ for $\max_{x\in M_1} \abs{\det D_xf}^{-1}$; as usual 
$\abs{\det D_xf} = \|(D_xf)_* \vol_x\|/\|\vol_{f(x)}\|$.  

We begin with the following elementary lemma. 

\begin{lem}\label{lem:volume_distortion_RP1}
If $A\in \GL(2,\R)$ and $A_*$ is the induced map $\RP^1\to \RP^1$, then
\[
(J(A_*)^{-1})_{\max}=\sval_1(A)/\sval_2(A).
\]
\end{lem}
\begin{proof}
We show that for any $B\in\GL(d,\R)$, $\max_{x\in\RP^1}J(B_*)=\sval_1(B)/\sval_2(B)$. Applying this to 
$B=A^{-1}$, using $B_*=A_*^{-1}$, we obtain 
\begin{align*}
(J(A_*)^{-1})_\text{max}&=((J(A_*))_\text{min})^{-1}=
(J(B_*))_{\text{max}}\\
&=\sval_1(B)/\sval_2(B)=\sval_2(A)^{-1}/\sval_1(A)^{-1}=\sval_1(A)/\sval_2(A).
\end{align*}
Let $B\in\GL(d,\R)$. By the singular value decomposition, it suffices to consider 
the case of a diagonal matrix. 
Now consider the unit circle $S^1$ in $\R^2$. We may regard $B_*$ as the composition of two maps $B$ 
and the projection $P$ of $\R^2\setminus \{0\}$ to $S^1$. Thus it suffices to compute the norm of 
the action on a tangent vector to $S^1$. The norm of $B$ is $\sval_1(B)$. The norm of $P$ restricted 
to vectors $v\in \R^2$ with $\|v\|\ge \delta$ is $\delta^{-1}$. Thus for the composition 
\[
B_*: S^1\to B(S^1)\to BA(S^1)=S^1,
\]
one has $J_{\max}\le \sval_1(B)\sval_2(B)^{-1}$. A straightforward computation using the 
chart $\theta\mapsto [\theta,1]$ shows that this value, $\sval_1(B)\sval_2(B)^{-1}$ is realized as 
the differential at the point $[0,1]$. Thus we have that $J_{\max}(B_*)=\sval_1(B)\sval_2^{-1}(B)$,
as required. 
\end{proof}

We will need to estimate the volume distortion on the miniflags. For this we have the following lemma. 


\begin{prop}
Suppose that $V$ is an inner product space. Then 
\[
\log \frac {\sval_1(B|_{V_{k+1}\perp V_{k-1}})}{\sval_2(B|_{V_{k+1}\perp V_{k-1}})} 
=\log J_{\max} (B\vert \mc{F}(V_{k-1},V_{k+1})).
\]
\end{prop}
\begin{proof}
The map $B_{V_{k+1}\perp V_{k-1}}$ is a linear map from $V_{k+1}\ominus V_{k-1}$ 
to $AV_{k+1}\ominus AV_{k-1}$. 
The map $B|\mc F(V_{k-1},V_{k+1})$ sending $\mc{F}(V_{k-1},V_{k+1})$ to $\mc{F}(BV_{k-1},BV_{k+1})$ 
is the projectivization of this map. Thus this statement is immediate from Lemma 
\ref{lem:volume_distortion_RP1}.
\end{proof}


\section{Entropy of Random Bundle Maps}\label{sec:entropy_of_bundle_maps}

Below we will consider random bundle maps; we will be particularly 
interested in the restriction of these random maps to different fibers.
Suppose that $E$ is a fiber bundle over a manifold $M$. As mentioned earlier, we are primarily interested
in the case $M=\PF(k-1,k+1)$ and $E=\PF(k-1,k,k+1)$ so that the fiber over $(V_{k-1},V_{k+1})$ is the 
miniflag $\mc F(V_{k-1},V_{k+1})$. 
The miniflag $\mc F(V_{k-1},V_{k+1})$ inherits a Haar measure, which we denote as $m_{V_{k-1},V_{k+1}}$. 
Let $\Aut(E)$ denote the space of bundle maps $F\colon E\to E$. 
Given a probability measure $\mu$ on $\Aut(E)$, 
we let $\bar\mu$ be the associated quotient dynamics on $M$.

Suppose that $\{\mu_n\}_{n\in \N}$ is a sequence of probability measures on $\Aut(E)$. 
We will write $\mu^{*n}$ for the convolution $\mu_n*\cdots\mu_2*\mu_1$, 
that is $\mu^{*n}$ is the distribution of the 
(non-stationary) evolution from time 0 to time $n$.


 We recall here that given a measurable partition $\mc{P}$ of a Borel space 
 $\Omega$ and a Borel probability measure $\nu$ that there is a disintegration 
 of $\nu$ along the partition and for each element $P\in \mc{P}$ we obtain a probability 
 measure $\nu_P$ on $P$ such that for each Borel $A\subseteq \Omega$,
\[
\nu(A)= \int \nu_P(A\cap P)\,d\bar{\nu}(P),
\]
where $\bar{\nu}$ is the measure on $\Omega/\mc{P}$. For more details about this 
construction see the discussion surrounding \cite[Thm.~5.11]{viana2016foundations}.

Next we define the fiberwise entropy. As above, suppose that $\mu$ is a 
probability measure on $\Aut(E)$. 
Suppose that $\mc{F}_1$ is a fiber in $E$. The fiber-averaged push-forward entropy 
estimates over all the possible 
images of $\mc{F}_1$, what is the mean entropy of the maps conditioned on being that image. 

In general, the maps $f$ in the support of $\mu$ map $\mc F_1$ into multiple fibers.
For fibers $\mc F_1$ and $\mc F_2$, write $\mu_{\mc{F}_1,\mc{F}_2}$ for the 
conditional distribution of $\mu$ 
conditioned on $\mu$ carrying $\mc{F}_1$ to $\mc{F}_2$. Let $\bar{\mu}_{\mc{F}_1}$ be the 
distribution of the images of $\mc{F}_1$ (recall that points in $M$ correspond to these fibers). 
Then we define the \emph{fiber-averaged push-forward entropy} of the fiber 
$\mc{F}_1$ under the dynamics $\mu$ to be 
\begin{equation}\label{eqn:fiberwise_pushforward_entropy}
\EPIA(\mc{F}_1,\mu)=\int \EP(\mu_{\mc{F}_1,\mc{F}_2})\,d\bar{\mu}_{\mc{F}_1}(\mc{F}_2).
\end{equation}
Note that the integrand is measurable because $\mu_{\mc{F}_1,\mc{F}_2}$ is 
Borel-measurable, $h(\cdot)$ is Borel-measurable as it is lower-semicontinuous 
\cite[Cor.~2.6]{gorodetski2023nonstationary}, and the composition of Borel-measurable
functions is Borel-measurable. 

\begin{definition}\label{defn:uniform_fiberwise_pushforward_entropy}
Suppose that $\mu$ is a measure on $\Aut(E)$. We say that $\mu$ has 
\emph{uniform fiberwise push-forward entropy} $h>0$ if 
\begin{equation}
\inf_{\mc{F}\in E} \EPIA(\mc{F},\mu)= h.
\end{equation}
\end{definition}

\begin{prop}\label{prop:additivity_of_pushforward_entropy}
Suppose that $\mu_1$ and $\mu_2$ are probability measures on $\Aut(\mc{E})$. 
Suppose that $\mu_2$ has uniform 
fiberwise push-forward entropy $h$. Then, 
\begin{equation}
\EPIA(\mc F_0,\mu_2*\mu_1)\ge h+\EPIA(\mc F_0,\mu_1).\label{eqn:additivity}
\end{equation}
\end{prop}

\begin{proof}
This follows along the lines that we have considered above. First we will estimate the fiberwise entropy
between a pair of fibers. As before, let $\mu^{*2}=\mu_2*\mu_1$. Recall the above notation that 
$\mu_{1,\mc{F}_0,\mc{F}_1}$ is the conditional distribution of $\mu_1$ on the maps from 
$\mc{F}_0$ to $\mc{F}_1$, and $\mu_{2,\mc{F}_1,\mc{F}_2}$ is defined similarly 
for $\mu_2$. Let $\bar{\mu}_{1,\mc{F}_0}^{\mc{F}_2}$ denote the distribution 
of the image $\mc{F}_1$ of $\mc{F}_0$ given that the image of 
$\mc{F}_0$ under $\mu^{*2}$ is equal to $\mc{F}_2$. We observe that
\begin{equation}\label{eqn:mu_2_representation}
\mu^{*2}_{\mc{F}_0,\mc{F}_2}=\int \mu_{2,\mc{F}_1,\mc{F}_2}*
\mu_{1,\mc{F}_0,\mc{F}_1}\,d\bar\mu_{1,\mc{F}_0}^{\mc{F}_2}(\mc{F}_1). 
\end{equation}
This equality is a combination of two things. First, if we analogously define 
$\mu^{*2}_{\mc{F}_0,\mc{F}_1,\mc{F}_2}$ to be the distribution of $f=f_2f_1$ given 
that $f_1(\mc{F}_0)=\mc{F}_1$ and $f_2(\mc{F}_1)=\mc{F}_2$, then 
$\mu^{*2}_{\mc{F}_0,\mc{F}_1,\mc{F}_2}=\mu_{\mc{F}_1,\mc{F}_2}*\mu_{\mc{F}_0,\mc{F}_1}$. 
Secondly, we can represent $\mu^{*2}_{\mc{F}_0,\mc{F}_2}$ by conditioning on the 
middle point in the trajectory: $\mu^{*2}_{\mc{F}_0,\mc{F}_2}=
\int \mu_{\mc{F}_0,\mc{F}_1,\mc{F}_2}(f)\,d\eta(\mc{F}_1)$, where $\eta$ is the 
distribution of the flag $\mc{F}_1$. In \eqref{eqn:mu_2_representation} we have combined 
these two things and renamed $\eta$ to reflect that it is a conditioned version of $\mu_1$.

Thus by Lemma \ref{lem:convexity_entropy} it follows that
\[
\EP(\mc{F}_0,\mu^{*2}_{\mc{F}_0,\mc{F}_2})\ge 
\int \EP(\mc{F}_0,\mu_{2,\mc{F}_1,\mc{F}_2}*\mu_{1,\mc{F}_0,\mc{F}_1})\,
d\bar\mu_{1,\mc{F}_0}^{\mc{F}_2}(\mc{F}_1). 
\]
By assumption, $\mu_2$ has uniform fiberwise entropy gap $h$. 
So by integrating the previous line over $\mc{F}_2$, 
and applying Lemma \ref{lem:additivity_of_entropy_gap} in the fourth line below, we see that
\begin{equation}\label{eq:uniformsumbound}
\begin{split}
\EPIA(\mc F_0,\mu^{*2})&=\int \EP(\mc F_0,\mu^{*2}_{\mc{F}_0,\mc{F}_2})\,
d \bar{\mu}^{*2}_{\mc{F}_0}(\mc{F}_2)\\
&\ge \int \EP(\mc F_0,\mu_{2,\mc{F}_1,\mc{F}_2}*\mu_{1,\mc{F}_0,\mc{F}_1})\,
d\bar\mu_{1,\mc{F}_0}^{\mc{F}_2}(\mc{F}_1)\,
d\bar{\mu}^{*2}_{\mc{F}_0}(\mc{F}_2) \\
&=\int \EP(\mc F_0,\mu_{2,\mc{F}_1,\mc{F}_2}*\mu_{1,\mc{F}_0,\mc{F}_1})\,
d\bar\mu_{2,\mc{F}_1}(\mc{F}_2)\,d\bar\mu_{1,\mc{F}_0}(\mc{F}_1)
\\
&\ge \int \big(h+\EP(\mc F_0,\mu_{1,\mc{F}_0,\mc{F}_1})\big)\,
d\bar\mu_{1,\mc{F}_0}(\mc{F}_1)=h+\EPIA(\mc{F}_0,\mu_1). 
\end{split}
\end{equation}
\end{proof}




\section{Tools for Bounding Entropy Below}

In this section we introduce three basic tools that allow us to estimate 
the entropy of the random bundle map on 
miniflags, and then use this estimate on the entropy to estimate the gap between singular values of the 
random matrix product.

\subsection{Pointwise Entropy}

In this subsection, we develop a tool for actually estimating the fiberwise entropy gap.

Our main tool for actually bounding entropy is a bound on 
the entropy for absolutely continuous measures.  
The pointwise entropy measures the failure of volume to be infinitesimally 
invariant under the dynamics of $\mu$ at the point $x$.

\begin{definition}\label{defn:pointwise_entropy}
Suppose that $M$ and $N$ are smooth manifolds, $x\in M$, $y\in N$, and that 
$\mu$ is a probability measure on $\Diff^1(M,N)$ such that $\mu$-a.s.~$f(x)=y$. 
Then we define the \emph{pointwise (volume) entropy} of $\mu$ at $y$ by 
\[
h_{\PW}(y,\mu)\coloneqq \int \log\left(\frac{\Jac_y^{-1}(f)}{\int \Jac_y^{-1}(f)\,d\mu(f)}\right)
\frac{\Jac_y^{-1}(f)}{\int \Jac^{-1}_y(f)\,d\mu(f)}\,d\mu(f).
\]
\end{definition}
Note that the quantity in the above definition might equal $0$.
We now record a simple estimate that will be useful for estimating the pointwise entropy later.
\begin{lem}\label{lem:convexity_xlogx}
Let $\psi(x)=x\log x$. Suppose that $X\ge 0$ is a random variable 
such that $\abs{X}\le M$ for some $M>0$
and $\E X=1$. Then
\[
\E\left[\psi(X)\right]\ge \var(X)/(2M).
\]
\end{lem}
\begin{proof}
Let $\nu$ denote the distribution of $X$ on $(0,\infty)$. 
Then using Taylor's formula with remainder gives:
\begin{align*}
\E\left[\psi(X)\right]&=
\int (\psi(x)-\psi(1))\,d\nu(x)\\
&=\int\left(\psi'(1)(x-1)+\frac{\psi''(g(x))}{2}(x-1)^2\right)\,d\nu(x)\\
&=\int \frac{\psi''(g(x))}{2}(x-1)^2\,d\nu(x)
\end{align*}
Now note that $\psi''(x)=1/x$. Thus 
\[
\E\left[\psi(X)\right]\ge \frac{\var(X)}{2M}.
\]
\end{proof}

\subsection{The Fubini Argument}
Suppose that $M$ and $N$ are two manifolds with volume and that $\mu$ is a 
measure supported on $\Diff(M,N)$. Suppose that $\mu$ is smoothing in the sense 
that for any $x\in M$, $\mu*\delta_x$ is absolutely continuous. How can we use the 
pointwise entropy to bound the entropy gap of $\mu$ below? By definition, the 
push-forward entropy $\Phi_{\mu}(\nu)$ is given by evaluating the integral:
\[
\int_{\Diff} h(f_*\nu\vert \mu*\nu)\,d\mu(f)=\int_{\Diff}\int_N 
\log\left(\frac{df_*\nu}{\,d\mu*\nu\,}(y)\right)\frac{df_*\nu}{\,d\mu*\nu\,}(y)\,
d\mu*\nu(y)\,d\mu(f).
\]
We would like to evaluate this by reversing the order of integration and 
seeing what the contribution to the integral is at each point $y$. 
Although there may be points $y$ at which the pointwise entropy is small,
the following Fubini argument estimates the average contribution.

We begin with a version of the argument for maps from one manifold to another. If we were only 
studying the Lyapunov exponents on $\SL(2,\R)$, then this estimate would suffice.
\begin{prop}[Fubini Argument]\label{prop:fubini_argument}
Let $M$ and $N$ be $d$-dimensional compact Riemannian manifolds of unit volume. 
Let $\mu$ be a probability measure on $\Diff(M,N)$ and suppose for each $y\in N$ 
we have a representation of $\mu$ as:
\[
\mu=\int_{\xi\in \Xi_{y}} \mu_{\xi}\,dm_y(\xi),
\]
where for each $\xi$, $f^{-1}(y)$ is constant for $\mu_{\xi}$-a.e.\ $f$.

Suppose that there exists $\beta>0$ and a set $G\subseteq \Diff(M,N)$, 
of ``good'' diffeomorphisms with the following property.
For any $\xi$, if $\supp \mu_{\xi}\cap G\ne\emptyset$ then $h_{\PW}(y,\mu_\xi)\ge \beta$. 
Then if $\nu$ is any absolutely continuous measure on $M$, 
\[
\Phi_{\mu}(\nu)\ge \beta \mu(G). 
\]
\end{prop}

\begin{proof}
    We compute
    \begin{align*}
        &\Phi_\mu(\nu)=\int\int\log\left(\frac{df_*\nu}{\,d\mu*\nu\,}(y)\right)\frac{df_*\nu}
        {\,d\mu*\nu\,}(y)\,d\mu(f)\,d(\mu*\nu)(y)\\
        &=\int\int\int\log\left(\frac{df_*\nu}{\,d\mu*\nu\,}(y)\right)\frac{df_*\nu}{\,d\mu*\nu\,}(y)
        \,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\\
       &=\int\int\int\left(
       \log\left(\frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\right)
       +\log\left(\frac{d\mu_{\xi}*\nu}{\,d\mu*\nu\,}(y)\right)
       \right)\frac{df_*\nu}{\,d\mu*\nu\,}(y)
        \,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\\ 
        &=\circled{1}+\circled{2},
    \end{align*}
    where
    \begin{align*}
        \circled{1}&=
       \int\int\int\log\left(\frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\right)
       \frac{df_*\nu}{\,d\mu*\nu\,}(y)
        \,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\text{;\quad and}\\
        \circled{2}&=
        \int\int\int
       \log\left(\frac{d\mu_{\xi}*\nu}{\,d\mu*\nu\,}(y)\right)
       \frac{df_*\nu}{\,d\mu*\nu\,}(y)
        \,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y).
    \end{align*}
Since the first term of \circled{2} does not depend on $f$, we have
$$
\circled{2}=\int\left(\int
       \log\left(\frac{d\mu_{\xi}*\nu}{\,d\mu*\nu\,}(y)\right)
       \frac{\,d\mu_{\xi}*\nu\,}{d\mu*\nu}(y)
        \,dm_y(\xi)\right)\,d(\mu*\nu)(y).
$$
Since $\int \frac{d\mu_{\xi}*\nu}{d\mu*\nu}(y)\,dm_y(\xi)=1$, 
by Jensen's inequality, the inner integral is non-negative, so $\Phi_\mu(\nu)\ge\circled 1$.
We rewrite $\circled 1$ as
\begin{align*}
&\circled 1=\int\int\int \log\left(\frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\right)
       \frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\frac{\,d\mu_{\xi}*\nu\,}{d\mu*\nu}(y)
        \,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\\
&=\int\int\left(\int \log\left(\frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\right)
       \frac{df_*\nu}{\,d\mu_{\xi}*\nu\,}(y)\,d\mu_{\xi}(f)\right)
       \frac{\,d\mu_{\xi}*\nu\,}{d\mu*\nu}(y)
        \,dm_y(\xi)\,d(\mu*\nu)(y)\\
&=\int\int h_\PW(y,\mu_{\xi})
        \frac{\,d\mu_{\xi}*\nu\,}{d\mu*\nu}(y)\,dm_y(\xi)\,d(\mu*\nu)(y).
\end{align*}
We say a fiber, $\xi$, is \emph{good} if $\supp\mu_\xi\cap G\ne\emptyset$. 
By hypothesis, $h_\PW(y,\mu_\xi)\ge \beta\mathbf 1_\text{$\xi$ good}$.
So we have
\begin{equation}\label{eq:lowerbd}
\begin{split}
    \circled 1&\ge\beta 
    \int\int \mathbf 1_\text{$\xi$ good}\frac{\,d\mu_{\xi}*\nu\,}{d\mu*\nu}(y)
        \,dm_y(\xi)\,d(\mu*\nu)(y)\\
&=\beta \int\int \mathbf 1_\text{$\xi$ good}\int \frac{df_*\nu}{d\mu*\nu}(y)
\,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\\
&\ge \beta \int\int \int \mathbf 1_G(f)\frac{df_*\nu}{d\mu*\nu}(y)
\,d\mu_{\xi}(f)\,dm_y(\xi)\,d(\mu*\nu)(y)\\
&= \beta \int \int \mathbf 1_G(f)\frac{df_*\nu}{d\mu*\nu}(y)
\,d\mu(f)\,d(\mu*\nu)(y)\\
&=\beta \int \mathbf 1_G(f)\left(\int 1\,
\frac{df_*\nu}{d\mu*\nu}(y)\,d(\mu*\nu)(y)\right)\,d\mu(f)\\
&=\beta \int \mathbf 1_G(f)\left(\int 1\,\,df_*\nu(y)\right)\,d\mu(f),
\end{split}
\end{equation}
where the third line holds since $\mathbf 1_G(f)\le \mathbf 1_{\xi\text{ good}}$ for $\mu_\xi$-a.e. $f$.
Since the inner integral is $1$, we obtain
\[
\Phi_\mu(\nu)\ge \circled 1\ge \beta \mu(G).
\]
\end{proof}

A small generalization of the above argument gives a version that applies to random bundle maps. 
The important thing in the following is to note that the conclusion is now averaged. 

\begin{prop}[Fubini Argument for Bundles]\label{prop:fubini_argument_for_bundles}
 Suppose that $\pi\colon E\to M$ is a fiber bundle with smooth fibers and that 
 $\mu$ is a measure supported on the set of diffeomorphisms $\Diff(E,M)$ of $E$ 
 that preserve the fibering over $M$.

For each pair of fibers $\mc{F}_1$ and $\mc{F}_2$, let $\mu_{\mc{F}_1,\mc{F}_2}$ be $\mu$ conditioned on the event that $f ({\mc{F}}_1)=\mc{F}_2$. 
We suppose we have a further decomposition of these measures:
for a pair of fibers $\mc F_1$ and $\mc F_2$ and for 
each $y\in \mc{F}_2$ we have a representation of $\mu_{\mc F_1,\mc F_2}$ as:
\[
\mu_{\mc{F}_1,\mc{F}_2}=\int_{\Xi_{y}^{\mc{F}_1,\mc{F}_2}} \mu_{\xi}\,dm_y(\xi),
\]
where each $\mu_{\xi}$ satisfies that for all $f\in \supp\mu_{\xi}$ that $f^{-1}(y)$ is constant. 

Suppose that there exists $\beta>0$ and a set $G\subseteq \Diff(E,M)$, 
of ``good'' diffeomorphisms with the following property:
if $\xi\in\Xi_y^{\mc F_1,\mc F_2}$ and $\supp\mu_\xi\cap G\ne\emptyset$,  
then $h_\PW(\mu_\xi)\ge \beta$. 
Then if $\nu$ is any absolutely continuous measure on a fiber $\mc F_1$, we have
\[
\int\Phi_{\mu_{\mc F_1,\mc F_2}}(\nu)\,d(\mu*\delta_{\mc F_1})(\mc F_2)\ge\beta\mu(G).
\]
In particular, if the minimizer of the fiberwise Furstenberg entropy is absolutely 
continuous, then $\mu$ has uniformly positive fiber-averaged push-forward entropy.
\end{prop}


\begin{proof}
The argument is a slight elaboration of the argument in Proposition 
\ref{prop:fubini_argument}. Given a pair of fibers $\mc F_1$ and $\mc F_2$
and an absolutely continuous probability measure $\nu$ on $\mc F_1$,
from \eqref{eq:lowerbd},  we can extract the estimate:
\[
\Phi_{\mu_{\mc{F}_1,\mc{F}_2}}(\nu)\ge 
\beta \int \mathbf 1_G(f)\left(\int 1\,\,
df_*\nu(y)\right)\,d\mu_{\mc{F}_1,\mc{F}_2}(f)=
\beta \int {\mathbf 1}_G(f)\,d\mu_{\mc{F}_1,\mc{F}_2}(f).
\]
Note that this estimate is not yet enough to conclude anything about the 
fiberwise entropy for any particular 
fiber: we don't know how much of $\mu_{\mc{F}_1,\mc{F}_2}$ is comprised of ``good" $f$. 
Now we can integrate 
this over all images $\mc{F}_2$ of $\mc{F}_1$. 
\[
\int \Phi_{\mu_{\mc{F}_1,\mc{F}_2}}(\nu)\,d(\mu*\delta_{\mc{F}_1})(\mc{F}_2)\ge 
\beta\int_{M} \int \mathbf 1_G(f)\,d\mu_{\mc{F}_1,\mc{F}_2}(f)\,
d(\mu*\delta_{\mc{F}_1})(\mc F_2)= \beta\mu(G).
\]
As long as the minimizers of the Furstenberg entropy are actually absolutely continuous, 
the final conclusion of the Proposition follows.
\end{proof}

\subsection{Mean miniflag volume distortion implies singular value gaps}
We are interested in obtaining the ratio of a pair of consecutive singular 
values of a product of matrices. 
The following proposition relates the logarithm of the ratio of the $k$th and 
$(k+1)$st singular values of a matrix
to an average value of the logarithm of the 1st and 2nd singular values 
for a corresponding fibered action.
For a matrix $A$, we write $\Svals_i^j(A)$ for the product 
$\sval_i(A)\sval_{i+1}(A)\cdots \sval_j(A)$ where
these are the $i$th through $j$th singular values, listed in non-increasing order.

Given a nested pair of subspaces $U\subseteq V$, we denote the orthogonal
complement of $U$ in $V$ by $V\ominus U$. Given a matrix $B$, 
we define the action of $B$ on the orthogonal complement of $U$ in $V$, denoted 
$B|_{V\perp U}$, by $\proj_{B(V)\ominus B(U)}B\proj_{V\ominus U}$, where $\proj_V$ 
denotes the orthogonal projection onto $V$.
For a pair of matrices $B_1$, $B_2$, one can check that
$(B_2B_1)|_{V\perp U}=(B_2)_{V_1\perp U_1}\cdot (B_1)_{V\perp U}$, where $U_1=B_1(U)$ and $V_1=B_1(V)$.
If $U$ is a $k$-dimensional subspace of an $\ell$-dimensional subspace $V$, we have the equality. 
\begin{equation}\label{eqn:singular_values_subspaces}
\Svals_1^{\ell}(B|_V)\coloneqq \Svals_1^\ell(B\proj_V)=\Svals_1^k(B|_U)\Svals_1^{\ell-k}(B|_{V\perp U}).
\end{equation}
This can be checked by writing the transformation $B$ with respect to an orthonormal basis 
with $U\oplus U^{\perp}$ on the domain and $B(U)\oplus B(U)^{\perp}$ on the codomain. The 
resulting matrix is block triangular and the singular values of the diagonal 
blocks are exactly those in the formula.

Given a partial flag
$\PF(i_1,i_2,\ldots,i_j)$, let $\lambda_{i_1,\ldots,i_j}$ be the normalized 
Haar measure, invariant under the
action of the orthogonal group, and recall that if $(i_{m_1},\ldots,i_{m_k})$ is a subsequence
of $(i_1,\ldots,i_j)$, then $\lambda_{i_{m_1},\ldots,i_{m_k}}$ is the 
marginal of $\lambda_{i_1,\ldots,i_j}$
under projection onto those coordinates. 

\begin{prop}\label{prop:gapest}
    For each $d\in\N$, there exists a constant $C_d$, such that for all $B\in\GL(d,\R)$,
    and all $1\le k<d$,
$$
\left|\int \log \frac {\sval_1(B|_{V_{k+1}\perp V_{k-1}})}{\sval_2(B|_{V_{k+1}\perp V_{k-1}})}\,
d\lambda_{k-1,k+1}(V_{k-1},V_{k+1})
-\log\frac {\sval_k(B)}{\sval_{k+1}(B)}\right|\le C_d.
$$
\end{prop}


For $V_\ell\in\grass_{\ell}$, let $\alpha_\ell(V_\ell)=S_1^{\ell}(\proj_{E_\ell}\proj_{V_\ell})$, 
where $E_\ell=\lin(e_1,\ldots,e_\ell)$.
This is a measure of the ``component'' of $V_\ell$ in the $E_\ell$ direction.

\begin{lem}\label{lem:gapcomp}
    Let $D=\diag(b_1,\ldots,b_d)$ and let $1\le k<d$ and let $(V_{k-1},V_k,V_{k+1})\in \PF(k-1,k,k+1)$. 
    Writing $\alpha_i$ for $\alpha_i(V_i)$, We have
$$\alpha_k^2\alpha_{k-1}\cdot\frac {b_k}{b_{k+1}}
\le \frac{\sval_1(D|_{V_{k+1}\perp V_{k-1}})}{\sval_2(D|_{V_{k+1}\perp V_{k-1}})}
\le \frac{1}{\alpha_{k-1}^2\alpha_{k+1}}\cdot \frac {b_k}{b_{k+1}}
$$
\end{lem}

\begin{proof}
For each $\ell$, we have the following inequalities:
\begin{equation}\label{eq:SVbounds}
    \alpha_\ell b_1\cdots b_\ell\le \Svals_1^\ell(D|_{V_\ell})\le b_1\cdots b_\ell,\\
\end{equation}
where the upper bound is by standard properties of singular values and the left hand side 
follows from 
\begin{align*}
    \Svals_1^\ell(D|_{V_\ell})&=\Svals_1^\ell(D\proj_{V_\ell})\\
    &\ge \Svals_1^\ell(\proj_{E_\ell}D\proj_{V_\ell})\\
    &=\Svals_1^\ell(\proj_{E_\ell}D\proj_{E_\ell}\proj_{E_\ell}\proj_{V_\ell})\\
    &=\Svals_1^\ell(\proj_{E_\ell}D\proj_{E_\ell})\Svals_1^\ell(\proj_{E_\ell}\proj_{V_\ell})\\
   &= \alpha_\ell\cdot b_1\cdots b_\ell.
\end{align*}
The second line follows by standard properties of singular values. The third line follows since
$\proj_{E_\ell}D=\proj_{E_\ell}D\proj_{E_\ell}^2$ and the fourth line follows by 
multiplicativity of determinants
since $\proj_{E_\ell}D\proj_{E_\ell}$ and $\proj_{E_\ell}\proj_{V_\ell}$ are rank $\ell$ matrices
where the domain of the first matches the range of the second. 
From earlier, if $W$ is any $k$-dimensional subspace containing $V_{k-1}$,
\begin{align}
    \Svals_1^{k}(D|_{W})&=\Svals_1^{k-1}(D|_{V_{k-1}})\sval_1(D|_{W\perp V_{k-1}});
    \text{\quad and}\label{eq:s1bound}
    \\
    \Svals_1^{k+1}(D|_{V_{k+1}})&=\Svals_1^{k-1}(D|_{V_{k-1}})
    \Svals_1^2(D|_{V_{k+1}\perp V_{k-1}}),\label{eq:s12bound}.
\end{align}

We then have
$$
\sval_1(D|_{W\perp V_{k-1}})=\frac{\Svals_1^k(D|_{W})}{\Svals_1^{k-1}(D|_{V_{k-1}})}
\le \frac{\Svals_1^k(D)}{\alpha_{k-1} b_1\cdots b_{k-1}}
=\frac{b_k}{\alpha_{k-1}}.
$$

Since $W$ was arbitrary, $\sval_1(D|_{\R^d\perp V_{k-1}})\le \frac{b_k}{\alpha_{k-1}}$, so that in 
particular
we see 
$$
\sval_1(D|_{V_{k+1}\perp V_{k-1}})\le \frac {b_k}{\alpha_{k-1}}.
$$
Now, taking $W$ to be $V_k$ in \eqref{eq:s1bound}, we have
$$
\sval_1(D|_{V_{k+1}\perp V_{k-1}})
\ge \sval_1(D|_{V_k\perp V_{k-1}})=\frac {\Svals_1^k(D|_{V_{k}})}{\Svals_1^{k-1}(D|_{V_{k-1}})}
\ge \frac{\alpha_k b_1\cdots b_k}{b_1\cdots b_{k-1}}
=\alpha_kb_k.
$$
Combining the bounds, we have
\begin{equation}\label{eq:s1bounds}
\alpha_k b_k\le \sval_1(D|_{V_{k+1}\perp V_{k-1}})\le \frac{b_k}{\alpha_{k-1}}.
\end{equation}

Since $\Svals_1^2(D|_{V_{k+1}\perp V_{k-1}})=\Svals_1^{k+1}(D|_{V_{k+1}})/\Svals_1^{k-1}(D|_{V_{k-1}})$,
applying the bounds in \eqref{eq:SVbounds} gives
\begin{equation}\label{eq:s12bounds}
    \alpha_{k+1}b_kb_{k+1}\le \Svals_1^2(B_{V_{k+1}\perp V_{k-1}})\le \frac{b_kb_{k+1}}{\alpha_{k-1}}.
\end{equation}

Dividing the square of \eqref{eq:s1bounds} by \eqref{eq:s12bounds} gives
the claimed result.
\end{proof}



\begin{lem}\label{lem:integrable}
    Let $\alpha_k\colon \grass_k\to\R$ be defined by 
    $\alpha_k(V_k)=\Svals_1^k(\proj_{E_k}\proj_{V_k})$ as above. 
    For all $1\le k<d$, $\log\alpha_k$ is an integrable function of 
    $V_k$ with respect to $\lambda_k$. 
\end{lem}

\begin{proof}
    Since $\alpha_k(V_k)\le 1$ for all $V_k\in\grass_k$ 
    (so that $\log\alpha_k$ takes non-positive values),
    we have the equality
\begin{align*}
    \int|\log\alpha_k(V_k)|\,d\lambda_k(V_k)&=
    \int_0^\infty \lambda_k(\{V_k\colon |\log\alpha_k(V_k)|\ge t\}\,dt\\
    &=\int_0^\infty \lambda_k(\{V_k\colon \alpha_k(V_k)\le e^{-t}\})\,d\!t.
\end{align*}
Recall that we may obtain a uniform random element of $V_k$ by sampling 
vectors $\mathbf v_1,\ldots,\mathbf v_k$ independently with independent standard normal entries
and setting $V_k=\lin(\mathbf v_1,\ldots,\mathbf v_k)$. Let 
$\mathbf u_i=\proj_{\lin(\mathbf v_1,\ldots,\mathbf v_{i-1})^\perp}(\mathbf v_i)$ and 
set $\hat{\mathbf u}_i=\mathbf u_i/\|\mathbf u_i\|$.
That is, $\hat{\mathbf u}_1,\ldots,\hat{\mathbf u}_k$ are the Gram-Schmidt orthonormalization
of $\mathbf v_1,\ldots,\mathbf v_k$. 
We then have 
$$
\alpha_k(V_k)=\prod_{j=1}^k
d\big(\proj_{E_k}\hat{\mathbf u}_j,\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{j-1})\big).
$$
In particular, if $\alpha_k(V_k)\le e^{-t}$, then for some $j\le k$, 
$d\big(\proj_{E_k}\hat{\mathbf u}_j,\proj_{E_k}\lin(\mathbf v_1,\ldots,
\mathbf v_{j-1})\big)\le e^{-t/k}$. 
That is
\begin{align*}
\lambda_k(\{V_k\colon \alpha_k(V_k)\le e^{-t}\})&\le
\sum_{j=1}^k \mathbb P\Big(d\big(\proj_{E_k}\hat{\mathbf u}_j,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{j-1})\big)\le e^{-t/k}\Big)\\
&\le k\,\mathbb P\Big(d\big(\proj_{E_k}\hat{\mathbf u}_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le e^{-t/k}\Big)\\
&=k\,\mathbb P\Big(d\big(\proj_{E_k}\mathbf u_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le e^{-t/k}\|\mathbf u_k\|\Big)\\
&=k\,\mathbb P\Big(d\big(\proj_{E_k}\mathbf v_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le e^{-t/k}\|\mathbf u_k\|\Big)\\
&\le k\,\mathbb P\Big(d\big(\proj_{E_k}\mathbf v_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le e^{-t/k}\|\mathbf v_k\|\Big)\\
\end{align*}


We observe
\begin{align*}
&\mathbb P\Big(d\big(\proj_{E_k}\mathbf v_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le e^{-t/k}\|\mathbf v_k\|\Big)\\
&\le
\mathbb P\Big(\|\mathbf v_k\|\ge t\Big)+\mathbb P\Big(d\big(\proj_{E_k}\mathbf v_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le te^{-t/k}\Big).
\end{align*}

The first term is $O(e^{-t^2/(2d)})$: at least one of the entries has to have 
absolute value exceeding $t/\sqrt d$,
so this is an integrable function of $t$. To estimate the second term, 
let $W$ be an arbitrary $(k-1)$-dimensional 
subspace of $\R^k$ and let $\mathbf V$ be a random vector in $\R^k$ with 
independent standard normal entries. 
We want to estimate $\mathbb P(d(\mathbf V,W)\le te^{-t/k})$.
We have
\begin{align*}
\mathbb P(d(\mathbf V,W)\le te^{-t/k})
&\le
\mathbb P(\|\mathbf V\|\ge t)+\operatorname{Vol}(B_{te^{-t/k}}(W)\cap B_t(0))\\
&=O(e^{-t^2/(2k^2)})+O(t^ke^{-t/k}).
\end{align*}
Since this holds for arbitrary $W$, 
we deduce
$$
\mathbb P\Big(d\big(\proj_{E_k}\mathbf v_k,
\proj_{E_k}\lin(\mathbf v_1,\ldots,\mathbf v_{k-1})\big)\le te^{-t/k}\Big)=O(t^ke^{-t/k}).
$$
Hence
$$
\int_0^\infty \lambda_k(\{V_k\colon \alpha_k(V_k)\le e^{-t}\})\,d\!t<\infty,
$$
as required.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:gapest}]
By the singular value decomposition, there exist orthogonal matrices matrices $O_1$ and $O_2$ 
and a diagonal matrix $D$ such that $B=O_1DO_2$. 
If $O$ is an orthogonal matrix and $V$ is a subspace of $\R^d$, we first observe
$O\proj_V=\proj_{O(V)}O$.
If $A$ is any matrix and $U$ is a proper subspace of a subspace $V$,
then 
\begin{align*}
\sval_i((AO)_{V\perp U})&=\sval_i(\proj_{AO(V)\ominus AO(U)}AO\proj_{V\ominus U})\\
&=\sval_i(\proj_{AO(V)\ominus AO(U)} A\proj_{O(V)\ominus O(U)}O)\\
&=\sval_i(\proj_{AO(V)\ominus AO(U)} A\proj_{O(V)\ominus O(U)})\\
&=\sval_i(A|_{O(V)\perp O(U)}).
\end{align*}
Similarly, 
\begin{align*}
\sval_i((OA)_{V\perp U})&=\sval_i(\proj_{OA(V)\ominus OA(U)} OA\proj_{V\ominus U})\\
&=\sval_i(O\proj_{A(V)\ominus A(U)}A\proj V)\\
&=\sval_i(OA_{V\perp U})\\
&=\sval_i(A_{V\perp U}).
\end{align*}
Hence we have $\sval_i(B|_{V_{k+1}\perp V_{k-1}})=\sval_i((DO_2)|_{V_{k+1}\perp V_{k-1}})=
\sval_i(D_{O_2(V_{k+1})\perp O_2(V_{k-1})})$. Additionally, $\sval_i(B)=\sval_i(D)$. 
Since $\lambda_{k-1,k+1}$ is invariant under the left action of the orthogonal group,
we see
\begin{equation}\label{eq:D=B}
\begin{split}
&\left|\int \log \frac {\sval_1(B|_{V_{k+1}\perp V_{k-1}})}{\sval_2(B|_{V_{k+1}\perp V_{k-1}})}\,
d\lambda_{k-1,k+1}(V_{k-1},V_{k+1})
-\log\frac {\sval_k(B)}{\sval_{k+1}(B)}\right|\\
=&
\left|\int \log \frac {\sval_1(D|_{V_{k+1}\perp V_{k-1}})}{\sval_2(D|_{V_{k+1}\perp V_{k-1}})}\,
d\lambda_{k-1,k+1}(V_{k-1},V_{k+1})
-\log\frac {\sval_k(D)}{\sval_{k+1}(D)}\right|.
\end{split}
\end{equation}

By Lemma \ref{lem:gapcomp},
we have for
$\lambda_{k-1,k,k+1}$-a.e. $(V_{k-1},V_k,V_{k+1})$, 
$$
2\log \alpha_k+\log \alpha_{k-1}\le
\log\frac{\sval_1(D|_{V_{k+1}\perp V_{k-1}})}{\sval_2(D|_{V_{k+1}\perp V_{k-1}})}-
\log\frac {\sval_k(D)}{\sval_{k+1}(D)}\le -2\log\alpha_{k-1}-\log\alpha_{k+1}.
$$
Applying \eqref{eq:D=B} and integrating the inequality with respect to $\lambda_{k-1,k,k+1}$,
we obtain
\begin{align*}
&\int\left|\log\frac{\sval_1(B|_{V_{k+1}\perp V_{k-1}})}{\sval_2(B|_{V_{k+1}\perp V_{k-1}})}-
\log\frac {\sval_k(B)}{\sval_{k+1}(B)}\right|\,d\lambda_{k-1,k,k+1}(V_{k-1},V_k,V_{k+1})\\
\le &\int\left(2|\log\alpha_{k-1}|+2|\log\alpha_k|+|\log\alpha_{k+1}|\right)\,
d\lambda_{k-1,k,k+1}(V_{k-1},V_k,V_{k+1}).
\end{align*}
Since $\lambda_{k-1}$, $\lambda_k$, $\lambda_{k+1}$ and $\lambda_{k-1,k+1}$ are marginals of 
$\lambda_{k-1,k,k+1}$, applying Lemma \ref{lem:integrable}, we obtain the desired conclusion, 
observing that the right side does not depend on $B$.
\end{proof}

\begin{rem}
The estimate in Proposition \ref{prop:gapest} is closely related to certain estimates in the theory 
of Dedieu-Shub measures \cite{dedieu2003shub,burns1999recent}. For example, 
\cite{rivin2005mean} shows that 
\[
\int_{O(n)} \rho(AO)\,d\text{Haar}(O) \ge C_d \|A\|,
\]
where $O_n$ is the orthogonal group and $\rho(AO)$ is the spectral radius of $AO$. 
See also \cite{armentano2024random}.
\end{rem}
\subsection{Mean miniflag fiber distortion implies mean singular value gaps} 

The following lemma provides the necessary connection between the entropy on miniflags
and the gaps between singular values. 

\begin{prop}\label{prop:miniflag_distortion_implies_singular_value_gaps}
Let $m$ be the Haar measure on $\PF(k-1,k+1)$. 
Let $\mu$ be a measure on $\GL(d,\R)$. Then:
\[
\E_{\mu}\left[\log \sval_{k}(A)-\log\sval_{k+1}(A)\right]\ge 
\int_{\PF(k-1,k+1)} \EPIA(\mc F,\mu)\,dm(\mc F)-C_d,
\]
where $C_d$ is the constant from Proposition \ref{prop:gapest}.
In other words, the mean fiber-averaged entropy gives a lower bound on the mean gap 
between singular values.
\end{prop}

\begin{proof} 
Integrating Proposition \ref{prop:gapest} over $\mu$ gives
\begin{align*}
&\E_{\mu}\left[\log \sval_{k}(A)-\log\sval_{k+1}(A)\right]\\
&\ge \E_{\mu}\left[\int \log 
\frac {\sval_1(A|_{V_{k+1}\perp V_{k-1}})}{\sval_2(A|_{V_{k+1}\perp V_{k-1}})}\,
dm(\mc F_1)\right]-C_d\\
&=\int\int \log \frac {\sval_1(A|_{V_{k+1}\perp V_{k-1}})}{\sval_2(A|_{V_{k+1}\perp V_{k-1}})}
\,d\mu(A)\,dm(\mc F_1)-C_d\\
&=\int\int\log (J(A|_{V_{k+1}\perp V_{k-1}})^{-1})_\text{max}\,d\mu(A)\,dm(\mc F_1)-C_d\\
&=\int\int\int\log (J(A|_{V_{k+1}\perp V_{k-1}})^{-1})_\text{max}\,d\mu_{\mc F_1,\mc F_2}(A)
\,d\mu_{\mc F_1}(\mc F_2)\,dm(\mc F_1)-C_d\\
&\ge \int\int \EP(\mc F_1,\mu_{\mc F_1,\mc F_2})\,d\mu_{\mc F_1}(\mc F_2)\,dm(\mc F_1)-C_d\\
&=\int\EPIA(\mc F_1,\mu)\,dm(\mc F_1)-C_d,
\end{align*}
where $\mc F_1$ denotes the pair $(V_{k-1},V_{k+1})$ and we used Lemma 
\ref{lem:entropy_volume_distortion}
in the sixth line. 
\end{proof}

\section{Entropy of the induced random bundle map on miniflags}\label{sec:pointwise_entropy_est}

Next we will show that a perturbation of size $\epsilon$ gives rise to 
pointwise entropy that is quadratic in $\epsilon$. 

Before we begin the proof, we outline the approach. We recall that we are considering the action by 
matrices of the form $A+\xi$ where $A$ is fixed and $\xi$ is a random perturbation.
Let $(V_{k-1},V_{k+1})\in \PF(k-1,k+1)$, let $\mc F_0=\mc F(V_{k-1},V_{k+1})$,
and let $x=(V_{k-1},V_k,V_{k+1})\in \PF(k-1,k,k+1)$ be a point in the corresponding
miniflag. Note that matrices act naturally on partial flags.
We then form an $x$-dependent partition of the $\xi\in \R^{d\times d}$,
where $\xi\sim\xi'$ if $(A+\xi)(x)=(A+\xi')(x)$.
Call this partition $\mc{Q}$. For $Q\in \mc Q$, $(A+\xi)(V_{k-1},V_{k+1})$
is a constant element of $\PF(k-1,k+1)$ for all $\xi\in Q$. We consider the action of
the $(A+\xi)_{\xi\in\ Q}$ on $\mc F(V_{k-1},V_{k+1})$ and look, in particular, at the 
variability of the Jacobian of the action at $x$. 

The most important point in the calculation is the following: there are some images of $x$ 
that are quite rare and hence do not contribute much entropy for two reasons. First, they do not 
contribute much due to their rarity, but second there is also not much variation under the dynamics. 
For example, consider the case where $\xi$ is extremely close to the boundary of the support of 
$\mu_{\epsilon}$: it is hard to ``vary" $\xi$ much while keeping $(A+\xi)(x)$ 
fixed. For this reason, we will simplify our work by restricting to images $(\mc{F}_1, y)$ 
given by an element $A+\xi$ where $\xi$ is deep inside the support of $\mu_{\epsilon}$.
The concavity of entropy allows us to derive a lower bound for the entropy based on the
action of these deep $\xi$'s. 

\begin{prop}\label{prop:fiberwise_entropy_invertible_case}
Suppose that $\phi$ is a continuous density on 
$M_{d\times d}(\R)$ such that there exists $C>0$ with $\phi(A)\le C/\|A\|^{d^2+1}$
for all $A$. There exists $C_{\phi}$ 
such that the following holds. Suppose that $M\ge 1$ and $\epsilon\le 1$ are given. 
Let $E$ be the absolutely continuously distributed matrix-valued random variable with density $\phi$.
If $A$ is any matrix with $\|A\|\le M$,
let the measure $\mu_{\blue \epsilon}$ be the distribution of
\[
A+\epsilon E.
\]
Then $\mu_{\blue \epsilon}$ has uniform fiberwise entropy gap of at least $C_{\phi}\epsilon^2/M^2$ when acting on 
the bundle of miniflags, $\PF(k-1,k,k+1)$ over $\PF(k-1,k+1)$
for any $1\le k<d$. 
\end{prop}

\begin{proof}
We assume that $\phi$ is positive at the zero matrix. This is without loss of generality as if 
$\phi$ is positive at some matrix $E_0$, then we may replace $\phi(\cdot)$ by $\phi(\cdot+E_0)$
and replace $A$ by $A+\epsilon E_0$, and arrive at a similar conclusion (with $C_\phi$
modified to take account of the possibly greater norm of $A+\epsilon E_0$). 
Let $K=\max\phi$.
For simplicity, we further assume 
that $\phi(E)\ge a>0$ whenever $\|E\|_\infty\le 1$, where $\|E\|_\infty$ denotes $\max_{i,j}|E_{ij}|$. 
Clearly, a bound of this type holds on some axis-aligned cube centered at the origin. If it were
a smaller cube, some minor adjustments would need to be made. 

Next, we will find a subset of the support of $\mu_{\epsilon}$ that is disjoint from the
non-invertible matrices and large enough that we may ``vary" freely within it.
Let $A$ be fixed with $\|A\|\le M$ and
let $O_1DO_2$ be a singular value decomposition of $A$.
Then there exists a diagonal matrix $D'$ with $s_d(D')\ge \frac\epsilon 2$ such that $\|D'-D\|\le
\frac\epsilon2$. Set $A'=O_1D'O_2$ so that $\|A'-A\|_\infty\le \|A'-A\|=\|D'-D\|<\frac\epsilon 2$
and $s_d(A')=s_d(D')\ge\frac\epsilon 2$.
Now if $\|B-A'\|_\infty<\frac\epsilon{4 d}$, then $\|B-A'\|<\frac\epsilon 4$, so that 
by the Lipschitz property of singular values, $s_d(B)\ge s_d(A')-\frac\epsilon 4\ge \frac\epsilon 4$. 
Let $G_{\epsilon,1}=\{B\colon \|B-A'\|_\infty\le\frac\epsilon{4 d}\}$ and
let $G_{\epsilon,2}=\{B\colon \|B-A'\|_\infty\le \frac\epsilon{8 d}\}$.
Note that any line $\ell$ 
containing a point $B\in G_{\epsilon,2}$ satisfies that the length of the intersection 
$G_{\epsilon,1}\cap \ell$ is at least $\frac{\epsilon}{4 d}$. 
In particular, using the fact that $\phi$ is continuous and compactly supported, we claim that
there exists $c_\phi>0$ such that if a line $\ell$ intersects $G_{\epsilon,2}$
then 
\begin{equation*}
    \frac{d\mu_\ell}{dm_\ell}(B)\ge c_\phi\text{\quad for $B\in \ell\cap G_{\epsilon,1}$},
\end{equation*}
where $\mu_\ell$ denotes the normalized version of $\mu$ on $\ell$ and
$m_\ell$ denotes the normalized Lebesgue measure on $\ell\cap G_{\epsilon,1}$.

To see this, let $\ell$ be any line such that $\ell\cap G_{\epsilon,2}
\ne\emptyset$ and let $\ell^\text{pre}$ be the pre-image of $\ell$ under the map 
$r:E\mapsto A+\epsilon E$. 
Let
the matrices on $\ell^\text{pre}$ be parameterized by $M(t)=B_0+tB_1$
where $\|B_1\|_\infty=1$ and $(B_0)_{ij}=0$ for some $i,j$ with $|(B_1)_{ij}|=1$. 
This ensures that $\|M(t)\|\ge |t|$, so that $\phi(M(t))\le \min(K,C/|t|^{d^2+1})$,
and $\int_{-\infty}^\infty \phi(M(t))\,dt\le C_1:=\int_{-\infty}^\infty\min(K,C/|t|^{d^2+1})\,dt$.
Since $\phi(M)\ge a$ on $r^{-1}(G_{\epsilon,1})$, the 
normalized conditional measure $\mu_\ell^\text{pre}$ on $\ell^\text{pre}$ has density
at least $a/C_1$ on $r^{-1}(G_{\epsilon,1})$ with respect to the chosen parameterization.
On the other hand, the set $r^{-1}(\ell\cap G_{\epsilon,1})$ has length at least $\frac 1{4d}$
with respect to the chosen parameterization, so the density of 
normalized Lebesgue measure $m_\ell^\text{pre}$ on this set has density 
at most $4d$. Hence, the density 
$d\mu_\ell^\text{pre}/dm_\ell^\text{pre}$ is at least $a/(4dC_1)$
on $r^{-1}(G_{\epsilon,1}\cap \ell)$. Pushing forward both measures by $r$, 
it follows that $d\mu_\ell/dm_\ell\ge c_\phi:=a/(4dC_1)$ on $\ell\cap G_{\epsilon,1}$.

In particular, we may write
\begin{equation}\label{eq:convex_comb}
    \mu_\ell=c_\phi m_\ell+(1-c_\phi)\mu'_\ell,
\end{equation}
where $\mu'_\ell$ is an absolutely continuous probability measure supported on $\ell$.


We construct the measurable partition of $\GL(d,\R)$ in stages. 
Let $(V_{k-1},V_{k+1})$ and $(W_{k-1},W_{k+1})$ be elements of 
$\PF(k-1,k+1)$ and write $\mc F_1$ and $\mc F_2$ for the corresponding miniflags. 
We write $\mu_{\mc F_1,\mc F_2}$ for the measure $\mu$ conditioned on 
$\{B\in\GL(d,\R)\colon B(\mc F_1)=\mc F_2\}$.
We then condition further: let $y=(W_{k-1},W_k,W_{k+1})$ be a fixed element of
$\mc F_2$.
For each $x=(V_{k-1},V_k,V_{k+1})$ in $\mc F_1$, we let $\mu_{x}$ be 
$\mu$ conditioned on $\{B\in\GL(d,\R)\colon B(x)=y\}$, so that $\mu_{\mc F_1,\mc F_2}$
is an integral combination of the $\mu_{x}$ where $x$ runs over $\mc F_1$.

Fix an orthonormal basis $\{f_1,\ldots,f_d\}$ for $\R^d$ such that $\lin(f_1,\ldots,f_j\}=W_j$
for $j=k-1,k,k+1$.
For $x=(V_{k-1},V_k,V_{k+1})$ in $\mc F(V_{k-1},V_{k+1})$, we take
an orthonormal basis $\{e_1,\ldots,
e_d\}$, depending Borel-measurably on $x$ \cite[Lemma 1]{Raghunathan},
again with the property that $V_j=\lin(e_1,\ldots,e_j)$ for $j=k-1,k,k+1$. 
We partition $\mu_{x}$ further: 
The measurable partitions that we consider have atoms $\{B+tf_k\otimes e_k\colon t\in\R\}$, where
$B(x)=y$. The measurable partition into lines that we obtain will be denoted $\Xi_{x,y}$. Let
$\mu_{\xi}$ denote the conditional measure on an element $\xi\in \Xi_{x,y}$.
We would like to apply Proposition \ref{prop:fubini_argument_for_bundles}, with 
$G_{\epsilon,2}$ playing the role of $G$, so that a partition element $\xi$ is 
"good" if $\xi$ intersects $G_{\epsilon,2}$. Hence we need to obtain
a lower bound on $h_\PW(\mu_\xi)$ for the conditional measures $\mu_\xi$
such that $\supp\mu_\xi$ intersects $G_{\epsilon,2}$. 
Since the conditional measures are supported on lines, we apply Lemma \ref{lem:convexity_entropy}
and \eqref{eq:convex_comb} to deduce $h_\PW(\mu_\xi)\ge c_\phi h_\PW(m_\xi)$, 
where $m_\xi$ is normalized 
Lebesgue measure on $\supp\mu_\xi\cap G_{\epsilon,1}$, a line segment of 
length at least $\frac{\epsilon}{4d}$.
We shall show that $h_\PW(m_\xi)\ge c'\epsilon^2$, where $c'$ is a universal constant 
whenever $\xi$ is a good element of the partition. Since 
$\mu_\epsilon(G_{\epsilon,2})\ge a(\frac 1{4d})^d$,
we are able to apply
Proposition \ref{prop:fubini_argument_for_bundles}.

For the remainder of the proof, we let $\xi$ be a fixed good element of the partition.
Then the linear maps in the support of $m_\xi$ have the following 
block-triangular form with respect to the $(e_1,\ldots,e_d)$ and $(f_1,\ldots,f_d)$ coordinates.
\[
B(E)=\begin{bNiceArray}{c|c|c}[margin]
B_{1,1} & B_{1,2} & B_{1,3}\\
\hline
0 & B_{2,2} & B_{2,3}\\
\hline
0 & 0 & B_{3,3}
\end{bNiceArray}
\]
where the first block is $(k-1)$-dimensional, the second block is 2-dimensional and
the last block is $(d-(k+1))$-dimensional. Recall that we are considering the action of 
the linear maps as maps from the miniflag $\mc F_1$ to $\mc F_2$, which we identify with 
one-dimensional projective spaces. The matrix $B_{2,2}$ is the matrix of interest to us: 
it controls the induced map along the miniflag.

By the choice of the measurable partition and coordinates,
the matrices in the support of $m_\xi$ differ only in the top left corner of $B_{2,2}$. 
 In particular, for any $E'$ as above we me may write $B_{2,2}(E')$
in the upper triangular form: 
\begin{equation}
B_{2,2}(E')=\begin{bmatrix}
a(E') & b(E') \\
0 & c(E')
\end{bmatrix}.
\end{equation}

We now estimate the pointwise entropy. Concretely, in the coordinate system 
introduced above, $m_\ell$ is  supported on a family of matrices of the form 
\[
B_{2,2}(t)=\begin{bmatrix}
    t&b\\0&c,
\end{bmatrix}
\]
where the $t$'s are uniformly distributed in an interval $[a-r,a+r]$
of length at least $\epsilon/(4d)$. Since matrices in $G_{\epsilon,1}$ have conorm at least 
$\frac\epsilon{8d}$ and norm at most $M+1$, we see the range of $t$ values is contained in 
$[\frac\epsilon{8d},M+1]$. 
To conclude, we must estimate the pointwise entropy of this family of matrices,
viewed as a map of $\RP^1$, at the vector 
${\bf{e}}=[1,0]^{T}$, and show it is bounded below by a quantity of order $\epsilon^2$. 

As we essentially computed in Lemma \ref{lem:volume_distortion_RP1}, 
$\Jac_{{\bf{e}}}^{-1}(B_{2,2}(t))=t/c$. 
By definition, the pointwise entropy is equal to
\[
h_{\PW}(m_\ell)=\E\left[ \log 
\left(\frac{\Jac_{{\bf{e}}}^{-1}(B_{2,2}(t))}{\E \Jac_{{\bf{e}}}^{-1}(B_{2,2}(t))}\right)
\frac{\Jac_{{\bf{e}}}^{-1}(B_{2,2}(t))}{\E \Jac_{{\bf{e}}}^{-1}(B_{2,2}(t))}\right].
\]

We observe that the random variable
$\Jac_{\bf e}^{-1}(B_{2,2}(t))/\E\Jac_{\bf e}^{-1}(B_{2,2}(t))$ is uniformly distributed
on $[1-\frac ra,1+\frac ra]$. That is, $h_\PW(m_\ell)=\E\psi(X)$, where $X$ is uniformly 
distributed on $[1-\frac ra,1+\frac ra]$, where $\psi(x)=x\log x$. 
Since $a-r>0$, we see $\frac ra<1$, so by Lemma \ref{lem:convexity_xlogx}, we see 
$$
h_\PW(m_\ell)\ge \tfrac 1{12}(\tfrac ra)^2.
$$
Since $r\ge \frac\epsilon{8d}$ and $a\le M+1$, we see $h_\PW(m_\ell)\ge c\epsilon^2/M^2$,
so that $h_\PW(\xi_\ell)\ge C\epsilon^2/M^2$ as required, where $C$ only depends on $\phi$.
The conclusion now follows from Proposition \ref{prop:fubini_argument_for_bundles} with $G_{\epsilon,2}$ playing the role of the good set.
\end{proof}


\section{Conclusion}\label{sec:conclusion}

We can now establish the main theorem of this paper.
This 
section is structured as follows. First, we obtain a consequence of the main result of 
\cite{gorodetski2023nonstationary}, 
which shows that almost surely the logarithmic singular values of
realizations of matrix products differ from their expectation by $o(n)$.
We then relate our $\GL(d,\R)$ matrices to $\SL(d,\R)$
matrices and control some moments required by \cite{gorodetski2023nonstationary}
before finishing the proof.

\subsection{Another consequence of Gorodetski-Kleptsyn}

We first record a consequence of the main theorem in \cite{gorodetski2023nonstationary}. 
We denote by $\SLpm(d,\R)$ the collection of $d\times d$ matrices of determinant $\pm 1$.
Given a matrix 
$A\in \SLpm(\R^d)$, we will say that $A$ acts on we write $\bigwedge^k\R^d$ by
\[
(\textstyle{\bigwedge^k}A)(v_1\wedge \cdots \wedge v_n)=(Av_1)\wedge\cdots\wedge(Av_n). 
\]
Similarly, given a miniflag $\mc F=\mc F(V_{k-1},V_{k+1})$, the action of $A$ on $\mc F$ is given
by the matrix $A|_{V_{k+1}\perp V_k}$.

\begin{lem}\label{lem:no_invariants_big_support}
Suppose that $\mu$ is a measure defined on $\SLpm(d,\R)$ that has a component that equivalent to 
volume on a neighborhood of $\Id\in \SLpm(d,\R)$. Then there do not exist any pair of probability 
measures $\nu_1$ and $\nu_2$ on $\mathbb{P}(\R^{d})$, such that $\mu$-a.s.~$A_*\nu_1=\nu_2$. 
Further, for $1\le k\le d-1$, there do not exist probability measures $\nu_1$ and $\nu_2$ on 
$\mathbb{P}(\bigwedge^k \R^d)$ such that $\mu$-almost surely $(\bigwedge^k A)_*\nu_1=\nu_2$. 

Further, for $1\le k\le d-1$, there does not exist a non-trivial pair of subspaces $V_1$ 
and $V_2$ of $\bigwedge^k \R^d$ such that $\mu$-a.s.~$(\bigwedge^k A)_*V_1=V_2$.
\end{lem}

\begin{proof}
We begin with the statement about the action on $\mathbb P(\R^d)$.
Suppose for a contradiction that $\nu_1$ and 
$\nu_2$ are two probability measures on $\mathbb P(\R^d)$ such that $A_*\nu_1=\nu_2$ for $\mu$-a.e. $A$.
From the assumption, it suffices to consider 
the case that $\mu$ is fully supported on an open symmetric generating set $\mc{N}$ containing 
$\Id\in \SLpm(d,\R)$; by symmetric we mean that if $A\in \mc{N}$ then $A^{-1}\in \mc{N}$. As 
preserving a measure is a closed condition, we see that for any such pair $A_*\nu_1=\nu_2$ for all 
$A\in \mc{N}$. In particular, as $\Id\in \mc{N}$, this implies $\nu_1=\nu_2$. 
As $\mc{N}$ is symmetric and $\SL(d,\R)$ 
is connected, it generates $\SL(d,\R)$ as a semigroup. In particular, this 
implies that such a measure is 
invariant under all of $\SL(d,\R)$, which is impossible because this easily implies that $\nu$ must be a 
$\delta$-mass but $\SL(d,\R)$ does not preserve any fixed lines $[v_{\delta}]\in \RP^{d-1}$ where 
$\delta$ is supported.

When we consider the induced action on $\bigwedge^k\R^d$, the push-forward of $\mu$ by the map 
$A\mapsto \bigwedge^k A$ is not fully supported in a neighborhood of $\Id\in \SL(\bigwedge^k \R^d)$. 
The same considerations as before reduce to the case of showing that there is no measure $\nu$ on 
$\mathbb{P}(\bigwedge^k\R^d)$ invariant under all the $(\bigwedge^k)_*\mu$. From 
\cite[Cor.~3.10]{abels1995semigroups}, as long as the eigenvalues of an element 
$g\in \SL(\R^d)$ are distinct in modulus, then the induced action of $\bigwedge^k g$ on 
$\bigwedge^k \R^d$ is proximal.
By proximal, we mean that the 
action of $\|\bigwedge^k g^n\|^{-1}g^n$ converges to a rank $1$-matrix. In particular, this 
implies that $\mu$ must be a $\delta$-mass sitting on some vector $v_{\delta}\in \bigwedge^k\R^d$. 
However, as $(\bigwedge^k)_*\mu$ generates $\bigwedge^k\SL(\R^d)$, we see that $v_{\delta}$ is invariant 
under all of $\bigwedge^k \SL(\R^d)$. But this is impossible: $\bigwedge^k\SL(\R^d)$ is an irreducible 
representation of $\SL(d,\R)$.\footnote{For this fact, first $\bigwedge^k \SL(d,\mathbb{C})$ is an 
irreducible representation on $\bigwedge^k \mathbb{C}^d$ \cite[p.~340]{knapp2002lie}. As this is 
the complexification of $\bigwedge^k \SL(d,\R)$, we must have that $\bigwedge^k \SL(d,\R)$ is 
irreducible as well, as otherwise its complexification would be reducible.}

The proof of the statement about subspaces is similar and just uses that the representations 
$\bigwedge^k \SL(d,\R)$ are irreducible.
\end{proof}

\begin{rem}
Lemma \ref{lem:no_invariants_big_support} is stated for measures whose support contains a neighborhood 
of the origin. However, note that if $\mu$ is a measure as in Lemma \ref{lem:no_invariants_big_support}, 
then the same conclusions follow for the measure $\delta_A*\mu$ for any matrix $A\in \SLpm(d,\R)$.
\end{rem}



\begin{prop}\label{prop:growth_in_expectations_implies_almost_sure}
Suppose that $\mc{K}$ is a compact subset of the space of probability 
measures on $\SLpm(d,\R)$ and that any 
$\mu\in \mc{K}$ has a component that is equivalent to volume on a neighborhood of $\Id\in \SLpm(d,\R)$. 
Suppose that we have the following moment condition: there exist $\gamma,C$, such that for all 
$\mu\in \mc{K}$, $\int \|A\|^{\gamma}\,d\mu(A)<C$. 
Suppose that $(\mu_n)_{n\in \N}$ is a sequence of probability measures in $\mc{K}$. Let $T_n$ 
denote the (nonstationary) random product of the first $n$ matrices, so that $T_n$ is 
distributed according to $\mu^{*n}=\mu_n*\cdots*\mu_1$. Let
\[
L_{k,n}=\E\left[\log \prod_{j=1}^k\sval_k(T_n)\right]=\E\left[\log \|\textstyle\bigwedge^k T_n\|\right].
\]
Then for each $k$,
\[
\lim_{n\to \infty} \frac{1}{n} \left(\log\|\textstyle\bigwedge^k T_n\|-L_{k,n}\right)=0. 
\]
\end{prop}
\begin{proof}
We apply \cite[Thm.~1.1]{gorodetski2023nonstationary} to the induced random 
product on the exterior power. 
Let $\mu_{k,n}$ be the push-forward of $\mu_n$ from $\SLpm(d,\R)$ to $\SLpm(\bigwedge^k\R^d)$. 
We point out that while \cite{gorodetski2023nonstationary} is stated for actions of $\SL(d,\R)$,
it applies verbatim to actions of $\SLpm(d,\R)$.

We check that the hypotheses of that theorem hold for the sequence of measures $\mu_{k,n}$. There are 
three hypotheses to check: The finite moment condition, the measures condition, and the subspaces 
condition. The latter two conditions are verified due to Lemma \ref{lem:no_invariants_big_support}. 
The moments condition is verified because $\|\bigwedge^k A\|\le \|A\|^{k}$.

Thus we may apply \cite[Thm.~1.1]{gorodetski2023nonstationary} to the measures $\mu_{k,n}$. 
The conclusion is now immediate from that theorem because 
$\|\bigwedge^k T_n\|=\prod_{j=1}^k \sval_j(T_n)$. 
\end{proof}


\subsection{Hypotheses on the noise and moments}
The results of \cite{gorodetski2023nonstationary} are phrased for matrices in $\SL(d,\R)$, 
whereas here we work with matrices that are almost surely in $\GL(d,\R)$. 
As such, we need to 
relate matrices in $\GL(d,\R)$ to matrices in $\SL^\pm(d,\R)$ and check that the appropriate moment 
estimate holds. Given a matrix $A\in \GL(d,\R)$, we write $\hat A$ for the matrix
$A/|\det A|^{1/d}$. We call this the \emph{normalization} of $A$.
We observe that it has the same projective action as $A$ on
any miniflag. 


\begin{definition}\label{defn:uniform_norm_moment}
Given a collection $\mc K$ of probability measures on $M_{d\times d}(\R)$ it
has finite \emph{uniform $\gamma$-norm moment} if
$$
\sup_{\mu\in \mc K}\int \|E\|^\gamma\,d\mu(E)<\infty.
$$
\end{definition}

\begin{definition}\label{defn:uniform_conorm_moment}
Given a collection $\mc K$ of probability measures on $M_{d\times d}(\R)$,
has finite \emph{uniform translated $\gamma$-conorm moments} if for all $M$,
$$
\sup_{\mu\in\mc K}\sup_{\|A\|\le M}\int \|(A+E)^{-1}\|^\gamma\,d\mu(E)<\infty
$$    
\end{definition}

The following lemma establishes that if $\mc K$ is a collection of probability 
measures on $\R^{d\times d}$,
satisfying norm and conorm moment conditions, then the normalizations of $A+E$ where $E$ is distributed
as $\mu$ satisfy moment conditions, possibly for some smaller exponent.
\begin{lem}\label{lem:specialization}
Suppose that $\mc K$ is a collection of probability measures on $M_{d\times d}(\R)$ with 
finite uniform $\gamma$-norm moment and finite uniform translated 
$\gamma$-conorm moments for some $\gamma>0$. 
Then there exists $\gamma'>0$ such that for all $M$,
\begin{align*}
&\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int \big\|\widehat{A+E}\big\|^{\gamma'}\,d\mu(E)
<\infty\text{; and}\\
&\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int \big\|(\widehat{A+E})^{-1}\big\|^{\gamma'}\,d\mu(E)<\infty.\\
\end{align*}
In particular, $\bigcup_{\|A\|\le M}(G_A)_*(\mc K)$ is tight, where $G_A(E)\coloneqq \widehat{A+E}$.
\end{lem}

\begin{proof}
    Let $\gamma'=\gamma/(2-\frac 2d)$. For any matrix $B\in\GL(d,\R)$, we have the inequalities
    \begin{equation*}\label{eq:detbounds}
    \frac{\|B\|}{\|B^{-1}\|^{d-1}}=s_1(B)s_d(B)^{d-1}\le |\det B|
    \le s_1(B)^{d-1}s_d(B)=\frac{\|B\|^{d-1}}{\|B^{-1}\|}.
    \end{equation*}
    Since $\hat B=B/|\det B|^{1/d}$, substituting the bounds above, we deduce
    \begin{equation}\label{eq:hatbounds}
    \begin{split}
    \|\hat B\|&\le \|B\|^{(d-1)/d}\|B^{-1}\|^{(d-1)/d};\text{ and}\\
    \|\hat B^{-1}\|&\le \|B\|^{(d-1)/d}\|B^{-1}\|^{(d-1)/d}.
    \end{split}
    \end{equation}
    We now compute
    \begin{align*}
        &\sup_{\|A\|\le M}\sup_{\mu\in \mc K}\int \|\widehat{A+E}\|^{\gamma'}\,d\mu(E)\\
        &\le \sup_{\|A\|\le M}\sup_{\mu\in\mc K}
        \int \|A+E\|^{\gamma'(d-1)/d}\|(A+E)^{-1}\|^{\gamma'(d-1)/d}\,d\mu(E)\\
        &=\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int \|A+E\|^{\gamma/2}\|(A+E)^{-1}\|^{\gamma/2}\,d\mu(E)\\
        &\le\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\left[\left(\int \|A+E\|^\gamma\,d\mu(E)\right)^{1/2}
        \left(\int \|(A+E)^{-1}\|^\gamma\,d\mu(E)\right)^{1/2}\right]\\
        &\le \left[\sup_{\mu\in\mc K}\left(\int (M+\|E\|)^\gamma\,d\mu(E)\right)^{1/2}\right]
        \left[\sup_{\|A\|\le M}\sup_{\mu\in\mc K}
        \left(\int \|(A+E)^{-1}\|^\gamma\,d\mu(E)\right)^{1/2}\right]\\  
        &\le \left[\sup_{\mu\in\mc K}
        \left(\int 2^\gamma(M^\gamma+\|E\|^\gamma)\,d\mu(E)\right)^{1/2}\right]
        \left[\sup_{\|A\|\le M}\sup_{\mu\in\mc K}
        \left(\int \|(A+E)^{-1}\|^\gamma\,d\mu(E)\right)^{1/2}\right].  
    \end{align*}
    By assumption, both terms are finite, giving the required bound. 
    Similarly, since by \eqref{eq:hatbounds} we have the same upper bounds for $\|\hat B\|$ and 
    $\|\hat B^{-1}\|$, we obtain the same estimate for $\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int\|
    (\widehat{A+E})^{-1}\|^{\gamma'}\,d\mu(E)$.

   To show that this implies that $\bigcup_{\|A\|\le M}(G_A)_*(\mc K)$ is tight, 
   let $L$ be defined by 
   $$
   L=\max\left(\sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int \big\|\widehat{A+E}\big\|^{\gamma'}\,d\mu(E),
   \sup_{\|A\|\le M}\sup_{\mu\in\mc K}\int \big\|(\widehat{A+E})^{-1}\big\|^{\gamma'}\,d\mu(E)\right).
   $$
   In particular, for any $A$ with $\|A\|\le M$ and any $\mu\in\mc K$, we have the estimates
   $\int\|\widehat{A+E}\|^{\gamma'}\,d\mu(E)\le L$ and
   $\int\|(\widehat{A+E})^{-1}\|^{\gamma'}\,d\mu(E)\le L$. If $\epsilon>0$ is given, then
   the first estimate gives 
   $\mu(\{E\colon \|\widehat{A+E}\|>(2L/\epsilon)^{1/{\gamma'}}\})<\frac\epsilon2$.
   That is, 
   $$
   (G_A)_*\mu(\{B\colon \|B\|>(2L/\epsilon)^{1/\gamma'}\})<\tfrac\epsilon 2.
   $$ 
   Similarly, the second estimate gives 
   $$
   (G_A)_*\mu(\{B\colon \|B^{-1}\|>(2L/\epsilon)^{1/\gamma'}\})<\tfrac\epsilon 2.
   $$
   This establishes that for all $A$ with $\|A\|\le M$ and for all $\mu\in\mc K$,
   $$
   (G_A)_*\mu(\{B\colon (2L/\epsilon)^{-1/\gamma'}\le s_d(B)\le s_1(B)\le (2L/\epsilon)^{1/\gamma'}\})
   >1-\epsilon.
   $$
   Since $\{B\in \SL(d,\R)\colon a\le s_d(B)\le s_1(B)\le b\}$ is a compact set for all $a,b$,
   this establishes the required tightness of $\bigcup_{\|A\|\le M}(G_A)_*(\mc K)$.    
\end{proof}

\begin{lem}\label{lem:singleton}
    Let $\mc K$ be a set of absolutely continuous probability measures on $\GL(d,\R)$
    with uniformly bounded density (i.e. $\sup_{\mu\in\mc K}\sup_{A\in\GL(d,\R)}\frac{d\mu}{d\vol}(A)
    <\infty$)
    and
    uniformly bounded $\gamma$-norm moment. Then $\mc K$ satisfies the assumptions of
    Lemma \ref{lem:specialization}.
\end{lem}

\begin{proof}
    It suffices to check that $\mc K$ has a finite uniform translated $\gamma'$-conorm moment 
    for some $\gamma'>0$. In the course of the proof, the letter $C$ will denote various constants 
    that do not depend on $A$, and may vary from line to line. We recall that $s_d(A)=\|A^{-1}\|^{-1}$.
    We make use of the fact that there is a constant $C$
    such that for any matrix $A$,
    \begin{equation}\label{eq:Leb_bound}
    \text{Leb}(\{B\colon \|B\|\le 2^n,\ s_d(A+B)<\alpha\})\le 
    C2^{(d^2-1)n}\alpha\text{ for all $\alpha$}.
    \end{equation}
    To see this, notice that if $s_d(A+B)<\alpha$, then there is a unit vector $v$ such that 
    $\|(A+B)v\|<\alpha$. If $v$ is such a vector and 
    $|v_i|\ge \frac 1{\sqrt d}$, then the $i$th column of $A+B$
    is no further than $\alpha\sqrt d$ from the span of the other columns, so that 
    $\{B\colon \|B\|\le 2^n,\ s_d(A+B)<\alpha\}$ is contained in the $d$-fold union
    of sets of volume $O((2^n)^{d^2-1}\alpha)$.

    Since $\mc K$ has a finite $\gamma$-norm moment, we observe from Markov's inequality, there
    exists a $C$ such that for all $\mu\in \mc K$,
\begin{equation}
    \mu(\{B\colon 2^n\le \|B\|<2^{n+1}\})\le C/2^{-\gamma n},
\end{equation}
(where $C$ is the $\gamma$-norm).

Let $s\in\N$ and $\mu\in\mc K$ be fixed. Let $\delta>0$ be a constant to be chosen 
later (independently of $s$ and $\mu$). 
If $\|A\|\le 2^s$, we now estimate
\begin{align*}
    &\int \|(A+E)^{-1}\|^\delta\,d\mu(E)\le\circled{1}+\circled{2}+\circled{3}\text{ where}\\
    \circled{1}&=C\int_{\|A+E\|\le 2^{s+1}}\|(A+E)^{-1}\|^{\delta}\,d\text{Leb}(E);\\
    \circled{2}&=\mu\{E\colon s_d(A+E)\ge 1\};\text{ and}\\
    \circled{3}&=\sum_{n=s+1}^\infty\sum_{m=0}^\infty 2^{\delta (m+1)}
    \mu(\{E\colon 2^n\le \|A+E\|<2^{n+1},
    2^{-(m+1)}\le s_d(A+E)<2^{-m}\}),
\end{align*}
the constant $C$ in the first line being the uniform bound on the density. 
Clearly, $\circled{2}\le 1$. For $\circled{1}$, we estimate
$$
\circled{1}\le C\int_{\|E\|\le 2^{s+2}}\|E^{-1}\|^\delta\,d\text{Leb}(E).
$$
For $\delta<1$, this can be seen to be finite using \eqref{eq:Leb_bound}.
For $\circled{3}$, since $\|A\|<2^{n-1}$ for the $n$'s we consider, we observe
\begin{align*}
    &\mu(\{E\colon 2^n\le \|A+E\|<2^{n+1}, 2^{-(m+1)}\le s_d(A+E)<2^{-m}\})\\
    &\le \min\Big(\mu(\{E\colon 2^n\le \|A+E\|<2^{n+1}\}),C\,\text{Leb}(\{E\colon\|A+E\|<2^{n+1},
    s_d(A+E)<2^{-m}\})\Big)\\
    &\le C\min\Big(\mu(\{E\colon 2^{n-1}\le \|E\|\}),
    \text{Leb}(\{E\colon \|E\|<2^{n+2}, s_d(E)<2^{-m}\})\Big)\\
    &\le C\min(2^{-n\gamma},2^{n(d^2-1)-m}),
\end{align*}
where the same constant $C$ works for all $\mu\in\mc K$.
Hence we need to estimate
$$
\sum_{n=s}^\infty\sum_{m=0}^\infty 2^{\delta m}\min(2^{-n\gamma},2^{n(d^2-1)-m}).
$$
Provided $\delta<1$, for fixed $n$, the summands increase geometrically in $m$ with 
common ratio $2^\delta$ up to $m=n(d^2-1+\gamma)$ (at which point the two terms in the minimum agree)
and then decrease  geometrically in $m$ with common ratio 2. 
Accordingly, the sum is bounded above by a constant multiple of 
$$
\sum_{n=s}^\infty 2^{\delta n(d^2-1+\gamma)}2^{-n\gamma}.
$$
Letting $\delta$ be $\frac \gamma 2/(d^2-1+\gamma)$, for example, ensures that the sum is finite. 
Hence we have shown that $\mc K$ has finite translated $\delta$-conorm moment. 
\end{proof}

\subsection{Proof of the Main Theorem. }
We first state our main theorem in a more general form and then state a more 
precise quantitative version of it. 
\begin{thm}\label{thm:main_thm_abstract}
For any dimension $d$ and any $M>0$, the following holds. Suppose that 
$(\mu_n)_{n\in \N}$ is a sequence of distributions on $M_{d\times d}(\R)$ satisfying 
\begin{enumerate}
    \item The collection $\mc K=\{\mu_n\}$ has a uniform $\gamma$-norm moment and uniform translated
    $\gamma$-conorm moment for some $\gamma>0$. 
   \item \label{it:eta_entropy}
    For any matrix $A$ with $\|A\|\le M$, $(G_A)_*\mu_n$ has a uniform fiberwise 
    push-forward entropy (Def.~\ref{defn:uniform_fiberwise_pushforward_entropy}) 
    of at least $\eta$ on the miniflags
    of core dimension $k$ for $0\le k\le d-2$, where $G_A(E)=A+E$.
\end{enumerate}
Then for any sequence of $d\times d$ matrices $(A_n)_{n\in \N}$ such that
$\|A_n\|\le M$ for each $n$, define a random product by
\[
B^{n}\coloneqq (A_n+E_n)(A_{n-1}+E_{n-1})\cdots(A_1+E_1),
\]
where the $(E_i)$ are independent and the distribution of $E_i$ is given by $\mu_i$. 
Then we have
\begin{equation}\label{eqn:expectation_grows_general}
\E\left[\log \sval_k(B^n)-\log \sval_{k+1}(B^n)\right]\ge n\eta-C_d,
\end{equation}
where $C_d$ is as in the statement of Proposition \ref{prop:gapest}; and almost surely
\begin{equation}\label{eqn:almost_sure_est}
\liminf_{n\to \infty} \tfrac 1n\big(\log \sval_k(B^n)-\log \sval_{k+1}(B^n)\big)\ge \eta.
\end{equation}
\end{thm}

\begin{proof}
It suffices to show the estimate \eqref{eqn:expectation_grows_general}; equation  
\eqref{eqn:almost_sure_est} then follows by Proposition 
\ref{prop:growth_in_expectations_implies_almost_sure}, 
whose hypotheses are satisfied due to Lemma \ref{lem:specialization} and the assumption (1) above.

Fix some $0\le k-1\le d-2$. By assumption \eqref{it:eta_entropy},
for all $n$, the distribution of $\nu_n=(G_{A_n})_*\mu_n$
has fiber-averaged push-forward entropy at least
$\eta$ on the miniflags of core dimension $k-1$. Then by Proposition 
\ref{prop:additivity_of_pushforward_entropy}, it follows 
that it follows that the distribution of $B^n$ satisfies that 
\[
\EPIA(\mc F_0,\nu_n*\cdots *\nu_1)\ge n\eta. 
\]
From Proposition \ref{prop:miniflag_distortion_implies_singular_value_gaps}, the estimate 
\eqref{eqn:expectation_grows_general} is now immediate.
\end{proof}

We can now deduce the main consequence of this, which is the theorem stated in the introduction. 


\begin{proof}[Proof of Theorem~\ref{thm:main_thm_simple}.]
We apply Theorem \ref{thm:main_thm_abstract} with $(\mu_n)$ being the constant sequence
$(\mu)$. Recall that $\mu$ is absolutely continuous with continuous density $\phi$
satisfying $\phi(E)\le C/\|E\|^{d^2+1}$. Let $K=\max\phi$.
For $0<\gamma<1$, we estimate the $\gamma$-norm moment of $\mu$ by
\begin{align*}
    \int\|E\|^\gamma\,d\mu(E)&=\int \phi(E)\|E\|^\gamma\,d\text{Leb}(E)\\
    &\le A\int_0^\infty \min(K,C{r^{-(d^2+1)}})r^\gamma r^{d^2-1}\,dr\\
    &\le AK\int_0^1 r^{d^2+\gamma-1}\,dr+AC\int_1^\infty r^{\gamma-2}\,dr<\infty.
\end{align*}
Hence Lemmas \ref{lem:singleton} and \ref{lem:specialization} imply
hypothesis (1) of the theorem is satisfied for the 
family $\mc K=\{\mu\}$.
Hypothesis \eqref{it:eta_entropy} of the theorem (with $\eta=\epsilon^2C_\phi/M^2$) 
is satisfied by
Proposition \ref{prop:fiberwise_entropy_invertible_case}.
\end{proof}


\begin{rem}
It is also possible to take the noise $\mu_{\epsilon}$ to be non-stationary but drawn from 
a family of distributions $\phi$ that is precompact.
\end{rem}

\appendix
\section{Upper bounds}\label{app:upper_bds}

For $L>0$, let $\mc M_L$ be the set of probability measures on $M_{d\times d}(\R)$ with the properties:
\begin{itemize}
    \item $\mu\{E\colon \|E\|\le L\}=1$;
    \item $\int E_{ij}\,d\mu(E)=0$ for all $i,j$.
    \item $\int E_{ij}E_{kl}\,d\mu(E)=\delta_{ik}\delta_{jl}$ for all $1\le i,j,k,l\le d$.
\end{itemize}

\begin{lem}\label{lem:conj}
Let $\SO(d)$ act on $M_{d\times d}(\R)$ by conjugation, denoted by $O(E)=OEO^{-1}$.
Then $O_*(\mc M_L)=\mc M_L$ for each $O\in \SO(d)$. 
\end{lem}

\begin{proof}
    Let $m\in\mc M_L$. For $O\in \SO(d)$, since $\|E\|=\|OEO^{-1}\|$, $O_*\mu$ satisfies the first condition. 
    The measure $O_*\mu$ satisfies the second condition follows by linearity. 
    For the third condition, we have
    \begin{align*}
        \int (OEO^{-1})_{ab}(OEO^{-1})_{cd}\,d\mu(E)&=\sum_{i,j,k,l}O_{ai}O^{-1}_{jb}O_{ck}O^{-1}_{ld}\int E_{ij}E_{kl}\,d\mu(E)\\
        &=\sum_{i,j,k,l}O_{ai}O^{-1}_{jb}O_{ck}O^{-1}_{ld}\delta_{ik}\delta_{jl}\\
        &=\sum_{i,j}O_{ai}O_{ci}O^{-1}_{jb}O^{-1}_{jd}\\
        &=(OO^T)_{ac}(OO^T)_{db}\\
        &=\delta_{ac}\delta_{db},
    \end{align*}
    as required. Hence $O_*\mc M_L\subseteq M_L$. Since $O^{-1}_*\mc M_L\subseteq \mc M_L$ also, it follows that
    $O_*\mc M_L=\mc M_L$ as required.
\end{proof}

\begin{lem}\label{lem:second_order_taylor_expansion}
Let $A>0$ be fixed. Then there exists $\epsilon_0>0$ such that if $Y$, $X_1$, $X_2$ 
are random variables such that $|X_1|\le A$, $|X_2|\le A$ and 
$|Y-(1+\epsilon X_1+\epsilon^2X_2)|\le A\epsilon^3$
almost surely, then for all $0<\epsilon<\epsilon_0$,
\[
\E\,\log Y=\epsilon \mathbb{E}X_1 + \epsilon^2 \big(\E X_2-\tfrac12\E X_1^2\big)+O(\epsilon^3).
\]
\end{lem}

\begin{proof}
We will use the Taylor expansion with remainder. Let $f(x)=\log(1+x)$
and write $Y=1+Z$ with $Z=\epsilon X_1+\epsilon^2X_2+R$, where $|R|\le A\epsilon^3$ a.s. Then
\[
\log Y=Z-\tfrac 12Z^2+\tfrac 16f'''(z)Z^3
\]
where $z$ is between $0$ and $Z$. 
By compactness of the support of the random variables we are considering, 
and truncating the expansions of $Z$ and $Z^2$ at the $\epsilon^2$ terms,
the error term is of size $O_A(\epsilon^3)$, and the stated estimate follows. 
\end{proof}


\begin{lem}\label{lem:Taylor}
    Let $1\le k\le d$ and let $M_{d\times d}$ act on $\bigwedge^k\R^d$ by $A(v_1\wedge\ldots\wedge v_k)
    =Av_1\wedge \ldots \wedge Av_k$. Then for all $\mu\in\mc M_L$, 
    $$
    \int\log\left\|(I+\epsilon E)(e_1\wedge\ldots\wedge e_k)\right\|\,d\mu(E)=\frac{k(d-k-1)\epsilon^2}{2}+O(\epsilon^3)
    $$ 
\end{lem}

\begin{proof}
Let $\mu\in\mc M_L$ and let $\V$ be the random variable 
$(I+\epsilon E)(e_1\wedge\ldots\wedge e_k)$, where $E$
is distributed as $\mu$. That is,
$$
\V=((I+\epsilon E)e_1)\wedge\ldots\wedge ((I+\epsilon E)e_k)
$$
Expanding the right side, we have
\begin{align*}
\V=&(e_1+\epsilon E_{11}e_1+\epsilon E_{21}e_2+\ldots+\epsilon E_{d1}e_d)\\
&\wedge(e_2+\epsilon E_{12}e_1+\epsilon E_{22}e_2+\ldots+\epsilon E_{d2}e_d)\\
&\wedge\quad\vdots\\
&\wedge (e_k+\epsilon E_{1k}e_1+\epsilon E_{2k}e_2+\ldots+\epsilon E_{dk}e_d).
\end{align*}
We need to compute $\E\log\|\V\|=\frac 12\E\log\|\V\|^2$. Recall that, by definition, 
if we write $\V$ as $\sum_{i_1<\ldots<i_k} a_{i_1\cdots i_k} e_{i_1}\wedge \cdots \wedge e_{i_k}$,
then $\|\V\|^2=\sum_{i_1<\ldots<i_k} a_{i_1\cdots i_k}^2$. Thus, in view of Lemma 
\ref{lem:second_order_taylor_expansion}, to compute $\E{\log\|\V\|^2}$ it suffices 
to study the sum $\sum_{i_1<\ldots<i_k} a_{i_1\cdots i_k}^2$ up to an
error of order $O(\epsilon^3)$.

We now examine the cross terms arising from the above expression for $\V$ with this in mind. 
Any term in $a_{i_1\ldots i_k}$ that is a multiple of $\epsilon^3$ or a higher power
may be discarded; similarly if $a_{i_1\ldots i_k}$ has no constant term, then any term
of order $\epsilon^2$ may be discarded since we sum the squares of the coefficients. 
Thus we see that there are two kinds of terms in $\V$ that give a contribution 
of order $\epsilon^2$ or greater to $\|\V\|^2$:
\[
e_1\wedge \cdots \wedge e_k\text{ and } e_1\wedge\ldots\wedge e_{i-1}\wedge 
e_\ell\wedge e_{i+1}\wedge\ldots\wedge e_k \text{ where }\ell>k.
\]
Let us examine these two cases:
\begin{enumerate}
    \item The coefficient of $e_1\wedge \cdots \wedge e_k$ (up to order $\epsilon^2$) is 
    \[
1+\epsilon \sum_{i=1}^kE_{ii}+
\epsilon^2\left(\sum_{i<j}(E_{ii}E_{jj}+(-1)^{j-i}
E_{ji}E_{ij})\right).
    \]
    \item
    Next, each term of the form 
    $e_1\wedge\ldots\wedge e_{i-1}\wedge e_\ell\wedge e_{i+1}\wedge\ldots\wedge e_k$
    up to order $\epsilon$ arises in a unique way: from each term of the wedge product
    expression for $\V$, we select the principal term except that in the $i$th term we select
    the $\epsilon E_{\ell i}e_\ell$ term.
\end{enumerate}

Squaring the coefficients and summing, we observe that $\|\V\|^2=
1+\epsilon X_1+\epsilon^2 X_2+O(\epsilon^3)$, where
\begin{align*}
    X_1&=2\sum_{i=1}^k E_{ii}; \text{\quad and}\\
    X_2&=\left(\sum_{i=1}^k E_{ii}\right)^2+2\sum_{i<j}\Big(E_{ii}E_{jj}+
    (-1)^{j-i}E_{ji}E_{ij}\Big)+\sum_{i=1}^k\sum_{\ell=k+1}^dE_{\ell i}^2.
\end{align*}
We observe from the expectation and covariance properties that $\E X_1=0$, $\E X_1^2=4k$
and $\E X_2=k+0+k(d-k)=k(d+1-k)$.  Applying Lemma \ref{lem:second_order_taylor_expansion}, we obtain
$$
\E\log\|\V\|^2=k(d-1-k)\epsilon^2+O(\epsilon^3).
$$

That gives
$$
\E\log\|\V\|=\tfrac 12\E\log\|\V\|^2=\frac{k(d-k-1)}2\epsilon^2+O(\epsilon^3),
$$
as required.
\end{proof}

\begin{cor}\label{cor:rank_1}
    For any $\mu\in\mc M_L$ and
    any rank 1 element, $v_1\wedge\ldots\wedge v_k$, of $\bigwedge^k\R^d$ of norm 1,
    $$
    \E\log\|(I+\epsilon E)(v_1\wedge\ldots\wedge v_k)\|=\frac{k(d-k-1)\epsilon^2}{2}+O(\epsilon^3).
    $$
\end{cor}

\begin{proof}
    By transitivity of the action of $\SO(d)$ on orthogonal $k$-frames, there
    exists $O\in \SO(d)$ such that $O(e_1\wedge\ldots\wedge e_k)=v_1\wedge\ldots\wedge v_k$. 
    Thus 
    \begin{align*}
    \|(I+\epsilon E)(v_1\wedge \ldots\wedge v_k)\|
    &=\|((I+\epsilon E)O)(e_1\wedge \ldots\wedge e_k)\|\\
    &=\|(O^{-1}(I+\epsilon E)O)(e_1\wedge\ldots\wedge e_k)\|\\
    &=\|(I+\epsilon O^{-1}EO)(e_1\wedge\ldots\wedge e_k)\|.
\end{align*}
    Since $(O^{-1})_*\mu\in\mc M_L$ by Lemma \ref{lem:conj}, the result follows from 
    Lemma \ref{lem:Taylor}.
\end{proof}

\begin{thm}
    Let $(\mu_n)_{n\in\N}$ be an arbitrary sequence of elements of $\mc M_L$ and
    let $(E_n)_{n\in\N}$ be an independent sequence of matrix random variables, with $E_n$ having distribution $\mu_n$. 
    For $\epsilon>0$, let $M_n=(I+\epsilon E_n)\cdots (I+\epsilon E_1)$.
    Then a.s. for each $1\le k\le d$,
    \begin{equation}\label{eqn:growth_rate_k_d-2k}
    \limsup_{n\to\infty} \left|\frac 1n\log\sigma_k(M_n)-\frac {(d-2k)\epsilon^2}{2}\right|=O(\epsilon^3).
    \end{equation}
    In particular, for each $1\le k<d$,
    $$
    \limsup_{n\to\infty} \left|\frac 1n\log\frac{\sigma_k(M_n)}{\sigma_{k+1}(M_n)}-\epsilon^2\right|=O(\epsilon^3).
    $$
\end{thm}

\begin{proof}
To begin, note that here we are studying a stationary matrix product given by a measure 
$\mu$ on $\GL(d,\R)$. 
Thus, in this case Lyapunov exponents exist.
As the Lyapunov exponents are the exponential grow rate of these singular values, 
equation \eqref{eqn:growth_rate_k_d-2k} will follow once we estimate the Lyapunov 
exponents as $n^{-1}\log \sigma_k(M_n)$ converges to $\lambda_k$. Hence it suffices to estimate $\lambda_k$.

Consider a stationary measure $\nu$ for the dynamics on $\Gr(k,d)$. 
Let $\Phi_k(A,V)\colon \GL(d,\R)\times \Gr(k,d)\to \R$ be given by 
\[
\Phi_k(A,v)=\log \frac{\|A(v_1\wedge \cdots \wedge v_k)\|}{\|v_1\wedge \cdots \wedge v_k\|},
\]
where $v_1\wedge \cdots \wedge v_k$ is any wedge representing the subspace $V\in \Gr(k,d)$. 
Then Furstenberg's formula \cite{goldsheid1989lyapunov} gives that there is some 
stationary measure $\nu$ such that:
\[
\lambda_1+\cdots+\lambda_k=\int_{\Gr(k,d)}\int_{\GL(d,\R)} \Phi(A,V)\,d\mu(A)\,d\nu(V).
\]
But note now that by the Corollary \ref{cor:rank_1}, we have already evaluated the 
inner integral for all rank-$1$ tensors, so the result follows by taking the 
difference between $\lambda_1+\cdots+\lambda_{k}$ and $\lambda_1+\cdots+\lambda_{k-1}$.
\end{proof}


