For a group $\Gamma$ and subset $ S$ the Cayley digraph $\dCay(\Gamma,S)$ has vertex set $\Gamma$, where two elements $a, b \in \Gamma$ form an arc $(a,b)$ if $a^{-1}b \in  S$. Note that \emph{antiparallell} arcs, i.e., of the form $(a,b)$ and $(b,a)$, may occur. We say that $D$ is a \emph{minimal Cayley digraph} if there is an inclusion-minimal generating set if sone group $\Gamma$ such that $D\cong \dCay(\Gamma,S)$. Cleary,
\begin{obs}\label{obs:diundi}
    A digraph $D$ is subdigraph of a minimal Cayley digraph if and only if the underlying graph $G$ of $D$ is subgraph of a minimal Cayley graph.
\end{obs}

Denote by $W=(a^{\sigma(1)}_1, \ldots, a^{\sigma(\ell)}_{\ell})$ a walk in $D$, where the sign $\sigma(i)\in \{+1,-1\}$ denotes wether arc $a_i$ is traversed in forward or backward direction respectively. Finally, denote by $\underline{W}$ the subdigraph of $D$ on the set of arcs $\{a_1, \ldots, a_{\ell}\}$.


\begin{defi}\label{def:dilonely}
An arc-coloring $f:A\to S$ of a digraph $D=(V,A)$ is called \emph{faithful no-lonely-color} if \begin{enumerate}
    \item for every $i\in S$ the subdigraph $f^{-1}(i)$ has maximum outdegree and maximum indegree at most $1$
    \item for every cycle $C\subseteq A$ of $D$ and $i\in S$ we have $|C\cap f^{-1}(i)|\neq 1$
    \item for walks $W=(a^{\sigma(1)}_1, \ldots, a^{\sigma(\ell)}_{\ell}), W'=(b^{\tau(1)}_1, \ldots, b^{\tau(\ell)}_{\ell})$ we have $f(a_i)=f(b_i)$ and $\sigma(i)=\tau(i)$ for every $i\in[\ell]$, then $\underline{W}\cong \underline{W'}$.
\end{enumerate}
\end{defi}


\begin{obs}\label{obs:reverse_mono}
Let $f:A\to  S$ be a faithful no-lonely-coloring of $D=(V,A)$ then for any $i\in S$
\begin{enumerate}
    \item  reversing the orientation of $f^{-1}(i)$ yields a digraph $D^i$ for which $f$ also is a faithful no-lonely-coloring.
    \item all cycles in $f^{-1}(i)$ are directed (by Definition~\ref{def:dilonely}.1.) and monchromatic (by Definition~\ref{def:dilonely}.3.).
\end{enumerate}
\end{obs}

\begin{lem}\label{lem:dinolo}
If $D=(V,A)$ is subdigraph of a minimal Cayley digraph $\dCay(\Gamma,S)$, then assigning via $f:A\to S$ to each $a\in A$ the corresponding element of $S$ is a faithful no-lonely-color.
\end{lem}
\begin{proof}
We show the properties one by one:
\noindent 1. For every $i\in S$ the subdigraph $f^{-1}(i)$ consists of the edges corresponding to one element of $c\in S$. Hence, every vertex $g$ can have at most one outneighbor $vc$ and one in-neighbor $vc^{-1}$.

\noindent 2. By Observation~\ref{obs:diundi} the underlying graph of $D$ is subgraph of a minimal Cayley graph. By Babai~\cite{B78} the coloring $f$  satisfies~2.

\noindent 3. Consider for walks $W=(a^{\sigma(1)}_1, \ldots, a^{\sigma(\ell)}_{\ell}), W'=(b^{\tau(1)}_1, \ldots, b^{\tau(\ell)}_{\ell})$ we have $f(a_i)=f(b_i)$ and $\sigma(i)=\tau(i)$ for every $i\in[\ell]$. Now let $g$ and $h$ be the starting vertices of $W$ and $W'$, respectively. It is well-known and easy to see that in $\dCay(\Gamma,S)$ the left-multiplication with $hg^{-1}$ is a digraph automorphism that preserves arc-colors and in particular maps $g$ to $h$, see e.g.~\cite[Chapter 7.3]{KK19}. Since $f(a_i)=f(b_i)$ and $\sigma(i)=\tau(i)$ for every $i\in[\ell]$, this automorphism induces an isomorphism from $\underline{W}$ to $\underline{W'}$.
\end{proof}

It follows directly that
\begin{obs}\label{obs:matching}
Let $D=(V,A)$ be a subgraph of a minimal Cayley digraph $\dCay(\Gamma, S)$ and $f:A\to S$ the faithful no-lonely-color coloring coming from Lemma~\ref{lem:dinolo}. If for some $i\in S$ there is a cycle of length $2$ in $f^{-1}(i)$, then each component of $f^{-1}(i)$ has at most two vertices and augmenting it to a cycle of length $2$, produces a $D'$, such that $D\subseteq D'\subseteq \dCay(\Gamma, S)$ with the correspondingly extended $f$.
\end{obs}


We turn our attention to undirected graphs.%, dropping point 3. in the following definition is usually just refered to as \emph{no-lonely-color coloring}.


\begin{defi}\label{def:lonely}
An edge-coloring $f:E\to S$ of a graph $G=(V,E)$ is called \emph{faithful no-lonely-color} if \begin{enumerate}
    \item for every $i\in S$ the subgraph $f^{-1}(i)$ has maximum degree $2$,
    \item for every cycle $C\subseteq E$ of $G$ and $i\in S$ we have $|C\cap f^{-1}(i)|\neq 1$,
    \item for every $i\in S$ all cycles in the subgraph $f^{-1}(i)$ are of the same length.
\end{enumerate}
\end{defi}

If $G$ is subgraph of a minimal Cayley graph, then by Observation~\ref{obs:diundi} $G$ is the underlying graph of $D$ a subdigraph of a minimal Cayley digraph. Now, we can apply Lemma~\ref{lem:dinolo} to $D$. By Observatiobn~\ref{obs:reverse_mono}.2 we get:%In particular, monochromatic cycles must be directed in $D$ because of the degree restrictions. Hence, by the walk-condition monochromatic cycles of the same color must be of same length. We get:

\begin{lem}
If $G=(V,E)$ is subgraph of a minimal Cayley graph $\Cay(\Gamma,S)$, then assigning via $f:E\to S$ to each $e\in E$ the corresponding element of $S$ yields a faithful no-lonely-color.    
\end{lem} 

A useful reformulation of Definition~\ref{def:lonely}.2 is the following:

\begin{obs}\label{obs:cut}
Let $f:E\to  S$ be an edge-coloring of $G=(V,E)$. Then $f$ satisfies Definition~\ref{def:lonely}.2 if and only if for any $i\in  S$ and $e=\{u,v\}\in f^{-1}(i)$ the vertices $u,v$ lie in different connected components of $G\setminus f^{-1}(i)$.
\end{obs}



\section{An algorithm}
The implementation of the following algorithms, is available in our GitHub repository~\cite{code_repo}.

First, we devise an algorithm that given a graph $G=(V,E)$  produces all faithful no-lonely-color colorings. We extend a partial coloring $f$. We assume the set $C=\{1, \ldots, k\}$ for some $k\in \mathbb{N}$. Initially however we set, $f(e)=0$ for all $e\in E$, which stands for $e$ being uncolored.



