\begin{algorithm}[H]
    \caption{\textsc{extendColoring}: Extends a partial faithful no-lonely-color coloring}
    \label{alg:all_no_lonely_colorings}
    \SetAlgoLined

    \textbf{Input:}\\
    \quad $c$: the color currently being extended.\\
    \quad $f\_valid$: \texttt{True} if $f^{-1}(c)$ satisfies Definition~\ref{def:lonely}, \texttt{False} otherwise.\\

    \BlankLine

    \If{all edges are colored \textbf{and} $f\_valid$}{
        \textbf{Output} current coloring $f$\\
        \Return \texttt{True}
    }

    \BlankLine

    \tcp{Determine candidate edges to color next}
    \uIf{there exists a cycle with a unique uncolored edge $e$}{
        $next\_edges \gets \{e\}$
    }
    \Else{
        \uIf{$f\_valid$}{
            \tcp{Start coloring with a new color $c+1$}
            Choose any uncolored edge $e$\\
            $f(e) \gets c+1$\\
            \If{\textsc{extendColoring}($c+1$, \texttt{False})}{
                \Return \texttt{True}
            }
            \tcp{Try other uncolored edges with current color}
            $next\_edges \gets$ uncolored edges of $G$
        }
        \Else{
            \tcp{Fix a cycle with exactly one edge of color $c$}
            Find a cycle $C$ with a unique edge of color $c$\\
            \uIf{such a cycle $C$ exists}{
                $next\_edges \gets$ uncolored edges of $C$
            }
            \Else{
                $next\_edges \gets$ uncolored edges of $G$
            }
        }
    }

    \BlankLine

    \ForEach{$e \in next\_edges$}{
        $f(e) \gets c$\\

        \If{$\Delta(f^{-1}(c)) \leq 2$ \textbf{and} all cycles in $f^{-1}(c)$ have the same length}{
            \BlankLine
            \tcp{Check Observation~\ref{obs:cut}}
            \If{$u', v'$ are in different components of $G \setminus f^{-1}(c)$ for all $e' \in f^{-1}(c)$}{
                \If{\textsc{extendColoring}($c$, \texttt{True})}{
                    \Return \texttt{True}
                }
            }
            \If{\textsc{extendColoring}($c$, \texttt{False})}{
                \Return \texttt{True}
            }
        }
        \Else{
            $f(e) \gets 0$ \tcp*{Reset edge if invalid}
        }
    }

    \BlankLine

    \Return \texttt{False}
\end{algorithm}

