For the following assume we are given $G=(V,E)$ together with a no-lonely-color coloring $f:E\to  S$. We devise an algorithm to construct an orientation $D$ of $G$ color by color to obtain a candidate orientation. It is based on the following easy observations. For this, we note that if $H$ is connected and \emph{non-trivial}, i.e., with more than one vertex of maximum degree $\leq 2$. Then $H$ has exactly two orientations satisfying Definition~\ref{def:dilonely}.1, denoted by $H^+$ and $H^-$. By Observation~\ref{obs:reverse_mono} in each color, one of these orientations can be arbitrarily fixed. Further, note that by Obervation~\ref{obs:matching}, only if some color $f^{-1}(i)$ is a matching, then its edges can potentially be completely bi-oriented. 
We initialize $D=G$ unoriented and $c=1$.

\begin{algorithm}[H]
\caption{\textsc{extendCandidateOrientation}: Extends candidate orientations of a graph with no-lonely-color $k$-coloring.}
\label{alg:obtainAllPossibleOrientations}
\textbf{Input:} An integer $c$ indicating the next color class to orient.\\

\If{$c = k+1$}{
    \textbf{output} $D$
}
\Else{
    fix an arbitrary non-trivial connected component  $H'$ of $f^{-1}(c)$\\
    \For{$H'\in S \subseteq \{ H \mid H \text{ is a non-trivial connected component of } f^{-1}(c) \}$}{
        Orient each $H \in S$ as $H^+$ in $D$\\
        Orient each $H \notin S$ as $H^-$ in $D$\\
        \textsc{extendCandidateOrientation}$(c+1)$
    }
    \If{$f^{-1}(c)$ is a matching}{
        Bi-orient all edges in $f^{-1}(c)$ in $D$\\
        \textsc{extendCandidateOrientation}$(c+1)$
    }
}
\end{algorithm}


