\section{Proofs}
\label{sec:proofs}
\subsection{Proof of Theorem \ref{thm:alt_null}}
\label{sec:proof_alt_null}
The ``if'' direction is straightforward. If $\mathcal{H}_0$ holds, then 
\begin{align*}
    \mathbb{E}\left( \varepsilon_0 | \phi_j (X) \right) = \mathbb{E}\left( \mathbb{E}(\varepsilon|X) | \phi_j (X) \right) = 0, \quad \forall j \geq 1. 
\end{align*}
Thus, 
$$ 
    \mathbb{E}\left( \varepsilon_0 \phi_j(X) \right) = 0, \quad \forall j \geq 1. 
$$
For the ``only if'' direction, note that 
$$ 
    \mathbb{E}(\varepsilon_0|X) \in L^2(\mathbb{P})
$$
thus, it can be expressed as
$$ 
    \mathbb{E}(\varepsilon_0|X) = \sum_{j=1}^{\infty} \eta_j \phi_j(X).
$$
For any arbitrary $j \geq 1$, we have
\begin{align*}
    \mathbb{E}\left( \varepsilon_0 \phi_j(X) \right) & = \mathbb{E}\left( \mathbb{E}(\varepsilon_0|X) \phi_j(X) \right) \\
    & = \mathbb{E}\left( \sum_{i=1}^{\infty} \eta_i \phi_i(X) \phi_j(X) \right) \\
    & = \mathbb{E}\left( \eta_i \phi_i(X)^2 \right) \\
    & = \eta_i =0.
\end{align*}
Thus,
$$ 
    \mathbb{E}(\varepsilon_0|X) = 0.
$$

\subsection{Proof of Lemma \ref{eigenvalue_rootn}}
\label{sec:proof_eigenvalue_rootn}
Note that for eigenfunctions $\phi_i$ defined by the integral operator $L_k$, we have 
    \begin{align*}
        C \phi_i & = \mathbb{E}\left(k(X,\cdot) \otimes k(X,\cdot)\right) \phi_i \\
        & = \mathbb{E}\left( \langle k(X,\cdot),\phi_i\rangle_{\mathcal{H}_k} k(X,\cdot)\right) \\
        & = \mathbb{E}\left( \phi_i(X) k(X,\cdot)\right) \\
        & = \mathbb{E}\left( \phi_i(X) \sum_{j\geq 1} \mu_j \phi_j(X) \phi_j\right) \\
        & = \sum_{j\geq 1} \mu_j \mathbb{E}\left( \phi_i(X) \phi_j(X)\right) \phi_j\\
        & =  \mu_i \phi_i 
    \end{align*}

    In addition, note that
    \begin{align*}
        C_n & = \frac{1}{n} \boldsymbol{\kappa}^\top  \boldsymbol{\kappa}\\ 
        & = \frac{1}{n}\left(\sum_{i=1}^n \sigma_i \sqrt{\mu_i} \boldsymbol{u}_i \phi_i\right)^\top \otimes \left(\sum_{j=1}^n \sigma_j \sqrt{\mu_j} \boldsymbol{u}_j \phi_j\right)\\
        & = \frac{1}{n} \sum_{i=1}^n \sum_{j=1}^n \sigma_i \sigma_j \sqrt{\mu_i \mu_j} \boldsymbol{u}_i^\top \boldsymbol{u}_j \phi_i \otimes \phi_j\\
        & = \frac{1}{n} \sum_{i=1}^n \sigma_i^2 \mu_i \boldsymbol{u}_i^\top \boldsymbol{u}_i \phi_i \otimes \phi_i \\
        & = \frac{1}{n} \sum_{i=1}^n \sigma_i^2 \mu_i  \phi_i \otimes \phi_i
    \end{align*}
    and 
    \begin{align*}
        C_n \phi_i & = \frac{1}{n} \sum_{j=1}^n \sigma_j^2 \mu_j  \phi_j \langle \phi_j, \phi_i\rangle_{\mathcal{H}_k} \\
        & = \frac{1}{n} \sigma_i^2 \mu_i  \phi_i \frac{1}{\mu_i} \\
        & = \frac{\sigma_i^2}{n} \phi_i
    \end{align*}
    Thus, the eigenfunctions of $L_k$ are also the eigenfunctions of $C$ and $C_n$ in the $L^2(\mathbb{P})$ space. Furthermore, we have 
    \begin{align*}
        & \mu_i = \langle \phi_i, C \phi_i\rangle_{L^2(\mathbb{P})}\\
        &\frac{\sigma_i^2}{n} = \langle \phi_i, C_n \phi_i\rangle_{L^2(\mathbb{P})}
    \end{align*}

    The difference between the empirical and population eigenvalues is bounded by
    \begin{align*}
        \left| \frac{\sigma_i^2}{n} - \mu_i \right| & = \left| \langle \phi_i, (C_n-C) \phi_i\rangle_{L^2(\mathbb{P})}\right|  \\
        & \leq ||\phi_i||^2_{L^2(\mathbb{P})} ||C_n-C||_{HS} \\
        & = ||C_n-C||_{HS} = O_p(1 / \sqrt{n})
    \end{align*}


\subsection{Proof of Lemma \ref{lem:est_dir_signal}}
\label{sec:proof_est_dir_signal}
First, note that 
\begin{align*}
    \boldsymbol{\kappa} \phi_i & = \sum_{j=1}^n \sigma_j \sqrt{\mu_j} \boldsymbol{u}_j \left \langle \phi_j, \phi_i \right \rangle_{\mathcal{H}_k} \\
    & = \sigma_i \frac{1}{\sqrt{\mu_i}} \boldsymbol{u}_i
\end{align*}

Thus, 
\[
    \boldsymbol{u}_i =  \frac{\sqrt{\mu_i}}{\sigma_i} \boldsymbol{\kappa} \phi_i
\]
we have 
\begin{align*}
    \frac{1}{\sqrt{n}} \boldsymbol{\varepsilon_0}^\top \boldsymbol{u}_i   & = \frac{1}{\sqrt{n}} \boldsymbol{\varepsilon_0}^\top \frac{\sqrt{\mu_i}}{\sigma_i} \boldsymbol{\kappa} \phi_i \\
    & = \frac{1}{\sqrt{n}}\frac{\sqrt{\mu_i}}{\sigma_i}  \boldsymbol{\varepsilon_0}^\top \boldsymbol{\kappa} \phi_i  \\
    & = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \frac{1}{n} \boldsymbol{\varepsilon_0}^\top \boldsymbol{\kappa} \phi_i\\
    & = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \frac{1}{n} \sum_{j=1}^n \varepsilon_{0,j} \phi_i(x_j)   
\end{align*}

By Lemma \ref{eigenvalue_rootn} and the continuous mapping theorem, we have
$$ 
    \frac{\sigma_i}{\sqrt{n}} \overset{p}{\longrightarrow} \sqrt{\mu_i} 
$$,
and by the Law of Large Numbers (LLN), we have 
$$ 
    \frac{1}{n} \sum_{j=1}^n \varepsilon_{0,j} \phi_i(x_j)  \overset{p}{\longrightarrow} \mathbb{E}[\varepsilon_0 \phi_i(X)].
$$

Putting these results together, we obtain
$$ 
    \frac{1}{\sqrt{n}} \boldsymbol{\varepsilon_0}^\top \boldsymbol{u}_i  \overset{p}{\longrightarrow} \mathbb{E}[\varepsilon_0 \phi_i(X)].
$$

For the asymptotic normality result, simply apply the classical Central Limit Theorem (CLT):
$$ 
    \frac{1}{\sqrt{n}} \sum_{j=1}^n \left(  \varepsilon_{0,j} \phi_i(x_j) - \mathbb{E}[\varepsilon_0 \phi_i(X)] \right)  \overset{d}{\longrightarrow} \mathcal{N}(0, S_i^2)
$$
with $S_i^2 = \mathrm{Var}(\varepsilon_0 \phi_i(X))$.

To consistently estimate $S_i^2$, note that by the kernel trick, we have 
$$ 
    \boldsymbol{u}_i = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \frac{1}{\sqrt{n}} \begin{pmatrix}
        \phi_i(x_1) \\ \vdots \\ \phi_i(x_n)
    \end{pmatrix} 
$$
and 
\begin{align*}
    \sqrt{n} \boldsymbol{\varepsilon_0} \odot \boldsymbol{u}_i & = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \begin{pmatrix}
        \varepsilon_{0,1} \phi_i(x_1) \\ \vdots \\ \varepsilon_{0,n} \phi_i(x_n)
    \end{pmatrix}
\end{align*}
By Lemma \ref{eigenvalue_rootn}, the LLN and the continuous mapping theorem, we can state that the sample variance of $\{\sqrt{n} \boldsymbol{\varepsilon_0} \odot \boldsymbol{u}_i\}$ converges in probability to $S_i^2$.


\subsection{Proof of Theorem \ref{thm:asymptotic_null_convergence}}
\label{sec:proof_asymptotic_null_convergence}
By the Hoffman--Wielandt inequality in infinite dimensions \cite{bhatia1994hoffman}, we have
$$ 
    \sum_{i=1}^{\infty} \left| \frac{\sigma_i^2}{n^\dagger} - \mu_i \right|  \leq \| C_{n^\dagger} - C\|_{HS}, 
$$
and by Lemma \ref{lem:empirical_second_moment}, we have
$$ 
   \left| \sum_{i=1}^{\infty} \left( \frac{\sigma_i^2}{n^\dagger} - \mu_i \right)  \right| \leq \sum_{i=1}^{\infty} \left| \frac{\sigma_i^2}{n^\dagger} - \mu_i \right| = O_p(1/\sqrt{n^\dagger}) = o_p(1).
$$

Thus, we have 
\begin{align*}
    n^\dagger \hat T_{basic} & = \sum_{i=1}^{J(N)} \boldsymbol{\varepsilon_0^\dagger}^\top \boldsymbol{u^\dagger}_i \frac{(\sigma_i^\dagger)^2}{n^\dagger} (\boldsymbol{u^\dagger}_i)^\top \boldsymbol{\varepsilon_0^\dagger} \\
    & =  \sum_{i=1}^{J(N)} \left( \boldsymbol{\varepsilon_0^\dagger}^\top \boldsymbol{u^\dagger}_i \right)^2 \left( \mu_i + \left( \frac{(\sigma_i^\dagger)^2}{n^\dagger} - \mu_i \right)  \right) \\
    & = \sum_{i=1}^{J(N)} \left( \boldsymbol{\varepsilon_0^\dagger}^\top \boldsymbol{u^\dagger}_i \right)^2 \mu_i + \sum_{i=1}^{J(N)} \left( \boldsymbol{\varepsilon_0^\dagger}^\top \boldsymbol{u^\dagger}_i \right)^2 \left( \frac{(\sigma_i^\dagger)^2}{n^\dagger} - \mu_i \right)  \\
    & \overset{d}{\longrightarrow} \sum_{i=1}^{\infty} S_i^2 W_i^2 \mu_i + \underbrace{O_p(1) \sum_{i=1}^{\infty} \left( \frac{(\sigma_i^\dagger)^2}{n^\dagger} - \mu_i \right)}_{o_p(1)}\\
    &  = \sum_{i=1}^{\infty} S_i^2 W_i^2 \mu_i.
\end{align*}

\subsection{Proof of Theorem \ref{thm:asymptotic_divergent}}
\label{sec:proof_asymptotic_divergent}
Note that by the CLT, the continuous mapping theorem, and Slutsky's theorem, we have
$$ 
    n^\dagger \hat T_{divergent}\overset{d}{\longrightarrow} \frac{\sum_{i=1}^\infty S_i^2 W_i^2 \omega_i - \sum_{i=1}^\infty S_i^2 \omega_i }{\sqrt{2\sum_{i=1}^\infty S_i^4 \omega_i^2}} = V_{\infty}.
$$
By the Berry--Esseen inequality, we have
$$ 
    \sup_{x \in \mathbb{R}} \left| P(V_{\infty} \leq x) - \Phi(x) \right| \leq C \frac{\sum_{i=1}^{\infty} \rho_i}{(\sum_{i=1}^{\infty} 2S_i^4 \omega_i^2)^{3/2}}.
$$
where $\rho_i = \mathbb{E}(|S_i^2 W_i^2 \omega_i|^3)<\infty$. Since
$$ 
    \frac{\sum_{i=1}^{\infty} \rho_i}{(\sum_{i=1}^{\infty} 2S_i^4 \omega_i^2)^{3/2}} = o_p(1),
$$ 
putting everything together, we have
$$ 
    n^\dagger \hat T_{divergent} \overset{d}{\longrightarrow} \mathcal{N}(0,1).
$$


\subsection{Proof of Theorem \ref{thm:power}}
\label{sec:proof_power}
Let $\boldsymbol{\tilde \varepsilon_0} = \boldsymbol{\varepsilon_0} + R(X) / \sqrt{n}$, and note that 
\begin{align*}
    \boldsymbol{\tilde \varepsilon_0}^\top \boldsymbol{u^\dagger}_i & =\boldsymbol{\varepsilon_0}^\top \boldsymbol{u^\dagger}_i + \frac{1}{\sqrt{n}} \boldsymbol{R}^\top \boldsymbol{u^\dagger}_i
\end{align*}
where $\boldsymbol{R} = (R(x_1), \ldots, R(x_n))^\top$.

We have shown that $\boldsymbol{\varepsilon_0}^\top \boldsymbol{u^\dagger}_i \overset{d}{\longrightarrow} S_i W_i$ in Lemma \ref{lem:est_dir_signal}. As for the second term, we have
\begin{align*}
    \frac{1}{\sqrt{n}} \boldsymbol{R}^\top \boldsymbol{u^\dagger}_i & = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \frac{1}{n} \boldsymbol{R}^\top \boldsymbol{\kappa} \phi_i \\
    & = \frac{\sqrt{\mu_i}}{\sigma_i / \sqrt{n}} \frac{1}{n} \sum_{j=1}^n R(x_j) \phi_i(x_j)\\
    & \overset{p}{\longrightarrow} \mathbb{E}[R(X) \phi_i(X)].
\end{align*} 
The rest of the proof would be trivial for $\hat T_{generic}$ and would be the same for $\hat T_{basic}$ with the help of the Hoffman--Wielandt inequality in infinite dimensions \cite{bhatia1994hoffman}.



\subsection{Proof of Theorem \ref{thm:power_divergent}}
\label{sec:proof_power_divergent}
We begin with the harmonic series case. Similar to the proof of Theorem \ref{thm:power}, let $\boldsymbol{\tilde \varepsilon_0} = \boldsymbol{\varepsilon_0} + R(X) / (\log(n^\dagger)\sqrt{n^\dagger})$, and note that
\begin{align*}
    \boldsymbol{\tilde \varepsilon_0}^\top \boldsymbol{u^\dagger}_i & =\boldsymbol{\varepsilon_0}^\top \boldsymbol{u^\dagger}_i + \frac{1}{\log(n^\dagger)} \frac{1}{\sqrt{n^\dagger}} \boldsymbol{R}^\top \boldsymbol{u^\dagger}_i \\
    & = \boldsymbol{\varepsilon_0}^\top \boldsymbol{u^\dagger}_i + \frac{1}{\log(n^\dagger)} \mathbb{E}[R(X) \phi_i(X)] + o_p(1).
\end{align*}
Hence, by the continuous mapping theorem and Slutsky's theorem, we have
\begin{align*}
    n^\dagger \hat T_{divergent} & \overset{d}{\longrightarrow} \lim_{n,n^\dagger \to \infty} \frac{ \sum_{i=1}^{J(N)} \omega_i (S_i W_i+ \mathbb{E}(R(X)\phi_i(X))/\log(n^\dagger))^2-\sum_{i=1}^{J(N)} \omega_i S_i^2   }{\sqrt{2\sum_{i=1}^{J(N)} \omega_i^2 S_i^4}} \\
    & = V_\infty + \lim_{n,n^\dagger \to \infty} \left( \frac{2\sum_{i=1}^{J(N)} \omega_i S_i W_i \mathbb{E}(R(X)\phi_i(X)) }{\log(n^\dagger)\sqrt{2\sum_{i=1}^{J(N)} \omega_i^2 S_i^4}} + \frac{\sum_{i=1}^{J(N)} \omega_i (\mathbb{E}(R(X)\phi_i(X)))^2 }{\log(n^\dagger)^2\sqrt{2\sum_{i=1}^{J(N)} \omega_i^2 S_i^4}} \right).
\end{align*}

Notice that the second term, 
\begin{align*}
    \lim_{n,n^\dagger \to \infty} \frac{2\sum_{i=1}^{J(N)} \omega_i S_i W_i \mathbb{E}(R(X)\phi_i(X)) }{\log(n^\dagger)\sqrt{2\sum_{i=1}^{J(N)} \omega_i^2 S_i^4}}& = O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)}\omega_i}{\log(n^\dagger) \sqrt{\sum_{i=1}^{J(N)} \omega_i^2} }\\
    & \approx O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\log(J(N))}{\log(n^\dagger) } \\
    & = O_p(1) 
\end{align*}
where the approximation holds because $\sum_{i=1}^{J(N)} \omega_i^{2}= \sum_{i=1}^{J(N)} i^{-2}$ converges.

While the third term,
\begin{align*}
    \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)} \omega_i (\mathbb{E}(R(X)\phi_i(X)))^2 }{\log(n^\dagger)^2\sqrt{2\sum_{i=1}^{J(N)} \omega_i^2 S_i^4}} & = O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)}\omega_i}{\log(n^\dagger)^2 \sqrt{\sum_{i=1}^{J(N)} \omega_i^2} } = o_p(1)
\end{align*}

Next, we consider the equal weights case: 
\begin{align*}
    \boldsymbol{\tilde \varepsilon_0}^\top \boldsymbol{u^\dagger}_i  = \boldsymbol{\varepsilon_0}^\top \boldsymbol{u^\dagger}_i + \frac{1}{\sqrt{n^\dagger}} \mathbb{E}[R(X) \phi_i(X)] + o_p(1),
\end{align*}
and similarly, we have 
\begin{align*}
    n^\dagger \hat T_{divergent} & \overset{d}{\longrightarrow} \lim_{n,n^\dagger \to \infty} \frac{ \sum_{i=1}^{J(N)}  (S_i W_i+ \mathbb{E}(R(X)\phi_i(X))/\sqrt{n^\dagger})^2-\sum_{i=1}^{J(N)}  S_i^2   }{\sqrt{2\sum_{i=1}^{J(N)}  S_i^4}} \\
    & = \mathcal{N}(0,1) + \lim_{n,n^\dagger \to \infty} \left( \frac{2\sum_{i=1}^{J(N)}  S_i W_i \mathbb{E}(R(X)\phi_i(X)) }{\sqrt{n^\dagger}\sqrt{2\sum_{i=1}^{J(N)}  S_i^4}} + \frac{\sum_{i=1}^{J(N)}  (\mathbb{E}(R(X)\phi_i(X)))^2 }{n^\dagger\sqrt{2\sum_{i=1}^{J(N)} S_i^4}} \right).
\end{align*}
For the second term, we have
\begin{align*}
    \lim_{n,n^\dagger \to \infty} \frac{2\sum_{i=1}^{J(N)}  S_i W_i \mathbb{E}(R(X)\phi_i(X)) }{\sqrt{n^\dagger}\sqrt{2\sum_{i=1}^{J(N)}  S_i^4}} & = O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)}1}{\sqrt{n^\dagger} \sqrt{\sum_{i=1}^{J(N)} 1} }\\
    & \approx O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\sqrt{J(N)}}{ \sqrt{n^\dagger} } \\
    & = O_p(1). 
\end{align*}
While the third term,
\begin{align*}
    \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)}  (\mathbb{E}(R(X)\phi_i(X)))^2 }{n^\dagger\sqrt{2\sum_{i=1}^{J(N)}  S_i^4}} & = O_p(1) \lim_{n,n^\dagger \to \infty} \frac{\sum_{i=1}^{J(N)}1}{n^\dagger\sqrt{\sum_{i=1}^{J(N)} 1} } = o_p(1)
\end{align*}


\subsection{Proof of Lemma \ref{lem:projection_finite_sample}}
\label{sec:proof_projection_finite_sample}
First, note 
\[
    \frac{1}{\sqrt{n^\dagger}} (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon^\dagger}_{\hat \theta})^\top \boldsymbol{u^\dagger}_i = \frac{\sqrt{\mu_i}}{ \sigma_i / \sqrt{n^\dagger}} \frac{1}{n^\dagger}  (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon^\dagger}_{\hat \theta})^\top \boldsymbol{\phi_i^\dagger}
\]
where $\boldsymbol{\phi_i^\dagger} = (\phi_i(x_1^\dagger),\ldots,\phi_i(x_{n^\dagger}^\dagger))^\top$.

We focus on the term $(1/n^\dagger) (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon^\dagger}_{\hat \theta})^\top \boldsymbol{\phi_i^\dagger}$:
\begin{align*}
    \frac{1}{n^\dagger}  (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon^\dagger}_{\hat \theta})^\top \boldsymbol{\phi_i^\dagger} & = \frac{1}{n^\dagger}  \left(  \hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon_0^\dagger} +   \hat{\boldsymbol{\Pi}} (\nabla_{\theta} \boldsymbol{\varepsilon^\dagger}(\theta)|_{\theta = \bar{\theta}})^\top (\hat \theta-\theta_0)  \right)^\top \boldsymbol{\phi_i^\dagger} \\
    & = \frac{1}{n^\dagger}  \left(  \hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon_0^\dagger} +   \hat{\boldsymbol{\Pi}} (\nabla_{\theta} \boldsymbol{\varepsilon^\dagger}(\theta)|_{\theta = \hat{\theta}})^\top (\hat \theta-\theta_0) + \hat{\boldsymbol{\Pi}} O_p((n^\dagger)^{-2\alpha}) \right)^\top \boldsymbol{\phi_i^\dagger}\\
    & = \frac{1}{n^\dagger} \left( \hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon_0^\dagger} \right)^\top \boldsymbol{\phi_i^\dagger} + O_p((n^\dagger)^{-2\alpha})
\end{align*}
The first equality comes from the mean value theorem, and the last equality is the consequence of the orthogonality between the matrix $\hat{\boldsymbol{\Pi}}$ and the matrix $\nabla_{\theta} \boldsymbol{\varepsilon^\dagger}(\theta)|_{\theta = \hat{\theta}} = \mathbb{G}^\top$.

Thus, we have 
\begin{align*}
    \frac{1}{\sqrt{n^\dagger}} (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon^\dagger}_{\hat \theta})^\top \boldsymbol{u^\dagger}_i &= \frac{\sqrt{\mu_i}}{ \sigma_i / \sqrt{n^\dagger}} \left(  \frac{1}{n^\dagger}  (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon_0^\dagger})^\top \boldsymbol{\phi_i^\dagger} + O_p((n^\dagger)^{-2\alpha})\right) \\
    & = \frac{1}{\sqrt{n^\dagger}} (\hat{\boldsymbol{\Pi}} \boldsymbol{\varepsilon_0^\dagger})^\top \boldsymbol{u^\dagger}_i+ O_p((n^\dagger)^{-2\alpha})
\end{align*}


\subsection{Proof of Theorem \ref{thm:bootstrap}}
\label{sec:proof_bootstrap}
We will prove the consistency of the generic decay weights case; the case with estimated eigenvalues would be identical with the help of the Hoffman--Wielandt inequality in infinite dimensions.

Simply note that 
\begin{align*}
    (\boldsymbol{\varepsilon^\dagger}_{\hat \theta}\odot \boldsymbol{V})^\top(\hat{\boldsymbol{\Pi}} )^\top \boldsymbol{u^\dagger}_i & = \frac{\sqrt{\mu_i}}{\sigma_i^\dagger / \sqrt{n^\dagger}} \frac{1}{\sqrt{n^\dagger}} \sum_{j=1}^{n^\dagger} \left( \left(\varepsilon(z_j^\dagger;\hat \theta) v_j - \hat g_j^\top \left(\mathbb{G}^\top \mathbb{G}\right)^{-1} \mathbb{G}^\top \left(\boldsymbol{\varepsilon^\dagger}_{\hat \theta} \odot \boldsymbol{V}\right) \right) \phi_i(x_j^\dagger) \right)  \\
    & =  \frac{\sqrt{\mu_i}}{\sigma_i^\dagger / \sqrt{n^\dagger}} \frac{1}{\sqrt{n^\dagger}} \sum_{j=1}^{n^\dagger} \left( \left(\varepsilon(z_j^\dagger;\theta_0) v_j - \hat g_j^\top \left(\mathbb{G}^\top \mathbb{G}\right)^{-1} \mathbb{G}^\top \left(\boldsymbol{\varepsilon^\dagger}_{\theta_0} \odot \boldsymbol{V}\right) \right) \phi_i(x_j^\dagger)  \right) +o_p(1)\\
    & = \frac{1}{\sqrt{n^\dagger}} \sum_{j=1}^{n^\dagger} \left( \left(\boldsymbol{\Pi}\varepsilon(z_j^\dagger;\theta_0) v_j  \right) \phi_i(x_j^\dagger)  \right) +o_p(1)
\end{align*}
where the second equality comes from the consistency of $\hat \theta$ to $\theta_0$, the last equality comes the consistencies of the estimator of the projection operator and the eigenvalue. 

Since $\mathbb{E}(V_1)=0$, $\mathrm{Var}(V_1)=1$, and is independent of the data. By the multiplier central limit theorem (see \cite{vaart1997weak}),  we have conditional on $z_1^\dagger,\ldots, z_{n^\dagger}^\dagger$,
$$ 
    \frac{1}{\sqrt{n^\dagger}} \sum_{j=1}^{n^\dagger} \left( \left(\boldsymbol{\Pi}\varepsilon(z_j^\dagger;\theta_0) v_j  \right) \phi_i(x_j^\dagger)  \right) \overset{d^*}{\longrightarrow} S_{i,p} W_i
$$
The rest of the proof is straightforward.


\section{Additional Simulation Results}
\label{sec:additional_simulation_results}

In Section \ref{sec:optimal_kernel}, we outline procedures for optimal kernel selection using a grid search over candidate kernel parameters. A natural question is whether a similar grid search can be applied to the truncation level $J(N)$. However, there are two main challenges that make this approach impractical. 

First, the truncation level $J(N)$ cannot exceed the training sample size $n$, which is often quite limited, especially when sample splitting is used. For instance, in our simulation study with $n=200$ and a training-to-testing split of $0.15:0.85$, the maximum feasible truncation level is only $J(N)=30$, leaving little room for an effective search grid.

Second, and more critically, the reliability of the SNR statistic used for selection depends heavily on the training sample size. Conducting a grid search for $J(N)$ on a small training set may result in selecting a truncation level that is too low to adequately capture the signal. Conversely, increasing the training sample size to improve the search may reduce the size of the testing set, potentially diminishing the overall power of the test. Balancing this trade-off between training and testing sample sizes is a complex issue, and we leave a thorough investigation of this problem to future research.   

To further examine the impact of the truncation level $J(N)$ on test performance, we conduct a simulation study using $n=400$ observations from $DGP_{5}$, considering both $q=10$ and $q=20$ covariate dimensions. We evaluate the empirical power of the test statistics $\hat{T}_{basic}$, $\hat{T}_{basel}$, $\hat{T}_{harmonic}$, and $\hat{T}_{equal}$ across a range of truncation levels $J(N)$. The results are presented in Figures~\ref{fig:power_q10} and~\ref{fig:power_q20}.

These results suggest several key insights: (i) the power of the tests is sensitive to the choice of truncation level $J(N)$, but increasing $J(N)$ does not always lead to higher power; (ii) higher truncation levels tend to be more beneficial when the covariate dimension $q$ is larger; and (iii) test statistics with divergent weights are generally more sensitive to the choice of truncation level than those with convergent weights.

