\title{Modeling ionic flow between small targets: insights from diffusion and electro-diffusion theory}
\author{Fr\'ed\'eric Paquin-Lefebvre$^{1}$ and David Holcman$^{1,\,2}$ \footnote{$^{1}$ Group of Data Modeling and Computational Biology, IBENS, \'Ecole Normale Sup\'erieure, 75005 Paris, France. $^2$ Department of Applied Mathematics and Theoretical Physics, and Churchill College, University of Cambridge, CB3 0DS, United Kingdom.}}
