\subsection{Concentration distribution with multiple absorbing windows}\label{sec:model_absorbing}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
An alternative model to \eqref{eq:model_neumann} consists of diffusing particles that are expelled from the domain through a collection of exit sites each with absorbing boundary conditions (Fig.~\ref{fig:fig1}\textbf{B})). The boundary $\p\Omega$ is now divided into a reflecting part $\p\Omega_r$, a single narrow influx window $\p\Omega_{A_1}$, and $N-1$ narrow absorbing windows $\p\Omega_{A_j}$ for $j=2,\ldots,N$. All the windows $\p\Omega_{A_j}$ are identical disks of radius A. By denoting the union of all exit sites as $\p\Omega_a = \cup_{j=2}^N \p\Omega_{A_j}$, the influx diffusion model \eqref{eq:model_neumann} is as follows
\begin{subequations}\label{eq:model_absorbing}
\begin{align}
D\Delta c(\x) = 0\,, \qquad \x \in \Omega\,,
\end{align}
with boundary conditions
\begin{align}
D\frac{\p c(\x)}{\p\n} = \frac{I}{\FF \pi A^2}\,, \quad \x \in \p\Omega_{A_1}\,, \quad c(\x) = 0\,, \quad \x \in \p\Omega_a\,, \quad  \frac{\p c(\x)}{\p\n} = 0\,, \quad \x \in \p\Omega_r\,.
\end{align}
\end{subequations}
Since $|\p\Omega_{A_j}| \ll |\p\Omega|$, the concentration $c(\x_1)$ at the center of the influx window
\cite{paquin2021} can be computed
\beq\label{eq:cdiff_absorbing}
c(\x_1) = \frac{I}{\FF\pi AD}\left(1 + \frac{\pi}{4(N-1)} - \left(H\left(\x_1\right) + \frac{1}{(N-1)^2}\sum_{i=2}^N H\left(\x_i\right) \right) \frac{A}{4}\log\left(\frac{A}{R}\right) + O\left(\frac{A}{R}\right) \right)\,,
\eeq
where  the mean curvature $H(\x_j)$ is computed at the center $\x_j$ of window $\p\Omega_{A_j}$. The derivation uses the classical Weber's solution \cite{crank1975} to approximate the outward flux at each exit site,
\beq\label{eq:weber}
D\frac{\p c(\x)}{\p \n} = \frac{K_j}{\sqrt{A^2 - \|\x-\x_j\|^2}}\,, \quad \text{for} \quad \|\x-\x_j\| < A \,, \quad j \neq 1\,,
\eeq
where the constant $K_j$ controls the strength of the exit flux through the boundary $\p\Omega_{A_j}$. By integrating \eqref{eq:weber} over each window area $\p\Omega_{A_j}$, we get that the total outflux $\Phi_j$, in units of ${\rm mol}/{\rm s}$, is given by
\beq
\Phi_j = \int_{\p\Omega_{A_j}} D\frac{\p c(\x)}{\p \n} d\x = 2\pi K_j \int_0^A \frac{rdr}{\sqrt{A^2 - r^2}} = 2\pi A K_j\,, \quad j \neq 1.
\eeq
The contribution from all exiting fluxes must compensate the total influx $\Phi_1 = I/\FF$ (compatibility condition) thus linking together the unknown constants $K_j$,
\beq
\sum_{j=2}^N K_j = -\frac{I}{\FF 2\pi A}\,.
\eeq
For a general domain $\Omega$,  this formula involves the mean curvature function $H(\x)$ \cite{paquin2021},
\beq\label{eq:Phi_j}
\Phi_j = - \frac{I}{(N-1)\FF}\left( 1 - \frac{A\log(A/R)}{\pi(N-1)}\sum_{\substack{i=2\\ i\neq j}}^N \left(H(\x_i) - H(\x_j)\right) + O\left(\frac{A}{R}\right) \right)\,, \quad j \neq 1\,.
\eeq
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Explicit solution on a spherical domain}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
For ball domains of radius $R$, since the exact Green's function \eqref{eq:gf_sphere} involves a three-term asymptotic expansion, the concentration has the following expression \cite{paquin2021}
\begin{equation}\label{eq:cdiff_sphere_abs}
\begin{split}
& c(\x_1) = \frac{I}{(N-1)\FF \pi AD}\left(N-1 + \frac{\pi}{4} - \frac{NA}{4R}\log\left(\frac{A}{R}\right) + \left( \frac{N+1}{8} - \frac{\log(2)}{4} \right. \right. \\
& \left. \left. + \frac{1}{N-1}\sum_{i=2}^N\sum_{j=i+1}^N \left( \frac{R}{L_{ij}} - \frac{1}{2}\log\left( \frac{L_{ij}^2}{2R^2} + \frac{L_{ij}}{R} \right) \right) - \sum_{j=2}^N \left( \frac{R}{L_{1j}} - \frac{1}{2}\log\left( \frac{L_{1j}^2}{2R^2} + \frac{L_{1j}}{R} \right) \right)\right)\frac{A}{R} + O\left(\frac{A^2}{R^2}\right)\right)\,,
\end{split}
\end{equation}
revealing the role of the windows geometrical organization on the maximal concentration drop across the domain. For a single exit window, this formula reduces to
\begin{equation}
\begin{split}
c(\x_1) &= \frac{I}{\FF \pi AD}\left(1+\frac{\pi}{4} - \frac{A}{2R}\log\left(\frac{A}{R}\right) \right. \\
& \left. + \left( \frac{3}{8} - \frac{\log(2)}{4} - \frac{R}{L} + \frac{1}{2}\log\left(\frac{L^2}{2R^2} + \frac{L}{R}\right) \right)\frac{A}{R} + O\left(\left(\frac{A}{R}\right)^2\right) \right)\,.
\end{split}
\end{equation}
Next, for the total outflux $\Phi_j$ through each exit window, the second term of the expansion \eqref{eq:Phi_j} vanishes since the mean curvature is constant on spherical domains. An additional term of order $O(A/R)$ yields  the formula below \cite{paquin2021}
\begin{equation}\label{eq:Phi_j_sphere}
\begin{split}
\Phi_j &= - \frac{I}{(N-1)\FF}\left(1 + \left(\sum_{\substack{i=2\\ i\neq j}}^N\left(\frac{R}{L_{1j}} - \frac{R}{L_{1i}} - \frac{R}{L_{ij}} - \frac{1}{2}\log\left( \frac{2R^2L_{1j}^2 + 4R^3L_{1j}}{\left(L_{1i}^2 + 2RL_{1i}\right)\left(L_{ij}^2 + 2RL_{ij}\right)} \right) \right) \right. \right. \\
& \left.\left. + \frac{2}{(N-1)} \sum_{i=2}^N \sum_{k=i+1}^N \left(\frac{R}{L_{ik}} - \frac{1}{2}\log\left( \frac{L_{ik}^2}{2R^2} + \frac{L_{ik}}{R} \right) \right)\right)\frac{2A}{\pi R} + O\left(\left(\frac{A}{R}\right)^2\right)\right)\,, \quad j \neq 1\,.
\end{split}
\end{equation}
Finally, numerical results illustrating how the relative position with respect to the influx window can affect the strength of the exit fluxes are shown in Fig.~\ref{fig:fig4}. In a spherical domain with three narrow windows (Fig.~\ref{fig:fig4}\textbf{A})), for which only the distance $L_{13}$ between the first (receiving the influx) and third windows is allowed to vary, eq.~\eqref{eq:Phi_j_sphere} with $N=3$ is used to compute the flux ratio $\Phi_3/\Phi_2$ between the third and second window,
\beq\label{eq:ratio_flux}
\frac{\Phi_3}{\Phi_2} = \frac{1 - \frac{2A}{\pi R}\left(\frac{R}{L_{12}} - \frac{R}{L_{13}} + \frac{1}{2}\log\left(\frac{L_{13}^2 + 2RL_{13}}{L_{12}^2 + 2RL_{12}}\right)\right) + O\left(\left(\frac{A}{R}\right)^2\right)}{1 + \frac{2A}{\pi R}\left(\frac{R}{L_{12}} - \frac{R}{L_{13}} + \frac{1}{2}\log\left(\frac{L_{13}^2 + 2RL_{13}}{L_{12}^2 + 2RL_{12}}\right)\right) + O\left(\left(\frac{A}{R}\right)^2\right)}.
\eeq
Comparing this against ratios numerically computed with COMSOL \cite{comsol}, we conclude that exit sites located near the influx receiving window contribute more to the escape dynamics than the farther ones (Fig.~\ref{fig:fig4}\textbf{C})).
